INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (42, 'zhTW', '死亡之翼又回來了。他奪下了格瑞姆巴託和大半塊的高地，而且我感覺根本無力阻止他。$B$B但不久之後我們龍後就會抵達，然後我們將一起協力將這位墮落的大地守護者埋回大地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
