INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (401, 'zhTW', '野錘矮人也許可能有快速的馬, 但那些艾瑞峰高峰格瑞夫恩站立的地方不是真正的炎熱嗎? 我認為不是!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 447 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (447, 'zhTW', '試煉谷是任何一個加入部落的成員都應該接受測試的地方。那裡炎熱的太陽考驗這你的耐性！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 518 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (518, 'zhTW', '做自己的老闆感覺真不錯!$B$B可以給我些銅幣讓我買個三明治嗎?我餓壞了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 519 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (519, 'zhTW', '雷德沃克斯主管曾讓我負責新型伐木機的研發計畫，但我上個月自己單飛了。現在，所有的供應商都把我列入了黑名單，更糟的是，我的研發計劃根本都還沒開始。我需要你的幫助，$n!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 520 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (520, 'zhTW', '我想我可以用這個方法開始進行我的研發計劃，呃...就是跟風險投資公司「借」一些他們的科技。看，他們的新型伐木機是最棒的，不管是可拆換的機械臂到控制把手都是!$B$B我的生意夥伴維茲克蘭克到西邊的淤泥沼澤偷...呃...是做些實地勘查，但到現在還沒回來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 521 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (521, 'zhTW', '你殺了鬼嚎。你這個傻瓜!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 522 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (522, 'zhTW', '年輕的$c，靠近一點。我年輕的時候耳朵可好使了，但現在你必須大聲說話我才能聽到。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 523 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (523, 'zhTW', '我在這片平原上生活了很多很多年，我捕獵過許多兇猛的野獸，從來沒有失敗過...直到我遇見了鬼嚎。$B$B很久以前，這隻巨狼曾經是牛頭人的盟友，還和燃燒軍團英勇作戰。不過後來它被一個惡魔所傷，身上的傷口一直沒有治癒。最後...這道傷口把它逼瘋了。$B$B現在它總是痛苦地在平原上游蕩，尋找終止它的痛苦的方法。我很慚愧，因為我無力把他殺掉...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 538 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (538, 'zhTW', '你好啊，法師。我能在魔法知識的學習上為你提供什麼幫助嗎?', '你好啊，法師。我能在魔法知識的學習上為你提供什麼幫助嗎?', '你好啊，法師。我能在魔法知識的學習上為你提供什麼幫助嗎?', '你好啊，法師。我能在魔法知識的學習上為你提供什麼幫助嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 539 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (539, 'zhTW', '很高興見到你，$c。我能給你的建議如下:當你在世間旅行的時候，小心魔法，因為那會傷了未受訓練的人吶。', '很高興見到你，$c。我能給你的建議如下:當你在世間旅行的時候，小心魔法，因為那會傷了未受訓練的人吶。', '幸會, $c.  我給你一個忠告: 當你在大陸上旅行的時候，一定要小心那些會魔法的傢伙，他們的魔法有可能把你燒成灰燼.', '你好。我是一個法師訓練師。而你不是法師!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 558 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (558, 'zhTW', '你好。你是來學習如何掌握魔法精髓的嗎?', '你好。你是來學習如何掌握魔法精髓的嗎?', '真巧.  我是一個法師訓練師，而你剛好就是個法師.', '你好。我是法師訓練師，而你是一個法師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 559 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (559, 'zhTW', '很高興見到你，$c。我能給你的建議如下:當你在世間旅行的時候，小心魔法，因為那會傷了未受訓練的人吶。', '很高興見到你，$c。我能給你的建議如下:當你在世間旅行的時候，小心魔法，因為那會傷了未受訓練的人吶。', '幸會, $c.  我給你一個忠告: 當你在大陸上旅行的時候，一定要小心那些會魔法的傢伙，他們的魔法有可能把你燒成灰燼.', '你好。我是法師訓練師，而你不是一個法師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 560 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (560, 'zhTW', '你好。我是一個地精法師訓練師，而你是一個法師。', '你好。我是一個地精法師訓練師，而你是一個法師。', '真巧.  我是一個侏儒法師訓練師，而你剛好就是個法師.', '你好。我是一個地精法師訓練師，而你是一個法師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 561 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (561, 'zhTW', '很高興見到你，$c。你想要一些忠告嗎?對法師好一點!我們的袖子裡面總可以變一兩個把戲，真的…', '很高興見到你，$c。你想要一些忠告嗎?對法師好一點!我們的袖子裡面總可以變一兩個把戲，真的…', '你好。我是一個地精法師訓練師，而你不是一個法師。', '很高興見到你，$c。你想要一些忠告嗎?對法師好一點!我們的袖子裡面總可以變一兩個把戲，真的…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 562 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (562, 'zhTW', '你好。我是一個不死族法師訓練師，而你是一個法師。', '你好。我是一個不死族法師訓練師，而你是一個法師。', '你好。我是一個亡靈法師訓練師，而你是一個法師。', '你好。我是一個不死族法師訓練師，而你是一個法師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 563 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (563, 'zhTW', '很高興見到你，$c。我能給你的建議如下:當你在世間旅行的時候，小心魔法，因為那會傷了未受訓練的人吶。', '很高興見到你，$c。我能給你的建議如下:當你在世間旅行的時候，小心魔法，因為那會傷了未受訓練的人吶。', '你好，$c。我給你的建議是：當你在世界各地旅行的時候，要當心魔法，它會將不熟悉它的人燒成灰。', '很高興見到你，$c。我能給你的建議如下:當你在世間旅行的時候，小心魔法，因為那會傷了未受訓練的人吶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 564 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (564, 'zhTW', '你好，$c。你是來學習秘藏技藝的嗎?', '你好，$c。你是來學習秘藏技藝的嗎?', '你好, $c.  你是來這裡學習黑暗魔法的嗎？', '你好，$c。你是來學習秘藏技藝的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 565 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (565, 'zhTW', '你好，$c。我很可憐你們這種人，因為魔法真正的秘密對你們來說太高深了...', '你好，$c。我很可憐你們這種人，因為魔法真正的秘密對你們來說太高深了...', '$c， 你這個可憐的傢伙。奧術的力量遠遠超出你的想象...', '很高興見到你，$c。我很可憐你們這種人，你根本不用想了解真正魔法的秘密…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 580 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (580, 'zhTW', '現在還不是讓你長眠的時候。我會幫你起死回生...但你也要為此付出一些代價。', '現在還不是讓你長眠的時候。我會幫你起死回生...但你也要為此付出一些代價。', '現在還不是讓你長眠的時候。我會幫你起死回生……但你也要為此付出一些代價。', '現在還不是讓你長眠的時候。我會幫你起死回生……但你也要為此付出一些代價。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 581 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (581, 'zhTW', '經希瓦娜斯女士批准，亡靈哨兵的數量增加了。我們可以在敵人意想不到的時候以更強大的力量打擊他們。', '經希瓦娜斯女士批准，亡靈哨兵的數量增加了。我們可以在敵人意想不到的時候以更強大的力量打擊他們。', '經瓦里瑪薩斯大人批准，亡靈哨兵的數量增加了。我們將進一步加強打擊敵人的力度。', '經瓦里瑪薩斯大人批准，亡靈哨兵的數量增加了。我們將進一步加強打擊敵人的力度。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 623 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (623, 'zhTW', '你要做什麼，$c?我快要遲到了，我的僱主不會給遲到的人好臉色看的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 624 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (624, 'zhTW', '是的，我是阿斯托·哈德恩。你是?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 638 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (638, 'zhTW', '破碎之手將會帶領部落重返昔日的榮耀。', '破碎之手將會帶領部落重返昔日的榮耀。', '破碎之手氏族將會見證部落的崛起和榮耀，酋長的懦弱不會阻止我們!', '破碎之手氏族將會見證部落的崛起和榮耀，酋長的懦弱不會阻止我們!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 678 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (678, 'zhTW', '看啊，竟然有個年輕的$c來看像我這樣的老農夫?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 698 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (698, 'zhTW', '納拉雷克斯又陷入了沉睡!$B$B很久以前，納拉雷克斯曾滿懷著進入翡翠夢境、讓貧瘠之地重新變成茂密森林的偉大理想而來到了這處洞穴中。但他的執著卻逐漸消退了，而他的思想也被腦海蜿蜒的幻象所侵染。$B$B現在，那些奇怪的爬蟲正從他的夢境中爬到這片土地上來，我們必須把他從夢魘中喚醒過來，否則他就將永遠失落於其中，並繼續給這片大地帶來邪惡的力量!$B$B不過，只有殺死他那些墮落的僕人─毒牙之王，我才能開始進行喚醒儀式。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 699 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (699, 'zhTW', '毒牙之王死了!我們還有希望!$B$B然而，整個喚醒儀式是非常複雜的，我無法獨自完成它。$B$B我現在就開始著手完成所有必要的準備工作，但與此同時，我需要你保護好我。從納拉雷克斯的夢魘中召喚出的怪物確實非常難纏。如果沒有你的幫助，這個任務對我來說會非常可怕。$B$B當你準備好要保護我的時候，就過來跟我說一聲，我會帶你到納拉雷克斯的房間去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 718 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (718, 'zhTW', '機器調整了一下，面對著你。$B$B它的背後是空的，但是有一個奇怪的凹槽，上面寫著:「基爾卡克·旋杆的財產」', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 720 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (720, 'zhTW', '嘿!你在為提爾斯干活嗎?如果我是你的話，我會離他遠遠的!酒精把他的大腦麻痺了，但是他的魔法還是和以前一樣厲害!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 738 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (738, 'zhTW', '當然了，我會告訴你密碼的。只要你不讓提爾斯抓到我就行了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 758 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (758, 'zhTW', '基爾卡克的鑰匙滑到了縫隙中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
