INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (798, 'zhTW', '終於!終於從這破牢房裡逃出來了!$B$B祈倫託將我從達拉然派到這個銀松森林裡來，要我調查阿魯高和他的亡靈僕從們的活動，可我們卻一點也不知道那個巫師已經完全失去了理智。$B$B我必須立刻把這個訊息彙報上去!可在我離開之前，讓我先把庭院門上的魔法鎖給開啟。$B$B既然你能擊敗雷希戈爾，或許也能從前面的層層埋伏中殺出一條血路……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 799 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (799, 'zhTW', '終於!終於有人把我從這破牢房裡給救出來了!$B$B高階執行官哈德瑞克大人派我們來這兒收集這座要塞裡的資訊，以便制定一個能永久消滅剷除阿魯高的計畫。$B$B但那個老不死的巫師還真有點能耐，我們很快就被他的魔法結界給發現了。我被抓來關在這裡，不過文森特可就沒這麼走運了。$B$B我得馬上回去向哈德瑞克大人彙報。首先我會把庭院裡的鎖給你開啟，或許你這麼強悍的$c能從前面的一大堆伏兵裡殺出一條血路……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 818 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (818, 'zhTW', '我以前曾經追尋過暮光之錘的道路。為了找到復活上古諸神的方法，我只身深入這座巢穴，想要找到從那個該死的惡魔阿庫麥爾身上抽取能量的方法。$B$B在看到無數無辜人白白地犧牲之後，我慢慢恢復了理智。$B$B我被困住了一段時間，但是現在我自由了!不幸的是，這裡離我的家鄉卡茲莫丹太遠了!$B$B勇敢的冒險者，我現在可以將你傳送至一個特別的地方，然後回來幹掉阿庫麥爾。如果你願意的話，我現在就送你到達納蘇斯去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 820 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (820, 'zhTW', '歡迎來到我的旅店，疲憊的旅人。我能為你效勞嗎?', '歡迎來到我的旅店，疲憊的旅人。我能為你效勞嗎?', '歡迎來到我的旅店，疲憊的旅行者。我能為您做點什麼嗎?', '歡迎來到我的旅店，疲憊的旅人。我能為你效勞嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
