INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (942, 'zhTW', '我獨自走在路上，為了扞衛榮譽和清除這片大陸上的敵人而戰。$B$B我能為你做什麼，$N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 943 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (943, 'zhTW', '是的，我見過你要找的薩滿。上次我見到她的時候，她正往西邊去。她隱居在鋼鬃部族上方的小山上。如果你夠聰明的話，就可以找到一條通往小屋的山路，就在北邊不遠的地方。那條路可以讓你避開野豬人，直接找到她。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1038 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1038, 'zhTW', '無論索爾是否存在，破碎之手氏族的秩序都將延續下去。', '無論索爾是否存在，破碎之手氏族的秩序都將延續下去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1039 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1039, 'zhTW', '破碎之手氏族的贊杜沙。贊杜沙怎麼可以幫你?他不能!也絕對不會!', '破碎之手氏族的贊杜沙。贊杜沙怎麼可以幫你?他不能!也絕對不會! $B', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1040 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1040, 'zhTW', '你是來接受訓練，還是來浪費一個戰士的時間的?', '你是來接受訓練，還是來浪費一個戰士的時間的?', '你是來接受訓練，還是來浪費一個戰士的時間的?', '你是來接受訓練，還是來浪費一個戰士的時間的?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1041 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1041, 'zhTW', '這臺機器開始運轉了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1058 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1058, 'zhTW', '他給你蜂蜜酒$B$B他給你啤酒$B$B他總是過著快樂的生活$B$B這麼多年他為我們每個人都服務過$B我們叫他微笑的吉姆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1059 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1059, 'zhTW', '這是一種非常奇怪的植物，你從未在泰達希爾的其他地方見過。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1060 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1060, 'zhTW', '這個植物矗立在泰達希爾的普通植物之間，散發著奇異的紫色光芒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1079 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1079, 'zhTW', '你好。我的職責在得到允許的情況下，根據艾澤拉斯的造物者對於土靈的分析，向來訪者提供相關的資訊。我隨時都可以與你分享這些資訊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1080 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1080, 'zhTW', '土靈是造物者設計的綜合產物，並作為艾澤拉斯開始的幾個種族之一。土靈被用於幫助造物者改善這個世界。$B$B他們是造物者在其他世界中設計的標準地下生物的改良形態。在最初的結構得以確定之後，這種原型產生了很多的變化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1081 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1081, 'zhTW', '它是造物者在開創世界的時候建立的最早的一個物種。造物者所建立的每種生物都肩負了一定的使命。對於艾澤拉斯來說，必須改造原有的標準地下生物構造，使其適應地下深處的生活，土靈就是這種改造的產品。$B$B在土靈被創造出來之後，由於巨大的環境壓力，它們出現了許多事先無法預見的變化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1082 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1082, 'zhTW', '在正確回答這個問題之前，需要向你介紹更多關於土靈的背景資料。$B$B資料處理中。$B$B為了理解土靈的變化，首先要了解土靈的設計特徵。創世者的目的是要提高標準地下生物母體的存活性，因此他們把與整個世界相聯絡的彈性構造基礎整合在其中，土靈的出現正是為了達到這一目的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1083 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1083, 'zhTW', '所謂彈性構造基礎就是指用於種族合成的基本材料。造物者在創造土靈的時候放棄了以前創造世界時一直使用的基礎材料，轉而使用這種常見於艾澤拉斯的材料。$B$B透過對世界組成成分的分析，造物者認為可以合成一種加強型的生物，將它作為世界本質的縮影。造物者最終透過混合艾澤拉斯大陸上各種不同的石頭成分，最後組成了這樣一種生物的構造基礎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1084 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1084, 'zhTW', '簡單地說，事實確實如此。$B$B雖然土靈的外表看起來像是一個小型的人型生物，但它們包含了艾澤拉斯大陸上各種石頭的成分。它們在得到了力量和耐力最大化的同時也沒有犧牲敏銳的感覺。它們的皮膚和肌肉的設計使其幾乎完全免疫物理傷害，而且只需進行非常小的改動，土靈就可以展現出驚人的魔法抗性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1085 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1085, 'zhTW', '以上這些內容是用來幫助你理解創世者的動機。他們創造出土靈這樣一個物種是為了在他們離開之後，土靈可以成為這個世界中的一個重要部分，並保障創世者在艾澤拉斯世界的宏大計畫得以繼續執行。$B$B創世者對於「土靈」這個名字十分滿意，因為它很好地體現了這個種族的基本特性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1086 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1086, 'zhTW', '土靈唯一的異常變化是在高壓環境下使用時容易使基質失序。$B$B附錄:原基質的設記是適合地底雕塑，因此從未進行高壓環境複製測試。$B$B這種失序直到土靈首度進入服務迴圈之後才被發現。造物者開始對土靈進行成體改造，而非將之召回並重新設計。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1087 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1087, 'zhTW', '[當你問了這個問題之後，它明顯地停頓了一會兒]$B$B你需要的資訊無法在該資料庫中獲取。對此我表示歉意。$B$B你可以在資料更新之後再次查詢該資訊，或者從艾澤拉斯的其他資訊資料庫處獲得更多資訊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1088 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1088, 'zhTW', '當土靈的合成母體不穩定的時候，產生了兩個變種。一號教程影象正在初始化。$B$B第一類變種被稱為「穴居怪」。這個變種保留了土靈的力量和耐力，但是它的感知力量完全喪失。慾望和狡詐成為了穴居怪的本能。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1089 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1089, 'zhTW', '抱歉，我無法將現有記錄資料按照時間順序進行排序。$B$B雖然穴居怪仍然包含了艾澤拉斯的各種石頭的核心成分，但是它們感知能力的喪失是造物者無法接受的。$B$B穴居怪可以進行單體繁殖。它們會把所有的東西當作食物，包括石頭，甚至是另外一個穴居怪。這樣的同類相殘是造物者極度反感的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1090 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1090, 'zhTW', '二號教程影象正在初始化。$B$B土靈母體的第二個變種和標準的地下生物母體相比較而言，保留了很多必要的元素。這個種族被稱作「矮人」。$B$B這個變種同樣保留了土靈的力量和耐力。在某些方面，矮人甚至超過了土靈母體所具有的感知能力。但是，矮人這個變種的身體結構中已經完全沒有了石質成分的蹤跡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1091 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1091, 'zhTW', '你的問題在資料庫中有相關聯接。$B$B矮人依然和艾澤拉斯的各種石頭有著密切的關係，但是由於土靈在高壓環境下的變異，矮人的結構與標準地下生物母體的結構保持了一致。$B$B因此，正如你所猜想的那樣，矮人確實是從母體中變異出來的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1092 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1092, 'zhTW', '抱歉，我無法將現有記錄資料按照時間順序進行排序。$B$B雖然矮人還是和艾澤拉斯的各種石頭有著某種聯絡，但是他們更多的是向普通的地下物種發展。矮人的生活習性和繁衍方式都和其他的標準生物完全一致。$B$B造物者認為矮人是一種可以接受的變種，可以讓其繼續發展下去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1093 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1093, 'zhTW', '造物者就是...造物者。$B$B他們根據自己的設計來創造和改變這個世界。他們是這個世界出現的原因，他們是艾澤拉斯的創造者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1094 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1094, 'zhTW', '造物者也知道這個資料庫中彙集了大量的資訊。所以，如果你擁有諾甘農圓盤的話，便可以得到一份所有資訊的複製。$B$B請確認你現在沒有關於這方面資訊的問題了。當你找到諾甘農圓盤之後，可以隨時過來製作複製。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1118 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1118, 'zhTW', '那麼說來你想要成為一名鐵匠?紮好圍裙，拿起鐵錘$g小夥子:小姑娘;，讓我們開始吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1119 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1119, 'zhTW', '$N，我已經許久沒有看見過有上好的護甲被鍛造出來了。我以前曾經在大鍛爐的格魯努斯·削鋼那裡接受過訓練。我相信如果你去他那裡的話，肯定可以學到很多東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1120 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1120, 'zhTW', '如果你想要找格魯努斯的話，那麼首先要到鐵爐堡去，然後去城市中心的大鍛爐，在那裡你就可以找到格魯努斯。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1121 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1121, 'zhTW', '$N，你已經擁有了驚人的鍛造技能。我不得不承認你鍛造出的武器已經超過了我的水準。我所認識的水準高過你的鐵匠只有博古斯·鋼手，我相信你可以從他那裡學到不少東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1122 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1122, 'zhTW', '你想要接受博古斯的訓練?當然，我可以告訴你在什麼地方能夠找到他。往西北方向穿過廣場，然後再順著西面的路走，在右手邊的第二座建築物中可以找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1123 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1123, 'zhTW', '難道你看不出我現在很忙嗎?有什麼事?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1124 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1124, 'zhTW', '破碎之手氏族的影響遍佈這一地區。我們已經統治了整個卡林多─法律，政治，軍事，一切的一切。我們無所不知，我們目及一切。$B$B你現在已經成長到能夠為我們效力的時候了，$N。是時候讓你投入戰鬥了。$B$B你做好接受下一個任務的準備了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1127 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1127, 'zhTW', '歡迎來到大鍛爐，$g小夥子:姑娘;。外面雖然非常寒冷，但是這裡確實熱火朝天。拿起錘子開工吧，讓我看看你到底有些什麼能耐!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1128 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1128, 'zhTW', '幹得好，$N，我打賭你做的東西和布魯克的酒一樣正點。你應該去和米洛爾·怒斬談談，他會給你更多指引的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1129 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1129, 'zhTW', '當然，我會告訴你怎麼才能找到米洛爾的。他就在大鍛爐的鐵鑽旁。仔細聆聽他的教導吧，米洛爾絕對是名不虛傳!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1130 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1130, 'zhTW', '$N，你已經得到了我的認可，你是我這些年來帶過的最好的徒弟。如果你想要鑄造一把真正的武器，那麼你一定要去和米洛爾·怒斬談談。那個矮人能夠教你鑄造出一把真真正正的絕世好劍。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1131 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1131, 'zhTW', '你要找米洛爾?他就在那兒，你瞧，就在你身後!呃，好吧，也許在你前面!反正就在大鍛爐附近!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1132 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1132, 'zhTW', '瘟疫襲擊了這座塔。這附近的所有風險投資公司僱員，包括我，都病倒了。$B$B就在上個星期，我們巡邏隊的兩個人死掉了，然後就變成了兩具沒有思想的行屍!$B$B我感到自己的生命力正在慢慢地被抽乾……我已經漸漸喪失對自己的控制力。快讓這樣的痛苦結束吧……求求你了……*費蘇勒開始重重地抽打自己的臉*我還沒有死……聽著……作為風險投資公司的高階成員，我知道很多敏感的資訊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1133 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1133, 'zhTW', '你真的那麼笨嗎?你鍛造出來的是什麼東西?那最多算得上是一把水果刀罷了。我可不會花時間來訓練一個菜鳥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1135 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1135, 'zhTW', '你打擾我就是為了這個?你穿得真是跟垃圾一樣，你還不如背只死兔子到食人妖的洞裡去跑一圈!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1136 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1136, 'zhTW', '$N，這真是你做的嗎?真是一件精美的作品。我會繼續訓練你的，相信總有一天你可以達到皇家鑄甲匠的水準。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1138 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1138, 'zhTW', '大約五個月之前，風險投資公司荊棘谷分公司從藏寶海灣的一個名叫克蘭克·菲茲巴布的神秘商人那裡買了一瓶特別的毒藥。顯然，那是從贊吉爾手中偷來的!$B$B沒錯，我說的就是那個『流亡者』贊吉爾，他因為研究亡靈巫術而被他的部族趕了出去。$B$B那幫荊棘谷分公司的傢伙拿到毒藥之後就開始互相實驗，結果可想而知。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1158 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1158, 'zhTW', '大工頭普茲克·加里維克斯在那件事情發生之後就把剩餘的毒藥帶到了他在淤泥沼澤的塔中繼續進行研究，主要是想要解決毒藥的不穩定性。最後他決定和迪菲亞兄弟會達成協議，共同研製開發這種毒藥，代價是由迪菲亞兄弟會提供批次的成品毒藥。$B$B迪菲亞兄弟會的克拉文·摩特維克負責對贊吉爾的毒藥進行改良。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1159 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1159, 'zhTW', '接下來就是你看到的情況了:毒藥發揮了預期的作用，喝下毒藥的人都變成了被人控制的行屍走人，然而，這種毒藥非常不穩定。$B$B加里維克斯，還有這座塔裡裡外外的人都已經感染了這種毒藥。我們的意志和身體都在不斷被侵襲。我們的器官變得越來越脆弱。$N，我已經無力去拯救這裡的人了，而且我感覺自己馬上要變成他們的一份子了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1160 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1160, 'zhTW', '現在，這座塔的防禦力量正處於最薄弱的時刻。包括加里維克斯在內的所有人都感染了疾病，你的攻擊一定可以對他們造成致命打擊!$B$B我想要看到你血洗那座塔，你要拿到大工頭普茲克·加里維克斯的腦袋，還有最後一瓶毒藥，把這些東西都交給申蘇爾。他會知道接下來該怎麼辦的……我希望如此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1202 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1202, 'zhTW', '我希望你是因為好事才打斷我的，我正在做一些重要的工作。', '我希望你是因為好事才打斷我的，我正在做一些重要的工作。', '我希望你是因為好事才打斷我的，我正在做一些重要的工作。', '我希望你是因為好事才打斷我的，我正在做一些重要的工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1203 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1203, 'zhTW', '關於草藥學，嗯...我認為你現在和我的水準已經差不多了，也許我只能在個別細節上給你一些點撥。', '關於草藥學，嗯...我認為你現在和我的水準已經差不多了，也許我只能在個別細節上給你一些點撥。', '關於草藥學，嗯……我認為你現在和我的水準已經差不多了，也許我只能在個別細節上給你一些點撥。', '關於草藥學，嗯……我認為你現在和我的水準已經差不多了，也許我只能在個別細節上給你一些點撥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1205 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1205, 'zhTW', '啊，一個漁夫。你想要接受訓練嗎?也許我能教你些東西?', '啊，一個漁夫。你想要接受訓練嗎?也許我能教你些東西?', '啊，一個漁夫。你想要接受訓練嗎?也許我能教你些東西?', '啊，一個漁夫。你想要接受訓練嗎?也許我能教你些東西?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1206 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1206, 'zhTW', '歡迎來暴風城。我們可是花了很長時間才將它重建起來的，但是這些工作都很值得。那麼，你是來參觀的還是有任務在身?', '歡迎來暴風城。我們可是花了很長時間才將它重建起來的，但是這些工作都很值得。那麼，你是來參觀的還是有任務在身?', '歡迎來暴風城。我們可是花了很長時間才將它重建起來的，但是這些工作都很值得。那麼，你是來參觀的還是有任務在身?', '歡迎來暴風城。我們可是花了很長時間才將它重建起來的，但是這些工作都很值得。那麼，你是來參觀的還是有任務在身?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1207 AND `Locale` = 'zhTW';
