INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1337, 'zhTW', '我不會因為你想學釣魚而責怪你的。莫高雷有卡林多大陸上最好的釣魚勝地，而在山頂漁具店中，你可以找到釣魚所需的一切裝備。$B$B告訴卡爾·迷霧行者是我讓你去的!', '我不會因為你想學釣魚而責怪你的。莫高雷有卡林多大陸上最好的釣魚勝地，而在山頂漁具店中，你可以找到釣魚所需的一切裝備。$B$B告訴卡爾·迷霧行者是我讓你去的!', '我不會因為你想學釣魚而責怪你的。莫高雷有卡林多大陸上最好的釣魚勝地，而在山頂漁具店中，你可以找到釣魚所需的一切裝備。$B$B告訴卡爾·迷霧行者是我讓你去的!', '我不會因為你想學釣魚而責怪你的。莫高雷有卡林多大陸上最好的釣魚勝地，而在山頂漁具店中，你可以找到釣魚所需的一切裝備。$B$B告訴卡爾·迷霧行者是我讓你去的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
