INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1343, 'zhTW', '莫蘭塔可以教你如何剝皮。你可以在中部高地的卡恩鐵匠鋪旁找到她。', '莫蘭塔可以教你如何剝皮。你可以在中部高地的卡恩鐵匠鋪旁找到她。', '莫蘭塔可以教你如何剝皮。你可以在中部高地的卡恩鐵匠鋪旁找到她。', '莫蘭塔可以教你如何剝皮。你可以在中部高地的卡恩鐵匠鋪旁找到她。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1351 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1351, 'zhTW', '這塊被詛咒的土地上的野獸擁有超自然的能力。$B$B我們的研究表明，在黑暗之門開啟的時候洩漏出了特別的能量，這種能量注入了那些野獸的體內，並把它們變成了現在的樣子。$B$B毫無疑問，這些野獸非常危險，但是我們也認為它們能夠在我們的研究中發揮很大的作用。$B$B$N，也許你有興趣幫助我們研究這些野獸?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1371 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1371, 'zhTW', '我的兄弟德拉吉亞專注於研究詛咒之地上的這些野獸的生理特點，而我則傾向於研究它們的精神特點。$B$B那些野獸確實具有相當驚人的力量、敏捷和耐力，而且還擁有驚人的智力和重生能力，這和它們的外表顯得不太符合。$B$B$r，你是不是有興趣來協助我進行研究呢?', '我的兄弟德拉吉亞專注於研究詛咒之地上的這些野獸的生理特點，而我則傾向於研究它們的精神特點。$B$B那些野獸確實具有相當驚人的力量、敏捷和耐力，而且還擁有驚人的智力和重生能力，這和它們的外表顯得不太符合。$B$B$r，你是不是有興趣來協助我進行研究呢?', '我的兄弟德拉吉亞專注於研究詛咒之地上的這些野獸的生理特點，而我則傾向於研究它們的精神特點。\n\n那些野獸確實具有相當驚人的力量、敏捷和耐力，而且還擁有驚人的智力和重生能力，這和它們的外表顯得不太符合。\n\n$r，你是不是有興趣來協助我進行研究呢?', '我的兄弟德拉吉亞專注於研究詛咒之地上的這些野獸的生理特點，而我則傾向於研究它們的精神特點。$B$B那些野獸確實具有相當驚人的力量、敏捷和耐力，而且還擁有驚人的智力和重生能力，這和它們的外表顯得不太符合。$B$B$r，你是不是有興趣來協助我進行研究呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1391 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1391, 'zhTW', '很難想像如此多的死亡和恐懼會彙集在那麼小的一塊地區中。在這些門後是一塊充斥著混亂和毀滅的大陸。$B$B冒險者，你要非常小心謹慎才行。詛咒之地中到處都是可以讓你喪命的強大生物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1392 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1392, 'zhTW', '作為索爾手下最強大的二十名戰士，我們被稱為索爾近衛軍。$B$B在等待奧格瑪的命令時，我要求在詛咒之地邊境建立一座營地。但是數星期過去了，大酋長那裡還是沒有任何訊息傳來，我們開始變得有些焦躁不安了。$B$B$N，那是個錯誤的決定。我曾經年輕而又雄心勃勃，無所畏懼。這支部隊在我的指揮下開進了詛咒之地。$B$B不久之後我就開始後悔了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1411 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1411, 'zhTW', '後悔。這就是現在我所能感受到的一切。一個錯誤的決定導致瞭如此災難性的後果。我多麼希望當時能多等幾天，直到命令傳來。也許那樣我們就能事先知道這片被詛咒的土地上到底有多少恐怖的東西等著我們!也許這一條命令就能指引我們去另外一個方向!無論怎麼樣，這都是我的錯。所有的一切都是我造成的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1451 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1451, 'zhTW', '你能相信作為精英戰士的我居然失敗了嗎?$B$B我們的部隊被無法抗拒的力量徹底摧毀，我所記得的一切就是不顧一切地逃跑，我所聽到的一切只有我的戰友撕心裂肺的慘叫和我自己的心跳。$B$B過了不久，我又回到了詛咒之地，希望能拯救我的夥伴。但是我被抓住了，最後被活活打死。$B$B這段日子中，我所能感受到的只有恐懼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1452 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1452, 'zhTW', '我被抓之後遭受了非人的虐待，$N。他們輪番拷打我和基利斯中尉，而且在虐待一方的同時讓另外一個在旁邊看著。我們不斷被折磨，直到有一天基利斯告訴把戰友們的遭遇告訴了我，還有他的拯救計畫。$B$B他們所遭受的痛苦比我和基利斯所遭受的還要多，他們真的是生不如死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1453 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1453, 'zhTW', '你和我都無法想像當他們的靈魂被強行從軀體中剝離出來的時候有多麼痛苦。他們沒有死，但是他們也不是活著的。他們成為了一具具行屍，只會聽從主人發號施令。$B$B幹出這些慘絕人寰的事情的就是這裡的惡魔領主拉瑟萊克，他把我的戰友都變成了奴隸。其中的九個被他繫結在黑暗之門附近，其餘的九個則被他的爪牙們瓜分。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1454 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1454, 'zhTW', '影誓大法師奧利斯塔、影誓術士瑟溫妮女士、還有巨槌部落的巨魔『毀滅者』戈洛爾，他們各自分配到了三個。$B$B$N，你要知道，如果沒有靈魂，我的戰友是無法被殺死的。他們現在都處於一種無敵的狀態。幸好的是，他們不能離開禁錮之石太遠的距離。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1455 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1455, 'zhTW', '那些禁錮之石就是你要去摧毀的東西!正如我剛剛所說的，基利斯有一個完整的計畫。$B$B每個被奴役的戰士都有一個弱點，你必須儘量攻擊他們，直到他們的實體形態幾近瓦解。這時禁錮之石就會變得非常脆弱。你一定要抓緊時間摧毀禁錮之石，否則不久之後，那些奴隸又將獲得新的力量，並再次變得刀槍不入了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1456 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1456, 'zhTW', '我想你真的可以幫我，$N，但是單憑你的力量是無法和拉瑟萊克以及他的爪牙抗衡的。$B$B你一定要找到一支足夠強大的隊伍來解救我的戰友，讓他們脫離無盡的痛苦!你總共要摧毀十八塊石頭。$B$B努力地去戰鬥吧，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1471 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1471, 'zhTW', '需要一些鏈金術的材料嗎?或者你有別的什麼事情?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1493 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1493, 'zhTW', '在這片沙漠中生活可是很艱辛!在這種熱度之下我口渴得要命。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1511 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1511, 'zhTW', '救命!$B$B如果你能幫我離開這裡，我就幫你炸開通向祖爾法拉克酋長所在地的那扇門!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1513 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1513, 'zhTW', '我們要殺掉更多的食人妖!殺了足夠的食人妖，我就炸開食人妖酋長的門!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1514 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1514, 'zhTW', '謝謝你，$N。你出現的真是時候，我差一點就死於非命了!現在我們只差打破這扇門就能面對食人妖酋長了...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1515 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1515, 'zhTW', '救命啊!我的隊伍被食人妖俘虜了，他們準備殺了我們!$B$B只要你能救我們出去，我會答應你的任何條件!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1516 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1516, 'zhTW', '沒有時間聊天了!我們必須馬上想辦法對付那些食人妖!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1517 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1517, 'zhTW', '$N，非常感謝你。沒有你，我們絕對沒辦法逃離魔爪。哦，如果我剛才說過要報答你之類的話...忘掉它吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1519 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1519, 'zhTW', '你好!如果你想要接受一些挑戰的話，我這裡有個建議給你!$B$B我正在利用我發明的超級測蛋器幫助夜精靈的德魯伊們拯救鷹角獸。他們受到菲拉斯廢墟中的戈杜尼巨魔影響，數量正在迅速減少。$B$B我收集各種不同型別的蛋。你能幫我找到一些嗎?', '你好!如果你想要接受一些挑戰的話，我這裡有個建議給你!$B$B我正在利用我發明的超級測蛋器幫助夜精靈的德魯伊們拯救鷹角獸。他們受到菲拉斯廢墟中的戈杜尼巨魔影響，數量正在迅速減少。$B$B我收集各種不同型別的蛋。你能幫我找到一些嗎?', '你好!如果你想要接受一些挑戰的話，我這裡有個建議給你!$b$b我正在利用我發明的超級測蛋器幫助夜精靈的德魯伊們拯救鷹角獸。他們受到菲拉斯廢墟中的戈杜尼巨魔影響，數量正在迅速減少。$b$b我收集各種不同型別的蛋。你能幫我找到一些嗎?', '你好!如果你想要接受一些挑戰的話，我這裡有個建議給你!$B$B我正在利用我發明的超級測蛋器幫助夜精靈的德魯伊們拯救鷹角獸。他們受到菲拉斯廢墟中的戈杜尼巨魔影響，數量正在迅速減少。$B$B我收集各種不同型別的蛋。你能幫我找到一些嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1521 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1521, 'zhTW', '這裡西邊有一處叫做菲拉斯的地方，那一帶的角鷹獸是夜精靈長久以來的同伴，他們正處於危險的境地中。$B$B我需要你從菲拉斯南部的伊斯迪爾廢墟中給我帶回角鷹獸的蛋，超級測蛋器會分析你帶回來的蛋，並判斷它是否可以孵化。然後我可以把蛋送給德魯伊們，避免它們受到戈杜尼巨魔的黑暗魔法影響。$B$B請記得一點，$N，有些被拯救的蛋是壞掉的，永遠也不會孵化。', '這裡西邊有一處叫做菲拉斯的地方，那一帶的角鷹獸是夜精靈長久以來的同伴，他們正處於危險的境地中。$B$B我需要你從菲拉斯南部的伊斯迪爾廢墟中給我帶回角鷹獸的蛋，超級測蛋器會分析你帶回來的蛋，並判斷它是否可以孵化。然後我可以把蛋送給德魯伊們，避免它們受到戈杜尼巨魔的黑暗魔法影響。$B$B請記得一點，$N，有些被拯救的蛋是壞掉的，永遠也不會孵化。', '這裡西邊有一處叫做菲拉斯的地方，那一帶的角鷹獸是夜精靈長久以來的同伴，他們正處於危險的境地中。$b$b我需要你從菲拉斯南部的伊斯迪爾廢墟中給我帶回角鷹獸的蛋，超級測蛋器會分析你帶回來的蛋，並判斷它是否可以孵化。然後我可以把蛋送給德魯伊們，避免它們受到戈杜尼巨魔的黑暗魔法影響。$b$b請記得一點，$N，有些被拯救的蛋是壞掉的，永遠也不會孵化。', '這裡西邊有一處叫做菲拉斯的地方，那一帶的角鷹獸是夜精靈長久以來的同伴，他們正處於危險的境地中。$B$B我需要你從菲拉斯南部的伊斯迪爾廢墟中給我帶回角鷹獸的蛋，超級測蛋器會分析你帶回來的蛋，並判斷它是否可以孵化。然後我可以把蛋送給德魯伊們，避免它們受到戈杜尼巨魔的黑暗魔法影響。$B$B請記得一點，$N，有些被拯救的蛋是壞掉的，永遠也不會孵化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1569 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1569, 'zhTW', '歡迎你, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1571 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1571, 'zhTW', '你好，$N!如果你需要的東西在我店裡找不到，那麼我可以專門去幫你找一下!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1597 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1597, 'zhTW', '鐵匠?真少見啊。我能為你做什麼嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1598 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1598, 'zhTW', '如果不住在有大理石天花板的房間裡，我就渾身不舒服。天上的星星讓我覺得很煩燥……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1599 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1599, 'zhTW', '這確實是一件上好的護甲，它給我留下了深刻的印象。我只知道誰可以打造出同樣品質的護甲，他叫格魯努斯·削鋼，就在鐵爐堡的大鍛爐那裡。我相信那位鍛造大師一定可以教你不少東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1600 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1600, 'zhTW', '大鍛爐在鐵爐堡的最中心。他就在那裡和其他的鑄造大師一起工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1605 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1605, 'zhTW', '歡迎你，鐵匠。讓我和你分享一些秘密吧。在這世界上，你不能相信任何人。任何人……你能相信的只有鋼鐵。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1606 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1606, 'zhTW', '你有什麼事?你是來接受訓練的嗎?你是來尋找鋼鐵的秘密的嗎?還是要學習鍛造的技巧?快說!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1609 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1609, 'zhTW', '到奧格瑪的榮譽谷去找她。她和她的丈夫還有兩個孩子都住在那裡。他們都是出色的鐵匠，而她將會是你最好的導師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1610 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1610, 'zhTW', '你已經在鍛造方面有了相當的造詣，可以把鋼鐵變成護身的鎧甲。你的技藝已經超過了我，我必須讓你去更好的鍛造訓練師那裡深造。$N，你應該去奧格瑪找莎伊斯·鋼怒，她是我所知道最好的護甲鍛造師，她應該能教你很多東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1611 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1611, 'zhTW', '所有東西都有靈魂，如果學會聆聽它們的聲音，你就可以隨心所欲地使用它們的力量。鍛造並不是擊打金屬並將其改變成自己想要的形狀那麼簡單，你必須傾聽鋼鐵的聲音，然後指引它，讓它為你所用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1615 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1615, 'zhTW', '你似乎正在尋求知識。也許你在找尋鍛造之道，也許我能在這條道路上指引你。但是一旦你決定從事鐵匠這個職業，你就應該學會聆聽鋼鐵中的那些靈魂的呼喊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1616 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1616, 'zhTW', '到奧格瑪去，你可以在榮譽谷找到她和她的家人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1617 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1617, 'zhTW', '你所鍛造的護甲能夠抵擋最鋒利的刀刃。$N你給我留下了深刻的印象，這可不容易。去找一個名叫莎伊斯·鋼怒的獸人吧，她是除了那些該死的矮人之外最好的鑄甲匠。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1618 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1618, 'zhTW', '你鑄造的武器怎麼樣?你認為它能輕易斬下敵人的頭顱嗎?讓我來告訴你如何把它變得更加鋒利吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1619 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1619, 'zhTW', '想要成為一名鐵匠?想要鍛造出最好的武器?我可以幫你，希望你能對這門手藝投入最大的熱情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1620 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1620, 'zhTW', '到獸人城市奧格瑪去，他就在榮譽谷的「傳說中的裝備」那家店裡。', '到獸人城市奧格瑪去，他就在榮譽谷的「傳說中的裝備」那家店裡。', '到獸人城市奧格瑪去，他就在榮譽谷的「傳說中的裝備」那家店裡。', '到獸人城市奧格瑪去，他就在榮譽谷的“傳說中的裝備”那家店裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
