INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1621, 'zhTW', '$N，你鑄造的武器很不錯，已經達到切金斷玉的水準了。但是我還認識比你的技藝更加精湛的鐵匠，那是一個名叫克爾格魯克·血斧的獸人，去找他繼續學習吧!', '$N，你鑄造的武器很不錯，已經達到切金斷玉的水準了。但是我還認識比你的技藝更加精湛的鐵匠，那是一個名叫克爾格魯克·血斧的獸人，去找他繼續學習吧!', '$N，你鑄造的武器很不錯，已經達到切金斷玉的水準了。但是我還認識比你的技藝更加精湛的鐵匠，那是一個名叫克爾格魯克·血斧的獸人，去找他繼續學習吧!', '$N，你鑄造的武器很不錯，已經達到切金斷玉的水準了。但是我還認識比你的技藝更加精湛的鐵匠，那是一個名叫克爾格魯克·血斧的獸人，去找他繼續學習吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
