INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1638, 'zhTW', '$N，你的旅行怎麼樣?$g蘇米和圖米都很想念你，在你結束訓練之後應該去拜訪他們:我聽說了一些關於你的故事，你似乎一直都很忙;。現在讓我們來看看在你離開的這段時間裡，你都學了些什麼。', '$N，你的旅行怎麼樣?$g蘇米和圖米都很想念你，在你結束訓練之後應該去拜訪他們:我聽說了一些關於你的故事，你似乎一直都很忙;。現在讓我們來看看在你離開的這段時間裡，你都學了些什麼。', '$N，你的旅行怎麼樣?$g蘇米和圖米都很想念你，在你結束訓練之後應該去拜訪他們:我聽說了一些關於你的故事，你似乎一直都很忙;。現在讓我們來看看在你離開的這段時間裡，你都學了些什麼。', '$N，你的旅行怎麼樣?$g蘇米和圖米都很想念你，在你結束訓練之後應該去拜訪他們:我聽說了一些關於你的故事，你似乎一直都很忙;。現在讓我們來看看在你離開的這段時間裡，你都學了些什麼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
