INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1640, 'zhTW', '我不會訓練一點水準都沒有的鐵匠，等你覺得自己達到我的要求之後再回來找我。', '我不會訓練一點水準都沒有的鐵匠，等你覺得自己達到我的要求之後再回來找我。', '我不會訓練一點水準都沒有的鐵匠，等你覺得自己達到我的要求之後再回來找我。', '我不會訓練一點水準都沒有的鐵匠，等你覺得自己達到我的要求之後再回來找我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
