INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1646, 'zhTW', '龐大的戈杜尼巨魔部族控制了菲拉斯森林的很大一塊區域。他們的黑暗魔法已經滲透了周圍的環境，從而直接對那裡的其他生物造成了毀滅性的打擊。$B$B如果你去菲拉斯的話，可得小心那些巨魔─他們非常骯髒，而且很多都會使用強大的黑暗魔法。', '龐大的戈杜尼巨魔部族控制了菲拉斯森林的很大一塊區域。他們的黑暗魔法已經滲透了周圍的環境，從而直接對那裡的其他生物造成了毀滅性的打擊。$B$B如果你去菲拉斯的話，可得小心那些巨魔─他們非常骯髒，而且很多都會使用強大的黑暗魔法。', '龐大的戈杜尼巨魔部落控制了菲拉斯森林的很大一塊區域。他們的黑暗魔法已經滲透了周圍的環境，從而直接對那裡的其它生物造成了毀滅性的打擊。$b$b如果你去菲拉斯的話，可得小心那些巨魔─他們非常骯髒，而且很多都會使用強大的黑暗魔法。', '龐大的戈杜尼巨魔部落控制了菲拉斯森林的很大一塊區域。他們的黑暗魔法已經滲透了周圍的環境，從而直接對那裡的其他生物造成了毀滅性的打擊。$B$B如果你去菲拉斯的話，可得小心那些巨魔─他們非常骯髒，而且很多都會使用強大的黑暗魔法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
