DELETE FROM `npc_text_locale` WHERE `ID` = 1657 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1657, 'zhTW', '資料訪問授權。祝你開心!$B$B01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1673 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1673, 'zhTW', '請等一下，$N。辛達爾在想辦法把精靈龍從恐怖圖騰營地中救出來。我們正巧路過這裡，誰知道那些邪惡的牛頭人對它們做了些什麼。', '請等一下，$N。辛達爾在想辦法把精靈龍從恐怖圖騰營地中救出來。我們正巧路過這裡，誰知道那些邪惡的牛頭人對它們做了些什麼。', '請等一下，$N。辛達爾在想辦法把精靈龍從恐怖圖騰營地中救出來。我們正巧路過這裡，誰知道那些邪惡的牛頭人對它們做了些什麼。', '請等一下，$N。辛達爾在想辦法把精靈龍從恐怖圖騰營地中救出來。我們正巧路過這裡，誰知道那些邪惡的牛頭人對它們做了些什麼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1674 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1674, 'zhTW', '向你致敬。我是這個入口的守衛。除非你的圓盤中包括奧丹姆圓盤，否則我是不會讓你進入奧丹姆的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1675 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1675, 'zhTW', '擁有奧丹姆圓盤才能夠進入奧丹姆。這些圓盤中儲存了造物者在這裡的所有活動的紀錄。$B$B從組成上來看，這些圓盤各不相同。它們的標註則只和奧丹姆資訊相關，與奧達曼圓盤截然不同。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1676 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1676, 'zhTW', '我的職責是為造物者守衛奧丹姆的入口。只有擁有正確的圓盤才能進入其中。$B$B你的圓盤中沒有包含奧丹姆圓盤，所以你不具備進入奧丹姆的基本條件。除非奧丹姆圓盤存在，否則你無法進入。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1677 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1677, 'zhTW', '造物者製造了若干張奧丹姆圓盤以供使用。他們控制著向整個世界分配奧丹姆圓盤的工作。同樣，艾澤拉斯已經被安排了新的探訪計畫，到那時，未來的奧丹姆圓盤也許會重新開始流通。$B$B現有的奧丹姆圓盤已經被全部分給了具有一定忠誠度的種族。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1678 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1678, 'zhTW', '當外部勢力和內部勢力相互衝突，以至於擾亂整個世界的時候，造物者將探訪計畫作為重新控制世界的手段，不過執行這樣的策略並不容易。$B$B關於預先安排的探訪計畫的更多資訊，請查詢所有與造物者相關的資料庫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1679 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1679, 'zhTW', '奧丹姆是一座為維繫艾澤拉斯的自然體系而建造的研究工廠。只有那些擁有奧丹姆圓盤的人知道創世者在奧丹姆所進行的研究工作的詳細情況。$B$B奧丹姆中的資料庫被用於進行特殊的試驗和資料編輯，更多詳細資訊，請查詢資料庫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1693 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1693, 'zhTW', '感謝聖光!現在情況十分緊急，即使有一個雙頭巨魔願意施以援手，我也會欣然接受的。$B$B這座城市裡到處都是穴居怪!為了把它們趕出這裡，我們採取了一些行動，但是卻導致這一地區遭受了大面積的汙染。幸好我們還有希望!$B$B我們疏散到鐵爐堡的科學家正在研究對付輻射疾病的方法。同時，如果你能幫我阻止穴居怪的入侵，那也許我們就能夠奪回我們的城市!', '感謝聖光!現在情況十分緊急，即使有一個雙頭巨魔願意施以援手，我也會欣然接受的。$B$B這座城市裡到處都是穴居怪!為了把它們趕出這裡，我們採取了一些行動，但是卻導致這一地區遭受了大面積的汙染。幸好我們還有希望!$B$B我們疏散到鐵爐堡的科學家正在研究對付輻射疾病的方法。同時，如果你能幫我阻止穴居怪的入侵，那也許我們就能夠奪回我們的城市!', '感謝聖光!現在情況十分緊急，即使有一個雙頭巨魔願意施以援手，我也會欣然接受的。$b$b這座城市裡到處都是石顎怪!為了把它們趕出這裡，我們採取了一些行動，但是卻導致這一地區遭受了大面積的汙染。幸好我們還有希望!$b$b我們疏散到鐵爐堡的科學家正在研究對付輻射疾病的方法。同時，如果你能幫我阻止石顎怪的入侵，那也許我們就能夠奪回我們的城市!', '感謝聖光!現在情況十分緊急，即使有一個雙頭巨魔願意施以援手，我也會欣然接受的。$B$B這座城市裡到處都是石顎怪!為了把它們趕出這裡，我們採取了一些行動，但是卻導致這一地區遭受了大面積的汙染。幸好我們還有希望!$B$B我們疏散到鐵爐堡的科學家正在研究對付輻射疾病的方法。同時，如果你能幫我阻止石顎怪的入侵，那也許我們就能夠奪回我們的城市!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1713 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1713, 'zhTW', '$N，給我幾分鐘時間。這裡剛剛發生了一些事情，我要去確定一切都已經搞定了。我會馬上會來繼續和你談談的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1734 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1734, 'zhTW', '歡迎你，$c。如果你有什麼問題，儘管來問我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
