INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1853, 'zhTW', '當你待在旅店裡的時候，你就可以好好地休息。因此，你可以比留在野外更快地恢復到「充分休息」的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以透過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你繫結的旅店裡了。', '當你待在旅店裡的時候，你就可以好好地休息。因此，你可以比留在野外更快地恢復到「充分休息」的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以透過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你繫結的旅店裡了。', '你能在旅店裡幹什麼?$b$b當你待在旅店裡的時候，你就可以好好地休息。因此,你可以比留在野外更快地恢復到充分休息的狀態，這樣就可以獲得更多的經驗值。$b$b另外你還可以透過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你繫結的旅店裡了。', '你能在旅店裡幹什麼?$B$B當你待在旅店裡的時候，你就可以好好地休息。因此,你可以比留在野外更快地恢復到充分休息的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以透過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你繫結的旅店裡了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1874 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1874, 'zhTW', '你現在進展順利，$N。但是你還有很多東西要學的，南貧瘠之地將是你獲得進一步發展的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1875 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1875, 'zhTW', '雖然我們把這塊土地稱作貧瘠之地，但對於睿智者來說，這裡到處都是生命。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1914 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1914, 'zhTW', '我出售山谷這一邊最好的布料和皮革服飾!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1916 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1916, 'zhTW', '你已經比許多人都走得更遠了，$N。敬畏大自然的力量，你就會取得比大多數人都要偉大的成就。', '你已經比許多人都走得更遠了，$N。敬畏大自然的力量，你就會取得比大多數人都要偉大的成就。', '你已經比許多人都走得更遠了，$N。敬畏大自然的力量，你就會取得比大多數人都要偉大的成就。', '你已經比許多人都走得更遠了，$N。敬畏大自然的力量，你就會取得比大多數人都要偉大的成就。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1918 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1918, 'zhTW', '祭壇似乎在召喚你，好像它具有生命一樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1920 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1920, 'zhTW', '讚美伊露恩!好些年都沒有人來拜訪我了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1921 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1921, 'zhTW', '作為黑海岸的一名年輕的夜精靈，我遇到了一隊暮光之錘的成員。他們待我如同親人，因此我背叛了對伊露恩的信仰，聽信了暮光之錘的蠱惑之言。$B$B直到伊露恩的預兆顯露在我眼前，我才幡然省悟，驚覺自己已經墮落成上古諸神的追隨者。$B$B我滿懷悔恨，開始向伊露恩祈禱。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1922 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1922, 'zhTW', '我的自責、羞愧、懊悔和悲傷全都刻在這塊純金石板上。不幸的是，暮光之錘找到了石板，並認定我是詛咒者。我被立即處死，而那時我對伊露恩的禱告還沒有做完。現在我已經成為了一個遊蕩的幽靈，無法降入扭曲虛空;我被關在籠子裡，用來警告那些試圖背叛暮光之錘的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1923 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1923, 'zhTW', '古老的哈卡祭壇靜靜地矗立在房間的入口處。$B$B你注意到陽臺上有一尊巨大的毒蛇雕像立在那兒。它看起來跟祭壇上的雕像非常相似。它們之間一定有什麼聯絡……', '古老的哈卡祭壇靜靜地矗立在房間的入口處。$B$B你注意到陽臺上有一尊巨大的毒蛇雕像立在那兒。它看起來跟祭壇上的雕像非常相似。它們之間一定有什麼聯絡……', '古老的哈卡祭壇靜靜地矗立在房間的入口處。$b$b你注意到陽臺上有一尊巨大的毒蛇雕像立在那兒。它看起來跟祭壇上的雕像非常相似。它們之間一定有什麼聯絡……', '古老的哈卡祭壇靜靜地矗立在房間的入口處。$B$B你注意到陽臺上有一尊巨大的毒蛇雕像立在那兒。它看起來跟祭壇上的雕像非常相似。它們之間一定有什麼聯絡……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1924 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1924, 'zhTW', '這個地區有許多生物都是夜精靈的同盟。精靈們可以藉助這些生物的能量來為自己效勞。部落也應該擁有這種能力。我想到一個方法，可以捕捉到這種能量併為我們所用。$B$B不要懷疑我告訴你的事情，$N。幫助我，你就會知道我所說的都是實話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1933 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1933, 'zhTW', '如果你是個裁縫，維茲格里克肯定有你想要的東西!隨便看看，$N，想要買什麼東西就和我說!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1934 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1934, 'zhTW', '收拾你的行裝，$N!我從灼熱峽谷那邊的尼莉絲·洛克拉夫收到訊息說，有個被稱作「暗黑拍賣會」的組織正在大熔爐一帶運作。到灼熱峽谷去找到尼莉絲·洛克拉夫，然後把那個暗黑拍賣會一網打盡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1935 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1935, 'zhTW', '房間中出現一道明亮的光束，隨即消失了。然後你注意到了另一道光束……又一道光束。$B$B它們似乎拼接出了某種圖案。', '房間中出現一道明亮的光束，隨即消失了。然後你注意到了另一道光束……又一道光束。$B$B它們似乎拼接出了某種圖案。', '房間中出現一道明亮的光束，隨即消失了。然後你注意到了另一道光束……又一道光束。$b$b它們似乎拼接出了某種圖案。', '房間中出現一道明亮的光束，隨即消失了。然後你注意到了另一道光束……又一道光束。$B$B它們似乎拼接出了某種圖案。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1953 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1953, 'zhTW', '我要復仇。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1954 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1954, 'zhTW', '我父親被大熔爐中的惡棍殺害了。我懇求暴風城給予援助，但是他們根本沒有理睬。不僅如此，他們甚至不願意承認這個地區的存在，更不要說派遣軍隊來匡扶正義了。$B$B我要報仇，$r。這世界上還有比這更強烈的理由嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1955 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1955, 'zhTW', '正如你所見的一樣，我只不過是單槍匹馬。黑鐵矮人和拉格納羅斯的爪牙可以輕鬆把我擺平，但是我對於像你這樣勇敢的冒險者充滿了信心，你一定可以把大熔爐裡的那些東西全部搞定的。如果你願意幫助我，我會給予你豐富的獎勵，那些獎勵將是你做夢也想不到的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1973 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1973, 'zhTW', '我熱烈歡迎你的到來，$r。你遠道而來僅僅是為了找一個住在洞裡的傢伙，我相信你的這次旅程一定是有重要的事情，對嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1994 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1994, 'zhTW', '你好，$G先生:小姐;。我是克希雷姆大人的學徒尼瑞爾。如果你們有任何問題，請隨意向主人詢問。$B$B當你準備下山的時候，就過來找我吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1995 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1995, 'zhTW', '我知道你是誰，$N。由於某種原因，命運將你帶到我面前，而且我對此並不感到高興。在未來的日子裡，你將做出很多抉擇，我希望你擁有足夠的智慧來做出正確的抉擇。$B$B相信我吧，$r，─總有正確的抉擇。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1996 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1996, 'zhTW', '你很好奇，這種好奇掩飾了你在理解能力上的缺乏。我說這些是因為，如果你來此有一個確定的目的，你要提的問題就會顯得毫無意義。$B$B因為這個原因，我只好對你說再見。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1997 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1997, 'zhTW', '你很清楚我知道這些，$r。我們坦率地說吧。$B$B很明顯你來這裡是因為你知道自己拿著什麼樣的東西，你在哈卡的神廟中得到的這件東西使你身負著一件使命來到我面前。這個使命就是讓我的夥伴……我的兄弟，得到安息。他被困在翡翠夢境的夢魘中，他自己無法解脫出來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1998 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1998, 'zhTW', '阿塔萊食人妖所崇拜的神靈曾經受到懲罰。我們毀掉了他的肉身並把神廟沉入水中，但是他比我們預料中的要強大得多。墮落的種子散播開來，腐化了它所接觸的一切。$B$B伊蘭尼庫斯負責看守沉沒的神廟，以確保阿塔萊食人妖或是阿塔萊神靈都不會再死灰復燃。他是個無辜的受害者，我們低估了墮落的力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1999 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1999, 'zhTW', '你來到此地僅僅是第一步……如果你想幫助伊瑟拉的綠龍軍團，這是個正確的選擇。$B$B你到這兒來也許只是受到個人利益的驅使，也許是受到良心的譴責。什麼緣由並不重要，重要的是結果:伊蘭尼庫斯所經受的痛苦令我從夢中驚醒，現在我要終止他的痛苦。我想請你幫助我完成這項任務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2013 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2013, 'zhTW', '有趣，真有趣……我知道有個德魯伊居住在哀嚎洞穴上方的山頂，$N。她也許能告訴你有關這塊裂片的更多資訊。$B$B現在，我必須工作了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2033 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2033, 'zhTW', '我們在艾薩拉度過的這段日子並不是輝煌而又燦爛的，但是我們仍然年輕而且熱血沸騰─我們最終會獲得勝利，這只是一個時間問題。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2034 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2034, 'zhTW', '貝爾戈洛姆派我們從奧格瑪到這裡來幫助他，不過如果他成功了，那樣整個部落就有了希望。$B$B雖然由於他一直以來都喜歡取悅女人，無數的獸人已經因此而喪生，但是他仍然是我們的指揮官，為了榮耀，我們只能盡力去做好。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2035 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2035, 'zhTW', '我不是為了榮耀而來這裡的，$N。我來這裡是為了獸人的驕傲。$B$B如果我沒有拒絕貝爾戈洛姆的提議，那我肯定現在還在奧格瑪料理真正的生意。$B$B他對女人的渴望在杜洛塔的女性戰士中盡人皆知，但是那仍然沒有影響他成為大眾情人。$B$B很幸運他並沒有騷擾我太長時間─否則他會被砍成肉醬的。', '我不是為了榮耀而來這裡的，$N。我來這裡是為了獸人的驕傲。$B$B如果我沒有拒絕貝爾戈洛姆的提議，那我肯定現在還在奧格瑪料理真正的生意。$B$B他對女人的渴望在杜洛塔的女性戰士中盡人皆知，但是那仍然沒有影響他成為大眾情人。$B$B很幸運他並沒有騷擾我太長時間─否則他會被砍成肉醬的。', '我不是為了榮耀而來這裡的，$N。我來這裡是為了獸人的驕傲。$b$b如果我沒有拒絕貝爾戈洛姆的提議，那我肯定現在還在奧格瑞瑪料理真正的生意。$b$b他對女人的渴望在杜洛塔的女性戰士中盡人皆知，但是那仍然沒有影響他成為大眾情人。$b$b很幸運他並沒有騷擾我太長時間——否則他會被砍成肉醬的。', '我不是為了榮耀而來這裡的，$N。我來這裡是為了獸人的驕傲。$B$B如果我沒有拒絕貝爾戈洛姆的提議，那我肯定現在還在奧格瑪料理真正的生意。$B$B他對女人的渴望在杜洛塔的女性戰士中盡人皆知，但是那仍然沒有影響他成為大眾情人。$B$B很幸運他並沒有騷擾我太長時間─否則他會被砍成肉醬的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2036 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2036, 'zhTW', '你好，$N。你是從奧格瑪來幫助我們的吧?很高興見到你。我想盡快離開這片亡靈的森林，回到奧格瑪去喝麥芽酒度日。$B$B不過，我很想知道貝爾戈洛姆是如何說服你來這兒的。', '你好，$N。你是從奧格瑪來幫助我們的吧?很高興見到你。我想盡快離開這片亡靈的森林，回到奧格瑪去喝麥芽酒度日。$B$B不過，我很想知道貝爾戈洛姆是如何說服你來這兒的。', '你好，$N。你是從奧格瑞瑪來幫助我們的吧?很高興見到你。我想盡快離開這片亡靈的森林，回到奧格瑞瑪去喝酒度日。$b$b不過，我很想知道貝爾戈洛姆是如何說服你來這兒的。', '你好，$N。你是從奧格瑪來幫助我們的吧?很高興見到你。我想盡快離開這片亡靈的森林，回到奧格瑪去喝麥芽酒度日。$B$B不過，我很想知道貝爾戈洛姆是如何說服你來這兒的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2037 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2037, 'zhTW', '你找塞納里奧議會有什麼事，$N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2038 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2038, 'zhTW', '我知道，我知道，我知道我根本不知道自己在哪裡!$B$B我的家在棘齒城，不過既然我的飛艇在這兒墜落了，那我不如現在就開始進行我的研究專案了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2039 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2039, 'zhTW', '靈魂還在屍體旁徘徊。它那鬼魅般的眼睛死死地盯著你……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2053 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2053, 'zhTW', '菲拉斯的土地經歷了歲月的洗禮，$r。大地、樹木和生物，它們改變著菲拉斯的現狀和未來。$B$B跟這兒所發生的一切相比，雙塔山可以算是亙古不變的了……', '菲拉斯的土地經歷了歲月的洗禮，$r。大地、樹木和生物，它們改變著菲拉斯的現狀和未來。$B$B跟這兒所發生的一切相比，雙塔山可以算是亙古不變的了……', '菲拉斯的土地經歷了歲月的洗禮，$r。大地、樹木和生物，它們改變著菲拉斯的現狀和未來。$b$b跟這兒所發生的一切相比，雙塔山可以算是亙古不變的了……', '菲拉斯的土地經歷了歲月的洗禮，$r。大地、樹木和生物，它們改變著菲拉斯的現狀和未來。$B$B跟這兒所發生的一切相比，雙塔山可以算是亙古不變的了……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2054 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2054, 'zhTW', '為了讓上來觀光的旅行者安全地下去，我可以為你提供翅膀。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2055 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2055, 'zhTW', '嗯，既然你提及了這一點，不錯，昨天下午我確實看見了奇怪的事情!$B$B當我從東南方的食人妖廢墟處跑過時……好吧，我其實不是跑過去的，應該說是跳過去的……沙地真是太燙了!$B$B總之，當我從廢墟旁跳過的時候，我注意到那兒有一座營帳。我不得不說，在那兒設立營帳是件可笑的事兒……我本來要到那裡去看看的，但是一隻瘋狂的大禿鷹把我趕走了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2113 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2113, 'zhTW', '謝謝你救了我!$B$B我是一名來自暴風城的廚師兼鏈金師。我到這兒來是要幫我叔叔安古斯尋找草藥和食物的，但是這些野豬人將我抓了起來。要不是你趕過來的話，我想我已經被它們煮著吃了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2114 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2114, 'zhTW', '嗯...對，我這裡確實有一些挺有用的食譜。讓我來教你吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2115 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2115, 'zhTW', '不錯，我確實知道一種罕見的鏈金術配方。讓我來教你吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2133 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2133, 'zhTW', '你好!如果你是來學習哥布林工程學結構圖的話，請了解我們只接受合格的哥布林工程師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2134 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2134, 'zhTW', '你好!如果你是來學習地精工程學結構圖的話，我們非常歡迎你。我們的掃瞄器顯示你是一名合格的地精工程師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2135 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2135, 'zhTW', '你好，$g小夥子:姑娘;...我是奧格索普，你擁有的某件地精裝置很可能就是我發明的!如果它爆炸了，那它就不是我發明的;如果它給你帶來了財富，那我們可以討論一下版權金的問題!$B$B哦，對了，如果你來自諾姆瑞根，那你可以走了。我沒有什麼跟你好說的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2136 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2136, 'zhTW', '哦，這不是$N嘛!很高興再見到你，我無法表達我對你的感激之情，你幫我及時完成了發明。$B$B我能為你做什麼事嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2137 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2137, 'zhTW', '我是技工大師歐沃斯巴克，現代地精工程學領域的頂級設計師。我的工作就是用我們的閃亮嶄新的扳手確保新的發明能夠付諸執行!$B$B要是你碰巧懂得製造消除輻射汙染的裝置，那你算是來對地方啦...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2138 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2138, 'zhTW', '寶貝，讓我來教你一個簡單的加法守則:「哥布林」+「工程學」=「萬事通」。告訴你其他演演算法的傢伙肯定數學不及格。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2139 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2139, 'zhTW', '透過研究，我發現在哈卡的化身被擊敗之後，他的力量也會隨之減弱。但是哈卡的大部分力量仍保留在扭曲虛空的深處。$B$B你曾經擊敗過哈卡的化身，$N。或許再次擊敗他的話就可以進一步削弱他的力量，也許有一天我們就將面對他的真身。$B$B我為你準備了一張卷軸，你可以用它在墮神聖地中再次召喚哈卡的化身。你敢再次迎接哈卡的挑戰嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2140 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2140, 'zhTW', '你好，$c。雖然長期飲用烈酒已經讓我的感覺變得遲鈍了，但我的心靈之眼依然十分強大。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2153 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2153, 'zhTW', '你好，$N。我在這裡訓練和照料年輕的角鷹獸，你可以隨意看看。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2154 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2154, 'zhTW', '德魯伊對世界上所有生物的生存狀況都非常敏感。當我們知道這些鳥處於危險之中時，便設立了一套營救系統，防止它們遭受菲拉斯的墮落氣息的影響。$B$B一個名叫克格爾·曲藤的地精負責這項工作，她收集鳥蛋並將其交給我照顧。$B$B我們總是在尋求更多的幫助，$N。或許你該前往加基森找克格爾談話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2155 AND `Locale` = 'zhTW';
