INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2280, 'zhTW', '即使在和平時?仍然會有戰爭，而許多氏族仍在大酋長的領導下奮勇作戰。你是來為奧格瑪而戰的嗎?', '即使在和平時?仍然會有戰爭，而許多氏族仍在大酋長的領導下奮勇作戰。你是來為奧格瑪而戰的嗎?', '即使在和平時期仍然會有戰爭，而許多氏族仍在酋長的領導下奮勇作戰。你是來為奧格瑞瑪而戰的嗎?', '即使在和平時期仍然會有戰爭，而許多氏族仍在酋長的領導下奮勇作戰。你是來為奧格瑪而戰的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
