INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2284, 'zhTW', '大地中蘊藏著許多秘密，$c。保護這些秘密是我們永遠的職責。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2285 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2285, 'zhTW', '如果你是來浪費我的時間，那你就是在浪費整個塞納里奧議會的時間。為你自己著想，希望你不至於那麼蠢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2286 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2286, 'zhTW', '在我們的家園面臨重重危機的情況下……暴風城的官員們竟然將大批軍隊派往別處，我真不敢相信!$B$B來自西部荒野的盜賊與東邊和西邊來的豺狼人蜂擁而至，暴風城沒有受到圍攻可真是個奇蹟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2287 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2287, 'zhTW', '你好，$C。希望你是來支援我們的。野獸和盜賊在艾爾文森林肆意妄為，我們的人手不夠，無法維持治安!$B$B如果你沒有做過這樣的工作，就去看看關於霍格的告示。他是森林中的一隻野獸，我們一定要幹掉他!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2288 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2288, 'zhTW', '你好，$n。歡迎來到塞爾薩瑪，你在這裡的逗留期間別忘了參觀一下本地的釀酒廠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2289 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2289, 'zhTW', '歡迎來到塞爾薩瑪，這兒是你在洛克莫丹的家!$B$B塞爾薩瑪是個好地方，但是對那些相應召喚來到這兒的勇士來說，這裡可不是個吃喝玩樂的地方!如果你想以聯盟的名義挑戰危險的話，就去讀讀貼在探險者協會塞爾薩瑪分部外面的海報吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2293 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2293, 'zhTW', '嘿，$N!這場景不甚美觀，是吧?地平線輕帆號沉在海底，我的手下狼狽不堪，我們的貨物和乘客如同碎片一般到處都是，你也許會認為暴風城曾在這兒舉辦過節日慶典。$B$B麻煩事兒還不止這麼點……', '嘿，$N!這場景不甚美觀，是吧?地平線輕帆號沉在海底，我的手下狼狽不堪，我們的貨物和乘客如同碎片一般到處都是，你也許會認為暴風城曾在這兒舉辦過節日慶典。$B$B麻煩事兒還不止這麼點……', '嘿，$N!這場景不甚美觀，是吧?地平線輕帆號沉在海底，我的手下狼狽不堪，我們的貨物和乘客如同碎片一般到處都是，你也許會認為暴風城曾在這兒舉辦過節日慶典。$b$b麻煩事兒還不止這麼點……', '嘿，$N!這場景不甚美觀，是吧?地平線輕帆號沉在海底，我的手下狼狽不堪，我們的貨物和乘客如同碎片一般到處都是，你也許會認為暴風城曾在這兒舉辦過節日慶典。$B$B麻煩事兒還不止這麼點……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2313 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2313, 'zhTW', '我感覺到處都是陰謀。還有那些對我所做的事情缺乏理解的傢伙，他們想要把我關起來!$B$B你最好不要牽扯進來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2314 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2314, 'zhTW', '什麼?我在幹什麼?你眼睛不好是嗎?我是一個夢想家，親愛的$g先生:女士;，我夢想我們的將來會更加美好。很明顯，我是個夢想家。$B$B然而，有些人卻在想盡辦法把我們困在平庸的泥沼裡。我告訴過他，我是一個夢想家，而大德魯伊鹿盔卻回答說，「哦，我們似乎還缺一些挖水溝的。」$B$B我會幫助塞納里奧議會弄走周圍的泥堆，直到平庸的枷鎖從我們身上卸下的那一天。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2315 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2315, 'zhTW', '你好，$r。我是弗蘭克羅恩·鑄鐵。你是來了解黑石塔和黑鐵矮人的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2316 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2316, 'zhTW', '我沒有選擇，至少我是這麼認為的。我會忍受索瑞森的毀滅並與我的國王和同胞站在一起。$B$B在拉格納羅斯的統治下，達格蘭·索瑞森國王開鑿了山脈的中央，並建立了黑石塔。我們不知疲倦地工作著，發誓要建立一座比以前的任何城市或堡壘都要堅固的矮人城堡...甚至將來也不會有能與之媲美的建築。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2317 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2317, 'zhTW', '我眼睜睜地看著拉格納羅斯的墮落滲透了整個黑鐵矮人社會，使這個曾經榮耀的民族變得瘋狂...變得邪惡。$B$B當黑石塔建造完畢時，我與同胞們共同生存下去的意願也消失殆盡了。我作為新的黑鐵矮人的英雄而死去。這座墳墓就在我親手建造的城門處，作為對我的成就的敬意。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2318 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2318, 'zhTW', '我那柄巨大的戰錘─鐵膽之錘，被交給了新的建築大師弗諾斯·達克維爾。這個傢伙人品低劣，才疏學淺。$B$B這點就是你需要知道的，$N。我想阻止他。他無法將鐵膽之錘的力量發揮到極致，但是如果他的後續者有這個能力的話，他們就會毀掉一切的，而這必將帶來災難性的後果。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2320 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2320, 'zhTW', '沒錯，但是如果你精通草藥學的話，你會發現它非常有用!你要做的是用特別的種子來細心培育藥草─而不是一遇到風吹草動就揮斧亂砍。雖然你即將得到的常青袋能讓最沒有經驗的新手輕鬆進行種植工作，但那些對草藥學有天資的冒險者將會得到更豐碩的成果。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2333 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2333, 'zhTW', '考慮清楚，$g小子:姑娘;─我可沒心情聽你廢話。我在這裡的工作是確認大德魯伊的研究工作正在按計畫進行，而不是跟那些不願為塞納里奧議會效勞的傢伙聊天。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2353 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2353, 'zhTW', '您好，尊貴的$c。我這個塞納里奧議會的謙卑的僕從願祝福與您同在。', '您好，尊貴的$c。我這個塞納里奧議會的謙卑的僕從願祝福與您同在。', '您好，尊貴的$c。我這個塞納里奧議會的謙卑的僕從願祝福與您同在。', '您好，尊貴的$c。我這個塞納里奧議會的謙卑的僕從願祝福與您同在。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2354 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2354, 'zhTW', '小心一點，$c，我有一個為你準備的變形術……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2355 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2355, 'zhTW', '我喜歡餡餅。', '我喜歡餡餅。', '我喜歡餡餅。', '我喜歡餡餅。', '我喜歡餡餅。', '我喜歡餡餅。', '我喜歡餡餅。', '我喜歡餡餅。', '櫻桃餡餅味道是那麼的好，它可以使一個成年侏儒痛哭。', '櫻桃餡餅味道是那麼的好，它可以使一個成年侏儒痛哭。', '嘗一嘗這些櫻桃餡餅，它會讓你臉上的笑容有10英里寬。', '嘗一嘗這些櫻桃餡餅，它會讓你臉上的笑容有10英里寬。', '買新鮮的櫻桃餡餅，它好吃到讓你淚流滿面。', '買新鮮的櫻桃餡餅，它好吃到讓你淚流滿面。', '櫻桃餡餅是全艾澤拉斯我最喜愛的食物。', '櫻桃餡餅是全艾澤拉斯我最喜愛的食物。');
