INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2570, 'zhTW', '呵呵呵呵……你是個相當好奇的傢伙，不是嗎，$n?嗯，我來告訴你該怎麼做。$B$B在此地以北的古老廢墟中居住著一個名叫米布隆·亂齒的令人厭惡的豺狼人。他日夜守護著靈根草，好像從不睡覺似的!$B$B你必須把他引開才行。我可以賣給你一些他喜歡吃的東西─把食物放在他附近，引他過來，然後你就可以趁機拿走靈根草啦。祝你好運!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
