INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2639, 'zhTW', '你好，$c。如果你在尋找皮製品和制皮物資的話，來問我這個半退休的聖騎士就算是找對人了。', NULL, '你好，$c。如果你在尋找皮製品和制皮物資的話，來問我這個半退休的聖騎士就算是找對人了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
