INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2673, 'zhTW', 'I am a mage of great power, I have spent my days studying the mind and the memory as it pertains to learning and the retention of learned abilities. I would even now be perfecting my studies if not for the great voices that came to me in the night, informing me that my services were required. I will be here for only a short time offering my ability to wipe your talents for free. Soon I will leave again, and you will once more be stuck with whatever choices you make.', '我是一名擁有強大力量的法師，一直以來，我都潛心研究精神和記憶，這有利於學習知識和保持學會的知識。要不是我在夜晚聽到一個巨大的聲音說需要我的幫助，我的研究一定已經完成啦。我只在這兒待一會兒，免費為你重修天賦。接著我就得離開，而你也要選擇自己的道路。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2676 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2676, 'zhTW', '你好，$n。如果你想學習烹飪技巧的話，可以隨時來找我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2693 AND `Locale` = 'zhTW';
