INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2695, 'zhTW', '你是說為了滿足一個妄想狂的地方官和一群沒準正在遭受中暑之苦的烏合之眾的願望，我們就得把世界各地的部隊都調回來，然後給他派過去嗎?', '你是說為了滿足一個妄想狂的地方官和一群沒準正在遭受中暑之苦的烏合之眾的願望，我們就得把世界各地的部隊都調回來，然後給他派過去嗎?', '你是說為了滿足一個妄想狂的地方官和一群沒準正在遭受中暑之苦的烏合之眾的願望，我們就得把世界各地的部隊都調回來，然後給他派過去嗎？', '你是說為了滿足一個妄想狂的地方官和一群沒準正在遭受中暑之苦的烏合之眾的願望，我們就得把世界各地的部隊都調回來，然後給他派過去嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
