INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2713, 'zhTW', '你想要什麼?*嗝兒*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2714 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2714, 'zhTW', '溫德索爾那天特別愛跟人爭吵─相信我，對溫德索爾來說，那是一個有紀念意義的偉大成就。他一直在跟我說「感覺有些怪異」。他不是在開玩笑!$B$B當那些骯髒的野獸出擊時，我們還在黑石山脈的中央。當然，我指的是獸人。你別分神，好嗎?一時之間，叫喊聲和鐵器的敲擊聲四起。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2715 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2715, 'zhTW', '我單挑50個獸人?我可不是傻子，$N。我爸爸常說「卑鄙是卑鄙者的通行證」這類的話，我突然之間就明白了那是什麼意思。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2716 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2716, 'zhTW', '好吧，好吧。總之，從某種意義上說，我退到了一個不起眼的角落裡。$B$B溫德索爾似乎並不安分，看看他那歇斯底里的樣兒。他拿著反對者戰錘沒命地亂揮，像發了瘋一樣對獸人咆哮著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2717 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2717, 'zhTW', '嗯。你從來沒有聽說過反對者?那把傳說中的令獸人聞風喪膽的戰錘?對，對，那是溫德索爾的錘子。他說是弗蘭克羅恩·鑄鐵親自為他偉大的父親製造了那把錘。弗蘭克羅恩·鑄鐵，就是那個建造了巨石水壩之類的……黑鐵矮人。他還說有一把與反對者一起鑄造出來的戰錘被弗蘭克羅恩自己留著用了。他好像叫它鐵膽之錘什麼的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2718 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2718, 'zhTW', '我說到哪裡了?哦，沒錯，獸人突襲了溫德索爾，這個溫德索爾呢，他動也不動。獸人朝他衝過去，大約有十來個。他卻昂然而立。只見反對者的光芒萬丈，和四濺的鮮血。戰鬥持續了數個小時，還是好幾天，我記不得。總之，最後，戰鬥停止了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2719 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2719, 'zhTW', '死了?你在開玩笑吧，$N?搞清楚，$n$g先生:小姐;$N!溫德索爾絕對不會死於區區50個獸人之手，這就跟塞爾薩瑪血腸是世界上最美味的食物一樣不容置疑，他被獸人層層包圍，但是他確實還活著……而且他非常非常憤怒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2720 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2720, 'zhTW', '你為什麼總說他死了?誰告訴你他死了?我從來都沒那麼說過。$B$B他只是不知去向而已。$B$B你看，很明顯，我們已經卷入了某個獸人對抗黑鐵矮人的戰爭中。獸人是一群骯髒又卑劣的雜種，他們設計了一些圈套和你可能永遠搞不明白的邪惡裝置!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2721 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2721, 'zhTW', '矮人可不會喝醉，$g先生:小姐;。我只是有些邋遢。$B$B無論如何，溫德索爾?我猜他在黑石深淵的某處。對你們這些未受教化的傢伙來說，就是一座黑鐵矮人的城市。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2722 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2722, 'zhTW', '放慢速度!就快接近了!$B$B他在那兒，全身血肉模糊，連內臟都流出來了，是誰把他弄成這樣的?$B$B黑鐵矮人!你記得我說過的話嗎??$B$B嗯，黑鐵矮人比黑石獸人更為狡猾。他們是有備而來的。人數有300之多……*嗝爾*。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2723 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2723, 'zhTW', '$N$g先生:女士;，如果我不是很瞭解你的話，我就會以為你也是那些穴居怪中的一員。$B$B黑鐵矮人沒有把溫德索爾怎麼樣，畢竟他的老祖父的最好最好的朋友就是一個黑鐵矮人，這可能也就是黑鐵軍隊到現在還沒把他幹掉的原因。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2724 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2724, 'zhTW', '你的知識太缺乏了。當你熔鍊技術更成熟些時再來找我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2725 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2725, 'zhTW', '最後!用手指堵住你的耳朵，你的腦子有可能會變得有五倍大，事實上，我甚至擔心你的腦子會洩出來。$B$B那麼，黑鐵矮人們饒了他的性命，但把他囚禁了起來。他們的首領，某個叫做索什麼森的妄自尊大的，愚蠢的，自負的傢伙，把反對者留作己用。那是我最後一次見到溫德索爾了……*嗝兒*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2726 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2726, 'zhTW', '費伍德森林的墮落禁錮了我的靈魂……我也許永遠都得不到安寧……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2727 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2727, 'zhTW', '歡迎來到我們的酒店!', '歡迎來到我們的酒店!', '歡迎來到我們的酒店!', '歡迎來到我們的酒店!', NULL, '歡迎來到我們的酒店!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
