INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2761, 'zhTW', '你有需要保管的財寶嗎?去找鐵爐堡銀行的石衣兄弟吧。$B$B從鐵爐堡的入口往東北方向走，銀行就在那邊。', '你有需要保管的財寶嗎?去找鐵爐堡銀行的石衣兄弟吧。$B$B從鐵爐堡的入口往東北方向走，銀行就在那邊。', '你有需要保管的財寶嗎?去找鐵爐堡銀行的石衣兄弟吧。$B$B從鐵爐堡的入口往東北方向走，銀行就在那邊。', '你有需要保管的財寶嗎?去找鐵爐堡銀行的石衣兄弟吧。$B$B從鐵爐堡的入口往東北方向走，銀行就在那邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
