INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2762, 'zhTW', '想要乘坐獅鷲獸，是嗎?你得去找格萊斯·瑟登。$B$B你可以在鐵爐堡中心的大鍛爐東邊找到他。', '想要乘坐獅鷲獸，是嗎?你得去找格萊斯·瑟登。$B$B你可以在鐵爐堡中心的大鍛爐東邊找到他。', '想要乘坐獅鷲獸，是嗎?你得去找格萊斯·瑟登。$B$B你可以在鐵爐堡中心的大鍛爐東邊找到他。', '想要乘坐獅鷲獸，是嗎?你得去找格萊斯·瑟登。$B$B你可以在鐵爐堡中心的大鍛爐東邊找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
