INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2804, 'zhTW', '這兒有采礦訓練師嗎?你認為你在哪兒!?$B$B你將在大鍛爐北邊深山採礦公會找到丹莫洛地區最好的礦工。吉爾弗拉姆·石趾將為你展示真正的採礦藝術。', '這兒有采礦訓練師嗎?你認為你在哪兒!?$B$B你將在大鍛爐北邊深山採礦公會找到丹莫洛地區最好的礦工。吉爾弗拉姆·石趾將為你展示真正的採礦藝術。', '這兒有采礦訓練師嗎?你認為你在哪兒!?$B$B你將在大鍛爐北邊深山採礦公會找到丹莫洛地區最好的礦工。吉爾弗拉姆·石趾將為你展示真正的採礦藝術。', '這兒有采礦訓練師嗎?你認為你在哪兒!?$B$B你將在大鍛爐北邊深山採礦公會找到丹莫洛地區最好的礦工。吉爾弗拉姆·石趾將為你展示真正的採礦藝術。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
