INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2807, 'zhTW', '約莫德·石眉對縫紉有獨到之處，真的。如果你想接受訓練的話，就去大鍛爐北邊的石眉布衣店找他吧。', '約莫德·石眉對縫紉有獨到之處，真的。如果你想接受訓練的話，就去大鍛爐北邊的石眉布衣店找他吧。', '約莫德·石眉對縫紉有獨到之處，真的。如果你想接受訓練的話，就去大鍛爐北邊的石眉布衣店找他吧。', '約莫德·石眉對縫紉有獨到之處，真的。如果你想接受訓練的話，就去大鍛爐北邊的石眉布衣店找他吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
