INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2811, 'zhTW', '水晶塔似乎正在傳送什麼資料。$B$B仔細地檢查了這座塔之後，你發現了一個由藍色、黃色和綠色水晶組成的圖樣，它們以一種特殊的形態排列著。$B$B一大圈藍色水晶兩側分別有一小圈黃色水晶和另一圈綠色水晶。$B$B你仔細觀察水晶的顏色，知道有人一定會對你所發現的很感興趣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2812 AND `Locale` = 'zhTW';
