INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2835, 'zhTW', '安戈洛這裡的暴掠龍看起來與貧瘠之地的迅猛龍有關，非常聰明，十分靈活，還有相似的行為準則。其中我所遇到的最偉大的是拉克維。他是我所見過的最危險的動物之一。在牛頭人語，拉克維的意思是「鋒利的爪子」，但那對他並不公平。$B$B如果你計畫獵殺拉克維的話，千萬不要低估他，但如果你決定要這樣做，無論如何我都會幫你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2836 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2836, 'zhTW', '北方的水晶塔接受黃紅綠三種顏色的水晶構成。$B$B而關鍵是使用黃水晶所產生的能量作為主要的力量來源。有兩種可能的效果:一種會製造破壞，一種會消除破壞。$B$B爆炸水晶需要紅水晶和黃水晶。這將產生劇烈爆炸，足以震懾你的敵人。$B$B恢復水晶需要黃水晶和綠水晶。這將給你提供治療光環。', '北方的水晶塔接受黃紅綠三種顏色的水晶構成。$B$B而關鍵是使用黃水晶所產生的能量作為主要的力量來源。有兩種可能的效果:一種會製造破壞，一種會消除破壞。$B$B爆炸水晶需要紅水晶和黃水晶。這將產生劇烈爆炸，足以震懾你的敵人。$B$B恢復水晶需要黃水晶和綠水晶。這將給你提供治療光環。', '北方的水晶塔接受黃紅綠三種顏色的水晶構成。$b$b而關鍵是使用黃水晶所產生的能量作為主要的力量來源。有兩種可能的效果:一種會製造破壞，一種會消除破壞。$b$b爆炸水晶需要紅水晶和黃水晶。這將產生劇烈爆炸，足以震懾你的敵人。$b$b恢復水晶需要黃水晶和綠水晶。這將給你提供治療光環。', '北方的水晶塔接受黃紅綠三種顏色的水晶構成。$B$B而關鍵是使用黃水晶所產生的能量作為主要的力量來源。有兩種可能的效果:一種會製造破壞，一種會消除破壞。$B$B爆炸水晶需要紅水晶和黃水晶。這將產生劇烈爆炸，足以震懾你的敵人。$B$B恢復水晶需要黃水晶和綠水晶。這將給你提供治療光環。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
