INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2837, 'zhTW', '西方的水晶塔接受紅色，綠色和藍色的水晶。$B$B塔門關鍵是要用紅色水晶作為力量源泉而產生的能量。可能有兩種結果:一種能提高你的防禦力，而另一種則是削弱敵人的防禦。$B$B防禦水晶需要紅色和綠色的水晶。這將會使你的裝甲更完備。$B$B破甲水晶需要藍色和紅色的水晶。這將會削弱即定目標的裝甲防禦。', '西方的水晶塔接受紅色，綠色和藍色的水晶。$B$B塔門關鍵是要用紅色水晶作為力量源泉而產生的能量。可能有兩種結果:一種能提高你的防禦力，而另一種則是削弱敵人的防禦。$B$B防禦水晶需要紅色和綠色的水晶。這將會使你的裝甲更完備。$B$B破甲水晶需要藍色和紅色的水晶。這將會削弱即定目標的裝甲防禦。', '西方的水晶塔接受紅色，綠色和藍色的水晶。$b$b塔門關鍵是要用紅色水晶作為力量源泉而產生的能量。可能有兩種結果:一種能提高你的防禦力，而另一種則是削弱敵人的防禦。$b$b防禦水晶需要紅色和綠色的水晶。這將會使你的裝甲更完備。$b$b破甲水晶需要藍色和紅色的水晶。這將會削弱即定目標的裝甲防禦。', '西方的水晶塔接受紅色，綠色和藍色的水晶。$B$B塔門關鍵是要用紅色水晶作為力量源泉而產生的能量。可能有兩種結果:一種能提高你的防禦力，而另一種則是削弱敵人的防禦。$B$B防禦水晶需要紅色和綠色的水晶。這將會使你的裝甲更完備。$B$B破甲水晶需要藍色和紅色的水晶。這將會削弱即定目標的裝甲防禦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
