INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2842, 'zhTW', '這片美麗的森林受到了可怕的詛咒!腐化的力量將這兒變成了一片恐懼之地。如果你跟他們不是一夥的，或許你能幫助我奪回費伍德森林。', '這片美麗的森林受到了可怕的詛咒!腐化的力量將這兒變成了一片恐懼之地。如果你跟他們不是一夥的，或許你能幫助我奪回費伍德森林。', '這片美麗的森林受到了可怕的詛咒!腐化的力量將這兒變成了一片恐懼之地。如果你跟他們不是一夥的，或許你能幫助我奪回費伍德森林。', '這片美麗的森林受到了可怕的詛咒!腐化的力量將這兒變成了一片恐懼之地。如果你跟他們不是一夥的，或許你能幫助我奪回費伍德森林。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
