INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2843, 'zhTW', '「牛頭人語?」$B$B牛頭人德魯伊滿懷期望地看著你，但是你顯然無法跟她溝通。她微笑著指向自己，然後指著你。最後她向南面的道路指了幾下。$B$B或許她是在表示南面道路的前方有可以跟你進行交談的德魯伊?', '「牛頭人語?」$B$B牛頭人德魯伊滿懷期望地看著你，但是你顯然無法跟她溝通。她微笑著指向自己，然後指著你。最後她向南面的道路指了幾下。$B$B或許她是在表示南面道路的前方有可以跟你進行交談的德魯伊?', '「牛頭人語?」$B$B牛頭人德魯伊滿懷期望地看著你，但是你顯然無法跟她溝通。她微笑著指向自己，然後指著你。最後她向南面的道路指了幾下。$B$B或許她是在表示南面道路的前方有可以跟你進行交談的德魯伊?', '“牛頭人語?”$B$B牛頭人德魯伊滿懷期望地看著你，但是你顯然無法跟她溝通。她微笑著指向自己，然後指著你。最後她向南面的道路指了幾下。$B$B或許她是在表示南面道路的前方有可以跟你進行交談的德魯伊?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2844 AND `Locale` = 'zhTW';
