INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2993, 'zhTW', '它們都失蹤了，$r。在天譴軍團入侵奎爾薩拉斯的時候，精靈族的聖契散落到世界各地。$B$B現在我們得搜尋這些聖契。尋找其中的秘密─並恢復其中蘊含的力量。$B$B我在尋找由卡里爾·溫薩魯斯書寫的聖契。如果你找到了聖契，請允許我吸收它的魔法力量，而為你我可以製作一種力量的融合物……當然，所有的事情都是有代價的。這項任務的風險極大，但是我給予的回報也是相當豐厚的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2995 AND `Locale` = 'zhTW';
