INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3042, 'zhTW', '世間動物死時會將它們的生命和獸皮賜予我們。要是你能尊重牠們的犧牲，或許剝皮這個專業技能會適合你的。去達納蘇斯北部的工匠區，找艾拉迪爾談談，學習更多知識。', '世間動物死時會將它們的生命和獸皮賜予我們。要是你能尊重牠們的犧牲，或許剝皮這個專業技能會適合你的。去達納蘇斯北部的工匠區，找艾拉迪爾談談，學習更多知識。', '世間動物死時會將它們的生命和獸皮賜予我們。要是你能尊重牠們的犧牲，或許剝皮這個專業技能會適合你的。去達納蘇斯北部的工匠區，找艾拉迪爾談談，學習更多知識。', '世間動物死時會將它們的生命和獸皮賜予我們。要是你能尊重牠們的犧牲，或許剝皮這個專業技能會適合你的。去達納蘇斯北部的工匠區，找艾拉迪爾談談，學習更多知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
