INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3044, 'zhTW', '如果你有希望學成一位裁縫的話你當然應該去找玫琳恩。她住在達納蘇斯東北方的工匠區。', '如果你有希望學成一位裁縫的話你當然應該去找玫琳恩。她住在達納蘇斯東北方的工匠區。', '如果你有希望學成一位裁縫的話你當然應該去找玫琳恩。她住在達納蘇斯東北方的工匠區。', '如果你有希望學成一位裁縫的話你當然應該去找玫琳恩。她住在達納蘇斯東北方的工匠區。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
