INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3074, 'zhTW', '好吧*嗝兒*……嗯，你看起來很眼熟*嗝兒*。我有跟你說過我和溫德索爾一起跟，呃，一，一百萬個獸人戰鬥的事兒嗎?$B$B哦，坐下來吧，朋友，這個故事非常棒的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
