INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3157, 'zhTW', '歡迎你來到塞拉摩，$N。$B$B我沒時間跟你寒暄，我為自己的唐突向你道歉，但是我必須以城市為首。我們的生活和聯盟的尊嚴受到了嚴重的威脅。要想使我的人民平安幸福，我就必須對不在我們控制之外的力量保持警惕。$B$B或許稍後我們能找時間談談。', '歡迎你來到塞拉摩，$N。$B$B我沒時間跟你寒暄，我為自己的唐突向你道歉，但是我必須以城市為首。我們的生活和聯盟的尊嚴受到了嚴重的威脅。要想使我的人民平安幸福，我就必須對不在我們控制之外的力量保持警惕。$B$B或許稍後我們能找時間談談。', '歡迎你來到塞拉摩，$N。$b$b我沒時間跟你寒暄，我為自己的唐突向你道歉，但是我必須以城市為首。我們的生活和聯盟的尊嚴受到了嚴重的威脅。要想使我的人民平安幸福，我就必須對不在我們控制之外的力量保持警惕。$b$b或許稍後我們能找時間談談。', '歡迎你來到塞拉摩，$N。$B$B我沒時間跟你寒暄，我為自己的唐突向你道歉，但是我必須以城市為首。我們的生活和聯盟的尊嚴受到了嚴重的威脅。要想使我的人民平安幸福，我就必須對不在我們控制之外的力量保持警惕。$B$B或許稍後我們能找時間談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3158 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3158, 'zhTW', '亨德爾已經被我們逮捕了，$N。謝謝你。$B$B儘管審訊的進展會比較緩慢，但我向你保證，他會告訴我們他所知道的一切。$B$B現在還請你耐心等待。如果我需要你的幫助，就會馬上聯絡你。$B$B在那之前，請享受塞拉摩之旅，我邀請你作為聯盟的朋友來到我們城市，要待多久隨便你。', '亨德爾已經被我們逮捕了，$N。謝謝你。$B$B儘管審訊的進展會比較緩慢，但我向你保證，他會告訴我們他所知道的一切。$B$B現在還請你耐心等待。如果我需要你的幫助，就會馬上聯絡你。$B$B在那之前，請享受塞拉摩之旅，我邀請你作為聯盟的朋友來到我們城市，要待多久隨便你。', '亨德爾已經被我們逮捕了，$N。謝謝你。$b$b儘管審訊的進展會比較緩慢，但我向你保證，他會告訴我們他所知道的一切。$b$b現在還請你耐心等待。如果我需要你的幫助，就會馬上聯絡你。$b$b在那之前，請享受塞拉摩之旅，我邀請你作為聯盟的朋友來到我們城市，要待多久隨便你。', '亨德爾已經被我們逮捕了，$N。謝謝你。$B$B儘管審訊的進展會比較緩慢，但我向你保證，他會告訴我們他所知道的一切。$B$B現在還請你耐心等待。如果我需要你的幫助，就會馬上聯絡你。$B$B在那之前，請享受塞拉摩之旅，我邀請你作為聯盟的朋友來到我們城市，要待多久隨便你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3173 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3173, 'zhTW', '在城市的大門外有一處路標，上頭註明了往西方飛艇塔的方向。', '在城市的大門外有一處路標，上頭註明了往西方飛艇塔的方向。', '在城市的大門外有一處路標，上頭註明了往西方飛艇塔的方向。', '在城市的大門外有一處路標，指向地精塔。去跟塔頂的地精飛艇管理人弗雷薩交談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3193 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3193, 'zhTW', '我和我的兄弟效忠於希瓦娜斯。在最黑暗的時代，她是我們的指路明燈。我們日復一日地奉獻著，希望使種族避免遭受厄運。$B$B我們不會一直軟弱下去的。我們會取回自己應得的。我們將報復敵人，讓他們嚐到十倍於我們的痛苦。並且，我們將面帶微笑報復敵人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3194 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3194, 'zhTW', '希瓦娜斯女王已經下令對艾澤拉斯的某些自然現象進行調查。她覺得能從艾澤拉斯神秘的歷史中學到更多的知識。$B$B我不知道要如何才能學到這些知識，但是我完全相信她，因此我會盡力而為的。所有的生物看起來很相似，但是周圍的環境對它們的影響是不容忽略的。$B$B我需要你幫我收集生物樣本。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3213 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3213, 'zhTW', '<你靠近沃科爾時，他一點都不理睬你。他好像集中精力關注他的繃帶以防脫落。過了一會兒，他抬頭看你，有一點驚詫。>$B$B噢，對不起，$c。現在不太合適。我希望你能理解。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3214 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3214, 'zhTW', '嗯，依我看來，$N，要離開這個洞穴有兩種選擇。$B$B我們可以秘密潛逃─我利用你給我的披風，你用你自己的辦法;或者，我們一起殺出去，但是我受傷了，這個方法或許比較困難。$B$B你更瞭解自己的實力，因此我讓你來做選擇。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3218 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3218, 'zhTW', '你好，$g小夥子:姑娘;，如果你想要在鐵爐堡之外找到最好的交易地點，那麼你就算找對地方了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
