INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3233, 'zhTW', '你看到我們湖中汙濁的水元素了嗎，$N?這個場景令人感到傷感，但是我不知道它們是從哪裡來的。$B$B在我過去的談話中似乎有人提起過你的名字，或許你可以幫我。$B$B我們必須瞭解的第一件事就是誰控制著這些元素。', '你看到我們湖中汙濁的水元素了嗎，$N?這個場景令人感到傷感，但是我不知道它們是從哪裡來的。$B$B在我過去的談話中似乎有人提起過你的名字，或許你可以幫我。$B$B我們必須瞭解的第一件事就是誰控制著這些元素。', '你看到我們湖中汙濁的水元素了嗎，$N?這個場景令人感到傷感，但是我不知道它們是從哪裡來的。$b$b在我過去的談話中似乎有人提起過你的名字，或許你可以幫我。$b$b我們必須瞭解的第一件事就是誰控制著這些元素。', '你看到我們湖中汙濁的水元素了嗎，$N?這個場景令人感到傷感，但是我不知道它們是從哪裡來的。$B$B在我過去的談話中似乎有人提起過你的名字，或許你可以幫我。$B$B我們必須瞭解的第一件事就是誰控制著這些元素。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3234 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3234, 'zhTW', '你好。我是古博·布拉普。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
