INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3273, 'zhTW', '當你靠近時，那些液體和混合物劇烈地翻騰起來。裝置旁邊是一把巨大的鉗子，似乎很適合用來夾起軟泥樣本。$B$B還有安全齒輪裝備，但是上面佈滿灰塵，似乎很久沒有使用過了。$B$B你覺得最好什麼東西都別碰。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
