INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3296, 'zhTW', '燃燒平原是個危險的地方，但是我這樣的學者將不惜一切代價來獲取新知識。', '燃燒平原是個危險的地方，但是我這樣的學者將不惜一切代價來獲取新知識。', '燃燒平原是個危險的地方，但是我這樣的學者將不惜一切代價來獲取新知識。', '燃燒平原是個危險的地方，但是我這樣的學者將不惜一切代價來獲取新知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
