INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3299, 'zhTW', '啊，一個術士同伴已經在某種程度上證明了$g他的:她的;價值。$B$B很高興認識你。我的名字是梅納拉·虛無撕裂者……那是有原因的。$B$B你看起來強大並博學，其他的工具……你是更強大的工具……會很受歡迎而不是愚蠢地洩密。如果事實確實如此，那再與我更深入地談談。如果不是，那麼你知道你該怎麼回到碼頭然後回到海洋的另一邊。', '啊，一個術士同伴已經在某種程度上證明了$g他的:她的;價值。$B$B很高興認識你。我的名字是梅納拉·虛無撕裂者……那是有原因的。$B$B你看起來強大並博學，其他的工具……你是更強大的工具……會很受歡迎而不是愚蠢地洩密。如果事實確實如此，那再與我更深入地談談。如果不是，那麼你知道你該怎麼回到碼頭然後回到海洋的另一邊。', '啊，一個術士同伴已經在某種程度上證明了$g他的:她的;價值。\n\n很高興認識你。我的名字是梅納拉·虛無撕裂者……那是有原因的。\n\n你看起來強大並博學，其他的工具……你是更強大的工具……會很受歡迎而不是愚蠢地洩密。如果事實確實如此，那再與我更深入地談談。如果不是，那麼你知道你該怎麼回到碼頭然後回到海洋的另一邊。', '啊，一個術士同伴已經在某種程度上證明了$g他的:她的;價值。$B$B很高興認識你。我的名字是梅納拉·虛無撕裂者……那是有原因的。$B$B你看起來強大並博學，其他的工具……你是更強大的工具……會很受歡迎而不是愚蠢地洩密。如果事實確實如此，那再與我更深入地談談。如果不是，那麼你知道你該怎麼回到碼頭然後回到海洋的另一邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3301 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3301, 'zhTW', '很久以前─我們的種族經歷了無數戰亂和衝突，幾乎到了滅絕的邊緣。我們承受了太多災難，$r。$B$B燃燒軍團的進攻，惡魔之魂，守護巨龍的分裂，死亡之翼的崛起，我們的女王雅立史卓莎受到龍喉氏族的奴役。$B$B經過種種磨難，我們擁有了不可動搖的意志─那是努力生存的大無畏力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3302 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3302, 'zhTW', '我以你所能接受的形態站在你面前。顯然，你無法接受一條名叫瓦拉斯塔茲的龍。$B$B<維埃蘭笑了起來。>$B$B我可以繼續嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3303 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3303, 'zhTW', '或許我應該告訴你為什麼我會在這兒。$B$B你知道守護巨龍，死亡之翼或者他的後裔，奈法利安和奧妮克希亞嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3304 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3304, 'zhTW', '死亡之翼，曾被稱為奈薩里奧，它是代表世界的力量的守護巨龍─世界的締造者卡茲格羅斯賦予了他無盡的力量，讓他保護這個世界。$B$B但是這個卑鄙的傢伙欺騙了其他四條守護巨龍，讓他們使用自己的力量製造了惡魔之魂─這使得他們的力量大為減弱，巨龍軍團於是就分裂了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3305 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3305, 'zhTW', '是的。最終惡魔之魂被摧毀了，剩餘的四條守護巨龍聯合起來，幾乎取了死亡之翼的性命。沒人知道死亡之翼現在到底在哪裡。但是，我們知道他的一名後裔奈法利安正統治著這座要塞，希望能繼續他父親未竟的事業。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3306 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3306, 'zhTW', '在被放逐之前，死亡之翼曾試圖產下混血的後代。混血的龍不僅無法獲得守護巨龍天生的力量，也無法被死亡之翼控制。$B$B似乎奈法利安在他父親失敗了的事情上取得了成功─至少是一些進展。$B$B夢境之龍伊瑟拉預見到了這種混血龍類的存在，我們必須殺死那些「炫彩」之龍。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3307 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3307, 'zhTW', '這不是我們做事的方法，也不可能是。奈法利安受到遠古結界的保護，這些結界與守護巨龍本身一樣古老。正是它們阻止我進入這座要塞的內部。除非……除非得到授權，否則黑暗魔法會永遠把我們擋在外面。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3308 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3308, 'zhTW', '除龍族之外的任何人都可能獲得晉升徽印並透過那層保護屏障，但是這樣的東西肯定會要了我的性命，或許你能使用它，想辦法破除屏障。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3309 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3309, 'zhTW', '你必須在這座要塞下層部分的那些邪惡生物裡找到一個擁有原始晉升徽印的傢伙。對於那些劣等生物來說，得到這枚物品是一個至高無上的榮譽，這是邁入堡壘上層，進入奈法利安的精英軍團─黑手軍團的第一步。找到這麼一件東西，把它交給我，讓我來檢查一下它，然後我就會知道下一步該怎麼做了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3310 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3310, 'zhTW', '你要知道，這樣的物品是非常罕見的。你可能需要進行數年的搜尋才能找到一枚印章。我建議你對這些邪惡的生物毫不留情，把他們全都殺掉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3311 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3311, 'zhTW', '別再靠近我了，$n。我已經可以感覺到徽印中流淌著的邪惡力量了。$B$B給我一點時間，讓我來檢查檢查─你要緊緊地握住它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3321 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3321, 'zhTW', '死亡之翼，曾被稱為奈薩里安，它是代表世界的力量的守護巨龍——世界的締造者卡茲格羅斯賦予了他無盡的力量，讓他保護這個世界。$b$b但是這個卑鄙的傢伙欺騙了其它四條守護巨龍，讓他們使用自己的力量製造了惡魔之魂——這使得他們的力量大為減弱，巨龍軍團於是就分裂了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3334 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3334, 'zhTW', '$N，我已經查明魔苔在整個黑海岸的影響有多麼的猖獗。泰達希爾和我們周圍大地的墮落的確引起了塞納里奧議會德魯伊以及所有的夜精靈的關注。$B$B我的目標就是查出為什麼會發生這樣的事並將其制止。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3337 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3337, 'zhTW', '沒有具備天賦的附魔師，刀刃不可能如此鋒利，護甲也不可能如此堅固。塔蘭丹就是這樣的附魔師，他可以教你如何給武器和護甲附魔。去工匠區找他吧。', '沒有具備天賦的附魔師，刀刃不可能如此鋒利，護甲也不可能如此堅固。塔蘭丹就是這樣的附魔師，他可以教你如何給武器和護甲附魔。去工匠區找他吧。', '沒有具備天賦的附魔師，刀刃不可能如此鋒利，護甲也不可能如此堅固。塔蘭丹就是這樣的附魔師，他可以教你如何給武器和護甲附魔。去工匠區找他吧。', '沒有具備天賦的附魔師，刀刃不可能如此鋒利，護甲也不可能如此堅固。塔蘭丹就是這樣的附魔師，他可以教你如何給武器和護甲附魔。去工匠區找他吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3357 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3357, 'zhTW', '歡迎來到我的商店，$c。古斯提兄弟能為你做什麼嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3358 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3358, 'zhTW', '啊，我最喜愛的顧客之一。你似乎是個有能力的術士，$N。很高興認識你。要是我能幫上什麼忙，請儘管開口。$B$B我和我的兄弟都認為你這樣的人才能領導我們進入新紀元。一個擁有力量……和控制力的人……讓軍團臣服於你只是時間問題。$B$B我有些羨慕你了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3375 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3375, 'zhTW', '啊，$r...我瞭解很多關於這個世界的知識，以及如何製造巨大能量的符咒的方法。', '啊，$r...我瞭解很多關於這個世界的知識，以及如何製造巨大能量的符咒的方法。', '啊，$r……我瞭解很多關於這個世界的知識，以及如何製造巨大能量的符咒的方法。', '啊，$r……我瞭解很多關於這個世界的知識，以及如何製造巨大能量的符咒的方法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3377 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3377, 'zhTW', '瑪艾裡知道你為什麼找她...$B$B帶給我你找到的魂精，我就會為你轉換它。', '瑪艾裡知道你為什麼找她...$B$B帶給我你找到的魂精，我就會為你轉換它。', '瑪艾裡知道你為什麼找她……$b$b帶給我你找到的魂精，我就會為你轉換它。', '瑪艾裡知道你為什麼找她……$B$B帶給我你找到的魂精，我就會為你轉換它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3380 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3380, 'zhTW', '是的是的，我知道達丹加不喜歡煙。但從它身上的氣味來看，達丹加好像還不喜歡洗澡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3382 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3382, 'zhTW', '瑪艾裡的容器有很多秘密……用來製作它的裂片是可以反光的，你可以使用它的反光面從其他事物身上吸取能量然後反射到自己身上。$B$B將符咒放在你的揹包裡可以讓你聚集魂精，也就是與你戰鬥的野獸的靈魂力量。一旦你找到魂精，你把它帶給瑪艾裡。', '瑪艾裡的容器有很多秘密……用來製作它的裂片是可以反光的，你可以使用它的反光面從其他事物身上吸取能量然後反射到自己身上。$B$B將符咒放在你的揹包裡可以讓你聚集魂精，也就是與你戰鬥的野獸的靈魂力量。一旦你找到魂精，你把它帶給瑪艾裡。', '瑪艾裡的容器有很多秘密……用來製作它的裂片是可以反光的，你可以使用它的反光面從其他事物身上吸取能量然後反射到自己身上。\n\n將符咒放在你的揹包裡可以讓你聚集魂精，也就是與你戰鬥的野獸的靈魂力量。一旦你找到魂精，你把它帶給瑪艾裡。', '瑪艾裡的容器有很多秘密……用來製作它的裂片是可以反光的，你可以使用它的反光面從其他事物身上吸取能量然後反射到自己身上。$B$B將符咒放在你的揹包裡可以讓你聚集魂精，也就是與你戰鬥的野獸的靈魂力量。一旦你找到魂精，你把它帶給瑪艾裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3383 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3383, 'zhTW', '魂精是每個生物都有的能量。我為你做的符咒使你能以物理形態來抓到它。$B$B我知道一個可以轉換你發現的魂精的咒語，並把它轉換成魂能。$B$B你然後可以得到瑪艾裡的容器，並使用它把魂能的能量轉換到自己身上。$B$B來吧，試一下。把瑪艾裡的魂精帶來我們開心一下。', '魂精是每個生物都有的能量。我為你做的符咒使你能以物理形態來抓到它。$B$B我知道一個可以轉換你發現的魂精的咒語，並把它轉換成魂能。$B$B你然後可以得到瑪艾裡的容器，並使用它把魂能的能量轉換到自己身上。$B$B來吧，試一下。把瑪艾裡的魂精帶來我們開心一下。', '魂精是每個生物都有的能量。我為你做的護符使你能以物理形態來抓到它。$b$b我知道一個可以轉換你發現的魂精的咒語，並把它轉換成魂能。$b$b你然後可以得到瑪艾裡的容器，並使用它把魂能的能量轉換到自己身上。$b$b來吧，試一下。把瑪艾裡的魂精帶來我們開心一下。', '魂精是每個生物都有的能量。我為你做的符咒使你能以物理形態來抓到它。$B$B我知道一個可以轉換你發現的魂精的咒語，並把它轉換成魂能。$B$B你然後可以得到瑪艾裡的容器，並使用它把魂能的能量轉換到自己身上。$B$B來吧，試一下。把瑪艾裡的魂精帶來我們開心一下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3395 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3395, 'zhTW', '你好，$g小夥子:姑娘;。我可以幫你什麼忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3396 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3396, 'zhTW', '你是來接受訓練的嗎?我也是剛剛開始學習這方面的知識，但是我很樂意把我所知道的教給你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3397 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3397, 'zhTW', '啊，我最喜愛的顧客之一。你似乎是個有能力的術士，$N。很高興認識你。要是我能幫上什麼忙，請儘管開口。$b$b我和我的兄弟都認為你這樣的人才能領導我們進入新紀元。一個擁有力量……和控制力的人……讓軍團臣服於你只是時間問題。$b$b我有些羨慕你了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3398 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3398, 'zhTW', '嗯?我沒時間聊天，我父親要我完成這個使命。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3399 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3399, 'zhTW', '你確實有點本事。我打賭你的技術足夠讓你學些東西了，我們來看看我有什麼能教給你的，好嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3400 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3400, 'zhTW', '你知道的比我還多，這一點很肯定。我告訴你接下來該怎麼辦，去和我的爸爸談談。他是個好的老師，但是他會要求你證明自己的實力。他的名字叫洛特加斯，你可以在本古斯的鐵砧旁邊找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3401 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3401, 'zhTW', '我的朋友，你所掌握的技藝遠勝於我。你為什麼不去找我的老朋友洛特加斯·石須繼續深造呢?我離開鐵爐堡加入了珍娜的軍隊，而他留了下來。我想他能教你點什麼，至少他會知道誰能教你。如果他還待在鐵爐堡的話，我想他一定在大鍛爐附近。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3402 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3402, 'zhTW', '從冬泉谷的生物開始應該不錯。$B$B然而，或許還有別的地方你可以看看……', '從冬泉谷的生物開始應該不錯。$B$B然而，或許還有別的地方你可以看看……', '從冬泉谷的生物開始應該不錯。$b$b然而，或許還有別的地方你可以看看……', '從冬泉谷的生物開始應該不錯。$B$B然而，或許還有別的地方你可以看看……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3403 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3403, 'zhTW', '當然，我可以幫你進行訓練。我也只是一個新手，但是我想我還是能對你有所幫助的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3404 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3404, 'zhTW', '我不會輕易承認這一點的，不過你的確是個比我出色得多的鐵匠。如果你想要學習更多高階的技能，我建議你去暴風城的矮人區找一個名叫瑟魯姆·深爐的矮人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3405 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3405, 'zhTW', '很抱歉，我現在有些忙，我要為湖畔鎮的弗納·奧斯古打造馬蹄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3406 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3406, 'zhTW', '我看起來像是有時間和你閒談的樣子嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3407 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3407, 'zhTW', '你還不壞，但讓我耍耍幾個小把戲，你可能會覺得很方便實用的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3408 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3408, 'zhTW', '你已經是一個比我好得多的鐵匠，那是肯定的。儘管如果你告訴其他人這點我會否認我曾說過。你該去找瑟魯姆·深爐談談。如果有人能教你，那就是他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3409 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3409, 'zhTW', '我若聽到任何有關水禽的意見, 你將來就必須用管子進食。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3410 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3410, 'zhTW', '僅僅會揮動鐵錘是無法成為鐵匠的。把鐵錘給我，在你讓大家感到窘迫之前讓我教教你好了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3411 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3411, 'zhTW', '還行。去跟斯納爾談談，他剛前往奧格瑪向薩魯求學。去薩魯的鐵匠鋪附近的戰士區找他吧。他會對你進行測試，你最好做好準備。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3412 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3412, 'zhTW', '斯納爾因為我動作太慢所以說我很笨。我只是想做好工作罷了，這得花時間的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3413 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3413, 'zhTW', '我可以告訴你你想知道的一切，但是你必須要有耐心。去練習打鐵吧，摸索用錘的力度。當你熟練後，自然也就掌握啦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3414 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3414, 'zhTW', '你學得很快，這是件好事。但要注意按照工作的要求適當地完成工作。現在，我恐怕必須要把你送到斯納爾那裡多學些東西。你要學會所有他能教的，但不要聽他的氣話。當薩魯的女兒笑話他時他就變成那樣了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3415 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3415, 'zhTW', '我在聽，我在聽，但是聽不見卡恩所說的那些靈魂的聲音。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3416 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3416, 'zhTW', '卡恩說我們需要聆聽熔爐和鋼鐵的靈魂之聲，它們會指引我們的。我只聽見一陣鈴聲。拿起鐵錘，讓我們一起試著聽它們在說什麼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3417 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3417, 'zhTW', '我猜那些靈魂更加喜歡你，我還沒有聽到他們的召喚但是你看起來已經上過他們好多課程了。去找卡恩談談，他會很高興看到一個像他一樣聽到它們聲音的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3418 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3418, 'zhTW', '你的打擾在佔用我的寶貴時間，你最好帶來的是好訊息。', '你的打擾在佔用我的寶貴時間，你最好帶來的是好訊息。', '你的打擾在佔用我的寶貴時間，你最好帶來的是好訊息。', '你的打擾在佔用我的寶貴時間，你最好帶來的是好訊息。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3419 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3419, 'zhTW', '啊是的，另一個要燒爐火併鍛造戰鬥武器的人。我當然會教你怎麼操作。', '啊是的，另一個要燒爐火併鍛造戰鬥武器的人。我當然會教你怎麼操作。', '啊是的，另一個要燒爐火併鍛造戰鬥武器的人。我當然會教你怎麼操作。', '啊是的，另一個要燒爐火併鍛造戰鬥武器的人。我當然會教你怎麼操作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3420 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3420, 'zhTW', '我的孩子，你學得很好。去幽暗城找一個名叫詹姆士·範·布朗特的鐵匠。他能傳授給你更多的知識。我想他應該在戰士訓練大廳附近鑄造武器。', '我的孩子，你學得很好。去幽暗城找一個名叫詹姆士·範·布朗特的鐵匠。他能傳授給你更多的知識。我想他應該在戰士訓練大廳附近鑄造武器。', '我的孩子，你學得很好。去幽暗城找一個名叫詹姆士·範·布朗特的鐵匠。他能傳授給你更多的知識。我想他應該在戰士訓練大廳附近鑄造武器。', '我的孩子，你學得很好。去幽暗城找一個名叫詹姆士·範·布朗特的鐵匠。他能傳授給你更多的知識。我想他應該在戰士訓練大廳附近鑄造武器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3421 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3421, 'zhTW', '我希望有一天能用敵人的骨頭製作武器。', '我希望有一天能用敵人的骨頭製作武器', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3422 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3422, 'zhTW', '你不要用錘子傻乎乎地敲打鐵砧，你應該是在製造一種可以殺死你的敵人的武器。讓我給你演示一下你哪裡做錯了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3423 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3423, 'zhTW', '我在聽，我在聽，但是聽不見卡恩所說的那些靈魂的聲音。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3424 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3424, 'zhTW', '魂精是超自然力量的一種沒有匯聚的形態，而魂能則是濃縮的精華。透過使用一種強大的咒語，我可以把魂精變成魂能。一旦它變成魂能，你就可以使用瑪艾裡的容器把能量反射到你自己身上。', '魂精是超自然力量的一種沒有匯聚的形態，而魂能則是濃縮的精華。透過使用一種強大的咒語，我可以把魂精變成魂能。一旦它變成魂能，你就可以使用瑪艾裡的容器把能量反射到你自己身上。', '魂精是超自然力量的一種沒有匯聚的形態，而魂能則是濃縮的精華。透過使用一種強大的咒語，我可以把魂精變成魂能。一旦它變成魂能，你就可以使用瑪艾裡的容器把能量反射到你自己身上。', '魂精是超自然力量的一種沒有匯聚的形態，而魂能則是濃縮的精華。透過使用一種強大的咒語，我可以把魂精變成魂能。一旦它變成魂能，你就可以使用瑪艾裡的容器把能量反射到你自己身上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3425 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3425, 'zhTW', '我很驚訝一個如此粗心的人竟然能走到這裡……$B$B是的，你可能還有一個符咒，但是瑪艾裡對你的行為很生氣!$B$B現在趕緊離開。', '我很驚訝一個如此粗心的人竟然能走到這裡……$B$B是的，你可能還有一個符咒，但是瑪艾裡對你的行為很生氣!$B$B現在趕緊離開。', '我很驚訝一個如此粗心的人竟然能走到這裡……$B$B是的，你可能還有一個符咒，但是瑪艾裡對你的行為很生氣！$B$B現在趕緊離開。', '我很驚訝一個如此粗心的人竟然能走到這裡……$B$B是的，你可能還有一個符咒，但是瑪艾裡對你的行為很生氣!$B$B現在趕緊離開。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3453 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3453, 'zhTW', '你掌握一些關於錘頭和鐵砧的技藝，但還不夠。去找丹恩·林德雷談談，他會讓你做好準備學習我教給你的知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3454 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3454, 'zhTW', '我說過你有鐵匠的血統，看來我是對的。去鐵爐堡大鍛爐找一個名叫本古斯·深爐的矮人鐵匠。他是我的老師，是我知道的最偉大的鐵匠之一。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3456 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3456, 'zhTW', '鐵匠的生活可不輕鬆，但是它能讓你體格健壯，充滿熱情。我的父親是一名鐵匠，我的祖父曾經在格瑞姆巴託的鍊鐵爐工作。現在，我的兒子也跟隨著我們的腳步，他讓我倍感自豪。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3457 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3457, 'zhTW', '很抱歉，$g小夥子:姑娘;，你還不夠資格在我這兒求學。去找我的兒子 格魯姆，他會收你做學生的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3458 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3458, 'zhTW', '我希望有一天能用敵人的骨頭製作武器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3459 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3459, 'zhTW', '是的，很高興能教你如何鍛造。繫上圍裙，拿起鐵錘，看看我們能鍛造出什麼來?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3460 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3460, 'zhTW', '你是個有天分的學生，而且還是個有潛質的鐵匠。我可以在本週任何時候宣佈你可以從我這裡畢業了。但是我覺得你還有東西要學。去找本古斯·深爐談談，他是個嚴厲的人，但他也是最出色的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3461 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3461, 'zhTW', '不要那樣從陰暗中走出來。下次你要先給女生一點警示。', '不要那樣從陰暗中走出來。下次你要先給女生一點警示。', '不要那樣從陰暗中走出來。下次你要先給女生一點警示。', '不要那樣從陰暗中走出來。下次你要先給女生一點警示。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3462 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3462, 'zhTW', '呣，你的工作還可以，但是離我期盼的學生素質還差太遠。去找閃金鎮的鐵匠阿古斯談談，我敢肯定他能教你一些基礎知識。當你學完後再來找我，我會給你一次小測試以確定你準備好了。', '呣，你的工作還可以，但是離我期盼的學生素質還差太遠。去找閃金鎮的鐵匠阿古斯談談，我敢肯定他能教你一些基礎知識。當你學完後再來找我，我會給你一次小測試以確定你準備好了。', '呣，你的工作還可以，但是離我期盼的學生素質還差太遠。去找閃金鎮的鐵匠阿古斯談談，我敢肯定他能教你一些基礎知識。當你學完後再來找我，我會給你一次小測試以確定你準備好了。', '呣，你的工作還可以，但是離我期盼的學生素質還差太遠。去找閃金鎮的鐵匠阿古斯談談，我敢肯定他能教你一些基礎知識。當你學完後再來找我，我會給你一次小測試以確定你準備好了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3463 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3463, 'zhTW', '是的，我曾聽到傳言說我遲早會見到你的。但我不會隨便接納任何人的，我需要首先確定你的水準。你願接受我的測試嗎?', '是的，我曾聽到傳言說我遲早會見到你的。但我不會隨便接納任何人的，我需要首先確定你的水準。你願接受我的測試嗎?', '是的，我曾聽到傳言說我遲早會見到你的。但我不會隨便接納任何人的，我需要首先確定你的水準。你願接受我的測試嗎?', '是的，我曾聽到傳言說我遲早會見到你的。但我不會隨便接納任何人的，我需要首先確定你的水準。你願接受我的測試嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3464 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3464, 'zhTW', '你乾得很漂亮，但是刀口還有些粗劣。不要擔心，多加練習就會好的。說到這裡，我們看看你一直以來的工作怎麼樣?', '你乾得很漂亮，但是刀口還有些粗劣。不要擔心，多加練習就會好的。說到這裡，我們看看你一直以來的工作怎麼樣?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3465 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3465, 'zhTW', '現在我真是力不從心了，我說實話真是沒什麼可教你的了。但你知道誰可以嗎?鐵爐堡的本古斯·深爐，現在有一個矮人很瞭解他。到鐵爐堡的大鍛爐去找他，看看他是否想收個新學徒。', '現在我真是力不從心了，我說實話真是沒什麼可教你的了。但你知道誰可以嗎?鐵爐堡的本古斯·深爐，現在有一個矮人很瞭解他。到鐵爐堡的大鍛爐去找他，看看他是否想收個新學徒。', '現在我真是力不從心了，我說實話真是沒什麼可教你的了。但你知道誰可以嗎?鐵爐堡的本古斯·深爐，現在有一個矮人很瞭解他。到鐵爐堡的大鍛爐去找他，看看他是否想收個新學徒。', '現在我真是力不從心了，我說實話真是沒什麼可教你的了。但你知道誰可以嗎?鐵爐堡的本古斯·深爐，現在有一個矮人很瞭解他。到鐵爐堡的大鍛爐去找他，看看他是否想收個新學徒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3466 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3466, 'zhTW', '要是我向薩魯證明了自己的實力，他將別無選擇，只能讓我為他的一個女兒而戰。讓我們看看誰是失敗的那個吧。', NULL, '要是我向薩魯證明了自己的實力，他將別無選擇，只能讓我為他的一個女兒而戰。讓我們看看誰是失敗的那個吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3467 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3467, 'zhTW', '再次給我帶來這種劣質貨我就把你裝在用山羊尿回過火的小鐵盒裡送回家。現在去見見那個傻瓜烏格索克，他更加適合你的需要。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3468 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3468, 'zhTW', '你認為自己夠資格向我學習嗎?偉大的斯納爾?你不過是我腳下的一名卑微的小人物罷了。但是，收納一名下屬或許能增加我對蘇米和圖米的吸引力。讓我看看你擁有什麼技能。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3470 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3470, 'zhTW', '我沒有什麼東西可以教你了 - 快滾!不要想接近薩魯，因為像你一樣卑微的人他只會用你們的血來鍊鋼的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3471 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3471, 'zhTW', '靈魂將你帶到我這兒來，感謝他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3472 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3472, 'zhTW', '你需要多加留心靈魂的指引。你的路線取決於另一個人，雷霆崖的瑟拉格·石蹄。或許你們可以互相學習。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3473 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3473, 'zhTW', '告訴你，你準備好接受我為你安排的挑戰了嗎?幽靈告訴我你會透過的，但是你相信他們抑或是相信自己?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3475 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3475, 'zhTW', '我們的人生之路只是暫時相交，現在是我們分道揚鑣的時候啦。很榮幸能傳授你知識，現在我送你上路，去找下一個導師吧。去奧格瑪找薩魯·鋼怒，他會教你你想學的知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3476 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3476, 'zhTW', '你有巨大的潛能，但你必須首先能理解，你必須接受精靈們並聽從他們的召喚。只有那時你才會準備好走你要走的路。去找瑟拉格談談，我想你們可能會互相學習很多東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3478 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3478, 'zhTW', '你已經學了很多，但我覺得精靈們還有很多要教給你。我可以給你引路但不能替你走路。去找到奧格瑪的薩魯·鋼怒，你的旅程的下一段從那裡開始。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3479 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3479, 'zhTW', '你在浪費我的時間，去找我的學生巴茲爾談談吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3481 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3481, 'zhTW', '你製造的裝備很不錯，真的。去獸人的家園奧格瑪找一個名叫薩魯·鋼怒的鐵匠吧。你必須給那些製造美麗的死亡器具的獸人一樣東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3482 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3482, 'zhTW', '很抱歉$g小夥子:姑娘;，但是你基礎不足，我不能教你。但是別煩惱，跟我的學生洛特加斯談談，他會幫助你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3484 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3484, 'zhTW', '我無法對你光用鐵錘和鐵砧就做出如此令人稱奇的東西提供足夠的意見。現在，不要告訴別人我建議你去找一位哥布林，不過那確實就是我想要做的事。布里克·基克拉夫是他的名字，我最後一次聽到他是在藏寶海灣經營一家商店。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3485 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3485, 'zhTW', '這可不是一個年輕人玩的遊戲!去外面找斯納爾談談。他看起來或許有些陰險，但是他確實是使鐵砧的好手。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3487 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3487, 'zhTW', '我發現你所掌握的鍊鋼知識已經比我多了。這很好，本該如此。現在你必須去人類領土南部的叢林，去哥布林城市藏寶海灣。你將在那兒找到一個名為布里克·基克拉夫的哥布林。我不喜歡哥布林，但他所掌握的鍊鋼知識卻是無與倫比的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3488 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3488, 'zhTW', '什麼?我當然是一個鐵匠。什麼，你認為矮人是打鐵最有效率的種族?好吧，可能是那樣。去找一個矮人來幫你!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3489 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3489, 'zhTW', '你是在開玩笑吧?你一定是在開玩笑!你認為我是個取悅於你的小丑，是嗎?我是小丑?嗯，是的!你認為我是小丑，是吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3490 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3490, 'zhTW', '你表現得像這是我見過最好的垃圾。當然它還過得去，但我每天都看到這類‘還行’的東西。告訴你吧，你若能想辦法讓我叫好，我就會教給你能讓矮人們在睡夢裡都會笑的東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3493 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3493, 'zhTW', '儘管我不願承認，但是熊確實打敗了我。我的天，那是一隻體型龐大的熊!$B$B但是，如果你能打敗那隻熊的話，那可是一件值得驕傲的事兒!既便是我們中最好的獵人，也為此頭痛不已。$B$B<他拍著你的背。>$B$B打敗熊吧，你將成為遠行者小屋中一名合格的成員的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3494 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3494, 'zhTW', '在遠行者小屋，我們最推崇狩獵技能。想獲得我的賞識嗎?你得靠行動來證明。$B$B面對挑戰吧，$G小夥子:姑娘;!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3495 AND `Locale` = 'zhTW';
