INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3546, 'zhTW', '歡迎來到避難所，$N。有些人帶著目的來到這裡，其餘的是湊巧路過...但是每個到這裡的人好像都有一個奇特的故事要講。', '歡迎來到避難所，$N。有些人帶著目的來到這裡，其餘的是湊巧路過...但是每個到這裡的人好像都有一個奇特的故事要講。', '歡迎來到避難所，$N。有些人來這裡是有目的的，其餘的是湊巧路過……但是每個到這裡的人好像都有一個奇特的故事要講。', '歡迎來到避難所，$N。有些人帶著目的來到這裡，其餘的是湊巧路過……但是每個到這裡的人好像都有一個奇特的故事要講。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
