INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3554, 'zhTW', '謝謝你，$N。你安撫了我死去的妻子的靈魂，我將永遠無法報答你的恩情。$B$B我想我會永遠仇視野豬人，但是現在我已經得到了滿足。$B$B我必須開始重建生活。', '謝謝你，$N。你安撫了我死去的妻子的靈魂，我將永遠無法報答你的恩情。$B$B我想我會永遠仇視野豬人，但是現在我已經得到了滿足。$B$B我必須開始重建生活。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
