INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3557, 'zhTW', '這具屍體屬於一個女性獸人戰士。$B$B很明顯她是在戰鬥中死去的，或許是在對付這片地區的野豬人時死亡的。', '這具屍體屬於一個女性獸人戰士。$B$B很明顯她是在戰鬥中死去的，或許是在對付這片地區的野豬人時死亡的。', '這具屍體屬於一個女性獸人戰士。$b$b很明顯她是在戰鬥中死去的，或許是在對付這片地區的野豬人時死亡的。', '這具屍體屬於一個女性獸人戰士。$B$B很明顯她是在戰鬥中死去的，或許是在對付這片地區的野豬人時死亡的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
