INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3559, 'zhTW', '歡迎來到十字路口，$c。我叫索克─以大酋長的名義，我負責在這兒進行防禦。$B$B請你在這裡隨意一些。在你處理生意的時候，沒人會對你佔用空間有所異議的。$B$B我們的安全存在許多威脅。如果你想熟悉周圍的情況的話，就跟其他人談談吧─或許他們會派給你一些任務的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3560 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3560, 'zhTW', '<高圖斯啐了一口唾沫。>$B$B我是部落的戰士，$N。讓我憤怒的是得知我們的敵人正坐在離卡加斯不到一天路程的堡壘中，密謀著要對我們發起攻擊。$B$B我渴望擺脫責任的束縛，以大酋長的名義將他們消滅。$B$B但是，我們都有各自必須承擔的職責。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3561 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3561, 'zhTW', '你能以部落的名義衝鋒陷陣，我可真羨慕你。我的職責是指揮部落的軍隊，而不是親自上陣。$B$B當然，我年輕時也曾夢想著能安度晚年。現在，我痴迷於勝利的榮耀和失敗的苦楚─這些都取決於我所指揮計程車兵們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3562 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3562, 'zhTW', '我做夢了，$N……對，我做夢了。在夢中，我以上千種不同的方式死去。有人會認為這是夢魘，但我不這樣想!在夢中，我在戰場上死去。每次死亡之前我都會讓一萬名部落的敵人倒在我的腳下。這是無上的榮耀!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3563 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3563, 'zhTW', '是的，看到你我就想起來了，$N。你讓我想起往日的時光，我曾是部落的一名年輕的戰士。$B$B毫無疑問，你將在你的一生中游歷四方，征戰沙場。$B$B<高圖斯向你敬禮致意。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3564 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3564, 'zhTW', '謙虛點吧……或許現在是時候了，$N。$B$B你做好進入黑石要塞的準備了嗎?你做好發動一場戰爭，摧毀他們大本營的準備了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3565 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3565, 'zhTW', '我絕不會懷疑你的，$N。$B$B這些是給你的命令，$N。我知道你是不會讓我失望的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3566 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3566, 'zhTW', '啊,一個來訪者!肯定是一個冒險家，沒有多少遊客會走這條路的。坐下來喝一杯飲料吧，隨便些。嗨，你看起來好像還有些肉。你想參加比賽嗎?', '啊,一個來訪者!肯定是一個冒險家，沒有多少遊客會走這條路的。坐下來喝一杯飲料吧，隨便些。嗨，你看起來好像還有些肉。你想參加比賽嗎?', '啊一個來訪者!肯定是一個冒險家，沒有多少遊客會走這條路的。坐下來喝一杯飲料吧，隨便些。嗨，你看起來好像還有些肉。你想參加比賽嗎?', '啊一個來訪者!肯定是一個冒險家，沒有多少遊客會走這條路的。坐下來喝一杯飲料吧，隨便些。嗨，你看起來好像還有些肉。你想參加比賽嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3573 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3573, 'zhTW', '你好，年輕的$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3574 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3574, 'zhTW', '雷德，黑手之子:黑石氏族無能的酋長，同時也是剛愎自用的愚者。$B$B當第二次大戰結束時，雷德和他的兄弟麥姆逃往黑石塔的山城尋求避難所。雷德正是在那兒宣稱自己為苟延殘喘的黑石氏族大酋長。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3575 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3575, 'zhTW', '是的，年輕人，你不需要讓我相信這些事情，大酋長和我有很多過去的故事要說。然而你所做的貢獻是眾所周知的。$B$B就像我說的那樣，雷德已經為他的人民找到了新的家園，我也是那些不知疲倦跟隨他的人中的一員。$B$B那一次衝突激起了其他……其他無數的衝突。就是在黑石氏族和黑鐵矮人為了黑石塔的戰鬥中我的兩個兒子被殺害了。就在那時我意識到了我在黑石氏族的日子結束了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3576 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3576, 'zhTW', '我走了。我不屬於黑石。不，我的孩子不能白白死去。我不會在雷德這樣無能、熱衷於權力的瘋子手下做事的。$B$B我隱居在壁爐谷附近羅德隆的森林中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3577 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3577, 'zhTW', '<伊崔格笑了。>$B$B年輕人，世界並非總是這麼混亂不堪。那只是天譴軍團籠罩大地前的一段時間。在羅德隆的那些地方在成為瘟疫之地之前。$B$B就是在那裡索爾從死亡之中拯救了我，也是在那裡我加入了新的部落…但是我離題了。這是另外一個時期的事。是的，另外一個時期……或許…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3578 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3578, 'zhTW', '我想你會的。或許有一天你能將訊息傳給我的一個老朋友。我聽說他還在那片森林中。$B$B<伊崔格低下頭，好像在做祈禱。>$B$B雷德，是的……雷德和他的兄弟麥姆統治了黑石塔，與黑鐵矮人經常發生衝突。他們試圖將黑鐵矮人完全趕出城市的上層部分，但是只有在飛龍來到和麥姆死掉之後它才真正實現。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3579 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3579, 'zhTW', '事實上。奈法利安，死亡之翼的子嗣現在正統治著黑石塔。雷德受到龍的支配。$B$B只要你能設法穿過晉升大廳。$B$B<伊崔格嘆息著。>$B$B此外，只有受到黑龍尊敬的人才有特權進入。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3580 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3580, 'zhTW', '或許吧。年輕人，現在就出發吧。去找大酋長，他肯定會樂意知道你的發現的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3583 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3583, 'zhTW', '試煉谷能將最軟弱的新兵鍛鍊成一名合格的部落戰士。無法透過試煉者將被拋棄，獨自忍受驕陽的煎烤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3584 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3584, 'zhTW', '你好，$N。我是克羅諾穆，但是你可以叫我克羅米。我覺得叫我這個名字舒服些。$B$B現在─你問我是怎麼知道你的名字的?我是青銅龍軍團的一員，永遠與時間的消長相合。所以可以說我們以前遇到過，而且我們之後也還會再見面的。', '你好，$N。我是克羅諾穆，但是你可以叫我克羅米。我覺得叫我這個名字舒服些。$B$B現在─你問我是怎麼知道你的名字的?我是青銅龍軍團的一員，永遠與時間的消長相合。所以可以說我們以前遇到過，而且我們之後也還會再見面的。', '你好，$N。我是克羅諾穆，但是你可以叫我克羅米。我覺得叫我這個名字舒服些。$b$b現在─你問我是怎麼知道你的名字的?我是青銅龍的一員，永遠與時間的消長相合。你可以認為我們以前遇到過。到最後，我們還會再次遇到。$b$b我希望我的行為不會打擾你;雖然我有可能作為一個悲傷之地的哨兵被起訴，我還是選擇離開那個傷心的地方。', '你好，$N。我是克羅諾穆，但是你可以叫我克羅米。我覺得叫我這個名字舒服些。$B$B現在─你問我是怎麼知道你的名字的?我是青銅龍軍團的一員，永遠與時間的消長相合。你可以認為我們以前遇到過。到最後，我們還會再次遇到。$B$B我希望我的行為不會打擾你;雖然我有可能作為一個悲傷之地的哨兵被起訴，我還是選擇離開那個傷心的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3585 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3585, 'zhTW', '嗨，又見面了，$N。我感覺時間流仍處在強大力量的威脅之下。青銅龍軍團始終歡迎你不斷地提供幫助。$B$B雖然過去的事情已無法改變，但是將來卻變化莫測。你此刻做出的決定將改變未來。', '嗨，又見面了，$N。我感覺時間流仍處在強大力量的威脅之下。青銅龍軍團始終歡迎你不斷地提供幫助。$B$B雖然過去的事情已無法改變，但是將來卻變化莫測。你此刻做出的決定將改變未來。', '嗨，又見面了，$N。我感覺時間流仍處在強大力量的威脅之下。青銅龍始終歡迎你不斷地提供幫助。$b$b雖然過去的事情已無法改變，但是將來卻變化莫測。你此刻做出的決定將改變未來。', '嗨，又見面了，$N。我感覺時間流仍處在強大力量的威脅之下。青銅龍軍團始終歡迎你不斷地提供幫助。$B$B雖然過去的事情已無法改變，但是將來卻變化莫測。你此刻做出的決定將改變未來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3586 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3586, 'zhTW', '聽你的長輩的話，$N。要是你擁有強大的意志和熱情，就沒有不能控制的力量。', '聽你的長輩的話，$N。要是你擁有強大的意志和熱情，就沒有不能控制的力量。', '聽你的長輩的話，$N。要是你擁有強大的意志和熱情，就沒有不能控制的力量。', '聽你的長輩的話，$N。要是你擁有強大的意志和熱情，就沒有不能控制的力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3587 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3587, 'zhTW', '並不是所有的被遺忘者都屈從於希瓦娜斯的意志，$N。我們中的某些人士被真正的力量驅動的--我們為自己贏得的力量。', '並不是所有的被遺忘者都屈從於希瓦娜斯的意志，$N。我們中的某些人士被真正的力量驅動的--我們為自己贏得的力量。', '並不是所有的被遺忘者都屈從於希爾瓦娜斯的意志，$N。我們中的某些人士被真正的力量驅動的--我們為自己贏得的力量。', '並不是所有的被遺忘者都屈從於希瓦娜斯的意志，$N。我們中的某些人士被真正的力量驅動的--我們為自己贏得的力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3589 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3589, 'zhTW', '現在……不……是……最好的……時候，$N。我必須集中……精力。', '現在……不……是……最好的……時候，$N。我必須集中……精力。', '現在……不……是……最好的……時候，$N。我必須集中……精力。', '現在……不……是……最好的……時候，$N。我必須集中……精力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3590 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3590, 'zhTW', '你的使命一定意義非凡，$c，它需要你深入沼澤...', '你的使命一定意義非凡，$c，它需要你深入沼澤...', '你的使命一定意義非凡，$c，它需要你深入沼澤……', '你的使命一定意義非凡，$c，它需要你深入沼澤……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
