INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3868, 'zhTW', '你見過守夜人巴庫斯嗎?很勇敢...$B$B我想他是所有守夜人中最兇猛的一個。我懷疑他是否看到我就在周圍...', '你見過守夜人巴庫斯嗎?很勇敢...$B$B我想他是所有守夜人中最兇猛的一個。我懷疑他是否看到我就在周圍...', '你見過守夜人巴庫斯嗎?很勇敢……$b$b我想他是所有守夜人中最兇猛的一個。我懷疑他是否看到我就在周圍……', '你見過守夜人巴庫斯嗎?很勇敢……$B$B我想他是所有守夜人中最兇猛的一個。我懷疑他是否看到我就在周圍……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
