INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3873, 'zhTW', '謝謝你!你讓我自由了!', '謝謝你!你讓我自由了!', '謝謝你!你讓我自由了!', '謝謝你!你讓我自由了!', '謝謝你!你讓我自由了!', '謝謝你!你讓我自由了!', '謝謝你!你讓我自由了!', '謝謝你!你讓我自由了!', '啊！拜託你，如果你看到達隆郡的一名倖存者，告訴他們，我是自由的！', '啊！拜託你，如果你看到達隆郡的一名倖存者，告訴他們，我是自由的！', NULL, NULL, NULL, NULL, NULL, NULL);
