INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3874, 'zhTW', '翡翠議會試圖治癒費伍德森林受傷的大地。儘管這片大地是以腐蝕它的東西命名，我們還是希望有一天我們能從這片土地中將腐敗清除。', '翡翠議會試圖治癒費伍德森林受傷的大地。儘管這片大地是以腐蝕它的東西命名，我們還是希望有一天我們能從這片土地中將腐敗清除。', '翡翠議會試圖治癒費伍德森林受傷的大地。儘管這片大地是以腐蝕它的東西命名，我們還是希望有一天我們能從這片土地中將腐敗清除。', '翡翠議會試圖治癒費伍德森林受傷的大地。儘管這片大地是以腐蝕它的東西命名，我們還是希望有一天我們能從這片土地中將腐敗清除。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
