INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3893, 'zhTW', '嘖嘖，勇敢的$c!我有最訓練有素的狼來讓你挑選。你到哪裡都不會發現另一種動物有與狼同樣的耐力和生存本能!請你親自來檢視一下他們吧。', '嘖嘖，勇敢的$c!我有最訓練有素的狼來讓你挑選。你到哪裡都不會發現另一種動物有與狼同樣的耐力和生存本能!請你親自來檢視一下他們吧。', '你好，勇敢的$c！我有世界上最訓練有素的狼供你挑選。你到哪裡都不會發現能與狼擁有同樣的耐力和生存本能的動物！你親自來看看它們吧。', '嘖嘖，勇敢的$c!我有最訓練有素的狼來讓你挑選。你到哪裡都不會發現另一種動物有與狼同樣的耐力和生存本能!請你親自來檢視一下他們吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
