INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3942, 'zhTW', '承蒙月神的關照，我很高興給你在整個泰達希爾找到的最好的坐騎，甚至是這世上最好的--黑豹。數年來，哨兵部隊一直倚賴這些同伴的價值。$B$B抓緊時間，朋友，挑選一匹你滿意的。我敢肯定你不會失望的。', '承蒙月神的關照，我很高興給你在整個泰達希爾找到的最好的坐騎，甚至是這世上最好的--黑豹。數年來，哨兵部隊一直倚賴這些同伴的價值。$B$B抓緊時間，朋友，挑選一匹你滿意的。我敢肯定你不會失望的。', '承蒙月神的關照，我很高興給你在整個泰達希爾找到的最好的坐騎，甚至是這世上最好的--黑豹。數年來，哨兵部隊一直倚賴這些同伴的價值。$b$b抓緊時間，朋友，挑選一匹你滿意的。我敢肯定你不會失望的。', '承蒙月神的關照，我很高興給你在整個泰達希爾找到的最好的坐騎，甚至是這世上最好的--黑豹。數年來，哨兵部隊一直倚賴這些同伴的價值。$B$B抓緊時間，朋友，挑選一匹你滿意的。我敢肯定你不會失望的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
