INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3945, 'zhTW', '如果你是為獲得快速而安全的產品而來，那麼這兒就是你的目的地了!今年的機械陸行鳥模型已經到了，我將為你展示其效能!', '如果你是為獲得快速而安全的產品而來，那麼這兒就是你的目的地了!今年的機械陸行鳥模型已經到了，我將為你展示其效能!', '如果你是為獲得快速而安全的產品而來，那麼這兒就是你的目的地了!今年的機械陸行鳥模型已經到了，我將為你展示其效能!', '如果你是為獲得快速而安全的產品而來，那麼這兒就是你的目的地了!今年的機械陸行鳥模型已經到了，我將為你展示其效能!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
