INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3953, 'zhTW', '當一個鐵匠達到了你們專家工藝水準的時候，我會提供給他們一個選擇。$B$B雖然沒有要求你做出選擇，但建議你最好還是做出抉擇─畢竟，你想永遠的當一名新手嗎?是專家級的護甲鍛造師和武器鍛造師給我們軍隊提供補給，從而贏得戰爭的勝利並獲得稱讚!$B$B注意，$N。一旦做出了決定並完成了要求的任務--就沒有回頭路了。一個人只能沿一條路走到底。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
