INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3983, 'zhTW', '根據你提供的毒素樣本，我們認為你需要下面這些東西:一份秘法速化劑、四份魂能共振器和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的鬼魂或怨靈身上獲取魂能共振器!$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
