INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3996, 'zhTW', '天譴軍團帶來的災難還在這片區域蔓延，在扭轉局面，摧毀天譴軍團之前，我們要走的路還很長。收集必要的資源，盡力幫助我們吧!', '天譴軍團帶來的災難還在這片區域蔓延，在扭轉局面，摧毀天譴軍團之前，我們要走的路還很長。收集必要的資源，盡力幫助我們吧!', '天災軍團帶來的災難還在這片區域蔓延，在扭轉局面，摧毀天災軍團之前，我們要走的路還很長。收集必要的資源，盡力幫助我們吧!', '天譴軍團帶來的災難還在這片區域蔓延，在扭轉局面，摧毀天譴軍團之前，我們要走的路還很長。收集必要的資源，盡力幫助我們吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 3997 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (3997, 'zhTW', '天譴軍團帶來的災難就快結束;一場難以控制的顛覆行動會將我們推向頂峰!你務必要幫助我們!', '天譴軍團帶來的災難就快結束;一場難以控制的顛覆行動會將我們推向頂峰!你務必要幫助我們!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
