INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4042, 'zhTW', '當然，$g先生:小姐;。我們曾是巴羅夫家裡的僕人:現在那裡被稱作通靈學院。$B$B我那時是女僕的領班而盧希恩是主人巴羅夫的男管家。$B$B我們為巴羅夫家族工作了數十年，直到...$B$B<艾瓦哭了。>', '當然，$g先生:小姐;。我們曾是巴羅夫家裡的僕人:現在那裡被稱作通靈學院。$B$B我那時是女僕的領班而盧希恩是主人巴羅夫的男管家。$B$B我們為巴羅夫家族工作了數十年，直到...$B$B<艾瓦哭了。>', '當然，$g先生:小姐;。我們曾是巴羅夫家裡的僕人:現在那裡被稱作通靈學院。$b$b我那時是女僕的領班而盧森是主人巴羅夫的男管家。$b$b我們為巴羅夫家族工作了數十年，直到……$b$b<艾瓦哭了。>', '當然，$g先生:小姐;。我們曾是巴羅夫家裡的僕人:現在那裡被稱作通靈學院。$B$B我那時是女僕的領班而盧森是主人巴羅夫的男管家。$B$B我們為巴羅夫家族工作了數十年，直到……$B$B<艾瓦哭了。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
