INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4043, 'zhTW', '喔真是太可怕了，$g先生:小姐;。巴羅夫的家裡從前充滿生機...充滿活力。這個莊園是巴羅夫家族在他們遙遠的王國裡主要的住所。$B$B盧希恩和我注意到隨著時間的流逝，巴羅夫家族變得抑鬱而沮喪。偏執妄想和暴怒籠罩著男主人和女主人。在夜裡，我們能聽到巴羅夫家族在房裡爭吵。根據我們瞭解，他們的貪婪毀了他們，可以這麼說。', '喔真是太可怕了，$g先生:小姐;。巴羅夫的家裡從前充滿生機...充滿活力。這個莊園是巴羅夫家族在他們遙遠的王國裡主要的住所。$B$B盧希恩和我注意到隨著時間的流逝，巴羅夫家族變得抑鬱而沮喪。偏執妄想和暴怒籠罩著男主人和女主人。在夜裡，我們能聽到巴羅夫家族在房裡爭吵。根據我們瞭解，他們的貪婪毀了他們，可以這麼說。', '喔真是太可怕了，$g先生:小姐;。巴羅夫的家裡從前充滿生機……充滿活力。這個莊園是巴羅夫家族在他們遙遠的王國裡主要的住所。$b$b盧森和我注意到隨著時間的流逝，巴羅夫家族變得抑鬱而沮喪。偏執妄想和暴怒籠罩著男主人和女主人。在夜裡，我們能聽到巴羅夫家族在房裡爭吵。根據我們瞭解，他們的貪婪毀了他們，可以這麼說。', '喔真是太可怕了，$g先生:小姐;。巴羅夫的家裡從前充滿生機……充滿活力。這個莊園是巴羅夫家族在他們遙遠的王國裡主要的住所。$B$B盧森和我注意到隨著時間的流逝，巴羅夫家族變得抑鬱而沮喪。偏執妄想和暴怒籠罩著男主人和女主人。在夜裡，我們能聽到巴羅夫家族在房裡爭吵。根據我們瞭解，他們的貪婪毀了他們，可以這麼說。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
