INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4047, 'zhTW', '限制?這世上有些東西比柵欄和鐐銬更加能夠限制住人，年輕的$g主人:女主人;。亡靈包圍著我們，不斷用恐怖的動作折磨我們。$B$B最終，他來了。他自我介紹叫瑟爾林·卡斯迪諾夫教授。我們都把他叫做「屠夫。」', '限制?這世上有些東西比柵欄和鐐銬更加能夠限制住人，年輕的$g主人:女主人;。亡靈包圍著我們，不斷用恐怖的動作折磨我們。$B$B最終，他來了。他自我介紹叫瑟爾林·卡斯迪諾夫教授。我們都把他叫做「屠夫。」', '限制?這世上有些東西比柵欄和鐐銬更加能夠限制住人，年輕的$g主人:女主人;。亡靈包圍著我們，不斷用恐怖的動作折磨我們。$b$b最終，他來了。他自我介紹叫瑟爾林·卡斯迪諾夫教授。我們都把他叫做“屠夫。”', '限制?這世上有些東西比柵欄和鐐銬更加能夠限制住人，年輕的$g主人:女主人;。亡靈包圍著我們，不斷用恐怖的動作折磨我們。$B$B最終，他來了。他自我介紹叫瑟爾林·卡斯迪諾夫教授。我們都把他叫做“屠夫。”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
