INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4049, 'zhTW', '屠夫說起「無辜者的鮮血」和他的黑暗主人，「基爾圖諾斯」。以及他會如何滿足主人的慾望。$B$B最後，這個怪獸完成了他的實驗。我們被耗乾了生命。我們的靈魂被打碎了。死亡的甜美的擁抱靠近了，我們張開雙臂歡迎它。但是在他極端的殘酷中，屠夫把我們從死亡之門中復活。$B$B我們要被活著扔進他貪婪的食屍鬼之中。他笑著看我們被魔鬼吞噬。', '屠夫說起「無辜者的鮮血」和他的黑暗主人，「基爾圖諾斯」。以及他會如何滿足主人的慾望。$B$B最後，這個怪獸完成了他的實驗。我們被耗乾了生命。我們的靈魂被打碎了。死亡的甜美的擁抱靠近了，我們張開雙臂歡迎它。但是在他極端的殘酷中，屠夫把我們從死亡之門中復活。$B$B我們要被活著扔進他貪婪的食屍鬼之中。他笑著看我們被魔鬼吞噬。', '屠夫說起“無辜者的鮮血”和他的黑暗主人，“基爾圖諾斯”。以及他會如何滿足主人的慾望。$b$b最後，這個怪獸完成了他的實驗。我們被耗幹了生命。我們的靈魂被打碎了。死亡的甜美的擁抱靠近了，我們張開雙臂歡迎它。但是在他極端的殘酷中，屠夫把我們從死亡之門中復活。$b$b我們要被活著扔進他貪婪的食屍鬼之中。他笑著看我們被魔鬼吞噬。', '屠夫說起“無辜者的鮮血”和他的黑暗主人，“基爾圖諾斯”。以及他會如何滿足主人的慾望。$B$B最後，這個怪獸完成了他的實驗。我們被耗幹了生命。我們的靈魂被打碎了。死亡的甜美的擁抱靠近了，我們張開雙臂歡迎它。但是在他極端的殘酷中，屠夫把我們從死亡之門中復活。$B$B我們要被活著扔進他貪婪的食屍鬼之中。他笑著看我們被魔鬼吞噬。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
