INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4050, 'zhTW', '我們什麼都沒感覺到。我們的靈魂在這裡，在地獄。在找到我們的屍體並讓靈魂安息之前我們不能離開。', '我們什麼都沒感覺到。我們的靈魂在這裡，在地獄。在找到我們的屍體並讓靈魂安息之前我們不能離開。', '我們什麼都沒感覺到。我們的靈魂在這裡，在地獄。在找到我們的屍體並讓靈魂安息之前我們不能離開。', '我們什麼都沒感覺到。我們的靈魂在這裡，在地獄。在找到我們的屍體並讓靈魂安息之前我們不能離開。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
