INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4052, 'zhTW', '在北方的雷霆崖，有一名雙足飛龍管理員。乘坐升降梯到達雷霆崖頂部，問問那兒的守衛，他們會為你指明方向的。', '在北方的雷霆崖，有一名雙足飛龍管理員。乘坐升降梯到達雷霆崖頂部，問問那兒的守衛，他們會為你指明方向的。', '在北方的雷霆崖，有一名雙足飛龍管理員。乘坐升降梯到達雷霆崖頂部，問問那兒的守衛，他們會為你指明方向的。', '在北方的雷霆崖，有一名雙足飛龍管理員。乘坐升降梯到達雷霆崖頂部，問問那兒的守衛，他們會為你指明方向的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
