INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4092, 'zhTW', '蘭德·洛巴爾特相當擅長剝夜行蝙蝠這類動物的皮。你可以在往布瑞爾東南角沿途的某個營帳中找到他。沿著城鎮東南方的道路走，然後在十字路口向東轉。', '蘭德·洛巴爾特相當擅長剝夜行蝙蝠這類動物的皮。你可以在往布瑞爾東南角沿途的某個營帳中找到他。沿著城鎮東南方的道路走，然後在十字路口向東轉。', '蘭德·洛巴爾特相當擅長剝夜行蝙蝠這類動物的皮。你可以在往布瑞爾東南角沿途的某個營帳中找到他。沿著城鎮東南方的道路走，然後在十字路口向東轉。', '蘭德·洛巴爾特相當擅長剝夜行蝙蝠這類動物的皮。你可以在往布瑞爾東南角沿途的某個營帳中找到他。沿著城鎮東南方的道路走，然後在十字路口向東轉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
