INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4113, 'zhTW', '你已經為我做了很多事情，$N。謝謝你。$B$B現在我至少可以告訴你，我是怎麼來到這裡的。我和我的好朋友特雷·萊弗治潛入加德納爾調查暗影議會，然後就在毫無準備的情況下被他們抓住了。他們把特雷帶到暗影堡的深處，並把我關在這裡，他們把我們所有的裝備都拿走了……我仍然可以聽到他的慘叫，$n。他們……簡直喪心病狂。我不知道他們都對他做了些什麼，但他們會為此付出代價的。', '你已經為我做了很多事情，$N。謝謝你。$B$B現在我至少可以告訴你，我是怎麼來到這裡的。我和我的好朋友特雷·萊弗治潛入加德納爾調查暗影議會，然後就在毫無準備的情況下被他們抓住了。他們把特雷帶到暗影堡的深處，並把我關在這裡，他們把我們所有的裝備都拿走了……我仍然可以聽到他的慘叫，$n。他們……簡直喪心病狂。我不知道他們都對他做了些什麼，但他們會為此付出代價的。', '你已經為我做了很多事情，$N。謝謝你。$B$B現在我至少可以告訴你，我是怎麼來到這裡的。我和我的好朋友特雷·萊弗治潛入加德納爾調查暗影議會，然後就在毫無準備的情況下被他們抓住了。他們把特雷帶到暗影堡的深處，並把我關在這裡，他們把我們所有的裝備都拿走了……我仍然可以聽到他的慘叫，$n。他們……簡直喪心病狂。我不知道他們都對他做了些什麼，但他們會為此付出代價的。', '你已經為我做了很多事情，$N。謝謝你。$B$B現在我至少可以告訴你，我是怎麼來到這裡的。我和我的好朋友特雷·萊弗治潛入加德納爾調查暗影議會，然後就在毫無準備的情況下被他們抓住了。他們把特雷帶到暗影堡的深處，並把我關在這裡，他們把我們所有的裝備都拿走了……我仍然可以聽到他的慘叫，$n。他們……簡直喪心病狂。我不知道他們都對他做了些什麼，但他們會為此付出代價的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4114 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4114, 'zhTW', '當你檢查牢籠和關在裡面的夜精靈時，你有一種奇怪的似曾相識的感覺。不知為什麼原因，她的目光從未與你接觸─好像你對她來說並不存在一樣。', '當你檢查牢籠和關在裡面的夜精靈時，你有一種奇怪的似曾相識的感覺。不知為什麼原因，她的目光從未與你接觸─好像你對她來說並不存在一樣。', '當你檢查牢籠和關在裡面的夜精靈時，你有一種奇怪的似曾相識的感覺。不知為什麼原因，她的目光從未與你接觸——好像你對她來說並不存在一樣。', '當你檢查牢籠和關在裡面的夜精靈時，你有一種奇怪的似曾相識的感覺。不知為什麼原因，她的目光從未與你接觸─好像你對她來說並不存在一樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4117 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4117, 'zhTW', '他們並未意識到自己已經死了，$r。他們受到詛咒，在頭腦中保留了這個城鎮被毀滅之前的記憶，大部分是這樣，還有一部分人更為不幸。$B$B你認為是天譴軍團所為?那時天譴軍團還不存在呢，就算是它們的話，我們也會與它們展開一場惡戰的。$B$B不，這場恐怖而極具破壞性的瘟疫源於通靈學院，它摧毀了整座城鎮，無人生還。$B$B讓我獨自承受這悲傷吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4118 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4118, 'zhTW', '你沒看到我們正在準備迎接烏瑟的訪問嗎?現在別妨礙我，我有許多工作要做!', NULL, '你沒看到我們正在準備迎接烏瑟的訪問嗎?現在別妨礙我，我有許多工作要做!', NULL, '你沒看到我們正在準備迎接烏瑟的訪問嗎?現在別妨礙我，我有許多工作要做!', NULL, '你沒看到我們正在準備迎接烏瑟的訪問嗎?現在別妨礙我，我有許多工作要做!', NULL, '我們美麗的島嶼上的另一個可愛的一天。', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4119 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4119, 'zhTW', '小心點，陌生人。別在我們的鎮子裡惹事。', NULL, '小心點，陌生人。別在我們的鎮子裡惹事。', NULL, '小心點，陌生人。別在我們的鎮子裡惹事。', NULL, '小心點，陌生人。別在我們的鎮子裡惹事。', NULL, '在凱爾達隆不允許遊蕩，乞討，罵，打架，或任何你想做的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4122 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4122, 'zhTW', '詛咒神教正在迅速壯大。從小型村落到首都，從部落到聯盟，幾乎每座城鎮的居民中都有詛咒神教的信徒。$B$B別驚訝，他們只在儀式和慶典上面才身穿統一的服飾。你很可能已經跟他們的信徒碰過面了，只是你不知道而已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4123 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4123, 'zhTW', '是嗎?這是他們一貫的操作手法。對科爾蘇加德和快速增長的天譴軍團軍隊來說，什麼東西擁有更大的價值?一個能成功潛入某個組織，然後釋放瘟疫使數千人喪命的狂熱追隨者，還是一個普通到掉渣的亡靈士兵?很明顯你不是那麼愚蠢。$B$B沒錯，$r，他們就在你周圍，生活著，工作著，密謀著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4124 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4124, 'zhTW', '停下來─不。放慢速度─或許這樣比較好。$B$B通靈學院是他們接受初級訓練和教育的地方。信徒們從那兒走出來，並最終進入我們的社會。$B$B這就是我們必須攻破通靈學院的原因。它是詛咒神教的中心!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4125 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4125, 'zhTW', '放慢速度，$r。你要殺的人已經死了，對著屍體狂砍是無濟於事的。可以真正摧毀殭屍的方法極少，而且你我也無法使用這些方法。為此，我制定了一項計畫，這項計畫將對詛咒神教產生巨大的影響。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4126 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4126, 'zhTW', '這很簡單，真的。從萊斯·霜語的身上奪走他的力量。將他變回普通的形態，然後果斷地殺死他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4127 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4127, 'zhTW', '啊，我想我說得太快了。萊斯·霜語是通靈學院的監督者，他負責訓練所有的黑暗大師，他是科爾蘇加德最欣賞的學生和副官。他曾經是激流堡的法師，一個從來沒有接受過達拉然正規訓練的流浪巫師。$B$B當科爾蘇加德開設詛咒神教的時候，萊斯就是首批加入其中的人，因為他知道透過黑暗魔法可以獲得不朽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4128 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4128, 'zhTW', '他真的獲得了不朽之身。他很快從眾多信徒中脫穎而出，巫妖王隨即授予了他永生的權力。巫妖萊斯·霜語因此而誕生。$B$B你明白嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4129 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4129, 'zhTW', '很好。為了實現我們的計畫，我們必須首先製造一塊生命徽章。你準備好了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4130 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4130, 'zhTW', '有人沒有受到記憶的折磨。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
