INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4134, 'zhTW', '很高興見到你，朋友。我是軍官加魯什，是銀色黎明這個世界性組織的驕傲成員。我們的任務是毫不留情地消滅艾澤拉斯大陸上所有邪惡的勢力。銀色黎明不是一個政治機構，我們也不願意成為政府機構。我們的目標很簡單，我們將部落和聯盟都看作自己的朋友─以剷除邪惡為目標的朋友!$B$B我的$g兄弟:姐妹;，為了黎明而戰!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4135 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4135, 'zhTW', '你好，朋友。我是軍官普爾哈特，隸屬於銀色黎明這個世界性的組織。我們的目標非常簡單─與艾澤拉斯的一切邪惡力量進行頑強而持久的戰鬥。我們不是一個政治團體，也不想成為那樣的團體。為了銀色黎明的偉大目標，我們將聯盟和部落的成員都當作並肩作戰的朋友來看待!$B$B為了黎明而戰，我的$g兄弟:姐妹;!', '你好，朋友。我是軍官普爾哈特，隸屬於銀色黎明這個世界性的組織。我們的目標非常簡單─與艾澤拉斯的一切邪惡力量進行頑強而持久的戰鬥。我們不是一個政治團體，也不想成為那樣的團體。為了銀色黎明的偉大目標，我們將聯盟和部落的成員都當作並肩作戰的朋友來看待!$B$B為了黎明而戰，我的$g兄弟:姐妹;!', '你好，朋友。我是普爾哈特，隸屬於銀色黎明這個世界性的組織。我們的目標非常簡單——與艾澤拉斯的一切邪惡力量進行頑強而持久的戰鬥。我們不是一個政治團體，也不想成為那樣的團體。為了銀色黎明的偉大目標，我們將聯盟和部落的成員都當作並肩作戰的朋友來看待!$B$B為了黎明而戰，我的$G兄弟:姐妹;!', '你好，朋友。我是軍官普爾哈特，隸屬於銀色黎明這個世界性的組織。我們的目標非常簡單─與艾澤拉斯的一切邪惡力量進行頑強而持久的戰鬥。我們不是一個政治團體，也不想成為那樣的團體。為了銀色黎明的偉大目標，我們將聯盟和部落的成員都當作並肩作戰的朋友來看待!$B$B為了黎明而戰，我的$g兄弟:姐妹;!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
