INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4173, 'zhTW', '銀色黎明向你致敬，$c。我是哈薩娜─銀色黎明為數不多經過授權的裝備和軍品軍需官之一。$B$B既然你在我們委任下作戰─同時贏得我們的尊敬和信任─你會從加魯什軍官那裡得到英勇勳章。它們有兩個作用:在我們的隊伍中贏得地位，或者作為交換得到某些特殊物品。$B$B隨著你在銀色黎明地位的升高，你會發現你能夠得到更多物品。', '銀色黎明向你致敬，$c。我是哈薩娜─銀色黎明為數不多經過授權的裝備和軍品軍需官之一。$B$B既然你在我們委任下作戰─同時贏得我們的尊敬和信任─你會從加魯什軍官那裡得到英勇勳章。它們有兩個作用:在我們的隊伍中贏得地位，或者作為交換得到某些特殊物品。$B$B隨著你在銀色黎明地位的升高，你會發現你能夠得到更多物品。', '銀色黎明向你致敬，$c。我是哈薩娜─銀色黎明為數不多經過授權的裝備和軍品軍需官之一。\n\n既然你在我們委任下作戰─同時贏得我們的尊敬和信任─你會從加魯什軍官那裡得到英勇勳章。它們有兩個作用:在我們的隊伍中贏得地位，或者作為交換得到某些特殊物品。\n\n隨著你在銀色黎明地位的升高，你會發現你能夠得到更多物品。', '銀色黎明向你致敬，$c。我是哈薩娜─銀色黎明為數不多經過授權的裝備和軍品軍需官之一。$B$B既然你在我們委任下作戰─同時贏得我們的尊敬和信任─你會從加魯什軍官那裡得到英勇勳章。它們有兩個作用:在我們的隊伍中贏得地位，或者作為交換得到某些特殊物品。$B$B隨著你在銀色黎明地位的升高，你會發現你能夠得到更多物品。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
