INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4193, 'zhTW', '銀色黎明向你致敬，$c!我叫萊斯巴克，是銀色黎明委派的裝備和物資軍需官。$B$B當你接受任命，同邪惡力量作戰時 - 以此搏取得我們的尊重和信任 - 你會從軍官普爾哈特那兒獲得勇氣勳章。勳章有兩個用途:可增加自己的聲望，或是用於獲取特殊物品。$B$B隨著你在銀色黎明中地位的提高，你會發現有更多的物品能讓你挑選。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4194 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4194, 'zhTW', '加入對抗邪惡的戰鬥中吧!今天就去獲得銀色黎明的委任徽章吧!', '加入對抗邪惡的戰鬥中吧!今天就去獲得銀色黎明的委任徽章吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4213 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4213, 'zhTW', '你好，$c。我是軍需官米蘭達·布利洛克─銀色軍團為數不多的授權裝備和軍品軍需官之一。$B$B既然你在我們的委任下與邪惡戰鬥─同時贏得我們的尊敬和信任─你會從瑟倫霍夫公爵那裡得到勇氣勳章。勳章有兩個作用:用他們贏得在軍隊中更高的地位，或者作為交換得到特殊物品。$B$B隨著你在軍團中地位的升高，你會發現你會有更多的物品。', '你好，$c。我是軍需官米蘭達·布利洛克─銀色軍團為數不多的授權裝備和軍品軍需官之一。$B$B既然你在我們的委任下與邪惡戰鬥─同時贏得我們的尊敬和信任─你會從瑟倫霍夫公爵那裡得到勇氣勳章。勳章有兩個作用:用他們贏得在軍隊中更高的地位，或者作為交換得到特殊物品。$B$B隨著你在軍團中地位的升高，你會發現你會有更多的物品。', '你好，$c。我是軍需官米蘭達·布利洛克——銀色軍團為數不多的授權裝備和軍品軍需官之一。$B$B既然你在我們的委任下與邪惡戰鬥——同時贏得我們的尊敬和信任——你會從尼古拉斯·瑟倫霍夫公爵那裡得到勇氣勳章。勳章有兩個作用：用他們贏得在軍隊中更高的地位，或者作為交換得到特殊物品。$B$B隨著你在軍團中地位的升高，你會發現你會有更多的物品。', '你好，$c。我是軍需官米蘭達·布利洛克─銀色軍團為數不多的授權裝備和軍品軍需官之一。$B$B既然你在我們的委任下與邪惡戰鬥─同時贏得我們的尊敬和信任─你會從瑟倫霍夫公爵那裡得到勇氣勳章。勳章有兩個作用:用他們贏得在軍隊中更高的地位，或者作為交換得到特殊物品。$B$B隨著你在軍團中地位的升高，你會發現你會有更多的物品。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4233 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4233, 'zhTW', '你好，$c。$B$B那邊的哨兵允許我住在他們的營地，只要我答應不會再有麻煩了─我敢肯定你能意識到對外交的需要，是嗎?$B$B我來調查這片土地的紊亂狀況，既然這也有助於他們的事業，他們同意我在這裡 只能協助艾澤拉斯各族之間脆弱的聯盟關係。如果你想幫我，那麼我會很感激，但無論如何，請不要引起任何麻煩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4253 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4253, 'zhTW', '歡迎來到鋼架補給站!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4254 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4254, 'zhTW', '種族並不代表榮譽，$r。只要你待在我的農場，就請你記住並尊重這個信條。$B$B我知道有些獸人，他們像最高貴的騎士那樣可敬;我還知道有些人類，他們像最殘忍的天譴軍團那樣邪惡。$B$B但是我不會拿我少年時的故事來煩你的!要做的事情還很多─如果那是你所期望的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4258 AND `Locale` = 'zhTW';
