INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4295, 'zhTW', '哦……一個聖騎士?嗯，$g小夥子:姑娘;，你真走運!阿札爾·戰錘剛結束訓練，他現在在卡拉諾斯的雷酒釀製廠。', '哦……一個聖騎士?嗯，$g小夥子:姑娘;，你真走運!阿札爾·戰錘剛結束訓練，他現在在卡拉諾斯的雷酒釀製廠。', '哦……一個聖騎士?嗯，$g小夥子:姑娘;，你真走運!阿札爾·戰錘剛結束訓練，他現在在卡拉諾斯的雷酒釀製廠。', '哦……一個聖騎士?嗯，$g小夥子:姑娘;，你真走運!阿札爾·戰錘剛結束訓練，他現在在卡拉諾斯的雷酒釀製廠。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
