INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4296, 'zhTW', '哦，是牧師嗎?要是你想接受訓練的話，就去雷酒釀製廠找馬克薩恩吧，他一定在那兒喝酒呢。', '哦，是牧師嗎?要是你想接受訓練的話，就去雷酒釀製廠找馬克薩恩吧，他一定在那兒喝酒呢。', '哦，是牧師嗎?要是你想接受訓練的話，就去雷酒釀製廠找馬克薩恩吧，他一定在那兒喝酒呢。', '哦，是牧師嗎?要是你想接受訓練的話，就去雷酒釀製廠找馬克薩恩吧，他一定在那兒喝酒呢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
