INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4297, 'zhTW', '那麼，似乎我們都是來找霍格拉爾·巴坎的。他是個矮人，所以他遲早都會去雷酒釀酒廠喝酒的 -- 說不定他現在已經在那兒了。', '那麼，似乎我們都是來找霍格拉爾·巴坎的。他是個矮人，所以他遲早都會去雷酒釀酒廠喝酒的 -- 說不定他現在已經在那兒了。', '那麼，似乎我們都是來找霍格拉爾·巴坎的。他是個矮人，所以他遲早都會去雷酒釀酒廠喝酒的 -- 說不定他現在已經在那兒了。', '那麼，似乎我們都是來找霍格拉爾·巴坎的。他是個矮人，所以他遲早都會去雷酒釀酒廠喝酒的 -- 說不定他現在已經在那兒了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
