INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4298, 'zhTW', '術士……我可不在乎他們。就像那個在雷酒釀製廠外開設商店的吉姆瑞茲。都是他，那兒的麥芽酒可能都跑了氣!術士……呸!', '術士……我可不在乎他們。就像那個在雷酒釀製廠外開設商店的吉姆瑞茲。都是他，那兒的麥芽酒可能都跑了氣!術士……呸!', '術士……我可不在乎他們。就像那個在雷酒釀製廠外開設商店的吉姆瑞茲。都是他，那兒的麥芽酒可能都跑了氣!術士……呸!', '術士……我可不在乎他們。就像那個在雷酒釀製廠外開設商店的吉姆瑞茲。都是他，那兒的麥芽酒可能都跑了氣!術士……呸!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
