INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4302, 'zhTW', '哦!這是一項極有價值的技能。託格努斯以你從未見過的方式敲擊鐵砧。為什麼你不去跟他談談，看看他能教你什麼?', '哦!這是一項極有價值的技能。託格努斯以你從未見過的方式敲擊鐵砧。為什麼你不去跟他談談，看看他能教你什麼?', '哦!這是一項極有價值的技能。託格努斯以你從未見過的方式敲擊鐵砧。為什麼你不去跟他談談，看看他能教你什麼?', '哦!這是一項極有價值的技能。託格努斯以你從未見過的方式敲擊鐵砧。為什麼你不去跟他談談，看看他能教你什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
