INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4303, 'zhTW', '一瓶雷酒牌麥芽酒外加格雷姆羅克做的菜就足以讓你飽餐一頓。如果你想成為一名廚師的話，就該去參加他的培訓。', '一瓶雷酒牌麥芽酒外加格雷姆羅克做的菜就足以讓你飽餐一頓。如果你想成為一名廚師的話，就該去參加他的培訓。', '一瓶雷酒牌麥芽酒外加格雷姆羅克做的菜就足以讓你飽餐一頓。如果你想成為一名廚師的話，就該去參加他的培訓。', '一瓶雷酒牌麥芽酒外加格雷姆羅克做的菜就足以讓你飽餐一頓。如果你想成為一名廚師的話，就該去參加他的培訓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
