INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4305, 'zhTW', '你應該去鋼架補給站找布隆克。當他不忙著修補一些奇怪裝置的時候，他通常就在跟飛行員們聊些關於他們的蒸汽坦克的事。', '你應該去鋼架補給站找布隆克。當他不忙著修補一些奇怪裝置的時候，他通常就在跟飛行員們聊些關於他們的蒸汽坦克的事。', '你應該去鋼架補給站找布隆克。當他不忙著修補一些奇怪裝置的時候，他通常就在跟飛行員們聊些關於他們的蒸汽坦克的事。', '你應該去鋼架補給站找布隆克。當他不忙著修補一些奇怪裝置的時候，他通常就在跟飛行員們聊些關於他們的蒸汽坦克的事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
