INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4306, 'zhTW', '急救雖然不能代替牧師的治療，但是它在緊要關頭卻很方便。我建議你去跟雷酒釀製廠的薩姆諾談談，併力所能及地學習一些東西。', '急救雖然不能代替牧師的治療，但是它在緊要關頭卻很方便。我建議你去跟雷酒釀製廠的薩姆諾談談，併力所能及地學習一些東西。', '急救雖然不能代替牧師的治療，但是它在緊要關頭卻很方便。我建議你去跟雷酒釀製廠的薩姆諾談談，併力所能及地學習一些東西。', '急救雖然不能代替牧師的治療，但是它在緊要關頭卻很方便。我建議你去跟雷酒釀製廠的薩姆諾談談，併力所能及地學習一些東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
