INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4308, 'zhTW', '有些弱小的植物竟然能在丹莫洛的寒風中開花，這真令人驚奇……但是這兒沒有草藥師。你得去鐵爐堡接受草藥學的訓練。', '有些弱小的植物竟然能在丹莫洛的寒風中開花，這真令人驚奇……但是這兒沒有草藥師。你得去鐵爐堡接受草藥學的訓練。', '有些弱小的植物竟然能在丹莫洛的寒風中開花，這真令人驚奇……但是這兒沒有草藥師。你得去鐵爐堡接受草藥學的訓練。', '有些弱小的植物竟然能在丹莫洛的寒風中開花，這真令人驚奇……但是這兒沒有草藥師。你得去鐵爐堡接受草藥學的訓練。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
