INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4333, 'zhTW', '奧拉密斯湖近來遭受襲擊，所有的漁夫都已經搬遷到達納蘇斯了。你應該去那兒看看。', '奧拉密斯湖近來遭受襲擊，所有的漁夫都已經搬遷到達納蘇斯了。你應該去那兒看看。', '奧拉密斯湖近來遭受襲擊，所有的漁夫都已經搬遷到達納蘇斯了。你應該去那兒看看。', '奧拉密斯湖近來遭受襲擊，所有的漁夫都已經搬遷到達納蘇斯了。你應該去那兒看看。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
