INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4334, 'zhTW', '不知道瑪洛尼是如何採集到那些最為嬌嫩的草藥的。顯然你得向他多多學習。他就住在多蘭納爾的旅店東邊。', '不知道瑪洛尼是如何採集到那些最為嬌嫩的草藥的。顯然你得向他多多學習。他就住在多蘭納爾的旅店東邊。', '不知道瑪洛尼是如何採集到那些最為嬌嫩的草藥的。顯然你得向他多多學習。他就住在多蘭納爾的旅店東邊。', '不知道瑪洛尼是如何採集到那些最為嬌嫩的草藥的。顯然你得向他多多學習。他就住在多蘭納爾的旅店東邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4335 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4335, 'zhTW', '納迪婭·織發離開自己的家園前往達納蘇斯進修去了。她精通制皮，而且是一名優秀的老師。你該去向她求教。', '納迪婭·織發離開自己的家園前往達納蘇斯進修去了。她精通制皮，而且是一名優秀的老師。你該去向她求教。', '納迪婭·織發離開自己的家園前往達納蘇斯進修去了。她精通制皮，而且是一名優秀的老師。你該去向她求教。', '納迪婭·織發離開自己的家園前往達納蘇斯進修去了。她精通制皮，而且是一名優秀的老師。你該去向她求教。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
