INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4355, 'zhTW', '你……你好，$N。對不起，我正從傷勢中恢復過來。$B$B那些血色十字軍比我料想的要兇猛的多。他們幾乎在裡面幹掉了我。$B$B你也應該多加小心。我不願看到他們先發制人。', '你……你好，$N。對不起，我正從傷勢中恢復過來。$B$B那些血色十字軍比我料想的要兇猛的多。他們幾乎在裡面幹掉了我。$B$B你也應該多加小心。我不願看到他們先發制人。', '你……你好，$N。對不起，我正從傷勢中恢復過來。$b$b那些血色十字軍比我料想的要兇猛的多。他們幾乎在裡面幹掉了我。$b$b你也應該多加小心。我不願看到他們先發制人。', '你……你好，$N。對不起，我正從傷勢中恢復過來。$B$B那些血色十字軍比我料想的要兇猛的多。他們幾乎在裡面幹掉了我。$B$B你也應該多加小心。我不願看到他們先發制人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
