INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4356, 'zhTW', '我的家人過去在北山伐木場工作，那裡現在被稱作西瘟疫之地。他們曾忠於杜馬家族，而現在血色十字軍把一切連同壁爐谷全都佔領了!$B$B在把那些狂熱分子從艾澤拉斯驅逐出去之前，我是不會停止行動的。', '我的家人過去在北山伐木場工作，那裡現在被稱作西瘟疫之地。他們曾忠於杜馬家族，而現在血色十字軍把一切連同壁爐谷全都佔領了!$B$B在把那些狂熱分子從艾澤拉斯驅逐出去之前，我是不會停止行動的。', '我的家人過去在北山伐木場工作，那裡現在被稱作西瘟疫之地。他們曾忠於杜馬家族，而現在血色十字軍把一切連同壁爐谷全都佔領了!$b$b在把那些狂熱分子從艾澤拉斯驅逐出去之前，我是不會停止行動的。', '我的家人過去在北山伐木場工作，那裡現在被稱作西瘟疫之地。他們曾忠於杜馬家族，而現在血色十字軍把一切連同壁爐谷全都佔領了!$B$B在把那些狂熱分子從艾澤拉斯驅逐出去之前，我是不會停止行動的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4357 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4357, 'zhTW', '很久以前，跟獸人的第一次大戰還沒爆發的時候，北山伐木場是我父親在經營的。伐木場是他的生命，而他也樂在其中。後來戰爭爆發了，雖然百般不願意，我們還是得逃到暴風城去避難。$B$B如今天譴軍離開了，血色十字軍也逃走了...北山伐木場總算又是我們的了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4393 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4393, 'zhTW', '我們是熊怪家族僅剩的成員了...木喉部族還未墮落，但是其他部族對我們懷有相同的敵意;有熊怪能免於墮落...很多人都認為這是不可能的...$B$B我的兄弟們對那麼急於與我們為敵的傢伙非常生氣，現在他們已經開始攻擊任何靠近我們的生物;他們誰都不信任。$B$B但是，如何你能努力證明想要和他們和平相處的話，他們或許會把你當作盟友的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4394 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4394, 'zhTW', '你必須想辦法來證明你們兩個是在同一條戰線上的。儘管現在木喉可能會攻擊你，但如果你夠勤奮的話，你就會找到辦法的。$B$B你一定要記住，任何對木喉熊怪的攻擊都會大大降低你們贏得與他們結盟的機會。$B$B有個不錯的著手點就是在費伍德森林的許多部分都發現的死木熊怪。這些熊怪是木喉部族的敵人，殺了他們將會大大提高你在木喉中的地位。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4395 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4395, 'zhTW', '我們能讓你安全透過這兒，但是，你得證明自己值得我們給予幫助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4396 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4396, 'zhTW', '居住在冬泉谷的冬泉熊怪曾經是我們的盟友……但是有一天，這一切都改變了。$B$B他們聽從酋長的號令，開始攻擊他們接觸到的任何生物，包括我們的部族。他們現在幾乎不與外界接觸了……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4398 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4398, 'zhTW', '我只信任你所在種族中的少數人，$N。但是我把你當朋友。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4399 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4399, 'zhTW', '是的，是的。我看到你了。$B$B在去找你的路上。你可能已經贏得了一些人的信任，但要向我證明可並不僅僅如此!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4401 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4401, 'zhTW', '如果你能證明自己是個真正的盟友，我或許會考慮訓練你的...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
