INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4445, 'zhTW', '安靜!你沒聽見主人在講話嗎?', '安靜!你沒聽見主人在講話嗎?', '安靜!你沒聽見主人在講話嗎?', '安靜!你沒聽見主人在講話嗎?', '安靜!你沒聽見主人在講話嗎?', '安靜!你沒聽見主人在講話嗎?', '安靜!你沒聽見主人在講話嗎?', '安靜!你沒聽見主人在講話嗎?', '你忘記自己的學生服了嗎?你認為時尚比天譴軍團的統治更重要嗎?', '你忘記自己的學生服了嗎?你認為時尚比天譴軍團的統治更重要嗎?', '你完成了昨天的作業嗎?要是完成了，就過來跟我坐一塊吧！', '你完成了昨天的作業嗎?要是完成了，就過來跟我坐一塊吧！', '小心點，$g男孩:女孩;。主人能洞察一切……', '小心點，$g男孩:女孩;。主人能洞察一切……', '你帶來了課本嗎?我能和你一起看嗎?', '你帶來了課本嗎?我能和你一起看嗎?');
