INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4517, 'zhTW', '透過千百次的錘鍊，伊琳尼雅·月火已經掌握了若干種武器的使用方法，現在她為別人提供訓練。如果你想接受訓練的話，就去戰士區找她吧。', '透過千百次的錘鍊，伊琳尼雅·月火已經掌握了若干種武器的使用方法，現在她為別人提供訓練。如果你想接受訓練的話，就去戰士區找她吧。', '透過千百次的錘鍊，伊琳尼雅·月火已經掌握了若干種武器的使用方法，現在她為別人提供訓練。如果你想接受訓練的話，就去戰士區找她吧。', '透過千百次的錘鍊，伊琳尼雅·月火已經掌握了若干種武器的使用方法，現在她為別人提供訓練。如果你想接受訓練的話，就去戰士區找她吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
