INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4518, 'zhTW', '比克斯和布里維夫的武器沾滿了獸人的鮮血。如果你想學習的話，就去密林武器店找他們吧。', '比克斯和布里維夫的武器沾滿了獸人的鮮血。如果你想學習的話，就去密林武器店找他們吧。', '比克斯和布里維夫的武器沾滿了獸人的鮮血。如果你想學習的話，就去密林武器店找他們吧。', '比克斯和布里維夫的武器沾滿了獸人的鮮血。如果你想學習的話，就去密林武器店找他們吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
