INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4521, 'zhTW', '你要找的阿基巴德在戰爭區內環的武器商店外。', '你要找的阿基巴德在戰爭區內環的武器商店外。', '你要找的阿基巴德在戰爭區內環的武器商店外。', '你要找的阿基巴德在戰爭區內環的武器商店外。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4522 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4522, 'zhTW', '我得向你解釋，我們的敵人能安然地潛伏在我們的眼皮底下。$B$B首先要記住這一點:我們的敵人是暗影議會。無論我給你什麼任務，或許無論我讓你與誰對抗，你都必須明瞭這個事實。$B$B議會擁有許多信徒，但是其行動資訊絕對不會透露給愚蠢的信徒。$B$B像燃刃、阿古斯覺醒和灼刃都是議會的工具。他們是一夥的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4533 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4533, 'zhTW', '啊，是我們的人。很高興看到我們的隊伍增長如此迅速，以至於我都記不清每個人的容貌了。$B$B索爾那個傻子認為我正努力改善術士的形象併為他服務呢。白痴!燃燒軍團在耗盡這世界的資源後會將它化為灰燼的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4534 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4534, 'zhTW', '天真的傻子。燃刃就是暗影議會!議會擁有許多信徒和組織，但是他們都服從於議會的意願。我或許能領導燃刃，但是我無非是議會手下的一名爪牙，就像你是我的爪牙一樣!$B$B看看灼刃吧─他們中的大多數人認為自己會成為下一批極具潛力的術士，併成功替代暗影議會。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4535 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4535, 'zhTW', '哈哈!除了他們的領導人─薩特, 巴札蘭, 還有術士耶戈什─是的，他們所有人。這就是我不斷的派索爾的信徒到他們那兒去的原因。這樣會讓索爾覺得我正在剷除他偉大城市中邪惡的人。事實上勝利是雙重的:殺掉索爾的信徒並測試一下那些灼刃的力量，看看他們是否真的有資格加入我的隊伍。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4536 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4536, 'zhTW', '我會讓你知道這一點的。很明顯，你如此迅速地成為中尉，已經證明了自己的實力。或許稍後你回到我這兒時，我會派給你任務的。委員會崇尚那些能熟練運用魔法的人，但也歡迎各種族的僕從，無論該僕從從事何種職業。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4573 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4573, 'zhTW', '作為探險者協會的一員，我曾在這片區域搜尋古代器物。據說冬泉谷有許多不可思議的物品...很多物品都受到嚴密的保護。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4633 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4633, 'zhTW', '現在是危險時期，冒險者。多加小心。', '現在是危險時期，冒險者。多加小心。', '現在是危險時期，冒險者。多加小心。', '現在是危險時期，冒險者。多加小心。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
