INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4634, 'zhTW', '你好!是什麼吸引你來到冬泉谷?這片寒冷廣袤的土地或許顯得有些淒涼，但是它蘊含著無數的秘密...', '你好!是什麼吸引你來到冬泉谷?這片寒冷廣袤的土地或許顯得有些淒涼，但是它蘊含著無數的秘密...', '你好!是什麼吸引你來到冬泉谷?這片寒冷廣袤的土地或許顯得有些淒涼，但是它蘊含著無數的秘密……', '你好!是什麼吸引你來到冬泉谷?這片寒冷廣袤的土地或許顯得有些淒涼，但是它蘊含著無數的秘密……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
