INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4693, 'zhTW', '$g嗨，帥哥，你想去格羅姆高嗎?我聽說那裡的叢林整日霧氣騰騰的，也許我們可以一起度個短假，我讓你看看真正的叢林虎怎麼樣?:來吧，參觀一下奇妙絢麗的荊棘谷叢林。你可以在水晶般的藍色海岸線上愜意地洗日光浴，而我卻站在這難以忍受的高溫下整天傻看著我的兄弟弗雷薩!盡情享受你的旅程吧!;', '$g嗨，帥哥，你想去格羅姆高嗎?我聽說那裡的叢林整日霧氣騰騰的，也許我們可以一起度個短假，我讓你看看真正的叢林虎怎麼樣?:來吧，參觀一下奇妙絢麗的荊棘谷叢林。你可以在水晶般的藍色海岸線上愜意地洗日光浴，而我卻站在這難以忍受的高溫下整天傻看著我的兄弟弗雷薩!盡情享受你的旅程吧!;', '$g嗨，帥哥，你想去格羅姆高嗎?我聽說那裡的叢林整日霧氣騰騰的，也許我們可以一起度個短假，我讓你看看真正的叢林虎怎麼樣?:來吧，參觀一下奇妙絢麗的荊棘谷叢林。你可以在水晶般的藍色海岸線上愜意地洗日光浴，而我卻站在這難以忍受的高溫下整天傻看著我的兄弟弗雷薩!盡情享受你的旅程吧!', '$g嗨，帥哥，你想去格羅姆高嗎?我聽說那裡的叢林整日霧氣騰騰的，也許我們可以一起度個短假，我讓你看看真正的叢林虎怎麼樣?:來吧，參觀一下奇妙絢麗的荊棘谷叢林。你可以在水晶般的藍色海岸線上愜意地洗日光浴，而我卻站在這難以忍受的高溫下整天傻看著我的兄弟弗雷薩!盡情享受你的旅程吧!;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
