INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4694, 'zhTW', '將一枚硬幣塞到首領手中，看看你會得到什麼。我喜歡自己的工作。但是，如果我能設法讓斯納爾克重新分配給這個飛行點的話……那樣就好了。但是我敢打賭，你到這兒來不是要幫我進行職業訓練的，而是尋找地精飛艇前往幽暗城，對吧?那很好，因為它會停泊在我後面。如果你看見斯納爾克，代我向他問好，行嗎?', '將一枚硬幣塞到首領手中，看看你會得到什麼。我喜歡自己的工作。但是，如果我能設法讓斯納爾克重新分配給這個飛行點的話……那樣就好了。但是我敢打賭，你到這兒來不是要幫我進行職業訓練的，而是尋找地精飛艇前往幽暗城，對吧?那很好，因為它會停泊在我後面。如果你看見斯納爾克，代我向他問好，行嗎?', '將一枚硬幣塞到首領手中，看看你會得到什麼。我喜歡自己的工作。但是，如果我能設法讓斯納爾克重新分配給這個飛行點的話……那樣就好了。但是我敢打賭，你到這兒來不是要幫我進行職業訓練的，而是尋找地精飛艇前往幽暗城，對吧？那很好，因為它會停泊在我後面。如果你看見斯納爾克，代我向他問好，行嗎？', '將一枚硬幣塞到首領手中，看看你會得到什麼。我喜歡自己的工作。但是，如果我能設法讓斯納爾克重新分配給這個飛行點的話……那樣就好了。但是我敢打賭，你到這兒來不是要幫我進行職業訓練的，而是尋找地精飛艇前往幽暗城，對吧?那很好，因為它會停泊在我後面。如果你看見斯納爾克，代我向他問好，行嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
