INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4697, 'zhTW', '來吧，到荊棘谷中壯闊迷人的熱帶叢林作一次旅行吧！很好，你也可以在水晶般透明的碧藍海水邊悠哉遊哉，而我就在這難以忍受的炎熱下無所事事，整天只能和我的兄弟弗雷扎看個大眼瞪小眼。祝你旅途愉快！', '來吧，到荊棘谷中壯闊迷人的熱帶叢林作一次旅行吧！很好，你也可以在水晶般透明的碧藍海水邊悠哉遊哉，而我就在這難以忍受的炎熱下無所事事，整天只能和我的兄弟弗雷扎看個大眼瞪小眼。祝你旅途愉快！', NULL, '來吧，到荊棘谷中壯闊迷人的熱帶叢林作一次旅行吧！很好，你也可以在水晶般透明的碧藍海水邊悠哉遊哉，而我就在這難以忍受的炎熱下無所事事，整天只能和我的兄弟弗雷扎看個大眼瞪小眼。祝你旅途愉快！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4713 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4713, 'zhTW', '夢魘終於結束了!達隆郡，原諒我吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4714 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4714, 'zhTW', '月爪梟獸逝去的靈魂專注地盯著你，就像等待發生什麼事情一樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4715 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4715, 'zhTW', '靈魂專注地盯著你的眼睛，握緊你的雙手。你感到一股熱流抨擊著身體，幾乎無法站立。$B$B熱流過後，你感覺身體中似乎充斥著熊的靈魂……讓你更加堅定。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4716 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4716, 'zhTW', '我們都親眼目睹了無數可怕的災難，但是我們不能由此絕望。$B$B記住這些往事，總有一天，我們會進行報復的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4718 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4718, 'zhTW', '熊平靜地注視著你，但是沒說一句話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4719 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4719, 'zhTW', '熊的靈魂平和的凝視著你。你聽到了一個聲音在對你講話，好像是從熊那裡傳來，但是沒有跡象表明這個動物在說話。$B$B「你好，我年輕的朋友。如果你是來找我尋求指引的，那麼或許我能幫你找到你想要的東西。」', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4721 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4721, 'zhTW', '我代表著使你成為一名年輕的德魯伊的力量。年輕人，你得向我學習這力量，我也樂於傳授給你。要是你願意聽從並理解的話，我將教你如何使用熊的靈魂。$B$B為了明白利用我的靈魂的含義，你需要了解軀體和心靈的力量的重要性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4732 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4732, 'zhTW', '歡迎你, $n.', '你好，$n。', '很高興見到你 $N', '你好，$N！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4733 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4733, 'zhTW', '身體的力量能使動作充滿力度，行動迅速。你必須在身體上和精神上一直保持就緒狀態。熊的體型造就了它的力量，使它成為危險的對手。但是，熊的體型也限制了其身體的敏捷性和頭腦的靈活性。你可以好好利用這點。$B$B你必須依賴熊的力量掌握利爪的使用方法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4734 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4734, 'zhTW', '心靈的力量將給你採取行動的決心……基於明確的、直接的目的行動。保持平衡並不意味著自命不凡或是平庸陳腐。$B$B你必須表現出對信仰的決心，你必須願意為此奮鬥。母熊對幼仔有極強的保護意識，年老的熊也這樣保護著它的洞穴。這就是決心，心靈的力量，如果你想要掌握利爪的使用方法，你就必須知道這一點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4735 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4735, 'zhTW', '年輕人，還要看你是否準備就緒。當最終考驗來臨時，即使最聰明最年老的德魯伊也無法真正地做好準備。$B$B你已經聽到我的話了，你必須繼續前進。記得我的囑咐。某個時候你的能力將經受考驗。你必須像熊那樣勇敢面對自己的敵人─用身體和心靈的力量。年輕人，你得從戰爭中學習成長。去吧……帶上我的祝福。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4753 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4753, 'zhTW', '你好，$c。歡迎你來到永夜港，還有整個月光林地。塞納里奧議會歡迎所有尊敬大自然的權威和支配力的生靈。$B$B當你在這裡的時候，請一定要保持所有事物的平衡。這裡不喜歡受到打擾，而我們的看守所受的訓練就是無條件地停止所有的敵對行為。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4773 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4773, 'zhTW', '你需要幻影嗎?$B$B要是在執行任務的過程中幻影失效，回到我這兒來，我將重新對你進行偽裝。$B$B如果你盡力而為還是失敗了，別放棄!回到我這兒來。我將助你完成目標。', '你需要幻影嗎?$B$B要是在執行任務的過程中幻影失效，回到我這兒來，我將重新對你進行偽裝。$B$B如果你盡力而為還是失敗了，別放棄!回到我這兒來。我將助你完成目標。', '你需要幻象嗎?$b$b要是在執行任務的過程中幻象失效，回到我這兒來，我將重新對你進行偽裝。$b$b如果你盡力而為還是失敗了，別放棄!回到我這兒來。我將助你完成目標。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4774 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4774, 'zhTW', '努力保持所有事情的平衡性，$c。真正的和諧便在於此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4775 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4775, 'zhTW', '歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B重申自己在這偉大的平衡中的地位總是無傷大雅的。作為這種平衡的守護者，我們必須努力保持清醒的頭腦和堅定的信念。訓練能使我們做到這一點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4776 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4776, 'zhTW', '戰爭結束了，達隆郡的人民得救了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4777 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4777, 'zhTW', '戰爭結束了，達隆郡的人民得救了。$B$B他們得救了，$N，這都歸功於你。你是達隆郡的英雄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4778 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4778, 'zhTW', '我的眼睛被黑暗所矇蔽，但是你把我從邪惡的幻想中拯救出來。你救了我，$N。$B$B現在我求你...原諒我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4779 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4779, 'zhTW', '歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B在瑪法裡恩的守護下，我們永遠是平衡的守衛者。別忘了這一點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4780 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4780, 'zhTW', '我們的主人瑪法裡恩已從夢境中歸來，$c。他是我們的指路明燈，我們必須竭盡全力保護他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
