INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4782, 'zhTW', '歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。', '歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。', '歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$b$b據傳塞納里奧議會戰事不斷，但是你不該輕信這些謠言。我們的德魯伊首領範達爾·鹿盔將領導我們和整個泰達希爾取得勝利!', '歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B據傳塞納里奧議會戰事不斷，但是你不該輕信這些謠言。我們的德魯伊首領範達爾·鹿盔將領導我們和整個泰達希爾取得勝利!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
