INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4783, 'zhTW', '即使在冰冷的石頭牆內，就像庇護這座城市的牆一樣，人們仍舊可以找到寧靜與和平。事實上，不論你人在哪裡都找得到它們...只需往你心裡探尋此等平衡。', '即使在冰冷的石頭牆內，就像庇護這座城市的牆一樣，人們仍舊可以找到寧靜與和平。事實上，不論你人在哪裡都找得到它們...只需往你心裡探尋此等平衡。', '即使在冰冷的石頭牆內，就像庇護這座城鎮的牆一樣，人們仍舊可以找到寧靜與和平。事實上，你可以在你所在的任何地方找到他們……只需在你體內尋找這種平衡。', '即使在冰冷的石頭牆內，就像庇護這座城鎮的牆一樣，人們仍舊可以找到寧靜與和平。事實上，你可以在你所在的任何地方找到他們……只需在你體內尋找這種平衡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
