INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4859, 'zhTW', '多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了─今天就在這裡找到你想要的馬!', '多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了─今天就在這裡找到你想要的馬!', '多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了─今天就在這裡找到你想要的馬!', '多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了─今天就在這裡找到你想要的馬!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
