INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4881, 'zhTW', '要教你學會駕駛機械陸行鳥，那簡直就是在浪費我的金錢和時間，$c。你的體形太龐大了!', '要教你學會駕駛機械陸行鳥，那簡直就是在浪費我的金錢和時間，$c。你的體形太龐大了!', '要教你學會駕駛機械陸行鳥，那簡直就是在浪費我的金錢和時間，$c。你的體形太龐大了!', '要教你學會駕駛機械陸行鳥，那簡直就是在浪費我的金錢和時間，$c。你的體形太龐大了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4888 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4888, 'zhTW', '我按照傳統一代代地訓練、指導年輕獵人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4889 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4889, 'zhTW', '記住，所有的事物都是有關聯的。如果陸地上的野獸滅絕，我們的種族將在孤獨中死去，因為牛頭人和野獸的命運是相通的，而艾澤拉斯的命運和所有艾澤拉斯上的生靈的命運也休慼相關。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4890 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4890, 'zhTW', '如果你是來接受狩獵技巧訓練的，那你就來對地方了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4891 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4891, 'zhTW', '嗨!你從來沒有過深海潛水的經歷嗎?我告訴你一個小秘訣，嗯。在海洋深處有許多冒氣泡的裂縫，當你在水下時可利用這些氣泡進行呼吸。這個秘密只限於你我之間。對我來說，貝殼到處都是……如果你懂我的意思的話!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4893 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4893, 'zhTW', '看看野獸的智慧和學識吧，你會認清自己的。你要學會像貓頭鷹那樣敏銳，像獵豹那樣聰明，像狼那樣強大。', '看看野獸的智慧和學識吧，你會認清自己的。你要學會像貓頭鷹那樣敏銳，像獵豹那樣聰明，像狼那樣強大。', '看看野獸的智慧和學識吧，你會認清自己的。你要學會像貓頭鷹那樣敏銳，像獵豹那樣聰明，像狼那樣強大。', '看看野獸的智慧和學識吧，你會認清自己的。你要學會像貓頭鷹那樣敏銳，像獵豹那樣聰明，像狼那樣強大。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 4913 AND `Locale` = 'zhTW';
