INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (4978, 'zhTW', '願塞納留斯注視著你，$g兄弟:姐妹;。$B$B我是塔加里，一個神殿的堅定保衛者。能夠作為這片神聖大地的看守來服侍保衛者雷姆洛斯是我的榮耀。', '願塞納留斯注視著你，$g兄弟:姐妹;。$B$B我是塔加里，一個神殿的堅定保衛者。能夠作為這片神聖大地的看守來服侍保衛者雷姆洛斯是我的榮耀。', '願塞納留斯注視著你，$g兄弟:姐妹;。$b$b我是塔加里，一個神殿的堅定保衛者。能夠作為這片神聖大地的看守來服侍守護者雷姆洛斯是我的榮耀。', '願塞納留斯注視著你，$g兄弟:姐妹;。$B$B我是塔加里，一個神殿的堅定保衛者。能夠作為這片神聖大地的看守來服侍保衛者雷姆洛斯是我的榮耀。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
