INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5011, 'zhTW', '僅在三百年前，一個叫作索瑞森的魯莽的矮人從他熾熱的領地中召喚出了魔王。他重返這個卑微的世界吞噬了周圍的田地並形成了這個火山之核。從那以後，強大的拉格納羅斯就沉睡在了這座山下。', '僅在三百年前，一個叫作索瑞森的魯莽的矮人從他熾熱的領地中召喚出了魔王。他重返這個卑微的世界吞噬了周圍的田地並形成了這個火山之核。從那以後，強大的拉格納羅斯就沉睡在了這座山下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5012 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5012, 'zhTW', '作為忠實的僕從，我們會聽從他的命令，執行他的鐵血政策的。沒有了強大的領域實權，拉格納羅斯不過是他自身的傀儡罷了。但是，他擁有足夠的力量與你抗衡。', '作為忠實的僕從，我們會聽從他的命令，執行他的鐵血政策的。沒有了強大的領域實權，拉格納羅斯不過是他自身的傀儡罷了。但是，他擁有足夠的力量與你抗衡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5013 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5013, 'zhTW', '你好，$g先生:女士;。我想握你的手，但是如你所見，我正忙著做事。我可以幫忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5014 AND `Locale` = 'zhTW';
