DELETE FROM `npc_text_locale` WHERE `ID` = 5015 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5015, 'zhTW', '你已經學會的任何知識我都可以教你, $N.  如果你想繼續學習的話,在暴風城法師區的暗夜精靈莉薩談談 . 聽說他是一個好老師', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5016 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5016, 'zhTW', '雖然我被關在這間小屋裡，但是我夢想著加入城牆外激烈的戰鬥。然而，職責迫使我為替我戰鬥的那些人傳授知識...', '雖然我被關在這間小屋裡，但是我夢想著加入城牆外激烈的戰鬥。然而，職責迫使我為替我戰鬥的那些人傳授知識...', '雖然我被關在這間小屋裡，但是我夢想著加入城牆外激烈的戰鬥。然而，職責迫使我為替我戰鬥的那些人傳授知識……', '雖然我被關在這間小屋裡，但是我夢想著加入城牆外激烈的戰鬥。然而，職責迫使我為替我戰鬥的那些人傳授知識……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
