INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5022, 'zhTW', '德魯伊們說大自然把部落從卡林多趕出去只是個時間問題。然而墮落繼續在我們的大地上蔓延，甚至在泰達希爾這裡也是。', '德魯伊們說大自然把部落從卡林多趕出去只是個時間問題。然而墮落繼續在我們的大地上蔓延，甚至在泰達希爾這裡也是。', '德魯伊們說大自然把部落從卡利姆多趕出去只是個時間問題。然而墮落繼續在我們的大地上蔓延，甚至在泰達希爾這裡也是。', '德魯伊們說大自然把部落從卡林多趕出去只是個時間問題。然而墮落繼續在我們的大地上蔓延，甚至在泰達希爾這裡也是。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
