INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5026, 'zhTW', '人們從森林植物中製造的東西難道不令人震驚嗎?說真的，月神對我們已經很慷慨了。', '人們從森林植物中製造的東西難道不令人震驚嗎?說真的，月神對我們已經很慷慨了。', '人們從森林植物中製造的東西難道不令人震驚嗎?說真的，月神對我們已經很慷慨了。', '人們從森林植物中製造的東西難道不令人震驚嗎?說真的，月神對我們已經很慷慨了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
