INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5055, 'zhTW', '嗯，我能教的你已經都學會了。或許你該找其他人談談了。試一下達納蘇斯工匠區的夜精靈安尼希爾。她確實很有智慧!', '嗯，我能教的你已經都學會了。或許你該找其他人談談了。試一下達納蘇斯工匠區的夜精靈安尼希爾。她確實很有智慧!', '嗯，我能教的你已經都學會了。或許你該找其它人談談了。試一下達納蘇斯工匠區的夜精靈安尼希爾。她確實很有智慧!', '嗯，我能教的你已經都學會了。或許你該找其他人談談了。試一下達納蘇斯工匠區的夜精靈安尼希爾。她確實很有智慧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
