INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5063, 'zhTW', '雖然我很高興聽到你對我的能力充滿信心，但我真的沒法再教你了。你必須到達納蘇斯的工匠區去找夜精靈安尼希爾談談。她可以幫助你。', '雖然我很高興聽到你對我的能力充滿信心，但我真的沒法再教你了。你必須到達納蘇斯的工匠區去找夜精靈安尼希爾談談。她可以幫助你。', '雖然我很高興聽到你對我的能力充滿信心，但我真的沒法再教你了。你必須到達納蘇斯的工匠區去找夜精靈安尼希爾談談。她可以幫助你。', '雖然我很高興聽到你對我的能力充滿信心，但我真的沒法再教你了。你必須到達納蘇斯的工匠區去找夜精靈安尼希爾談談。她可以幫助你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
