INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5064, 'zhTW', '即使輕微地改變藥劑的成份也能使它發生根本的變化。耐心和精確，年輕人:他們會讓你在所有行業都受益匪淺。', '即使輕微地改變藥劑的成份也能使它發生根本的變化。耐心和精確，年輕人:他們會讓你在所有行業都受益匪淺。', '即使輕微地改變藥劑的成份也能使它發生根本的變化。耐心和精確，年輕人：他們會讓你在所有行業都受益匪淺。', '即使輕微地改變藥劑的成份也能使它發生根本的變化。耐心和精確，年輕人:他們會讓你在所有行業都受益匪淺。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
