INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5069, 'zhTW', '我很忙，$N。告訴伍特去處理一切。那個年輕人整天都焦慮不安的。他大部分時間都處於這種狀態，像是要做些什麼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5070 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5070, 'zhTW', '見到你是我的榮幸，$N，但是你在配製藥水方面比我厲害。去幽暗城 鏈金房找亡靈赫伯特·哈爾希醫生。他能幫助你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5072 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5072, 'zhTW', '你找錯獸人了。我不訓練新手。去問問那邊的小伍特……謙虛一點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5073 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5073, 'zhTW', '另一名學生，是嗎?好吧。我看看有什麼能幫助你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5074 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5074, 'zhTW', '格里克斯和我達成一項共識:他給我供貨，而我給他錢。這是很認真的!那個海賊為了一小袋皺皺巴巴的皇血草收我多少錢...足夠把一個成年的哥布林弄哭了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5075 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5075, 'zhTW', '我有許多處方可供選擇，我還可以為你打折!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5078 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5078, 'zhTW', '你做得比我要好!你需要一個經驗比我還要多的人。那就是安尼希爾，一個在達納蘇斯工匠區生活的夜精靈女士。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5079 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5079, 'zhTW', '第一次看見亡靈時，我哭了，我無法想像他們的恐懼和孤寂。大地之母在我耳邊吟唱，她告訴我:「拯救他們吧。」', '第一次看見亡靈時，我哭了，我無法想像他們的恐懼和孤寂。大地之母在我耳邊吟唱，她告訴我:「拯救他們吧。」', '第一次看見亡靈時，我哭了，我無法想象他們的恐懼和孤寂。大地之母在我耳邊吟唱，她告訴我:“拯救他們吧。”', '第一次看見亡靈時，我哭了，我無法想像他們的恐懼和孤寂。大地之母在我耳邊吟唱，她告訴我:“拯救他們吧。”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5080 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5080, 'zhTW', '你難道感覺不到大地之母為了她所丟失的孩子，也就是亡靈們，而出現的苦惱嗎?快些說，$N。每一秒對我都很珍貴。我們必須幫他們找到迴歸她身邊的路!', '你難道感覺不到大地之母為了她所丟失的孩子，也就是亡靈們，而出現的苦惱嗎?快些說，$N。每一秒對我都很珍貴。我們必須幫他們找到迴歸她身邊的路!', '你難道感覺不到大地之母為了她所丟失的孩子，也就是亡靈們，而出現的苦惱嗎?快些說，$N。每一秒對我都很珍貴。我們必須幫他們找到迴歸她身邊的路!', '你難道感覺不到大地之母為了她所丟失的孩子，也就是亡靈們，而出現的苦惱嗎?快些說，$N。每一秒對我都很珍貴。我們必須幫他們找到迴歸她身邊的路!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5081 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5081, 'zhTW', '當我們的盟友，也就是亡靈們，在遭受可怕苦難時候，我如果還在這裡訓練新手，這會讓我感到良心不安。請找那邊的克瑞談談;他目前能夠幫你。', '當我們的盟友，也就是亡靈們，在遭受可怕苦難時候，我如果還在這裡訓練新手，這會讓我感到良心不安。請找那邊的克瑞談談;他目前能夠幫你。', '當我們的盟友，也就是亡靈們，在遭受可怕苦難時候，我如果還在這裡訓練新手，這會讓我感到良心不安。請找那邊的克瑞談談；他目前能夠幫你。', '當我們的盟友，也就是亡靈們，在遭受可怕苦難時候，我如果還在這裡訓練新手，這會讓我感到良心不安。請找那邊的克瑞談談;他目前能夠幫你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5083 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5083, 'zhTW', '你製造藥劑的技術已經在我之上。去幽暗城的鏈金房找亡靈赫伯特·哈爾希醫生。他可以繼續你的訓練，而你也可以親眼目睹他的人民所遭受的苦難。', '你製造藥劑的技術已經在我之上。去幽暗城的鏈金房找亡靈赫伯特·哈爾希醫生。他可以繼續你的訓練，而你也可以親眼目睹他的人民所遭受的苦難。', '你製造藥劑的技術已經在我之上。去幽暗城的鍊金房找亡靈赫伯特·哈爾希醫生。他可以繼續你的訓練，而你也可以親眼目睹他的人民所遭受的苦難。', '你製造藥劑的技術已經在我之上。去幽暗城的鍊金房找亡靈赫伯特·哈爾希醫生。他可以繼續你的訓練，而你也可以親眼目睹他的人民所遭受的苦難。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5084 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5084, 'zhTW', '又來打擾我了。像這樣我還能做什麼工作麼?不用回答，我看起來像是很在乎你的回答麼?如果我們要清理這個地方並且擴張我們帝國的話，我需要絕對的安靜!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5085 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5085, 'zhTW', '要我訓練你?別開玩笑了─我們都知道這是不可能的。我可無法勝任。你要是想接受訓練的話，就去幽暗城的鏈金房找被遺忘者赫伯特·哈爾希醫生吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5087 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5087, 'zhTW', '別浪費我時間。我從事研究的時間比你的年紀還要大。去跟幽暗城鍊金房的亡靈馬丁·費爾本談談。他或許能傳授給你一些基礎知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5088 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5088, 'zhTW', '另一名學生。棒極了。這就是林度恩躋身皇家學會從事研究工作的原因，也是我堅持成為一名導師的原因。只要我再獲得一枚教學獎章，我的美名便不會被人所遺忘了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5089 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5089, 'zhTW', '有奧格諾恩提供所需的供應，我可以不用尋找一株草藥就能完成在這裡的任務。如果我永遠都不用再次看到自然的奇蹟，這就不會很快發生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5090 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5090, 'zhTW', '我沒有可傳授給你的知識了。穿過拱門走下斜坡到東南方，找赫伯特·哈爾希醫生談談。他是個被遺忘者，他能教給你更加高階的技術。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5092 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5092, 'zhTW', '你如此大膽地跑來找我，想要接受訓練，我對此可不高興。穿過拱道，沿著坡道向東南方走，跟被遺忘者馬丁·費爾本談談。他能教你一些基礎知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5093 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5093, 'zhTW', '到這兒來學習的嗎?很好。我想要是我教你的話，你不會對我們的聯盟造成太多的傷害。只要你一心對付我們的敵人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5094 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5094, 'zhTW', '雖然每次我都使用了相同的成分，但配製出的藥水似乎都達不到預期的治療效果。這隻能得出一個結論:植物發生了變化。我還不清楚具體原因。', '雖然每次我都使用了相同的成分，但配製出的藥水似乎都達不到預期的治療效果。這隻能得出一個結論:植物發生了變化。我還不清楚具體原因。', '雖然每次我都使用了相同的成分，但配製出的藥水似乎都達不到預期的治療效果。這隻能得出一個結論:植物發生了變化。我還不清楚具體原因。', '雖然每次我都使用了相同的成分，但配製出的藥水似乎都達不到預期的治療效果。這隻能得出一個結論:植物發生了變化。我還不清楚具體原因。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5095 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5095, 'zhTW', '現在你該找一位更加淵博的老師了。在菲拉斯的羽月要塞居住著夜精靈凱蘭娜·風語。她有聰明的頭腦;毫無疑問她能繼續教你。', '現在你該找一位更加淵博的老師了。在菲拉斯的羽月要塞居住著夜精靈凱蘭娜·風語。她有聰明的頭腦;毫無疑問她能繼續教你。', '現在你該找一位更加淵博的老師了。在菲拉斯的羽月要塞居住著夜精靈凱蘭娜·語風。她有聰明的頭腦;毫無疑問她能繼續教你。', '現在你該找一位更加淵博的老師了。在菲拉斯的羽月要塞居住著夜精靈凱蘭娜·風語。她有聰明的頭腦;毫無疑問她能繼續教你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5097 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5097, 'zhTW', '你製造藥劑的技能需要再高超一些才能當我的學生。在此期間，在那邊的希爾瓦娜·林月或米拉·法拉科納可能會幫助你。', '你製造藥劑的技能需要再高超一些才能當我的學生。在此期間，在那邊的希爾瓦娜·林月或米拉·法拉科納可能會幫助你。', '你製造藥劑的技能需要再高超一些才能當我的學生。在此期間，在那邊的希爾瓦娜·林月或米拉·法拉科納可能會幫助你。', '你製造藥劑的技能需要再高超一些才能當我的學生。在此期間，在那邊的希爾瓦娜·林月或米拉·法拉科納可能會幫助你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5098 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5098, 'zhTW', '你的培訓進展很好。你該為你的成就感到自豪。', '你的培訓進展很好。你該為你的成就感到自豪。', '你的培訓進展很好。你該為你的成就感到自豪。', '你的培訓進展很好。你該為你的成就感到自豪。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5099 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5099, 'zhTW', '我和我的同伴正在收集我們所知的致命物質，並在敵人身上測試它們的效果。一旦我收集齊備，我將製造出這世界前所未有的瘟疫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5100 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5100, 'zhTW', '難以置信。你配製藥水的技能已經能跟我匹敵了。我不能再訓練你了，去悲傷沼澤找斯通納德的獸人羅格瓦爾談談。他以他的寶刀而聞名。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5102 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5102, 'zhTW', '你的技術太差了，還不能跟我學習。去跟那邊的馬丁醫生談談，或者爬上斜坡到東南方去看看馬許醫生。他們是被遺忘者，可以給你所需的訓練。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5103 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5103, 'zhTW', '準備好接受訓練了?保持速度，$N。我們要走的路還長著呢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5104 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5104, 'zhTW', '從前我歡迎過黑暗，因為它是夜晚的姐妹。現在總是漆黑一片，甚至在白天也是這樣，而森林迫切需要給養。除非我們快些行動，否則這擴散的荒疫會遍佈整個世界。', '從前我歡迎過黑暗，因為它是夜晚的姐妹。現在總是漆黑一片，甚至在白天也是這樣，而森林迫切需要給養。除非我們快些行動，否則這擴散的荒疫會遍佈整個世界。', '從前我歡迎過黑暗，因為它是夜晚的姐妹。現在總是漆黑一片，甚至在白天也是這樣，而森林迫切需要給養。除非我們快些行動，否則這擴散的瘟疫就會遍佈整個世界。', '從前我歡迎過黑暗，因為它是夜晚的姐妹。現在總是漆黑一片，甚至在白天也是這樣，而森林迫切需要給養。除非我們快些行動，否則這擴散的荒疫會遍佈整個世界。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5105 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5105, 'zhTW', '你是來接受藥水配製這一技能的訓練的嗎?要是你認為能從我這兒不費吹灰之力地學到東西的話，你就大錯特錯了。走吧，在你沒有掌握更高技能之前別來找我。', '你是來接受藥水配製這一技能的訓練的嗎?要是你認為能從我這兒不費吹灰之力地學到東西的話，你就大錯特錯了。走吧，在你沒有掌握更高技能之前別來找我。', '你是來接受藥水配製這一技能的訓練的嗎?要是你認為能從我這兒不費吹灰之力地學到東西的話，你就大錯特錯了。走吧，在你沒有掌握更高技能之前別來找我。', '你是來接受藥水配製這一技能的訓練的嗎?要是你認為能從我這兒不費吹灰之力地學到東西的話，你就大錯特錯了。走吧，在你沒有掌握更高技能之前別來找我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5106 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5106, 'zhTW', '你的技能顯示你一直喜愛我們的藝術，但是我想看到你所做承諾的進一步證據。我會分配給你一項任務。完成它就會令我滿意。', '你的技能顯示你一直喜愛我們的藝術，但是我想看到你所做承諾的進一步證據。我會分配給你一項任務。完成它就會令我滿意。', '你的技能顯示你一直喜愛我們的藝術，但是我想看到你所做承諾的進一步證據。我會分配給你一項任務。完成它就會令我滿意。', '你的技能顯示你一直喜愛我們的藝術，但是我想看到你所做承諾的進一步證據。我會分配給你一項任務。完成它就會令我滿意。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5108 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5108, 'zhTW', '大酋長索爾親自邀請我到這兒來。我感到非常榮幸，這並不困難。我不要求自己的職務高於斯通納德。我只想找些生長在這兒的草藥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5110 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5110, 'zhTW', '嗯，好吧，我看到你還懂一點做藥劑的方法。然而，你是否配做我的學生仍有待察看。我有一項任務交給你。爭取給我一個好印象。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5111 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5111, 'zhTW', '你膽敢讓我培訓你，你這可憐蟲?你期望什麼，你這個呆頭呆腦的鄉巴佬，一場關於如何正確使用銀葉的講演?滾出去!你浪費我的時間沒把你打個半死算你走運。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5112 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5112, 'zhTW', '只需做些小調整...我們出發吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
