INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5119, 'zhTW', '呃……雖然我不願承認，但是你要想繼續訓練的話就必須跟我的姐妹談談。目前來說……我知道的沒她多!她乘坐火箭車四處巡查。', '呃……雖然我不願承認，但是你要想繼續訓練的話就必須跟我的姐妹談談。目前來說……我知道的沒她多!她乘坐火箭車四處巡查。', '呃……雖然我不願承認，但是你要想繼續訓練的話就必須跟我的姐妹談談。目前來說……我知道的沒她多!她乘坐火箭車四處巡查。', '呃……雖然我不願承認，但是你要想繼續訓練的話就必須跟我的姐妹談談。目前來說……我知道的沒她多!她乘坐火箭車四處巡查。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
