INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5122, 'zhTW', '哦，你還有很多東西要學。我會教給你我所學的全部知識，但是我自己也在學習!你為什麼不找鐵爐堡的特里克希談談，她會幫你進修的!', '哦，你還有很多東西要學。我會教給你我所學的全部知識，但是我自己也在學習!你為什麼不找鐵爐堡的特里克希談談，她會幫你進修的!', '哦，你還有很多東西要學。我會教給你我所學的全部知識，但是我自己也在學習!你為什麼不找鐵爐堡的特里克希談談，她會幫你進修的!', '哦，你還有很多東西要學。我會教給你我所學的全部知識，但是我自己也在學習!你為什麼不找鐵爐堡的特里克希談談，她會幫你進修的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5123 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5123, 'zhTW', '你想學習?跟著我?太棒了!唯一比裝配子彈和爆裂物裝置有趣的事情就是與別人分享那種知識!我們開始吧!', '你想學習?跟著我?太棒了!唯一比裝配子彈和爆裂物裝置有趣的事情就是與別人分享那種知識!我們開始吧!', '你想學習?跟著我?太棒了!唯一比裝配子彈和炸藥裝置有趣的事情就是與別人分享那種知識!我們開始吧!', '你想學習?跟著我?太棒了!唯一比裝配子彈和爆裂物裝置有趣的事情就是與別人分享那種知識!我們開始吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5124 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5124, 'zhTW', '啊，多麼美好的一天啊!真該炸點什麼東西。', '啊，多麼美好的一天啊!真該炸點什麼東西。', '啊，多麼美好的一天啊!真該炸點什麼東西。', '啊，多麼美好的一天啊!真該炸點什麼東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
