INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5182, 'zhTW', '我擔心對有你這樣經驗的人沒什麼可教的。但是你還有其他方法。去找那邊櫃檯後面的魯坎·考迪爾談談。他會指引你透過旅行的下一個階段。', '我擔心對有你這樣經驗的人沒什麼可教的。但是你還有其他方法。去找那邊櫃檯後面的魯坎·考迪爾談談。他會指引你透過旅行的下一個階段。', '我擔心對有你這樣經驗的人沒什麼可教的。但是你還有其它方法。去找那邊櫃檯後面的魯坎·考迪爾談談。他會指引你透過旅行的下一個階段。', '我擔心對有你這樣經驗的人沒什麼可教的。但是你還有其他方法。去找那邊櫃檯後面的魯坎·考迪爾談談。他會指引你透過旅行的下一個階段。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5183 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5183, 'zhTW', '嗯……你看起來很有能耐。如果你真想學習的話，那麼沒有什麼能阻擋你!我會指引你透過漫長而碩果豐盛的道路上的第一步。', '嗯……你看起來很有能耐。如果你真想學習的話，那麼沒有什麼能阻擋你!我會指引你透過漫長而碩果豐盛的道路上的第一步。', '嗯……你看起來很有能耐。如果你真想學習的話，那麼沒有什麼能阻擋你!我會指引你透過漫長而碩果豐盛的道路上的第一步。', '嗯……你看起來很有能耐。如果你真想學習的話，那麼沒有什麼能阻擋你!我會指引你透過漫長而碩果豐盛的道路上的第一步。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
