INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5187, 'zhTW', '女神已經賜予我智慧，陌生人。如果那是她的意願，我將會把它傳給你。', '女神已經賜予我智慧，陌生人。如果那是她的意願，我將會把它傳給你。', '女神已經賜予我智慧，陌生人。如果那是她的意願，我將會把它傳給你。', '女神已經賜予我智慧，陌生人。如果那是她的意願，我將會把它傳給你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
