INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5188, 'zhTW', '你的技能已經非我能及。現在你該接受新的挑戰了。塔蘭丹會幫你準備。他就站在那裡的桌子旁邊。', '你的技能已經非我能及。現在你該接受新的挑戰了。塔蘭丹會幫你準備。他就站在那裡的桌子旁邊。', '你的技能已經非我能及。現在你該接受新的挑戰了。塔蘭丹會幫你準備。他就站在那裡的桌子旁邊。', '你的技能已經非我能及。現在你該接受新的挑戰了。塔蘭丹會幫你準備。他就站在那裡的桌子旁邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
