INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5229, 'zhTW', '如果我不是天天都陷在這裡，我已經得到訓練你們這些人的技能了!不幸的是事實不是這樣。去石爪山脈的烈日石居找赫加斯談談。', '如果我不是天天都陷在這裡，我已經得到訓練你們這些人的技能了!不幸的是事實不是這樣。去石爪山脈的烈日石居找赫加斯談談。', '如果我不是天天都陷在這裡，我已經得到訓練你們這些人的技能了!不幸的是事實不是這樣。去石爪山脈的烈日石居找赫加斯談談。', '如果我不是天天都陷在這裡，我已經得到訓練你們這些人的技能了!不幸的是事實不是這樣。去石爪山脈的烈日石居找赫加斯談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
