INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5232, 'zhTW', '好吧，我明白些了。但是，你有潛力，這點我不會否定。多加留心你或許就能學到什麼東西!', '好吧，我明白些了。但是，你有潛力，這點我不會否定。多加留心你或許就能學到什麼東西!', '好吧，我明白些了。但是，你有潛力，這點我不會否定。多加留心你或許就能學到什麼東西!', '好吧，我明白些了。但是，你有潛力，這點我不會否定。多加留心你或許就能學到什麼東西!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
