INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5257, 'zhTW', '自從我的丈夫上了前線後，海倫尼便一直保護著我。她用善良的心腸和鋒利的寶劍幫助我度過了無數艱難歲月。沒有她，我真不知道會發生什麼事。', '自從我的丈夫上了前線後，海倫尼便一直保護著我。她用善良的心腸和鋒利的寶劍幫助我度過了無數艱難歲月。沒有她，我真不知道會發生什麼事。', '自從我的丈夫上了前線後，海倫尼便一直保護著我。她用善良的心腸和鋒利的寶劍幫助我度過了無數艱難歲月。沒有她，我真不知道會發生什麼事。', '自從我的丈夫上了前線後，海倫尼便一直保護著我。她用善良的心腸和鋒利的寶劍幫助我度過了無數艱難歲月。沒有她，我真不知道會發生什麼事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
