INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5258, 'zhTW', '唉，對不起。我沒什麼新東西可以教你了。你去暴風城的老城區找西蒙·坦納爾談談怎麼樣?他是一個肌肉發達有一頭漂亮紅髮的人類。', '唉，對不起。我沒什麼新東西可以教你了。你去暴風城的老城區找西蒙·坦納爾談談怎麼樣?他是一個肌肉發達有一頭漂亮紅髮的人類。', '唉，對不起。我沒什麼新東西可以教你了。你去暴風城的老城區找西蒙·坦納爾談談怎麼樣?他是一個肌肉發達有一頭漂亮紅髮的人類。', '唉，對不起。我沒什麼新東西可以教你了。你去暴風城的老城區找西蒙·坦納爾談談怎麼樣?他是一個肌肉發達有一頭漂亮紅髮的人類。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
