INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5263, 'zhTW', '歡迎來到我們家，$N。拉德納爾和我沒什麼東西拿給你，但是我們會盡最大盛情歡迎你。', '歡迎來到我們家，$N。拉德納爾和我沒什麼東西拿給你，但是我們會盡最大盛情歡迎你。', '歡迎來到我們家，$N。拉德納爾和我沒什麼東西拿給你，但是我們會盡最大盛情歡迎你。', '歡迎來到我們家，$N。拉德納爾和我沒什麼東西拿給你，但是我們會盡最大盛情歡迎你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
