INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5273, 'zhTW', '如果你對皮革縫紉感興趣，那你算來對地方了。法多恩和泰龍尼斯都是真正的藝術家，而我希望能從他們那裡多學些知識。', '如果你對皮革縫紉感興趣，那你算來對地方了。法多恩和泰龍尼斯都是真正的藝術家，而我希望能從他們那裡多學些知識。', '如果你對皮革縫紉感興趣，那你算來對地方了。法多恩和泰龍尼斯都是真正的藝術家，而我希望能從他們那裡多學些知識。', '如果你對皮革縫紉感興趣，那你算來對地方了。法多恩和泰龍尼斯都是真正的藝術家，而我希望能從他們那裡多學些知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
