INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5275, 'zhTW', '在達納蘇斯這裡真是太令人興奮了，到處都是才華橫溢的人們!我這才知道我會讓我的家人感到驕傲的。或許如果我幸運的話，哨兵們會請我加入他們前線的軍隊的!', '在達納蘇斯這裡真是太令人興奮了，到處都是才華橫溢的人們!我這才知道我會讓我的家人感到驕傲的。或許如果我幸運的話，哨兵們會請我加入他們前線的軍隊的!', '在達納蘇斯這裡真是太令人興奮了，到處都是才華橫溢的人們!我這才知道我會讓我的家人感到驕傲的。或許如果我幸運的話，哨兵們會請我加入他們前線的軍隊的!', '在達納蘇斯這裡真是太令人興奮了，到處都是才華橫溢的人們!我這才知道我會讓我的家人感到驕傲的。或許如果我幸運的話，哨兵們會請我加入他們前線的軍隊的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
