INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5276, 'zhTW', '還沒準備好收拾這張皮。我希望做皮革不要花太多時間。肯定有辦法削減等待的時間。這對我身體不太好，你知道嗎?', '還沒準備好收拾這張皮。我希望做皮革不要花太多時間。肯定有辦法削減等待的時間。這對我身體不太好，你知道嗎?', '還沒準備好收拾這張皮。我希望做皮革不要花太多時間。肯定有辦法削減等待的時間。這對我身體不太好，你知道嗎?', '還沒準備好收拾這張皮。我希望做皮革不要花太多時間。肯定有辦法削減等待的時間。這對我身體不太好，你知道嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
