INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5281, 'zhTW', '我們不能剝下人類及其聯盟的皮，這真糟糕。這些皮都白白浪費掉了。儘管如此，誰想穿著你由此製造出的質地極差的皮革?', '我們不能剝下人類及其聯盟的皮，這真糟糕。這些皮都白白浪費掉了。儘管如此，誰想穿著你由此製造出的質地極差的皮革?', '我們不能剝下人類及其聯盟的皮，這真糟糕。這些皮都白白浪費掉了。儘管如此，誰想穿著你由此製造出的質地極差的皮革?', '我們不能剝下人類及其聯盟的皮，這真糟糕。這些皮都白白浪費掉了。儘管如此，誰想穿著你由此製造出的質地極差的皮革?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5282 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5282, 'zhTW', '膚質很好。它將你包裹其中。你也許已經注意到我的皮膚不是那麼好。我過去常常擔心自己的毛孔。這些日子我幾乎不擔心皮膚了。在某種程度上，它得到了解放。', '膚質很好。它將你包裹其中。你也許已經注意到我的皮膚不是那麼好。我過去常常擔心自己的毛孔。這些日子我幾乎不擔心皮膚了。在某種程度上，它得到了解放。', '膚質很好。它將你包裹其中。你也許已經注意到我的皮膚不是那麼好。我過去常常擔心自己的毛孔。這些日子我幾乎不擔心皮膚了。在某種程度上，它得到了解放。', '膚質很好。它將你包裹其中。你也許已經注意到我的皮膚不是那麼好。我過去常常擔心自己的毛孔。這些日子我幾乎不擔心皮膚了。在某種程度上，它得到了解放。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5283 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5283, 'zhTW', '你已經掌握了它的用法。我沒有什麼要教你的了，但是找亞瑟·摩爾談談，他是在幽暗城盜賊區工作的一位被遺忘者。告訴他是我派你去的。', '你已經掌握了它的用法。我沒有什麼要教你的了，但是找亞瑟·摩爾談談，他是在幽暗城盜賊區工作的一位被遺忘者。告訴他是我派你去的。', '你已經掌握了它的用法。我沒有什麼要教你的了，但是找亞瑟·摩爾談談，他是在幽暗城盜賊區工作的一位被遺忘者。告訴他是我派你去的。', '你已經掌握了它的用法。我沒有什麼要教你的了，但是找亞瑟·摩爾談談，他是在幽暗城盜賊區工作的一位被遺忘者。告訴他是我派你去的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5284 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5284, 'zhTW', '在瘟疫來之前，我對皮革一無所知。現在我的知識可以傳授別人了。死亡讓我有了很多時間供自己支配。', '在瘟疫來之前，我對皮革一無所知。現在我的知識可以傳授別人了。死亡讓我有了很多時間供自己支配。', '在瘟疫來之前，我對皮革一無所知。現在我的知識可以傳授別人了。死亡讓我有了很多時間供自己支配。', '在瘟疫來之前，我對皮革一無所知。現在我的知識可以傳授別人了。死亡讓我有了很多時間供自己支配。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5285 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5285, 'zhTW', '肉、獸皮、骨頭……好的獵人是不會浪費任何東西的。每塊獸皮都有利用價值，也許能用來增強盟友的武器裝備。單獨來看，我們每個人都很強大，但是團結在一起我們就無敵了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5286 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5286, 'zhTW', '我已經沒什麼可教你了。帶著大地之母的祝福離開吧。在雷霆崖的中央高原西北方的商店找到牛頭人塔恩。願你得到他智慧的指引。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5287 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5287, 'zhTW', '我們在此繁衍生息，生生死死，數年來大地卻亙古不動。因此，這片土地並不屬於我們，$N。我們是屬於大地的。因此，我們守護著它，沒有它我們就無法生存。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5288 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5288, 'zhTW', '我們腳下的洞穴中有許多奇異的獸皮，如果你想深入其中探險的話，一定要非常小心，$N。要記住你自己的性命比那些獸皮有價值得多。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5289 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5289, 'zhTW', '你對皮革的理解比我要深刻。可能你應該拜訪一下貧瘠之地陶拉祖營地的牛頭人克魯姆·滿月。對你這麼聰明的學生他有很多知識要教給你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5291 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5291, 'zhTW', '凱恩自己住這兒，他們說。一旦我完成了製作一件合適的禮物，我就會把他找出來。或許他會有智慧的話要對我說。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5292 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5292, 'zhTW', '你的智慧勝於我，朋友。與這裡的塔恩談話;他對皮革的知識比我要豐富得多。我肯定他會歡迎新學生的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5293 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5293, 'zhTW', '在你開始任何工作之前都要洗淨雙手。皮革被血或塵土玷汙了會帶走它的自然美。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5294 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5294, 'zhTW', '當我從墓穴中爬出來後，我本以為我的家人會熱烈地歡迎我。相反，他們把我從村裡趕了出去，用一種我聽不懂的語言高聲尖叫著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5295 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5295, 'zhTW', '我不能幫助你，我無法勝任。跟棺材那邊的亞瑟·摩爾談談。他會為你提供更多的訓練的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5296 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5296, 'zhTW', '記住我說的每句話。在打敗敵人之前，我們絕對不能放棄學習知識、提高自身能力的機會。增強你的實力，絕不能放鬆警戒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5314 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5314, 'zhTW', '你已經超越我有限的能力了。到達納蘇斯的工匠區尋找夜精靈安尼希爾。她可以教給你更多知識。我很希望我可以跟你一起去。', '你已經超越我有限的能力了。到達納蘇斯的工匠區尋找夜精靈安尼希爾。她可以教給你更多知識。我很希望我可以跟你一起去。', '你已經超越我有限的能力了。到達納蘇斯的工匠區尋找夜精靈安尼希爾。她可以教給你更多知識。我很希望我可以跟你一起去。', '你已經超越我有限的能力了。到達納蘇斯的工匠區尋找夜精靈安尼希爾。她可以教給你更多知識。我很希望我可以跟你一起去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5316 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5316, 'zhTW', '對你來說，我的教學在這個階段略顯深奧了。要是你想學習有關藥水的更多知識，就跟泰蘭希爾談談。', '對你來說，我的教學在這個階段略顯深奧了。要是你想學習有關藥水的更多知識，就跟泰蘭希爾談談。', '對你來說，我的教學在這個階段略顯深奧了。要是你想學習有關藥水的更多知識，就跟泰蘭希爾談談。', '對你來說，我的教學在這個階段略顯深奧了。要是你想學習有關藥水的更多知識，就跟泰蘭希爾談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5317 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5317, 'zhTW', '聽仔細了，$N，我要傳授給你的知識很多。', '聽仔細了，$N，我要傳授給你的知識很多。', '聽仔細了，$N，我要傳授給你的知識很多。', '聽仔細了，$N，我要傳授給你的知識很多。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5318 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5318, 'zhTW', '即使我也有我的侷限性!如果你想繼續學習的話去找幽暗城的拉文尼亞·克洛文談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5319 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5319, 'zhTW', '還行……訓練你是不成問題的。很好!我們開始吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5320 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5320, 'zhTW', '蘭達爾打扮得有些像花花公子，但是他是個可靠的人，他比我向許多學生所說的那樣更加值得信賴。儘管如此，我還是不能責備他們想要冒險的想法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5321 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5321, 'zhTW', '很抱歉，我已經沒有什麼可以教給你的了。如果你還想學的話，就去達納蘇斯的工匠區找泰龍尼斯吧。我聽說他相當有才能。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5323 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5323, 'zhTW', '當你接受更多訓練以後再回來找我。在那邊的蘭達爾·沃斯可以幫你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5324 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5324, 'zhTW', '嗯，我想我可以再收一個學生。好吧，不要傻站在那裡。告訴我你想學什麼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5325 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5325, 'zhTW', '達麗亞娜答應了，但是她的精力如此充沛，很難讓她安靜下來仔細的聆聽。她氣力十足又機靈敏捷，我恐怕她不久就會被叫去參加戰鬥。我們必須快點教她。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5326 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5326, 'zhTW', '如果你來這兒是為了得到進一步的訓練，那你是高估我的能力了。跟泰龍尼斯談談;他應該能幫助你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5328 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5328, 'zhTW', '你得及時準備好接受我的教學，$N。到那時，找達麗亞娜談談，他會幫助你訓練的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5329 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5329, 'zhTW', '我們可以從死去的動物身上獲得原料。別無視它們的犧牲，$N。帶著尊敬來處理這些皮革。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5330 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5330, 'zhTW', '要做的事情很多!自從我的兄弟不小心蒸發了諾姆瑞根所有的衣料和皮革之後，事情便多起來了。我只能保持暫時通風!啊，$N，那些日子...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5331 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5331, 'zhTW', '不，恐怕我不能幫你。你的技能遠勝於我!如果你想學習更多的知識，跟達納蘇斯工匠區的夜精靈泰龍尼斯談談。他擁有令人驚異的技能!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5333 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5333, 'zhTW', '嗯，我宣告!他是個新學生!只要你再多掌握一點技能，我會很樂意將我所知道的一切都教給你的。去跟格雷塔談談，好嗎?她會教你如何速成技能的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5334 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5334, 'zhTW', '你的技術在進步,很快你就會擁有一家你自己的皮革商店。我很高興能幫你，$N。我的速度就只能這麼快了，你知道嗎?有那麼多工作要做!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5335 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5335, 'zhTW', '這些棲息在這片荒地上的科多獸的獸皮最為堅韌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5336 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5336, 'zhTW', '我不能再教你啦:你所掌握的技能已經超過我了。去雷霆崖中央平原西北部的商店找牛頭人猶納吧。她會為你提供更多訓練的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5338 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5338, 'zhTW', '我不會給一個學徒訓練。去貧瘠之地的哀嚎洞穴找牛頭人瓦多爾吧，他會幫助你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5339 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5339, 'zhTW', '你來這裡是為了進一步的訓練?抖去你身上的塵土吧，讓我們馬上開始工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5340 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5340, 'zhTW', '我的斧頭經歷過多場戰事，我喜歡將它帶在身邊。敵人曾數次入侵我們的首都，但是別怕:我們總能擊退他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5341 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5341, 'zhTW', '我不能為你提供更多的訓練啦:你的製革技能已經超過我啦。你應該去那兒找猶納談談。如果需要的話我會為你擔保的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5343 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5343, 'zhTW', '你的技藝不足以學會我所教授的。去找那邊的瑪克談談。他可以幫你直到你準備好學習更高階的課程。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5344 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5344, 'zhTW', '我目前對你的進步感到很滿意。很顯然大地之母已經賦予你的雙手以靈感了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5345 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5345, 'zhTW', '現在，我們在這片大陸上只有一處立足之地，但是人類是永遠不可能打敗我們的。他們很快就會受到報復。我們會割下他們說謊的舌頭，懲戒他們的背叛行為。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5346 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5346, 'zhTW', '要是我能的話，我會教你的，但我力所不及。去跟雷霆崖中央高地西北部的商店找牛頭人猶納談談。她擁有真正的才能。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5348 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5348, 'zhTW', '經過我的訓練,你有更多的膽識,現在你去找在奧格瑞瑪的獸人卡馬吧,他更加適合你現在的情況.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5350 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5350, 'zhTW', '我忙嗎?這話什麼意思?你覺得我只是成天站在這兒玩弄手指嗎?如果你想買些什麼的話，跟罕杜爾談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5351 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5351, 'zhTW', '你在我這裡學不到新的東西了;你知道的已經很多了。如果你想得到更多培訓的話，去找雷霆崖中央高原西北方商店裡的牛頭人尤納談談。替我向她致意，怎麼樣?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5353 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5353, 'zhTW', '你在學習好基礎知識之前不能學我的技藝。如果你對訓練感興趣的話就去找卡瑪瑞談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5354 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5354, 'zhTW', '奧格瑪地形迂迴曲折，能有效地阻止入侵者。你能想像這些矮小的地精在多麼短的時間內就迷失方向嗎?哈哈!如果夠幸運的話，我會追蹤到他們，將他們變成我的寵物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5355 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5355, 'zhTW', '我生前是一名圖書管理員，與戰爭和災難無緣。我從未想過要變成現在這樣。另一方面，現在我能主宰自己，我是不會不戰而降的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5356 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5356, 'zhTW', '你的能力已經超過我了。走吧。嗯，去雷霆崖中央高地西北部的商店找牛頭人猶納。她擁有強大的力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5358 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5358, 'zhTW', '我沒時間教你這些初學者了,去找那邊的丹格斯吧,他是個不錯的老師', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5359 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5359, 'zhTW', '起先，我在魔法區開設商店，但是那兒太嘈雜啦。儘管我進行了重新部署，除了有些學生堅持要向我求學之外，環境還是得到了相當的改善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5360 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5360, 'zhTW', '月神已經賜予夜精靈很多禮物。作為回報，我們有職責保衛這些森林免受部落帶來的惡魔的汙染。', '月神已經賜予夜精靈很多禮物。作為回報，我們有職責保衛這些森林免受部落帶來的惡魔的汙染。', '月神已經賜予夜精靈很多禮物。作為回報，我們有職責保衛這些森林免受部落帶來的惡魔的汙染。', '月神已經賜予夜精靈很多禮物。作為回報，我們有職責保衛這些森林免受部落帶來的惡魔的汙染。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5361 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5361, 'zhTW', '繼續培訓你已經超越我的能力了。與達納蘇斯工匠區的泰龍尼斯談談。他總是很願意幫助有才能的學生。', '繼續培訓你已經超越我的能力了。與達納蘇斯工匠區的泰龍尼斯談談。他總是很願意幫助有才能的學生。', '繼續培訓你已經超越我的能力了。與達納蘇斯工匠區的泰龍尼斯談談。他總是很願意幫助有才能的學生。', '繼續培訓你已經超越我的能力了。與達納蘇斯工匠區的泰龍尼斯談談。他總是很願意幫助有才能的學生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5363 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5363, 'zhTW', '我只教那些掌握基本指示的學生。你必須在達納蘇斯工匠區找到夜精靈達麗亞娜。她的技能與你的是完美的互補。', '我只教那些掌握基本指示的學生。你必須在達納蘇斯工匠區找到夜精靈達麗亞娜。她的技能與你的是完美的互補。', '我只教那些掌握基本指示的學生。你必須在達納蘇斯工匠區找到夜精靈達麗亞娜。她的技能與你的是完美的互補。', '我只教那些掌握基本指示的學生。你必須在達納蘇斯工匠區找到夜精靈達麗亞娜。她的技能與你的是完美的互補。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5364 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5364, 'zhTW', '在你開始切割皮革之前一定要仔細檢查尺寸。我們可不能浪費材料。', '在你開始切割皮革之前一定要仔細檢查尺寸。我們可不能浪費材料。', '在你開始切割皮革之前一定要仔細檢查尺寸。我們可不能浪費材料。', '在你開始切割皮革之前一定要仔細檢查尺寸。我們可不能浪費材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5373 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5373, 'zhTW', '你必須去西部荒野的海洋搜尋，朝正西方西─金海岸礦坑與海岸交接處往西北方向。海岸邊有一隻錨，看來附近一定有艘沉船。水下的壓力很大;如果遊得太遠的話，即使是最優秀的潛水者也可能死於疲勞。$B$B去找一處適宜的自然環境吧，$N─這附近有起泡的海底裂縫，能在深海潛水時提供氧氣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5374 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5374, 'zhTW', '在銀松森林北流海岸邊緣，海灘上擱著一艘廢棄的船。船隻以西有你要找的東西;遊得太遠的話，你會因疲勞無法游回海岸的。海床上有一隻上了鎖的帶鎖箱，等著你去取呢。$B$B要是沒有人幫忙的話，潛到這樣的深度會承受極大的水壓，要小心;海床上有一道裂縫，能釋放出氣泡，有助於你尋找那半塊墜飾。好好利用吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5375 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5375, 'zhTW', '在黑海岸的北面流淌著壁泉河，發源於現今的費伍德森林。隨著河流流出並匯入薄霧海，一直蜿蜒到海洋北部最深處。一處被人們稱為石爪的地方有你要找的東西。$B$B要當心─蛇頸龍聚集在石爪那裡，會攻擊侵入他們領地的人。', '在黑海岸的北面流淌著壁泉河，發源於現今的費伍德森林。隨著河流流出並匯入薄霧海，一直蜿蜒到海洋北部最深處。一處被人們稱為石爪的地方有你要找的東西。$B$B要當心─蛇頸龍聚集在石爪那裡，會攻擊侵入他們領地的人。', '在黑海岸的北面流淌著壁泉河，發源於現今的費伍德森林。隨著河流流出並匯入薄霧海，一直蜿蜒到海洋北部最深處。一處被人們稱為石爪的地方有你要找的東西。$b$b要當心─蛇頸龍聚集在石爪那裡，會攻擊侵入他們領地的人。', '在黑海岸的北面流淌著壁泉河，發源於現今的費伍德森林。隨著河流流出並匯入薄霧海，一直蜿蜒到海洋北部最深處。一處被人們稱為石爪的地方有你要找的東西。$B$B要當心─蛇頸龍聚集在石爪那裡，會攻擊侵入他們領地的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5376 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5376, 'zhTW', '在貧瘠之地的東北部，有一處受到嚴重汙染的水池。當地人稱它為淤泥沼澤;風險投資公司將水晶般幽藍的水域變成工業副產品和廢棄品的泥潭。在沼澤的中心有你要找的東西，$N。$B$B要小心，風險投資公司絕不容許有人入侵，他們將不為其工作的人都當作入侵者。你作為自然的保衛者，更是他們極力對抗的目標。', '在貧瘠之地的東北部，有一處受到嚴重汙染的水池。當地人稱它為淤泥沼澤;風險投資公司將水晶般幽藍的水域變成工業副產品和廢棄品的泥潭。在沼澤的中心有你要找的東西，$N。$B$B要小心，風險投資公司絕不容許有人入侵，他們將不為其工作的人都當作入侵者。你作為自然的保衛者，更是他們極力對抗的目標。', '在貧瘠之地的東北部，有一處受到嚴重汙染的水池。當地人稱它為淤泥沼澤；風險投資公司將水晶般幽藍的水域變成工業副產品和廢棄品的泥潭。在沼澤的中心有你要找的東西，$N。$b$b要小心，風險投資公司絕不容許有人入侵，他們將不為其工作的人都當作入侵者。你作為自然的保護者，更是他們極力對抗的目標。', '在貧瘠之地的東北部，有一處受到嚴重汙染的水池。當地人稱它為淤泥沼澤;風險投資公司將水晶般幽藍的水域變成工業副產品和廢棄品的泥潭。在沼澤的中心有你要找的東西，$N。$B$B要小心，風險投資公司絕不容許有人入侵，他們將不為其工作的人都當作入侵者。你作為自然的保衛者，更是他們極力對抗的目標。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5393 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5393, 'zhTW', '草地柔軟青蔥。空氣清新，陽光明媚，歌聲飄飄。泰達希爾的夢想終成現實。但是為什麼我感到有種不詳的預兆?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5394 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5394, 'zhTW', '你的進步已經超越了我能教授的技藝了。現在到辛特蘭的鷹巢山去找矮人德拉克·石拳談話。他的作品太棒了，比我的好多了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5396 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5396, 'zhTW', '$g尊敬的先生:女士;，在你掌握制皮的更多知識之前，我還不能幫助你，對此我感到很遺憾。跟法多恩或達麗亞娜談談。他們能教你所需的技能。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5397 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5397, 'zhTW', '別試圖將你的意願強加到皮革上。而是讓其天然的特性顯示出自身的形狀和功能。這不是一場戰役。與皮革協同工作，而不是與其作對。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5398 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5398, 'zhTW', '針太細，線太粗，針腳倒還不錯。我們與索爾和其他人的合約將繼續有效。部落不會被驅逐出這片土地的。', '針太細，線太粗，針腳倒還不錯。我們與索爾和其他人的合約將繼續有效。部落不會被驅逐出這片土地的。', '針太細，線太粗，針腳倒還不錯。我們與薩爾和其它人的合約將繼續有效。部落不會被驅逐出這片土地的。', '針太細，線太粗，針腳倒還不錯。我們與索爾和其他人的合約將繼續有效。部落不會被驅逐出這片土地的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5399 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5399, 'zhTW', '我的才能有限，你也已經達到了。恭喜你，$N。你的下一站應該是菲拉斯的莫沙徹營地。牛頭人哈拉納·鐵皮住在那裡;她的技術很有聲望。', '我的才能有限，你也已經達到了。恭喜你，$N。你的下一站應該是菲拉斯的莫沙徹營地。牛頭人哈拉納·鐵皮住在那裡;她的技術很有聲望。', '我的才能有限，你也已經達到了。恭喜你，$N。你的下一站應該是菲拉斯的莫沙徹營地。牛頭人哈拉納·鐵皮住在那裡;她的技術很有聲望。', '我的才能有限，你也已經達到了。恭喜你，$N。你的下一站應該是菲拉斯的莫沙徹營地。牛頭人哈拉納·鐵皮住在那裡;她的技術很有聲望。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5401 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5401, 'zhTW', '我自己不久前也是一個新手，所以我覺得我不太適合教你。試著跟那邊的塔恩或是瑪克談談。他們之中應該有人能回答你的問題。', '我自己不久前也是一個新手，所以我覺得我不太適合教你。試著跟那邊的塔恩或是瑪克談談。他們之中應該有人能回答你的問題。', '我自己不久前也是一個新手，所以我覺得我不太適合教你。試著跟那邊的塔恩或是瑪克談談。他們之中應該有人能回答你的問題。', '我自己不久前也是一個新手，所以我覺得我不太適合教你。試著跟那邊的塔恩或是瑪克談談。他們之中應該有人能回答你的問題。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5402 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5402, 'zhTW', '凱恩把我們帶到了一片充滿希望的大地。我們很幸運，因此我們再把好運帶給別人。這就是我為什麼開始教學的原因，$N。', '凱恩把我們帶到了一片充滿希望的大地。我們很幸運，因此我們再把好運帶給別人。這就是我為什麼開始教學的原因，$N。', '凱恩把我們帶到了一片充滿希望的大地。我們很幸運，因此我們再把好運帶給別人。這就是我為什麼開始教學的原因，$N。', '凱恩把我們帶到了一片充滿希望的大地。我們很幸運，因此我們再把好運帶給別人。這就是我為什麼開始教學的原因，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5403 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5403, 'zhTW', '我可以利用在這兒找到的材料製作有趣的東西。這些山林中有許多奇怪的生物!去殺死它們，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5405 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5405, 'zhTW', '我喜歡機會;你不喜歡嗎?啊，當然你也喜歡。這就是你要按我說的去做的原因。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5406 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5406, 'zhTW', '我不是來教那些剛離開搖籃的寶寶的。你離我對學生的要求還差遠了。你不過是個年幼的$g小夥子:姑娘;，你最好別在這兒煩我了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 5407 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5407, 'zhTW', '我所有的作品都必須由買主親自來訂購。奧爾文常常要我改變這個習慣，但是我就是不改。看看你周圍吧，無數戰士還指望我給他們打造裝甲呢。', '我所有的作品都必須由買主親自來訂購。奧爾文常常要我改變這個習慣，但是我就是不改。看看你周圍吧，無數戰士還指望我給他們打造裝甲呢。', '我所有的作品都必須由買主親自來訂購。奧爾文常常要我改變這個習慣，但是我就是不改。看看你周圍吧，無數戰士還指望我給他們打造裝甲呢。', '我所有的作品都必須由買主親自來訂購。奧爾文常常要我改變這個習慣，但是我就是不改。看看你周圍吧，無數戰士還指望我給他們打造裝甲呢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
