INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5408, 'zhTW', '我真希望有更多像你一樣的學生。很少有人會冒險深入敵境。我佩服你的勇氣。', '我真希望有更多像你一樣的學生。很少有人會冒險深入敵境。我佩服你的勇氣。', '我真希望有更多像你一樣的學生。很少有人會冒險深入敵境。我佩服你的勇氣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
