INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5409, 'zhTW', '我不會在這場戰爭中讓步。我不分晝夜的製造新裝甲，還把舊的裝甲修補好。我沒時間做其他任務。你願幫我分擔一些嗎?', '我不會在這場戰爭中讓步。我不分晝夜的製造新裝甲，還把舊的裝甲修補好。我沒時間做其他任務。你願幫我分擔一些嗎?', '我不會在這場戰爭中讓步。我不分晝夜的製造新裝甲，還把舊的裝甲修補好。我沒時間做其它任務。你願幫我分擔一些嗎?', '我不會在這場戰爭中讓步。我不分晝夜的製造新裝甲，還把舊的裝甲修補好。我沒時間做其他任務。你願幫我分擔一些嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
