DELETE FROM `npc_text_locale` WHERE `ID` = 5426 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5426, 'zhTW', '我知道一些，但我不是專家。祝你好遠，瑪加爾也是。他就站在商店後面。看看他是否能幫助你，但是小心別惹惱他。他脾氣有些暴躁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
