INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5541, 'zhTW', '你的才能出眾!你真是有靈性。你要想繼續追求知識的話，找暴風城的喬吉奧·波利羅談談。他深受眾人尊敬，而且他能深化對你的指導。', '你的才能出眾!你真是有靈性。你要想繼續追求知識的話，找暴風城的喬吉奧·波利羅談談。他深受眾人尊敬，而且他能深化對你的指導。', '你的才能出眾!你真是有靈性。你要想繼續追求知識的話，找暴風城的喬吉奧·波利羅談談。他深受眾人尊敬，而且他能深化對你的指導。', '你的才能出眾!你真是有靈性。你要想繼續追求知識的話，找暴風城的喬吉奧·波利羅談談。他深受眾人尊敬，而且他能深化對你的指導。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
