INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5543, 'zhTW', NULL, '這是必須學的基礎知識. 和站在我旁邊的緹娜談談吧她可以教你,過一段時間才來找我', NULL, '有些基礎知識是必須要學的，訓練師就在旁邊，和他談談再回來找我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
