INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5595, 'zhTW', '這隻黑豹傳言在夜精靈和他們的同盟面前很馴服，這使她成為一個更有價值的對手。薩杜布拉的獵殺路線把她從瑞恩伍德居所趕到了我們的西方，最終在那裡的正西方登陸。她的皮毛是瀝青一般的顏色，而她的速度也不能低估。', '這隻黑豹傳言在夜精靈和他們的同盟面前很馴服，這使她成為一個更有價值的對手。薩杜布拉的獵殺路線把她從瑞恩伍德居所趕到了我們的西方，最終在那裡的正西方登陸。她的皮毛是瀝青一般的顏色，而她的速度也不能低估。', '這隻黑豹傳言在夜精靈和他們的同盟面前很馴服，這使她成為一個更有價值的對手。薩杜布拉的獵殺路線把她從瑞恩伍德居所趕到了我們的西方，最終在那裡的正西方登陸。她的皮毛是瀝青一般的顏色，而她的速度也不能低估。', '這隻黑豹傳言在夜精靈和他們的同盟面前很馴服，這使她成為一個更有價值的對手。薩杜布拉的獵殺路線把她從瑞恩伍德居所趕到了我們的西方，最終在那裡的正西方登陸。她的皮毛是瀝青一般的顏色，而她的速度也不能低估。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
