INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5724, 'zhTW', '你不是戰士...你在我的訓練課程中會連一天都堅持不下去的!$B$B認為$g他是:她是;一個戰士的$c。哈!', '你不是戰士...你在我的訓練課程中會連一天都堅持不下去的!$B$B認為$g他是:她是;一個戰士的$c。哈!', '你不是戰士……你在我的訓練課程中會連一天都堅持不下去的!$b$b認為$g他是:她是;一個戰士的$c。哈!', '你不是戰士……你在我的訓練課程中會連一天都堅持不下去的!$B$B認為$g他是:她是;一個戰士的$c。哈!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
