INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5725, 'zhTW', '孩子，我看不出你具備戰士的精神。我不會訓練你這樣的$c的。', '孩子，我看不出你具備戰士的精神。我不會訓練你這樣的$c的。', '孩子，我看不出你具備戰士的精神。我不會訓練你這樣的$c的。', '孩子，我看不出你具備戰士的精神。我不會訓練你這樣的$c的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
