INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5834, 'zhTW', '瑟銀兄弟會懂得如何製造火焰之王的神聖武器，但是我們缺乏人力，無法獲得製造武器所需的材料。$B$B我，羅克圖斯·暗契，兄弟會賦予我強大的力量，用珍貴的藥方來交換從熔火之心收集的材料。$B$B給個價吧，$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
