INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5840, 'zhTW', '皇家藥劑師學會對愚蠢的傢伙可沒有耐心，我也一樣。或許下次我們談到戰馬的時候，你會被當作是幽暗城的貴族。到那時...', '皇家藥劑師學會對愚蠢的傢伙可沒有耐心，我也一樣。或許下次我們談到戰馬的時候，你會被當作是幽暗城的貴族。到那時...', '皇家藥劑師學會對愚蠢的傢伙可沒有耐心，我也一樣。或許下次我們談到戰馬的時候，你會被當作是幽暗城的貴族。到那時……', '皇家藥劑師學會對愚蠢的傢伙可沒有耐心，我也一樣。或許下次我們談到戰馬的時候，你會被當作是幽暗城的貴族。到那時……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
