INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5842, 'zhTW', '很抱歉$g兄弟:姐妹;，但是在確定買主受到暗矛部族的崇拜之前，我不會將迅猛龍賣給他的。當你證明自己受到我們的崇拜之後，我才會把迅猛龍賣給你。', '很抱歉$g兄弟:姐妹;，但是在確定買主受到暗矛部族的崇拜之前，我不會將迅猛龍賣給他的。當你證明自己受到我們的崇拜之後，我才會把迅猛龍賣給你。', '很抱歉$g兄弟:姐妹;，但是在確定買主是暗矛部落的貴族之前，我不會將迅猛龍賣給他的。當你證明自己是部落貴族之後，我才會把迅猛龍賣給你。', '很抱歉$g兄弟:姐妹;，但是在確定買主是暗矛部落的貴族之前，我不會將迅猛龍賣給他的。當你證明自己是部落貴族之後，我才會把迅猛龍賣給你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
