INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (5843, 'zhTW', '你並不為我的人民所知。科多獸是強大的坐騎，它是我的人民愛心和關懷的產物;所以它不能給陌生人。在雷霆崖的長老認為你的品德高尚之前，我不能賣給你科多獸。', '你並不為我的人民所知。科多獸是強大的坐騎，它是我的人民愛心和關懷的產物;所以它不能給陌生人。在雷霆崖的長老認為你的品德高尚之前，我不能賣給你科多獸。', '你並不為我的人民所知。科多獸是強大的坐騎，它是我的人民愛心和關懷的產物;所以它不能給陌生人。在雷霆崖的長老認為你的品德高尚之前，我不能賣給你科多獸。', '你並不為我的人民所知。科多獸是強大的坐騎，它是我的人民愛心和關懷的產物;所以它不能給陌生人。在雷霆崖的長老認為你的品德高尚之前，我不能賣給你科多獸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
