INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6100, 'zhTW', '我已經做過接觸了，$N。那是『冰雪之王』洛克霍拉。他認為我們的事業很有價值--我們給大地的祭品十分充足。他很快就來了...做好準備。', '我已經做過接觸了，$N。那是『冰雪之王』洛克霍拉。他認為我們的事業很有價值--我們給大地的祭品十分充足。他很快就來了...做好準備。', '我已經做過接觸了，$N。那是冰雪之王洛克霍拉。他認為我們的事業很有價值--我們給大地的祭品十分充足。他很快就來了……做好準備。', '我已經做過接觸了，$N。那是‘冰雪之王’洛克霍拉。他認為我們的事業很有價值--我們給大地的祭品十分充足。他很快就來了……做好準備。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
