INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6107, 'zhTW', '艦隊整裝待發，$N。你必須帶上火炬，並將它放在戰場中心的東部環形山。在艦隊確定其位置時你要保護好火炬。', '艦隊整裝待發，$N。你必須帶上火炬，並將它放在戰場中心的東部環形山。在艦隊確定其位置時你要保護好火炬。', '艦隊整裝待發，$N。你必須帶上火炬，並將它放在戰場中心的東部環形山。在艦隊確定其位置時你要保護好火炬。', '艦隊整裝待發，$N。你必須帶上火炬，並將它放在戰場中心的東部環形山。在艦隊確定其位置時你要保護好火炬。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
