INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6134, 'zhTW', '$N, 你在等什麼?  到戰場找到特拉元帥並且交個他攻擊命令.  當他得到命令,他和她的部屬向部落進攻並那些那些戰俘!', '$N, 你在等什麼?  到戰場找到特拉元帥並且交個他攻擊命令.  當他得到命令,他和她的部屬向部落進攻並那些那些戰俘!', NULL, '你還在等什麼？去征戰平原找到特拉瓦雷元帥下達攻擊命令。一旦他接到了命令，他和他的部隊將會向部落發起猛烈的衝鋒，絕不手下留情！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6153 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6153, 'zhTW', '如果你想在塞納里奧議會中找尋某些檔案的話，我就是那個你要交談的人。你首先要知道要尋找的確切資訊，那樣我才能幫你。$B$B看看那個，真是光彩奪目呀!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6154 AND `Locale` = 'zhTW';
