INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6158, 'zhTW', '$n，你準備好完成終極任務了。刻在熔火之心地面上的熾熱的符文是通向火海的導管,它們的存在既是對我們的侵犯，又是火焰之王的力量源泉。必須把它們撲滅!$B$B要熄滅符文，拿一小瓶水之精華。把它倒在符文上,火焰就會熄滅,這會使其變得毫無用處並能削弱我們的敵人!', 'Hey there, friend. My name\'s Remy. I\'m from Redridge to the east, and came here looking for business, looking for business. You got any...got any??', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6159 AND `Locale` = 'zhTW';
