INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6178, 'zhTW', '我被穆維裡克這個魯莽的傻子擊中了。我擔心要是不能將這東西送到基地的話，所有的事情都會失敗的!必須阻止穆維裡克和他的騎兵隊!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6179 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6179, 'zhTW', '真不敢相信…我在中央非軍事區執行例行偵察任務時，事情變得一團糟。我看見部落空軍指揮官穆維裡克擊倒了艾克曼和斯里多爾!怒不可遏的我，撇下我的僚機，把那個愛現自大的穆維裡克打了下來。不幸的是，他在墜機之前擊中了我的獅鷲獸，我也隨之跌下。結局就是我被這些野蠻的傢伙給活逮了。$B$B我必須返回基地!幫幫我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6180 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6180, 'zhTW', '當我的獅鷲獸墜落時，我聽到了他們嘲弄的笑聲，$c。$B$B「斯里多爾， 你太差勁了!」他們大聲嚷道。$B$B沒有人敢對斯里多爾那樣說話!幫我離開這裡，我會讓他們知道我的厲害!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6193 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6193, 'zhTW', '這片森林容易使人迷路!要小心。', '這片森林容易使人迷路!要小心。', '這片森林容易使人迷路!要小心。', '這片森林容易使人迷路!要小心。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
