INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6291, 'zhTW', '我可沒法教你戰鬥時如何保持優雅姿態，我只能教你如何使用武器。', '我可沒法教你戰鬥時如何保持優雅姿態，我只能教你如何使用武器。', '我可沒法教你戰鬥時如何保持優雅姿態，我只能教你如何使用武器。', '我可沒法教你戰鬥時如何保持優雅姿態，我只能教你如何使用武器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
