INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6317, 'zhTW', '再有一些坐騎我們的獸欄就滿啦。士兵，讓我來保管它們吧。我會從這兒牽走一些。', '再有一些坐騎我們的獸欄就滿啦。士兵，讓我來保管它們吧。我會從這兒牽走一些。', '再有一些坐騎我們的馬廄就滿啦。士兵，讓我來保管它們吧。我會從這兒牽走一些。', '再有一些坐騎我們的馬廄就滿啦。士兵，讓我來保管它們吧。我會從這兒牽走一些。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6333 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6333, 'zhTW', '很高興遇見你，$N。要做的事情還很多，我們必須抓緊時間。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6334 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6334, 'zhTW', '願塞納留斯指引你，$c。$B$B我和我的姐妹身負重任，從塞納里奧議會來到這片被汙染的土地。但是在我詢問的人中，只有那些足夠強大的人才告訴我說─派遣能力較低的人是愚蠢的做法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6335 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6335, 'zhTW', '我和我的姐妹從石爪山脈來到這兒，想要終止數年來的悲劇。不幸的是，我們還不夠強大，無法獨立完成目標，想向你這樣的人尋求幫助。$B$B如果你足夠強大，我們就談談任務的詳細情況，$c。如果你還不夠強大，那麼，為了你的安全著想，就到此為止吧。', '我和我的姐妹從石爪山脈來到這兒，想要終止數年來的悲劇。不幸的是，我們還不夠強大，無法獨立完成目標，想向你這樣的人尋求幫助。$B$B如果你足夠強大，我們就談談任務的詳細情況，$c。如果你還不夠強大，那麼，為了你的安全著想，就到此為止吧。', '我和我的姐妹從石爪山脈來到這兒，想要終止數年來的悲劇。不幸的是，我們還不夠強大，無法獨立完成目標，想向你這樣的人尋求幫助。$b$b如果你足夠強大，我們就談談任務的詳細情況，$c。如果你還不夠強大，那麼，為了你的安全著想，就到此為止吧。', '我和我的姐妹從石爪山脈來到這兒，想要終止數年來的悲劇。不幸的是，我們還不夠強大，無法獨立完成目標，想向你這樣的人尋求幫助。$B$B如果你足夠強大，我們就談談任務的詳細情況，$c。如果你還不夠強大，那麼，為了你的安全著想，就到此為止吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6336 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6336, 'zhTW', '向你致意，$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6353 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6353, 'zhTW', '在這世上，我已經不需要什麼立足之地了，$c。部族...所有的部族成員將看見。他們相互交戰，這是為了什麼?遍地是禿鷹留下的骸骨...軍團大肆侵犯我們的土地...呸!$B$B半人馬應該為他們的遺產感到驕傲─這些遺產就跟夜精靈或獸人的遺產一樣高貴─現在是我們效仿的時候啦!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6354 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6354, 'zhTW', '最後，我從將我禁錮在此的腐化中解脫了……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6373 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6373, 'zhTW', '感謝你所做的一切，$N。$B$B請保管好權杖，它可以幫你抵禦那些入侵此地的邪惡力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6375 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6375, 'zhTW', '我的權杖……這麼多年過去了……你終於重新得到它了!你真是這兒的救世主……$B$B請仔細聽我說，$N。只有在瑪拉頓之石才能將權杖的杖頭和杖身結合在一起。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6377 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6377, 'zhTW', '在繁複的色彩中出現一條小路。$B$B被光線映襯得閃閃發光。$B$B你從水底浮上來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6378 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6378, 'zhTW', '在瑪拉頓大門附近的橘色和紫色通道之間還有一條道路。$B$B你手中的權杖便是鑰匙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6379 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6379, 'zhTW', '我越來越疲憊了……$B$B從這兒你可以看見瀑布，$n……要是你敢再次進入瑪拉頓的大門，權杖將賦予你抵達那兒的能力。$B$B在瑪拉頓的入口附近，你會看見一條通往洞穴之下的通道。在遠古遺址處使用權杖講創造傳送門，你就可進入瑪拉頓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6380 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6380, 'zhTW', '很久以前，我和我的森林女神姐妹們曾進入這些洞穴，想釋放我的叔叔札爾塔倍受折磨的靈魂。但是，已經充斥了所有洞穴的腐化力量很快擊敗了我們。$B$B我們註定要在此迷失方向;毒素侵蝕了我們的頭腦……$B$B儘管現在我的靈魂已經安息，但是我知道我沒能完成任務。我要為此承擔巨大的悲傷……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6381 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6381, 'zhTW', '啊，札爾塔……<塞雷布拉斯把頭扭了過去。>$B$B我的父親雷姆洛斯試圖阻止他……$B$B札爾塔太頑固了，當他愛上一位土元素公主時，我父親就知道他們的結合將受到詛咒，但是札爾塔拒絕聽從父親的意見。$B$B他因此變成了半人馬。他們生下來就帶著畸形的軀體，並充滿仇恨;我的叔叔札爾塔被自己的親戚所殺……$B$B那個邪惡的瑟萊德絲公主，還在水晶洞穴內守護著他的遺體。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6383 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6383, 'zhTW', '歡迎來到探險者協會。如果你需要資訊，而又剛好是屬於書面形式的，我也許能幫你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6384 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6384, 'zhTW', '潛伏在瑪拉頓的毒素開始滲入我的頭腦，我逐漸喪失對事實的判斷力。我的林精姐妹們擔心我會被惡魔利用，她們悄悄地拿走了我的權杖，將權杖斷成兩截，藏在洞穴中。$B$B很快，她們也喪失了理智，兩段權杖也因無人看守，成了維利塔恩的囊中之物。那個薩特將一截權杖交給邪惡的元素諾克賽恩看管，另一截則由他自己保管至今。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6385 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6385, 'zhTW', '沒有結合權杖兩部分所需的咒語，維利塔恩領主是無法使用權杖的。但是，我已經從維利塔恩的詛咒中解放啦，如果你能將權杖的兩部分交給我─權杖的頭部和杖身，我會幫助你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6393 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6393, 'zhTW', '你問到塞納留斯的兒子雷姆洛斯和札爾塔。$B$B我的父親雷姆洛斯強壯英俊，我的叔叔札爾塔矮小靈動。雖然兩人受到大家的一致尊重，但是札爾塔總認為自己無法得到雷姆洛斯所享受的榮耀和受到的關注。$B$B我和我的姐妹們出生後，札爾塔在嫉妒心的驅使下，想要超越他的兄弟……他自作自受。即使事情已經過去了這麼久，我心中仍悲慟不已……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6413 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6413, 'zhTW', '你好，$N。我是葛列格里·維克多醫生，部落的首席外科醫生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6414 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6414, 'zhTW', '很高興再次見到你，$N醫生。我看著你逐步成長，我敢說現在是你學習更高的繃帶技能的時候啦。$B$B一旦你的技能得到提高，就回來找我，我會把我所知的一切都教給你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6415 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6415, 'zhTW', '你好，$N。我是古斯塔夫·範沃森醫生，聯盟的首席外科醫生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6433 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6433, 'zhTW', '嗨，$N!很高興你來看我。我們正準備對征戰平原發動一場規模浩大的地面攻擊!等到霜狼突擊隊隊長一聲令下，他和他的部隊將給予聯盟致命的攻擊!$B$B你想傳達這些命令嗎，$N?加瑞克在征戰平原等著你呢……', '嗨，$N!很高興你來看我。我們正準備對征戰平原發動一場規模浩大的地面攻擊!等到霜狼突擊隊隊長一聲令下，他和他的部隊將給予聯盟致命的攻擊!$B$B你想傳達這些命令嗎，$N?加瑞克在征戰平原等著你呢……', '嗨，$N!很高興你來看我。我們正準備對征戰平原發動一場規模浩大的地面攻擊!等到霜狼突擊隊隊長一聲令下，他和他的部隊將給予聯盟致命的攻擊!$b$b你想傳達這些命令嗎，$N?加瑞克在征戰平原等著你呢……', '嗨，$N!很高興你來看我。我們正準備對征戰平原發動一場規模浩大的地面攻擊!等到霜狼突擊隊隊長一聲令下，他和他的部隊將給予聯盟致命的攻擊!$B$B你想傳達這些命令嗎，$N?加瑞克在征戰平原等著你呢……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6435 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6435, 'zhTW', '能在奧特蘭克山谷找到你這樣經驗豐富的傢伙真好，$N。我們的軍需不夠，無法發動對奧特蘭克山谷的地面攻擊...跟我們的軍需官談談─他會告訴你如何增加我們的軍需儲備。', '能在奧特蘭克山谷找到你這樣經驗豐富的傢伙真好，$N。我們的軍需不夠，無法發動對奧特蘭克山谷的地面攻擊...跟我們的軍需官談談─他會告訴你如何增加我們的軍需儲備。', '能在奧特蘭克山谷找到你這樣經驗豐富的傢伙真好，$N。我們的軍需不夠，無法發動對奧特蘭克山谷的地面攻擊……跟我們的軍需官談談——他會告訴你如何增加我們的軍需儲備。', '能在奧特蘭克山谷找到你這樣經驗豐富的傢伙真好，$N。我們的軍需不夠，無法發動對奧特蘭克山谷的地面攻擊……跟我們的軍需官談談─他會告訴你如何增加我們的軍需儲備。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6437 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6437, 'zhTW', '你!$N!你在山谷這兒遊蕩什麼呢?在奧特蘭克到處都是聯盟的敵人!我們必須趕走它們!$B$B我們的軍需不夠，無法發動大規模的地面攻擊,跟我們的軍需官談談。他會告訴你如何增加我們的軍需。', '你!$N!你在山谷這兒遊蕩什麼呢?在奧特蘭克到處都是聯盟的敵人!我們必須趕走它們!$B$B我們的軍需不夠，無法發動大規模的地面攻擊,跟我們的軍需官談談。他會告訴你如何增加我們的軍需。', '你!$N!你在山谷這兒遊蕩什麼呢?在奧特蘭克到處都是聯盟的敵人!我們必須趕走它們!$b$b我們的軍需不夠，無法發動大規模的地面攻擊,跟我們的軍需官談談。他會告訴你如何增加我們的軍需。', '你!$N!你在山谷這兒遊蕩什麼呢?在奧特蘭克到處都是聯盟的敵人!我們必須趕走它們!$B$B我們的軍需不夠，無法發動大規模的地面攻擊,跟我們的軍需官談談。他會告訴你如何增加我們的軍需。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6475 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6475, 'zhTW', '我負責霜狼氏族的軍隊招募工作。作為一名霜狼士兵，如果你的等級足夠高的話，就來向我報到吧。$B$B在冰冷的戰場上，你會獲得榮譽和尊重的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6476 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6476, 'zhTW', '你好，$r!我是哈格丁中尉，是負責招募雷矛守衛的官員。$B$B你在雷矛軍隊中獲得一定的威望後再來找我吧，我會升級你的徽記的。如果你丟失了徽記，我也能再給你一枚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6491 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6491, 'zhTW', '現在還不是時候，我將幫助您復活……出個價吧。', '現在還不是讓你長眠的時候。我會幫你起死回生...但你也要為此付出一些代價。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6513 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6513, 'zhTW', '我們的祖先教誨說，集體的力量勝過個人的力量。你想要加入公會為了雷霆崖的榮譽而戰嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6514 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6514, 'zhTW', '是的，你看起來是個領導者。你是來這裡組織公會與聯盟作戰嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6520 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6520, 'zhTW', 'MISSING TEXT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6533 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6533, 'zhTW', '你好，$c。我是部落的勇士羅卡洛，是索爾的僕人，是野獸與野性之王。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6534 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6534, 'zhTW', '你向藍龍軍團要求什麼?', '你向藍龍軍團要求什麼?', '你向藍龍要求什麼?', '你向藍龍軍團要求什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6535 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6535, 'zhTW', '奈辛瓦里要出去狩獵。我發現幫助他做叢林狩獵的準備工作比做戰爭準備的工作輕鬆多了。儘管我錯過了戰場上的光輝歲月。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6553 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6553, 'zhTW', '我對這片森林非常熟悉，它們就像我自己的身體一樣...但是它們依然隱藏著很多值得學習的知識，當然也隱藏著很多危險。', '我對這片森林非常熟悉，它們就像我自己的身體一樣...但是它們依然隱藏著很多值得學習的知識，當然也隱藏著很多危險。', '我對這片森林非常熟悉，它們就像我身體的一部分……但是它們還蘊藏著很多值得學習的知識，當然也有很多危險。', '我對這片森林非常熟悉，它們就像我身體的一部分……但是它們還蘊藏著很多值得學習的知識，當然也有很多危險。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6555 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6555, 'zhTW', '你已經完成了泰洛尼斯的任務，感謝你所做的一切，$N。', '你已經完成了泰洛尼斯的任務，感謝你所做的一切，$N。', '你已經完成了泰洛尼斯的任務，感謝你所做的一切，$N。', '你已經完成了泰洛尼斯的任務，感謝你所做的一切，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
