INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6575, 'zhTW', '哦，很高興你已經回來啦，$N。$B$B我兄弟的靈魂已經從墮落中解脫啦，但是我得留在此地表示我的哀悼。$B$B非常感謝你的幫助，$N。', '哦，很高興你已經回來啦，$N。$B$B我兄弟的靈魂已經從墮落中解脫啦，但是我得留在此地表示我的哀悼。$B$B非常感謝你的幫助，$N。', '哦，很高興你已經回來啦，$N。$b$b我兄弟的靈魂已經從墮落中解脫啦，但是我得留在此地表示我的哀悼。$b$b非常感謝你的幫助，$N。', '哦，很高興你已經回來啦，$N。$B$B我兄弟的靈魂已經從墮落中解脫啦，但是我得留在此地表示我的哀悼。$B$B非常感謝你的幫助，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
