INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6829, 'zhTW', '哨塔高地東側是征戰平原和南部部落領土之間的要塞。$B$B部落控制著這片土地。東部霜狼哨塔保護著霜狼村和霜狼要塞的大門。$B$B部落控制著這片土地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6832 AND `Locale` = 'zhTW';
