INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6882, 'zhTW', '嗯，你殺死了國王，是嗎?這就是說你取代了他的位置。你成為了新的頭目!向國王致敬!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6883 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6883, 'zhTW', '嗯，從我跟巨魔的交戰情況來看...你不必逐一殺死這兒的所有巨魔。$B$B就在前幾天戈多克大王恢復權力，殺死以前的國王取而代之的時候，巨魔紛紛離開此地。嗯，國王的追隨者們─戈多克沒有要他們的命─立即發誓效忠新國王。$B$B誰知道呢─你饒恕的巨魔說不定會效忠於你呢...當然，這是打個比方!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6894 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6894, 'zhTW', '你現在是首領了，對嗎?祝新國王長命百歲!$B$B克雷格讓你看看戈多克酒。巨魔酒是所有酒中的極品，戈多克酒則是巨魔酒中的極品!你能從我這裡買一些，是不是國王?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6895 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6895, 'zhTW', '好吧老大，當你想要下屬為你上貢的時候，就告訴我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6896 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6896, 'zhTW', '陌生人，離開這兒吧，免得送命，它會吃掉它接觸到的一切東西的。', '陌生人，離開這兒吧，免得送命，它會吃掉它接觸到的一切東西的。', '陌生人，離開這兒吧，免得送命，它會吃掉它接觸到的一切東西的。', '陌生人，離開這兒吧，免得送命，它會吃掉它接觸到的一切東西的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6897 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6897, 'zhTW', '你知道精靈貴族嗎?你知道辛德拉古嗎?', '你知道精靈貴族嗎?你知道辛德拉古嗎?', '你知道高等精靈嗎?你知道辛德拉古嗎?', '你知道精靈貴族嗎?你知道辛德拉古嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6898 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6898, 'zhTW', '辛德拉古是艾薩拉女王最器重的秘法師。女王最重要的物品都在這些高大的城牆內秘密製造完成。$B$B永恆之井被破壞後，精靈貴族陷入渾渾噩噩的境地，一支較小的夜精靈氏族，埃德薩拉斯的王子託塞德林開始建造水晶塔，你可以在西側的城牆那兒看到那些分散在各處的水晶塔。', '辛德拉古是艾薩拉女王最器重的秘法師。女王最重要的物品都在這些高大的城牆內秘密製造完成。$B$B永恆之井被破壞後，精靈貴族陷入渾渾噩噩的境地，一支較小的夜精靈氏族，埃德薩拉斯的王子託塞德林開始建造水晶塔，你可以在西側的城牆那兒看到那些分散在各處的水晶塔。', '辛德拉古是艾薩拉女王最器重的秘法學家。女王最重要的物品都在這些高大的城牆內秘密製造完成。$b$b永恆之井被破壞後，高等精靈陷入渾渾噩噩的境地，一支較小的夜精靈氏族，埃德薩拉斯的王子託塞德林開始建造水晶塔，你可以在西側的城牆那兒看到那些分散在各處的水晶塔。', '辛德拉古是艾薩拉女王最器重的秘法師。女王最重要的物品都在這些高大的城牆內秘密製造完成。$B$B永恆之井被破壞後，精靈貴族陷入渾渾噩噩的境地，一支較小的夜精靈氏族，埃德薩拉斯的王子託塞德林開始建造水晶塔，你可以在西側的城牆那兒看到那些分散在各處的水晶塔。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6899 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6899, 'zhTW', '王子策劃將擁有巨大力量的惡魔伊莫塔爾禁錮到一個巨大的力場中。水晶塔能將潛在的能量彙集到這個力場中。$B$B一旦被囚禁，惡魔將成為埃德薩拉斯人民的能量來源。', '王子策劃將擁有巨大力量的惡魔伊莫塔爾禁錮到一個巨大的力場中。水晶塔能將潛在的能量彙集到這個力場中。$B$B一旦被囚禁，惡魔將成為埃德薩拉斯人民的能量來源。', '王子策劃將擁有巨大力量的惡魔伊莫塔爾禁錮到一個巨大的力場中。水晶塔能將潛在的能量彙集到這個力場中。$b$b一旦被囚禁，惡魔將成為埃德薩拉斯人民的能量來源。', '王子策劃將擁有巨大力量的惡魔伊莫塔爾禁錮到一個巨大的力場中。水晶塔能將潛在的能量彙集到這個力場中。$B$B一旦被囚禁，惡魔將成為埃德薩拉斯人民的能量來源。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6900 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6900, 'zhTW', '汲取的能量能維持精靈貴族的魔力，使埃德薩拉斯的人民滿足他們對魔法無盡而持續增長的渴求。$B$B數千年過去了，用於監禁惡魔伊莫塔爾以及維繫埃德薩拉斯人民生命的力量開始減弱。監禁惡魔所需的魔法就要超過所能汲取的魔法。曾經的能量機制已經不復存在。', '汲取的能量能維持精靈貴族的魔力，使埃德薩拉斯的人民滿足他們對魔法無盡而持續增長的渴求。$B$B數千年過去了，用於監禁惡魔伊莫塔爾以及維繫埃德薩拉斯人民生命的力量開始減弱。監禁惡魔所需的魔法就要超過所能汲取的魔法。曾經的能量機制已經不復存在。', '汲取的能量能維持上層精神的魔力，使埃德薩拉斯的人民滿足他們對魔法無盡而持續增長的渴求。$b$b數千年過去了，用於監禁惡魔伊莫塔爾以及維繫埃德薩拉斯人民生命的力量開始減弱。監禁惡魔所需的魔法就要超過所能汲取的魔法。曾經的能量機制已經不復存在。', '汲取的能量能維持精靈貴族的魔力，使埃德薩拉斯的人民滿足他們對魔法無盡而持續增長的渴求。$B$B數千年過去了，用於監禁惡魔伊莫塔爾以及維繫埃德薩拉斯人民生命的力量開始減弱。監禁惡魔所需的魔法就要超過所能汲取的魔法。曾經的能量機制已經不復存在。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6901 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6901, 'zhTW', '你所見到的那些在埃德薩拉斯的庭院和城牆附近遊蕩的精靈貴族鬼魂不是被戈多克巨魔或薩特所殺，而是死於王子之手!', '你所見到的那些在埃德薩拉斯的庭院和城牆附近遊蕩的精靈貴族鬼魂不是被戈多克巨魔或薩特所殺，而是死於王子之手!', '你所見到的那些在埃德薩拉斯的庭院和城牆附近遊蕩的高等精靈靈魂不是被戈多克巨魔或薩特所殺，而是死於王子之手!', '你所見到的那些在埃德薩拉斯的庭院和城牆附近遊蕩的精靈貴族鬼魂不是被戈多克巨魔或薩特所殺，而是死於王子之手!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6902 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6902, 'zhTW', '王子為了獲得永恆的生命和無盡的力量，殺死了許多人。曾經在數千人中分配的力量現在全部彙集到王子和辛德拉狂熱者身上。那些少數的倖存者不停地向水晶塔輸送能量來禁錮惡魔伊莫塔爾。$B$B一旦惡魔掙脫束縛，他一定會毀掉這片曾經繁榮的秘法之地。', '王子為了獲得永恆的生命和無盡的力量，殺死了許多人。曾經在數千人中分配的力量現在全部彙集到王子和辛德拉狂熱者身上。那些少數的倖存者不停地向水晶塔輸送能量來禁錮惡魔伊莫塔爾。$B$B一旦惡魔掙脫束縛，他一定會毀掉這片曾經繁榮的秘法之地。', '王子為了獲得永恆的生命和無盡的力量，殺死了許多人。曾經在數千人中分配的力量現在全部彙集到王子和辛德拉狂熱者身上。那些少數的倖存者不停地向水晶塔輸送能量來禁錮惡魔伊莫塔爾。$b$b一旦惡魔掙脫束縛，他一定會毀掉這片曾經繁榮的秘法之地。', '王子為了獲得永恆的生命和無盡的力量，殺死了許多人。曾經在數千人中分配的力量現在全部彙集到王子和辛德拉狂熱者身上。那些少數的倖存者不停地向水晶塔輸送能量來禁錮惡魔伊莫塔爾。$B$B一旦惡魔掙脫束縛，他一定會毀掉這片曾經繁榮的秘法之地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6903 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6903, 'zhTW', '卑微的傢伙，你現在是個男人啦!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6904 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6904, 'zhTW', '衛兵芬古斯令你變得兇殘!瘋狂!啊!', '卑微的傢伙，你現在是個男人啦!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6905 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6905, 'zhTW', '你可難倒我啦，老大!你怎麼能逃出斯里基克那一關呢??好在我動作敏捷，很快就逃了出來!哈哈!$B$B沒有人逃的過斯里基克那一關。斯里基克萬歲!', '你可找到我啦，頭兒!斯里基克陷入了大塊的冰塊中!好在我動作敏捷，很快就逃了出來!哈哈!$B$B或許冰塊很快就會融化……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6906 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6906, 'zhTW', '國王陛下，我會讓你看看我有多聰明的!有了這些強大的魔法魔精，你會更聰明的!$B$B嗯……或許斯里基克在自己身上使用魔法。那會是個不錯的點子……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6907 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6907, 'zhTW', '你是戈多克的國王!你是至高無上的王!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6908 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6908, 'zhTW', '我聽說你已經死啦……嗯，以後你想要裝死的話就不那麼容易啦!', NULL, '我聽說你已經死啦……嗯，以後你想要裝死的話就不那麼容易啦！', NULL, '老國王死了嗎？那不可能！', NULL, '卑微的傢伙，你現在是個男人啦!', NULL, '只要你跟我們呆在一起，你就是國王。你離開的話，會有其它食人魔取代你的位置的。這就是戈多克的行事之道！', NULL, '我聽說你已經死啦……嗯，以後你想要裝死的話就不那麼容易啦！', NULL, '老國王死了嗎？那不可能！', NULL, '國王陛下，我可沒有給你帶來什麼麻煩。', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6909 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6909, 'zhTW', '我統治這個王國已經有一萬年啦。在那時，我從那些神聖的辛德拉家族成員那兒聽到很多令人著迷的故事。$B$B由於我必須待在這兒，所以我常常和訪問者溝通交談。你可以為我講個故事嗎，或許你想聽聽我的故事?', '我統治這個王國已經有一萬年啦。在那時，我從那些神聖的辛德拉系列成員那兒聽到很多令人著迷的故事。$b$b由於我必須待在這兒，所以我常常和訪問者溝通交談。你可以為我講個故事嗎，或許你想聽聽我的故事?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6911 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6911, 'zhTW', '我們可不能惹惱了他。他發起火來就沒有節制啦。', '我們可不能惹惱了他。他發起火來就沒有節制啦。', '我們可不能惹惱了他。他發起火來就沒有節制啦。', '我們可不能惹惱了他。他發起火來就沒有節制啦。', '我們可不能惹惱了他。他發起火來就沒有節制啦。', '我們可不能惹惱了他。他發起火來就沒有節制啦。', '我們可不能惹惱了他。他發起火來就沒有節制啦。', '我們可不能惹惱了他。他發起火來就沒有節制啦。', '最近書本丟失甚多。博學者和他的助手非常惱怒。他們懷疑在埃雷薩拉斯有人妄圖不軌。', '最近書本丟失甚多。博學者和他的助手非常惱怒。他們懷疑在埃雷薩拉斯有人妄圖不軌。', '王子不再講述灰燼使者的故事了嗎？在他的諸多故事中，我們最喜歡這個。他的愛好則是尋找灰燼使者的下落。當然，沒人能從他口中得知那個故事。', '王子不再講述灰燼使者的故事了嗎？在他的諸多故事中，我們最喜歡這個。他的愛好則是尋找灰燼使者的下落。當然，沒人能從他口中得知那個故事。', '我猜想那些小鬼在偷學知識。', '我猜想那些小鬼在偷學知識。', '王子對奈法利安的巢穴非常感興趣。如果有誰能殺死巨龍及其屬下，並將戰鬥經過告訴王子，我敢打賭王子會非常滿意的。找到灰燼使者之日可待啦！', '王子對奈法利安的巢穴非常感興趣。如果有誰能殺死巨龍及其屬下，並將戰鬥經過告訴王子，我敢打賭王子會非常滿意的。找到灰燼使者之日可待啦！');
DELETE FROM `npc_text_locale` WHERE `ID` = 6913 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6913, 'zhTW', '你在附近閒逛什麼?為什麼不把那些小傢伙鎖起來?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6914 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6914, 'zhTW', '現在你變得強大了!向戈多克的新國王致敬!', '現在你變得強大了!向戈多克的新國王致敬!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6915 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6915, 'zhTW', '為什麼他們身上還有武器?你為什麼不拿走他們的武器?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6916 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6916, 'zhTW', '老大手下的所有下屬─踐踏者克雷格、三名守衛、克羅卡斯和觀察者─都為新的國王獻上貢品。如果你殺死了一名下屬，這名下屬就不能為新國王上貢啦!留下的活口越多，你得到的貢品就越多。別殺他們，你會得到很多東西的!$B$B就是這樣的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6917 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6917, 'zhTW', '哦，真恐怖!這是個悲劇!我們就要突破啦，但也有可能遭遇全軍覆滅的慘劇。', '哦，真恐怖!這是個悲劇!我們就要突破啦，但也有可能遭遇全軍覆滅的慘劇。', '哦，真恐怖!這是個悲劇!我們就要突破啦，但也有可能遭遇全軍覆滅的慘劇。', '哦，真恐怖!這是個悲劇!我們就要突破啦，但也有可能遭遇全軍覆滅的慘劇。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6918 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6918, 'zhTW', '呃...很抱歉我襲擊了你。不要殺我，求你了!?你是國王啦，我會為你提供更多的貢品的!', '呃……很抱歉我襲擊了你。不要殺我，求你了！？你是國王啦，我會為你提供更多的貢品的！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6919 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6919, 'zhTW', '粗略地檢查一下骨骸，上面的肉已經乾枯了。真是令人毛骨悚然的場景。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6920 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6920, 'zhTW', '從可怕的精靈王子那兒取回戈多克的聖物，或許你能比老頭目做得更好!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6922 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6922, 'zhTW', '向新國王致敬!', NULL, '向新國王致敬!', NULL, '向新國王致敬!', NULL, '向新國王致敬!', NULL, '只要你跟我們呆在一起，你就是國王。你離開的話，會有其它食人魔取代你的位置的。這就是戈多克的行事之道！', NULL, '我很聰明！我知道二加二等於五！', NULL, '老國王死了嗎？那不可能！', NULL, '國王陛下，我可沒有給你帶來什麼麻煩。', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6923 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6923, 'zhTW', '你不跟米茲勒講話，你就不能變成國王!跟狡猾的米茲勒講話!', '你不跟米茲勒談話的話是當不了國王的!跟他談談!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6924 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6924, 'zhTW', '那麼...你殺死了國王?我就知道這些傢伙會擁戴你成為新國王的。我就知道!那些傢伙只知道力量。$B$B似乎你赦免的跟隨者越多，獻殷勤的人也就越多。別這麼不公平─我是說來一次有趣的挑戰。如果你離開，我也不敢期望繼續當國王。這些傢伙肯定有人趁機取代你的地位。$B$B還有...你找到了我的鑰匙，是嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6925 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6925, 'zhTW', '你必須明白，像我這樣活了一萬年的人，對生命有獨特的看法。現在你經受的考驗和磨難都是毫無意義的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6926 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6926, 'zhTW', '哦，年輕的主人制造的這一系列事件和慌亂。可以想像，世界的命運就掌控在他手中。只有人類才會對世界產生這種扭曲的看法。$B$B唉，他將秘法的秘密都告訴了我……聖契之類的無用之物。這種東西對我來說是一無是處，但是或許你對它們感興趣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6927 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6927, 'zhTW', '被偷啦，$r!我們最珍貴的三卷卷軸。如果你能找回來的話，一定會得到豐厚的報酬的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6929 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6929, 'zhTW', '<你無法理解這份卷軸上記載的任何技術。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6930 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6930, 'zhTW', '<羊皮紙上畫著的是修理機器人的結構示意圖。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6931 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6931, 'zhTW', '<依你目前的工程學技能是看不懂這張複雜的結構圖的。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6932 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6932, 'zhTW', '<你精通製造和操作這個機器人。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6933 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6933, 'zhTW', '世界的構造精妙細緻。只靠某些知識和對已知知識的應用是不可能破壞世界構造的。裂隙也由此產生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6934 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6934, 'zhTW', '盯著敵人，$r。看吧，強大的部落足以對付巨龍!所有跟我們做對的人都是這種下場!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6935 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6935, 'zhTW', '我當然是來傳達大酋長的命令的。我是部落的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6936 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6936, 'zhTW', '我活著就是為了為國王服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6937 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6937, 'zhTW', '或許有一天，你對聯盟的貢獻會跟你今日所見的英雄一樣偉大。尊重英雄吧，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6938 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6938, 'zhTW', '主人，你的到來令我們倍感榮幸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6939 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6939, 'zhTW', '擁有萬年曆史的知識卷軸將那些邪惡的傢伙吸引到圖書館。大量的書籍被盜，被找回之後再次被盜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6940 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6940, 'zhTW', '基爾達斯總是過分誇大。比如，「迦羅娜:潛行與詭計研究」已經被偷過400多次啦。$B$B圖書館的標誌保護著這本卷軸，防止任何人偷看。', '基爾達斯總是過分誇大。比如，「迦羅娜:潛行與詭計研究」已經被偷過400多次啦。$B$B圖書館的標誌保護著這本卷軸，防止任何人偷看。', '基爾達斯總是過分誇大。比如，“迦羅娜：潛行與詭計研究”已經被偷過400多次啦。$b$b阿西娜神廟的標誌保護著這本卷軸，防止任何人偷看。', '基爾達斯總是過分誇大。比如，“迦羅娜:潛行與詭計研究”已經被偷過400多次啦。$B$B圖書館的標誌保護著這本卷軸，防止任何人偷看。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6947 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6947, 'zhTW', '我可沒時間停下來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6948 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6948, 'zhTW', '我能幫忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6949 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6949, 'zhTW', '是的，我知道埃德薩拉斯。多年前，那兒曾是夜精靈的魔法要塞。$B$B你知道埃德薩拉斯嗎，年輕人?也許有人會說這跟我目前的處境一致……但是我可不相信巧合這回事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6950 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6950, 'zhTW', '塞納里奧議會的人已經瞭解埃德薩拉斯的近況了。我陷入僵局，不知如何是好。我很可能向那些體格強健、善於作戰的人尋求幫助。$B$B但是，要對埃德薩拉斯採取行動，就要了解關於豐碩的果實的知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6951 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6951, 'zhTW', '多年前，埃德薩拉斯是魔法師的集中地，居住在那些神聖的大廳中的人都能使用強大的魔法。米莉仙·瑟琳就是這樣一名夜精靈─她是個自然學家，能將自然本身的力量灌輸到她鑄造的神器中。$B$B豐饒之果便是她的傑作……她利用特殊的月井製造出一種奇異的葡萄酒，具備保護和生長的效力。埃德薩拉斯在葡萄酒的滋養下日益繁華起來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6952 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6952, 'zhTW', '唉，事情似乎總是這樣。和塞納里奧議會的其他人一樣，我也認為是米利的造物在先祖之戰中毀掉了。但是我已經認識到，這種觀點是錯誤的。$B$B豐碩的果實並未被摧毀……儘管現在它被稱為惡魔之藤。它被埃德薩拉斯的惡魔領主『狂野變形者』奧茲恩汙染了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6953 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6953, 'zhTW', '我……我無法開始想像，$N。我只知道我不能讓這件事發生。它會被摧毀的─就算不毀在我們對巨魔的防禦上，也會毀在米莉仙·瑟琳的記憶上……米莉……$B$B我的朋友，這就是我希望你伸出援手的事情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6954 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6954, 'zhTW', '<德米提恩跪倒在地。>$B$B你已經找回了主人的永久牢籠!$B$B我期待這一天已經很久很久了，我的願望終於實現了。$B$B必須解放我的主人!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6955 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6955, 'zhTW', '我有他的重生之瓶。一旦你準備接受這項任務，你必須保護好這個小瓶，要擺脫拉格納羅斯的控制!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6956 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6956, 'zhTW', '必須用源質來對重生之瓶進行固化。我只知道這種礦物的一種原料:位於世界核心的元素神域。$B$B塑地者對這種東西的瞭解比我多得多。你必須找到塑地者!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6957 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6957, 'zhTW', '向你致敬，英雄!我有來自大陸和島嶼的最新訊息，供你參考。', '向你致敬，英雄!我有來自大陸和島嶼的最新訊息，供你參考。', '向你致敬，英雄!我有來自大陸和島嶼的最新訊息，供你參考。', '向你致敬，英雄!我有來自大陸和島嶼的最新訊息，供你參考。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6958 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6958, 'zhTW', '必須摧毀拉格納羅斯的肉身。在屍體殘骸中將出現他的精華。在這個虛弱時期，被關押在桑德蘭監獄中的拉格納羅斯的護手將被釋放。精華本身就是鑰匙……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6959 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6959, 'zhTW', '你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。', '你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。', '你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。', '你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6960 AND `Locale` = 'zhTW';
