INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6993, 'zhTW', '你的護甲看起來很破舊。你為此感到膽怯嗎?', NULL, '你的護甲看起來很破舊。你為此感到膽怯嗎?', NULL, '你的護甲看起來很破舊。你為此感到膽怯嗎?', NULL, '你的護甲看起來很破舊。你為此感到膽怯嗎?', NULL, '我的鼻子裡有塊石頭。', NULL, '要是海龜沒有殼的話，那不就成無家可歸或是裸體啦?', NULL, '「嘖嘖」是什麼意思?', NULL, '要是你的手套太大的話，還算是合手的手套嗎?', NULL);
