INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7012, 'zhTW', '哎呀……你可真是好人。我聽說你是兒童周的志願者，是嗎$c?嗯，你會受到讚揚的。我們必須記得那些不幸的人─特別是那些孩子。$B$B我很樂意簽名。拿去吧。', '哎呀……你可真是好人。我聽說你是兒童周的志願者，是嗎$c?嗯，你會受到讚揚的。我們必須記得那些不幸的人─特別是那些孩子。$B$B我很樂意簽名。拿去吧。', '哎呀……你可真是好人。我聽說你是兒童周的志願者，是嗎$c?嗯，你會受到讚揚的。我們必須記得那些不幸的人——特別是那些孩子。$b$b我很樂意簽名。拿去吧。', '哎呀……你可真是好人。我聽說你是兒童周的志願者，是嗎$c?嗯，你會受到讚揚的。我們必須記得那些不幸的人─特別是那些孩子。$B$B我很樂意簽名。拿去吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
