INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7013, 'zhTW', '年輕人，歡迎你來到雷霆崖。在這兒你能卸下負擔，享受庇佑。我們歡迎所有的部落居民來到雷霆崖。$B$B我的朋友，靈魂都會來這個神聖的地方復活。尊敬他們吧，這也是尊敬你自己。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7014 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7014, 'zhTW', '啊，毫無疑問，他一定是想要成為一名戰士!我想你是來參加兒童周的，是嗎?你的行為堪稱楷模，其他人必定會以你為榜樣的，這令那些疲憊不堪的靈魂倍感欣慰。$B$B我很樂意幫助你和這位年輕的男子。嗯……我要給他提些什麼建議呢?聽聽靈魂怎麼說吧，是的……或許是關於吃掉所有蔬菜……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7015 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7015, 'zhTW', '烹飪是一種值得畢生追求的職業，而我可以看到我們共有著一樣的熱情!', '烹飪是一種值得畢生追求的職業，而我可以看到我們共有著一樣的熱情!', '烹飪是我一生的追求，我覺得我們倆有共同的愛好!', '烹飪是我一生的追求，我覺得我們倆有共同的愛好!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7016 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7016, 'zhTW', '去銀風避難所找珊蒂瑞亞吧。她可以賣給你「高階烹飪書」。', '去銀風避難所找珊蒂瑞亞吧。她可以賣給你「高階烹飪書」。', '去銀風避難所找珊蒂瑞亞吧。她可以賣給你“高階烹飪教材”。', '去銀風避難所找珊蒂瑞亞吧。她可以賣給你“高階烹飪教材”。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7017 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7017, 'zhTW', '加基森的戴格·迅斬對廚藝非常精通。要想提高自己的能力，你就去找他吧。', '加基森的戴格·迅斬對廚藝非常精通。要想提高自己的能力，你就去找他吧。', '加基森的迪爾格·奎克里弗對廚藝非常精通。要想提高自己的能力，你就去找他吧。', '加基森的戴格·迅斬對廚藝非常精通。要想提高自己的能力，你就去找他吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7019 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7019, 'zhTW', '葬影村的烏蘭可以賣給你「高階烹飪書」。如果你想要提高烹飪技能的話，就需要這本書。', '葬影村的烏蘭可以賣給你「高階烹飪書」。如果你想要提高烹飪技能的話，就需要這本書。', '葬影村的烏蘭可以賣給你「高階烹飪書」。如果你想要提高烹飪技能的話，就需要這本書。', '葬影村的烏蘭可以賣給你“高階烹飪教材”。如果你想要提高烹飪技能的話，就需要這本書。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
