INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7177, 'zhTW', '在獸人的新主城奧格瑞瑪地底下的，一系列火山洞穴形成了怒焰裂谷，最近，有傳言說一個膜拜追隨惡魔暗影議會的邪教居住在裂谷的深處，這個邪教——據傳叫做火刃教，已經威脅到了杜隆塔爾的國家主權，人們認為獸人領袖薩爾知道火刃教的存在，並且選擇了不去摧毀它，希望它的成員能帶他找到暗影議會。 $b', '在獸人的新主城奧格瑞瑪地底下的，一系列火山洞穴形成了怒焰裂谷，最近，有傳言說一個膜拜追隨惡魔暗影議會的邪教居住在裂谷的深處，這個邪教——據傳叫做火刃教，已經威脅到了杜隆塔爾的國家主權，人們認為獸人領袖薩爾知道火刃教的存在，並且選擇了不去摧毀它，希望它的成員能帶他找到暗影議會。 $b', NULL, '在獸人的新主城奧格瑞瑪地底下的，一系列火山洞穴形成了怒焰裂谷，最近，有傳言說一個膜拜追隨惡魔暗影議會的邪教居住在裂谷的深處，這個邪教——據傳叫做火刃教，已經威脅到了杜隆塔爾的國家主權，人們認為獸人領袖薩爾知道火刃教的存在，並且選擇了不去摧毀它，希望它的成員能帶他找到暗影議會。 $b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
