INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7183, 'zhTW', '最近，一個叫做納拉雷克斯的暗夜精靈德魯伊在貧瘠之地的中心發現了一系列地底洞穴，他認為能靠洞穴的泉水來為貧瘠之地恢復生機，德魯伊從虛幻的翡翠之夢獲取能量，後來他的夢境不知怎麼的變得十分可怕，很快，哀嚎洞穴稱為了邪惡的獸窩、致命的禁地，據說納拉雷克斯仍然被困於翡翠夢境邊緣的迷宮某處。', '最近，一個叫做納拉雷克斯的暗夜精靈德魯伊在貧瘠之地的中心發現了一系列地底洞穴，他認為能靠洞穴的泉水來為貧瘠之地恢復生機，德魯伊從虛幻的翡翠之夢獲取能量，後來他的夢境不知怎麼的變得十分可怕，很快，哀嚎洞穴稱為了邪惡的獸窩、致命的禁地，據說納拉雷克斯仍然被困於翡翠夢境邊緣的迷宮某處。', NULL, '最近，一個叫做納拉雷克斯的暗夜精靈德魯伊在貧瘠之地的中心發現了一系列地底洞穴，他認為能靠洞穴的泉水來為貧瘠之地恢復生機，德魯伊從虛幻的翡翠之夢獲取能量，後來他的夢境不知怎麼的變得十分可怕，很快，哀嚎洞穴稱為了邪惡的獸窩、致命的禁地，據說納拉雷克斯仍然被困於翡翠夢境邊緣的迷宮某處。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7185 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7185, 'zhTW', '在第三次戰役中達拉然的法師們作為平平，被天災軍團戰敗，大法師阿魯高決定召喚異度空間的狼族來給己方勢力增添實力，狼人屠殺了天災士兵，但是很快，屠殺的目標就輪到了法師們自己以及最高尊者席瓦萊恩男爵，城堡很快淪陷成為了陰影和廢墟。阿魯高愧疚致狂，竟認狼為子，逃到了附近的“影牙城堡”。$b', '在第三次戰役中達拉然的法師們作為平平，被天災軍團戰敗，大法師阿魯高決定召喚異度空間的狼族來給己方勢力增添實力，狼人屠殺了天災士兵，但是很快，屠殺的目標就輪到了法師們自己以及最高尊者席瓦萊恩男爵，城堡很快淪陷成為了陰影和廢墟。阿魯高愧疚致狂，竟認狼為子，逃到了附近的“影牙城堡”。$b', NULL, '在第三次戰役中達拉然的法師們作為平平，被天災軍團戰敗，大法師阿魯高決定召喚異度空間的狼族來給己方勢力增添實力，狼人屠殺了天災士兵，但是很快，屠殺的目標就輪到了法師們自己以及最高尊者席瓦萊恩男爵，城堡很快淪陷成為了陰影和廢墟。阿魯高愧疚致狂，竟認狼為子，逃到了附近的“影牙城堡”。$b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7186 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7186, 'zhTW', '啊，你!如果你想要贏得暗矛的尊重，那你可以向我們捐贈那些繼續的資源!你要知道，布料和繃帶不會從樹上長出來。$B$B我們需要你在冒險中得到的那些布料，把它們捐給我們吧!這樣你就可以得到暗矛部族的親睞!', '啊，你!如果你想要贏得暗矛的尊重，那你可以向我們捐贈那些繼續的資源!你要知道，布料和繃帶不會從樹上長出來。$B$B我們需要你在冒險中得到的那些布料，把它們捐給我們吧!這樣你就可以得到暗矛部族的親睞!', '啊，你!如果你想要贏得暗矛的尊重，那你可以向我們捐贈那些繼續的資源!你要知道，布料和繃帶不會從樹上長出來。$b$b我們需要你在冒險中得到的那些布料，把它們捐給我們吧!這樣你就可以得到暗矛部族的親睞!', '啊，你!如果你想要贏得暗矛的尊重，那你可以向我們捐贈那些繼續的資源!你要知道，布料和繃帶不會從樹上長出來。$B$B我們需要你在冒險中得到的那些布料，把它們捐給我們吧!這樣你就可以得到暗矛部族的親睞!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7187 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7187, 'zhTW', '死亡礦井曾經是人類領地上最大的金礦，如今已經變成了被迪菲亞兄弟會佔據的秘密領地，他們透過陰暗的秘密隧道進入礦井。傳聞，這些強盜找到了聰明的哥布林，在地底幫助他們建立某種可怕的玩意，但也可能僅僅是傳聞。據傳進入死亡礦井需要經過寧靜安詳的的月溪鎮。$b', '死亡礦井曾經是人類領地上最大的金礦，如今已經變成了被迪菲亞兄弟會佔據的秘密領地，他們透過陰暗的秘密隧道進入礦井。傳聞，這些強盜找到了聰明的哥布林，在地底幫助他們建立某種可怕的玩意，但也可能僅僅是傳聞。據傳進入死亡礦井需要經過寧靜安詳的的月溪鎮。$b', NULL, '死亡礦井曾經是人類領地上最大的金礦，如今已經變成了被迪菲亞兄弟會佔據的秘密領地，他們透過陰暗的秘密隧道進入礦井。傳聞，這些強盜找到了聰明的哥布林，在地底幫助他們建立某種可怕的玩意，但也可能僅僅是傳聞。據傳進入死亡礦井需要經過寧靜安詳的的月溪鎮。$b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7188 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7188, 'zhTW', '在這個艱難的時期，捐贈布料對於那些不幸的人是非常重要的幫助手段。布料還可以製作裝備和繃帶─這對於戰爭十分重要!$B$B如果你想要為奧格瑪的獸人捐贈布料的話，我會欣然接受它們，你一定會收到我們的親睞。$B$B為了部落!', '在這個艱難的時期，捐贈布料對於那些不幸的人是非常重要的幫助手段。布料還可以製作裝備和繃帶─這對於戰爭十分重要!$B$B如果你想要為奧格瑪的獸人捐贈布料的話，我會欣然接受它們，你一定會收到我們的親睞。$B$B為了部落!', '在這個艱難的時期，捐贈布料對於那些不幸的人是非常重要的幫助手段。布料還可以製作裝備和繃帶─這對於戰爭十分重要!$b$b如果你想要為奧格瑞瑪的獸人捐贈布料的話，我會欣然接受它們，你一定會收到我們的親睞。$b$b為了部落!', '在這個艱難的時期，捐贈布料對於那些不幸的人是非常重要的幫助手段。布料還可以製作裝備和繃帶─這對於戰爭十分重要!$B$B如果你想要為奧格瑪的獸人捐贈布料的話，我會欣然接受它們，你一定會收到我們的親睞。$B$B為了部落!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7189 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7189, 'zhTW', '就是你……在這迫切的時期是你幫助被遺忘者最好的時機。好好聽著，我不喜歡重複我說過的話。$B$B我們現在極度缺乏布料。繃帶和任何布料儲存量都很低，我們希望接受捐贈來補充庫存。你的捐贈不會有任何經濟補償─這就是捐贈的含義─你的捐贈一定會為我們所賞識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7190 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7190, 'zhTW', '嘿，$g兄弟:姐妹;……我希望可以打擾你一下，如果可以的話。$B$B我們在透過試煉和進行家園重建中經歷了很多。我們現在極度缺乏布料。如果你有一些多餘的話，我希望你可以捐獻給我們。你一定會為此贏得所有牛頭人的尊重的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7191 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7191, 'zhTW', '怒焰峽谷的入口就在奧格瑞瑪中心的暗影裂口。', '怒焰峽谷的入口就在奧格瑞瑪中心的暗影裂口。', NULL, '怒焰峽谷的入口就在奧格瑞瑪中心的暗影裂口。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7192 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7192, 'zhTW', '哀嚎洞穴的入口就在貧瘠之地十字路口西南邊的甜水綠洲。', '哀嚎洞穴的入口就在貧瘠之地十字路口西南邊的甜水綠洲。', NULL, '哀嚎洞穴的入口就在貧瘠之地十字路口西南邊的甜水綠洲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7193 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7193, 'zhTW', '嘿，朋友─請等一下，如果可以的話……$B$B我們在重建泰達希爾的過程中經歷了很多的痛苦。現在，我們不僅要忍受這些痛苦，而且我們還發現我們的布料儲存已經很少了。如果你有多餘的布料，那我希望你可以捐贈出它們。你一定因為幫助夜精靈贏得我們的尊重!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7194 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7194, 'zhTW', '諾姆瑞根的流亡者需要大量的布料資源!也許你可以幫幫我們，是不是?$B$B把你多餘的布料資源帶給我們。透過捐獻它們，你可以獲得所有地精的尊重。這是金錢無法換的!好吧，布料可以幫助我們，但是它們意義絕不限於這些……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7195 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7195, 'zhTW', '啊，你!如果你想要贏得鐵爐堡矮人的尊重，那麼你可以開始為我們捐贈有價值的資源!鐵爐堡現在的布料和繃帶的儲存量很低!$B$B你可以捐贈各種你在冒險中得到的布料!這樣做你可以贏得鐵爐堡矮人對你的尊重中!', '啊，你!如果你想要贏得鐵爐堡矮人的尊重，那麼你可以開始為我們捐贈有價值的資源!鐵爐堡現在的布料和繃帶的儲存量很低!$B$B你可以捐贈各種你在冒險中得到的布料!這樣做你可以贏得鐵爐堡矮人對你的尊重中!', '啊，你!如果你想要贏得鐵爐堡矮人的尊重，那麼你可以開始為我們捐贈有價值的資源!鐵爐堡現在的布料和繃帶的儲存量很低!$b$b你可以捐贈各種你在冒險中得到的布料!這樣做你可以贏得鐵爐堡矮人對你的尊重中!', '啊，你!如果你想要贏得鐵爐堡矮人的尊重，那麼你可以開始為我們捐贈有價值的資源!鐵爐堡現在的布料和繃帶的儲存量很低!$B$B你可以捐贈各種你在冒險中得到的布料!這樣做你可以贏得鐵爐堡矮人對你的尊重中!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7196 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7196, 'zhTW', '朋友─暴風城需要你的協助和慷慨解囊!$B$B我們曾經儲藏豐富的布料已經所剩不多了。暴風城現在需要大量的布料和繃帶!你的捐贈將能夠幫助暴風城度過難關，你還能贏得我們對你的尊重!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7197 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7197, 'zhTW', '影牙城堡的入口就在銀松森林南部焚木村的北邊。', '影牙城堡的入口就在銀松森林南部焚木村的北邊。', NULL, '影牙城堡的入口就在銀松森林南部焚木村的北邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7198 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7198, 'zhTW', '在你匆忙追尋榮耀的過程中，你有沒有想過你的行動對於遊戲的節奏影響。你是否感覺我說的話很荒謬!我所說的話都是如此哲理化，這讓你頭顱裡那花生大小的東西感到十分迷茫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7199 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7199, 'zhTW', '這是真的。請允許我總結一下...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
