INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7200, 'zhTW', '黑暗深淵位於梣谷海岸左拉姆海岸的最北部。', '黑暗深淵位於梣谷海岸左拉姆海岸的最北部。', '黑暗深淵位於梣谷海岸左拉姆海岸的最北部。', '黑暗深淵就在佐拉姆海岸北端與灰谷海岸交界處。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
