INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7201, 'zhTW', '位於佐拉姆海岸與灰谷海岸之間的黑暗深淵，曾經是一座供奉著暗夜精靈的月亮女神艾露恩的輝煌神殿，然而大災變粉碎了這座神殿，並把它沉沒到了迷霧之海，那裡一直是不可觸及的——直到它的神力因時間流逝而鬆懈。納迦和半人馬為了探究神殿的秘密而出現，傳說古老的神獸——阿庫麥爾，居住在神殿廢墟的深處。$b', '位於佐拉姆海岸與灰谷海岸之間的黑暗深淵，曾經是一座供奉著暗夜精靈的月亮女神艾露恩的輝煌神殿，然而大災變粉碎了這座神殿，並把它沉沒到了迷霧之海，那裡一直是不可觸及的——直到它的神力因時間流逝而鬆懈。納迦和半人馬為了探究神殿的秘密而出現，傳說古老的神獸——阿庫麥爾，居住在神殿廢墟的深處。$b', NULL, '位於佐拉姆海岸與灰谷海岸之間的黑暗深淵，曾經是一座供奉著暗夜精靈的月亮女神艾露恩的輝煌神殿，然而大災變粉碎了這座神殿，並把它沉沒到了迷霧之海，那裡一直是不可觸及的——直到它的神力因時間流逝而鬆懈。納迦和半人馬為了探究神殿的秘密而出現，傳說古老的神獸——阿庫麥爾，居住在神殿廢墟的深處。$b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7202 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7202, 'zhTW', '諾莫瑞根在丹莫洛的西邊。', '諾莫瑞根在丹莫洛的西邊。', '諾莫瑞根在丹莫洛的西邊。', '諾莫瑞根中位於丹莫羅西部。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
