INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7203, 'zhTW', '位於丹莫羅的諾莫瑞根曾經是地精們代代相傳的首都城市，但是最近出現了大量石顎怪，地精首領——大工匠梅卡托克孤注一擲，下令緊急動用放射性坦克進行報復性攻擊，雖然石顎怪被輻射了，但他們仍然有增無減，地精們被迫撤退，在矮人的鐵爐堡尋求避難。現在大工匠梅卡托克正在召集勇士，以幫助他的人民收回自己心愛的城市。$b', '位於丹莫羅的諾莫瑞根曾經是地精們代代相傳的首都城市，但是最近出現了大量石顎怪，地精首領——大工匠梅卡托克孤注一擲，下令緊急動用放射性坦克進行報復性攻擊，雖然石顎怪被輻射了，但他們仍然有增無減，地精們被迫撤退，在矮人的鐵爐堡尋求避難。現在大工匠梅卡托克正在召集勇士，以幫助他的人民收回自己心愛的城市。$b', NULL, '位於丹莫羅的諾莫瑞根曾經是地精們代代相傳的首都城市，但是最近出現了大量石顎怪，地精首領——大工匠梅卡托克孤注一擲，下令緊急動用放射性坦克進行報復性攻擊，雖然石顎怪被輻射了，但他們仍然有增無減，地精們被迫撤退，在矮人的鐵爐堡尋求避難。現在大工匠梅卡托克正在召集勇士，以幫助他的人民收回自己心愛的城市。$b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7204 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7204, 'zhTW', '剃刀沼澤位於貧瘠之地最南端的大路西邊。', '剃刀沼澤位於貧瘠之地最南端的大路西邊。', '剃刀沼澤位於貧瘠之地最南端的大路西邊。', '剃刀沼澤就在位於貧瘠之地最南端的路西首。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
