INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7205, 'zhTW', '上古戰爭期間，野豬之神——阿迦瑪甘出來對抗燃燒軍團，它戰敗了。隨著時間的流逝，在它灑落鮮血的地方，萌發生長出了大量的荊棘藤，大量野豬人出來守護這塊神聖之地，剃刀沼澤現在被卡爾加·刺肋統治，傳聞他在與天災使者合作，計劃著一些見不得人的勾當。$b', '上古戰爭期間，野豬之神——阿迦瑪甘出來對抗燃燒軍團，它戰敗了。隨著時間的流逝，在它灑落鮮血的地方，萌發生長出了大量的荊棘藤，大量野豬人出來守護這塊神聖之地，剃刀沼澤現在被卡爾加·刺肋統治，傳聞他在與天災使者合作，計劃著一些見不得人的勾當。$b', NULL, '上古戰爭期間，野豬之神——阿迦瑪甘出來對抗燃燒軍團，它戰敗了。隨著時間的流逝，在它灑落鮮血的地方，萌發生長出了大量的荊棘藤，大量野豬人出來守護這塊神聖之地，剃刀沼澤現在被卡爾加·刺肋統治，傳聞他在與天災使者合作，計劃著一些見不得人的勾當。$b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7206 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7206, 'zhTW', '血色修道院座落於提瑞斯法林地東北角的山上。', '血色修道院座落於提瑞斯法林地東北角的山上。', NULL, '血色修道院座落於提瑞斯法林地東北角的山上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
