INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7207, 'zhTW', '血色修道院曾經是一個學習與啟迪的中心。隨天災亡靈在第三次戰爭出現，和平的修道院被改建成了血色十字軍的堡壘。血色十字軍不能容忍所有非人類的種族，不管是否聯盟或者關係如何。他們認為，任何外族都是潛在的亡靈瘟疫——必須予以銷燬。$b', '血色修道院曾經是一個學習與啟迪的中心。隨天災亡靈在第三次戰爭出現，和平的修道院被改建成了血色十字軍的堡壘。血色十字軍不能容忍所有非人類的種族，不管是否聯盟或者關係如何。他們認為，任何外族都是潛在的亡靈瘟疫——必須予以銷燬。$b', NULL, '血色修道院曾經是一個學習與啟迪的中心。隨天災亡靈在第三次戰爭出現，和平的修道院被改建成了血色十字軍的堡壘。血色十字軍不能容忍所有非人類的種族，不管是否聯盟或者關係如何。他們認為，任何外族都是潛在的亡靈瘟疫——必須予以銷燬。$b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7208 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7208, 'zhTW', '剃刀高地位於貧瘠之地最南端的大路東邊。', '剃刀高地位於貧瘠之地最南端的大路東邊。', '剃刀高地位於貧瘠之地最南端的大路東邊。', '剃刀高地位於貧瘠之地最南端的大路東邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7209 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7209, 'zhTW', '剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊，以及他們的高等祭司——亡首部族。然而最近，一股黑暗的力量籠罩了這座原始的洞穴。天譴軍團的爪牙在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族，並將佈滿荊棘的迷宮變成了亡靈力量的堡壘。現在野豬人正在奮力戰鬥來奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。', '覆蓋著和剃刀沼澤一樣的荊棘藤，剃刀高地是野豬人的傳統首都。漫天遍地的荊棘藤下駐紮著大量野豬人部隊以及它們的高等牧師們——亡首族。然而最近，一股迫在眉睫的陰影降臨了這個天然的洞穴，亡靈天災的使者——巫妖“寒冰使者’亞門納爾掌控了野豬族並且把這座荊棘的迷宮變成了亡靈勢力的堡壘。', NULL, '覆蓋著和剃刀沼澤一樣的荊棘藤，剃刀高地是野豬人的傳統首都。漫天遍地的荊棘藤下駐紮著大量野豬人部隊以及它們的高等牧師們——亡首族。然而最近，一股迫在眉睫的陰影降臨了這個天然的洞穴，亡靈天災的使者——巫妖“寒冰使者’亞門納爾掌控了野豬族並且把這座荊棘的迷宮變成了亡靈勢力的堡壘。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7210 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7210, 'zhTW', '奧達曼位於荒蕪之地最北端。', '奧達曼位於荒蕪之地最北端。', '奧達曼位於荒蕪之地最北端。', '奧達曼位於荒蕪之地北部的盡頭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
