INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7211, 'zhTW', '拉爾德在這裡維持和平。拉爾德還在這裡賣魚。想要一些魚嗎?', '拉爾德在這裡維持和平。拉爾德還在這裡賣魚。想要一些魚嗎?', '拉爾德在這裡維持和平。拉爾德還在這裡賣魚。想要一些魚嗎?', '拉爾德在這裡維持和平。拉爾德還在這裡賣魚。想要一些魚嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7212 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7212, 'zhTW', '自從宇宙誕生，奧達曼就一直在地下作為上古之神泰坦的墓穴而存在。矮人考古隊最近公佈了泰坦首次失敗的創作——石顎怪。傳說泰坦認為石顎怪的試驗失敗後，他們再次嘗試，結果建立了矮人種族。這些秘密被記錄在諾甘農的傳說圓盤上——大量的史前古物藏在這座古老的城市，被巨大的石頭生物守護著。', '自從宇宙誕生，奧達曼就一直在地下作為上古之神泰坦的墓穴而存在。矮人考古隊最近公佈了泰坦首次失敗的創作——石顎怪。傳說泰坦認為石顎怪的試驗失敗後，他們再次嘗試，結果建立了矮人種族。這些秘密被記錄在諾甘農的傳說圓盤上——大量的史前古物藏在這座古老的城市，被巨大的石頭生物守護著。', NULL, '自從宇宙誕生，奧達曼就一直在地下作為上古之神泰坦的墓穴而存在。矮人考古隊最近公佈了泰坦首次失敗的創作——石顎怪。傳說泰坦認為石顎怪的試驗失敗後，他們再次嘗試，結果建立了矮人種族。這些秘密被記錄在諾甘農的傳說圓盤上——大量的史前古物藏在這座古老的城市，被巨大的石頭生物守護著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7213 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7213, 'zhTW', '祖爾法拉克遺蹟位於塔納利斯沙漠最西北角。', '祖爾法拉克遺蹟位於塔納利斯沙漠最西北角。', '祖爾法拉克遺蹟位於塔納利斯沙漠最西北角。', '祖爾法拉克的廢墟位於塔納利斯沙漠的西北角。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
