INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7214, 'zhTW', '日光暴曬下的這座城市是沙怒巨魔的家園，他們一向以來都以其無情和黑暗魔法而聞名。巨魔傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。', '日光暴曬下的這座城市是沙怒巨魔的家園，他們一向以來都以其無情和黑暗魔法而聞名。巨魔傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。', '日光暴曬下的這座城市是沙怒巨魔的家園，他們一向以來都以其無情和黑暗魔法而聞名。巨魔傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。', '這座終日被太陽枯曬的城市是以殘忍、黑暗、神秘出名的沙怒巨魔的家。巨魔的傳說中描述有一把強大的劍叫做“鞭笞者蘇薩斯”，一把能向它的敵人灌輸恐懼與虛弱的武器。很久以前，這把武器被一分為二，然而，傳言這兩半可能散落在祖爾法拉克內的某處。$b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7215 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7215, 'zhTW', '瑪拉頓位於淒涼之地西部中間的長矛谷中。', '瑪拉頓位於淒涼之地西部中間的長矛谷中。', '瑪拉頓位於淒涼之地西部中間的長矛谷中。', '瑪拉頓位於淒涼之地西部中間的長矛谷中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
