INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7216, 'zhTW', '瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7217 AND `Locale` = 'zhTW';
