INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7219, 'zhTW', '黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。', '黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。', '黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。', '黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
