INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7226, 'zhTW', '斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
