INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7230, 'zhTW', '暴風城監獄是一座高度安全的監獄，它被掩藏在暴風城運河區之下，由典獄官塞爾沃特主管。這裡居住著騙子、政治犯、殺人犯以及大量這片土地上最危險的犯人。一名囚犯領導起義製造了監獄的混亂，看守們被趕了出來，罪犯們則在裡面閒庭信步。$b', '暴風城監獄是一座高度安全的監獄，它被掩藏在暴風城運河區之下，由典獄官塞爾沃特主管。這裡居住著騙子、政治犯、殺人犯以及大量這片土地上最危險的犯人。一名囚犯領導起義製造了監獄的混亂，看守們被趕了出來，罪犯們則在裡面閒庭信步。$b', NULL, '暴風城監獄是一座高度安全的監獄，它被掩藏在暴風城運河區之下，由典獄官塞爾沃特主管。這裡居住著騙子、政治犯、殺人犯以及大量這片土地上最危險的犯人。一名囚犯領導起義製造了監獄的混亂，看守們被趕了出來，罪犯們則在裡面閒庭信步。$b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
