INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7240, 'zhTW', '別踩到我的商品，陌生人。', '別踩到我的商品，陌生人。', '我出售各種奢靡的貨物和商品，陌生人。', '我出售各種奢靡的貨物和商品，陌生人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7241 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7241, 'zhTW', '釣魚只是為了娛樂，夥計。你知道嗎?我是在向我的導師學習，世界上最偉大的釣魚者─納特·帕格。你聽說他沒有，夥計?$B$B如果你想要尋求啟迪，那麼納特·帕格會指引你前進的道路。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7242 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7242, 'zhTW', '祖爾金有一天會回來的，$r。記住我的話。在那一天到來之前，我們會守住我們的位置並保護森林食人妖的數量。$B$B作為惡齒村的獵人首領，我的責任就是確保我們居住環境的安全。$B$B我對這個區域周圍的野獸都要進行監控。$B$B你是不是來找些活幹的?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7243 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7243, 'zhTW', '我是基爾拉姆，斧類大師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7244 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7244, 'zhTW', '啊，一個經歷豐富的冒險者。基爾拉姆讓你來這裡了。我知道你具有相當的能力，你只需要詢問我，我就會教你斧類鐵匠的知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7245 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7245, 'zhTW', '不要靠得太近，$N。我有可能失誤將我的錘子敲到你的腦袋。', '不要靠得太近，$N。我有可能失誤將我的錘子敲到你的腦袋。', '不要靠得太近，$N。我有可能失誤將我的錘子敲到你的腦袋。', '不要靠得太近，$N。我有可能失誤將我的錘子敲到你的腦袋。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7246 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7246, 'zhTW', '我會教你錘類鍛造的專精之道。你只需要恭恭敬敬地問我就可以了。', '我會教你錘類鍛造的專精之道。你只需要恭恭敬敬地問我就可以了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7247 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7247, 'zhTW', '退後，否則我會把你一下子砍成兩半的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7248 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7248, 'zhTW', '如果你希望成為一名劍類鍛造師，那就問問我吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7249 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7249, 'zhTW', '我剛剛完成了一次新的空間爆破，用它我可以變成最最富有的人，我做夢都無法夢到的富有程度!我所需要的就是找到一個熟練的哥布林工程師來製作一個空間撕裂器，然後將兩者連線起來!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7251 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7251, 'zhTW', '透過在諾姆瑞根中的危險探險，我找到了製作一種偉大發明的方法:物質傳送器!我所需要的就是一個熟練的地精工程師，讓他製造一個信標連線在這個傳送器上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7252 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7252, 'zhTW', '一旦你建造了這個裝置，你就將被傳送至可愛的加基森!幾乎使用這個裝置的人都發現在其立即到達了這裡!$B$B有報告說，有別人試圖用一種壞的版本來替換我們的產品，但是我相信我們不久之後就可以解決這個問題……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7253 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7253, 'zhTW', '如果你有辦法改善這個裝置，那就讓我們知道!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7256 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7256, 'zhTW', '我將進行最後一步。我希望它能有效...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7257 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7257, 'zhTW', '拿到鑰匙，開啟這些鎖鏈!鑰匙在『看守者』希坦亞手裡……就在洞的後面……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7274 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7274, 'zhTW', '工作/遺失和找到物品/懸賞:', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7294 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7294, 'zhTW', '嘖嘖，我的朋友！我是哈古斯，戰歌偵察騎兵的主要供給商。隨著你在戰歌氏族中的地位不斷提升，我可以提供一些你可以在戰歌峽谷中使用的商品。如果你需要修理裝備的話，我也可以提供這樣的服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7295 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7295, 'zhTW', NULL, '願夜之祝福永遠與你同在，我的朋友！我是艾蒂爾?月火，我是灰谷銀翼哨兵部隊的軍需官。隨著你在銀翼哨兵中的聲望不斷提升，我可以為你提供一些可在戰歌峽谷中使用的商品。如果你需要修理裝備的話，我也可以提供這樣的服務。', '願夜之祝福永遠與你同在，我的朋友！我是艾蒂爾·月火，我是灰谷銀翼哨兵部隊的軍需官。隨著你在銀翼哨兵中的聲望不斷提升，我可以為你提供一些可在戰歌峽谷中使用的商品。如果你需要修理裝備的話，我也可以提供這樣的服務。', '向您致以暗夜精靈的祝福，朋友！我是艾蒂爾·月火，我是灰谷的銀翼要塞補給員。如果你提高在銀翼要塞的聲望，我將提供給你更多精選的商品，讓你可以在戰歌峽谷中使用。如果你需要修理物品，我也能為你提供服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7314 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7314, 'zhTW', '歡迎!歡迎來到亞布·尼比蓋爾的暗月珍奇館－－各種傳奇生物跟神秘物品的大集合!請盡情的參觀，朋友!$B$B但是請注意你的手摸到的東西!神聖的神器和可怕的野獸守護著這些展品!它們可能會燒掉過度好奇的參觀者那些討厭的手...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7315 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7315, 'zhTW', '今天要我送你去哪裡，$c?', NULL, '今天要我送你去哪裡，$c?', NULL, '今天要我送你去哪裡，$c?', NULL, '今天要我送你去哪裡，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7334 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7334, 'zhTW', '你好!我的朋友，歡迎來到艾澤拉斯大陸上最偉大的博覽會!$B$B請往前走並享受我們所提供的一切。讓暗月馬戲團在這個巨大而神秘的世界上所發現的奇特事物為你帶來前所未有的驚奇!我們不收取任何費用，我們為你帶來無限驚喜，為孩子們帶來讓他們興奮的東西!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7335 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7335, 'zhTW', '歡迎回到艾澤拉斯大陸上最偉大的表演，我的朋友!很高興再次看到你。$B$B請往前走並享受我們所提供的一切。請務必要四處逛逛，因為我們會不斷的為暗月馬戲團增加新鮮而刺激的事物!讓我們所發現的各種新舊的奇特事物為你帶來前所未有的驚奇吧!我們會繼續不遺餘力地為各個年齡的小孩帶來雀躍不已的興奮感受!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7336 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7336, 'zhTW', '有些時候跟錢是沒關係的，朋友!我們接受很多慷慨的捐獻－－有些還是非常大的數目－－我們旅行團的所有表演者都因為想要激勵這個被戰爭撕裂的世界而充滿活力與幹勁。不需要擔心我們，相反的，讓我們擔心如何才可以最好的取悅你們吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7337 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7337, 'zhTW', '票券兌換處在這兒!將你的票券兌換成獎品!趕快來吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7338 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7338, 'zhTW', '閃開點，鄉巴佬。', NULL, '閃開點，鄉巴佬。', NULL, '閃開點，鄉巴佬。', NULL, '閃開點，鄉巴佬。', NULL, '你打擾希拉斯，就是打擾我。祝你有個愉快的一天。', NULL, '我需要第二個頭，就像我需要把第一個弄掉一樣。', NULL, '我在厄運之槌裡住過一段時間，那真的很有趣。真的。', NULL, '跟大部分的食人魔不同的是，我瞭解流動廁所是做什麼的。', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7339 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7339, 'zhTW', '我知道你會找到我的，$N。$B$B這個世界上的每一個證明都被他們所做出的選擇驅動著。一個選擇導致另一個選擇，最終這些選擇決定了你的一切，也決定了你可以從哪裡獲得財富 - 你是誰，作了什麼選擇。$B$B你準備好要發現你的財富在哪裡了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7340 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7340, 'zhTW', '很好，那就開始吧...$B$B你的主人要你去看守他的玉米田，以免盜賊跟小偷潛入。某天晚上巡邏時，你碰巧發現一個衣衫破爛、面容憔悴的人正在田裡偷取玉米。你很快的捉住他，但他乞求你饒了他的小命。他聲稱他之所以偷拿玉米是為了給他的家人吃的，因為地主－你的主人－要求太多的稅收了。你的主人確實也因為他那高昂的稅收而遠近馳名。$B$B做出你的選擇吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7341 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7341, 'zhTW', '你的下一個選擇在等著你。$B$B你是你的主人所指派的行刑者。有一個男人因為背叛了主人跟你的同胞而被送來給你。這個之前突然神秘消失的人其實是你一個很親密、很正直的朋友。你也知道他所犯的罪行可能讓很多無辜的平民因此喪失了生命。在看到你的時候，他乞求你饒了他的命，並聲稱他是被另一個有著更高權力的人所陷害。$B$B做出你的選擇吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7354 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7354, 'zhTW', '你沒看到我正在忙嗎?', '你沒看到我正在忙嗎?', '你沒看到我正在忙嗎?', '你沒看到我正在忙嗎?', '你沒看到我正在忙嗎?', '你沒看到我正在忙嗎?', '你沒看到我正在忙嗎?', '你沒看到我正在忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7355 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7355, 'zhTW', '歡迎來到暗月馬戲團年輕人!我們從世界上搜集了各種奇珍異寶任你參觀。喔，如果你能夠集滿整套的小暗月卡，請讓我知道，因為我的主人...我是說我會對它們有非常非常大的興趣的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7356 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7356, 'zhTW', '我們在世界各地散發暗月卡片，看看有沒有任何足以與其匹配的人能集齊八套暗月卡片中的任何一套。若你設法集齊八張一套的卡片，我們就會獎勵你一張高階暗月卡，不但可拿來作為一樣力量強大的飾品也可當作暗月馬戲團的紀念。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7357 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7357, 'zhTW', '如果你收集整套的野獸套卡，你將可以得到一張高階暗月卡片:藍龍作為獎勵。這張卡片對於恢復魔法能量非常有用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7358 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7358, 'zhTW', '如果你收集整套的傳送門套卡，你將可以獲得一張高階暗月卡:虛空作為獎勵。這張卡會偶發性的在你死後將你的靈魂拖回你的身體並讓你復活。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7359 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7359, 'zhTW', '如果你收集整套的元素套卡，那你將可以得到一張高階暗月卡:漩渦作為獎勵。這張卡片會偶發性的對正在跟你戰鬥的敵人給予嚴重的傷害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7360 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7360, 'zhTW', '如果你收集整套的督軍套卡，那你將可以得到一張高階暗月卡:英雄作為獎勵。這張卡會偶發性的在你進行近身戰鬥時治療你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7361 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7361, 'zhTW', '你的下一個選擇在等著你。$B$B你奉了主人之命，出使交戰中的敵國。戰爭讓雙方都元氣大傷，你的使命是確保兩國人民都可以獲得可敬的和平。$B$B在外交宴會上，你無意中聽到敵國的統治者惡意中傷你的主人。你斷定他原本是想揹著你說的，但他還是辱及了你的主人的威名。$B$B做出你的選擇吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7362 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7362, 'zhTW', '你的下一個選擇在等著你。$B$B你的兄弟想要加入你所在的享有盛名的軍隊。你對他的責任心和忠誠毫不懷疑，但是你擔心他的能力還不足以執行軍隊艱鉅的任務。你無法確定他能否接受挑戰─這可能會讓你和其他人陷入危機─但是你知道你的話將決定他的去留。$B$B做出你的選擇吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7363 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7363, 'zhTW', '你的下一個選擇在等著你。$B$B你憑藉自己的力量殺死了一頭破壞農田的可怕野獸，並且割下它的耳朵作為戰利品。後來你聽說你的主人在懸賞這頭野獸的性命，你所認識的一位仁慈但貧窮的騎士說自己殺死了這頭野獸，想要領取賞金養家餬口。你自己並不需要錢，但是你知道這傢伙謊報實情，牟取私利。$B$B做出你的選擇吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7364 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7364, 'zhTW', '你的占卜已經完成了，$c。在接下來的幾個小時中，你將發現你的精神與你真正的天性趨於一致。你要小心，因為你的財富－－及你的命運－－並不像你所想的那麼條理清晰。$B$B如果你想要對你的未來有所瞭解，那麼儘管告訴我。我會很樂意給你一張手寫的籤詩，你的揹包中必須留有足夠的空間。這張籤詩是根據你回答我的問題時的意象所抽出來的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7365 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7365, 'zhTW', '$N，這是你的籤詩。願你能好好利用它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7366 AND `Locale` = 'zhTW';
