INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7383, 'zhTW', '歡迎來到暗月馬戲團，$c!$B$B我叫克莉·希克斯，我應該跟你握手致意的，但是我怕會把你的手捏碎，因為我是當今世上最強壯的女人!', '歡迎來到暗月馬戲團，$c!$B$B我叫克莉·希克斯，我應該跟你握手致意的，但是我怕會把你的手捏碎，因為我是當今世上最強壯的女人!', '歡迎來到暗月馬戲團，$c!$b$b我叫克莉·希克斯，我應該跟你握手致意的，但是我怕會把你的手捏碎，因為我是當今世上最強壯的女人!', '歡迎來到暗月馬戲團，$c!$B$B我叫克莉·希克斯，我應該跟你握手致意的，但是我怕會把你的手捏碎，因為我是當今世上最強壯的女人!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
