INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7393, 'zhTW', '唉...很抱歉，我現在還不能告訴你關於你的命運，你不久前才從我這兒獲得了關於命運的資訊。$B$B過幾個小時你再來找我吧。命運的力量將會有所改變，那時候我就可以洞察你的未來了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7394 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7394, 'zhTW', '$N，很高興再次見到你!你玩得開心嗎?$B$B想要來比腕力嗎?不，當然不……你還想保有自己的手臂吧!', '$N，很高興再次見到你!你玩得開心嗎?$B$B想要來比腕力嗎?不，當然不……你還想保有自己的手臂吧!', '$N，很高興再次見到你！你玩得開心嗎？想要來掰手腕嗎？不，當然不……你想要保護好自己的手臂！', '$N，很高興再次見到你!你玩得開心嗎?$B$B想要來比腕力嗎?不，當然不……你還想保有自己的手臂吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7395 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7395, 'zhTW', '你好。我是克洛諾斯－－過目不忘的克洛諾斯。我的記憶力毫無瑕疵，而且連最微小的細節都記得一清二楚。$B$B相信我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7396 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7396, 'zhTW', '又見面了，$n。你認為我會忘記你?$B$B我知道你不會這麼認為的。你是個聰明的$c，你所認識的我只要看到任何人就可以立即認出$g他:她;。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7397 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7397, 'zhTW', '你好!歡迎你!恐怕我的攤位還不能開張...有很多東西得修理...$B$B但是我仍然受制於血的詛咒，求你啦，笑一笑吧。如果你的臉上沒有笑容的話，我就得砍下我的手，並且在手掌再生之前不得食用任何肉類...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7398 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7398, 'zhTW', '$n，你回來啦!我上次吃掉的那些靈魂說你會來看我的，而且我們還會談點生意。$B$B他們說對了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7399 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7399, 'zhTW', '嗨，$n!很高興又見到你了!暗月馬戲團真是一場盛大的展覽，不是嗎?$B$B有很多東西值得一看!看吧!或許有一天，還會有更多的東西呈現在你面前...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7400 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7400, 'zhTW', '我找不到我的寵物啾啾啦。她喜歡喝黑鐵麥芽酒，那是她唯一肯喝的飲料，但是卻很難取得!現在麥芽酒已經沒有了...啾啾一定是自己跑去找酒喝了!$B$B我希望她可以趕快回來...', '我找不到我的寵物啾啾啦。她喜歡喝黑鐵麥芽酒，那是她唯一肯喝的飲料，但是卻很難取得!現在麥芽酒已經沒有了...啾啾一定是自己跑去找酒喝了!$B$B我希望她可以趕快回來...', '我找不到我的寵物啾啾啦。她喜歡喝黑鐵啤酒，那是她唯一肯喝的飲料，但是卻很難取得!現在啤酒已經沒有了……啾啾一定是自己跑去找酒喝了!$b$b我希望她可以趕快回來……', '我找不到我的寵物啾啾啦。她喜歡喝黑鐵麥芽酒，那是她唯一肯喝的飲料，但是卻很難取得!現在麥芽酒已經沒有了……啾啾一定是自己跑去找酒喝了!$B$B我希望她可以趕快回來……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7401 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7401, 'zhTW', '啾啾回來了!我太高興了!我只希望我的黑鐵麥芽酒不會很快又被喝光了，不然我怕我的小青蛙可能會再一次偷跑出去的!', '啾啾回來了!我太高興了!我只希望我的黑鐵麥芽酒不會很快又被喝光了，不然我怕我的小青蛙可能會再一次偷跑出去的!', '啾啾回來了!我太高興了!我只希望我的黑鐵麥芽酒不會很快又被喝光了，不然我怕我的小青蛙可能會再一次偷跑出去的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
