INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7517, 'zhTW', '要贏得這場戰爭，我們不能坐在這裡，靜待戰爭之潮將我們淹沒。我們必須果斷出擊，否則阿拉希永遠也不會成為我們的囊中之物。', '要贏得這場戰爭，我們不能坐在這裡，靜待戰爭之潮將我們淹沒。我們必須果斷出擊，否則阿拉希永遠也不會成為我們的囊中之物。', '要贏得這場戰爭，我們不能坐在這裡，靜待戰爭之潮將我們淹沒。我們必須果斷出擊，否則阿拉希永遠也不會成為我們的囊中之物。', '要贏得這場戰爭，我們不能坐在這裡，靜待戰爭之潮將我們淹沒。我們必須果斷出擊，否則阿拉希永遠也不會成為我們的囊中之物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7519 AND `Locale` = 'zhTW';
