INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7525, 'zhTW', '那裡很冷！你應該去皇家區找格里茲爾談談。', '那裡很冷！你應該去皇家區找格里茲爾談談。', '那裡很冷！你應該去皇家區找格里茲爾談談。', '這裡很冷，你去皇家區，和格里茲爾·半鬃談談吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
