INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7528, 'zhTW', '戰歌峽谷？好吧。你應該去跟武器大廳的萊蘭迪斯談一談。', '戰歌峽谷？好吧。你應該去跟武器大廳的萊蘭迪斯談一談。', '戰歌峽谷？好吧。你應該去跟武器大廳的萊蘭迪斯談一談。', '你說戰歌峽谷？那麼你得和軍事大廳的萊蘭迪斯好好談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
