INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7534, 'zhTW', '你想要什麼?$B$B梅維基只跟德魯伊和薩滿往來。', '你想要什麼?$B$B梅維基只跟德魯伊和薩滿往來。', '你想要什麼?$b$b梅維克只跟德魯伊和薩滿往來。', '你想要什麼?$B$B梅維克只跟德魯伊和薩滿往來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7535 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7535, 'zhTW', '你好，$c。現在正是收穫節－一個感恩與追思的時間。我們舉辦盛宴感激所有我們應該感激的人，追憶我們的祖先和英雄，感謝他們給我們留下的寶貴遺產。$B$B請盡情享受這盛宴吧。我還提供一些煙火來慶祝這個美好的日子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7536 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7536, 'zhTW', '你好，$c。現在正是收穫節－一個感恩與追思的時間。我們舉辦盛宴感激所有我們應該感激的人，追憶我們的祖先和英雄，感謝他們給我們留下的寶貴遺產。$B$B請盡情享受這盛宴吧。我還提供一些煙火來慶祝這個美好的日子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7554 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7554, 'zhTW', '我們絕不能讓聯盟在阿拉希擴張勢力!既便是小小的避難谷地，在將來也可能對我們形成威脅。', '我們絕不能讓聯盟在阿拉希擴張勢力!既便是小小的避難谷地，在將來也可能對我們形成威脅。', '我們絕不能讓聯盟在阿拉希擴張勢力!既便是小小的避難谷地，在將來也可能對我們形成威脅。', '我們絕不能讓聯盟在阿拉希擴張勢力!既便是小小的避難谷地，在將來也可能對我們形成威脅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7555 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7555, 'zhTW', '阿拉希盆地的戰鬥是一場謀略戰。木材、礦石、食物……所有這些物資對戰鬥來說都是必需品。$B$B摧毀敵方的物資跟在戰場上殺死他們一樣重要。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7556 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7556, 'zhTW', '我眼睛雖然看不到，但是我還擁有洞察力。$B$B我主要跟獵人和盜賊打交道，$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7574 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7574, 'zhTW', '冒險者，你好。我是贊達拉的商人林沃斯。我來自南海，從我的家鄉帶來了許多新奇的貨物。$B$B如果你能證明自己的價值，我會樂意與你交換物品的。如果你有我們部族的榮譽勳章，我這裡還有些更好的東西……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7594 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7594, 'zhTW', '我是贊達拉的贊札。我用以太形態從贊達拉趕來幫助我的人民。哈卡不能控制我的靈魂。$B$B我是來幫助那些曾經有恩於贊達拉的朋友的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7595 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7595, 'zhTW', '贊達拉的朋友!你已經進入血神的巢穴深處，$c。你最好仔細聽我說。$B$B數千年前，當祖阿曼帝國的食人妖與入侵的高等精靈異教徒作戰時，高等精靈盜取了贊札強大的魔法，在自己的武器和護甲上附魔，以此征服當地的食人妖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7596 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7596, 'zhTW', '是嗎?這麼說你已經知道高等精靈所掌握的食人妖魔法有多麼淺顯了?$B$B高等精靈怎麼都想不明白，作為一個與魔法密切相關的種族，他們為何無法駕馭食人妖巫毒的力量。對這些白皮膚的生靈而言，這簡直難以置信。他們只好使用一種不純的食人妖法術來增強他們的魔法力量。我想他們稱其為「秘紋」。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7597 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7597, 'zhTW', '只要有正確的材料，贊札就能製造古老的食人妖附魔。這種魔法能幫助你打敗哈卡和他的爪牙。$B$B我只要你幫我找2種東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7598 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7598, 'zhTW', '首先你得從強大的哈卡副官:金度和血領主那裡獲得一個原始的雕像。$B$B第二是打孔的巫毒人偶。你可以在散落此地的黴運巫毒垃圾堆中找到。$B$B把這些物品都給我找來，我會為你進行一次強效的附魔!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7599 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7599, 'zhTW', '很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。', '很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。', '很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。', '很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
