INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7634, 'zhTW', '權力珍寶是古代古拉巴什帝國的遺物。贊達拉部族正在尋找它們─它們不僅有著極大的收藏價值，而且我們相信它們還蘊藏著遠古帝國的魔法。$B$B你可以在祖爾格拉布找到三種權力珍寶:硬幣、珠寶和原始神靈的物品。收集到一定數量之後，把這些東西交給我們，我們就會送你一些贊達拉最好的工藝製品。', '權力珍寶是古代古拉巴什帝國的遺物。贊達拉部族正在尋找它們─它們不僅有著極大的收藏價值，而且我們相信它們還蘊藏著遠古帝國的魔法。$B$B你可以在祖爾格拉布找到三種權力珍寶:硬幣、珠寶和原始神靈的物品。收集到一定數量之後，把這些東西交給我們，我們就會送你一些贊達拉最好的工藝製品。', '權力珍寶是古代古拉巴什帝國的遺物。贊達拉部族正在尋找它們─它們不僅有著極大的收藏價值，而且我們相信它們還蘊藏著遠古帝國的魔法。$b$b你可以在祖爾格拉布找到三種權力珍寶:硬幣、珠寶和原始神靈的物品。收集到一定數量之後，把這些東西交給我們，我們就會送你一些贊達拉最好的工藝製品。', '權力珍寶是古代古拉巴什帝國的遺物。贊達拉部族正在尋找它們─它們不僅有著極大的收藏價值，而且我們相信它們還蘊藏著遠古帝國的魔法。$B$B你可以在祖爾格拉布找到三種權力珍寶:硬幣、珠寶和原始神靈的物品。收集到一定數量之後，把這些東西交給我們，我們就會送你一些贊達拉最好的工藝製品。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7635 AND `Locale` = 'zhTW';
