INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7638, 'zhTW', '在我看來，釣魚的美妙之處在於其緩慢的節奏。人們可以在釣魚的過程中思考、回想過去和計畫未來。$B$B哦，當然這也是用來大醉一場的絕佳理由。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7639 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7639, 'zhTW', '再次感謝你找回了我的幸運捲尺，$N。這東西能幫我捕到更大的魚呢!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7640 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7640, 'zhTW', '你需要一種特殊的臭泥魚誘餌來捕捉加茲蘭卡。這些魚餌是我親自制作的!$B$B但是除了魚餌之外，你還需要臭泥魚……你得把臭泥魚放入誘餌，讓它充滿臭味!$B$B將做好的誘餌放到祖爾格拉布中的帕格漁場……然後就坐下來喝酒等待……你無需等太久，因為加茲蘭卡肯定會迫不及待地上鉤!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7641 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7641, 'zhTW', '*吱吱**叮噹*$B$B我奉命收購肥美的稀有魚類，用納特·帕格的釣魚用品來交換哦。收購魚類啦。$B$B*砰**?嗡*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7642 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7642, 'zhTW', '很抱歉，$c，在你變得更加強大之前，我不能讓你去阿拉希盆地送死。', '很抱歉，$c，在你變得更加強大之前，我不能讓你去阿拉希盆地送死。', '很抱歉，$c，在你變得更加強大之前，我不能讓你去阿拉希盆地送死。', '很抱歉，$c，在你變得更加強大之前，我不能讓你去阿拉希盆地送死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
