INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7643, 'zhTW', '鋼鐵之血格里雷克$B$B漫遊者。願他的力量和對戰爭的渴望生生不息。$B$B格里雷克正在遙遠的地方徘徊。總有一天，他會回來的……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7644 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7644, 'zhTW', '去勇者大廳找汙染者迪茲?斯諾班，他會幫助你進入阿拉希盆地的。', '去勇者大廳找汙染者迪茲?斯諾班，他會幫助你進入阿拉希盆地的。', '去勇者大廳找汙染者迪茲·斯諾班，他會幫助你進入阿拉希盆地的。', '到勇士大廳去找汙染者迪茲·斯諾班，他會引導你加入阿拉希盆地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7645 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7645, 'zhTW', '臭泥魚是一種散發著特殊臭味的魚，它們生活在熱帶水域中。祖利安臭泥魚則是其中最臭的一種，只有在祖爾格拉布的水域中才能找到。$B$B我想一定是祖力安臭泥魚引來了加茲蘭卡，儘管食人妖會告訴你它是食人妖膜拜的眾多神靈之一，但是……$B$B相信自己─用祖利安臭泥魚製成的誘餌去捕捉加茲蘭卡吧，那傢伙肯定會上鉤的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7646 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7646, 'zhTW', '去聖殿區找瑪洛維爾爵士。', '去聖殿區找瑪洛維爾爵士。', '去聖殿區找瑪洛維爾爵士。', '去聖殿區找瑪洛維爾爵士。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7648 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7648, 'zhTW', '去靈魂高地下面的預見之池找馬丁?林塞。他會幫助你轉至阿拉希盆地。', '去靈魂高地下面的預見之池找馬丁?林塞。他會幫助你轉至阿拉希盆地。', '去靈魂高地下面的預見之池找馬丁·林塞。他會幫助你前往阿拉希盆地。', '你該去找預見之池的馬丁·林塞，就在靈魂高地的下面，他會幫助你到達阿拉希盆地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7649 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7649, 'zhTW', '在阿拉希盆地跟被遺忘者作戰的人類需要你的幫助。去武器大廳找他們的代表杜納爾?奧斯古德談談。', '在阿拉希盆地跟被遺忘者作戰的人類需要你的幫助。去武器大廳找他們的代表杜納爾?奧斯古德談談。', '在阿拉希盆地跟被遺忘者作戰的人類需要你的幫助。去武器大廳找他們的代表杜納爾·奧斯古德談談。', '人類需要你的幫助，在阿拉希盆地與汙染者作戰，到軍事大廳和杜納爾·奧斯古談談吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7650 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7650, 'zhTW', '阿拉索聯軍在阿拉希盆地所做的一切令人敬佩。可惜亡靈憎惡和他們的部落盟友擋住了去路。去暴風要塞國王的覦見室找到赫塔希姆吧，她會幫你轉至阿拉希盆地的。', '阿拉索聯軍在阿拉希盆地所做的一切令人敬佩。可惜亡靈憎惡和他們的部落盟友擋住了去路。去暴風要塞國王的覦見室找到赫塔希姆吧，她會幫你轉至阿拉希盆地的。', '阿拉索聯軍在阿拉希盆地所做的一切令人敬佩。可惜亡靈憎惡和他們的部落盟友擋住了去路。去暴風要塞國王的覦見室找到赫塔希姆吧，她會幫你前往阿拉希盆地的。', '你可以在國王的晉見室找到赫塔希姆女士，她能幫你抵達阿拉希盆地，在那裡阿拉索盟軍正需要援助來對抗汙染者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7651 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7651, 'zhTW', NULL, '人類迫切需要我們在阿拉希盆地給予援助，有個人你可能需要和他談談，他叫克拉斯·狼心，他就在戰士區等著你呢。', NULL, '人類迫切需要我們在阿拉希盆地給予援助，有個人你可能需要和他談談，他叫克拉斯·狼心，他就在戰士區等著你呢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7652 AND `Locale` = 'zhTW';
