INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7689, 'zhTW', '$C，我們需要你的幫助來在戰歌峽谷對抗銀翼哨兵。在那裡你可以獲取無上的榮耀!你是否有勇氣去和我們的戰場軍官對話呢?', '$C，我們需要你的幫助來在戰歌峽谷對抗銀翼哨兵。在那裡你可以獲取無上的榮耀!你是否有勇氣去和我們的戰場軍官對話呢?', '$C，我們需要你的幫助來在戰歌峽谷對抗銀翼哨兵。在那裡你可以獲取無上的榮耀!你是否有勇氣去和我們的戰場軍官對話呢?', '$C，我們需要你的幫助來在戰歌峽谷對抗銀翼哨兵。在那裡你可以獲取無上的榮耀!你是否有勇氣去和我們的戰場軍官對話呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
