INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7690, 'zhTW', '很榮幸我能告訴你，布萊克歐·死亡召喚者就在勇士大廳等著協助你抵達戰歌峽谷，你能在榮譽谷找到他。', '很榮幸我能告訴你，布萊克歐·死亡召喚者就在勇士大廳等著協助你抵達戰歌峽谷，你能在榮譽谷找到他。', NULL, '很榮幸我能告訴你，布萊克歐·死亡召喚者就在勇士大廳等著協助你抵達戰歌峽谷，你能在榮譽谷找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
