INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7694, 'zhTW', '$N，現在，奧特蘭克山谷的雷矛衛兵需要你助戰，共同打敗霜狼氏族。這是個獲得榮譽、提升聲望的大好機會!你需要知道戰場軍官在哪裡，好讓他們送你一程嗎?', '$N，現在，奧特蘭克山谷的雷矛衛兵需要你助戰，共同打敗霜狼氏族。這是個獲得榮譽、提升聲望的大好機會!你需要知道戰場軍官在哪裡，好讓他們送你一程嗎?', '$N，現在，奧特蘭克山谷的雷矛衛兵需要你助戰，共同打敗霜狼氏族。這是個獲得榮譽、提升聲望的大好機會!你需要知道戰場軍官在哪裡，好讓他們送你一程嗎?', '$N，現在，奧特蘭克山谷的雷矛衛兵需要你助戰，共同打敗霜狼氏族。這是個獲得榮譽、提升聲望的大好機會!你需要知道戰場軍官在哪裡，好讓他們送你一程嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
