INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7696, 'zhTW', '釣魚大師巴斯貝特已經在這片水域中放入了美味的可口魚，釣魚比賽可以開始啦。$B$B一旦勝出，我會按五條可口魚換一銀幣的價格進行交換!', '釣魚大師巴斯貝特已經在這片水域中放入了美味的可口魚，釣魚比賽可以開始啦。$B$B一旦勝出，我會按五條可口魚換一銀幣的價格進行交換!', '釣魚大師巴斯貝特已經在這片水域中放入了美味的可口魚，釣魚比賽可以開始啦。$b$b一旦勝出，我會按五條可口魚換一銀幣的價格進行交換!', '釣魚大師巴斯貝特已經在這片水域中放入了美味的可口魚，釣魚比賽可以開始啦。$B$B一旦勝出，我會按五條可口魚換一銀幣的價格進行交換!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7697 AND `Locale` = 'zhTW';
