INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7700, 'zhTW', '阿拉希盆地急需增援，你能幫助我們嗎，$c?這是個獲得榮譽、提升聲望的大好機會。你的幫助定能扭轉局勢，幫助我們打敗汙染者。我們能將希望寄託到你身上嗎?', '阿拉希盆地急需增援，你能幫助我們嗎，$c?這是個獲得榮譽、提升聲望的大好機會。你的幫助定能扭轉局勢，幫助我們打敗汙染者。我們能將希望寄託到你身上嗎?', '阿拉希盆地急需增援，你能幫助我們嗎，$c?這是個獲得榮譽、提升聲望的大好機會。你的幫助定能扭轉局勢，幫助我們打敗汙染者。我們能將希望寄託到你身上嗎?', '阿拉希盆地急需增援，你能幫助我們嗎，$c?這是個獲得榮譽、提升聲望的大好機會。你的幫助定能扭轉局勢，幫助我們打敗汙染者。我們能將希望寄託到你身上嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
