INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7703, 'zhTW', '太棒了，趕跑阿拉希盆地的汙染者與部落幫兇，你將為聯盟作出重大貢獻！到暴風城的覲見室去找赫塔希姆女士吧，她正在等你，$N。', '太棒了，趕跑阿拉希盆地的汙染者與部落幫兇，你將為聯盟作出重大貢獻！到暴風城的覲見室去找赫塔希姆女士吧，她正在等你，$N。', NULL, '太棒了，趕跑阿拉希盆地的汙染者與部落幫兇，你將為聯盟作出重大貢獻！到暴風城的覲見室去找赫塔希姆女士吧，她正在等你，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7704 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7704, 'zhTW', '四季輪迴變幻，但是你年紀尚輕。當你經歷更多之後再來找我們吧，$c。', '四季輪迴變幻，但是你年紀尚輕。當你經歷更多之後再來找我們吧，$c。', '四季輪迴變幻，但是你年紀尚輕。當你經歷更多之後再來找我們吧，$c。', '四季輪迴變幻，但是你年紀尚輕。當你經歷更多之後再來找我們吧，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7705 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7705, 'zhTW', '$C，我們感到非常慚愧，戰歌峽谷一役迫切需要增援。如果你願意助我們一臂之力的話，你將獲得前所未有的榮譽。銀翼哨兵對你的所做所為表示敬意。我帶你去戰場軍官那兒，好嗎?', '$C，我們感到非常慚愧，戰歌峽谷一役迫切需要增援。如果你願意助我們一臂之力的話，你將獲得前所未有的榮譽。銀翼哨兵對你的所做所為表示敬意。我帶你去戰場軍官那兒，好嗎?', '$C，我們感到非常慚愧，戰歌峽谷一役迫切需要增援。如果你願意助我們一臂之力的話，你將獲得前所未有的榮譽。銀翼哨兵對你的所做所為表示敬意。我帶你去戰場軍官那兒，好嗎?', '$C，我們感到非常慚愧，戰歌峽谷一役迫切需要增援。如果你願意助我們一臂之力的話，你將獲得前所未有的榮譽。銀翼哨兵對你的所做所為表示敬意。我帶你去戰場軍官那兒，好嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7706 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7706, 'zhTW', '艾露恩的光輝永遠照耀著你，$N!你可以去找戰士區的艾薩拉斯——我們的戰場軍官，她會協助你抵達戰歌峽谷。', '艾露恩的光輝永遠照耀著你，$N!你可以去找戰士區的艾薩拉斯——我們的戰場軍官，她會協助你抵達戰歌峽谷。', NULL, '艾露恩的光輝永遠照耀著你，$N!你可以去找戰士區的艾薩拉斯——我們的戰場軍官，她會協助你抵達戰歌峽谷。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7707 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7707, 'zhTW', '權力珍寶是古拉巴什帝國的遺物。贊達拉氏族正在尋找權力珍寶─它們不僅具富收藏價值，贊達拉氏族還相信它們含有遠古帝國使用的強效魔精。$B$B你可以在祖爾格拉布找到三種權力珍寶:硬幣、寶石和原始物品。一旦你收集到一定數量的權力珍寶，你將獲得贊達拉氏族製作的最好的物品。$B$B獎勵豐厚，值得一試!', '權力珍寶是古拉巴什帝國的遺物。贊達拉氏族正在尋找權力珍寶─它們不僅具富收藏價值，贊達拉氏族還相信它們含有遠古帝國使用的強效魔精。$B$B你可以在祖爾格拉布找到三種權力珍寶:硬幣、寶石和原始物品。一旦你收集到一定數量的權力珍寶，你將獲得贊達拉氏族製作的最好的物品。$B$B獎勵豐厚，值得一試!', '權力珍寶是古拉巴什帝國的遺物。贊達拉氏族正在尋找權力珍寶─它們不僅具富收藏價值，贊達拉氏族還相信它們含有遠古帝國使用的強效魔精。$b$b你可以在祖爾格拉布找到三種權力珍寶:硬幣、寶石和原始物品。一旦你收集到一定數量的權力珍寶，你將獲得贊達拉氏族製作的最好的物品。$b$b獎勵豐厚，值得一試!', '權力珍寶是古拉巴什帝國的遺物。贊達拉氏族正在尋找權力珍寶─它們不僅具富收藏價值，贊達拉氏族還相信它們含有遠古帝國使用的強效魔精。$B$B你可以在祖爾格拉布找到三種權力珍寶:硬幣、寶石和原始物品。一旦你收集到一定數量的權力珍寶，你將獲得贊達拉氏族製作的最好的物品。$B$B獎勵豐厚，值得一試!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7708 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7708, 'zhTW', '時間證明你的明智，$c。謝謝你，你可以在軍事大廳找到我們的戰場軍官——萊蘭迪斯，她能協助你抵達戰歌峽谷。', '時間證明你的明智，$c。謝謝你，你可以在軍事大廳找到我們的戰場軍官——萊蘭迪斯，她能協助你抵達戰歌峽谷。', NULL, '時間證明你的明智，$c。謝謝你，你可以在軍事大廳找到我們的戰場軍官——萊蘭迪斯，她能協助你抵達戰歌峽谷。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7709 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7709, 'zhTW', '銀翼哨兵向您致敬，$c！你能在暴風城的覲見室找到我們的戰場軍官——艾弗拉蘭，願女神永遠照耀你！', '銀翼哨兵向您致敬，$c！你能在暴風城的覲見室找到我們的戰場軍官——艾弗拉蘭，願女神永遠照耀你！', NULL, '銀翼哨兵向您致敬，$c！你能在暴風城的覲見室找到我們的戰場軍官——艾弗拉蘭，願女神永遠照耀你！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7712 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7712, 'zhTW', '很高興遇到你，漁夫!如果你想要在釣魚好手中一展自己的釣魚技能，那麼就聽好了!在本週日，荊棘谷將舉辦一場釣魚大賽，選出一名釣魚大師!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7713 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7713, 'zhTW', '權力珍寶是強大的魔精，是古拉巴什帝國的魔精。我們贊德拉部族必須得到魔精，必須把魔精佔為己有。血神將無法毀滅我們。$B$B在祖爾格拉布有三種權力珍寶。去找到硬幣，找到珠寶。找到原始神靈的物品。這些都是權力珍寶。$B$B現在就去祖爾格拉布，屠殺!然後拿到權力珍寶。把它們帶給部族，獲得我們的尊敬，贏得我們對你的獎勵，得到真正的力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7714 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7714, 'zhTW', '釣魚大賽的贏家已經出爐了，但是賈恩願意收購你們釣到的可口魚!$B$B每週日都會有一場釣魚大賽，你儘可展示自己的釣魚技能!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7717 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7717, 'zhTW', '在我身後是贊札祭壇，是贊達拉氏族的神聖之地。我們在此禱告，希望能充分做好對抗血神哈卡的準備工作。$B$B利用祭壇摧毀你在祖爾格拉布找到的任何哈卡萊寶石，以此證明你對氏族的價值。我會用贊達拉榮譽硬幣跟你交換祖爾格拉布的硬幣。找到我需要的硬幣，你將獲得豐厚的獎勵!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7718 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7718, 'zhTW', '贊達拉食人妖長途跋涉、歷經艱險才來到此地，但是這一切卻招致我們的厄運……', '贊達拉食人妖長途跋涉、歷經艱險才來到此地，但是這一切卻招致我們的厄運……', '贊達拉食人妖長途跋涉、歷經艱險才來到此地，但是這一切卻招致我們的厄運……', '贊達拉食人妖長途跋涉、歷經艱險才來到此地，但是這一切卻招致我們的厄運……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7720 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7720, 'zhTW', '我們，贊達拉食人妖長途跋涉來此，因為我們無法坐視即將到來的危機。$B$B我們的遠征隊首領莫托爾帶領我們來到荊棘谷海岸以北的尤亞姆巴島，儘管如此，依然有勇敢的英雄前來造訪這座古老的食人妖城市……祖爾格拉布。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7721 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7721, 'zhTW', '我們，贊達拉食人妖長途跋涉來此，因為我們無法坐視即將到來的危機。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7722 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7722, 'zhTW', '老狗學不會新把戲。至少我聽人這麼說過。你運氣真好，我發現這種說法是錯誤的。$B$B現在，你想讓你的寵物遺忘天賦嗎?', '老狗學不會新把戲。至少我聽人這麼說過。你運氣真好，我發現這種說法是錯誤的。$B$B現在，你想讓你的寵物遺忘天賦嗎?', '老狗學不會新把戲。至少我聽人這麼說過。你運氣真好，我發現這種說法是錯誤的。$b$b但是，寵物對此有所牴觸，因此我需要更多的食物是它們保持快樂。這就是說，我每廢除寵物的技能一次，你就需要付出更多的金幣。$b$b現在，我可以開始廢除寵物技能了嗎?', '老狗學不會新把戲。至少我聽人這麼說過。你運氣真好，我發現這種說法是錯誤的。$B$B但是，寵物對此有所牴觸，因此我需要更多的食物是它們保持快樂。這就是說，我每廢除寵物的技能一次，你就需要給我更多的金幣。$B$B現在，我可以開始廢除寵物技能了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7723 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7723, 'zhTW', '我是駐紮在阿拉希盆地的汙染者物資供應商盧瑟弗·圖恩。隨著你在汙染者的聲望的提升，我可以出售給你一些非常有用的物品。如果你需要修理裝備，我也樂意為你服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7724 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7724, 'zhTW', '我是駐紮在阿拉希盆地的阿拉索聯軍物資供應商薩繆爾·霍克。隨著你在阿拉索聯軍的聲望的提升，我可以出售給你一些非常有用的物品。如果你需要修理裝備，我也樂意為你服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7725 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7725, 'zhTW', '戰歌峽谷一役至關重要，我們必須獲勝。我們為了榮譽和國家而戰，獸人或是那些誤入歧途的盟友是無法打敗我們的!', '戰歌峽谷一役至關重要，我們必須獲勝。我們為了榮譽和國家而戰，獸人或是那些誤入歧途的盟友是無法打敗我們的!', '戰歌峽谷一役至關重要，我們必須獲勝。我們為了榮譽和國家而戰，獸人或是那些誤入歧途的盟友是無法打敗我們的!', '戰歌峽谷一役至關重要，我們必須獲勝。我們為了榮譽和國家而戰，獸人或是那些誤入歧途的盟友是無法打敗我們的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7726 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7726, 'zhTW', '要保護部落在梣谷的木材收集工作並不容易，但是我們從不畏懼戰鬥!夜精靈和他們的盟友必將失敗!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7727 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7727, 'zhTW', '噢，你這可憐的傢伙，你從頭到腳都是沙!歡迎在這個美麗的綠洲休息並回復你的體力。', '噢，你這可憐的傢伙，你從頭到腳都是沙!歡迎在這個美麗的綠洲休息並回復你的體力。', '你好，旅人。只要你待在塞納里奧城堡的城牆裡，就可以免受一切傷害。$b$b當你離開城堡的保護之後要特別小心，異種生物在這片土地上橫行。', '你好，旅人。只要你待在塞納里奧城堡的城牆裡，就可以免受一切傷害。$B$B當你離開城堡的保護之後要特別小心，異種生物在這片土地上橫行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7728 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7728, 'zhTW', '我向城堡提供各種施法所需的碎片和其他鏈金材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7729 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7729, 'zhTW', '一股強大的邪惡力量正在蠢蠢欲動，$R。你感覺到了沒?$B$B啊!當然你無法感覺到。把你的護甲和武器給我吧，我會讓它們恢復活力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7730 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7730, 'zhTW', '唉，我現在的補給品儲量已經非常少了!是什麼耽擱了那個該死的地精那麼長時間?', '唉，我現在的補給品儲量已經非常少了!是什麼耽擱了那個該死的地精那麼長時間?', '唉，我現在的補給品儲量已經非常少了!是什麼耽擱了那個該死的地精那麼長時間?', '唉，我現在的補給品儲量已經非常少了!是什麼耽擱了那個該死的地精那麼長時間?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7731 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7731, 'zhTW', '看看你身後，$R。蟲巢中的異動使我們周圍的土地震動起來。$B$B現在是我們實現一千年前許下的諾言的時候了。沙土飛揚，似乎其拉蟲人是在計畫開戰了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7732 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7732, 'zhTW', '為什麼是現在，$r?我不明白。要做的事情還有很多...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7733 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7733, 'zhTW', '指揮官最近一直心不在焉。他的妻子在最近的一次南部沙漠考古挖掘中失蹤了─一下子消失地蹤影全無!真的非常奇怪。$B$B我想你是不是想要找份工作?我是不是可以給你一些提示?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7734 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7734, 'zhTW', '你可以聽到嗎，陌生人?嗡嗡的聲音一天比一天響。這些水晶一定是把那些蟲子逼瘋的元兇。', '你可以聽到嗎，陌生人?嗡嗡的聲音一天比一天響。這些水晶一定是把那些蟲子逼瘋的元兇。', '你可以聽到嗎，陌生人?嗡嗡的聲音一天比一天響。這些水晶一定是把那些蟲子逼瘋的元兇。', '你可以聽到嗎，陌生人?嗡嗡的聲音一天比一天響。這些水晶一定是把那些蟲子逼瘋的元兇。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7735 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7735, 'zhTW', '仰望天空吧，$C。這片區域已經有一千年沒有見過龍族軍團了!我就知道，那些其拉蟲人在策劃著什麼陰謀!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7736 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7736, 'zhTW', '銅須再次失蹤了!那傢伙跟他的兄弟不一樣，一點判斷力都沒有。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7737 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7737, 'zhTW', '燃燒稻草人產生的灰燼散發出了魔法的力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7738 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7738, 'zhTW', '燃燒稻草人產生的灰燼散發出了魔法的力量。你把這些灰燼抹在了臉上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7739 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7739, 'zhTW', '萬鬼節快樂，$c!', NULL, '萬鬼節快樂，$c!', NULL, '萬鬼節快樂，$c!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7740 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7740, 'zhTW', '歡迎來到稻草人慶典，$c!$B$B為了慶祝萬鬼節，被遺忘者焚燒稻草人來彰顯其榮耀，最為尊崇的場合。就是這一天，女妖之王帶著我們逃出了巫妖王與天譴軍團的魔爪，從此以後我們得到了自由。我們對那些造成我們墮落之人的仇恨將會全額奉還!$B$B稻草人將會在下午8:00開始焚燒!', '歡迎來到稻草人慶典，$c!$B$B為了慶祝萬鬼節，被遺忘者焚燒稻草人來彰顯其榮耀，最為尊崇的場合。就是這一天，女妖之王帶著我們逃出了巫妖王與天譴軍團的魔爪，從此以後我們得到了自由。我們對那些造成我們墮落之人的仇恨將會全額奉還!$B$B稻草人將會在下午8:00開始焚燒!', '歡迎來到稻草人慶典，$c！\n按照萬聖節的習俗，被遺忘者要焚燒一個稻草人來紀念這個最崇高的時刻。就是在這一天，女妖之王將我們從巫妖王和天災軍團的魔掌中解救了出來，從那以後，我們就成了自由之身，直到今天。那些想要毀滅我們的敵人終將化為灰燼！\n焚燒稻草人的慶典將在晚上八點整開始！', '歡迎來到稻草人慶典，$c!$B$B為了慶祝萬鬼節，被遺忘者焚燒稻草人來彰顯其榮耀，最為尊崇的場合。就是這一天，女妖之王帶著我們逃出了巫妖王與天譴軍團的魔爪，從此以後我們得到了自由。我們對那些造成我們墮落之人的仇恨將會全額奉還!$B$B稻草人將會在下午8:00開始焚燒!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7741 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7741, 'zhTW', '你!你看起來身體強健……南海鎮需要你的幫助!$B$B萬聖節到了，那些受詛咒的被遺忘者蠢蠢欲動。他們把所謂的慶典開到我們家門口來了。如果你有時間的話，我們真的需要你的幫助!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7742 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7742, 'zhTW', '巴利斯托爾斯送來了一個最讓人印象深刻的樣本。不幸的是，時間還是太短了。在我們可以攻擊之前我們必需讓他們露出他們的脖子。$B$B耐心，凡人...有耐心點...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7744 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7744, 'zhTW', '受死吧，異教徒!願深淵的力量毀滅你!', '受死吧，異教徒!願深淵的力量毀滅你!', '受死吧，異教徒!願深淵的力量毀滅你!$b$b受死吧，異教徒!願深淵的力量毀滅你!', '受死吧，異教徒!願深淵的力量毀滅你!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7746 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7746, 'zhTW', '你好，$c。歡迎來到塞納里奧城堡。我們在這個異種生物最強盛的地方對抗他們。我希望你可以助我們一臂之力。', '你好，$c。歡迎來到塞納里奧城堡。我們在這個異種生物最強盛的地方對抗他們。我希望你可以助我們一臂之力。', '你好，$c。歡迎來到塞納里奧城堡。我們在這個異種生物最強盛的地方對抗他們。我希望你可以助我們一臂之力。', '你好，$c。歡迎來到塞納里奧城堡。我們在這個異種生物最強盛的地方對抗他們。我希望你可以助我們一臂之力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7747 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7747, 'zhTW', '我很高興再見到你，$N。你的幫助為我們保證了補給線的安全。我希望你可以理解在如此一場大戰中，物資補給的重要性。', '我很高興再見到你，$N。你的幫助為我們保證了補給線的安全。我希望你可以理解在如此一場大戰中，物資補給的重要性。', '我很高興再見到你，$N。你的幫助為我們保證了補給線的安全。我希望你可以理解在如此一場大戰中，物資補給的重要性。', '我很高興再見到你，$N。你的幫助為我們保證了補給線的安全。我希望你可以理解在如此一場大戰中，物資補給的重要性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7748 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7748, 'zhTW', NULL, '暮光之錘的事情沒有什麼進展?去搜尋一下東南面的山嶺吧。傳言說那裡居住著一個神秘的隱士。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7749 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7749, 'zhTW', '你這渺小的蟲子，你竟敢跟議會公爵交談!', '你這渺小的蟲子，你竟敢跟議會公爵交談!', '你這渺小的蟲子，你竟敢跟議會公爵交談!', '你這渺小的蟲子，你竟敢跟議會公爵交談!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7751 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7751, 'zhTW', '你是在獵殺死亡彎鉤吧，$N?我記得很清楚。這周我手下的兩個家夥就是被她殺死的。希望你的運氣比他們好。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7752 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7752, 'zhTW', '嗨!謝謝你手下留情，沒有懲罰我!我想我得躺一會兒恢復體力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7753 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7753, 'zhTW', '你是誰?我在哪兒?我感到...非常虛弱...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7754 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7754, 'zhTW', '議會領主面前出現了一隻蟲子?沒錯，無疑是一隻想要被碾碎的蟲子!', '議會領主面前出現了一隻蟲子?沒錯，無疑是一隻想要被碾碎的蟲子!', '議會領主面前出現了一隻蟲子?沒錯，無疑是一隻想要被碾碎的蟲子!', '議會領主面前出現了一隻蟲子?沒錯，無疑是一隻想要被碾碎的蟲子!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7755 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7755, 'zhTW', '你最好坐下，這是個很長的故事。$B$B當我們第一次來到希利蘇斯時，瑪爾利斯女士是塞納里奧城堡中第一位加入遠征隊的夜精靈。我們的行程沒有什麼特別的:組隊進入蟲巢探險，尋找失落的神器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7756 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7756, 'zhTW', '很明顯!蟲巢中住著各種不歡迎我們到來的異種蟲。$B$B一切進展順利，直到我們在雷戈蟲巢中發現了一塊雕紋水晶。她像飛蛾撲火一般往水晶靠過去!她把可愛的臉頰湊上去，精神也變得恍惚起來。隊友們都很擔心她。我們以最快的速度將她帶出了蟲巢!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7757 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7757, 'zhTW', '我們把她交給了指揮官，希望議會的德魯伊能醫好她。我們相信德魯伊們能讓她清醒過來。我們跟議會之間已經兩清，該回去做自己的事情了。$B$B過了好幾周，一切看來進展順利。布萊恩仍然四處奔波，我們也正常地工作著。有一天，她突然出現在我們的營地裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7758 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7758, 'zhTW', '你聾了嗎?我還能指誰?當然是瑪爾利斯女士。無論如何，她已經回來了，但是她的心情似乎不太好。她需要我們幫個忙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7759 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7759, 'zhTW', '她要我們立即返回雷戈蟲巢!布萊恩拒絕了她。他認為我們在沒有軍隊支援的情況下是無法進入蟲巢的。那樣太危險了。跟我們首次進入蟲巢相比，這些蟲子的數量似乎膨脹了3倍。$B$B娜塔莉亞就是在那時得了失心瘋的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7760 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7760, 'zhTW', '你認為我說的什麼意思?她變得十分瘋狂!那個女孩就在我們面前變瘋了。一般來說我不會動手，但是當我從震驚中清醒過來的時候，我變得非常氣憤。布萊恩，魯特加爾，我，當然還有猴子，一起向她撲去!我們能擋開她真是一個奇蹟。她好像完全被佔據了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7761 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7761, 'zhTW', '誰知道呢?無論如何，那是我最後一次見到她。或許法蘭克爾能告訴你更多資訊。$B$B別轉移話題，我想指揮官給你的工作相當重要吧，但是我們也是來執行重要任務的!鐵爐堡對我們請求軍隊增援的要求置若罔聞。很明顯，以我們的力量難以保護這片土地。一旦你將報告交還給指揮官，就跟你的朋友一同回到這兒來。我們需要你的幫助!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7762 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7762, 'zhTW', '哦，就是這樣了...先找個椅子，$g小夥子:小姑娘;。$B$B我肯定魯特加爾已經告訴你一些事情了，因此我將省略一些細節，讓你直奔主題。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7763 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7763, 'zhTW', '好吧!她從蟲巢回來過，但是布萊恩一點都沒有察覺到!混戰之前，她開始跟什麼人交談起來。奇怪的是，她用了一種我們從未聽過的語言談話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7764 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7764, 'zhTW', '那還用說!布萊恩、魯特加爾、猴子和我都對此感到陌生，我們懂38種語言，還略懂一點泰坦語─連華納神族和阿薩神族都不例外。$B$B總之，無論她嘴裡嘰裡咕嚕在說些什麼，肯定都不是在跟「現場」的任何人對話。她點點頭，就開始攻擊我們!馬上攻擊我們!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7765 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7765, 'zhTW', '聽著$g小子:小姑娘;，我要讓你知道無論是什麼攻擊我們，她都不是隨便一個不知名的女祭司!她的眼裡發出邪惡的光芒，而且她真的口吐白沫!她靠過來，發出了某種瘋狂的尖嘯使得我們全都往不同的方向逃走，然後開始一個接一個地鞭笞我們的心靈。我聽到黑暗的文字在我的腦海中迴盪，眼前忽明忽暗。我瘋了!如果沒有那隻該死的猴子，我們可能已經玩完了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7766 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7766, 'zhTW', '你想問什麼?牠就是一隻猴子，你這個瘋狂的笨蛋。所以，反正就是，當那隻猴子看到老布萊恩忽然臉朝下地撲倒在地時，就變得狂暴了。那個夜精靈做不到的事情就是阻止格里布持續重擊她的頭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7767 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7767, 'zhTW', '我會告訴你的。她直直地往巢穴跑去。你知道有多瘋狂嗎? 竟然沒有一隻該死的蟲擋住她的路或是試圖阻止她。她用跑的穿過它們就像她跟它們當了好幾百年的朋友一般。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7768 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7768, 'zhTW', '沒錯。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7770 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7770, 'zhTW', '水晶上佈滿了神秘的雕紋和符文。你無法理解。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7771 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7771, 'zhTW', '從石頭中傳來很輕的聲音……$B$B你好，渺小的凡人。你為聖殿騎士帶來了什麼訊息?', '從石頭中傳來很輕的聲音……$B$B你好，渺小的凡人。你為聖殿騎士帶來了什麼訊息?', '從石頭中傳來很輕的聲音……$b$b你好，渺小的凡人。你為聖殿騎士帶來了什麼訊息?$b$b從石頭中傳來很輕的聲音……$b$b你好，渺小的凡人。你為聖殿騎士帶來了什麼訊息?', '從石頭中傳來很輕的聲音……$B$B你好，渺小的凡人。你為聖殿騎士帶來了什麼訊息?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7772 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7772, 'zhTW', '從石頭中傳來清晰的聲音……$B$B你的身份勳章在哪裡?沒有身份勳章的話，你就無法和公爵對話……', '從石頭中傳來清晰的聲音……$B$B你的身份勳章在哪裡?沒有身份勳章的話，你就無法和公爵對話……', '從石頭中傳來清晰的聲音……$b$b你的身份勳章在哪裡?沒有身份勳章的話，你就無法和公爵對話……$b$b你的身份勳章在哪裡?沒有身份勳章的話，你就無法和公爵對話……', '你的身份勳章在哪裡?沒有身份勳章的話，你就無法和公爵對話……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7773 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7773, 'zhTW', '從石頭中傳來清晰的聲音……$B$B你帶著你的頭銜來找我們，我們將會聆聽，但是不要試圖考驗我們的耐心，$c。議會沒有時間來和你這樣的凡人閒聊。', '從石頭中傳來清晰的聲音……$B$B你帶著你的頭銜來找我們，我們將會聆聽，但是不要試圖考驗我們的耐心，$c。議會沒有時間來和你這樣的凡人閒聊。', '你帶著你的頭銜來找我們，我們將會聆聽，但是不要試圖考驗我們的耐心，$c。議會沒有時間來和你這樣的凡人閒聊。', '你帶著你的頭銜來找我們，我們將會聆聽，但是不要試圖考驗我們的耐心，$c。議會沒有時間來和你這樣的凡人閒聊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7774 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7774, 'zhTW', 'A thunderous voice bellows from the stone...$B$B歡迎您, commander. What news of Silithus do you bring the Lords of the Council?', '從石頭中傳來雷鳴般的聲音...$b$b你好，指揮官。你從希利蘇斯給議會領主帶來了什麼訊息?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
