INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7776, 'zhTW', '從石頭中傳來雷霆般的聲音……$B$B這是什麼?我感覺到一個小小的教徒在竄來竄去!快點走開，苦力，否則你將面對議會領主的憤怒!', '從石頭中傳來雷霆般的聲音……$B$B這是什麼?我感覺到一個小小的教徒在竄來竄去!快點走開，苦力，否則你將面對議會領主的憤怒!', '從石頭中傳來雷霆般的聲音……\n\n這是什麼?我感覺到一個小小的信徒在竄來竄去!快點走開，苦力，否則你將面對議會領主的憤怒!', '從石頭中傳來雷霆般的聲音……$B$B這是什麼?我感覺到一個小小的信徒在竄來竄去!快點走開，苦力，否則你將面對議會領主的憤怒!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
