INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7780, 'zhTW', '你好，$C。看來你最近在進行一項秘密的收集工作?你還是老樣子，但是這是個繁忙的城市。$B$B如果你參加了那場會議，你就該得到一段驗證碼。把驗證碼告訴我，我就會給你一份特殊的獎勵作為回報。', '你好，$C。看來你最近在進行一項秘密的收集工作?你還是老樣子，但是這是個繁忙的城市。$B$B如果你參加了那場會議，你就該得到一段驗證碼。把驗證碼告訴我，我就會給你一份特殊的獎勵作為回報。', '你好，$C。看來你最近在進行一項秘密的收集工作。你還是老樣子，但是這是個繁忙的城市。$b$b如果經常去擊殺野外BOSS，你就有機會得到可樂兌獎券。把兌獎券給我，我就會給你一份特殊的獎勵作為回報。', '你好，$C。看來你最近在進行一項秘密的收集工作?你還是老樣子，但是這是個繁忙的城市。$B$B如果你參加了那場會議，你就該得到一段驗證碼。把驗證碼告訴我，我就會給你一份特殊的獎勵作為回報。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7781 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7781, 'zhTW', '$N!我希望你已經準備好要工作了，因為在逐日者之島有很多事等著你做。$B$B自從阿薩斯和天譴軍團摧毀了太陽之井，我們就在海邊過著漂浮不定的生活。我們存活在被遺忘的邊緣。一切將會改變，$c，你將會學習很多的東西，並同時協助我們重建。$B$B外域正等著我們!', '$N!我希望你已經準備好要工作了，因為在逐日者之島有很多事等著你做。$B$B自從阿薩斯和天譴軍團摧毀了太陽之井，我們就在海邊過著漂浮不定的生活。我們存活在被遺忘的邊緣。一切將會改變，$c，你將會學習很多的東西，並同時協助我們重建。$B$B外域正等著我們!', '$N!我希望你已經準備好要工作了，因為在逐日者之島有很多事等著你做。$b$b自從阿爾薩斯和天災軍團摧毀了太陽之井，我們就在海邊過著漂浮不定的生活。我們存活在被遺忘的邊緣。一切將會改變，$c，你將會學習很多的東西，並同時協助我們重建。$b$b外域正等著我們!', '$N!我希望你已經準備好要工作了，因為在逐日者之島有很多事等著你做。$B$B自從阿薩斯和天譴軍團摧毀了太陽之井，我們就在海邊過著漂浮不定的生活。我們存活在被遺忘的邊緣。一切將會改變，$c，你將會學習很多的東西，並同時協助我們重建。$B$B外域正等著我們!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7782 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7782, 'zhTW', '塞納里奧議會是睿智的，他們發現了很多有關大地的秘密。願意聆聽這些德魯伊的教誨的工匠總是會得到許多寶貴的知識。', '塞納里奧議會是睿智的，他們發現了很多有關大地的秘密。願意聆聽這些德魯伊的教誨的工匠總是會得到許多寶貴的知識。', '塞納-馬恩省里奧議會是睿智的，他們發現了很多有關大地的秘密。願意聆聽這些德魯伊的教誨的工匠總是會得到許多寶貴的知識。', '塞納里奧議會是睿智的，他們發現了很多有關大地的秘密。願意聆聽這些德魯伊的教誨的工匠總是會得到許多寶貴的知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7783 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7783, 'zhTW', '這個鬼魅般的身影不信任地看著你，並且保持著沉默。', '這個鬼魅般的身影不信任地看著你，並且保持著沉默。', '這個鬼魂一樣的身影不信任地看著你，並且保持著沉默。', '這個鬼魅般的身影不信任地看著你，並且保持著沉默。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7784 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7784, 'zhTW', '曾經……日尖塔處於太陽之井旁的優渥位置。如今我們的生活方式從天堂掉落了地獄，$N，但我們仍在努力向前邁進。我們是倖存者，這是我們的生存方式。$B$B如果你想從這場動亂中活下來……靠自己的力量活下去，那你一定要學會如何生存。所有的血精靈都是如此。你一定要在心中對於魔法永無止盡的渴望主宰你之前先主宰它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7785 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7785, 'zhTW', '你對血精靈長久以來的貢獻是我們種族生存最重要的助力!我們一定要同心協力突破目前的困境。$B$B如果你已經做好了準備，那就讓我們開始吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7786 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7786, 'zhTW', '知識就是力量 - 真正的力量，我年輕的朋友。獲得越多知識就會讓你越有智慧，並且從那些有智慧的人身上學習吧。$B$B在太陽之井被夷平前，我們還自以為我們的文明發展已經攀上了最高峰。是天譴軍團迫使我們屈服……並且，看清這個事實。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7787 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7787, 'zhTW', '你在我研究最關鍵的時刻打擾了我!別擔心，歡迎你加入我一起安靜的沉思……重點是「安靜」，如果你不介意的話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7788 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7788, 'zhTW', '如果你正前往那座城市的話，那麼我有一件重要的事情要你去做!', '如果你正前往那座城市的話，那麼我有一件重要的事情要你去做!', '如果你正前往那座城市的話，那麼我有一件重要的事情要你去做!', '如果你正前往那座城市的話，那麼我有一件重要的事情要你去做!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
