INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7789, 'zhTW', '歡迎!上前來，不要害羞。這是我最自豪的發明……衝擊者5000型超級大炮!她難道不漂亮嗎?她實在就是很漂亮啊!看起來對於炮管的中段來說，你的體型稍微大了一點，但是我想這不是什麼大問題。飛行充滿了樂趣，你想要學學嗎?', '歡迎!上前來，不要害羞。這是我最自豪的發明……衝擊者5000型超級大炮!她難道不漂亮嗎?她實在就是很漂亮啊!看起來對於炮管的中段來說，你的體型稍微大了一點，但是我想這不是什麼大問題。飛行充滿了樂趣，你想要學學嗎?', '歡迎!上前來，不要害羞。這是我最自豪的發明……衝擊者5000型超級大炮!她難道不漂亮嗎?她實在就是很漂亮啊!看起來對於炮管的中段來說，你的體型稍微大了一點，但是我想這不是什麼大問題。飛行充滿了樂趣，你想要學學嗎?', '歡迎!上前來，不要害羞。這是我最自豪的發明……衝擊者5000型超級大炮!她難道不漂亮嗎?她實在就是很漂亮啊!看起來對於炮管的中段來說，你的體型稍微大了一點，但是我想這不是什麼大問題。飛行充滿了樂趣，你想要學學嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
