INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7792, 'zhTW', '您好，$c，歡迎來到暗月馬戲團。在馬戲團這裡有太多可以做的事情了，所以第一次來的客人可能感到有些不知所措。這就是我在這裡幫忙的原因。您有什麼問題嗎?', '您好，$c，歡迎來到暗月馬戲團。在馬戲團這裡有太多可以做的事情了，所以第一次來的客人可能感到有些不知所措。這就是我在這裡幫忙的原因。您有什麼問題嗎?', '您好，$c，歡迎來到暗月馬戲團。在馬戲團這裡有太多可以做的事情了，所以第一次來的客人可能感到有些不知所措。這就是我在這裡幫忙的原因。您有什麼問題嗎?', '您好，$c，歡迎來到暗月馬戲團。在馬戲團這裡有太多可以做的事情了，所以第一次來的客人可能感到有些不知所措。這就是我在這裡幫忙的原因。您有什麼問題嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
