INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7794, 'zhTW', '很高興您問到這個問題。暗月馬戲團獎品券是我們鼓勵大家幫助馬戲團所推出的，您可以使用這些獎品券來兌換特別的獎品!$B$B首先您可以找克洛諾斯、克莉·希克斯和亞布·尼比蓋爾談談來看看您有什麼可以幫他們的。他們總是需要幫助。$B$B當您有足夠的獎品券時，和吉瓦斯·格里加特談談，他有很多獎品可供選擇。', '很高興您問到這個問題。暗月馬戲團獎品券是我們鼓勵大家幫助馬戲團所推出的，您可以使用這些獎品券來兌換特別的獎品!$B$B首先您可以找克洛諾斯、克莉·希克斯和亞布·尼比蓋爾談談來看看您有什麼可以幫他們的。他們總是需要幫助。$B$B當您有足夠的獎品券時，和吉瓦斯·格里加特談談，他有很多獎品可供選擇。', '很高興您問到這個問題。暗月馬戲團獎券是我們鼓勵大家幫助馬戲團所推出的，您可以使用這些獎券來兌換特別的獎品!$b$b首先您可以找克洛諾斯、克莉·希克斯和亞布·尼比蓋爾談談來看看您有什麼可以幫他們的。他們總是需要幫助。$b$b當您有足夠的獎券時，和吉瓦斯·格里加特談談，他有很多獎品可供選擇。', '很高興您問到這個問題。暗月馬戲團獎品券是我們鼓勵大家幫助馬戲團所推出的，您可以使用這些獎品券來兌換特別的獎品!$B$B首先您可以找克洛諾斯、克莉·希克斯和亞布·尼比蓋爾談談來看看您有什麼可以幫他們的。他們總是需要幫助。$B$B當您有足夠的獎品券時，和吉瓦斯·格里加特談談，他有很多獎品可供選擇。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
