INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7795, 'zhTW', '沒有人知道誰製作了暗月卡片，或者他們真正的意圖是什麼，但是我可以告訴你，在艾澤拉斯各地都可以找到它們，尤其是在那些試圖揭開它秘密的邪惡怪物手中。', '沒有人知道誰製作了暗月卡片，或者他們真正的意圖是什麼，但是我可以告訴你，在艾澤拉斯各地都可以找到它們，尤其是在那些試圖揭開它秘密的邪惡怪物手中。', '沒有人知道誰製作了暗月卡片，或者他們真正的意圖是什麼，但是我可以告訴你，在艾澤拉斯各地都可以找到它們，那些試圖揭開它秘密的邪惡怪物手中都可能有卡片。', '沒有人知道誰製作了暗月卡片，或者他們真正的意圖是什麼，但是我可以告訴你，在艾澤拉斯各地都可以找到它們，尤其是在那些試圖揭開它秘密的邪惡怪物手中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
