INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7799, 'zhTW', '我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道...他是個食人妖。不過他是一個非常特別的食人妖，擁有占卜你未來的能力!$B$B而且我們一直持續地擴充套件馬戲團在各方面的新吸引力!', '我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道...他是個食人妖。不過他是一個非常特別的食人妖，擁有占卜你未來的能力!$B$B而且我們一直持續地擴充套件馬戲團在各方面的新吸引力!', '我強烈建議你去賽吉那裡算個命。我知道，我知道……他是一個豺狼人。但是他是一個擁有特別力量的豺狼人，他可以預知你的命運!$b$b而且我們不斷在增加新事物擴充套件我們的馬戲團!', '我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道...他是個食人妖。不過他是一個非常特別的食人妖，擁有占卜你未來的能力!$B$B而且我們一直持續地擴充套件馬戲團在各方面的新吸引力!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
