INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7802, 'zhTW', '我被殺死過無數次。我總是發現我會在這裡醒來。有些人說我遭受了詛咒，還有些人...', '我被殺死過無數次。我總是發現我會在這裡醒來。有些人說我遭受了詛咒，還有些人...', '我被殺死過無數次。我總是發現我會在這裡醒來。有些人說我遭受了詛咒，還有些人……', '我被殺死過無數次。我總是發現我會在這裡醒來。有些人說我遭受了詛咒，還有些人……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
