INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7804, 'zhTW', '上古的力量被數千年來從未活動過的蟲子所震撼。世界在哭泣，$r。也許一次新的災變正在開始。其中孕育的是痛苦...$B$B那些可惡的傢伙開始滲透入我們的土地。夢魘來自於睡眠。夢魘開始在我們醒著的時候糾纏我們...', '上古的力量被數千年來從未活動過的蟲子所震撼。世界在哭泣，$r。也許一次新的災變正在開始。其中孕育的是痛苦...$B$B那些可惡的傢伙開始滲透入我們的土地。夢魘來自於睡眠。夢魘開始在我們醒著的時候糾纏我們...', '上古的力量被數千年來從未活動過的蟲子所震撼。世界在哭泣，$r。也許一次新的災變正在開始。其中孕育的是痛苦……$B$B那些可惡的傢伙開始滲透入我們的土地。噩夢來自於睡眠。噩夢開始在我們醒著的時候糾纏我們……', '上古的力量被數千年來從未活動過的蟲子所震撼。世界在哭泣，$r。也許一次新的災變正在開始。其中孕育的是痛苦……$B$B那些可惡的傢伙開始滲透入我們的土地。夢魘來自於睡眠。夢魘開始在我們醒著的時候糾纏我們……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
