INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7808, 'zhTW', '我很傷心!萬鬼節快結束了，但是我生病了。我將會因為無法外出而錯過「不給糖就搗蛋」的活動的!', '我很傷心!萬鬼節快結束了，但是我生病了。我將會因為無法外出而錯過「不給糖就搗蛋」的活動的!', '我太傷心了！萬聖節到了，我卻生病了。我不能出去，不能參加要糖果的惡作劇遊戲！', '我很傷心!萬鬼節快結束了，但是我生病了。我將會因為無法外出而錯過“不給糖就搗蛋”的活動的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7809 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7809, 'zhTW', '你是最棒的，$N - 謝謝你幫我去參加「不給糖就搗蛋」的活動!', '你是最棒的，$N - 謝謝你幫我去參加「不給糖就搗蛋」的活動!', '你真好，$N——謝謝你陪我玩要糖果的惡作劇遊戲！', '你是最棒的，$N - 謝謝你幫我去參加“不給糖就搗蛋”的活動!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
