INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7812, 'zhTW', '怎麼玩?!$B$B世界各地的旅店老闆都會將糖果分發給孩子們，許多城鎮都將裝飾一新，歡度節日!此外，幽暗城外還會在夜間舉辦稻草人慶典。$B$B對了，我聽說奧格瑪孤兒院裡有個生病的小女孩，她想找人陪她玩要糖果的惡作劇遊戲……或許你能幫幫她?', '怎麼玩?!$B$B世界各地的旅店老闆都會將糖果分發給孩子們，許多城鎮都將裝飾一新，歡度節日!此外，幽暗城外還會在夜間舉辦稻草人慶典。$B$B對了，我聽說奧格瑪孤兒院裡有個生病的小女孩，她想找人陪她玩要糖果的惡作劇遊戲……或許你能幫幫她?', '怎麼玩？！\n世界各地的旅店老闆都會將糖果分發給孩子們，許多城鎮都將裝飾一新，歡度節日！此外，幽暗城外還會在夜間舉辦稻草人慶典。\n對了，我聽說奧格瑞瑪孤兒院裡有個生病的小女孩，她想找人陪她玩要糖果的惡作劇遊戲……或許你能幫幫她？', '怎麼玩?!$B$B世界各地的旅店老闆都會將糖果分發給孩子們，許多城鎮都將裝飾一新，歡度節日!此外，幽暗城外還會在夜間舉辦稻草人慶典。$B$B對了，我聽說奧格瑪孤兒院裡有個生病的小女孩，她想找人陪她玩要糖果的惡作劇遊戲……或許你能幫幫她?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
