INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7818, 'zhTW', '與部落之間的戰爭已經到了白熱化的階段，$N。聯盟需要大量的物資，我們應竭盡所能，提供幫助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7819 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7819, 'zhTW', '戰爭即將來臨，$N。每個部落成員都要響應號召，並肩擊潰懦弱的聯盟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7820 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7820, 'zhTW', '你是個皮革商吧?我對獸皮的味道再熟悉不過了。$B$B我的父親過去常常跟我談起數世紀前一位居住在南風村的著名工匠。很遺憾，那兒已是一片廢墟了。', '你是個皮革商吧?我對獸皮的味道再熟悉不過了。$B$B我的父親過去常常跟我談起數世紀前一位居住在南風村的著名工匠。很遺憾，那兒已是一片廢墟了。', '你是個皮革商吧?我對獸皮的味道再熟悉不過了。$b$b我的父親過去常常跟我談起數世紀前一位居住在南風村的著名工匠。很遺憾，那兒已是一片廢墟了。', '你是個皮革商吧?我對獸皮的味道再熟悉不過了。$B$B我的父親過去常常跟我談起數世紀前一位居住在南風村的著名工匠。很遺憾，那兒已是一片廢墟了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7821 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7821, 'zhTW', '嗯，$N - 很高興再見到你。我相信你的事情進行的很順利。', '嗯，$N - 很高興再見到你。我相信你的事情進行的很順利。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7823 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7823, 'zhTW', '我們已經有所有需要的銅錠了。謝謝你的幫忙，$c。你應該想在這裡協助我們收集另一種材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7824 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7824, 'zhTW', '$C，我需要更多的銅錠。安其拉大門正在醞釀一場大戰，我們需要補給！聯盟已經收集了 $1997w 銅錠，我們總共需要 $1998w 銅錠。如果我收集不齊銅錠，我的腦袋就保不住了！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7825 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7825, 'zhTW', '你看到大量的岩漿隧道和參雜著火山水晶的通道，你認為這這裡就是熔火之心了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7827 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7827, 'zhTW', '很高興見到你, $r. 今天真是充滿朝氣.不是嗎?', '很高興見到你, $r. 今天真是充滿朝氣.不是嗎?', '很高興見到你, $r. 今天真是充滿朝氣.不是嗎?', '你好，$r！又是美好的一天，活著真好，不是嗎？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7828 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7828, 'zhTW', '並不是我們牛頭人看不起你們的種族，$r，唉，我實在沒辦法向你提供服務。', '並不是我們牛頭人看不起你們的種族，$r，唉，我實在沒辦法向你提供服務。', NULL, '並不是我們牛頭人看不起你們的種族，$r，唉，我實在沒辦法向你提供服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7829 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7829, 'zhTW', '聽著，親愛的。為了生存，我們註定要與安其拉的蟲子一戰，我們需要為此而準備。我在這裡收集鐵錠。目前聯盟還僅僅收集了 $2002w 鐵錠，而我們需要 $2003w 鐵錠來備戰！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7830 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7830, 'zhTW', '在大家的努力下，我們已經集齊了必需的鐵錠。問問其它人，看他們是否需要你幫忙收集作戰物資。至於我，我得瞧瞧我能不能早點離開，去玩幾局牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7831 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7831, 'zhTW', NULL, '$C，請聽我說，聯盟與部落正在為安其拉與異型蟲族及它們的主人戰鬥而做準備，如果你能給予任何援助，我們將不勝感激。我們總共需要收集 $2012w 瑟銀錠，目前我們已經有 $2011w 了。', NULL, '$C，請聽我說，聯盟與部落正在為安其拉與異型蟲族及它們的主人戰鬥而做準備，如果你能給予任何援助，我們將不勝感激。我們總共需要收集 $2012w 瑟銀錠，目前我們已經有 $2011w 了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7832 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7832, 'zhTW', NULL, '謝謝你，$C。我們已經集齊了所需的瑟銀錠了，但是你可以問問這兒收集其它作戰物資的負責人。', '謝謝你，$C。我們已經集齊了所需的瑟銀錠了，但是你可以問問這兒收集其他作戰物資的負責人。', '謝謝你來關照我，$c，我們現在已經收集齊了所需的瑟銀錠，不過你可以去問問別人，可能還有些其他的物資需要收集的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7833 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7833, 'zhTW', '真的，就連荊棘藻也會成為戰爭中的重要資源！它有許多用途，比如用來製作可以在希利蘇斯的炎炎烈日下品嚐的冰淇淋，清除一些非常難以清除的植物，水下呼吸，硬化皮膚，讓你的行動變得更迅速，恢復魔法能量，太多了，我簡直沒法一一歷數！我有沒有說冰淇淋？總之，我手頭上總共有$2047w份的存貨，而需求總量是$2048w！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7834 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7834, 'zhTW', '我不是置疑你收集荊棘藻的能力，但是我們似乎已經擁有足夠的荊棘藻了。至少我是這麼聽說的。這兒的其它人需要你幫忙收集戰爭物資。收集其它的作戰物資可沒有收集荊棘藻那麼有趣，我能理解你這種想法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7835 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7835, 'zhTW', '紫蓮花的用處很多，年輕的$C。聯盟派我收集這種花，為安其拉之戰做好準備。我答應幫助他們收集$2055w份紫蓮花，當前我們已經收集到了$2053w份。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7837 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7837, 'zhTW', NULL, '我們正在為戰爭作準備，$c。我們一定要徹底消滅安其拉的威脅，為了戰備的需要，我在這裡收集阿爾薩斯之淚這種材料。我不清楚這些草藥是用來做什麼的。如果你問我的話，我可不想跟那個瘋子扯上關係，即使這不過是一種以他命名的花而已。不過，我不僅是個聯盟的公民，還是一名軍人，因此我會遵守上級的命令。現在我們已經收集到$2057w份阿爾薩斯之淚了，總的需求量是$2058w份。', '我們正在為戰爭作準備，$c。我們一定要徹底消滅安其拉的威脅，為了戰備的需要，我在這裡收集阿爾薩斯之淚這種材料。我不清楚這些草藥是用來做什麼的。如果你問我的話，我可不想跟那個瘋子扯上關係，即使這不過是一種以他命名的花而已。不過，我不僅是個聯盟的公民，還是一名軍人，因此我會遵守上級的命令。現在我們已經收集到$2057w份阿爾薩斯之淚了，總的需求量是$2058w份。', '我們正在備戰，$c。我負責收集阿爾薩斯之淚，我們總共需要 $2058w ，目前已經有 $2057w 了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7838 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7838, 'zhTW', NULL, '我想我們的阿爾薩斯之淚已經夠多了，你可以看看還有些什麼別的可以提供的。', NULL, '我想我們的阿爾薩斯之淚已經夠多了，你可以看看還有些什麼別的可以提供的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7839 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7839, 'zhTW', '我得到報告說，你對深淵議會的戰果卓著，$n。你乾得很好!$B$B繼續保持鬥志，我們會獎勵你的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7840 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7840, 'zhTW', '安其拉之戰已經展開，$c，聯盟要求我的家人為戰爭收集許多輕皮。總共需要$2061w塊，我們目前有$2060w塊。你看起來很適合幫忙。', '安其拉之戰已經展開，$c，聯盟要求我的家人為戰爭收集許多輕皮。總共需要$2061w塊，我們目前有$2060w塊。你看起來很適合幫忙。', '安其拉之戰已經展開，$c，聯盟要求我的家人為戰爭收集許多輕皮。總共需要$2061w塊，我們目前有$2060w塊。你看起來很適合幫忙。', '安其拉之戰已經展開，$c，聯盟要求我的家人為戰爭收集許多輕皮。總共需要$2061w塊，我們目前有$2060w塊。你看起來很適合幫忙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7842 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7842, 'zhTW', NULL, '謝謝你的關心，$C。但是我們已經集齊輕皮了。或許這兒負責收集物資的其它人需要你的幫助。', '謝謝你的關心，$C。但是我們已經集齊輕皮了。或許這兒負責收集物資的其他人需要你的幫助。', '你的聲音真好聽，$c。但是我們已經收集齊了所需的輕皮了，也許有其他收集官需要你的，你願意幫助他們嗎？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7843 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7843, 'zhTW', '$G先生:女士;，是的$g先生:女士;!士兵波特已準備好要幫你收集中皮了。安其拉之戰就要展開，我們需要做好充分的準備。$B$B如你所見我們已收集了$2063w塊中皮，而我們總共需要收集$2064w塊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7844 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7844, 'zhTW', '啊，呃，是的，$G先生:女士;。我們已經集齊聯盟在戰爭中所需的所有中皮了。我聽說這兒的其它人需要你的幫助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7845 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7845, 'zhTW', '你好，$c!隨著安其拉之戰的逼近，我們的準備工作仍在進行著。我的工作是收集重皮。今天是個收集重皮的好日子，對吧?我收集到一堆厚皮了，看來現在已經有$2069w塊。而我們的理想數字是$2071w塊。要不要幫忙啊?', '你好，$c!隨著安其拉之戰的逼近，我們的準備工作仍在進行著。我的工作是收集重皮。今天是個收集重皮的好日子，對吧?我收集到一堆厚皮了，看來現在已經有$2069w塊。而我們的理想數字是$2071w塊。要不要幫忙啊?', '你好，$c!隨著安其拉之戰的逼近，我們的準備工作仍在進行著。我的工作是收集重皮。今天是個收集重皮的好日子，對吧?我收集到一堆厚皮了，看來現在已經有$2069w塊。而我們的理想數字是$2071w塊。要不要幫忙啊?', '你好，$c!隨著安其拉之戰的逼近，我們的準備工作仍在進行著。我的工作是收集重皮。今天是個收集重皮的好日子，對吧?我收集到一堆厚皮了，看來現在已經有$2069w塊。而我們的理想數字是$2071w塊。要不要幫忙啊?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7846 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7846, 'zhTW', NULL, '哇！似乎我們已經集齊厚皮了。速度很快呢。你可以問問這兒的其它人，看他們是否需要幫助。', '哇！似乎我們已經集齊厚皮了。速度很快呢。你可以問問這兒的其他人，看他們是否需要幫助。', '哇哦！看來厚皮已經收集夠了，去幫助收集其他的物資吧！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7847 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7847, 'zhTW', NULL, '你好，$C。我正在為安其拉之戰收集亞麻繃帶。這場戰爭對我們來說是一次嚴酷的考驗和鍛鍊，你捐獻的繃帶將在戰爭中挽救士兵們的生命。我需要收集$2077w根亞麻繃帶，到當前為止已經有$2076w根了。你願意幫助我們嗎？', '你好，$C。我正在為安其拉之戰收集亞麻繃帶。這場戰爭對我們來說是一次嚴酷的考驗和鍛鍊，你捐獻的繃帶將在戰爭中挽救士兵們的生命。我需要收集$2077w根亞麻繃帶，到目前為止已經有$2076w根了。你願意幫助我們嗎？', '你好，$c。我為準備安其拉之戰負責收集亞麻繃帶，到時候這些繃帶能在戰場上派上大用場呢，我們總共需要 $2077w ，現在還只有 $2076w ，你願意幫助我們嗎？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7848 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7848, 'zhTW', NULL, '謝謝你的關照，$C，你看，我們的亞麻繃帶已經足夠多了。', NULL, '謝謝你的關照，$C，你看，我們的亞麻繃帶已經足夠多了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7851 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7851, 'zhTW', '嗨，$c，你今天好嗎?希望一切都好。你應該知道這裡發生什麼事了。安其拉之戰正在計畫、準備中。我們和部落正加強準備。$B$B最後，聯盟要求我在這裡監督收集絲質繃帶，而目前我們只收集到$2082w個，但總需求是$2083w個。你可以考慮幫個忙嗎?', '嗨，$c，你今天好嗎?希望一切都好。你應該知道這裡發生什麼事了。安其拉之戰正在計畫、準備中。我們和部落正加強準備。$B$B最後，聯盟要求我在這裡監督收集絲質繃帶，而目前我們只收集到$2082w個，但總需求是$2083w個。你可以考慮幫個忙嗎?', '嗨，$c，你今天好嗎?希望一切都好。你應該知道這裡發生什麼事了。安其拉之戰正在計畫、準備中。我們和部落正加強準備。\n\n最後，聯盟要求我在這裡監督收集絲質繃帶，而目前我們只收集到$2082w個，但總需求是$2083w個。你可以考慮幫個忙嗎?', '嗨，$c，你今天好嗎?希望一切都好。你應該知道這裡發生什麼事了。安其拉之戰正在計劃、準備中。我們和部落正加強準備。$B$B最後，聯盟要求我在這裡監督收集絲質繃帶，而目前我們只收集到$2082w個，但總需求是$2083w個。你可以考慮幫個忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7852 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7852, 'zhTW', NULL, '謝謝你的關心，但是我們已經集齊絲質繃帶了。你可以四下問問，看看他們是否需要幫助。', '謝謝你的關心，但是我們已經集齊絲質繃帶了。你可以四下問問，看看他們是否需要幫助。', '你可真是個好心人啊，我們已經收集齊絲質繃帶了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7853 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7853, 'zhTW', '$C，在即將來臨的戰爭中，即使最勇敢計程車兵也需要治療。當無法運用魔法治療時，士兵們必須依賴我們收集的作戰物資。到目前為止，我已經收集了$2088w個符文布繃帶，總需求量是$2090w個。$B$B讓我們談談你能為我們做些什麼吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7854 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7854, 'zhTW', '$C，在許多人的幫助下，我們已經設法集齊了聯盟所需的戰爭物資符文布繃帶。如果我是你的話，我會問問這兒的其它人，看他們是否需要幫助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7855 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7855, 'zhTW', '哎呀$N，我現在太忙沒辦法說話。就如我先前說的，我需要時間思考目前的狀況。$B$B祝你一路順風，有個愉快的一天。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7856 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7856, 'zhTW', '聞聞，聞聞，你能聞到嗎？這兒有好吃的東西，$c，彩鰭魚永遠是那麼美味，不論是對飢腸咕嚕的旅人還是對精挑細選的美食家，它們可是為我們即將在安其拉奮勇作戰的軍隊準備的，我們需要 $2093w 這種魚，現在已經有 $2092w 了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7857 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7857, 'zhTW', '很好，看來彩鰭魚已經收集齊了，我們可以把它們醃製起來儲存，到時候安其拉大戰一旦開打，就可以拿出來用了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7859 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7859, 'zhTW', NULL, '嗨，$C。聯盟派遣我來到此地監管烤肉的收集工作。這聽起來很有趣吧？我想你一定想知道我們收集到多少烤迅猛龍肉了。我上次數了數，我們已經有$2098w塊了，總需求量是$2099w塊。', '嗨，$C。聯盟派遣我來到此地監管烤肉的收集工作。這聽起來很有趣吧？我想你一定想知道我們收集到多少烤迅猛龍肉了。我上次數了數，我們已經有$2098w塊了，總需求量是$2099w塊。', '嗨，你好，$c。聯盟讓我幫他們收集烤迅猛龍肉，因為在安其拉即將發生厄運，聽起來挺有意思的。我可以告訴你目前我已經收集了 $2098w 了，最終我需要 $2099w 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7860 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7860, 'zhTW', NULL, '你來晚了，$c。迅猛龍都已經宰殺、烹飪、醃製了。不過看起來旁邊有人還有待幫助的，你可以去看看他們需要點什麼。', NULL, '你來晚了，$c。迅猛龍都已經宰殺、烹飪、醃製了。不過看起來旁邊有人還有待幫助的，你可以去看看他們需要點什麼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7861 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7861, 'zhTW', NULL, '食物對於士兵保持充沛的體力非常重要，我們需要一些斑點黃尾魚，$B$B目前我們已經收集了 $2101w ，只要弄到總共 $2103w 就夠了。', NULL, '食物對於士兵保持充沛的體力非常重要，我們需要一些斑點黃尾魚，$B$B目前我們已經收集了 $2101w ，只要弄到總共 $2103w 就夠了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7866 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7866, 'zhTW', '我們需要大量銅錠，$c。安其拉之戰即將開打，我們需要準備足夠的金屬來製造武器、護甲和其他器物。我聽說光是部落就需要$1998w塊銅錠。目前我們已收集$2018w塊了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7868 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7868, 'zhTW', 'MISSING TEXT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
