INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7870, 'zhTW', '(獸人語)你好，$c。你來幫我收集錫錠的嗎?他們說我需要$2006w塊錫錠他們才能製作安其拉之戰需要的武器和護甲，但我現在只有$2005w塊。你得再幫我收集一些!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7872 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7872, 'zhTW', '歡迎光臨獵鷹之翼廣場旅館，需要我為您準備一頓大餐，或是一間房間呢?', '歡迎光臨獵鷹之翼廣場旅館，需要我為您準備一頓大餐，或是一間房間呢?', '歡迎光臨獵鷹之翼廣場旅館，需要我為您準備一頓大餐，或是一間房間呢?', '歡迎光臨獵鷹之翼廣場旅館，需要我為您準備一頓大餐，或是一間房間呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
