INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7874, 'zhTW', '嗨，$c。鐵爐堡兵團被部署在這裡監視佐拉蟲巢。塞納里奧議會的德魯伊一直以來都在監控異種活動，他們預期在這兒會有重大的事情發生。', '嗨，$c。鐵爐堡兵團被部署在這裡監視佐拉蟲巢。塞納里奧議會的德魯伊一直以來都在監控異種活動，他們預期在這兒會有重大的事情發生。', '嗨，$c。鐵爐堡軍團被部署在這裡監視佐拉蟲巢。塞納里奧議會的德魯伊一直以來都在監控異種活動，他們預期在這兒會有重大的事情發生。', '嗨，$c。鐵爐堡軍團被部署在這裡監視佐拉蟲巢。塞納里奧議會的德魯伊一直以來都在監控異種活動，他們預期在這兒會有重大的事情發生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
