INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7875, 'zhTW', '上尉現在很忙。他正在研讀我們最近從地底異種巢穴找到的地圖。如果你想幫忙就跟著我們，他隨時都會出來。', '上尉現在很忙。他正在研讀我們最近從地底異種巢穴找到的地圖。如果你想幫忙就跟著我們，他隨時都會出來。', '上尉現在很忙。他正在研讀我們最近從地底異種巢穴找到的地圖。如果你想幫忙就跟著我們，他隨時都會出來。', '上尉現在很忙。他正在研讀我們最近從地底異種巢穴找到的地圖。如果你想幫忙就跟著我們，他隨時都會出來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7876 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7876, 'zhTW', '嗨，你是來這裡幫我收集秘銀的吧。希利蘇斯沙漠上的安其拉有大麻煩了。我們和聯盟都沒時間對付那些異種蟲類了，這就是你看到大家都在這裡的原因。$B$B部落要求我們為戰爭收集$2009w塊秘銀錠，但我只有$2008w塊。你能幫我的忙，是嗎?', '嗨，你是來這裡幫我收集秘銀的吧。希利蘇斯沙漠上的安其拉有大麻煩了。我們和聯盟都沒時間對付那些異種蟲類了，這就是你看到大家都在這裡的原因。$B$B部落要求我們為戰爭收集$2009w塊秘銀錠，但我只有$2008w塊。你能幫我的忙，是嗎?', '嗨，你是來這裡幫我收集秘銀的吧。希利蘇斯沙漠上的安其拉有大麻煩了。我們和聯盟都沒時間對付那些異種蟲類了，這就是你看到大家都在這裡的原因。$b$b部落要求我們為戰爭收集$2009w塊秘銀錠，但我只有$2008w塊。你能幫我的忙，是嗎?', '嗨，你是來這裡幫我收集秘銀的吧。希利蘇斯沙漠上的安其拉有大麻煩了。我們和聯盟都沒時間對付那些異種蟲類了，這就是你看到大家都在這裡的原因。$B$B部落要求我們為戰爭收集$2009w塊秘銀錠，但我只有$2008w塊。你能幫我的忙，是嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
