INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7882, 'zhTW', '魔法的奧秘不光是那些神秘的施法動作而已……但是跟我對話的你也明白這點，對嗎?$B$B你來找我學習而你將得償所望……只要你專心學習並且聽從我的指示。惡魔的秘密不會平白無故提供給傻瓜，而我也不會。', '魔法的奧秘不光是那些神秘的施法動作而已……但是跟我對話的你也明白這點，對嗎?$b$b你來找我學習而你將得償所望……只要你專心學習並且聽從我的指示。惡魔的秘密不會平白無故提供給傻瓜，而我也不會。', '魔法的奧秘不光是那些神秘的施法動作而已……但是跟我對話的你也明白這點，對嗎?$b$b你來找我學習而你將得償所望……只要你專心學習並且聽從我的指示。惡魔的秘密不會平白無故提供給傻瓜，而我也不會。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7883 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7883, 'zhTW', '< 安多洛夫冷酷地看著你。>$B$B如果它會流血，我們就能殺了它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7885 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7885, 'zhTW', '你是來尋找保護藍龍軍團的權杖裂片?$B$B<艾索雷葛斯的表情似乎是在微笑。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7886 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7886, 'zhTW', '我當然沒有裂片。把那東西帶在身上是極其愚蠢的做法。我生活在這片被詛咒的蠻荒之地上!我走不到五步，就必然有瘋子一般的獸人或是人類想要攻擊我。我隨時都可能命喪黃泉。$B$B總之……我把那東西藏起來了。$B$B繼續吧……問問我把裂片藏在哪兒了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7887 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7887, 'zhTW', '你會愛上這個故事的，$r。你看，就是這個。當瑪裡苟斯讓我保護權杖裂片時，我就知道我會為此頭痛的。$B$B我只想在這片滿是魔法遺物的海岸線上進行研究工作，尋找那次世界分裂時留下的神器。要知道，這裡曾經有過一個輝煌的精靈貴族文明!你不需要告訴我這附近有魔法物品，$R。我能聞到它們的味道!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7888 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7888, 'zhTW', '正如我所說的，我儲存權杖裂片已經有500年了，這東西真麻煩。所有生物都不懷好意地覬覦這塊裂片。我希望能專心研究，不受打擾。因此……我把它扔給了一條魚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7889 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7889, 'zhTW', '不是一般的魚，凡人。我說的是小魚，一種非常特別的小魚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7890 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7890, 'zhTW', '完全正確!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7891 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7891, 'zhTW', '這是個天才的想法，我知道……它永遠都不會被找到的。為了確保這一點，我賦予了這條小魚某些特殊的能力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7892 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7892, 'zhTW', '沒錯。你一直在認真聽我說話!在我創造的生物當中，這條小魚算得上是一個相當可怕的傢伙了。每當我放鬆休息的時候，我就喜歡想像那些不幸的漁民，想像他們碰到這條小魚，然後被完全吞掉的樣子。我敢打賭他們會對此驚訝萬分的!$B$B<艾索雷葛斯大笑著。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7893 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7893, 'zhTW', '天才通常都被誤解，$r。現在，關於權杖裂片……如果你想要裂片而且不希望花下一個一萬年去尋找，你就必需仔細聽著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7894 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7894, 'zhTW', '四個字:奧金浮標。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7895 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7895, 'zhTW', '沒錯……你要做一個奧金浮標並把它放進海里。我的小魚會被奧金浮漂所吸引，當它接近魚漂時─砰!奧金浮漂將釋放出神秘的力量，使它現出原形。不過這麼一來，你有可能招致奈普圖隆的仇恨，機率大概是50%吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7896 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7896, 'zhTW', '如果我不夠了解的話我會以為你在嘲笑我，凡人;但是，那基本是最正確的做法，不過你得把全身裹起來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7897 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7897, 'zhTW', '將這個帳本交給我在塔納利斯的老朋友。他名叫納裡安·柔想，是個精神極度癲狂的偉大工程師!他應該能讀懂這東西。$B$B不用謝我，$N。這是我唯一能做的。$B$B祝你好運!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7899 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7899, 'zhTW', '當心點，凡人。那些強大的生物就是在此地葬生的。', '當心點，凡人。那些強大的生物就是在此地葬生的。', '當心點，凡人。那些強大的生物就是在此地葬生的。', '當心點，凡人。那些強大的生物就是在此地葬生的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7900 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7900, 'zhTW', '一千年前，流沙之戰結束，在安納克羅斯和鹿盔封住安其拉大門時，我們的三位族人犧牲了自己，將其拉蟲人禁錮在這些大牆內。$B$B我們曾立下誓言，一旦甲蟲之牆開啟，就要找到麥琳瑟拉、亞雷戈斯和凱雷斯塔茲。$B$B而它真的發生了...因此我們來了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7901 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7901, 'zhTW', '你不是要拯救世界嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7902 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7902, 'zhTW', '<納裡安將一封未開啟的信貼到他的前額。>$B$B這是什麼...嗯...天鵝絨!$B$B是嗎?$B$B如果你想重新學習交易技能，就翻翻那本書吧...$B$B<納裡安指著「新手的預言入門」。>', NULL, '<納裡安將一封未開啟的信貼到他的前額。>$B$B這是什麼...嗯...天鵝絨!$B$B是嗎?$B$B如果你想重新學習交易技能，就翻翻那本書吧...$B$B<納裡安指著「新手的預言入門」。>', NULL, '<納裡安將一封未開啟的信貼到他的前額。>$B$B這是什麼...嗯...天鵝絨!$B$B是嗎?$B$B如果你想重新學習交易技能，就翻翻那本書吧...$B$B<納裡安指著「新手的預言入門」。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7903 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7903, 'zhTW', '我們所選擇的道路不同。你必須要到別處接受訓練，$C。', '我們所選擇的道路不同。你必須要到別處接受訓練，$C。', '我們所選擇的道路不同。你必須要到別處接受訓練，$C。', '我們所選擇的道路不同。你必須要到別處接受訓練，$C。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7904 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7904, 'zhTW', '你想獲得更多的指示嗎，$n?', '你想獲得更多的指示嗎，$n?', '你想獲得更多操作那魯力量的指示嗎，$n?', '你想獲得更多操作那魯力量的指示嗎，$n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7905 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7905, 'zhTW', '哈哈哈，怎麼樣老兄。你可幫了比雷凱基的大忙。我們需要大量的火焰花。他們說，嘿，比雷凱基，你得馬上收集$2051w份火焰花。到目前為止他只收集到$2050w份，但是你能很快幫我們完成任務，是嗎老兄?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7907 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7907, 'zhTW', '啊，你在這啊。我被告知在這兒等候幫助，所以聽仔細了。情況是這樣:我接到任務要為安其拉之戰收集$2055w份紫蓮花。目前為止我們有$2054w份。$B$B事實上進入戰場和收集花朵要靠你和像你這樣的人。我需要在這兒做好紫蓮花的入庫儲存工作，並研究它的新用途，以便對抗異種蟲和安其拉高牆後的神秘生物。', '啊，你在這啊。我被告知在這兒等候幫助，所以聽仔細了。情況是這樣:我接到任務要為安其拉之戰收集$2055w份紫蓮花。目前為止我們有$2054w份。$B$B事實上進入戰場和收集花朵要靠你和像你這樣的人。我需要在這兒做好紫蓮花的入庫儲存工作，並研究它的新用途，以便對抗異種蟲和安其拉高牆後的神秘生物。', '啊，你在這啊。我被告知在這兒等候幫助，所以聽仔細了。情況是這樣:我接到任務要為安其拉之戰收集$2055w份紫蓮花。目前為止我們有$2054w份。$b$b事實上進入戰場和收集花朵要靠你和像你這樣的人。我需要在這兒做好紫蓮花的入庫儲存工作，並研究它的新用途，以便對抗異種蟲和安其拉高牆後的神秘生物。', '啊，你在這啊。我被告知在這兒等候幫助，所以聽仔細了。情況是這樣:我接到任務要為安其拉之戰收集$2055w份紫蓮花。目前為止我們有$2054w份。$B$B事實上進入戰場和收集花朵要靠你和像你這樣的人。我需要在這兒做好紫蓮花的入庫儲存工作，並研究它的新用途，以便對抗異種蟲和安其拉高牆後的神秘生物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
