INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7911, 'zhTW', '凡人，這兒充斥著一種難以形容的恐怖。克蘇恩和他的追隨者們不僅公然藐視自然的力量，他們的存在更預言著艾澤拉斯的毀滅。$B$B一千年前，麥琳瑟拉、凱雷斯塔茲和亞雷戈斯都犧牲了自己以保全這個世界。我們來這裡不僅僅是要報仇，還因為我們必須阻止克蘇恩!', '凡人，這兒充斥著一種難以形容的恐怖。克蘇恩和他的追隨者們不僅公然藐視自然的力量，他們的存在更預言著艾澤拉斯的毀滅。$B$B一千年前，麥琳瑟拉、凱雷斯塔茲和亞雷戈斯都犧牲了自己以保全這個世界。我們來這裡不僅僅是要報仇，還因為我們必須阻止克蘇恩!', '凡人，這兒充斥著一種難以形容的恐怖。克蘇恩和他的追隨者們不僅公然藐視自然的力量，他們的存在更預言著艾澤拉斯的毀滅。$b$b一千年前，麥琳瑟拉、凱雷斯特拉茲和亞雷戈斯都犧牲了自己以保全這個世界。我們來這裡不僅僅是要報仇，還因為我們必須阻止克蘇恩!', '凡人，這兒充斥著一種難以形容的恐怖。克蘇恩和他的追隨者們不僅公然藐視自然的力量，他們的存在更預言著艾澤拉斯的毀滅。$B$B一千年前，麥琳瑟拉、凱雷斯塔茲和亞雷戈斯都犧牲了自己以保全這個世界。我們來這裡不僅僅是要報仇，還因為我們必須阻止克蘇恩!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
