INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7914, 'zhTW', '你好，$c。我相信你帶來了關於安其拉之戰準備工作的好訊息。我負責為部落收集硬甲皮;這是個我認為只有我能勝任的任務。千萬別低估了銳利小刀的功用。$B$B至於硬甲皮，我們目前已經有$2073w塊，總共需要$2074w塊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
