INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7917, 'zhTW', '能再見到你真好，$N!你替我帶信給親愛的小地精，我真的很感謝你。$B$B你想不想聽首歌?這會讓你在大海中艱難的旅行輕鬆許多!', '能再見到你真好，$N!你替我帶信給親愛的小地精，我真的很感謝你。$B$B你想不想聽首歌?這會讓你在大海中艱難的旅行輕鬆許多!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
