INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7918, 'zhTW', '啊，$c，很高興見到你。我們這裡需要協助收集安其拉的作戰物資。我負責收集大量的急救物品，主要是絨線繃帶。我已經有一些了，現在有$2079w個繃帶，但我的總需要是要收集$2080w個。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
