INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7920, 'zhTW', '你好，$c，很高興你露面了。我長話短說，我們正在收集安其拉之戰的物資。我們不希望有更多的傷亡，可以嗎?我要負責協調收集$2086w個魔紋布繃帶。目前我們已有$2085w個。可以幫忙嗎?', '你好，$c，很高興你露面了。我長話短說，我們正在收集安其拉之戰的物資。我們不希望有更多的傷亡，可以嗎?我要負責協調收集$2086w個魔紋布繃帶。目前我們已有$2085w個。可以幫忙嗎?', '你好，$c，很高興你露面了。我長話短說，我們正在收集安其拉之戰的物資。我們不希望有更多的傷亡，可以嗎?我要負責協調收集$2086w個魔紋布繃帶。目前我們已有$2085w個。可以幫忙嗎?', '你好，$c，很高興你露面了。我長話短說，我們正在收集安其拉之戰的物資。我們不希望有更多的傷亡，可以嗎?我要負責協調收集$2086w個魔紋布繃帶。目前我們已有$2085w個。可以幫忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
