INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7924, 'zhTW', '感謝你對我們的關心，$c。但是我們已經集齊備戰所需的符文布繃帶。我能請你去四處問問別人是否需要你的幫助嗎?願祖先守護著你。', '感謝你對我們的關心，$c。但是我們已經集齊備戰所需的符文布繃帶。我能請你去四處問問別人是否需要你的幫助嗎?願祖先守護著你。', '感謝你對我們的關心，$c。但是我們已經集齊備戰所需的符文布繃帶。我能請你去四處問問別人是否需要你的幫助嗎？願祖先守護著你。', '感謝你對我們的關心，$c。但是我們已經集齊備戰所需的符文布繃帶。我能請你去四處問問別人是否需要你的幫助嗎?願祖先守護著你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
