INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7965, 'zhTW', '歡迎來到寶藏海灣，夥伴。希望你在這兒度過一段快樂平靜的日子 - 重點在後者。如果你口渴的話，我們這兒有很多飲料;如果你擔心受怕的話，我們這兒還有很多保鏢。$B$B現在...我這個熱砂企業卑微的僕人能為你做什麼呢?這麼說好了 - 你又能為我做些什麼呢，嗯?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7967 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7967, 'zhTW', '收集已經完備了，年輕的$c，就在我們談話的此刻所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間，一旦準備就緒，銅鑼被流沙節杖敲響的那一刻，戰爭就正式開始了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7969 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7969, 'zhTW', NULL, '你報名參戰了嗎，$c？此刻所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間。我真希望已經有人拿到了完整的流沙節杖。', NULL, '你報名參戰了嗎，$c？此刻所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間。我真希望已經有人拿到了完整的流沙節杖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7971 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7971, 'zhTW', NULL, '據說一切都已經收集完備，所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間，一旦準備就緒，銅鑼被流沙節杖敲響的那一刻，戰爭就正式開始了。', NULL, '據說一切都已經收集完備，所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間，一旦準備就緒，銅鑼被流沙節杖敲響的那一刻，戰爭就正式開始了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
