INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7981, 'zhTW', '所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間。真想馬上就給那些蟲子們點顏色看看！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7984 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7984, 'zhTW', NULL, '嗨，$C！似乎部落已經集齊所有的戰爭物資了，現在部落和聯盟的物資都將如約運往希利蘇斯。據說貨物在$2113w天之內就能到達，那時就能敲響安其拉大門附近的銅鑼，戰爭也就開始了。', '嗨，$C！似乎部落已經集齊所有的戰爭物資了，現在部落和聯盟的物資都將如約運往希利蘇斯。據說貨物在$2113w天之內就能到達，那時就能敲響安其拉大門附近的銅鑼，戰爭也就開始了。', '你好$c！看來部落完成了他們的收集工作，我們的物資將和部落的物資匯合，一同發往希利蘇斯，可能會花費大概 $2113w 天的時間。然後會有人敲響安其拉大門前的大銅鑼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7988 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7988, 'zhTW', NULL, '$C，所有的戰爭物資將如約運往希利蘇斯。按照當前的情況來看，貨物將在$2113w天內全部抵達。然後，某位英雄將敲響甲蟲牆上的銅鑼，戰爭也就開始了。', '$C，所有的戰爭物資將如約運往希利蘇斯。按照目前的情況來看，貨物將在$2113w天內全部抵達。然後，某位英雄將敲響甲蟲牆上的銅鑼，戰爭也就開始了。', '就在我們談話的此刻所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間。然後會有一個英雄，獨自用流沙節杖敲響安其拉大門前的銅鑼，戰爭就正式開始了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7991 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7991, 'zhTW', NULL, '每個人都為收集作出了貢獻，此刻所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間，一旦準備就緒，銅鑼被流沙節杖敲響的那一刻，戰爭就正式開始了。那時候我們的繃帶就得派上用場。', NULL, '每個人都為收集作出了貢獻，此刻所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間，一旦準備就緒，銅鑼被流沙節杖敲響的那一刻，戰爭就正式開始了。那時候我們的繃帶就得派上用場。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7994 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7994, 'zhTW', '一切都收集完畢了，$c。此刻所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間，一旦準備就緒，銅鑼被流沙節杖敲響的那一刻，戰爭就正式開始了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7997 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7997, 'zhTW', '所有的魚和物資都已經收集完備了，就在我們談話的此刻所有的戰爭物資正在發運到希利蘇斯，可能會花費大概 $2113w 天的時間。然後會有一個英雄，獨自用流沙節杖敲響安其拉大門前的銅鑼，戰爭就正式開始了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7998 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7998, 'zhTW', '所有物資都已經準備發運了，它們會和部落的物資匯合。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8000 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8000, 'zhTW', NULL, '所有的食物和物資都已經準備完畢了，它們會被髮運到希利蘇斯，可能會花費大概 $2113w 天的時間。然後安其拉大門前的銅鑼一旦被敲響，戰爭就正式開始了。', NULL, '所有的食物和物資都已經準備完畢了，它們會被髮運到希利蘇斯，可能會花費大概 $2113w 天的時間。然後安其拉大門前的銅鑼一旦被敲響，戰爭就正式開始了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8003 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8003, 'zhTW', NULL, '很高興見到你, $r.', '很高興見到你, $r.', '你好，$C。所有物資都已經準備完畢了，它們會被髮運到希利蘇斯，可能會花費大概 $2113w 天的時間。然後安其拉大門前的銅鑼一旦被敲響，戰爭就正式開始了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8006 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8006, 'zhTW', '沒想到你們都能勝任這樣的組織工作。聯盟和部落都完成了他們在安其拉之戰的準備工作。所有的戰爭物資將如約運往希利蘇斯，預計將在$2113w天抵達。那時，會有一位英雄使用流沙權杖敲響甲蟲之臺的銅鑼，開啟安其拉之門。那時戰爭就真正打響了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8007 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8007, 'zhTW', '正如我所料，部落早在你和你那所謂聯盟之前已完成所有的籌備工作。你們都給予了支援，但是我們不知道孰輕孰重。$B$B現在，去把你們的物資稱出重量來！$r 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8037 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8037, 'zhTW', '所有的東西都收集好並送往希利蘇斯了，$c。最後一批應該會在$2113w天內到達那裡。我只希望銅鑼被敲響、大門被開啟之後，我們的努力能發揮效用，拯救許多性命。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8049 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8049, 'zhTW', '只剩下 $2113w 天了，一旦有人敲響銅鑼，戰爭即將開始！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8052 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8052, 'zhTW', '假如你聽到聯盟和部落都已經把物資收集完畢了，可別以為自己聽錯了，這是真的！$2113w 天后物資就會被運到希利蘇斯，一旦有人拿著流沙節仗敲響銅鑼，安其拉大戰就打響了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8059 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8059, 'zhTW', '我們以無比的驕傲效忠索爾。我們會盡所能消滅敵人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8060 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8060, 'zhTW', '你來的正是時候，$c。你感覺到身後的地表震動嗎?$B$B有東西從蟲巢逼近了。守住你的崗位吧，$N。我靠你了!', '你來的正是時候，$c。你感覺到身後的地表震動嗎?$B$B有東西從蟲巢逼近了。守住你的崗位吧，$N。我靠你了!', '你來得正是時候，$C。你感覺到腳下的大地在顫抖了嗎？蟲巢裡的敵人正在逼近我們。站到步兵旁邊去，$N。我就指望你了！', '你來的正是時候，$c。你感覺到身後的地表震動嗎?$B$B有東西從蟲巢逼近了。守住你的崗位吧，$N。我靠你了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8061 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8061, 'zhTW', '異種不是奧格瑪子民的對手。很快他們就會全部成為我們腳下破碎的肢體了，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8063 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8063, 'zhTW', '要靠異種這麼近又要不被發現需要一點練習。如果你能避免我建議你就不嘗試。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8064 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8064, 'zhTW', '別誤會我的意思，雖然我不願天天在充滿異種的隧道里，但是如果躲在這裡觀察他們的活動能幫助我們贏得勝利，那麼我願意，多久都沒關係。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8065 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8065, 'zhTW', '我們很快就能擺脫艾澤拉斯上可恨的異種了。他們潛在的毀滅性比你所親眼見過的任何東西還要強大，$N。更強大、更黑暗的力量就藏在他們的活動背後。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8070 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8070, 'zhTW', '聯盟榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。聯盟不同陣營的表揚官分佈在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找落雪戰場元帥。', '聯盟榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。聯盟不同陣營的表揚官分佈在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找落雪戰場元帥。', '聯盟榮譽徽章是獎勵給那些富於責任感的英雄的。各大主城均設有嘉獎官，與你想要提升聲望的主城中的嘉獎官交談，按照規定的數量繳納徽章吧！\n順便說一句，在安其拉大戰期間，如果你想要用徽章換取實物獎勵而不是提升聲望的話，可以去找大元帥斯諾·落雪。', '聯盟榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。聯盟不同陣營的表揚官分佈在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找落雪戰場元帥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8071 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8071, 'zhTW', '我們團結一致，$r。一個古老的惡魔威脅要毀滅卡林多上的所有生命，並以它邪惡的力量摧毀世界…它是所有仇恨事物的締造者:永恆的泰坦。$B$B我們是唯一能與克蘇恩軍隊抗衡的軍隊。如果我們不繼續向前攻打我們的敵人， 我們的敵人絕對會摧毀我們。$B$B戰備需要你!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8072 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8072, 'zhTW', '聯盟榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。聯盟不同陣營的表揚官分佈在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找落雪戰場元帥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8073 AND `Locale` = 'zhTW';
