INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8076, 'zhTW', '這隻麋鹿的脖子上有著一塊上面有著燻木牧場的標誌的標籤，上面寫著「梅特森」。$B$B梅特森用一種傷心、絕望的眼神看著你。看起來這頭麋鹿似乎被某種看不見的力量給限制了行動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8077 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8077, 'zhTW', '當你把麋鹿粉灑在梅特森身上時，它的雙眼中充滿了喜悅之情。它朝著你搖了搖鹿角，併發出了沉重的嘆息聲，聽起來像是如釋重負的樣子。$B$B你感覺到身邊有魔法能量的湧動，一定是有什麼事情就要發生了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8078 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8078, 'zhTW', '即使你不知道為何沒有擊敗克蘇恩而設法解救我們，我們仍會集中所有的力量將野獸驅回牠原本的地獄－不惜任何代價。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8079 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8079, 'zhTW', '一群英雄?一定要驅逐克蘇恩，我們會幫助你，人類!', '一群英雄?一定要驅逐克蘇恩，我們會幫助你，人類!', '龍類指派的英雄？必須除掉克蘇恩！我們可以幫助你，凡人！', '一群英雄?一定要驅逐克蘇恩，我們會幫助你，人類!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8080 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8080, 'zhTW', '我目睹站在我眼前的奇蹟!經過了一千年的囚禁，我還沒見過一件活的樣品－除了那些邪惡的其拉和異種蠍－進入密室。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8081 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8081, 'zhTW', '別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', '別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', '別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', '別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', '別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', '別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', '別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', '別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8082 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8082, 'zhTW', '你好，$c。我是這裡指揮作戰的戰場元帥落雪。我們還有一段辛苦的路要走，$g小夥子:小姑娘;，所以如果你能幫忙，那是再好不過。請任意發問。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8084 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8084, 'zhTW', '我們成功了，$G小夥子:姑娘;！聯盟和部落已經集齊了安其拉一戰所需的所有物資。現在這些物資都在運往希利蘇斯塞納里奧要塞的途中，預計將在$2113w天內達到。然後，會有一位勇敢的英雄使用流沙節杖敲響甲蟲之臺的銅鑼，開啟安其拉之門。那時，戰爭也就開始了！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8085 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8085, 'zhTW', '你聽說了嗎？聯盟和部落都已經把物資收集完畢了， $2113w 天后物資就會被運到希利蘇斯，一旦有人拿著流沙節仗敲響銅鑼，安其拉大戰就打響了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8087 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8087, 'zhTW', '問得好，$C。我得到的最新訊息稱我們已經收集到$1997w塊銅錠、$2002w塊鐵錠和$2011w塊瑟銀錠了，總的需求量分別是$1998w、$2003w和$2012w。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8088 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8088, 'zhTW', '草藥，草藥，嗯，讓我看看。啊，是的。到當前為止我們已經收集到$2047w份荊棘藻、$2053w份紫蓮花和$2057w份阿爾薩斯之淚，而總的需求量分別是$2048w、$2055w和$2058w。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8089 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8089, 'zhTW', '我剛剛得到最新的訊息。似乎我們已經收集到$2060w張輕皮、$2063w張中皮和$2069w張厚皮，而總的需求量分別是$2061w、$2064w和$2071w。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8090 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8090, 'zhTW', '收集繃帶的工作正有條不紊地按計劃進行著。我們已經收集到$2076w根亞麻繃帶、$2082w根絲質繃帶和$2088w根符文布繃帶了，總的需求量分別是$2077w、$2083w和$2090w。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8091 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8091, 'zhTW', '我們已經收集到了$2092w條彩鰭魚、$2098w塊烤迅猛龍肉和$2101w條斑點黃尾魚，而總的需求量是$2093w、$2099w和$2103w。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8092 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8092, 'zhTW', '(獸人語)你好，部落的$C，以你為榮!我是部落作戰指揮官，督軍格爾庫克。我們將面臨一連串艱難的考驗，我們會戰勝一切的，一如往常。$B$B如果你有問題，可以問問他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8094 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8094, 'zhTW', '作戰的時刻就要來臨了，$c!部落和聯盟都完成了他們的準備工作。所有的物資都被送往希利蘇斯了。我想最後一批應該$2113w天內就會到達。當一切就緒後，就會有人完成重組流沙之地權杖的艱難任務並敲響甲蟲之鑼，開啟安其拉之門。然後就會展開許久不見的大戰!$B$B為了部落!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8096 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8096, 'zhTW', '我們已有$2018w個銅錠超過所需的$1998w個。已收集了$2005w個錫錠及$$2008w個秘銀錠，總需求量分別是$2006w個錫錠和$2009w個秘銀錠。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8097 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8097, 'zhTW', '我剛收到最新訊息。我們現在已有$2021w寧神花超過所需的$2020w。已收集了$2050w火焰花及$2054w紫蓮花，總需求分別是$2051w火焰花和$2055w紫蓮花。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8098 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8098, 'zhTW', '等我一下;這兒有很多數字要記一下。看來我們需要$2067w張重皮，現在只收集到$2066w張。還有，厚皮也需要$2071w張，現在只收集到$2070w張。需要$2074w張粗皮現在也只有$2073w張。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8099 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8099, 'zhTW', '繃帶?為什麼，你是打算活久一點所以才需要它們嗎?哈!很好，$r，我告訴你。我們需要$2080w絨線繃帶，但目前只有$2079w張。目前還需要$2086w魔紋布繃帶，但目前只有$2085w張。符文布繃帶要$2090w，目前也只收集$2089w。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8100 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8100, 'zhTW', '食物，是現在能塞我牙縫的東西!我說過我們需要$2096w瘦狼排，現在有$2095w103w有斑點的黃尾魚，現在有$2102w106w冷藏並已儲存的烤鮭魚，現在有$2105w。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
