INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8101, 'zhTW', '你好，$c。我希望你是來問安其拉之戰的事。我們需要很多協助。$B$B這是場聯盟和部落結合起來準備對抗安其拉異種和主使者的大戰。在鐵爐堡的軍事區，我們正在收集所有的物品來製造我們的作戰物資，而這些收集的任務正需要你的幫忙。$B$B我能請你去和我們的指揮官談談嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8103 AND `Locale` = 'zhTW';
