INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8112, 'zhTW', '若克蘇恩還活著，我們的自由就根本不算什麼。你真是一位預言勇士。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8113 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8113, 'zhTW', '英雄，在這受咒的寺廟裡所發生的事情都會被發現。它會被記載於史書中－故事以傳說描述艾澤拉斯遠至虛空本身!', '英雄，在這受咒的寺廟裡所發生的事情都會被發現。它會被記載於史書中－故事以傳說描述艾澤拉斯遠至虛空本身!', '英雄，在這受咒的寺廟裡所發生的事情都會被發現。它會被記載於史書中－故事以傳說描述艾澤拉斯遠至虛空本身!', '英雄，在這受咒的寺廟裡所發生的事情都會被發現。它會被記載於史書中－故事以傳說描述艾澤拉斯遠至虛空本身!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8114 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8114, 'zhTW', '既然戰火蔓延已達巔峰，到目前為止，部落與聯盟的強壯戰士都沒有短缺。$B$B但願我們能將他們趕盡殺絕...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8115 AND `Locale` = 'zhTW';
