INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8120, 'zhTW', '詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個某種製作揹包的裁縫術語。以你對裁縫的瞭解還無法讓你破解這術語。', '詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個某種製作揹包的裁縫術語。以你對裁縫的瞭解還無法讓你破解這術語。', '詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個某種製作揹包的裁縫術語。以你對裁縫的瞭解還無法讓你破解這術語。', '詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個某種製作揹包的裁縫術語。以你對裁縫的瞭解還無法讓你破解這術語。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8121 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8121, 'zhTW', NULL, 'The journal of Jandice Barov is filled with rantings and ravings about the undead. Towards the end of the book is what appears to be a tailoring pattern for the creation of a felcloth bag. This bag is used by warlocks to store soul shards. Do you wish to copy the pattern into your own journal?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8122 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8122, 'zhTW', NULL, 'The journal of Jandice Barov is filled with rantings and ravings about the undead. Towards the end of the book is what appears to be a tailoring pattern for the creation of a felcloth bag. This bag is used by warlocks to store soul shards. You already know how to create this bag.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
