INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8199, 'zhTW', '不知道是什麼原因，雷角長者到安戈洛環形山的巨痕谷去了。', '不知道是什麼原因，雷角長者到安戈洛環形山的巨痕谷去了。', '雷角長者到安戈洛環形山的巨痕谷去了，天知道他要幹什麼。', '不知道是什麼原因，雷角長者到安戈洛環形山的巨痕谷去了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
