INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8201, 'zhTW', '基石長者在希利蘇斯的水晶谷度過了許多年。', '基石長者在希利蘇斯的水晶谷度過了許多年。', '稜石長者在希利蘇斯的水晶谷生活了許多年。', '基石長者在希利蘇斯的水晶谷度過了許多年。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8202 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8202, 'zhTW', '長者們的榮譽就是對你們文化和人民的榮譽，$c。這個時候，祖先的錢幣就是表揚那些選擇踏上可敬之路的人最有力的方法。$B$B在這次的新年慶典中，你有機會為許多長者爭光。如果你要這樣做，就需要祖先的錢幣。帶給我這些錢幣，我就會讓你選擇一個獨特的物品作為獎勵。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8205 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8205, 'zhTW', '你好，$N。我們從月光林地過來，散播新年慶典的精神至世界各地。$B$B你何不加入我們的慶祝活動?', '你好，$N。我們從月光林地過來，散播新年慶典的精神至世界各地。$B$B你何不加入我們的慶祝活動?', '你好，$n。我們從月光林地來這裡，要將新年的喜悅傳播到世界的各個角落.\n你難道不想與我們一起慶祝新年嗎？', '你好，$N。我們從月光林地過來，散播新年慶典的精神至世界各地。$B$B你何不加入我們的慶祝活動?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8209 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8209, 'zhTW', '我們和聯盟站在同一陣線，$r。一個惡魔，古老到世界已經遺忘了它，想要吞沒我們;先是卡林多，再來就是整個艾澤拉斯。它被一個偉大變形者所創的仇恨而驅使:永恆的泰坦。$B$B我們全都阻擋著克蘇恩的軍隊。我們會先進攻並拿下安其拉的軍隊。讓整個艾澤拉斯因為部落和聯盟的力量結合而震動。$B$B戰爭需要你!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8210 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8210, 'zhTW', '我上次看到草奔長者是在西瘟疫之地的聖光之願禮拜堂。', '我上次看到草奔長者是在西瘟疫之地的聖光之願禮拜堂。', '幽林長者在西瘟疫之地的哭泣之洞外面。', '我上次看到草奔長者是在西瘟疫之地的聖光之願禮拜堂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8211 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8211, 'zhTW', '你可以在荊棘谷通往祖爾格拉布的入口外面找到星林長者。', '你可以在荊棘谷通往祖爾格拉布的入口外面找到星林長者。', '你可以在荊棘谷通往祖爾格拉布的入口外面找到星林長者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8212 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8212, 'zhTW', '「你的戰爭物資收集工作做的很好」他們說，「你一定會得到晉升的!」。他們真正的意思是，「你會和一群小不點的矮人一起被部署在希利蘇斯的某個蟲巢外面，卡恩斯!」$B$B謝謝你的提拔，上尉!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8213 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8213, 'zhTW', '我，就像我的哥哥一樣，為那些替自己祖先爭光的人爭光。與新年慶典的侍徒們分享我手工技藝的秘密帶給我很大的快樂!', '我，就像我的哥哥一樣，為那些替自己祖先爭光的人爭光。與新年慶典的侍徒們分享我手工技藝的秘密帶給我很大的快樂!', '我，就像我的兄弟們一樣，以那些尊重祖先的人為榮。對我來說，與歡度春節的人們一起分享我的秘密手藝是極大的快樂。', '我，就像我的哥哥一樣，為那些替自己祖先爭光的人爭光。與新年慶典的信徒們分享我手工技藝的秘密帶給我很大的快樂!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8214 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8214, 'zhTW', '當戰爭開打時，我就像其他人一樣，是來這裡幫助我的夥伴德魯伊們。$B$B現在安其拉之門已經開啟，我知道還有很多工作需要完成。我已決定要待在希利蘇斯，並盡全力協助達成目標，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8215 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8215, 'zhTW', '異種蠍看來相當致命，但牠們和其拉主宰比起來卻只是只溫馴的小動物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8216 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8216, 'zhTW', '這戰爭還沒結束，才剛開始而已!我們日夜都有勇猛的戰士對抗安其拉里的敵人， $N。不久之後其拉城就會淪陷。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
