INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8234, 'zhTW', '一團糟，這就是怎麼回事!這些生物全都不知道從哪冒出來，然後就開始失去控制!!而博學者和他的學徒跑到哪去了呢?只把我留在這裡，連一句「嘿，威利坦要不要一起走?」都沒有。$B$B真是大膽!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8235 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8235, 'zhTW', '戰爭讓我們飽受催殘。我們也忘了要花時間去愛。', '戰爭讓我們飽受催殘。我們也忘了要花時間去愛。', '戰爭讓我們飽受催殘。我們也忘了要花時間去愛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
