INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8263, 'zhTW', '我們獸人通常都對愛情相當保密，但最近大家都不想再躲躲藏藏了。', '我們獸人通常都對愛情相當保密，但最近大家都不想再躲躲藏藏了。', '我們獸人通常不喜歡過多談論自己的感情問題，但今天可不是遮遮掩掩的時候。', '我們獸人通常都對愛情相當保密，但最近大家都不想再躲躲藏藏了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
