INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8269, 'zhTW', '嘿!你看起來很眼熟...我們以前在哪見過?\n\n恩~如果我們見過.應該...給過你一個密碼.\n\n告訴我密碼.我會給你一份禮物!', '嘿!你看起來很眼熟...我們以前在哪見過?\n\n恩~如果我們見過.應該...給過你一個密碼.\n\n告訴我密碼.我會給你一份禮物!', '嘿!你看起來很眼熟...我們以前在哪見過?\n\n恩~如果我們見過.應該...給過你一個密碼.\n\n告訴我密碼.我會給你一份禮物!', '你好，$C，我有沒有在最近的聚會上看到過你？你看起來挺眼熟的，說起來那地方還真是挺熱鬧的，$B$B如果你參加了那次會議，你肯定有一個密碼，告訴我密碼，作為回報我會給你些特殊的禮品。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
