INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8307, 'zhTW', '愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。', '愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。', '愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$b$b或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。', '愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
