INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8308, 'zhTW', '如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住:給別人硬幣時，你也要聞起來香香的才行!男人喜歡香水的味道，而女人則偏愛古龍水的香味。', '如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住:給別人硬幣時，你也要聞起來香香的才行!男人喜歡香水的味道，而女人則偏愛古龍水的香味。', '如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$b$b請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。', '如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住:給別人硬幣時，你也要聞起來香香的才行!男人喜歡香水的味道，而女人則偏愛古龍水的香味。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8312 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8312, 'zhTW', '誰是這個伺服器最受歡迎的英雄呢，你猜?這是目前的排行榜!$B$B索爾:$2200w$B凱恩:$2201w$B希瓦娜斯:$2202w$B部落總票數:$2207w$B$B瓦爾:$2203w$B麥格尼:$2204w$B泰蘭妲:$2205w$B聯盟總票數:$2206w$B$B如果想投票，就快去繳交你的禮物典藏品!', '誰是這個伺服器最受歡迎的英雄呢，你猜?這是目前的排行榜!$B$B索爾:$2200w$B凱恩:$2201w$B希瓦娜斯:$2202w$B部落總票數:$2207w$B$B瓦爾:$2203w$B麥格尼:$2204w$B泰蘭妲:$2205w$B聯盟總票數:$2206w$B$B如果想投票，就快去繳交你的禮物典藏品!', '誰是這個伺服器最受歡迎的英雄呢，你猜？這是目前的排行榜！$b$b薩爾:$2200w\n凱恩:$2201w\n希爾瓦娜斯:$2202w\n部落總數量:$2207w$b$b瓦爾:$2203w\n麥格尼:$2204w\n泰蘭德:$2205w\n聯盟總數量:$2206w\n如果想投票，就快去繳交你的禮物典藏品！', '誰是這個伺服器最受歡迎的英雄呢，你猜?這是目前的排行榜!$B$B索爾:$2200w$B凱恩:$2201w$B希瓦娜斯:$2202w$B部落總票數:$2207w$B$B瓦爾:$2203w$B麥格尼:$2204w$B泰蘭妲:$2205w$B聯盟總票數:$2206w$B$B如果想投票，就快去繳交你的禮物典藏品!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8313 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8313, 'zhTW', '嗨!我是丘位元·傳播者!我在這裡是為了找出艾澤拉斯最受歡迎的英雄!$B$B看到這麼多崇拜領導者的狂熱仰慕者真是溫暖我心啊，但……你知道還有什麼也能溫暖我心嗎?$B$B是一個香吻!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8315 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8315, 'zhTW', '這是最後的排行榜！$B$B索爾: $2200w$B凱恩: $2201w$B希瓦娜斯: $2202w$B部落總數量: $2207w$B$B伯瓦爾: $2203w$B麥格尼: $2204w$B泰蘭妲: $2205w$B聯盟總數量: $2206w$B$B聯盟是最受歡迎的英雄！', '這是最後的排行榜！$B$B索爾: $2200w$B凱恩: $2201w$B希瓦娜斯: $2202w$B部落總數量: $2207w$B$B伯瓦爾: $2203w$B麥格尼: $2204w$B泰蘭妲: $2205w$B聯盟總數量: $2206w$B$B聯盟是最受歡迎的英雄！', '最終的排名是！薩爾：$2200w凱恩：$2201w希爾瓦娜斯：$2202w部落總計：$2207w伯瓦爾：$2203w麥格尼：$2204w泰蘭德：$2205w聯盟總計：$2206w聯盟的英雄人氣最高！', '這是最後的排行榜！$B$B索爾: $2200w$B凱恩: $2201w$B希瓦娜斯: $2202w$B部落總數量: $2207w$B$B伯瓦爾: $2203w$B麥格尼: $2204w$B泰蘭妲: $2205w$B聯盟總數量: $2206w$B$B聯盟是最受歡迎的英雄！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8317 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8317, 'zhTW', '當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘位元·傳播者把禮物交給他。$B$B丘位元就在伯瓦爾，麥格尼和泰蘭妲附近。', '當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘位元·傳播者把禮物交給他。$B$B丘位元就在伯瓦爾，麥格尼和泰蘭妲附近。', '當你把愛情信物交給城鎮裡的居民時，你可以收到各種禮物作為回報。一些禮物最好留起來用，另一些則最好放在一起做成一個大禮品包！去找匹德菲特為你喜歡的英雄投票吧。你可以在伯瓦爾、麥格尼或者泰蘭德身邊找到匹德菲特。', '當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘位元·傳播者把禮物交給他。$B$B丘位元就在伯瓦爾，麥格尼和泰蘭妲附近。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8318 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8318, 'zhTW', '我註定永遠被束縛在這個受詛咒的世界。你的慾望是什麼，凡人?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8319 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8319, 'zhTW', '當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘位元·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。', '當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘位元·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。', '當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其它的就可以收集在一起送給你最喜歡的英雄！拜訪丘位元·傳播者把禮物交給他。$b$b傳播者就在凱恩，希爾瓦娜斯和薩爾附近。', '當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘位元·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8321 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8321, 'zhTW', '這本秘典的內容就像潮水不斷流出。你覺得好像你腦中的思緒被榨乾並被這本書消化掉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8322 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8322, 'zhTW', 'MISSING TEXT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8326 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8326, 'zhTW', '影像，形狀，和記號的組合出現在你眼前。這本書似乎瞭解你的制皮技術並提供你一個選擇 - 但是警告你 - 你只能做一個選擇，並且一旦決定後，就不能改變心意!:', '影像，形狀，和記號的組合出現在你眼前。這本書似乎瞭解你的制皮技術並提供你一個選擇 - 但是警告你 - 你只能做一個選擇，並且一旦決定後，就不能改變心意!:', '無數的圖象、幻影與標記同時出現在你的腦海中。這本書似乎知道你在制皮方面的技術成就一般，並給了你一個選擇的機會，但是請注意，你只能選擇一次！', '影像，形狀，和記號的組合出現在你眼前。這本書似乎瞭解你的制皮技術並提供你一個選擇 - 但是警告你 - 你只能做一個選擇，並且一旦決定後，就不能改變心意!:', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8327 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8327, 'zhTW', '我不能教你龍鱗的制皮技術，$n。你一定要去塔納利斯找到納裡安·柔想的家。到了那裡，參照「新手的預言入門」這本書。', '我不能教你龍鱗制皮，$N你必須去塔納利斯，並找到納裡安·柔想的家。你到了那兒以後，詢問有關一本叫做《新手的預言入門》的書。', NULL, '我不能教你龍鱗制皮，$N你必須去塔納利斯，並找到納裡安·柔想的家。你到了那兒以後，詢問有關一本叫做《新手的預言入門》的書。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8332 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8332, 'zhTW', '索爾讓我進入他領地中的聖域是對我釋出相當大的善意。無論如何，我不求久留。給我們的領導者帶來任何麻煩都是極大的侮辱。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8333 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8333, 'zhTW', '試著別引來太多注目，我正等著國王覲見。我不介意等待，在這些魁梧的守衛旁邊我覺得相當有安全感。', '試著別引來太多注目，我正等著國王覲見。我不介意等待，在這些魁梧的守衛旁邊我覺得相當有安全感。', '請儘量不要引起太多注目，我正在等待國王的召見。我並不介意多等一會兒，這兒到處是身材魁梧的守衛，我感到非常安全。', '試著別引來太多注目，我正等著國王覲見。我不介意等待，在這些魁梧的守衛旁邊我覺得相當有安全感。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8334 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8334, 'zhTW', '喪命的危險是我常碰到的事。但失去亞希達是我不能容忍的事，就算我死了也是一樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8335 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8335, 'zhTW', '你好，朋友!想不想看一些精華電容器?或是精細的全方位鬼靈吸收器?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8336 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8336, 'zhTW', '什麼事?你沒看到我正在忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8344 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8344, 'zhTW', '我現在很好，別擔心我。等我在這房間裡進行一些淨化儀式後就會想辦法出去。邪惡的魔法汙染了這個地方，$N。', '我現在很好，別擔心我。等我在這房間裡進行一些淨化儀式後就會想辦法出去。邪惡的魔法汙染了這個地方，$N。', '我現在很好，別擔心我。等我在這房間裡進行一些淨化儀式後就會想辦法出去。邪惡的魔法汙染了這個地方，$N。', '我現在很好，別擔心我。等我在這房間裡進行一些淨化儀式後就會想辦法出去。邪惡的魔法汙染了這個地方，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8347 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8347, 'zhTW', '我們最新的產品，我不會多收你的錢，就是這些小型坦克，可以受馬戲團裡的任何坦克控制檯所控制。$B$B你所要做的就是啟動一個可用的控制檯。每輛坦克會裝備一批儀器，還有可以隨意對你的敵人釋放的特殊能量。$B$B和你的朋友一起打場史詩戰，四處逛逛，或是去試試它的威力...隨你想怎麼作都可以!', '我們最新的產品，我不會多收你的錢，就是這些小型坦克，可以受馬戲團裡的任何坦克控制檯所控制。$B$B你所要做的就是啟動一個可用的控制檯。每輛坦克會裝備一批儀器，還有可以隨意對你的敵人釋放的特殊能量。$B$B和你的朋友一起打場史詩戰，四處逛逛，或是去試試它的威力...隨你想怎麼作都可以!', '我們新近發現，馬戲團中隨處可見的蒸汽車控制檯能操縱這些被稱為蒸汽車的迷你坦克，我可是很慷慨地跟你分享這一資訊。\n你只需啟用控制檯就行了。每輛坦克都配備了常用的彈藥和某種秘密武器，向你的敵人開火吧！\n和朋友一起參加史詩般的戰鬥、巡邏、或者僅僅是進行野蠻的破壞……一切都由你自己選擇！', '我們最新的產品，我不會多收你的錢，就是這些小型坦克，可以受馬戲團裡的任何坦克控制檯所控制。$B$B你所要做的就是啟動一個可用的控制檯。每輛坦克會裝備一批儀器，還有可以隨意對你的敵人釋放的特殊能量。$B$B和你的朋友一起打場史詩戰，四處逛逛，或是去試試它的威力……隨你想怎麼作都可以!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8348 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8348, 'zhTW', 'MISSING TEXT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
