INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8349, 'zhTW', '衝擊者5000型超級大炮是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大炮是布萊頓海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想和鳥一樣在空中翱翔，就去雷霆崖獵人高地南方邊緣找瑪克希瑪·布萊頓海默。她會在石牛湖南方的目標向你瞄準!', '衝擊者5000型超級大炮是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大炮是布萊頓海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想和鳥一樣在空中翱翔，就去雷霆崖獵人高地南方邊緣找瑪克希瑪·布萊頓海默。她會在石牛湖南方的目標向你瞄準!', '衝擊者5000型超級大炮是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大炮是布萊頓海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的!\n\n如果你想和鳥一樣在空中翱翔，就去雷霆崖獵人高地南方邊緣找瑪克希瑪·布萊頓海默。她會在石牛湖南方的目標向你瞄準!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8350 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8350, 'zhTW', '聽說科爾蘇加德在尋找充滿傳奇的阿泰絲，偉大的守護者。$B$B對，就是麥迪文曾經持有的那把神杖。', '聽說科爾蘇加德在尋找充滿傳奇的阿泰絲，偉大的守護者。$B$B對，就是麥迪文曾經持有的那把神杖。', '聽說克爾蘇加德正在研究傳說中的埃提耶什，守護者的傳說之杖。\n是的，就是那件曾屬於麥迪文的神奇法杖。', '聽說科爾蘇加德在尋找充滿傳奇的阿泰絲，偉大的守護者。$B$B對，就是麥迪文曾經持有的那把神杖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8351 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8351, 'zhTW', '當碰到危害這個世界的事物時，我們聖光兄弟會相較之下是不會手下留情的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8352 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8352, 'zhTW', '巫妖王想讓自己名揚四海。絕不能讓他得逞。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8353 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8353, 'zhTW', '什麼是聖光兄弟會?嗯...我們都是銀色黎明的核心成員，不受道德、罪惡感和沒用的人類情感所操控。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8354 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8354, 'zhTW', '銀色黎明也許是個無力的理想主義者，他們有妄想傾向的領導者知道自己有優勢。我是血色十字軍派來的密使，也就是外交大使，如果你將…能不能削弱科爾蘇加德的軍隊都還是個問號－統一或獨立－我們如果能攔截他們的話就是奇蹟發生了。$B$B至於我呢?我將死在戰場上…$B$B<馬翰聳肩。>', '銀色黎明也許是個無力的理想主義者，他們有妄想傾向的領導者知道自己有優勢。我是血色十字軍派來的密使，也就是外交大使，如果你將…能不能削弱科爾蘇加德的軍隊都還是個問號－統一或獨立－我們如果能攔截他們的話就是奇蹟發生了。$B$B至於我呢?我將死在戰場上…$B$B<馬翰聳肩。>', '銀色黎明只不過是一群懦弱無力的理想主義者，若不是他們的領袖能意識到自己的不足，他們真可以說是無可救藥了。我是血色十字軍派駐到這裡來的一名大使。是的，算是一名外交人員……我們的未來仍然是一片迷霧，我不知道我們是否能成為一支聯軍，或各自為戰；我也不知道我們是否能夠在克爾蘇加德的侵略之下保衛家園，或讓這個世界淪陷，但我們應該竭盡全力，奇蹟總在風雨之後到來。\n至於我？馬革裹屍，戰死沙場……\n<瑪爾蘭聳了聳肩。>', '銀色黎明也許是個無力的理想主義者，他們有妄想傾向的領導者知道自己有優勢。我是血色十字軍派來的密使，也就是外交大使，如果你將…能不能削弱科爾蘇加德的軍隊都還是個問號－統一或獨立－我們如果能攔截他們的話就是奇蹟發生了。$B$B至於我呢?我將死在戰場上…$B$B<馬翰聳肩。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8355 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8355, 'zhTW', '頭銜是騙人的。你瞭解我後，你就知道我是個好人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8356 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8356, 'zhTW', '他們都派了我的兄弟，洛克希，到這個集會。他連他的獵犬都顧不好了，更別說有資格代表血色十字軍。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8357 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8357, 'zhTW', '我一直在期...$B$B<林布拉特咳嗽。>$B$B不好意思，老毛病。我是陶土議會的林布拉特。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8358 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8358, 'zhTW', '哈羅，$c。請不要吸引太多注意。', '哈羅，$c。請不要吸引太多注意。', '哈囉，$c。抱歉我在跟林布拉特談話。他深信這塊土地還沒復元。', '哈囉，$c。抱歉我在跟林布拉特談話。他深信這塊土地還沒復元。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8359 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8359, 'zhTW', '你要什麼，鼠輩?知道為什麼大家都叫我施怒者?在我證明之前，你趕快給我滾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8363 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8363, 'zhTW', '第一套無畏護甲是專為血色大領主莫格萊尼訂做的。完成時，大領主覺得自己活生生像是從冥府來的惡魔。$B$B沒錯，這的確是個絕佳機會親見莫格萊尼精神飽滿的率領血色十字軍，齊聲吶喊、高舉揮舞著灰燼使者，眼看另一端敵軍於燃火飛塵之中在他的雙腳下慌張撤離。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8364 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8364, 'zhTW', '在飽受爭議的死亡事件之後，羅德隆的騎士與戰士為了向他們倒下的英雄表示敬意，紛紛都穿起類似的戰袍。而莫格萊尼的死對科爾蘇加德是偉大的勝利，最後殉難的結果要一直到戰爭結束才知分曉。$B$B一王倒下，他強必崛起…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8366 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8366, 'zhTW', '我就是你口中的資本家，$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8374 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8374, 'zhTW', '喔，哈羅…嗯，你是?$B$B不要緊，是什麼風把你吹來我在這美麗鄉村的離家之園啊?', '喔，哈囉…嗯，你是?$b$b不要緊，是什麼風把你吹來我在這美麗鄉村的離家之園啊?', '喔，哈囉…嗯，你是?$b$b不要緊，是什麼風把你吹來我在這美麗鄉村的離家之園啊?', '喔，哈囉…嗯，你是?$B$B不要緊，是什麼風把你吹來我在這美麗鄉村的離家之園啊?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8375 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8375, 'zhTW', '嗨，$c。想必你們一定玩得很開心吧?你們覺得的派對好玩嗎?希望我們派對上的東西都夠供應。飲料跟開胃點心如果不夠就是派對的致命傷啊，對吧?$B$B嗯，好啦，我要去招待其他賓客羅。盡興玩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8378 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8378, 'zhTW', '你好，$g大人:小姐;。我相信你一定玩的很開心吧?', '你好，$g大人:小姐;。我相信你一定玩的很開心吧?', '你好，尊敬的$g先生:女士', '你好，$g大人:小姐;。我相信你一定玩的很開心吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8379 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8379, 'zhTW', '你不覺得很好玩嗎?我真高興薩瑟裡領主每晚都舉辦舞會，尤其是那些令人作嘔的東西滾到南方，感覺就像把它們拋諸腦後，對吧?', '你不覺得很好玩嗎?我真高興薩瑟裡領主每晚都舉辦舞會，尤其是那些令人作嘔的東西滾到南方，感覺就像把它們拋諸腦後，對吧?', '這不是很有趣嗎？我很高興薩瑟利爾男爵每晚都舉辦這樣的聚會，特別在南部發生著些令人不愉快的事情時，聚會可以讓我們忘記那一切，你覺得呢？', '你不覺得很好玩嗎?我真高興薩瑟裡領主每晚都舉辦舞會，尤其是那些令人作嘔的東西滾到南方，感覺就像把它們拋諸腦後，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8388 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8388, 'zhTW', '我跟科爾蘇加德一樣都曾經是祈倫託的法師，我們也都在遍尋傳說中的守護者之杖，阿泰絲。我們的命運是如此糾纏著，$c。', '我跟科爾蘇加德一樣都曾經是祈倫託的法師，我們也都在遍尋傳說中的守護者之杖，阿泰絲。我們的命運是如此糾纏著，$c。', '與克爾蘇加德一樣，我也是一個來自肯瑞託議會的法師，更相似的是，我與他都在尋找著埃提耶什，守護者的傳說之杖。我們的命運似乎就這樣交織在一起了，$c。', '我跟科爾蘇加德一樣都曾經是肯瑞託的法師，我們也都在遍尋傳說中的守護者的大法杖，阿泰絲。我們的命運是如此糾纏著，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8389 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8389, 'zhTW', '艾格文的後裔，他會成為提里斯法最後一位守護者…麥迪文。', '艾格文的後裔，他會成為提里斯法最後一位守護者…麥迪文。', '艾格文的唯一子嗣，最後一任提瑞斯法的守護者……麥迪文。', '艾格文的後裔，他會成為提里斯法最後一位守護者…麥迪文。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8390 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8390, 'zhTW', '這是一個傳奇，這也是個我沒時間和意願重述的故事，只要知道麥迪文是最後一位守護者。阿泰絲大法杖是權力的核心，也是墮落的極點。', '這是一個傳奇，這也是個我沒時間和意願重述的故事，只要知道麥迪文是最後一位守護者。阿泰絲大法杖是權力的核心，也是墮落的極點。', '有關他的傳說，我想我沒有時間也沒有興趣重述一遍給你聽。你只要知道麥迪文是最後一位守護者。而埃提耶什這把傳說中的法杖，既是他力量的焦點，也是腐蝕的焦點。', '這是一個傳奇，這也是個我沒時間和意願重述的故事，只要知道麥迪文是最後一位守護者。阿泰絲大法杖是權力的核心，也是墮落的極點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8391 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8391, 'zhTW', '失敗巨人的腐敗，毀滅者的墮落。終究這法杖還是由仇恨的種子所鍛造。也就是說，這當然是我來這裡的主因…', '失敗巨人的腐敗，毀滅者的墮落。終究這法杖還是由仇恨的種子所鍛造。也就是說，這當然是我來這裡的主因…', '一位墮落泰坦的腐蝕。毀滅者的腐蝕。總之，這根法杖發源於仇恨的種子。當然，這也是我來到這裡的原因……', '失敗巨人的腐敗，毀滅者的墮落。終究這法杖還是由仇恨的種子所鍛造。也就是說，這當然是我來這裡的主因…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8392 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8392, 'zhTW', '在卡拉贊倒下後，祈倫託派了一群法師到哨塔搜尋，並扣押所有進口的物品……就為了「研究」的目的。就是那時候才發現了寓言中的法杖，並將它帶回達拉然。', '在卡拉贊倒下後，祈倫託派了一群法師到哨塔搜尋，並扣押所有進口的物品……就為了「研究」的目的。就是那時候才發現了寓言中的法杖，並將它帶回達拉然。', '在卡拉贊陷落之後，肯瑞託議會派遣了一隊法師搜尋了整座塔，收集到了所有重要的東西……目的？或許是研究吧。總之不知道是否真的，據說這根法杖被帶到了達拉然。', '在卡拉贊倒下後，肯瑞託派了一群法師到哨塔搜尋，並扣壓所有進口的物品……就為了“研究”的目的。就是那時候才發現了寓言中的法杖，並將它帶回達拉然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8393 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8393, 'zhTW', '所跟隨的是一連串的悲劇，以致每位只要接觸阿泰絲的祈倫託法師都會死亡。$B$B你看，這是有知覺的神器，是薩格拉斯賦予它的…', '所跟隨的是一連串的悲劇，以致每位只要接觸阿泰絲的祈倫託法師都會死亡。$B$B你看，這是有知覺的神器，是薩格拉斯賦予它的…', '接著，達拉然那邊發生了一系列不幸的事件，所有碰過埃提耶什——甚至是僅僅做過與之相關工作的肯瑞託法師都離奇地死亡了。\n你看，它似乎是一種有感知的神器，這感知能力想必是薩格拉斯所授予的……', '所跟隨的是一連串的悲劇，以致每位只要接觸阿泰絲的肯瑞託法師都會死亡。$B$B你看，這是有知覺的神器，是薩格拉斯賦予它的…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8394 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8394, 'zhTW', '<安琪拉點頭。>$B$B他們死後，六人決定最好的應變措施，就是藉由堅固的魔法屏障來隔離法杖，並且任命守護者︰法杖的守護者…而我就是那位守護者。', '<安琪拉點頭。>$B$B他們死後，六人決定最好的應變措施，就是藉由堅固的魔法屏障來隔離法杖，並且任命守護者︰法杖的守護者…而我就是那位守護者。', '<安吉拉點了點頭。>\n在他們死後，六人議會做出了決定。他們認為對這根法杖最好的處理方法無非是用牢固的魔力監牢封印起來，並委任一名看守者……原本應該是我。', '<安吉拉點頭。>$B$B他們死後，六人決定最好的應變措施，就是藉由堅固的魔法屏障來隔離法杖，並且任命守護者∶法杖的守護者…而我就是那位守護者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8395 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8395, 'zhTW', '沒什麼好說的。達拉然幾乎全被阿克蒙德破壞，法杖遺失了，可能遭到故障防護裝置機所粉碎了。$B$B有些人相信就是因為法杖，所以引起阿克蒙德的報復。', '沒什麼好說的。達拉然幾乎全被阿克蒙德破壞，法杖遺失了，可能遭到故障防護裝置機所粉碎了。$B$B有些人相信就是因為法杖，所以引起阿克蒙德的報復。', '後來也沒什麼可說的了。達拉然幾乎完全被阿克蒙德摧毀，法杖也遺失了。據說，在那時，禁錮法陣啟動了某種保護機制，將法杖擊碎了。\n也有人說，禁錮了這根法杖是導致阿克蒙德毀滅達拉然的原因，是他為薩格拉斯所做的復仇。', '沒什麼好說的。達拉然幾乎全被阿克蒙德破壞，法杖遺失了，可能遭到故障防護裝置機所粉碎了。$B$B有些人相信就是因為法杖，所以引起阿克蒙德的報復。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8396 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8396, 'zhTW', '在達拉然被陷落之後，我也離開了祈倫託。我花了好幾年尋找阿泰絲，希望能取回祈倫託在某次可怕的突襲中，從我身上奪取的東西。就算要花一輩子，我也要找到法杖。那就是為什麼我參加銀色黎明，還有我現在為什麼在這裡的原因。', '在達拉然被陷落之後，我也離開了祈倫託。我花了好幾年尋找阿泰絲，希望能取回祈倫託在某次可怕的突襲中，從我身上奪取的東西。就算要花一輩子，我也要找到法杖。那就是為什麼我參加銀色黎明，還有我現在為什麼在這裡的原因。', '在達拉然淪陷以後，我離開了肯瑞託議會，用了好幾年的時間來搜尋埃提耶什的下落，只是為了履行我在肯瑞託未盡的責任。我會找到這根法杖，即使這要用去我一生的時間。這也是我加入銀色黎明並站在這裡的原因。', '在達拉然被攻陷之後，我也離開肯瑞託。我花了好幾年觀察阿泰絲，以求取回肯瑞託在某次可怕的突襲中，從我身上奪取的東西。雖然會追尋一生，但是我一定要找到法杖。那就是為什麼我參加銀色黎明，還有我現在為什麼在這裡的原因。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8397 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8397, 'zhTW', '我橫跨世界追蹤了各式各樣的法杖碎片，還因此發現科爾蘇加德改良法杖的計畫。他目前收集一些法杖碎片，並且由他最信賴的副官保管著。$B$B努力讓守護者的大法杖遠離科爾蘇加德的控制，這重要性可是非比尋常。坦白說，除了史詩部分的大災難外，我不知道結果將如何。', '我橫跨世界追蹤了各式各樣的法杖碎片，還因此發現科爾蘇加德改良法杖的計畫。他目前收集一些法杖碎片，並且由他最信賴的副官保管著。$B$B努力讓守護者的大法杖遠離科爾蘇加德的控制，這重要性可是非比尋常。坦白說，除了史詩部分的大災難外，我不知道結果將如何。', '最近幾年來，我一直在世界各地搜尋著法杖碎片的下落，並且發現克爾蘇加德正試圖重鑄它。他已經收集到了其中的幾塊碎片，並交給幾位深得他信賴的軍官儲存著。\n我無法再用什麼語言來強調從克爾蘇加德手中搶回法杖的重要性了。坦誠地講，如果讓他拿到了完整的法杖，我不知道這個世界除了被災難徹底淹沒之外還能有什麼其它結局。', '我橫跨世界追蹤了各式各樣的法杖碎片，還因此發現科爾蘇加德改良法杖的計劃。他目前收集一些法杖碎片，並且由他最信賴的副官保管著。$B$B努力讓守衛者的大法杖遠離科爾蘇加德的控制，這重要性可是非比尋常。坦白說，除了史詩部分的大災難外，我不知道結果將如何。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8398 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8398, 'zhTW', '這就是權力，低能兒。<麥特斯眼眸加深。>$B$B這些傻瓜派了像你這樣的白痴到納克薩瑪斯，取回玷汙的護甲以便淨化它，重組零件恢復昔日光采。$B$B<麥特斯啐了一口。>就是這種愚蠢至極的想法讓我反胃想吐。$B$B我也去尋找護甲，我要找玷汙以及被褻瀆最深的護甲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8399 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8399, 'zhTW', '我不會裝模作樣，蛆蟲。這種黑暗物品所支配的力量可以把我們兩個都摧毀。這就是為什麼價格如此高昂的原因。如果我就要死了，也會是個富翁。$B$B你死了我也不會對你吐一口豺狼人的口水，照我的話做就對了。把我要的東西帶來，我們就能雙方受惠 - 或者死;我已經解釋過了……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8401 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8401, 'zhTW', '你好，旅人。我奉命得將任何握有卡拉贊鑰匙的持有者待為主人的座上賓。有需要我幫忙的地方嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8402 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8402, 'zhTW', '我們對那些生物都太仁慈了。我們應該用劍刺進每一具身體內。$B$B牠們先拿下了日帆，下一個是誰都還不知道呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
