INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8403, 'zhTW', '無止盡行進到死亡之痕，削減無心智的天譴軍團，花了一整天時間。不要浪費時間了，除非你是來幫忙的，否則我很享受現在的安寧不想被打擾。', '無止盡行進到死亡之痕，削減無心智的天譴軍團，花了一整天時間。不要浪費時間了，除非你是來幫忙的，否則我很享受現在的安寧不想被打擾。', '無止盡行進到死亡之痕，削減無心智的天災軍團，花了一整天時間。不要浪費時間了，除非你是來幫忙的，否則我很享受現在的安寧不想被打擾。', '無止盡行進到死亡之痕，削減無心智的天譴軍團，花了一整天時間。不要浪費時間了，除非你是來幫忙的，否則我很享受現在的安寧不想被打擾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
