INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8408, 'zhTW', '那些汙穢的野獸充斥此地。$B$B如果你喜歡在戶外狩獵的話，你可以在病木林跟恐懼谷尋獲牠們大部分的蹤跡，也請特別留意惡蛛隧道。牠們也可能出沒在東瘟疫之地的天譴軍團紮營處。$B$B假如你熱衷於地城，你在斯坦索姆會發現更多牠們的蹤影，另外，在通靈學院可以找到一些通靈魔。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8409 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8409, 'zhTW', '你是笨蛋嗎?遺失了你回程時那堆散亂路旁的骷髏類生物?<洛漢嘆氣。>$B$B如果你是戶外型的人，你可在東、西瘟疫之地找到骷髏生物。相信我，你不能搞丟牠們－如果他們可以的話，他們一定不會放過你。倘若你是地城冒險型，斯坦索姆和通靈學院正是尋找為骨頭碎片的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8410 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8410, 'zhTW', '今日的安寧地又是個美好且陰鬱的一天，你說是吧，$c?$B$B有需要我幫忙的地方嗎?', '今日的安寧地又是個美好且陰鬱的一天，你說是吧，$c?$B$B有需要我幫忙的地方嗎?', '今日的安寧地又是個美好且陰鬱的一天，你說是吧，$c?$b$b有需要我幫忙的地方嗎?', '今日的安寧地又是個美好且陰鬱的一天，你說是吧，$c?$B$B有需要我幫忙的地方嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8411 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8411, 'zhTW', '沒有什麼是比翱翔天空更自由的事，$c。有什麼需要我幫忙的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
