INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8421, 'zhTW', '我們辛多雷失守了這麼多老家園的土地真是可恥。我們一定能很快恢復元氣，然後從天譴軍團那奪回屬於我們的土地!', '我們辛多雷失守了這麼多老家園的土地真是可恥。我們一定能很快恢復元氣，然後從天譴軍團那奪回屬於我們的土地!', '我們辛多雷失守了這麼多老家園的土地真是可恥。我們一定能很快恢復元氣，然後從天災軍團那奪回屬於我們的土地!', '我們辛多雷失守了這麼多老家園的土地真是可恥。我們一定能很快恢復元氣，然後從天譴軍團那奪回屬於我們的土地!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
