INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8424, 'zhTW', '我一天多前就派遊俠沙裡莎往南去了營地，還有遊俠萊斯瓦林往西去安寧地!你都沒見到他們兩個嗎?你是被派回來的援軍嗎?', '我一天多前就派遊俠沙裡莎往南去了營地，還有遊俠萊斯瓦林往西去安寧地!你都沒見到他們兩個嗎?你是被派回來的援軍嗎?', NULL, '我一天多前就派遊俠沙裡莎往南去了營地，還有遊俠萊斯瓦林往西去安寧地!你都沒見到他們兩個嗎?你是被派回來的援軍嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
