INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8426, 'zhTW', '啊，$g英雄:女英雄;來了!好開心再見到你，$N!我相信你仍在消滅看到的天譴軍團吧?', '啊，$g英雄:女英雄;來了!好開心再見到你，$N!我相信你仍在消滅看到的天譴軍團吧?', '瞧，當世的英雄！很高興再次見到你，$N！一旦發現天災士兵，你是絕不會手下留情的，對嗎？', '啊，$g英雄:女英雄;來了!好開心再見到你，$N!我相信你仍在消滅看到的天譴軍團吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
