INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8433, 'zhTW', '歡迎來到安寧地，$c。很抱歉你發現了這樣的狀況。如你所見，我們有了些麻煩，不過被遺忘者，和他們的領導者希瓦娜斯·風行者，非常好心的在我們有需要的時候給予我們大量的援助。$B$B如果你能伸出援手請千萬不要猶豫。我們在面臨無數軍力對抗的時候會善用各種能獲得的協助。', '歡迎來到安寧地，$c。很抱歉你發現了這樣的狀況。如你所見，我們有了些麻煩，不過被遺忘者，和他們的領導者希瓦娜斯·風行者，非常好心的在我們有需要的時候給予我們大量的援助。$B$B如果你能伸出援手請千萬不要猶豫。我們在面臨無數軍力對抗的時候會善用各種能獲得的協助。', NULL, '歡迎來到安寧地，$c。很抱歉你發現了這樣的狀況。如你所見，我們有了些麻煩，不過被遺忘者，和他們的領導者希瓦娜斯·風行者，非常好心的在我們有需要的時候給予我們大量的援助。$B$B如果你能伸出援手請千萬不要猶豫。我們在面臨無數軍力對抗的時候會善用各種能獲得的協助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
