INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8455, 'zhTW', '我事情太多，時間根本不夠用，$r!拜託，別擋我路。$B$B萬一你被蛆蟲粘液跟腐爛食屍鬼感染的話，我有能力治療各種疾病。', '我事情太多，時間根本不夠用，$r!拜託，別擋我路。$B$B萬一你被蛆蟲粘液跟腐爛食屍鬼感染的話，我有能力治療各種疾病。', '我事情太多，時間根本不夠用，$r!拜託，別擋我路。$b$b萬一你被巨蛆跟腐爛食屍鬼感染的話，我有能力治療各種疾病。', '我事情太多，時間根本不夠用，$r!拜託，別擋我路。$B$B萬一你被蛆蟲粘液跟腐爛食屍鬼感染的話，我有能力治療各種疾病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8456 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8456, 'zhTW', '<當你將恢復藥劑倒入他嘴裡後血精靈很快恢復意識。>$B$B我欠你一命，$c。沒有你的幫忙，我就得屈服於天譴軍團的痛苦折磨了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8457 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8457, 'zhTW', '<血精靈倒在地上看起來變的很遲緩。>', '<血精靈倒在地上看起來變的很遲緩。>', '<血精靈倒在地上看起來變的很遲緩。>', '<血精靈倒在地上看起來變的很遲緩。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8458 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8458, 'zhTW', '你好，$r。我是辛多雷也是泛稱血精靈的憂日大使。我非常希望我們和部落的新聯結會使雙方互利。', '歡迎您, $r.  I am Ambassador Sunsorrow of the sin\'dorei, or blood elves as we are commonly known.  I have high hopes that this new bond between us and the Horde will be mutually beneficial.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8459 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8459, 'zhTW', '<女性被遺忘者蜷曲在地上，她的表情相當痛苦。她現在看起來沒辦法自己爬起來。>', '<女性被遺忘者蜷曲在地上，她的表情相當痛苦。她現在看起來沒辦法自己爬起來。>', '<女性被遺忘者蜷曲在地上，她的表情相當痛苦。她現在看起來沒辦法自己爬起來。>', '<女性被遺忘者蜷曲在地上，她的表情相當痛苦。她現在看起來沒辦法自己爬起來。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8460 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8460, 'zhTW', '啊……我的頭快痛死了。$B$B他們一定是派你來救我。他們拖了真夠久的!你知道他們對這裡的犯人都做了些什麼嗎?', '啊……我的頭快痛死了。$B$B他們一定是派你來救我。他們拖了真夠久的!你知道他們對這裡的犯人都做了些什麼嗎?', '啊啊啊……頭痛欲裂！\n肯定是他們派你來救我的。拖了太久了！你知道他們都對這裡的戰俘做了些什麼嗎？', '啊……我的頭快痛死了。$B$B他們一定是派你來救我。他們拖了真夠久的!你知道他們對這裡的犯人都做了些什麼嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8461 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8461, 'zhTW', '<血精靈毫無生氣地躺在桌上。雖然他還有呼吸，但他明顯地中了高效的鎮靜毒素。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8462 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8462, 'zhTW', '你好，$r。我是聽從高階執行官的建議來到這裡。我有信心只要我們團結一致就能打造一個前所未有的強大部落並消滅所有的天譴軍團威脅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8463 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8463, 'zhTW', '<當恢復藥劑開始生效瓦尼司激烈地咳嗽。>$B$B謝謝你救了我。我一定要立刻回到安寧地!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8464 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8464, 'zhTW', '從永歌森林三不五時吹來的風真讓我作嘔，你懂我的意思吧。', '從永歌森林三不五時吹來的風真讓我作嘔，你懂我的意思吧。', '從永歌森林三不五時吹來的風真讓我作嘔，你懂我的意思吧。', '從永歌森林三不五時吹來的風真讓我作嘔，你懂我的意思吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8466 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8466, 'zhTW', '如果你要和我說的是很重要的事，$c，或許找阿莉法娜奧絲夫人一起來聽會比較妥當。不過我警告你，她很忙碌所以你要等上好一陣子。', '如果你要和我說的是很重要的事，$c，或許找阿莉法娜奧絲夫人一起來聽會比較妥當。不過我警告你，她很忙碌所以你要等上好一陣子。', NULL, '如果你要和我說的是很重要的事，$c，或許找阿莉法娜奧絲夫人一起來聽會比較妥當。不過我警告你，她很忙碌所以你要等上好一陣子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8467 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8467, 'zhTW', '通常我不會允許你直接和我對談;確切的說，你應該請女士也來聽聽。不過，我的確是直接給了你一個任務，那麼我們到底需要談論什麼?', '通常我不會允許你直接和我對談;確切的說，你應該請女士也來聽聽。不過，我的確是直接給了你一個任務，那麼我們到底需要談論什麼?', NULL, '通常我不會允許你直接和我對談;確切的說，你應該請女士也來聽聽。不過，我的確是直接給了你一個任務，那麼我們到底需要談論什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8468 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8468, 'zhTW', '$C，阿莉法娜奧絲夫人告訴我她對你在過去為我們做的一切感到很滿意。她希望你能繼續在鬼魂之地這裡做一個辛多雷的戰士。', '$C，阿莉法娜奧絲夫人告訴我她對你在過去為我們做的一切感到很滿意。她希望你能繼續在鬼魂之地這裡做一個辛多雷的戰士。', '$C，阿莉法娜奧絲夫人告訴我她對你在過去為我們做的一切感到很滿意。她希望你能繼續在鬼魂之地這裡做一個辛多雷的戰士。', '$C，阿莉法娜奧絲夫人告訴我她對你在過去為我們做的一切感到很滿意。她希望你能繼續在鬼魂之地這裡做一個辛多雷的戰士。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8469 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8469, 'zhTW', '這塊告示寫著許多宣佈事項和獎勵辦法。', '這塊告示寫著許多宣佈事項和獎勵辦法。', NULL, '這塊告示寫著許多宣佈事項和獎勵辦法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8470 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8470, 'zhTW', '我們有重要的工作要做，$N。讓我們在敵人的守衛失去警戒時攻擊他們。讓他們知道辛多雷的復仇從不會遺忘也不會原諒。', '我們有重要的工作要做，$N。讓我們在敵人的守衛失去警戒時攻擊他們。讓他們知道辛多雷的復仇從不會遺忘也不會原諒。', '我們有重要的工作要做，$N。讓我們在敵人的守衛失去警戒時攻擊他們。讓他們知道辛多雷的復仇從不會遺忘也不會原諒。', '我們有重要的工作要做，$N。讓我們在敵人的守衛失去警戒時攻擊他們。讓他們知道辛多雷的復仇從不會遺忘也不會原諒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8471 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8471, 'zhTW', '戰爭浪潮又再度襲來。巫妖王的亡域軍隊已經從寒冷的北方，包圍了我們的土地。他派出了飛行的亡域入侵全世界。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8472 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8472, 'zhTW', '這真是麻煩!礦坑充滿了討厭的豺狼人，我要怎麼幫博學者收集礦石樣本?', '這真是麻煩!礦坑充滿了討厭的豺狼人，我要怎麼幫博學者收集礦石樣本?', NULL, '這真是麻煩!礦坑充滿了討厭的豺狼人，我要怎麼幫博學者收集礦石樣本?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8474 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8474, 'zhTW', '她會在哪?我滿早以前就派我的學徒，莎夏莉雅去西邊的光底礦坑了。我們需要把那些礦石樣本帶回來，要快，否則我們的實驗就會失敗!', '她會在哪?我滿早以前就派我的學徒，莎夏莉雅去西邊的光底礦坑了。我們需要把那些礦石樣本帶回來，要快，否則我們的實驗就會失敗!', '她會在哪?我滿早以前就派我的學徒，莎夏莉雅去西邊的光底礦坑了。我們需要把那些礦石樣本帶回來，要快，否則我們的實驗就會失敗!', '她會在哪?我滿早以前就派我的學徒，莎夏莉雅去西邊的光底礦坑了。我們需要把那些礦石樣本帶回來，要快，否則我們的實驗就會失敗!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8475 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8475, 'zhTW', '如果沒有那個光底礦石，這樣的情況下，我們的研究一定會失敗。$B$B等莎夏莉雅回來這裡再說吧。我有一些有趣的任務要交給她，你可以相信我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8476 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8476, 'zhTW', '辛多雷在過去幾年已失去太多。我們的土地，我們的家園，甚至我們自己……$B$B是時候開始把一切奪回來了。', '辛多雷在過去幾年已失去太多。我們的土地，我們的家園，甚至我們自己……$B$B是時候開始把一切奪回來了。', NULL, '辛多雷在過去幾年已失去太多。我們的土地，我們的家園，甚至我們自己……$B$B是時候開始把一切奪回來了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8477 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8477, 'zhTW', '在我們戰勝像天譴軍團和阿曼尼這些外患之前，一定要先克服內憂。鄙惡者已經惹人厭夠久了，是時候消滅他們了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8478 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8478, 'zhTW', '你可以幫我離開這裡嗎?', '你可以幫我離開這裡嗎?', NULL, '你可以幫我離開這裡嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8479 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8479, 'zhTW', '在那幾張羊皮紙裡有核對清單和其他遠行者的資料，其中有一張特別搶眼。那是一張醜陋的食人妖素描，可能是你見過最可怕的生物!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8480 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8480, 'zhTW', '的確，冬泉谷山丘一帶正嘗試要抵擋重生的天譴軍團攻擊。你的幫忙對他們來說很重要。$B$B剩餘的亡域:$2284W', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8481 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8481, 'zhTW', '這地方目前暫時脫離天譴軍團的威脅了。我擔心他們很快又要回來了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8482 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8482, 'zhTW', '天譴軍團好像到了塔納利斯。他們眾多的亡域和其他軍隊都在那裡被殺了。$B$B剩餘的亡域:$2283W', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8483 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8483, 'zhTW', '天譴軍團的入侵在詛咒之地日益加大。每個健全的戰士都要挺身而出阻擋他們的入侵。$B$B剩餘的亡域:$2280W', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8484 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8484, 'zhTW', '如果援軍不能及時趕到燃燒平原，我怕天譴軍團會在那裡建立指揮基地。如果你可以，就應該趕快到那邊協助防衛部隊。$B$B剩餘的亡域:$2281W', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8485 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8485, 'zhTW', '瞭解我們的敵人能有許多好處。把這件事情牢記在心，$N。$B$B我們對天譴軍團瞭解得越多，我們越能夠擊敗他們。', '瞭解我們的敵人能有許多好處。把這件事情牢記在心，$N。$B$B我們對天譴軍團瞭解得越多，我們越能夠擊敗他們。', '對付天災軍團沒有那麼糟，$N。只要其它一些博學者能減輕一點負擔，事情就會可以掌控。', '瞭解我們的敵人能有許多好處。把這件事情牢記在心，$N。$B$B我們對天譴軍團瞭解得越多，我們越能夠擊敗他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8486 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8486, 'zhTW', '天譴軍團正在攻擊地區設定火力點，接收橫跨天際的亡域的通訊協助，和其他方面的軍援，我們知道，將他們根除的方法就是殺掉所有地面基地的軍力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8487 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8487, 'zhTW', '歡迎在旅行者營地停留，你想待多久都可以，$c。我們歡迎任何幫助我們在鬼魂之地努力的人。', '歡迎在旅行者營地停留，你想待多久都可以，$c。我們歡迎任何幫助我們在鬼魂之地努力的人。', '歡迎在旅行者營地停留，你想待多久都可以，$c。我們歡迎任何幫助我們在鬼魂之地努力的人。', '歡迎在遠行者營地停留，你想待多久都可以，$c。我們歡迎任何幫助我們在鬼魂之地努力的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
