INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8489, 'zhTW', '高階執行官是個很忙的人，$c。有什麼事我可以幫你嗎?', '高階執行官是個很忙的人，$c。有什麼事我可以幫你嗎?', '高階執行官是個很忙的人，$c。有什麼事我可以幫你嗎?', '高階執行官是個很忙的人，$c。有什麼事我可以幫你嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8490 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8490, 'zhTW', '你是我們的楷模，$N。在對付光底礦坑的豺狼人和阿曼尼地下墓穴的屍化食人妖之後，你對我們的敵人擊出了致命的一擊!$B$B$G做得好!:我們應該找個時間好好喝一杯，你覺得怎麼樣?;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8491 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8491, 'zhTW', '很高興再見到你，$g老兄!:美女!;我們合作愉快;$g下回再見。:我希望我們還有機會合作。;', '很高興再見到你，$g老兄!:美女!;我們合作愉快;$g下回再見。:我希望我們還有機會合作。', '很高興再見到你，$g老兄!:美女!;我們合作愉快;$g下回再見。:我希望我們還有機會合作。', '很高興再見到你，$g老兄!:美女!;我們合作愉快;$g下回再見。:我希望我們還有機會合作。;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8492 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8492, 'zhTW', '我聽說了希瓦娜斯女王知道你找回她項鍊後的反應。我仍然認為你做了對的事;別擔心希瓦娜斯的反應。$B$B那麼，說說你今天來此的目的吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8493 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8493, 'zhTW', '我能說什麼，$c?你是個真正的$g英雄:女英雄;!你不僅個人救了我許多的遊俠，還幫助我們對影松食人妖擊出致命一擊。你確定你不要留下來成為我手下的遠行者之一嗎?$B$B再見了，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8494 AND `Locale` = 'zhTW';
