INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8548, 'zhTW', '達克汗認為我們會還沒開戰就被天譴軍團給擊敗。我們一定要讓他知道他是錯的，$N。', '達克汗認為我們會還沒開戰就被天譴軍團給擊敗。我們一定要讓他知道他是錯的，$N。', '達克汗認為我們會還沒開戰就被天災軍團給擊敗。我們一定要讓他知道他是錯的，$N。', '達克汗認為我們會還沒開戰就被天譴軍團給擊敗。我們一定要讓他知道他是錯的，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8549 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8549, 'zhTW', '你沒看到我正在和這位小姐說話嗎?喔，非常好，反正她看起來有點忙。$B$B我只賣最好的酒，國外和國內的葡萄酒都有。要看一看嗎?', '沒瞧見我正準備跟這位女士講話嗎？哦，好吧，她似乎很忙。我出售來自本土和異域的葡萄酒。要看看嗎？', '沒瞧見我正準備跟這位女士講話嗎？哦，好吧，她似乎很忙。我出售來自本土和異域的葡萄酒。要看看嗎？', '你沒看到我正在和這位小姐說話嗎?喔，非常好，反正她看起來有點忙。$B$B我只賣最好的酒，國外和國內的葡萄酒都有。要看一看嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8550 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8550, 'zhTW', '那是薩瑟裡避難所的清單嗎?沒問題，他的身分地位可以獲得一瓶最好的酒。當然，任何薩瑟裡領主的朋友都可以特殊的價格買到這樣上好的葡萄酒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8551 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8551, 'zhTW', '我們贏了天譴軍團$2219W場戰役。做好準備，$N，這場戰爭要結束還差的遠了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8552 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8552, 'zhTW', '如果你有錢，我有讓你滿足口腹之慾的食物和飲料。所有的錢都會拿來讓這地方維持在最佳狀態。', '如果你有錢，我有讓你滿足口腹之慾的食物和飲料。所有的錢都會拿來讓這地方維持在最佳狀態。', '如果你有錢，我保證你對我提供的食品和飲料都很滿意，每個銅幣都物有所值！', '如果你有錢，我有讓你滿足口腹之慾的食物和飲料。所有的錢都會拿來讓這地方維持在最佳狀態。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8553 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8553, 'zhTW', '你手上的是薩瑟裡領主的清單嗎?好的，我可以賣給你一批開胃菜，剛出爐的。', '你手上的是薩瑟裡領主的清單嗎?好的，我可以賣給你一批開胃菜，剛出爐的。', '你手上的是薩瑟裡督軍的清單嗎?好的，我可以賣給你一批開胃菜，剛出爐的。', '你手上的是薩瑟裡領主的清單嗎?好的，我可以賣給你一批開胃菜，剛出爐的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8555 AND `Locale` = 'zhTW';
