INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8569, 'zhTW', '我們一定要時時保持高度警惕，$c!因為背叛者達克汗和他的天譴軍團夾攻，加上影松食人妖被祖阿曼的軍隊擊退，我們僅能勉強生存而已。我們實在不該分散注意力的!$B$B我衷心希望你能幫忙我們。', '我們一定要時時保持高度警惕，$c!因為背叛者達克汗和他的天譴軍團夾攻，加上影松食人妖被祖阿曼的軍隊擊退，我們僅能勉強生存而已。我們實在不該分散注意力的!$B$B我衷心希望你能幫忙我們。', NULL, '我們一定要時時保持高度警惕，$c!因為背叛者達克汗和他的天譴軍團夾攻，加上影松食人妖被祖阿曼的軍隊擊退，我們僅能勉強生存而已。我們實在不該分散注意力的!$B$B我衷心希望你能幫忙我們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
