INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8570, 'zhTW', '我很高興像你這樣的人來幫忙，$c。我們越快對付完這些食人妖，就能越快把天譴軍團趕回他們出生的地方。', '我很高興像你這樣的人來幫忙，$c。我們越快對付完這些食人妖，就能越快把天譴軍團趕回他們出生的地方。', NULL, '我很高興像你這樣的人來幫忙，$c。我們越快對付完這些食人妖，就能越快把天譴軍團趕回他們出生的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
