INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8571, 'zhTW', '已經對付完了一批食人妖，還有一批要繼續。你不知道我有多感激你的幫忙，$N!在你來到這裡之前我根本不相信我們能將影松的麻煩控制住。', '已經對付完了一批食人妖，還有一批要繼續。你不知道我有多感激你的幫忙，$N!在你來到這裡之前我根本不相信我們能將影松的麻煩控制住。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
