INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8572, 'zhTW', '我真是太感謝你了，$N!你不會相信我們最近在這裡遇到了哪些烏合之眾。他們帶來的不是想像中的幫助而是更多的麻煩。不像你。$B$B你確定你不想和遠行者簽約?', '我真是太感謝你了，$N!你不會相信我們最近在這裡遇到了哪些烏合之眾。他們帶來的不是想像中的幫助而是更多的麻煩。不像你。$B$B你確定你不想和遠行者簽約?', '你簡直無法想象最近我們都是和怎樣一群烏合之眾共同渡過的，大部分人簡直是來找麻煩而不是幫忙的，完全不像你那樣能幹。\n你確定你不想加入遠行者嗎？', '我真是太感謝你了，$N!你不會相信我們最近在這裡遇到了哪些烏合之眾。他們帶來的不是想像中的幫助而是更多的麻煩。不像你。$B$B你確定你不想和遠行者簽約?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8573 AND `Locale` = 'zhTW';
