INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8674, 'zhTW', '希望外域並不會像這個區域一樣全為貧瘠之地。這和永歌森林的翠綠草地和森林相比簡直是天壤之別。', '希望外域並不會像這個區域一樣全為貧瘠之地。這和永歌森林的翠綠草地和森林相比簡直是天壤之別。', '希望外域並不會像這個區域一樣全為貧瘠之地。這和永歌森林的翠綠草地和森林相比簡直是天壤之別。', '希望外域並不會像這個區域一樣全為貧瘠之地。這和永歌森林的翠綠草地和森林相比簡直是天壤之別。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8675 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8675, 'zhTW', '外域裡存在著比我們以前見過還強大很多的惡魔勢力。$B$B強大的力量應該給予那些不會畏懼的人，但能學著駕馭和控制它的力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8676 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8676, 'zhTW', '我在這裡出生的，$r。這是我的世界 - 就我所知...小時候，我的父母總是和我說你們世界的故事還有那裡的壯麗。我有多想離開這個地方啊。$B$B唉，命運是個殘酷的女人。我的父母很久前就過世了，葬在這個墓地。我仍維持著他們的榮耀和我家族的光榮 - 洛薩之子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8678 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8678, 'zhTW', '我能幫你什麼忙?', '我能幫你什麼忙?', '我能為你效勞嗎？', '我能幫你什麼忙?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8680 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8680, 'zhTW', '外域散發著魔法能量，就在那空氣中。你能感覺到嗎，$N?我想不到比這更適合我們種族的地方了。很快辛多雷就有自己的新土地了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8681 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8681, 'zhTW', '我的丈夫失蹤好幾天了。我們一起去朝聖，本來是要一起結束的。$B$B這樣的擔心讓我比平常更常汲取法力水晶。', '我的丈夫失蹤好幾天了。我們一起去朝聖，本來是要一起結束的。$B$B這樣的擔心讓我比平常更常汲取法力水晶。', '我的丈夫失蹤好幾天了。我們一起去朝聖，本來是要一起結束的。$b$b這樣的擔心讓我比平常更常汲取法力水晶。', '我的丈夫失蹤好幾天了。我們一起去朝聖，本來是要一起結束的。$B$B這樣的擔心讓我比平常更常汲取法力水晶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8682 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8682, 'zhTW', '如果有適當地照料，龍鷹是相當溫馴的。你不覺得這很棒嗎?如果好好撫養它們是如此的友善好相處，如果在野外生長又是如此的兇惡致命……我真是愛死它們了。', '如果有適當地照料，龍鷹是相當溫馴的。你不覺得這很棒嗎?如果好好撫養它們是如此的友善好相處，如果在野外生長又是如此的兇惡致命……我真是愛死它們了。', '如果有適當地照料，龍鷹是相當溫馴的。你不覺得這很棒嗎?如果好好撫養它們是如此的友善好相處，如果在野外生長又是如此的兇惡致命……我真是愛死它們了。', '如果有適當地照料，龍鷹是相當溫馴的。你不覺得這很棒嗎?如果好好撫養它們是如此的友善好相處，如果在野外生長又是如此的兇惡致命……我真是愛死它們了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8683 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8683, 'zhTW', '別...擔心...我...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8684 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8684, 'zhTW', '我不真的認為我們的情況有那麼糟。我確定一切會很快好轉，太陽之井的能量會恢復。它就是不可能像大家說的那樣糟。', '我不真的認為我們的情況有那麼糟。我確定一切會很快好轉，太陽之井的能量會恢復。它就是不可能像大家說的那樣糟。', '我不覺得我們的處境有這麼壞。我很確信一切都會很快得到糾正，太陽之井的能量也會恢復。事情不可能像大家所想的那樣壞。', '我不真的認為我們的情況有那麼糟。我確定一切會很快好轉，太陽之井的能量會恢復。它就是不可能像大家說的那樣糟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8685 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8685, 'zhTW', '和逐日者交朋友各有各的好處;我用只能在外域找到的實驗品來進行研究，而他們則獲得...我迷人的個性和粗獷的帥臉蛋。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8688 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8688, 'zhTW', '當我父親被派來這片荒地時我只是個嬰兒。所有我知道關於他的事都是別人告訴我的。$B$B你的夢會變嗎，$N?我的不會。我只有一個夢:一條赤紅的軍團地平線包圍著我，數量龐大無法計算，在遠處作戰。我在一個人的軀體前跪下，他大概就是我的父親，然後哭泣。當他喘著氣時，他的身體整個被壓碎，他虛弱的說著一些話。儘管我再怎麼努力;還是聽不到他要和我說的話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8698 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8698, 'zhTW', '你認為我對這個小人太殘忍了嗎?$B$B他們這個月已經殺了我手下兩個人!我們對這些鄙惡人渣太仁慈了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8699 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8699, 'zhTW', '歡迎來到晴風村。銀月城已經敗在我們手下了，但我們拒絕離開。這裡是我們的家。', '歡迎來到晴風村。銀月城已經敗在我們手下了，但我們拒絕離開。這裡是我們的家。', '歡迎來到晴風村。銀月城已經敗在我們手下了，但我們拒絕離開。這裡是我們的家。', '歡迎來到晴風村。銀月城已經敗在我們手下了，但我們拒絕離開。這裡是我們的家。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8700 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8700, 'zhTW', '我的工作包含一個任務也只是唯一的任務:確定西部聖所正常運作。$B$B你要原諒我脾氣這麼差但是，如你所見，這裡的狀況已經有點失控了。', '我的工作包含一個任務也只是唯一的任務:確定西部聖所正常運作。$B$B你要原諒我脾氣這麼差但是，如你所見，這裡的狀況已經有點失控了。', '我的工作包含一個任務也只是唯一的任務:確定西部聖所正常運作。\n\n你要原諒我脾氣這麼差但是，如你所見，這裡的狀況已經有點失控了。', '我的工作包含一個任務也只是唯一的任務:確定西部聖所正常運作。$B$B你要原諒我脾氣這麼差但是，如你所見，這裡的狀況已經有點失控了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8701 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8701, 'zhTW', '雙子帝王被殺之後，神廟裡的魔法防護阻礙傳送就大幅衰弱。如果你想的話，我可以將你傳送至帝王的巢穴。', '雙子帝王被殺之後，神廟裡的魔法防護阻礙傳送就大幅衰弱。如果你想的話，我可以將你傳送至帝王的巢穴。', '雙子皇帝被殺之後，神廟中能夠阻止傳送法陣的魔法護罩已經遠遠被削弱了。如果你願意，我可以將你直接傳送到雙子皇帝住所那裡去。', '雙子帝王被殺之後，神廟裡的魔法防護阻礙傳送就大幅衰弱。如果你想的話，我可以將你傳送到帝王的巢穴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8702 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8702, 'zhTW', '奧羅被殺後通往最後房間的路就顯而易見了。如果你想的話，我可以將你傳送至那裡。', '奧羅被殺後通往最後房間的路就顯而易見了。如果你想的話，我可以將你傳送至那裡。', '奧羅死後，通向最後那個密室的道路已經徹底暢通了。如果你願意的話，我可以把你傳送到那邊去。', '奧羅被殺後通往最後房間的路就顯而易見了。如果你想的話，我可以將你傳送到那裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8703 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8703, 'zhTW', '喜歡這個節慶嗎，$c?$B$B雖說火焰管理者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$B$B你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著...', '喜歡這個節慶嗎，$c?$B$B雖說火焰管理者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$B$B你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著...', '盡情在節慶上玩耍吧，$c?$b$b火焰管理者負責看管目前的火焰，而我則算是個歷史學家，儲存著過去的節慶內容。當然，我也會記錄今年的節慶活動。目前一切進展的都很順利，你不覺得嗎?$b$b你知道，$n，這個節慶是從火焰之王的火焰在敵人領土中心被偷走後開始的。重複這項功績不會引來更多的注意，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著……', '喜歡這個節慶嗎，$c?$B$B雖說火焰管理者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$B$B你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8712 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8712, 'zhTW', '如果你在找工作，$C，拿起一個工具開始挖吧。這裡所見都是廢墟!', '如果你在找活幹的話，$c，拿起鋤頭去挖吧。你沒看到那邊有一大堆廢墟麼？', '如果你在找活幹的話，$c，拿起鋤頭去挖吧。你沒看到那邊有一大堆廢墟麼？', '如果你在找工作，$C，拿起一個工具開始挖吧。這裡所見都是廢墟!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
