INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8713, 'zhTW', '你好，$N。我親愛的洛薩之子，我困在這個悲慘的世界已經接近二十年了。我們盡力做到最好，但我們過去失敗的陰影威脅今日依舊令人感到震驚。$B$B或許你願意幫助我們改正它?', '你好，$N。我親愛的洛薩之子，我困在這個悲慘的世界已經接近二十年了。我們盡力做到最好，但我們過去失敗的陰影威脅今日依舊令人感到震驚。$B$B或許你願意幫助我們改正它?', '有戰場元帥和他的軍隊到來，我們終於可以期待完成任務了。這是洛薩之子驕傲的一天，$C。', '有戰場元帥和他的軍隊到來，我們終於可以期待完成任務了。這是洛薩之子驕傲的一天，$C。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8715 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8715, 'zhTW', '外域的腐敗程度真的相當驚人，$c。塞納里奧議會想了解這土地的生物如何在這麼艱難的環境下生存。研究這塊破碎，受盡折磨的土地和它的居民，或許能教我們如何治療這生病的世界。', '外域的腐敗程度真的相當驚人，$c。塞納里奧議會想了解這土地的生物如何在這麼艱難的環境下生存。研究這塊破碎，受盡折磨的土地和它的居民，或許能教我們如何治療這生病的世界。', '外域的腐敗程度真的相當驚人，$c。塞納-馬恩省里奧議會想了解這土地的生物如何在這麼艱難的環境下生存。研究這塊破碎，受盡折磨的土地和它的居民，或許能教我們如何治療這生病的世界。', '外域的腐敗程度真的相當驚人，$c。塞納里奧議會想了解這土地的生物如何在這麼艱難的環境下生存。研究這塊破碎，受盡折磨的土地和它的居民，或許能教我們如何治療這生病的世界。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8716 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8716, 'zhTW', '外域的腐敗程度真的相當驚人，$c。塞納里奧遠征隊想了解這土地的生物如何在這麼艱難的環境下生存。研究這塊破碎，受盡折磨的土地和它的居民，或許能教我們如何治療這生病的世界。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
