INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8719, 'zhTW', '索爾瑪需要你，$c。大酋長需要你。準備好履行你的職責。', '薩爾瑪需要你，$c。酋長需要你。做好準備去完成你的職責吧。', '薩爾瑪需要你，$c。酋長需要你。做好準備去完成你的職責吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
