INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8756, 'zhTW', '我想我開始後悔參加這次朝聖了。我知道路途會很崎嶇而我對旅行也不陌生，但我並沒有料想到外域艱苦的環境。$B$B更重要的是，那個達勒利斯好像想在我還沒完全恢復我的力量時把我趕出這裡。', '我想我開始後悔參加這次朝聖了。我知道路途會很崎嶇而我對旅行也不陌生，但我並沒有料想到外域艱苦的環境。$B$B更重要的是，那個達勒利斯好像想在我還沒完全恢復我的力量時把我趕出這裡。', '我想我已經開始後悔來進行這次朝聖了。我知道路途會很艱辛，而且我也並不是一個遠行的新手，但我沒有準備好面對外域的困難。\n最主要的是，那個塔雷里斯似乎想要在我完全恢復力量之前把我趕出這裡。', '我想我開始後悔參加這次朝聖了。我知道路途會很崎嶇而我對旅行也不陌生，但我並沒有料想到外域艱苦的環境。$B$B更重要的是，那個達勒利斯好像想在我還沒完全恢復我的力量時把我趕出這裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8759 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8759, 'zhTW', '喔……我認識你嗎 ?', '喔……我認識你嗎 ?', '喔……我認識你嗎 ?', '喔……我認識你嗎 ?', '喔……我認識你嗎 ?', '喔……我認識你嗎 ?', '喔……我認識你嗎 ?', '喔……我認識你嗎 ?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
