INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8760, 'zhTW', '嗨，$N!派對好玩嗎?', '嗨，$N!派對好玩嗎?', '嗨，$N!派對好玩嗎?', '嗨，$N!派對好玩嗎?', '嗨，$N!派對好玩嗎?', '嗨，$N!派對好玩嗎?', '嗨，$N!派對好玩嗎?', '嗨，$N!派對好玩嗎?', '你應該試試泉爪開胃菜，他們好吃死了！', '你應該試試泉爪開胃菜，他們好吃死了！', '嗯……我認為今年的特殊美酒不怎麼特別。你同意嗎，$N?', '嗯……我認為今年的特殊美酒不怎麼特別。你同意嗎，$N?', '我聽說我們今晚都要去邊界觀看和天譴軍團的戰鬥。真棒！', '我聽說我們今晚都要去邊界觀看和天譴軍團的戰鬥。真棒！', '你相信那個艾莉薩·擊日者的膽量嗎?覺得她可以吸引到薩瑟裡領主的目光?你有看到她穿的衣服嗎?早就過時了。真悲哀，真的。', '你相信那個艾莉薩·擊日者的膽量嗎?覺得她可以吸引到薩瑟裡領主的目光?你有看到她穿的衣服嗎?早就過時了。真悲哀，真的。');
DELETE FROM `npc_text_locale` WHERE `ID` = 8761 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8761, 'zhTW', '啊……走開!', '啊……走開!', '啊……走開!', '啊……走開!', '啊……走開!', '啊……走開!', '啊……走開!', '啊……走開!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
