INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8767, 'zhTW', '我讓我自己成了一個笑柄。先知瑞卡酷試著警告我，但我的粗心最後還是讓我哉了個跟斗。$B$B我來這裡研究札斯可廢墟，但卻在路上與燃燒軍團發生衝突。現在，我所有的一切就是腿上一個討厭的傷口。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8768 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8768, 'zhTW', '雖然我無法提供你訓練，年輕的$c，但我可以給你我的祝福。勇敢地走進聖光裡!$B$B還有別的事嗎?', '雖然我無法提供你訓練，年輕的$c，但我可以給你我的祝福。勇敢地走進聖光裡!$B$B還有別的事嗎?', '雖然我無法提供你訓練，年輕的$c，但我可以給你我的祝福。勇敢地走進聖光裡!$b$b還有別的事嗎?', '雖然我無法提供你訓練，年輕的$c，但我可以給你我的祝福。勇敢地走進聖光裡!$B$B還有別的事嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8769 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8769, 'zhTW', '找出夜精靈在忙些什麼事對我們而言相當重要，$c! 請集中你們的精神直到找到結果。', '找出夜精靈在忙些什麼事對我們而言相當重要，$c! 請集中你們的精神直到找到結果。', NULL, '找出夜精靈在忙些什麼事對我們而言相當重要，$c! 請集中你們的精神直到找到結果。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
