INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8770, 'zhTW', '就在不久之前，此地才發生了一場慘烈的戰鬥。我們守望堡與銀色黎明抵抗著一波波從黑暗之門中湧出的惡魔。$B$B那些黑暗的日子，充滿的血腥與絕望...$B$B但是艾澤拉斯王國很快地加入我們，把那些怪物給逼退了!戰鬥持續在傳送門邊進行著...$B$B這個營地現在雖然很平靜，但我害怕此地的寧靜只是在掩飾著那座地獄之門後的狂暴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8771 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8771, 'zhTW', '英勇的托爾貝恩血統具有傳奇性。我崇拜他。$B$B找到他時要是活著的，就在外域...$B$B<洛摩斯注視著你經過。>$B$B當我第一次看到他時，我幾乎昏厥過去。難以阻擋的震驚力。當我跪在他面前，我必需勇敢面對。$B$B你能確信在我盡我能力完成某些事之後，洛薩之子能安全無虞。', '英勇的托爾貝恩血統具有傳奇性。我崇拜他。$B$B找到他時要是活著的，就在外域……$B$B<洛摩斯注視著你經過。>$B$B當我第一次看到他時，我幾乎昏厥過去。難以阻擋的震驚力。當我跪在他面前，我必需勇敢面對。$B$B你能確信在我盡我能力完成某些事之後，洛薩之子能安全無虞。', '英勇的托爾貝恩血統具有傳奇性。我崇拜他。$B$B找到他時要是活著的，就在外域……$B$B<洛摩斯注視著你經過。>$B$B當我第一次看到他時，我幾乎昏厥過去。難以阻擋的震驚力。當我跪在他面前，我必需勇敢面對。$B$B你能確信在我盡我能力完成某些事之後，洛薩之子能安全無虞。', '英勇的托爾貝恩血統具有傳奇性。我崇拜他。$B$B找到他時要是活著的，就在外域……$B$B<洛摩斯注視著你經過。>$B$B當我第一次看到他時，我幾乎昏厥過去。難以阻擋的震驚力。當我跪在他面前，我必需勇敢面對。$B$B你能確信在我盡我能力完成某些事之後，洛薩之子能安全無虞。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
