INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8772, 'zhTW', '洛摩斯通知我圍攻我美麗激流堡的噩耗。沒有任何適切的言語能訴說我聽聞羅德隆命運時的悲傷 - 以及我至愛的激流堡的命運。$B$B二十年前，根本沒有人聽過『燃燒軍團』…那些天殺該受詛咒的惡魔!$B$B儘量休息吧， $N; 要是我回到艾澤拉斯，激流堡將再次起義反戰。我發誓…', '洛姆斯把我的美麗城市所遭遇的悲劇告訴了我。在我聽到了洛丹倫的命運……還有我所深愛的激流堡的命運之後，我找不出什麼合適的語言來形容我的悲傷。\n\n二十年前，沒人聽說過“燃燒軍團”……那些該死的惡魔！\n好好休息，$N。等到我再回到艾澤拉斯去的時候，我發誓，激流堡將再次崛起！', '洛姆斯把我的美麗城市所遭遇的悲劇告訴了我。在我聽到了洛丹倫的命運……還有我所深愛的激流堡的命運之後，我找不出什麼合適的語言來形容我的悲傷。\n\n二十年前，沒人聽說過“燃燒軍團”……那些該死的惡魔！\n好好休息，$N。等到我再回到艾澤拉斯去的時候，我發誓，激流堡將再次崛起！', '洛摩斯通知我圍攻我美麗激流堡的噩耗。沒有任何適切的言語能訴說我聽聞羅德隆命運時的悲傷 - 以及我至愛的激流堡的命運。$B$B二十年前，根本沒有人聽過‘燃燒軍團’…那些天殺該受詛咒的惡魔!$B$B儘量休息吧， $N; 要是我回到艾澤拉斯，激流堡將再次起義反戰。我發誓…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
