INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8855, 'zhTW', '歡迎，$N。我是藍卓·長射-黑色烈焰的管理者。也許在此之前你並沒有聽過黑色烈焰這個名詞。我一點都不驚訝，因為我們一向都保持低調。我們寧願避開……派系與種族之間的鬥爭。$B$B黑色烈焰專門提供錢所能買的到最好的娛樂服務，不論是難以尋找的寶物、決鬥場的戰鬥或者一擲千金的賭局。$B$B您想尋找哪一方面的刺激呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8856 AND `Locale` = 'zhTW';
