INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8862, 'zhTW', '我是個夜精靈，陌生人。雖然你對我的種族沒有任何瞭解，但我們對你和你的祖先卻相當清楚。你雖然不自稱埃雷達爾，但從外表看來，你們有很多共同點。$B$B你幫助了我的盟友，因此我很感激;但你目前的情況暫時是如履薄冰。或許時間久了，你就能解開我心中的疑慮和恐懼。', '我是個夜精靈，陌生人。雖然你對我的種族沒有任何瞭解，但我們對你和你的祖先卻相當清楚。你雖然不自稱埃雷達爾，但從外表看來，你們有很多共同點。$B$B你幫助了我的盟友，因此我很感激;但你目前的情況暫時是如履薄冰。或許時間久了，你就能解開我心中的疑慮和恐懼。', '我是個夜精靈，陌生人。雖然你對我的種族沒有任何瞭解，但我們對你和你的祖先卻相當清楚。你雖然不自稱埃雷達爾，但從外表看來，你們有很多共同點。$b$b你幫助了我的盟友，因此我很感激;但你目前的情況暫時是如履薄冰。或許時間久了，你就能解開我心中的疑慮和恐懼。', '我是個夜精靈，陌生人。雖然你對我的種族沒有任何瞭解，但我們對你和你的祖先卻相當清楚。你雖然不自稱埃雷達爾，但從外表看來，你們有很多共同點。$B$B你幫助了我的盟友，因此我很感激;但你目前的情況暫時是如履薄冰。或許時間久了，你就能解開我心中的疑慮和恐懼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
