INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8868, 'zhTW', '我是偉大之城鐵爐堡的阿達曼·鐵心。你們看我的制服應該猜到我曾是鐵爐堡精英守衛之一。是的，我是麥格尼的副手!至少在我退休之前都是。現在我都在研究考古學。這是個嗜好;加上我認為這是個見識世界的好方法!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
