INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8869, 'zhTW', '<科倫啜泣。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8870 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8870, 'zhTW', '我做了什麼讓神只們用這樣殘暴的行為抨擊我?失去了所有我珍愛的一切 - 不是死亡就是毀滅。森林裡的野獸帶走我身邊的家人。我的家園被夷平。我的船沉了。$B$B我是個一無所有的人，擱淺在一座破碎的島上。$B$B或許你是來這裡完成任務的?快點了結吧，我不會抵抗的。取我的性命吧，陌生人;我太懦弱不敢自己了斷。我的雙手顫抖...那把劍不會正中要害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8871 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8871, 'zhTW', '如果不是神只，那會是誰?是什麼造成了這樣的衝突?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8872 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8872, 'zhTW', '軍團?惡魔?他們追捕你?我的人民也被燃燒軍團追捕:黑暗大師將他們視為毀滅的目標。$B$B<科倫擦去眼淚。>$B$B這是我和家人多年前搬遷至此的原因。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8873 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8873, 'zhTW', '你好，$c。在夜精靈邀請德萊尼加入他們之前，這片林地是被遺忘的。$B$B卡多雷和這片土地關係密切，而我們德萊尼很榮幸他們要我們一起接下重新振作林歌神殿的任務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8874 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8874, 'zhTW', '很高興在這裡看到新面孔。我們的前哨很小而我們的敵人卻很多。我們被那些想摧毀我們的人給包圍:西邊的薩特，南方戰歌伐木營地的獸人和冥火嶺的惡魔。$B$B我們感激德萊尼答應加入我們保衛林歌神殿不受這些人的威脅。', '很高興在這裡看到新面孔。我們的前哨很小而我們的敵人卻很多。我們被那些想摧毀我們的人給包圍:西邊的薩特，南方戰歌伐木營地的獸人和冥火嶺的惡魔。$B$B我們感激德萊尼答應加入我們保衛林歌神殿不受這些人的威脅。', '很高興可以在這裡看到新面孔。我們的哨站很小，但卻有著大量的敵人。我們被那些企圖消滅我們的傢伙包圍著：西面的薩特，南面戰歌伐木營地的獸人，還有那些冥火嶺的惡魔。\n德萊尼人已經同意了我們的邀請，與我們一起加固林歌神殿，做好抵抗種種威脅的準備。', '很高興在這裡看到新面孔。我們的前哨很小而我們的敵人卻很多。我們被那些想摧毀我們的人給包圍:西邊的薩特，南方戰歌伐木營地的獸人，和冥火嶺的惡魔。$B$B我們感激德萊尼答應加入我們保衛林歌神殿不受這些人的威脅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8875 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8875, 'zhTW', '再次在林歌神殿這裡聽到其他人的聲音真好。我開始覺得好像我會是這片土地衰退腐敗前最後一個注視它們的卡多雷人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8876 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8876, 'zhTW', '你可以感覺到附近邪惡的氣息嗎，$c?By the Hand，它必須被淨化!$B$B惡魔毀了我們的家園，阿古斯。我絕對不允許它們出現在我們新的家園，艾澤拉斯!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8878 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8878, 'zhTW', '雖然你給南方的邪惡惡魔一次很大的教訓，但我仍感應到那個區域有麻煩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8880 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8880, 'zhTW', '有你和你的人民做盟友，我們決定留在這座島上重建家園。伊露恩祝福你，英雄。$B$B雖然悲傷依舊來來去去，我想我們會活下來的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8881 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8881, 'zhTW', '你是一個$r，對嗎?在這裡見到你讓我很振奮!我們可以利用所有能獲得的幫助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8883 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8883, 'zhTW', '要撲殺惡魔，$c。你有那個膽量去做該做的事嗎?', '要撲殺惡魔，$c。你有那個膽量去做該做的事嗎?', '要撲殺惡魔，$c。你有那個膽量去做該做的事嗎?', '要撲殺惡魔，$c。你有那個膽量去做該做的事嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8887 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8887, 'zhTW', '只要殺死足夠的惡魔，燃燒軍團就會考慮是否要再次攻擊我們的伐木場。不過，我仍然感受到惡魔的禍害不斷騷動著。', '只要殺死足夠的惡魔，燃燒軍團就會考慮是否要再次攻擊我們的伐木場。不過，我仍然感受到惡魔的禍害不斷騷動著。', '只要殺死足夠的惡魔，燃燒軍團就會考慮是否要再次攻擊我們的伐木場。不過，我仍然感受到惡魔的禍害不斷騷動著。', '只要殺死足夠的惡魔，燃燒軍團就會考慮是否要再次攻擊我們的伐木場。不過，我仍然感受到惡魔的禍害不斷騷動著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8892 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8892, 'zhTW', '大家為崇高的英雄喝采!', NULL, '大家為崇高的英雄喝采!', NULL, '大家為崇高的英雄喝采!', NULL, '大家為崇高的英雄喝采!', NULL, '我們很幸運能從這次的磨難中存活下來。如果不是你，島上所有的人可能都被殺了！', NULL, '不知道他們還有多少人藏在我們之中。我認識火花好幾年了 - 從沒想過他竟是個叛徒。', NULL, NULL, NULL, NULL, NULL);
