INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8961, 'zhTW', '怎麼啦，$T小子:女孩;?你想找媽咪?嗯很抱歉。或許你該前往索爾瑪官員的俱樂部去把她找回來?', NULL, '怎麼啦，$T小子:女孩;?你想找媽咪?嗯很抱歉。或許你該前往索爾瑪官員的俱樂部去把她找回來?', NULL, '怎麼啦，$T小子:女孩;?你想找媽咪?嗯很抱歉。或許你該前往索爾瑪官員的俱樂部去把她找回來?', NULL, '怎麼啦，$T小子:女孩;?你想找媽咪?嗯很抱歉。或許你該前往索爾瑪官員的俱樂部去把她找回來?', NULL, '你的主要故障是什麼?!', NULL, '我已經看到你周圍的歡呼。你為什麼不幫我們所有人一個忙,僅僅是把齒輪放在軍械庫?', NULL, '誰叫庫德蘭讓你穿越黑暗之門?', NULL, '好，好，好，我們這裡有什麼？一個$T 平民：平民；？不，寶貝？你會從我這裡得到非特殊的對待！!', NULL);
