INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8969, 'zhTW', '是時候讓公會派一些新血給我們了!可惜你大老遠趕來卻落空。我們不能讓賓客看秀，你相信嗎?摩洛禁止我們演出新秀，我的贊助者都瘋了!一定要對摩洛做些什麼才行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
