INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9124, 'zhTW', '不要浪費我的時間。你想要什麼?', '不要浪費我的時間。你想要什麼?', '不要浪費我的時間。你想要什麼?', '不要浪費我的時間。你想要什麼?', '不要浪費我的時間。你想要什麼?', '不要浪費我的時間。你想要什麼?', '不要浪費我的時間。你想要什麼?', '不要浪費我的時間。你想要什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9125 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9125, 'zhTW', '被獵人當做寵物來養是多麼難為情的一件事!$B$B你救了我一命，但拜託你，麻煩不要再幹擾我的幸福了。既然你已從莫斯萊克那裡釋放了我，我就能自己找到生路。或許我還會順道碰上瑞吉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9127 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9127, 'zhTW', '願聖光屈服在你努力的意志之下。', '願聖光屈服在你努力的意志之下。', '願聖光屈服在你努力的意志之下。', '願聖光屈服在你努力的意志之下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9128 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9128, 'zhTW', '自然中的所有事物都是息息相關的;這是生態。如果我們小心點不要打擾了它，單純的觀察，或許能幸運地拼湊出我們身邊各種生物間複雜的關係。$B$B一旦我們有了這樣的共識，就可以採取適當的行動來確保所有生物的安康。沒有這樣的認知卻硬是介入，就絕對會造成毀滅。$B$B我是來這裡觀察孢子人和泥沼領主間複雜的互動。', '自然中的所有事物都是息息相關的;這是生態。如果我們小心點不要打擾了它，單純的觀察，或許能幸運地拼湊出我們身邊各種生物間複雜的關係。$B$B一旦我們有了這樣的共識，就可以採取適當的行動來確保所有生物的安康。沒有這樣的認知卻硬是介入，就絕對會造成毀滅。$B$B我是來這裡觀察孢子人和泥沼領主間複雜的互動。', '在大自然中存在的所有東西都有著相互的聯絡，這被稱作生態系統。如果我們小心地不去打擾它，透過簡單的觀察便可以瞭解到我們周圍不同的生物體之間的複雜關係。\n一旦我們理解了這些，就可以採取適當的行動來保證所有生物的生存。反之，在沒有這種認識的情況下去幹預的話，就會引起破壞。\n我在這裡觀察孢子人和沼澤領主之間的複雜關係。', '自然中的所有事物都是息息相關的;這是生態。如果我們小心點不要打擾了它，單純的觀察，或許能幸運地拼湊出我們身邊各種生物間複雜的關係。$B$B一旦我們有了這樣的共識，就可以採取適當的行動來確保所有生物的安康。沒有這樣的認知卻硬是介入，就絕對會造成毀滅。$B$B我是來這裡觀察孢子人和泥沼領主間複雜的互動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9130 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9130, 'zhTW', '<復仇者艾伊森向你致敬。>$B$B你和阿德密特斯談過了嗎?我想他在打聽你的下落。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9131 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9131, 'zhTW', '德魯伊保護我不受納迦和邪惡的失落者欺負，我教導他們認識沼澤的植物和動物做為回報。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
