INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9136, 'zhTW', '<被俘虜的太陽之鷹密探懷疑地看著你。>$B$B我從沒見過你。你是誰?', '<被俘虜的太陽之鷹密探懷疑地看著你。>$B$B我從沒見過你。你是誰?', '<被俘虜的太陽之鷹密探懷疑地看著你。>$b$b我從沒見過你。你是誰?', '<被俘虜的太陽之鷹密探懷疑地看著你。>$B$B我從沒見過你。你是誰?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9137 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9137, 'zhTW', '<被俘虜的太陽之鷹密探奸笑。>$B$B別擔心，新成員，還有更多傳送門控制器和更多適合的傳送地點。我相信賽羅娜斯很快就會有一個新的入口了。這些藍皮膚的狗在這世界活不久了。賽羅娜斯和憎恨會把太陽之鷹軍隊留下的所有事物都清理的一乾二淨。', '<被俘虜的太陽之鷹密探奸笑。>$B$B別擔心，新成員，還有更多傳送門控制器和更多適合的傳送地點。我相信賽羅娜斯很快就會有一個新的入口了。這些藍皮膚的狗在這世界活不久了。賽羅娜斯和憎恨會把太陽之鷹軍隊留下的所有事物都清理的一乾二淨。', '<被俘虜的太陽之鷹密探奸笑。>$b$b別擔心，新成員，還有更多傳送門控制器和更多適合的傳送地點。我相信賽羅娜斯很快就會有一個新的入口了。這些藍皮膚的狗在這世界活不久了。賽羅娜斯和憎恨會把太陽之鷹軍隊留下的所有事物都清理的一乾二淨。', '<被俘虜的太陽之鷹密探奸笑。>$B$B別擔心，新成員，還有更多傳送門控制器和更多適合的傳送地點。我相信賽羅娜斯很快就會有一個新的入口了。這些藍皮膚的狗在這世界活不久了。賽羅娜斯和憎恨會把太陽之鷹軍隊留下的所有事物都清理的一乾二淨。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9138 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9138, 'zhTW', '是賽羅娜斯的主意...憎恨其實是他們的一員。他是德萊尼軍事制度裡的一個高階成員:三頭政治還是什麼狗屁的。$B$B不管那是個什麼東西，他很龐大，強大，而且充滿了怒氣。只要憎恨在場，任何對旋繞導航器的攻擊大部分都會以失敗結尾。', '是賽羅娜斯的主意...憎恨其實是他們的一員。他是德萊尼軍事制度裡的一個高階成員:三頭政治還是什麼狗屁的。$B$B不管那是個什麼東西，他很龐大，強大，而且充滿了怒氣。只要憎恨在場，任何對旋繞導航器的攻擊大部分都會以失敗結尾。', '是賽羅娜斯的主意……憎恨其實是他們的一員。他是德萊尼軍事制度裡的一個高階成員:三頭政治還是什麼狗屁的。$b$b不管那是個什麼東西，他很龐大，強大，而且充滿了怒氣。只要憎恨在場，任何對旋繞導航器的攻擊大部分都會以失敗結尾。', '是賽羅娜斯的主意……憎恨其實是他們的一員。他是德萊尼軍事制度裡的一個高階成員:三頭政治還是什麼狗屁的。$B$B不管那是個什麼東西，他很龐大，強大，而且充滿了怒氣。只要憎恨在場，任何對旋繞導航器的攻擊大部分都會以失敗結尾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9139 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9139, 'zhTW', '賽羅娜斯聲稱某些埃雷達爾擁有將他人從原本的種族轉變為曼那瑞的能力。德萊尼原本應是埃雷達爾的一份子而賽羅娜斯則是一個強大的埃雷達爾。$B$B<密探笑著。>$B$B你相信嗎?這些可悲的生物都曾是強大的惡魔。什麼樣的笨蛋會拒絕這樣的力量?', '賽羅娜斯聲稱某些埃雷達爾擁有將他人從原本的種族轉變為曼那瑞的能力。德萊尼原本應是埃雷達爾的一份子而賽羅娜斯則是一個強大的埃雷達爾。$B$B<密探笑著。>$B$B你相信嗎?這些可悲的生物都曾是強大的惡魔。什麼樣的笨蛋會拒絕這樣的力量?', '賽羅娜斯聲稱某些埃雷達爾擁有將他人從原本的種族轉變為曼那瑞的能力。德萊尼原本應是埃雷達爾的一份子而賽羅娜斯則是一個強大的埃雷達爾。$b$b<密探笑著。>$b$b你相信嗎?這些可悲的生物都曾是強大的惡魔。什麼樣的笨蛋會拒絕這樣的力量?', '賽羅娜斯聲稱某些埃雷達爾擁有將他人從原本的種族轉變為曼那瑞的能力。德萊尼原本應是埃雷達爾的一份子而賽羅娜斯則是一個強大的埃雷達爾。$B$B<密探笑著。>$B$B你相信嗎?這些可悲的生物都曾是強大的惡魔。什麼樣的笨蛋會拒絕這樣的力量?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9140 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9140, 'zhTW', '很明顯。不然她要怎麼滲入他們的階級並以一個德萊尼的身份透過?她和他們住在一起很長的一段時間。', '很明顯。不然她要怎麼滲入他們的階級並以一個德萊尼的身份透過?她和他們住在一起很長的一段時間。', '很明顯。不然她要怎麼滲入他們的階級並以一個德萊尼的身份透過?她和他們住在一起很長的一段時間。', '很明顯。不然她要怎麼滲入他們的階級並以一個德萊尼的身份透過?她和他們住在一起很長的一段時間。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9141 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9141, 'zhTW', '很多?它有兩個弱點:那棟建築物西邊和東邊的底部。嘿，等等。你怎麼會知道旋繞導航器的事?你不是說你在成形之前都被俘虜了嗎?', '很多?它有兩個弱點:那棟建築物西邊和東邊的底部。嘿，等等。你怎麼會知道旋繞導航器的事?你不是說你在成形之前都被俘虜了嗎?', '很多?它有兩個弱點:那棟建築物西邊和東邊的底部。嘿，等等。你怎麼會知道旋繞導航器的事?你不是說你在成形之前都被俘虜了嗎?', '很多?它有兩個弱點:那棟建築物西邊和東邊的底部。嘿，等等。你怎麼會知道旋繞導航器的事?你不是說你在成形之前都被俘虜了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9142 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9142, 'zhTW', '是時候來摧毀旋繞導航器了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9143 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9143, 'zhTW', '我正耐心地等待命令，$c。', '我正耐心地等待命令，$c。', '我正耐心地等待命令，$c。', '我正耐心地等待命令，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9144 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9144, 'zhTW', '粗野的干擾已結束，如我所說，奎克米瑞已經接近了!$B$B依先前允諾的，我可以用一個魔法恩賜增強你的力量，幫助你與他對抗。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9145 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9145, 'zhTW', '[操著不流利的普通語]是時候慶祝我們做的事了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9146 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9146, 'zhTW', '允諾者，你記得我們嗎?你還記得克茲的預言嗎?這一刻是早就註定的了。你已做了這個世界要你做的。$B$B<大酋長靜松在你面前鞠躬。>$B$B德萊尼將會永遠受我的人民愛戴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9149 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9149, 'zhTW', '你走了很長一段路，$N。真的是很辛苦...但我知道你註定要成就偉大的事業。我們都知道。全體向$N敬禮!$B$B再次謝謝你解決了我們的地精問題...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9152 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9152, 'zhTW', '你或許不記得我，但你救了我一命。我最近才康復到可以自己走路。$B$B我想謝謝你為我做的一切併為我說過的話道歉...謝謝你，$N。願伊露恩永遠守護著你。', '你或許不記得我，但你救了我一命。我最近才康復到可以自己走路。$B$B我想謝謝你為我做的一切併為我說過的話道歉...謝謝你，$N。願伊露恩永遠守護著你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9154 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9154, 'zhTW', '為了世界我不會錯過的，$N。$B$B<主教米奈奧斯擁抱你。>$B$B我們以你為傲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9156 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9156, 'zhTW', '再次見到你真好，$N。我帶了一個朋友和我一起。她真的很想見你。\n\n<凱索笑著。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9159 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9159, 'zhTW', '我會越過無盡之海來看你。我們永遠不會忘記你為我們做的事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9160 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9160, 'zhTW', '我想再次感謝你為我所做的一切。你給了我勇氣從森林裡的野獸手裡奪回我的家園。同時，我還找到了麥格文!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9162 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9162, 'zhTW', '德萊尼的勇士就走在我們之中。這是個藍謎島和血謎島救星的慶祝活動!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9163 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9163, 'zhTW', '這全都是給你的，$N。你做到了。你救了所有這些人們和幾千幾萬的生命。$B$B你在這世界的衝突和悲劇之上興起，將我們和你一起提升。$B$B你做了這麼多 - 比許多人十輩子可以做的還要多 - 但你的生命才剛開始。真希望我們有幾千個像你一樣的英雄。$B$B但聽好了，$N。你的命運在外域。我在幻境中看過一個未透露的預言。$B$B找到我們的人民，$N。找到他們並把他們帶回家...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9166 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9166, 'zhTW', '我們不能讓我們的守衛倒下，$c。這個世界充滿了燃燒軍團的密探和盟友。如果你遇到任何奇怪的事，立刻向我報備。', '我們不能讓我們的守衛倒下，$c。這個世界充滿了燃燒軍團的密探和盟友。如果你遇到任何奇怪的事，立刻向我報備。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9167 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9167, 'zhTW', '伊斯歐認為一些敵方對手會對外域展開突擊。這就是為什麼我們看守者也來到這裡的原因。$B$B我們從未想過我們的對手會以納迦呈現過的力量或數量出現。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9168 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9168, 'zhTW', '我不知道你是誰，但歡迎你的到來。阿克蒙德和他的天譴軍隊隨時都有可能發動攻擊，$C。你會和我們站在同一陣線對抗這個惡魔嗎?', '我不知道你是誰，但歡迎你的到來。阿克蒙德和他的天譴軍隊隨時都有可能發動攻擊，$C。你會和我們站在同一陣線對抗這個惡魔嗎?', '我不知道你是誰，但是我歡迎你的到來。阿克蒙德和他的天災軍團隨時都有可能向我們進攻，$C。你會和我們一起面對這些惡魔嗎？', '我不知道你是誰，但歡迎你的到來。阿克蒙德和他的天譴軍隊隨時都有可能發動攻擊，$C。你會和我們站在同一陣線對抗這個惡魔嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9169 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9169, 'zhTW', '謝謝你，$R。現在做好準備。阿克蒙德就在邊界，我們一定要儘量拖延不可避免的一切。', '謝謝你，$R。現在做好準備。阿克蒙德就在邊界，我們一定要儘量拖延不可避免的一切。', '謝謝你，$c。好好準備一下。阿克蒙德正在行軍，我們必須儘可能在這裡堅守得更久一些。', '謝謝你，$R。現在做好準備。阿克蒙德就在邊界，我們一定要儘量拖延不可避免的一切。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9170 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9170, 'zhTW', '我們一定要盡力繼續撐下去!繼續奮鬥!', '我們一定要盡力繼續撐下去!繼續奮鬥!', '我們必須繼續守住這裡，越久越好！戰鬥到底！', '我們一定要盡力繼續撐下去!繼續奮鬥!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9172 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9172, 'zhTW', '我是血色守望防禦的領導者。我能幫你什麼忙嗎?', '我是血色守望防禦的領導者。我能幫你什麼忙嗎?', '我是血色守望防禦的領導者。我能幫你什麼忙嗎?', '我是血色守望防禦的領導者。我能幫你什麼忙嗎?', NULL, '我是血色守望防禦的領導者。我能幫你什麼忙嗎?', NULL, '我是血色守望防禦的領導者。我能幫你什麼忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9173 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9173, 'zhTW', '[操著不流利的普通語]靜松做好準備!非常感激!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9174 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9174, 'zhTW', '歡迎來到奎爾薩拉斯的防衛者，血騎士的總部，我們是銀月忠誠的僕人，也是聖光真正的主人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9176 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9176, 'zhTW', '大自然會幫助那些願意瞭解它的奧妙的人，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9177 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9177, 'zhTW', '自然是一種強大的力量，$r。那些想制服大自然的人從未永久成功過。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9179 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9179, 'zhTW', '你好，$N。', '你好，$N。', '你好，$N。', '你好，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9180 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9180, 'zhTW', '靈魂很不安，$r。在納葛蘭要小心你的四周，免得被他們的憤怒給吞噬了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
