DELETE FROM `npc_text_locale` WHERE `ID` = 9220 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9220, 'zhTW', '聽著$g小子:小姑娘;。我將遠征工作交給了我能幹的兒子。當你追蹤了艾澤拉斯上最棒的獵物，你就開始渴望更多東西。$B$B你有看到這裡的野獸的大小嗎?!$B$B我在這裡獵捕你所見過最危險的獵物。我是說抓到長牙並將她的心臟帶回去做為戰利品!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9221 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9221, 'zhTW', '$N!我對你的打獵本領印象深刻。你在荊棘谷的開始或許不太穩當，但你堅持到底，捕獲老邦加拉西成為最出色的人之一。$B$B但聽好了，$g小夥子:小姑娘;，外域的獵物是真的很難對付。我還有疤可以證明這點!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9225 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9225, 'zhTW', '普勞德摩爾女士的軍隊已奮力阻擋了阿克蒙德和他的燃燒軍團，而現在這個艱困的任務落到我們頭上。你準備好和我一起抵擋突擊了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9226 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9226, 'zhTW', '我謙遜地歡迎你來我們的神廟，靈魂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9227 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9227, 'zhTW', '和德萊尼那些在我們受苦的時候背叛我們的人協商?我不這麼想。$B$B一個真正的靈魂不會這樣對談!顯露出你的真面目吧，騙子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9228 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9228, 'zhTW', '然後讓軍團痛苦至極!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9229 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9229, 'zhTW', '所以我們要信任那些用欺騙來侮辱我們的人嗎?德萊尼那麼輕視我們所以他們必須使用奸計來引起我們的注意嗎?$B$B我們知道他們想「救贖」我們，但我的人民根本不想要他們的救贖。我們可以自己站起來而且我們追求的是驕傲，獨立的命運。把這個訊息帶給你的盟友。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9230 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9230, 'zhTW', '燃燒軍團緊逼我們，但我們的防禦還撐的住。我們每讓阿克蒙德遠離世界之樹一步就讓我們離勝利更近一步。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9231 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9231, 'zhTW', '很好。確定他們瞭解。$B$B現在，如果你能安靜的離開我的神廟我會非常感激。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9235 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9235, 'zhTW', '歡迎來到奧雷伯爾港，朋友。在這裡沒有什麼好怕的。我們是破碎者，但我們不是你的敵人。$B$B我是卡爾奈的伊庫堤，我們是一群想和德萊尼兄弟及他們新找到的盟友重新建立關係的破碎者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9236 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9236, 'zhTW', '瑪克吐沒有認出你來，$r，但他很高興見到你。如果你需要購買或修理護甲，別找別人，要找瑪克吐。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9237 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9237, 'zhTW', '這座神廟的回憶像一層厚厚的霧氣覆蓋了我的心靈，但我不能把它們拼湊成一個有條理的故事。這個地方曾對我而言有著某種意義。除非我可以重拾記憶，否則我會覺得一部分的自己不見了。$B$B或許德萊尼可以幫我想起我所遺忘的事情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9238 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9238, 'zhTW', '有些人可以叫我「提姆」，但對我朋友而言，我是「專家」。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9239 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9239, 'zhTW', '如果你要問，你根本不瞭解我，不足以使用那個稱號。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9240 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9240, 'zhTW', '你好，$c。你想將你的獵人本領發展到極限嗎?就是這裡了。$B$B赫米特·奈辛瓦里召集了這世界上有史以來最厲害的遠征隊。如果你敢的話就加入我們的狩獵旅行隊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9241 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9241, 'zhTW', '別被我們身邊這些廢墟搞糊塗了，$c。達拉然一如往常的強大。', '別被我們身邊這些廢墟搞糊塗了，$c。達拉然一如往常的強大。', '別被我們身邊這些廢墟搞糊塗了，$c。達拉然一如往常的強大。', '別被我們身邊這些廢墟搞糊塗了，$c。達拉然一如往常的強大。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9242 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9242, 'zhTW', '卡拉贊不只是個建築物，$N。如果你追溯橫跨艾澤拉斯的能量界線，你會發現它們都會合在那裡。$B$B<艾特羅斯指向哨塔下隱密的一點。>$B$B很棒，對吧?', NULL, '卡拉贊不只是個建築物，$N。如果你追溯橫跨艾澤拉斯的能量界線，你會發現它們都會合在那裡。$B$B<艾特羅斯指向哨塔下隱密的一點。>$B$B很棒，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9243 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9243, 'zhTW', '那魯比我們想像的還要聰明。過去五個月我從阿達歐那裡學到比我在達拉然圖書館那些年更多事情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9244 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9244, 'zhTW', '獎勵捕獲惡名昭彰的罪犯和邪惡的動物的懸賞就貼在這裡。現在就去追求這份賞金對你而言還太危險了，等你獲得了力量之後再來看這塊佈告。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9245 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9245, 'zhTW', '一條粗粗的紅色斜線被畫過佈告懸賞:死亡之爪。「此賞金由英勇的$N獲得，他征服了可怕的野獸」，還有更多內容以相同的紅色墨水寫著。', '一條粗粗的紅色斜線被畫過佈告懸賞:死亡之爪。“此賞金由英勇的$N獲得，他征服了可怕的野獸”，還有更多內容以相同的紅色墨水寫著。', '一條粗粗的紅色斜線被畫過佈告懸賞:死亡之爪。“此賞金由英勇的$N獲得，他征服了可怕的野獸”，還有更多內容以相同的紅色墨水寫著。', '一條粗粗的紅色斜線被畫過佈告懸賞:死亡之爪。“此賞金由英勇的$N獲得，他征服了可怕的野獸”，還有更多內容以相同的紅色墨水寫著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9246 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9246, 'zhTW', '這塊告示牌上有著各種佈告和懸賞告示。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9248 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9248, 'zhTW', '歡迎來到薩布拉金，$c。我是暗影獵人丹傑，這座前哨站的監督者，也是贊格沼澤的暗矛軍隊指揮官。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9249 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9249, 'zhTW', '現在你別想試圖逃跑小魚人!我有著像老鷹一樣的眼睛，像...像...像某種有強大能量動物的耳朵!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9250 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9250, 'zhTW', '巫醫托卡斯相信他可以在鳥的內臟裡或擲祖先的指關節骨來預測未來。真的，你所要做的就是詢問靈魂。但不要告訴他，$N。他很固執。', '巫醫托卡斯相信他可以在鳥的內臟裡或擲祖先的指關節骨來預測未來。真的，你所要做的就是詢問靈魂。但不要告訴他，$N。他很固執。', '托爾加什相信他可以透過鳥的腸子或者透過搖骨頭預測未來。但實際上，你所要做的就是詢問那些靈魂。不過別告訴他這些，$N。他是個很固執的傢伙。', '巫醫托卡斯相信他可以在鳥的內臟裡或擲祖先的指關節骨來預測未來。真的，你所要做的就是詢問靈魂。但不要告訴他，$N。他很固執。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9256 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9256, 'zhTW', '你已證明自己是個非常稱職的王牌獵人，$N。但仍有一隻野獸還縈繞在你夢中...長牙!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9257 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9257, 'zhTW', '你已捕獲他們全部了:巴奇洛爾，班薩爾，卡特瑞普，還有強大的長牙!你真的是我所認識最厲害的王牌獵人!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9258 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9258, 'zhTW', '我就在一塊多刺的矮樹叢裡打滾，和一隻塔巴克雄鹿正面交鋒，只有我銳利的小刀...<咳嗽>...和敏捷獵人的智力能救我。$B$B突然間一對兇猛的風翼貓頭鷹獵人從天而降朝我彈過來!他們懦弱的攻擊...<咳嗽>...完全幫不了他們自己。$B$B雖然我拿到他們的鳥喙做為戰利品，但我也在戰鬥過程中被刮傷感染。有點令人不快，我也承受了很大的痛苦，但我相信一兩天就會好了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9259 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9259, 'zhTW', '我第一次看到蘑菇長的比樹還要高，我不知道我是否可以稱這個地方為家。過了一陣子之後你就不再注意了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9260 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9260, 'zhTW', '在贊格沼澤別忘了花點時間去釣魚。你永遠不知道什麼時候還會看到水源。', '在贊格沼澤別忘了花點時間去釣魚。你永遠不知道什麼時候還會看到水源。', '不要忘記當你在贊加沼澤的時候花點時間釣魚。你從不知道什麼時候你會再次看到水。', '在贊格沼澤別忘了花點時間去釣魚。你永遠不知道什麼時候還會看到水源。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9261 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9261, 'zhTW', '泰倫多爾曾是德萊尼牧師和朝聖者的隱蔽休息處。牧師居民顯少接見訪客。$B$B當獸人開始攻擊德萊尼居民們，難民開始大批到來。隱士阿浩恩和其他人將泰倫多爾從神殿轉變為一個安全的避風港。許多德萊尼，包括我自己，都欠他一個人情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9262 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9262, 'zhTW', '泰倫多爾頂端的風景很壯觀，對吧?', '泰倫多爾頂端的風景很壯觀，對吧?', '在泰雷多爾頂部觀景真是華麗啊，難道不是嗎？', '泰倫多爾頂端的風景很壯觀，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9263 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9263, 'zhTW', '歡迎來到泰倫多爾，$c。如果你需要任何東西，請隨時來跟我要。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9264 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9264, 'zhTW', '我從沒見過一個地方有那麼多不同種類的蘑菇。如果有足夠的時間，我相信我可以找出它們所有的用途。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9265 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9265, 'zhTW', '泰倫多爾過去20年來經歷的改變比先前幾個世紀還要來的多。我不能抱怨，$N，因為世界那些時候改變更多。$B$B聖光為我帶來了身為隱居牧師不會有的朋友和同伴。在這裡學習過去帶給你的經驗。它會幫助你瞭解你的旅程將帶你去哪裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9267 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9267, 'zhTW', '暗影獵人丹傑派我和一支由建築商和戰士組成的小分遣隊來這裡建立這座前哨。我們才剛建好而他就已經開始向我們要報告了!$B$B如果你需要補給，我可以提供一些東西，但我們仍在等待第一批貨物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9268 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9268, 'zhTW', '如果你看到巫醫托卡斯就告訴他，他的混合物和符咒根本沒用!我完全照著他的話做，但瑪卡莎眼裡還是隻有祖瑞伊。$B$B不要相信那個假巫醫告訴你的任何話!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9269 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9269, 'zhTW', '瑞伏基擁有所有科多獸俱備的敏銳!有趣的是牠不認為自己很引人注目。我看過牠盯著我看的眼神，以為沒有人在看牠的樣子。$B$B牠讓我汗毛直豎，我多希望暗影獵人丹傑沒把牠送來和我們一起。設立斯溫派特崗哨時是個甩開牠的好時機。', '瑞伏基擁有所有科多獸俱備的敏銳!有趣的是牠不認為自己很引人注目。我看過牠盯著我看的眼神，以為沒有人在看牠的樣子。$B$B牠讓我汗毛直豎，我多希望暗影獵人丹傑沒把牠送來和我們一起。設立斯溫派特崗哨時是個甩開牠的好時機。', '瑞伏基擁有所有科多獸俱備的的敏銳!有趣的是它不認為自己很引人注目。我看過它盯著我看的眼神，以為沒有人在看它的樣子。$b$b它讓我汗毛直豎，我多希望暗影獵人丹傑沒把它送來和我們一起。設立斯溫帕特崗哨時是個甩開它的好時機。', '瑞伏基擁有所有科多獸俱備的敏銳!有趣的是它不認為自己很引人注目。我看過它盯著我看的眼神，以為沒有人在看它的樣子。$B$B它讓我汗毛直豎，我多希望暗影獵人丹傑沒把它送來和我們一起。設立斯溫派特崗哨時是個甩開它的好時機。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9270 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9270, 'zhTW', '哈羅，$c。我就是人們口中的破碎者。和失落者一樣，雖然我們不像他們那麼壞，但我們還是對邪惡能量十分頭痛，就是它把我們從原本的德萊尼形態轉變過來的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9271 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9271, 'zhTW', '卡拉達爾處於一團混亂中，陌生人。自從主母生病後，卡爾洛斯就得變的意氣消沉。他已經變的不像他爸爸的兒子了。$B$B<可庫許嘆氣。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9273 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9273, 'zhTW', '暗羽和血鱗部族的納迦領導者懸賞公告公佈在此。他們聽起來都相當可怕，或許你該等下再來看看。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9274 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9274, 'zhTW', '暗羽和血鱗部族的納迦領導者懸賞公告公佈在此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9275 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9275, 'zhTW', '他們死了。全部的人...$B$B當黑暗之血拿下我們，就有某種我無法理解的東西控制了我。告訴我，你曾感受過極大的憤怒，讓你整個人像在燃燒一樣嗎?一種讓生命都枯萎的高溫?一種焚化你血管的熱度?那就是我感受到的。$B$B<薩魯法爾的雙眼短暫地閃了一陣紅光。>$B$B我是最後一個活下來的人。他們30個人圍繞著我...黑暗之血...我只記得這個畫面。後來我眼前一黑，過了不知道多久才醒來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9276 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9276, 'zhTW', '黑暗時期隱約出現在前方，陌生人...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9277 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9277, 'zhTW', '靈魂都受到極大的煽動。我們一定要找出這次動亂的原因。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9283 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9283, 'zhTW', '赫米特是我所知道最出色的獵人。我們幾個月前偶然在艾澤拉斯的冬泉谷大廳巧遇過。我們在追蹤同一個獵物:一隻叫拉克西裡的巨豹。$B$B我們沒為了獵物打起來，而是對牠做了個賭注;誰收集到霜刃豹的皮革就可以要求對方某事。讓我永遠羞愧的是，這就是我如何得到我的綽號，費茲。$B$B我看起來像費茲嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9284 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9284, 'zhTW', '偉大的獵人，$N回來了。告訴我你最近追蹤獵物的故事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9286 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9286, 'zhTW', '對，對，我感覺好多了，但我還滿喜歡這裡的。', '對，對，我感覺好多了，但我還滿喜歡這裡的。', '對，對，我感覺好多了，但我還滿喜歡這裡的。', '對，對，我感覺好多了，但我還滿喜歡這裡的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9287 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9287, 'zhTW', '聯合團已經籌備這個計畫好幾個月了!我們想挖掘歐夏剛，這是一種被譽為宇宙中最大的鑽石。$B$B在我們要開始進行計畫的數分鐘前，奈薩斯王子哈拉瑪德傳話來命令我們在虛空風暴的一場政治衝突解決之前暫時按兵不動。我已經將我們的計畫轉變成目前暫時營運一個囤積走私寶石的貨倉，但這樣只會慢慢的吞噬我們的利潤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9288 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9288, 'zhTW', '吉札是來把工作做好的。我來確認這時候沒有人打擾他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9289 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9289, 'zhTW', '你知道我們是誰嗎，陌生人?我們是瑪格哈 - 咖啡色獸人，我聽過你們族人這樣稱呼我們。瑪格哈是生還者:一個墮落朝代的生還者;紅色帕斯的生還者;一個粉碎世界的生還者...$B$B我是喬林，基爾羅格之子;亡眼的最後一個後裔:血之谷氏族的酋長。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9290 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9290, 'zhTW', '如果赫米特在嘗試獵捕地面的獵物時可以避開穿過副翼的射擊，我們就不會墜毀了。$B$B不過別擔心，我會很快就把她修好的。', '如果赫米特在嘗試獵捕地面的獵物時可以避開穿過副翼的射擊，我們就不會墜毀了。$B$B不過別擔心，我會很快就把她修好的。', '如果赫米特在嘗試獵捕地面的獵物時可以避開穿過副翼的射擊，我們就不會墜毀了。$b$b不過別擔心，我會很快就把她修好的。', '如果赫米特在嘗試獵捕地面的獵物時可以避開穿過副翼的射擊，我們就不會墜毀了。$B$B不過別擔心，我會很快就把她修好的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
