INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9297, 'zhTW', '主母將我們撫養長大。你看到的任何瑪格哈利都因為主母而有他們生命動容的一面在。當她去世後我們會非常想念她的。', '主母將我們撫養長大。你看到的任何瑪格哈利都因為主母而有他們生命動容的一面在。當她去世後我們會非常想念她的。', '主母將我們撫養長大。你看到的任何瑪格哈利都因為主母而有他們生命動容的一面在。當她去世後我們會非常想念她的。', '主母將我們撫養長大。你看到的任何瑪格哈利都因為主母而有他們生命動容的一面在。當她去世後我們會非常想念她的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
