INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9315, 'zhTW', '堅強點。凱爾薩斯已經背叛我們了，我們所知了解的事物正在變化，不過不要失去信心。我們將會如同我們一直以來所做的，忍耐。當阿薩斯橫掃過我們的大陸時都沒能擊垮我們的精神，而凱爾薩斯也一樣。就讓這成為我們前進繁榮的未來所該學到的一課吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
