INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9328, 'zhTW', '遠行者廣場的血騎士好心地讓了他們大廳一個空間給伊利達，銀月城的武器大師。雖然她的訓練不便宜，但她的專業知識會讓你激賞的。', '遠行者廣場的血騎士好心地讓了他們大廳一個空間給伊利達，銀月城的武器大師。雖然她的訓練不便宜，但她的專業知識會讓你激賞的。', '遠行者廣場的血騎士慷慨地允許銀月城的武器大師伊蕾達使用他們的大廳。雖然她的訓練費用並不便宜，但是你會非常欣賞她的專業素養。', '遠行者廣場的血騎士好心地讓了他們大廳一個空間給伊利達，銀月城的武器大師。雖然她的訓練不便宜，但她的專業知識會讓你激賞的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
