INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9329, 'zhTW', '三個戰場軍官悠閒的在遠行者廣場裡休息，就在血騎士營地的大廳裡。雖然他們有些……粗野，但他們也有其可取之處。', '三個戰場軍官悠閒的在遠行者廣場裡休息，就在血騎士營地的大廳裡。雖然他們有些……粗野，但他們也有其可取之處。', '三個戰場軍官悠閒的在旅行者廣場裡休息，就在血騎士營地的大廳裡。雖然他們有些……粗野，但他們也有其可取之處。', '三個戰場軍官悠閒的在遠行者廣場裡休息，就在血騎士營地的大廳裡。雖然他們有些……粗野，但他們也有其可取之處。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
