INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9330, 'zhTW', '德魯伊的一員?我們的人民不走那條路的……但你很幸運。一個牛頭人女性 - 至少我認為她是個女性 - 已在長者步道的北方盡頭建立了一個有模有樣的居住地。她的名字叫海若妮·大地行者。', '德魯伊的一員?我們的人民不走那條路的……但你很幸運。一個牛頭人女性 - 至少我認為她是個女性 - 已在長者步道的北方盡頭建立了一個有模有樣的居住地。她的名字叫海若妮·大地行者。', '德魯伊之路？我們的人不會選擇這個……但是你很幸運。一個女性牛頭人——至少，我相信那是個女性——在長者步道的北面盡頭建了個住處。她叫哈雷尼·平原行者。', '德魯伊的一員?我們的人民不走那條路的……但你很幸運。一個牛頭人女性 - 至少我認為她是個女性 - 已在長者步道的北方盡頭建立了一個有模有樣的居住地。她的名字叫海若妮·大地行者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9331 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9331, 'zhTW', '你想追尋什麼道路?', '你想追尋什麼道路?', '你想追尋什麼道路?', '你想追尋什麼道路?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
