INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9332, 'zhTW', '喔。你在找他們……的一員啊。嗯，如果你真的想浪費時間和那些畏縮的人講話，你可以在遠行者廣場找到那些遊俠。席丹會照顧你。', '喔。你在找他們……的一員啊。嗯，如果你真的想浪費時間和那些畏縮的人講話，你可以在遠行者廣場找到那些遊俠。席丹會照顧你。', '哦，你在找……他們。好啊，如果你真的想浪費你的時間來和那些遲鈍的傢伙談話，可以在遠行者廣場裡面找到這些遊俠。桑迪恩會接待你的。', '喔。你在找他們……的一員啊。嗯，如果你真的想浪費時間和那些畏縮的人講話，你可以在遠行者廣場找到那些遊俠。席丹會照顧你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9333 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9333, 'zhTW', '啊，在尋找秘法大師嗎?你可以在日怒尖塔裡找到奎薩斯和其他博學者。', '啊，在尋找秘法大師嗎?你可以在日怒尖塔裡找到奎薩斯和其他博學者。', '啊，在尋找秘法大師嗎?你可以在日怒尖塔裡找到奎薩斯和其它博學者。', '啊，在尋找秘法大師嗎?你可以在日怒尖塔裡找到奎薩斯和其他博學者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
