INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9339, 'zhTW', '鏈金師在陽光庭院裡;你會找到坎伯朗，他會很樂意教你任何關於釀造藥水的事。', '鏈金師在陽光庭院裡;你會找到坎伯朗，他會很樂意教你任何關於釀造藥水的事。', '鍊金師們都在逐日王庭，你可以去找卡博隆，他會很熱情地教你一大堆關於製造藥水的知識。', '鍊金師在陽光庭院裡;你會找到坎伯朗，他會很樂意教你任何關於釀造藥水的事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
