INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9340, 'zhTW', '貝瑪倫在遠行者廣場教授鍛造的手藝。雖然它是個有點……髒的差事，但我想它還是有它的價值。', '貝瑪倫在遠行者廣場教授鍛造的手藝。雖然它是個有點……髒的差事，但我想它還是有它的價值。', '畢瑪霖在旅行者廣場教授鍛造的手藝。雖然它是個有點……髒的差事，但我想它還是有它的價值。', '貝瑪倫在遠行者廣場教授鍛造的手藝。雖然它是個有點……髒的差事，但我想它還是有它的價值。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
