INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9341, 'zhTW', '我想附魔師希丹娜目前正在招生。你可以在陽光庭院裡的一個凹室裡找到她。', '我想附魔師希丹娜目前正在招生。你可以在陽光庭院裡的一個凹室裡找到她。', '我相信附魔師瑟丹娜正在招收學生。你可以在逐日王庭的某個亭子裡面找到她。', '我想附魔師希丹娜目前正在招生。你可以在陽光庭院裡的一個凹室裡找到她。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9342 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9342, 'zhTW', '奇怪的選擇……但我想我不是該批判的那個人。丹威是你該去找的人;他的工程學小攤在去遠行者廣場的路上，陽光庭院附近。', '奇怪的選擇……但我想我不是該批判的那個人。丹威是你該去找的人;他的工程學小攤在去遠行者廣場的路上，陽光庭院附近。', '一個奇怪的選擇……但是我想這並不是我該評判的。你應該去找丹文，他的工程臺就在逐日王庭附近，通往遠行者廣場的那條路上。', '奇怪的選擇……但我想我不是該批判的那個人。丹威是你該去找的人;他的工程學小攤在去遠行者廣場的路上，陽光庭院附近。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9343 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9343, 'zhTW', '艾瑞斯塔是個擅長用……較混亂的方式治療傷口的專家。如果學習急救是你的目的，就去皇家市場入口附近的長者步道找他吧。', '艾瑞斯塔是個擅長用……較混亂的方式治療傷口的專家。如果學習急救是你的目的，就去皇家市場入口附近的長者步道找他吧。', '埃雷圖斯是個……處理各種傷口的大師。如果學習急救是你的目標，就去長者步道找他吧，他就在皇家貿易區的入口附近。', '艾瑞斯塔是個擅長用……較混亂的方式治療傷口的專家。如果學習急救是你的目的，就去皇家市場入口附近的長者步道找他吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9344 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9344, 'zhTW', '奎爾薩拉斯的水裡充滿了魚群;我想你也注意到了吧?崔森在釣魚手藝上相當有技巧，你可以在皇家交易所拍賣場旁的長者步道找到他。', '奎爾薩拉斯的水裡充滿了魚群;我想你也注意到了吧?崔森在釣魚手藝上相當有技巧，你可以在皇家交易所拍賣場旁的長者步道找到他。', '奎爾薩拉斯的水裡有著大量的魚，你從來都沒發現過嗎？德拉森對釣魚很有經驗，你可以在長者步道靠近皇家貿易區的地方找到他。', '奎爾薩拉斯的水裡充滿了魚群;我想你也注意到了吧?崔森在釣魚手藝上相當有技巧，你可以在皇家交易所拍賣場旁的長者步道找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9345 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9345, 'zhTW', '草藥師納德娜有雙銳利的雙眼可以尋找草藥，我想她應該會將她的智慧與你這種人分享。你可以在陽光庭院的凹室裡找到她和鏈金師們在一起。', '草藥師納德娜有雙銳利的雙眼可以尋找草藥，我想她應該會將她的智慧與你這種人分享。你可以在陽光庭院的凹室裡找到她和鏈金師們在一起。', '植物學家娜薩蘭有著一副尋找藥草的敏銳眼睛，我想她可能會把她的智慧傳授給像你這樣的傢伙吧。你可以在逐日王庭那裡的亭子中找到她和鍊金師們。', '草藥師納德娜有雙銳利的雙眼可以尋找草藥，我想她應該會將她的智慧與你這種人分享。你可以在陽光庭院的凹室裡找到她和鍊金師們在一起。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9346 AND `Locale` = 'zhTW';
