INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9347, 'zhTW', '在長者步道東南方盡頭，萊娜利斯設了一個很棒的制皮攤。她會訓練你……只要一點點代價。', '在長者步道東南方盡頭，萊娜利斯設了一個很棒的制皮攤。她會訓練你……只要一點點代價。', '沿著長者步道走到東南方的盡頭，萊納里斯在那裡開了一家制皮點。她會教你的，只要你肯付錢。', '在長者步道東南方盡頭，萊娜利斯設了一個很棒的制皮攤。她會訓練你……只要一點點代價。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
