INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9348, 'zhTW', '如果挖土是一種讓你享受的消遣，那就去遠行者廣場找貝利爾分享你瘋狂的興趣吧。我相信他會很高興看到不只他一個人有病的。', '如果挖土是一種讓你享受的消遣，那就去遠行者廣場找貝利爾分享你瘋狂的興趣吧。我相信他會很高興看到不只他一個人有病的。', '如果挖土是一種讓你享受的消遣，那就去旅行者廣場找比利分享你瘋狂的興趣吧。我相信他會很高興看到不只他一個人有病的。', '如果挖土是一種讓你享受的消遣，那就去遠行者廣場找貝利爾分享你瘋狂的興趣吧。我相信他會很高興看到不只他一個人有病的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
