INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9349, 'zhTW', '帝恩是個相當有天份的剝皮師;她製作的山貓毛皮是我見過最好的。如果你想向她學習，你可以在長者步道東南方的盡頭找到她。', '帝恩是個相當有天份的剝皮師;她製作的山貓毛皮是我見過最好的。如果你想向她學習，你可以在長者步道東南方的盡頭找到她。', '提恩是個很有天賦的剝皮師，她所生產的山貓皮是我見過的最好的東西。如果你想從她那裡學到點本事，可以在長者步道的東南盡頭找到她。', '帝恩是個相當有天份的剝皮師;她製作的山貓毛皮是我見過最好的。如果你想向她學習，你可以在長者步道東南方的盡頭找到她。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
