INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9350, 'zhTW', '裁縫奇蘭一直都在尋找更有好奇心的學生來傳授他微妙的手藝。他的店第一次會有點難找，但它就在商店街拍賣場的北邊。你會在建築物的較低層找到他。', '裁縫奇蘭一直都在尋找更有好奇心的學生來傳授他微妙的手藝。他的店第一次會有點難找，但它就在商店街拍賣場的北邊。你會在建築物的較低層找到他。', '裁縫基倫一直在尋找好奇的學生來傳授他那精巧的手藝。他的店有點不好找，就在花園街市的拍賣行的北面。你可以在那座建築的底層找到他。', '裁縫奇蘭一直都在尋找更有好奇心的學生來傳授他微妙的手藝。他的店第一次會有點難找，但它就在商店街拍賣場的北邊。你會在建築物的較低層找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
