INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9352, 'zhTW', '你為什麼要對浪普這麼壞?浪普只是肚子餓而已。', '為什麼你對拉普這麼粗暴？拉普只是餓了。', '為什麼你對拉普這麼粗暴？拉普只是餓了。', '你為什麼要對浪普這麼壞?浪普只是肚子餓而已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
