INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9354, 'zhTW', '石拳餓了!需要食物!戰槌巨魔部族把石拳踢出土堆到北邊去了。現在有更多的石拳要餵養。', '石拳氏族好餓！要吃東西！戰槌氏族把石拳氏族趕到了北面。石拳需要更多食物。', '石拳氏族好餓！要吃東西！戰槌氏族把石拳氏族趕到了北面。石拳需要更多食物。', '石拳餓了!需要食物!戰槌巨魔部族把石拳踢出土堆到北邊去了。現在有更多的石拳要餵養。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
