INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9367, 'zhTW', '<劍刃傳授者痛快地大笑。>$B$B你知道你現在在哪嗎，笨蛋?這是巨魔的地盤。在獸人之前，在德萊尼之前，還有巨魔。而你卻想發動一場必然會輸的戰爭?石拳會粉碎你的。如果石拳沒有毀滅你們，戰槌也會...$B$B我想你的領導者早就知道這點了...', '<劍刃傳授者痛快地大笑。>$b$b你知道你現在在哪嗎，笨蛋?這是巨魔的地盤。在獸人之前，在德萊尼之前，還有巨魔。而你卻想發動一場必然會輸的戰爭?石拳會粉碎你的。如果石拳沒有毀滅你們，戰錘也會……$b$b我想你的領導者早就知道這點了……', '<劍刃傳授者痛快地大笑。>$b$b你知道你現在在哪嗎，笨蛋?這是巨魔的地盤。在獸人之前，在德萊尼之前，還有巨魔。而你卻想發動一場必然會輸的戰爭·石拳會粉碎你的。如果石拳沒有毀滅你們，戰錘也會……$b$b我想你的領導者早就知道這點了……', '<劍刃傳授者痛快地大笑。>$B$B你知道你現在在哪嗎，笨蛋?這是巨魔的地盤。在獸人之前，在德萊尼之前，還有巨魔。而你卻想發動一場必然會輸的戰爭?石拳會粉碎你的。如果石拳沒有毀滅你們，戰槌也會……$B$B我想你的領導者早就知道這點了……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
