INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9368, 'zhTW', '<劍刃傳授者像是正看穿你一樣地注視著你。>$B$B或許還有別的辦法...我會同意你的領導者的要求，只要你照著我的話去做。$B$B有了你的幫助，我們或許可以幫對方一個大忙。', '<劍刃傳授者像是正看穿你一樣地注視著你。>$b$b或許還有別的辦法……我會同意你的領導者的要求，只要你照著我的話去做。$b$b有了你的幫助，我們或許可以幫對方一個大忙。', '<劍刃傳授者像是正看穿你一樣地注視著你。>$b$b或許還有別的辦法……我會同意你的領導者的要求，只要你照著我的話去做。$b$b有了你的幫助，我們或許可以幫對方一個大忙。', '<劍刃傳授者像是正看穿你一樣地注視著你。>$B$B或許還有別的辦法……我會同意你的領導者的要求，只要你照著我的話去做。$B$B有了你的幫助，我們或許可以幫對方一個大忙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
