INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9369, 'zhTW', '你要發動一系列活動讓吉爾索洛堡壘的吉爾索洛相信戰槌巨魔攻擊了他們的基地，再策劃另一系列活動讓戰槌巨魔相信吉爾索洛正要攻擊他們的基地。$B$B這樣做你就解決了我們的兩個麻煩。$B$B石拳將奪回他們的領土而你的人民將不再遭受石拳，戰槌，和吉爾索洛的攻擊。', '你要發動一系列活動讓吉爾索洛堡壘的吉爾索洛相信戰錘巨魔攻擊了他們的基地，再策劃另一系列活動讓戰錘巨魔相信吉爾索洛正要攻擊他們的基地。$b$b這樣做你就解決了我們的兩個麻煩。$b$b石拳將奪回他們的領土而你的人民將不再遭受石拳，戰錘，和吉爾索洛的攻擊。', '你要發動一系列活動讓吉爾索洛堡壘的吉爾索洛相信戰錘巨魔攻擊了他們的基地，再策劃另一系列活動讓戰錘巨魔相信吉爾索洛正要攻擊他們的基地。$b$b這樣做你就解決了我們的兩個麻煩。$b$b石拳將奪回他們的領土而你的人民將不再遭受石拳，戰錘，和吉爾索洛的攻擊。', '你要發動一系列活動讓吉爾索洛堡壘的吉爾索洛相信戰槌巨魔攻擊了他們的基地，再策劃另一系列活動讓戰槌巨魔相信吉爾索洛正要攻擊他們的基地。$B$B這樣做你就解決了我們的兩個麻煩。$B$B石拳將奪回他們的領土而你的人民將不再遭受石拳，戰槌，和吉爾索洛的攻擊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
