INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9383, 'zhTW', '你是誰?你想要什麼?', NULL, '你是誰?你想要什麼?', NULL, '你是誰?你想要什麼?', NULL, '你是誰?你想要什麼?', NULL, '大家都到哪裡去了?', NULL, '晚宴賓客應該表現更多尊重！', NULL, '喔，這裡真是個神聖的地方！', NULL, '把治療藥膏塗在我頭上。你喜歡我的刺棘皇冠嗎?', NULL);
