INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9387, 'zhTW', '太驚人了!你擊敗安納塞隆的事實讓阿克蒙德的目的受到延誤，也讓我們離勝利更近一步。不過，我的軍隊不能待在這裡。我和我的軍隊都筋疲力竭，現在是時候好好休息了。如果你的力量還夠，就前往東邊的索爾的營地。我們會在那裡再做停留。祝你好運。', '太驚人了!你擊敗安納塞隆的事實讓阿克蒙德的目的受到延誤，也讓我們離勝利更近一步。不過，我的軍隊不能待在這裡。我和我的軍隊都筋疲力竭，現在是時候好好休息了。如果你的力量還夠，就前往東邊的索爾的營地。我們會在那裡再做停留。祝你好運。', '太驚人了!你擊敗安納塞隆的事實讓阿克蒙德的目的受到延誤，也讓我們離勝利更近一步。不過，我的軍隊不能待在這裡。我和我的軍隊都筋疲力竭，現在是時候好好休息了。如果你的力量還夠，就前往東邊的索爾的營地。我們會在那裡再做停留。祝你好運。', '太驚人了!你擊敗安納塞隆的事實讓阿克蒙德的目的受到延誤，也讓我們離勝利更近一步。不過，我的軍隊不能待在這裡。我和我的軍隊都筋疲力竭，現在是時候好好休息了。如果你的力量還夠，就前往東邊的索爾的營地。我們會在那裡再做停留。祝你好運。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
