INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9408, 'zhTW', '我們非常感激你幫助我們對抗燃燒軍團。珍娜·普勞德摩爾在前線可能需要你的幫助。', '我們非常感激你幫助我們對抗燃燒軍團。珍娜·普勞德摩爾在前線可能需要你的幫助。', '我們非常感激你幫助我們對抗燃燒軍團。珍娜·普勞德摩爾在前線可能需要你的幫助。', '我們非常感激你幫助我們對抗燃燒軍團。珍娜·普勞德摩爾在前線可能需要你的幫助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
