INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9433, 'zhTW', '雙塔廢墟還沒落入我方的控制之中!我的命令是點燃兩座烽火臺，並且在該區域處於我方控制之下時傳送戰旗。去將那兩座烽火臺奪下!', '雙塔廢墟還沒有被佔領！我的命令是當這兩座燈塔都被點亮、並且整個區域都被佔領的時候發放軍旗。到那裡去控制燈塔吧！', '雙塔廢墟還沒有被佔領！我的命令是當這兩座燈塔都被點亮、並且整個區域都被佔領的時候發放軍旗。到那裡去控制燈塔吧！', '雙塔廢墟還沒落入我方的控制之中!我的命令是點燃兩座烽火臺，並且在該區域處於我方控制之下時傳送戰旗。去將那兩座烽火臺奪下!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9435 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9435, 'zhTW', '<沙薩拉畢恩對你咆哮，再回去喝他充滿泡沫的飲料。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
