INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9437, 'zhTW', '<守望者崔洛斯打趣的看著你然後停了一下，明顯地在掙扎>$B$B贊格沼澤……太接近真相了。$B$B<他的臉再次變得瘋狂。>$B$B他還在看嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9438 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9438, 'zhTW', '那是什麼?贊格沼澤?我為什麼會想去那裡?$B$B<崔洛斯看起來在沉思。>$B$B好，贊格沼澤……我們……那裡的德魯伊很快就會知道為什麼水平面一直在降低了。它在摧毀一切!$B$B<你可以在守望者的眼裡看見瘋狂錯亂的恐懼。>$B$B摧毀我們全部的人!刺眼的光芒!爆炸!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9439 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9439, 'zhTW', '血精靈……不知道為什麼他們就是想阻止我們。$B$B<守望者崔洛斯明顯地努力讓他的頭腦多保持清醒幾秒。>$B$B他們……他們派了一個破碎者當……當間諜……但他帶了一顆炸彈!$B$B他們死了，他們全都死了!他們試著逃跑!根本不知道有沒有倖存者。$B$B我一定是在爆炸的邊緣。那實在太可……它又在盯著我們看了!$B$B<崔洛斯變的很沮喪並直視你後方好像你不在那裡一樣。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9440 AND `Locale` = 'zhTW';
