INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9451, 'zhTW', '我的工作是照顧可些可憐的靈魂。我接受任何樂於幫助的人，不管他們是奧多爾或占卜者。$B$B我們人手很不足，如果有巨魔知道怎麼使用止血帶我也不會拒絕他的。我不太在意這個城市的政治傾向。', '我的工作是照顧可些可憐的靈魂。我接受任何樂於幫助的人，不管他們是奧多爾或占卜者。$B$B我們人手很不足，如果有巨魔知道怎麼使用止血帶我也不會拒絕他的。我不太在意這個城市的政治傾向。', '我的工作是照顧可些可憐的靈魂。我接受任何樂於幫助的人，不管他們是奧多爾或占卜者。$B$B我們人手很不足，如果有巨魔知道怎麼使用止血帶我也不會拒絕他的。我不太在意這個城市的政治傾向。', '我的工作是照顧可些可憐的靈魂。我接受任何樂於幫助的人，不管他們是奧多爾或占卜者。$B$B我們人手很不足，如果有巨魔知道怎麼使用止血帶我也不會拒絕他的。我不太在意這個城市的政治傾向。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9452 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9452, 'zhTW', '你相信嗎?這個以太族身上竟然連一個蜥蝪眼也沒有!$B$B他的領導者竟然還有臉自稱為「走私者王子」!', '你相信嗎?這個以太族身上竟然連一個蜥蝪眼也沒有!$B$B他的領導者竟然還有臉自稱為「走私者王子」!', '你相信嗎?這個伊斯利身上沒有一個蜥蝪眼!$B$B他的領導者竟然還有臉自稱為「走私者王子」!', '你相信嗎?這個伊斯利身上沒有一個蜥蝪眼!$B$B他的領導者竟然還有臉自稱為“走私者王子”!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9457 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9457, 'zhTW', '歡迎，$N。我們是奧多爾，聖光的祭司和薩塔的僕人。$B$B歡迎你留下來和我們一起，要多久都可以。', '歡迎，$N。我們是奧多爾，聖光的祭司和薩塔的僕人。$B$B歡迎你留下來和我們一起，要多久都可以。', '歡迎，$N。我們是奧多爾，聖光的祭司和薩塔的僕人。\n\n歡迎你留下來和我們一起，要多久都可以。', '歡迎，$N。我們是奧多爾，聖光的祭司和薩塔的僕人。$B$B歡迎你留下來和我們一起，要多久都可以。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
