INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9458, 'zhTW', '「生於聖光」會是薩塔最貼切的寫照。那是我們給予那些從伊利丹密探手中奪回撒塔斯城的那魯的名稱。', '「生於聖光」會是薩塔最貼切的寫照。那是我們給予那些從伊利丹密探手中奪回撒塔斯城的那魯的名稱。', '「生於聖光」會是薩塔最貼切的寫照。那是我們給予那些從伊利丹密探手中奪回撒塔斯城的那魯的名稱。', '“生於聖光”會是薩塔最貼切的寫照。那是我們給予那些從伊利丹密探手中奪回撒塔斯城的那魯的名稱。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9459 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9459, 'zhTW', '撒塔斯不只是個和燃燒軍團與伊利丹作戰的舞臺而已。它也是那些想逃離周遭暴力的人的聖域。$B$B如果我們把難民趕走那會使我們成為偽君子。$B$B如果你的問題是那些占卜者，那麼我告訴你，雖然我也不喜歡他們或他們領導者為救贖幻像做出的野蠻要求，但那魯的智慧是不容我們懷疑的。$B$B現在是艱難的時刻，$N。我們需要所有的盟友。', '撒塔斯不只是個和燃燒軍團與伊利丹作戰的舞臺而已。它也是那些想逃離周遭暴力的人的聖域。$B$B如果我們把難民趕走那會使我們成為偽君子。$B$B如果你的問題是那些占卜者，那麼我告訴你，雖然我也不喜歡他們或他們領導者為救贖幻像做出的野蠻要求，但那魯的智慧是不容我們懷疑的。$B$B現在是艱難的時刻，$N。我們需要所有的盟友。', '撒塔斯不只是個和燃燒軍團與伊利丹作戰的舞臺而已。它也是那些想逃離周遭暴力的人的聖殿。$B$B如果我們把難民趕走那會使我們成為偽君子。$B$B如果你的問題是那些占卜者，那麼我告訴你，雖然我也不喜歡他們或他們領導者為救贖幻像做出的野蠻要求，但那魯的智慧是不容我們懷疑的。$B$B現在是艱難的時刻，$N。我們需要所有的盟友。', '撒塔斯不只是個和燃燒軍團與伊利丹作戰的舞臺而已。它也是那些想逃離周遭暴力的人的聖殿。$B$B如果我們把難民趕走那會使我們成為偽君子。$B$B如果你的問題是那些占卜者，那麼我告訴你，雖然我也不喜歡他們或他們領導者為救贖幻像做出的野蠻要求，但那魯的智慧是不容我們懷疑的。$B$B現在是艱難的時刻，$N。我們需要所有的盟友。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9471 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9471, 'zhTW', '歡迎來到艾蘭裡堡壘，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9472 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9472, 'zhTW', '小心點，$c。森林裡充滿了隱藏的危險和潛在的敵人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9477 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9477, 'zhTW', '這真是太糟了。$B$B我不是為了我們的不安著想，但是我們必須做一些事情以減輕白骨荒野死者的傷痛!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9478 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9478, 'zhTW', NULL, '你們是在這裡幫助奧爾多？', NULL, '你為奧爾多效力嗎？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9481 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9481, 'zhTW', '如果你期待會有什麼正式歡迎款待之類的話，你恐怕要失望了，$c。在這裡我們傳統不算什麼，有什麼工作就好好做。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9482 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9482, 'zhTW', '懸賞告示上釘著幾張羊皮紙，一張新的告示引人注目的釘在這個告示牌上。宣佈一則在白骨荒野殺死鞭骨者的訊息。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9484 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9484, 'zhTW', '不，別生氣，我知道的。$B$B<泰蘭看起來又喜又怒>$B$B我是高等精靈，不是血精靈。別擔心，我不會把你的魔法吸光的。', '不，別生氣，我知道的。$B$B<泰蘭看起來又喜又怒>$B$B我是高等精靈，不是血精靈。別擔心，我不會把你的魔法吸光的。', '不，沒關係。我經常遇到這種事情。\n<泰拉看上去有些高興又有些惱火。>\n我是個**高等**精靈，不是個血精靈。所以不要擔心，我不會把你的所有法力吸個精光的。', '不，別生氣，我知道的。$B$B<泰蘭看起來又喜又怒>$B$B我是高等精靈，不是血精靈。別擔心，我不會把你的魔法吸光的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9485 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9485, 'zhTW', '鞭骨者，我恨死他們了!$B$B要不是因為我沒看到，而且還中了暈眩法術，我會在同一時間把他們全都射下!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9486 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9486, 'zhTW', '我看到奧多爾在城牆上工作，你知道?，他們要重建整個城市。$B$B他們工作的速度比老工頭奧斯洛回到湖畔鎮還快。他一直讓他的工具遺失在湖裡，要不然豺狼人會拿走他的補給品。$B$B我應該詢問奧多爾需不需要幫忙，因為他們還得儘速把橋修好。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9487 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9487, 'zhTW', '這裡有廣大的森林，$c。就讓薩滿和靈魂一起玩，也讓戰士把玩他們的劍吧。我將在泰洛卡這個地方創造我的命運財富。', '這裡有廣大的森林，$c。就讓薩滿和靈魂一起玩，也讓戰士把玩他們的劍吧。我將在泰洛卡這個地方創造我的命運財富。', '那裡有著大片的森林，$c。讓薩滿和靈魂們玩耍，讓戰士們耍他們的劍。泰羅卡森林是個要讓我賺大錢的地方。', '這裡有廣大的森林，$c。就讓薩滿和靈魂一起玩，也讓戰士把玩他們的劍吧。我將在泰洛卡這個地方創造我的命運財富。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9488 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9488, 'zhTW', '瑪魯卡茲不斷喋喋不休地講著這個森林的歷史有多重要，但我現在沒有興趣聽這個歷史，除非我們當前的問題解決了。$B$B我不是說他在這裡的工作不重要，但要有個人去看管防禦工事並掌管後勤流程。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9489 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9489, 'zhTW', '從納葛蘭旅行直到來到這個森林，我很害怕我們的原始文化會消逝，但我很高興我錯了。$B$B這裡還是一如既往!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9490 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9490, 'zhTW', '開啟黑暗之門為我的人民的命運帶來了新的訊息，我的流亡保護了我沒有和他們一同毀滅，但是看見那些遠行者卻把他們丟給凱爾薩斯...$B$B我從未想像過我從前的兄弟們會碰到這種事。$B$B我夢想中的歸國永遠不再能實現，這個森林是我唯一的家鄉，我卻得離開。', '開啟黑暗之門為我的人民的命運帶來了新的訊息，我的流亡保護了我沒有和他們一同毀滅，但是看見那些遠行者卻把他們丟給凱爾薩斯...$B$B我從未想像過我從前的兄弟們會碰到這種事。$B$B我夢想中的歸國永遠不再能實現，這個森林是我唯一的家鄉，我卻得離開。', '我的同胞的命運隨著黑暗之門的開啟進入了新的篇章。在某種程度上來說，我的流放使我免於墮落。但是看到遠行者把他們的命運都交給了凱爾薩斯……$B$B我不敢相信我以前的朋友可以做出這樣的事情。$B$B我那回家的夢看來永遠都不可能實現了，這片森林是我唯一的家。', '開啟黑暗之門為我的人民的命運帶來了新的訊息，我的流亡保護了我沒有和他們一同毀滅，但是看見那些遠行者卻把他們丟給凱爾薩斯……$B$B我從未想像過我從前的兄弟們會碰到這種事。$B$B我夢想中的歸國永遠不再能實現，這個森林是我唯一的家鄉，我卻得離開。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9492 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9492, 'zhTW', '當我第一次來到這裡，我希望能遇見和城同名的人。$B$B<羅斯勒斯環視一週>$B$B大部分年輕高等的精靈屬於「我想要成為遠行者」的階段，這時候的他們會被當作新手。接下來，會變成「我想要成為博學者」的階段。$B$B老實說，我不認為我不再適合遠行者的階段。沒有人夢想長大之後，要成為一個女裁縫師，但就像我媽曾說過的話，我不能像遠行者一樣光溜溜的到處跑。', '當我第一次來到這裡，我希望能遇見和城同名的人。$B$B<羅斯勒斯環視一週>$B$B大部分年輕高等的精靈屬於「我想要成為遠行者」的階段，這時候的他們會被當作新手。接下來，會變成「我想要成為博學者」的階段。$B$B老實說，我不認為我不再適合遠行者的階段。沒有人夢想長大之後，要成為一個女裁縫師，但就像我媽曾說過的話，我不能像遠行者一樣光溜溜的到處跑。', '當我最初來到這裡時，我曾希望能和這個小鎮所用名字的主人會面。\n<洛瑟蕾絲掃視著周圍。>\n當年幼的高等精靈成長到學徒的年齡時，他們的腦袋裡想的便不再是“我要成為一名遠行者”，而是“我要當一名魔導師”。\n說實話，我不覺得我曾經幻想過成為遠行者。沒有人會夢想成為一名女裁縫，但就像我母親常常說的那樣，我們不能讓遠行者就這麼不穿衣服走來走去。', '當我第一次來到這裡，我希望能遇見和城同名的人。$B$B<羅斯勒斯環視一週>$B$B大部分年輕高等的精靈屬於“我想要成為遠行者”的階段，這時候的他們會被當作新手。接下來，會變成“我想要成為博學者”的階段。$B$B老實說，我不認為我不再適合遠行者的階段。沒有人夢想長大之後，要成為一個女裁縫師，但就像我媽曾說過的話，我不能像遠行者一樣光溜溜的到處跑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9493 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9493, 'zhTW', '每當我穿了件衣服或帽子，你曾看過羅斯勒斯裝做沒看見我嗎?這裡所有的事情都安頓下來，我要帶她去森林散步。$B$B就這麼一次，我錯過暴風城所有精緻的小酒館。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9494 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9494, 'zhTW', '<凱德對你發出噓聲>$B$B安靜點，要不然你能擊敗獸人和聯盟嗎，你這個笨手笨腳的蠢蛋!$B$B這就對了，點頭就好了，當我們談話結束，你就離開這裡然後忘記你在這裡找到了我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9495 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9495, 'zhTW', '我們可能會在一起工作，但是要小心謹慎，我再一次提醒你要注意你的言行舉止。$B$B我可以保證在這裡我們是最不親近的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9497 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9497, 'zhTW', '是啊，你想要什麼?你看不出來我正在忙嗎?暗影議會讓我一刻不得閒!', '是啊，你想要什麼?你看不出來我正在忙嗎?暗影議會讓我一刻不得閒!', '嗯，你想要什麼？你沒看到我正忙著嗎？暗影議會可不會按小時給我付工錢。', '是啊，你想要什麼?你看不出來我正在忙嗎?暗影議會讓我一刻不得閒!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9498 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9498, 'zhTW', '我看起來像是在做什麼?我在整修這個地方 - 而且還全靠我自己一個人 - 這樣我們才能搬進來!$B$B有了運作基地在這裡的森林，要知道撒塔斯、艾蘭裡、碎石和塞納里奧的德魯伊在幹嘛就容易的多了。我們在奧齊頓的基地就很不方便。$B$B等一下，我認識你嗎?', '我看起來像是在做什麼?我在整修這個地方 - 而且還全靠我自己一個人 - 這樣我們才能搬進來!$B$B有了運作基地在這裡的森林，要知道撒塔斯、艾蘭裡、碎石和塞納里奧的德魯伊在幹嘛就容易的多了。我們在奧齊頓的基地就很不方便。$B$B等一下，我認識你嗎?', '我看上去像在幹什麼？我正在盡我的全力修理這個地方，這樣我們就可以搬進來常駐了！隨著基地在森林中運作起來，我們就更容易監視沙塔斯城、奧蕾莉亞崗哨、裂石堡，以及塞納里奧的德魯伊們。我們在奧金頓的基地中可不方便做這個。等一下，我認識你嗎？', '我看起來像是在做什麼?我在整修這個地方 - 而且還全靠我自己一個人 - 這樣我們才能搬進來!$B$B有了運作基地在這裡的森林，要知道撒塔斯、艾蘭裡、碎石和塞納里奧的德魯伊在幹嘛就容易的多了。我們在奧齊頓的基地就很不方便。$B$B等一下，我認識你嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9502 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9502, 'zhTW', '嗯?去你的，現在我得從頭來過!', '嗯?去你的，現在我得從頭來過!', '嗯？該死的，現在我不得不重新開始了！', '嗯?去你的，現在我得從頭來過!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9503 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9503, 'zhTW', '練習!不用多久我就可以加入其他召喚師並且輪到我去奧齊頓的暗影迷宮。$B$B我希望我有機會可以召喚更大的東西!或許像莫爾墨那麼大，雖然我不會對他失去掌控!', '練習!不用多久我就可以加入其他召喚師並且輪到我去奧齊頓的暗影迷宮。$B$B我希望我有機會可以召喚更大的東西!或許像莫爾墨那麼大，雖然我不會對他失去掌控!', '加緊練習！很快我就會有足夠的能力跟其他召喚者一起進入奧金頓的暗影迷宮了。我希望能得到召喚一些大東西的機會！也許是和摩摩爾一樣大的傢伙，但是我不會失去對他的控制！', '練習!不用多久我就可以加入其他召喚師並且輪到我去奧齊頓的暗影迷宮。$B$B我希望我有機會可以召喚更大的東西!或許像莫爾墨那麼大，雖然我不會對他失去掌控!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9505 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9505, 'zhTW', '你覺得我到底能為你做什麼?你難道不能看出我正忙著和我們偉大的領袖談論重大的議題嗎?$B$B兔崽仔，快說你有什麼事，要不我就扁你一頓!', '你覺得我到底能為你做什麼?你難道不能看出我正忙著和我們偉大的領袖談論重大的議題嗎?$B$B兔崽仔，快說你有什麼事，要不我就扁你一頓!', '你覺得我能為你做些什麼嗎？沒看到我正在討論關於我們傑出領袖的重要事情嗎？有話快說！', '你覺得我到底能為你做什麼?你難道不能看出我正忙著和我們偉大的領袖談論重大的議題嗎?$B$B兔崽仔，快說你有什麼事，要不我就扁你一頓!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9506 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9506, 'zhTW', '好吧，我只是要給我們領袖進度報告，現在所有的事情都在進行中也包括了計畫，不出幾個禮拜，這個地方就能成型了。$B$B然而，我們希望暗影議會派一個人和獸人一起來到村莊。這樣我們就可以完成祖先的要求並且暗中進行這件事。$B$B等等，我認識你嗎?你叫什麼名字?', '好吧，我只是要給我們領袖進度報告，現在所有的事情都在進行中也包括了計畫，不出幾個禮拜，這個地方就能成型了。$B$B然而，我們希望暗影議會派一個人和獸人一起來到村莊。這樣我們就可以完成祖先的要求並且暗中進行這件事。$B$B等等，我認識你嗎?你叫什麼名字?', '好吧，我正在給我們的首領進行彙報。應該只需要再多幾周，我們就可以讓這地方處於良好的執行狀態。不過，我們可能想讓暗影議會只派遣獸人來這裡，那樣的話，我們就能宣稱這村子是我們的屬地，便於進行秘密工作了。等一下，我認識你嗎？你叫什麼名字？', '好吧，我只是要給我們領袖進度報告，現在所有的事情都在進行中也包括了計劃，不出幾個禮拜，這個地方就能成型了。$B$B然而，我們希望暗影議會派一個人和獸人一起來到村莊。這樣我們就可以完成祖先的要求並且暗中進行這件事。$B$B等等，我認識你嗎?你叫什麼名字?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9507 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9507, 'zhTW', '你好，年輕的$r。', '你好，年輕的$r。', '你好，年輕的$r。', '你好，年輕的$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9508 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9508, 'zhTW', '你好，親愛的。我是吉雅，瑪格哈的女守護者。$B$B<主母吉雅咳了幾聲。>$B$B如果你待在這裡，大門會一直敞開著，所以你會很安全。大部分的獸人都太年輕、太虛弱而記不得黑暗之門。$B$B<主母吉雅指向圍繞著她的獸人。>$B$B他們大多是孤兒或是快成為孤兒，唉!黑手會用盡所有的辦法。要健健康康的，唯有強壯才能生存……所以他們才這麼說。', '你好，親愛的。我是吉雅，瑪格哈的女守護者。$B$B<主母吉雅咳了幾聲。>$B$B如果你待在這裡，大門會一直敞開著，所以你會很安全。大部分的獸人都太年輕、太虛弱而記不得黑暗之門。$B$B<主母吉雅指向圍繞著她的獸人。>$B$B他們大多是孤兒或是快成為孤兒，唉!黑手會用盡所有的辦法。要健健康康的，唯有強壯才能生存……所以他們才這麼說。', '你好，親愛的。我是蓋亞安，瑪格漢的女族長。$B$B<蓋亞安祖母咳嗽了一下。>$B$B你在這裡，那及說明黑暗之門已經重新開啟了。在這裡的大部分獸人都太年輕或是太虛弱，以至於不能記起黑暗之門。$B$B<蓋亞安祖母指了指她周圍的獸人。>$B$B他們大部分是孤兒，或很快就會變成孤兒了。是的，這就是黑手酋長的做法，讓體弱者遠離健康者，只有強壯的獸人可以生存……', '你好，親愛的。我是吉雅，瑪格哈的女守護者。$B$B<祖母吉雅咳了幾聲。>$B$B如果你待在這裡，大門會一直敞開著，所以你會很安全。大部分的獸人都太年輕、太虛弱而記不得黑暗之門。$B$B<祖母吉雅指向圍繞著她的獸人。>$B$B他們大多是孤兒或是快成為孤兒，唉!黑手會用盡所有的辦法。要健健康康的，唯有強壯才能生存……所以他們才這麼說。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9509 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9509, 'zhTW', '他們得在這裡成長，我們讓他們安全無憂。我們盡全力讓他們恢復健康。有許多虛弱的人反而更加的成長茁壯，像卡爾洛斯就是……$B$B<主母吉雅嘆了口氣。>$B$B你知道他失去了他的心。他說我是他的平衡。如果沒有了我，他血液中的貪婪會毀滅他的父親，最後還會傷害我們的人民。', '他們得在這裡成長，我們讓他們安全無憂。我們盡全力讓他們恢復健康。有許多虛弱的人反而更加的成長茁壯，像卡爾洛斯就是……$B$B<主母吉雅嘆了口氣。>$B$B你知道他失去了他的心。他說我是他的平衡。如果沒有了我，他血液中的貪婪會毀滅他的父親，最後還會傷害我們的人民。', '他們在這裡長大，我們讓他們遠離傷害。我儘可能地照顧他們的健康。很多都夭折了，但是更多的孩子茁壯成長了起來。就像加爾魯什那樣……$B$B<蓋亞安祖母嘆了口氣。>$B$B你知道，他失去了他的信心。他告訴我，我是他的一切。如果失去了我，吞噬了他的父親、詛咒了我們的人民的嗜血狂熱會徹底佔據他。', '他們得在這裡成長，我們讓他們安全無憂。我們盡全力讓他們恢復健康。有許多虛弱的人反而更加的成長茁壯，像卡爾洛斯就是……$B$B<祖母吉雅嘆了口氣。>$B$B你知道他失去了他的心。他說我是他的平衡。如果沒有了我，他血液中的貪婪會毀滅他的父親，最後還會傷害我們的人民。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9510 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9510, 'zhTW', '<祖母吉雅虛弱的笑著。>$B$B當然不是，親愛的。但這不是我相不相信的問題……$B$B卡爾洛斯可以領導瑪格哈，他強壯且睿智，所有的靈魂都認同他。只是他需要相信他自己。他太害怕了……他的恐懼如此之深，若他可以放自己一馬，他的怒氣會讓他全神貫注，所有的東西也就垂手可得了。', '<祖母吉雅虛弱的笑著。>$B$B當然不是，親愛的。但這不是我相不相信的問題……$B$B卡爾洛斯可以領導瑪格哈，他強壯且睿智，所有的靈魂都認同他。只是他需要相信他自己。他太害怕了……他的恐懼如此之深，若他可以放自己一馬，他的怒氣會讓他全神貫注，所有的東西也就垂手可得了。', '<蓋亞安祖母虛弱地笑了笑。>$B$B當然不，親愛的。但是這並不是我相不相信的問題……$B$B加爾魯什有能力來領導瑪格漢。他是個強壯又聰明的領袖，所有的靈魂都對他很滿意，他只不過需要相信他自己。他害怕的東西太多了……他非常害怕若是讓他管理氏族，他的憤怒會毀滅他自己和所有接近他的人。', '<祖母吉雅虛弱的笑著。>$B$B當然不是，親愛的。但這不是我相不相信的問題……$B$B卡爾洛斯可以領導瑪格哈，他強壯且睿智，所有的靈魂都認同他。只是他需要相信他自己。他太害怕了……他的恐懼如此之深，若他可以放自己一馬，他的怒氣會讓他全神貫注，所有的東西也就垂手可得了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9511 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9511, 'zhTW', '我希望我知道，親愛的。他既不會聽你也不會聽我的，老實說這就是為什麼我還在這裡，為什麼我還不能和族母卡修爾一起離開。他必須找到他的心，沒有了領導者我們的子民活不過這個冬天的。', '我希望我知道，親愛的。他既不會聽你也不會聽我的，老實說這就是為什麼我還在這裡，為什麼我還不能和族母卡修爾一起離開。他必須找到他的心，沒有了領導者我們的子民活不過這個冬天的。', '我希望我能知道該怎麼做，親愛的。他不會聽你的，同樣他也不會聽我的。事實上，這就是我還在這裡的原因，這就是我還沒有和卡舒爾宗母一起離開的原因。他必須找回他的自信。如果沒有合適的領導，我們的人民根本活不過這個冬天。', '我希望我知道，親愛的。他既不會聽你也不會聽我的，老實說這就是為什麼我還在這裡，為什麼我還不能和卡修爾母親一起離開。他必須找到他的心，沒有了領導者我們的子民活不過這個冬天的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9512 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9512, 'zhTW', '<主母吉雅微笑著。>$B$B我老了，時間該到了，當我走了之後，我的靈魂會移往靈界，在那裡我會和我的祖先站在一起，看著我們的子民。$B$B只要卡拉達爾還活著，族母卡修爾的義務就同我現在的義務一樣了。', '<主母吉雅微笑著。>$B$B我老了，時間該到了，當我走了之後，我的靈魂會移往靈界，在那裡我會和我的祖先站在一起，看著我們的子民。$B$B只要卡拉達爾還活著，族母卡修爾的義務就同我現在的義務一樣了。', '<蓋亞安祖母笑了笑。>$B$B我老了，我的時日已經不多了。當我去世以後，我的靈魂會前往靈魂的國度。我會在那裡與我的祖先們團聚。那就是我們關注著仍然活著的人民的地方。$B$B當加拉達還活著的時候，卡舒爾宗母的職責就和我現在的一樣。', '<祖母吉雅微笑著。>$B$B我老了，時間該到了，當我走了之後，我的靈魂會移往靈界，在那裡我會和我的祖先站在一起，看著我們的子民。$B$B只要卡拉達爾還活著，卡修爾母親的義務就同我現在的義務一樣了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9513 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9513, 'zhTW', '身為一位氏族之母的責任就是聆聽。傾聽風、水、火、大地的聲音。替她的氏族收集資訊，就像其他人收集毛皮以供保暖。那些靈魂和我親密地交談……在我的夢裡，族母卡修爾和我談話，正猶如那些靈魂和她談話一樣……當我走了之後，我將會用這種方式與崔克雅和瑟萊斯丁交談。$B$B< 主母吉雅微笑著。>', '身為一位氏族之母的責任就是聆聽。傾聽風、水、火、大地的聲音。替她的氏族收集資訊，就像其他人收集毛皮以供保暖。那些靈魂和我親密地交談……在我的夢裡，族母卡修爾和我談話，正猶如那些靈魂和她談話一樣……當我走了之後，我將會用這種方式與崔克雅和瑟萊斯丁交談。$B$B< 主母吉雅微笑著。>', '部族母親的職責就是傾聽。傾聽風、水、火和大地。從它們那裡收集對氏族有用的資訊，就像氏族中的其他人收集皮毛以供大家禦寒一樣。與我交流的正是靈魂……在我的夢裡，卡舒爾宗母就像靈魂和她談話那樣對我談話……當我去世之後，我會以相同的方式和德拉吉亞和塞雷斯蒂談話。$B$B<蓋亞安祖母微笑著。>', '身為一位氏族之母的責任就是聆聽。傾聽風、水、火、大地的聲音。替她的氏族收集資訊，就像其他人收集毛皮以供保暖。那些靈魂和我親密地交談……在我的夢裡，卡修爾母親和我談話，正猶如那些靈魂和她談話一樣……當我走了之後，我將會用這種方式與崔克雅和瑟萊斯丁交談。$B$B< 祖母吉雅微笑著。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9515 AND `Locale` = 'zhTW';
