INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9520, 'zhTW', '我們需要找出葛蘭戈瓦村謎樣的團體到底要做什麼!', '我們需要找出葛蘭戈瓦村謎樣的團體到底要做什麼!', '我們要找出那些傢伙在格蘭戈瓦村幹些什麼！', '我們需要找出葛蘭戈瓦村謎樣的團體到底要做什麼!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
