INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9537, 'zhTW', '聖光保佑你!這個祝福是給予那些關心其他人的人。每一次都像我們需要得到所有的幫助。衲斯在這方面可以給予你急救的訓練。她在水晶大廳的水晶洞穴附近。願聖光與你同在!', '聖光保佑你!這個祝福是給予那些關心其他人的人。每一次都像我們需要得到所有的幫助。衲斯在這方面可以給予你急救的訓練。她在水晶大廳的水晶洞穴附近。願聖光與你同在!', '以聖光之名！有人願意關心其他人的安寧真是一種幸福。在這種時候，我們就是應該互幫互助幫助。努絲可以教你急救技能，她就在水晶大廳的水晶洞附近。聖光與你同在！', '聖光保佑你!這個祝福是給予那些關心其他人的人。每一次都像我們需要得到所有的幫助。衲斯在這方面可以給予你急救的訓練。她在水晶大廳的水晶洞穴附近。願聖光與你同在!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
