INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9556, 'zhTW', '你可以在水晶大廳找到薩滿訓練師。或許你該拜訪那裡的先知諾柏多，並且在破碎者面前表現一副可憐兮兮的樣子。願聖光保佑你。', '你可以在水晶大廳找到薩滿訓練師。或許你該拜訪那裡的先知諾柏多，並且在破碎者面前表現一副可憐兮兮的樣子。願聖光保佑你。', '水晶大廳中有數名薩滿祭司訓練師。或者你可以找預言者努波頓談談，對這位破碎者表示一下你的憐憫之情。願聖光與你同在。', '你可以在水晶大廳找到薩滿訓練師。或許你該拜訪那裡的先知諾柏多，並且在破碎者面前表現一副可憐兮兮的樣子。願聖光保佑你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
