INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9597, 'zhTW', '塔倫米爾就在樹的另一邊。在全鄉村湧入大量人類士兵之前，敦霍爾德城堡的暴動讓我們多了點時間去尋找塔蕾莎，我們先去檢查附近的穀倉，然後再前往城鎮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
