INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9603, 'zhTW', '旅人休憩小酒館位於長者步道和商店街中間，不管從哪一邊走你都可以到達。', '旅人休憩小酒館位於長者步道和商店街中間，不管從哪一邊走你都可以到達。', '旅者的夢鄉位於長者步道和花園街市之間，你可以從任一方向走到那裡。', '旅人休憩小酒館位於長者步道和商店街中間，不管從哪一邊走你都可以到達。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
