INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9610, 'zhTW', NULL, '我的朋友們，謝謝你們幫助薩爾逃脫。現在我只希望你也可以幫助我。今天早晨我醒來的時候，發現自己被關在這個有法力的監牢裡。一個奇怪的巫師告訴我說，我暫時得待在這裡。', '我的朋友們，謝謝你們幫助薩爾逃脫。現在我只希望你也可以幫助我。今天早晨我醒來的時候，發現自己被關在這個有法力的監牢裡。一個奇怪的巫師告訴我說，我暫時得待在這裡。', '我的朋友們，謝謝你們幫助索爾逃脫。現在我只希望你也可以幫助我。今天早晨我醒來的時候，發現自己被關在這個有法力的監牢裡。一個奇怪的巫師告訴我說，我暫時得待在這裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
