INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9615, 'zhTW', '身為陰鬱城的代表，在這裡我要提出我們的困擾，奧齊頓必須解決暗影議會的侵擾。也就是說比起白骨荒野的世界，我們對於未來要有希望，並儘可能地擊退大洪水!$B$B我們的子民已經承受太多的苦難了，我希望能看見這場災難停止。', '身為陰鬱城的代表，在這裡我要提出我們的困擾，奧齊頓必須解決暗影議會的侵擾。也就是說比起白骨荒野的世界，我們對於未來要有希望，並儘可能地擊退大洪水!$B$B我們的子民已經承受太多的苦難了，我希望能看見這場災難停止。', '身為陰鬱城的代表，在這裡我要提出我們的困擾，奧齊頓必須解決暗影議會的侵擾。也就是說比起白骨荒野的世界，我們對於未來要有希望，並儘可能地擊退大洪水!$B$B我們的子民已經承受太多的苦難了，我希望能看見這場災難停止。', '身為陰鬱城的代表，在這裡我要提出我們的困擾，奧齊頓必須解決暗影議會的侵擾。也就是說比起白骨荒野的世界，我們對於未來要有希望，並儘可能地擊退大洪水!$B$B我們的子民已經承受太多的苦難了，我希望能看見這場災難停止。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
