INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9624, 'zhTW', '賽藍恩，城市裡最好的廚師之一，可以在旅人休憩小酒館的樓上發現他。你也能從她的助手那裡購買烹飪用具。', '賽藍恩，城市裡最好的廚師之一，可以在旅人休憩小酒館的樓上發現他。你也能從她的助手那裡購買烹飪用具。', '塞萊恩是城裡最好的廚師之一，你可以在旅者的夢鄉旅店的樓上找到她。你同樣可以從她的助手那兒買到烹呼叫品。', '賽藍恩，城市裡最好的廚師之一，可以在旅人休憩小酒館的樓上發現他。你也能從她的助手那裡購買烹飪用具。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
