INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9626, 'zhTW', '冬天爺爺在冬幕節日的盛宴期間，會在鐵爐堡的樹下為每個人留下玩具!', '冬天爺爺在冬幕節日的盛宴期間，會在鐵爐堡的樹下為每個人留下玩具!', '在冬幕節期間，冬天爺爺在鐵爐堡的樹下給每個人都留下了玩具。', '冬天爺爺在冬幕節日的盛宴期間，會在鐵爐堡的樹下為每個人留下玩具!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
