INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9632, 'zhTW', '你對礦山的幫助無法言謝。現在，只剩下說服這些礦工回去工作這事了。', '我不知道該怎麼感謝你對我的幫助了。現在，唯一的問題就是說服那些礦工回來工作。', '我不知道該怎麼感謝你對我的幫助了。現在，唯一的問題就是說服那些礦工回來工作。', '你對礦山的幫助無法言謝。現在，只剩下說服這些礦工回去工作這事了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9634 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9634, 'zhTW', '<伊斯法嘆氣。>$B$B一堆樹上小屋不算是一個家，但卻是比塞司克大廳有過之而無不及。$B$B如同在撒塔斯般的舒服，我不能在沒有我的妹妹的情況下回去我真實的家司凱堤斯。她仍然被困在塞司克大廳裡，被我們的哥哥作為囚犯。', '<伊斯法嘆氣。>$b$b一堆樹上小屋不算是一個家，但卻是比塞司克大廳有過之而無不及。$b$b如同在撒塔斯般的舒服，我不能在沒有我的妹妹的情況下回去我真實的家司凱堤斯。她仍然被困在塞司克大廳裡，被我們的哥哥作為囚犯。', '<伊斯法嘆氣。>$b$b一堆樹上小屋不算是一個家，但卻是比塞司克大廳有過之而無不及。$b$b如同在撒塔斯般的舒服，我不能在沒有我的妹妹的情況下回去我真實的家司凱堤斯。她仍然被困在塞司克大廳裡，被我們的哥哥作為囚犯。', '<伊斯法嘆氣。>$B$B一堆樹上小屋不算是一個家，但卻是比塞司克大廳有過之而無不及。$B$B如同在撒塔斯般的舒服，我不能在沒有我的妹妹的情況下回去我真實的家司凱堤斯。她仍然被困在塞司克大廳裡，被我們的哥哥作為囚犯。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9636 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9636, 'zhTW', '現在是我們的機會!把我從這隻籠中放出!', '現在是我們的機會!把我從這隻籠中放出!', '現在是我們的機會!把我從這隻籠中放出!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9637 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9637, 'zhTW', '試煉競技場曾經是偉大光榮和榮譽的地方。後來，熱砂企業的哥布林們來了，帶著許多裝滿黃金的馬車和比任何獸人斧還鋒利的鵝毛筆……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9638 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9638, 'zhTW', '塞司克相信他們自己是所有阿拉卡主人最真和最忠誠的崇拜者。不要詢問關於主人的事情，$R，因為他的神秘只給予那些有羽毛的人的。$B$B塞司克解釋奧齊頓的崩潰是因為我們主人到達這顆行星上。他們準備出發去廢墟，帶著我們最偉大之英雄泰洛克的遺物。$B$B他們仍然在神廟的廢墟中尋找主人，但是我看穿了他們的謊話。我不再是他們其中的一個。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9639 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9639, 'zhTW', '當我在大廳時，鷹王伊奇斯帶著泰洛克羽毛，作為他權力的標誌。$B$B我的兄弟，暗法師希斯，在我們的儀式期間戴著泰洛克面罩。$B$B至於泰洛克的傳說，沒有辦法確切知道它在那裡，但是他們通常將它放在他們巨大拱頂大廳內的符文法陣中心。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9640 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9640, 'zhTW', '鷹王伊奇斯是塞司克的領導人之一，與我的兄弟，暗法師希斯一起。$B$B他們領導塞司克人從司凱堤斯遷徙到奧齊頓的廢墟。最初，伊奇斯是一位有號召力的領導人，但是他已經幾近瘋狂。$B$B現在，他公開宣佈他是泰洛克再世!他真的期望阿拉卡人對他卑躬屈膝以作為他們的統治者。你能相信他的傲慢嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9641 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9641, 'zhTW', '他曾經是阿拉卡最偉大的英雄。$B$B傳說在古代，他用他自己的爪子建造司凱堤斯城。他是我們最偉大的勇士和防衛者，但是當我們捨棄了對魯克馬爾的尊敬感時，他離開了我們。$B$B我們來信奉一位新的主人，一個將宇宙裡未知的力量和地位許諾給我們的人。$B$B有些人說泰洛克和魯克馬爾是同一個人，並且當我們對他遠離時，他從我們這裡消失了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9642 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9642, 'zhTW', '都是肌肉沒有大腦，那樣等於是勞工!當你能激勵他們的時候，他們是偉大的，但他們必須被「踢」動，你知道我的意思吧。', '苦工就是那樣力大無腦！他們還是很聽話的，不過必須在開始前被“踢幾下”才行，我想你應該能明白我的意思。', '苦工就是那樣力大無腦！他們還是很聽話的，不過必須在開始前被“踢幾下”才行，我想你應該能明白我的意思。', '都是肌肉沒有大腦，那樣等於是勞工!當你能激勵他們的時候，他們是偉大的，但他們必須被“踢”動，你知道我的意思吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9643 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9643, 'zhTW', '就像你看見的任何事情一樣嗎，$c?', '就像你看見的任何事情一樣嗎，$c?', '就像你看見的任何事情一樣嗎，$c?', '就像你看見的任何事情一樣嗎，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9644 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9644, 'zhTW', '如果你有錢，我就有你需要的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
