INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9646, 'zhTW', '不用著急，看看這些武器。如果你需要修理武器和盔甲，我也提供這樣的服務。', '不用著急，看看這些武器。如果你需要修理武器和盔甲，我也提供這樣的服務。', '不用著急，看看這些武器。如果你需要修理武器和盔甲，我也提供這樣的服務。', '不用著急，看看這些武器。如果你需要修理武器和盔甲，我也提供這樣的服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9647 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9647, 'zhTW', '我這裡只有你施法所需要的東西。', '我有你所需要的施法材料。', '我有你所需要的施法材料。', '我這裡只有你施法所需要的東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
