INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9652, 'zhTW', '你迷路了嗎?大多數的鎮上小販都在市中心附近。', '你迷路了嗎?大多數的鎮上小販都在市中心附近。', '你迷路了嗎？這裡大部分的商人都居住在城鎮中心。', '你迷路了嗎?大多數的鎮上小販都在市中心附近。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
