INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9654, 'zhTW', '我快要發瘋了。我不能拿到那些可惡的蛋!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9656 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9656, 'zhTW', '多年來，榮譽堡一直對抗著地獄火半島的恐怖。現在，既然傳送門的入口已經重新開啟，且援助從艾澤拉斯來到，或許這個流血的僵持將會結束。', '多年來，榮譽堡一直對抗著地獄火半島的恐怖。現在，既然傳送門的入口已經重新開啟，且援助從艾澤拉斯來到，或許這個流血的僵持將會結束。', NULL, '多年來，榮譽堡一直對抗著地獄火半島的恐怖。現在，既然傳送門的入口已經重新開啟，且援助從艾澤拉斯來到，或許這個流血的僵持將會結束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9657 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9657, 'zhTW', '令人遺憾的是，我們在地獄火半島上那麼多的敵人中，地獄火堡壘的獸人們站在他們中間。$B$B但是...誰能比獸人們更適於挑戰並消耗部落...?', '令人遺憾的是，我們在地獄火半島上那麼多的敵人中，地獄火堡壘的獸人們站在他們中間。$B$B但是...誰能比獸人們更適於挑戰並消耗部落...?', '令人遺憾的是，我們在地獄火半島上那麼多的敵人中，地獄火堡壘的獸人們站在他們中間。$b$b但是……誰能比獸人們更適於挑戰並消耗部落……?', '令人遺憾的是，我們在地獄火半島上那麼多的敵人中，地獄火堡壘的獸人們站在他們中間。$B$B但是……誰能比獸人們更適於挑戰並消耗部落……?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9659 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9659, 'zhTW', '真高興再次見到你，$N!只需一些更多的調整，而跳躍軌道將會是完美的!', '真高興再次見到你，$N!只需一些更多的調整，而跳躍軌道將會是完美的!', '真高興再次見到你，$N!只需一些更多的調整，而跳躍軌道將會是完美的!', '真高興再次見到你，$N!只需一些更多的調整，而跳躍軌道將會是完美的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
