INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9662, 'zhTW', '德魯伊們舉行的新年節慶慶祝活動正在月光林地進行。如果旅行到那裡對你來說太遠了，他們正在公園提供月井的運輸服務。', '德魯伊們舉行的新年節慶慶祝活動正在月光林地進行。如果旅行到那裡對你來說太遠了，他們正在公園提供月井的運輸服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9686 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9686, 'zhTW', '冬天爺爺可以在鐵爐堡銀行的前面找到。靠近他的樹是分發禮物的地方。', '冬天爺爺可以在鐵爐堡銀行的前面找到。靠近他的樹是分發禮物的地方。', '冬天爺爺就在鐵爐堡銀行門口。他身旁的樹下堆滿了禮物。', '冬天爺爺可以在鐵爐堡銀行的前面找到。靠近他的樹是分發禮物的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9688 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9688, 'zhTW', '去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們談話。他們能將你送到月光林地參加新年節慶慶祝活動。', '去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們談話。他們能將你送到月光林地參加新年節慶慶祝活動。', '去鐵爐堡的秘法區和那裡的暗夜精靈德魯伊談談吧，他們可以把你傳送到月光林地去參加春節慶典。', '去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們談話。他們能將你送到月光林地參加新年節慶慶祝活動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9690 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9690, 'zhTW', 'The younger races make a big fuss over Winter Veil. Ironforge\'s bank is the center of the festivities.', '青少年者的比賽引起冬幕節的大混亂。鐵爐堡的銀行是慶典的中心。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
