INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9692, 'zhTW', '新年節慶的慶祝活動正在月光林地達到高峰。你可以選擇艱辛的長途旅行，或者是利用塞納里奧區的德魯伊們所提供的運輸服務。', '新年節慶的慶祝活動正在月光林地達到高峰。你可以選擇艱辛的長途旅行，或者是利用塞納里奧區的德魯伊們所提供的運輸服務。', '新年節慶的慶祝活動正在月光林地達到高峰。你可以選擇艱辛的長途旅行，或者是利用塞納里奧區的德魯伊們所提供的運輸服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9694 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9694, 'zhTW', '我遊歷過無數個世界，但是我從未見過像冬幕節這樣令人愉快的慶祝活動。你應該前往鐵爐堡，矮人們的偉大城市，親眼看看這場盛會。', '我遊歷過無數個世界，但是我從未見過像冬幕節這樣令人愉快的慶祝活動。你應該前往鐵爐堡，矮人們的偉大城市，親眼看看這場盛會。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
