INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9696, 'zhTW', '艾澤拉斯的德魯伊在月光林地舉行一個盛大的慶祝活動。如果你在城市裡找到新年狂歡者，他們可傳送你到那裡。', '艾澤拉斯的德魯伊在月光林地舉行一個盛大的慶祝活動。如果你在城市裡找到新年狂歡者，他們可傳送你到那裡。', '艾澤拉斯的德魯伊在月光林地舉行一個盛大的慶祝活動。如果你在城市裡找到新年狂歡者，他們可傳送你到那裡。', '艾澤拉斯的德魯伊在月光林地舉行一個盛大的慶祝活動。如果你在城市裡找到新年狂歡者，他們可傳送你到那裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
