INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9704, 'zhTW', '新年節慶最大的慶祝活動正在月光林地進行。如果覺得旅行到那裡太遠，德魯伊們提供從智慧谷出發的運輸服務。', '新年節慶最大的慶祝活動正在月光林地進行。如果覺得旅行到那裡太遠，德魯伊們提供從智慧谷出發的運輸服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9706 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9706, 'zhTW', '在如此寒冷的季節裡，冬幕節的慶祝宴會溫暖了大家的心，而慶祝的主要地點位在奧格瑪。', '在如此寒冷的季節裡，冬幕節的慶祝宴會溫暖了大家的心，而慶祝的主要地點位在奧格瑪。', '在如此寒冷的季節裡，冬幕節的慶祝宴會溫暖了大家的心，而慶祝的主要地點位在奧格瑪。', '在如此寒冷的季節裡，冬幕節的慶祝宴會溫暖了大家的心，而慶祝的主要地點位在奧格瑪。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9708 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9708, 'zhTW', 'The largest celebration of the Lunar Festival takes place in Moonglade. Druids will transport you there from the Elder Rise of Thunder Bluff.', '新年節慶最大的慶祝活動在月光林地進行。在雷霆崖長者高地那裡的德魯伊們將可以傳送你過去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9710 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9710, 'zhTW', '我們仍然舉行應景的活動，但是今年的冬幕節宴會已經冷清了許多。在奧格瑪，他們有真正的慶祝活動。', '我們仍然舉行應景的活動，但是今年的冬幕節宴會已經冷清了許多。在奧格瑪，他們有真正的慶祝活動。', '我們也開始慶祝冬幕節了，但這裡的宴會感覺有點空曠。奧格瑞瑪那邊才是真正的慶典。', '我們仍然舉行應景的活動，但是今年的冬幕節宴會已經冷清了許多。在奧格瑪，他們有真正的慶祝活動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9712 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9712, 'zhTW', '對大多數的被遺忘者而言，月亮現在我們心中佔有一席之地，那個太陽曾經存在的地方。不過，如果你選擇參加慶祝活動，去卡林多的月光林地。在幽暗城上的王座廳裡的德魯伊們將可以傳送你到那裡。', '對大多數的被遺忘者而言，月亮現在我們心中佔有一席之地，那個太陽曾經存在的地方。不過，如果你選擇參加慶祝活動，去卡林多的月光林地。在幽暗城上的王座廳裡的德魯伊們將可以傳送你到那裡。', '對遺忘者來說，月亮已經取代了太陽在我們心中的地位。如果你想要參加節日慶典的話，就去卡利姆多的月光林地吧。幽暗城王座廳的德魯伊可以將你傳送到那裡。', '對大多數的被遺忘者而言，月亮現在我們心中佔有一席之地，那個太陽曾經存在的地方。不過，如果你選擇參加慶祝活動，去卡林多的月光林地。在幽暗城上的寶座房間裡的德魯伊們將可以傳送你到那裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9713 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9713, 'zhTW', '你 - 過來這裡。這些刀劍難道不是質地優良的嗎?當然你會希望從我這裡購買。你在別處找不到像這樣的手藝，並且這樣做工精細的武器，$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9714 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9714, 'zhTW', '你在注視什麼，$r?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
