INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9715, 'zhTW', 'Go to Ironforge\'s Mystic Ward and speak with the night elf druids there. They can transport you to Moonglade to join in the Lunar Festival celebration.', '去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們講話。他們能送你到月光林地參加新年節慶慶祝活動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9716 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9716, 'zhTW', '最驚人的新年節慶派對在月光之林舉行。不過，不要用走的，在智慧谷的德魯伊們可以傳送你到那裡。', '最驚人的新年節慶派對在月光之林舉行。不過，不要用走的，在智慧谷的德魯伊們可以傳送你到那裡。', '最驚人的新年節慶派對在月光之林舉行。不過，不要用走的，在智慧谷的德魯伊們可以傳送你到那裡。', '最驚人的新年節慶派對在月光之林舉行。不過，不要用走的，在智慧谷的德魯伊們可以傳送你到那裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
