INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9717, 'zhTW', '冬天爺爺可以在鐵爐堡銀行的前面被發現。靠近他的樹是分發禮物的地方。', '冬天爺爺可以在鐵爐堡銀行的前面被發現。靠近他的樹是分發禮物的地方。', '冬天爺爺可以在鐵爐堡銀行的前面被發現。靠近他的樹是分發禮物的地方。', '冬天爺爺可以在鐵爐堡銀行的前面被發現。靠近他的樹是分發禮物的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
