INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9734, 'zhTW', '離開我的視線，孩子!你看不見我正在訓練嗎?就是我，我將是下一名戰槌勇士。$B$B呀，我就快要準備就緒然後就能前往舊獰笑骷髏廢墟的北面的血之競技場了。但是想都不要想，孩子。你太弱了。葛爾薩克，競技場廣播員，甚至不會讓你偷看一下競技場，更不用說在它裡面的戰鬥。$B$B現在，在它擊敗你之前，先擊敗它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9735 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9735, 'zhTW', '好，看看你。你不是高大和強壯的……或許你認為你強壯到足以走進血色競技場，並且面對戰槌勇士嗎?$B$B<競技場鬥士笑了。>$B$B不是很可能，不過如果你想要試試你力量，血色競技場的位置是遠北方，面對著分隔納葛蘭和贊格沼澤的山脈。葛爾薩克在舊獰笑骷髏廢墟經營表演，而他負責發放獎品。談到獎品，我聽到這季的獎品令人難以置信!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9738 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9738, 'zhTW', '審問者試圖查明這些血精靈正在納葛蘭這裡做些什麼。從我聽到的，他們在追蹤來自歐夏剛，西方的鑽石山，的水晶粉末殘渣。無疑地要用在一些陰險的計畫或者混合物裡的……$B$B假如你願意幫助我們並且阻止這些血精靈的話，衝突現在正在哈剌的西北方發生。血精靈們和阿古斯之手計程車兵正在戰鬥!加入他們並且讓他們知道我們的厲害!', '審問者試圖查明這些血精靈正在納葛蘭這裡做些什麼。從我聽到的，他們在追蹤來自歐夏剛，西方的鑽石山，的水晶粉末殘渣。無疑地要用在一些陰險的計畫或者混合物裡的……$B$B假如你願意幫助我們並且阻止這些血精靈的話，衝突現在正在哈剌的西北方發生。血精靈們和阿古斯之手計程車兵正在戰鬥!加入他們並且讓他們知道我們的厲害!', '審問者試圖查明這些血精靈正在納葛蘭這裡做些什麼。從我聽到的，他們在追蹤來自歐夏剛，西方的鑽石山，的水晶粉末殘渣。無疑地要用在一些陰險的計畫或者混合物裡的……\n\n假如你願意幫助我們並且阻止這些血精靈的話，衝突現在正在哈剌的西北方發生。血精靈們和阿古斯之手計程車兵正在戰鬥!加入他們並且讓他們知道我們的厲害!', '審問者試圖查明這些血精靈正在納葛蘭這裡做些什麼。從我聽到的，他們在追蹤來自歐夏剛，西方的鑽石山，的水晶粉末殘渣。無疑地要用在一些陰險的計劃或者混合物裡的……$B$B假如你願意幫助我們並且阻止這些血精靈的話，衝突現在正在哈剌的西北方發生。血精靈們和阿古斯之手計程車兵正在戰鬥!加入他們並且讓他們知道我們的厲害!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
