INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9775, 'zhTW', '地獄火半島是一個粉碎的王國 - 對它的居民殘酷而無情。在冒險以前一定要修理好裝備並且貯存補給品。', '地獄火半島是一個粉碎的王國 - 對它的居民殘酷而無情。在冒險以前一定要修理好裝備並且貯存補給品。', '地獄火半島是一個粉碎的王國 - 對它的居民殘酷而無情。在冒險以前一定要修理好裝備並且貯存補給品。', '地獄火半島是一個粉碎的王國 - 對它的居民殘酷而無情。在冒險以前一定要修理好裝備並且貯存補給品。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9777 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9777, 'zhTW', '降低你的音量，並張大你的雙眼，$N。我們的外面到處都是敵人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9778 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9778, 'zhTW', '你必須在敦霍爾德城堡拘留室裡的桶子旁使用燃燒炸彈包裹。一旦5顆炸彈已經被點燃且轉向已經被設定，找到位於敦霍爾德地下監獄的索爾並且釋放他。跟著他並且確保他的安全!$B$B當你準備好時，布瑞茲恩將載你飛到敦霍爾德。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9779 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9779, 'zhTW', '我可以立刻帶你去敦霍爾德，如果你想要的話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9780 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9780, 'zhTW', '在我載你飛到敦霍爾德之前，你應該從伊洛森那獲取燃燒炸彈包裹。畢竟，你不會想要浪費你的時間吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9781 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9781, 'zhTW', '可怕...就只有可怕!$B$B我們只是從虛空風暴的52區離開回來而已，而他們擊落我們!我知道我們不該利用那個捷徑去泰洛卡森林!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9784 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9784, 'zhTW', '遠征隊哨塔是聯盟與軍團前線最近的接觸點。這裡北部除了惡魔之外別無他物，惡魔和更多的惡魔。建議最好與一個同伴一起旅行。', '遠征軍崗哨是聯盟最接近燃燒軍團前線的聯絡點。這裡的北面除了惡魔還是惡魔。找個朋友搭伴旅行吧。', '遠征軍崗哨是聯盟最接近燃燒軍團前線的聯絡點。這裡的北面除了惡魔還是惡魔。找個朋友搭伴旅行吧。', '遠征隊哨塔是聯盟與軍團前線最近的接觸點。這裡北部除了惡魔之外別無他物，惡魔和更多的惡魔。建議最好與一個同伴一起旅行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9787 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9787, 'zhTW', '因為我對古老德萊尼水晶和遺物的知識，伊利丹的惡魔將我囚禁在這裡。$B$B他們已經奴役我們大多數人，並且利用我們尋找一顆強而有力的水晶...一顆甚至很可能根本不在這裡的水晶。', '因為我對古老德萊尼水晶和遺物的知識，伊利丹的惡魔將我囚禁在這裡。$b$b他們已經奴役我們大多數人，並且利用我們尋找一顆強而有力的水晶……一顆甚至很可能根本不在這裡的水晶。', '因為我對古老德萊尼水晶和遺物的知識，伊利丹的惡魔將我囚禁在這裡。$b$b他們已經奴役我們大多數人，並且利用我們尋找一顆強而有力的水晶……一顆甚至很可能根本不在這裡的水晶。', '因為我對古老德萊尼水晶和遺物的知識，伊利丹的惡魔將我囚禁在這裡。$B$B他們已經奴役我們大多數人，並且利用我們尋找一顆強而有力的水晶……一顆甚至很可能根本不在這裡的水晶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9788 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9788, 'zhTW', '為什麼?如果伊利丹的惡魔沒有再次抓到我並奴役我，贊格沼澤的納迦也會。$B$B加入伊利丹和他所屬聯盟的人原來只是一些破碎者部族裡的奴役。我的人民沒有希望了。', '為什麼？就算伊利丹的惡魔不再抓住我、奴役我，那麼贊加沼澤的納迦也會這麼做的。$B$B加入伊利丹和他的惡魔大軍無非是為破碎者氏族套上新的枷鎖罷了。我們的人民沒有任何希望。', '為什麼？就算伊利丹的惡魔不再抓住我、奴役我，那麼贊加沼澤的納迦也會這麼做的。$B$B加入伊利丹和他的惡魔大軍無非是為破碎者氏族套上新的枷鎖罷了。我們的人民沒有任何希望。', '為什麼?如果伊利丹的惡魔沒有再次抓到我並奴役我，贊格沼澤的納迦也會。$B$B加入伊利丹和他所屬聯盟的人原來只是一些破碎者部族裡的奴役。我的人民沒有希望了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9789 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9789, 'zhTW', '我絕不會再抄捷徑了，我發誓!我怎麼會知道在地獄火半島上方的天空是那麼的危險?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9800 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9800, 'zhTW', '<當你接近那些那魯時，慰藉的亮光充滿你。緩慢的音樂鐘琴聲在你的心裡迴盪，雖然一言不發，你感覺到安全的保證。歡迎你來到在撒塔斯城。 >', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9801 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9801, 'zhTW', '向前走，除非對艦隊有任何意見。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9805 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9805, 'zhTW', '她是個美人，不是嗎?史蓋瑞……我們指揮官的忠實獅鷲。庫德蘭他自己，他在堡壘裡有他的觀眾。當他忙碌的時候，我會照顧我們這裡的史蓋瑞。華麗的動物，她是;生來強大而兇猛。她會為庫德蘭而死。一個你們從未見過的忠實靈魂。$B$B照顧他是一種榮譽，是的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9819 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9819, 'zhTW', NULL, '卡爾洛斯跟你說了什麼，$n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9821 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9821, 'zhTW', NULL, '<主母吉雅點了點頭，接受你的回答。>$B$B我不能再與那些精靈戰鬥了，$n。我的時代老早以前就過去了。再一次，我必須為你所做的一切感謝你。當卡爾洛斯也許無法被移動，我的大多數族人已經被你的成就所感動。他們現在願意成為一個聯合的部落來為我們的權利而戰鬥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9822 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9822, 'zhTW', NULL, '<主母吉雅對著你微笑。>$B$B你使我想起我的兒子，$n。$B$B他是一座不可移動的山︰一個社會的棟樑和榮譽。$B$B<吉雅的眼睛湧出眼淚。>$B$B他犧牲自己，好讓我們能倖存下來。以便在他之後的數代獸人，可以出生於一個沒有血詛咒的世界...沒有古爾丹和他的黑暗部落...$b$b<吉雅凝視遠方，呆呆地默想的。>$B$B噢 杜洛坦，我真希望你能在這裡。你的族人如此地需要你...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9823 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9823, 'zhTW', NULL, '<主母吉雅點點頭。>$B$B你認識我兒子嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9824 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9824, 'zhTW', NULL, '<主母吉雅紫色的眼睛緊盯著你的雙眼。>$B$B是的...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9825 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9825, 'zhTW', NULL, '<淚水從主母吉雅的臉上落下。>$B$B我...我...杜洛坦倖存下來而有一個孩子嗎?這個孩子崔坎在他們離開之前告訴我...那是他們最大的恐懼...在這個世界培養一個孩子。在那扇門的另一邊是他們唯一的希望。我不敢告訴杜洛坦，但是秘密地，我懇求精靈庇佑他們 - 保護他們的孩子並且給他們力量。$B$B我...我必須看看我的孫子。我必須看看他。拜託，我太虛弱了。你必須告訴他。在我離開這個世界之前...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9826 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9826, 'zhTW', '虛空風暴不是永遠如你現在所看見的一樣。$B$B曾幾何時這塊被踐踏的土地被稱為法拉隆平原。那些原有的面目現在卻已面目全非。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9827 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9827, 'zhTW', '$C，停止你的攻擊，這只是一個偽裝!我在撒塔斯城外為陰鬱城聯盟工作的一個間諜。$B$B我希望你在這裡能幫助我!', '$C，停止你的攻擊，這只是一個偽裝!我在撒塔斯城外為陰鬱城聯盟工作的一個間諜。$B$B我希望你在這裡能幫助我!', NULL, '$C，停止你的攻擊，這只是一個偽裝!我在撒塔斯城外為陰鬱城聯盟工作的一個間諜。$B$B我希望你在這裡能幫助我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9828 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9828, 'zhTW', '大法師瓦戈斯在告知我如何從血精靈對紫色之塔的攻擊中逃離後將他的法杖委託於我。我按他所告訴我的去做，希望能在阿克隆的舊德萊尼殖民地裡避難。$B$B沒有暫緩。我已經一直走進燃燒軍團部隊的前方。惡魔從我那兒搶走法杖，但是我都幸運的逃離。$B$B雖然我的主人對我的失敗一無所知，但它仍然使我羞愧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9832 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9832, 'zhTW', '很好。看看虛空之風掃了什麼進來。進來，坐下，好好的休息一下。費用是適當的;你肯定能支付得起。', '很好。看看虛空之風掃了什麼進來。進來，坐下，好好的休息一下。費用是適當的;你肯定能支付得起。', '很好。看看虛空之風掃了什麼進來。進來，坐下，好好的休息一下。費用是適當的;你肯定能支付得起。', '很好。看看虛空之風掃了什麼進來。進來，坐下，好好的休息一下。費用是適當的;你肯定能支付得起。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9833 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9833, 'zhTW', '他們從不休息嗎?!$B$B假如我們是去確保陰鬱城民眾的未來，我們必須要在暗影議會引起一場比白骨荒野更大的劇變之前處理它們!$B$B因為撒塔斯城的領導將不再迅速轉變，我們這些陰鬱城的自由人們已經把責任放進我們自己的手中。$B$B但我們的間諜已經被發現。當你溜進迷宮，看看能發現到什麼秘密的同時，我們將拖延暗影議會的特務。', '他們從不休息嗎?!$b$b假如我們是去確保陰鬱城民眾的未來，我們必須要在暗影議會引起一場比白骨荒野更大的劇變之前處理它們!$b$b因為撒塔斯城的領導將不再迅速轉變，我們這些陰鬱城的自由人們已經把責任放進我們自己的手中。$b$b但我們的間諜已經被發現。當你溜進迷宮，看看能發現到什麼秘密的同時，我們將拖延暗影議會的特務。', '他們從不休息嗎?!$b$b假如我們是去確保陰鬱城民眾的未來，我們必須要在暗影議會引起一場比白骨荒野更大的劇變之前處理它們!$b$b因為撒塔斯城的領導將不再迅速轉變，我們這些陰鬱城的自由人們已經把責任放進我們自己的手中。$b$b但我們的間諜已經被發現。當你溜進迷宮，看看能發現到什麼秘密的同時，我們將拖延暗影議會的特務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9834 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9834, 'zhTW', '很久以前，在凡人心智深不可測的宇宙空間內，誕生了 - 如果能這麼說的話 - 一個具有如此難以相信強大力量的生命，以致於它的出現粉碎了在它周遭的所有事物。$B$B人們稱它為莫爾墨，它是聲音的精華，任何聽到它言語的人都將見識到永恆的死亡!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9835 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9835, 'zhTW', '只為混亂存在，它輕微的低語意味著全世界的毀滅!$B$B但仍然，有那些嚐試崇拜這無腦的生物。甚至有那些更加瘋狂想要控制它的人!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9836 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9836, 'zhTW', '發黴的法典書頁好像會魔術般地翻轉它們自己，引導你的注意到一個特定的章節，沒有凡人的眼睛可以察覺剛過去的恐怖。$B$B書本會開啟到不知怎麼地感到〝正確〞的一頁，然而是錯的離譜的一頁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9837 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9837, 'zhTW', '看啊，勇者在它的跟前顫抖，害怕它會對其出聲。$B$B但是這些騙子，這些崇拜不存在之偽教的假信徒，依舊罔顧現實，企圖要控制他們的「神」。然而，莫爾墨只是毫不在乎地 - 或可能甚至根本沒注意到他們 - 打了個呵欠，他們就這樣灰飛湮滅了。$B$B但不知怎麼的，有個人倖存了下來，而且他的瘋狂同時也找到了使莫爾墨進入這世界的途徑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9838 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9838, 'zhTW', '有一個對於秘法和黑暗的知識的狂熱是無人所能超過的凡人，他想出一種方法透過捕捉和使用未知的靈魂來強化他的召喚。$B$B整個文明世界因為他的靈魂裝置成為儀式的燃料而陷入絕盡，透過他和他的陰謀者們莫爾墨將被召喚到他們的世界。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9839 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9839, 'zhTW', '而他們將莫爾墨召喚前來。$B$B使用強大的封鎖魔法和沉默魔法，並定期的餵食他們靈魂。然而他們仍然無法控制那野獸，不能使它屈服於他們的意願。$B$B這些凡人開始想出不同的策略，而他們全部都一個接一個的失敗。也因為不斷的嘗試，儀式的力量因此減弱，意外的使莫爾墨獲得輕微的一點點自由。$B$B而那就是它所需要的全部。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9840 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9840, 'zhTW', '只有這本書在經歷毀滅他們世界的災變之後仍然倖存。那些想要控制一個具有未知力量的宇宙生命的驕傲和愚蠢的人。$B$B身為法典的持有人，你會作出同樣的事嗎?$B$B你有想出一個萬全的方法來召喚莫爾墨，以及任何在這邪惡的書頁內所隱藏的秘密嗎?$B$B我們拭目以待。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9841 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9841, 'zhTW', '嘿你!看見一張新面孔真好 - 這裡不常出現參觀者，而那些技師也不是很好的談話物件。$B$B我打賭你是要去52區的路上。對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9842 AND `Locale` = 'zhTW';
