INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10011, 'zhTW', '陸行鷹是高貴的生物。記得永遠都要對你的陸行鷹很好;很少比憤怒的陸行鷹更危險的了。', '陸行鷹是高貴的生物。記得永遠都要對你的陸行鷹很好;很少比憤怒的陸行鷹更危險的了。', '陸行鳥是種高貴的生物。你要好好對待你的陸行鳥，沒有什麼比一隻憤怒的陸行鳥更危險了。', '陸行鷹是高貴的生物。記得永遠都要對你的陸行鷹很好;很少比憤怒的陸行鷹更危險的了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
