INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10018, 'zhTW', '前往外域?去虛空風暴的52區拜訪維斯頓·急嘯。身為熱砂戰鬥同盟的官方競技場商人，他販賣各種不可思議的物品給有足夠競技場點數的人。', '前往外域?去虛空風暴的52區拜訪維斯頓·急嘯。身為熱砂戰鬥同盟的官方競技場商人，他販賣各種不可思議的物品給有足夠競技場點數的人。', '去外域？記得拜訪一下虛空風暴52區的維克斯頓。他是熱砂搏擊會的官方競技場商人，他那裡有許多不可思議的物品，專門賣給那些有著足夠競技場點數的傢伙。', '前往外域?去虛空風暴的52區拜訪維斯頓·急嘯。身為熱砂戰鬥同盟的官方競技場商人，他販賣各種不可思議的物品給有足夠競技場點數的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
