INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10022, 'zhTW', '這些人幾天前從撒塔斯抵達，從那時候開始他們就沒停止過爭吵。$B$B我很高興他們沒有把你嚇跑，因為我開始認為他們在嚇跑我的顧客。', '這些人幾天前從撒塔斯抵達，從那時候開始他們就沒停止過爭吵。$B$B我很高興他們沒有把你嚇跑，因為我開始認為他們在嚇跑我的顧客。', '這些人幾天前從撒塔斯抵達，從那時候開始他們就沒停止過爭吵。\n\n我很高興他們沒有把你嚇跑，因為我開始認為他們在嚇跑我的顧客。', '這些人幾天前從撒塔斯抵達，從那時候開始他們就沒停止過爭吵。$B$B我很高興他們沒有把你嚇跑，因為我開始認為他們在嚇跑我的顧客。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
