INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10024, 'zhTW', '你的等級還不足以參加暴風之眼的戰鬥。等你獲得更多經驗的時候再回來。', '你的等級還不足以參加暴風之眼的戰鬥。等你獲得更多經驗的時候再回來。', '你的等級還無法在暴風之眼裡進行戰鬥。當你獲得更多經驗時再回來試試。', '你的等級還不足以參加暴風之眼的戰鬥。等你獲得更多經驗的時候再回來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
