INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10025, 'zhTW', '在外域的暴風之眼，德萊尼部隊和他們的聯盟與部落開始了戰爭。你願意加入他們來扭轉戰爭的情勢嗎?', '在外域的暴風之眼，德萊尼部隊和他們的聯盟與部落開始了戰爭。你願意加入他們來扭轉戰爭的情勢嗎?', '在外域的暴風之眼，德萊尼部隊和他們的聯盟與部落開始了戰爭。你願意加入他們來扭轉戰爭的情勢嗎?', '在外域的暴風之眼，德萊尼部隊和他們的聯盟與部落開始了戰爭。你願意加入他們來扭轉戰爭的情勢嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10026 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10026, 'zhTW', '部落不允許德萊尼和他們愛管閒事的聯盟控制在外域裡全部的法力電池。你願意加入血精靈的行列與他們一起對暴風之眼的發出攻擊嗎?', '部落不允許德萊尼和他們愛管閒事的聯盟控制在外域裡全部的法力電池。你願意加入血精靈的行列與他們一起對暴風之眼的發出攻擊嗎?', '部落不允許德萊尼和他們愛管閒事的聯盟控制在外域裡全部的法力電池。你願意加入血精靈的行列與他們一起對暴風之眼的發出攻擊嗎?', '部落不允許德萊尼和他們愛管閒事的聯盟控制在外域裡全部的法力電池。你願意加入血精靈的行列與他們一起對暴風之眼的發出攻擊嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10027 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10027, 'zhTW', '你好，$c!你要回報一項飛行任務嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10031 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10031, 'zhTW', '如果你曾到過贊格沼澤，你可能遇到一個名叫丹尼爾的人。你知道的 -- 戴一頂奇怪的盔帽，只會回答「專家」的人。$B$B當然，他知道的一切都是我教的。$B$B不要讓這身華麗的衣服欺騙了你。我內心裡仍然是一名盜賊。丹尼爾和我一同在戰壕中度過許多時光，但是在我退休之前。據我所知，他仍然在外頭，教訓敵人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10032 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10032, 'zhTW', '日復一日，我們只能在這礦坑做苦力。血精靈男性並不是做苦工的料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10039 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10039, 'zhTW', '$N，請確實的將我們的成功轉告加魯。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10040 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10040, 'zhTW', '大使·塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素……但是沒有人願意聽。', '大使·塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素……但是沒有人願意聽。', '塔盧恩大使把我一起帶過來，希望我可以向我們的新夥伴們傳授關於這個世界上的元素的知識……但沒人願意聽。', '大使·塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素……但是沒有人願意聽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10041 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10041, 'zhTW', '讓我靜一靜，$c。我必須致力於我對憂日大使的職責，雖然這些工作是非常單調乏味的。', '讓我靜一靜，$c。我必須致力於我對憂日大使的職責，雖然這些工作是非常單調乏味的。', '離我遠點，$c。我必須要和他們一樣，傻乎乎地保護銀月大使歐諾·炎傷。', '讓我靜一靜，$c。我必須致力於我對憂日大使的職責，雖然這些工作是非常單調乏味的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10042 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10042, 'zhTW', '儘管薩塔的焦點依然著重在影月谷和伊利丹，我們仍然不能忽視凱爾薩斯·逐日者帶來的威脅。', '儘管薩塔的焦點依然著重在影月谷和伊利丹，我們仍然不能忽視凱爾薩斯·逐日者帶來的威脅。', '儘管薩塔的焦點依然著重在影月谷和伊利丹，我們仍然不能忽視凱爾薩斯·逐日者帶來的威脅。', '儘管薩塔的焦點依然著重在影月谷和伊利丹，我們仍然不能忽視凱爾薩斯·逐日者帶來的威脅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10043 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10043, 'zhTW', '大使·塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素。目前沒有人願意聽，但也許你有興趣聽嗎?', '大使·塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素。目前沒有人願意聽，但也許你有興趣聽嗎?', '塔盧恩大使把我一起帶過來，希望我可以向我們的新夥伴們傳授關於這個世界上的元素的知識……但迄今為止他們都拒絕聽這些，也許你願意聽聽？', '大使·塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素。目前沒有人願意聽，但也許你有興趣聽嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10044 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10044, 'zhTW', '我對保護憂日大使感到厭煩，$n。介意跟我談談嗎?或許我們之中有人可以學到一些事情。', '我對保護憂日大使感到厭煩，$n。介意跟我談談嗎?或許我們之中有人可以學到一些事情。', '我對保護銀月大使歐諾·炎傷感到有點厭煩了，$n。你有空和我聊聊嗎？或許我們能彼此學到些什麼？', '我對保護憂日大使感到厭煩，$n。介意跟我談談嗎?或許我們之中有人可以學到一些事情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10045 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10045, 'zhTW', '當你接近控制檯時，你身上的控制水晶發出輕柔的嗡嗡聲以及一陣陣光源的脈動。$B$B一陣訊息突然湧入你的腦海，突然之間你明瞭了法力熔爐的能量生產水準，它的產量穩定以及它透過不同的輸送管運送能源。控制檯等待你的命令。', '當你接近控制檯時，你身上的控制水晶發出輕柔的嗡嗡聲以及一陣陣光源的脈動。$B$B一陣訊息突然湧入你的腦海，突然之間你明瞭了法力熔爐的能量生產水準，它的產量穩定以及它透過不同的輸送管運送能源。控制檯等待你的命令。', NULL, '當你接近控制檯時，你身上的控制水晶發出輕柔的嗡嗡聲以及一陣陣光源的脈動。$B$B一陣訊息突然湧入你的腦海，突然之間你明瞭了法力熔爐的能量生產水準，它的產量穩定以及它透過不同的輸送管運送能源。控制檯等待你的命令。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10047 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10047, 'zhTW', '別碰那件披風!是的，是的，我知道你也想要一件。所有人都想要我的披風。相信我，目前我只是個道德和社會地位低落的人，但是有一天我將靠賣我的披風而賺大錢。從這裡到鐵爐堡的所有人都將知道巴圖羅·吉塞提的名字。吉塞提標籤將成為炙手可熱的商品!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10051 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10051, 'zhTW', '艾德伊恩的工作分成兩部份。首先最重要的是保護教士。再來是找出聖光的敵人並且消滅他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10052 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10052, 'zhTW', '以穆拉丁的鬍子起誓，$c。這塊土地瀕臨毀滅。我不能想像任何人從第二次戰爭結束後能在這裡倖存。', '以穆拉丁的鬍子起誓，$c。這塊土地瀕臨毀滅。我不能想像任何人從第二次戰爭結束後能在這裡倖存。', '透過穆拉丁的公然反抗，$c。這塊土地瀕臨毀滅。我不能想象任何人從第二次戰爭結束後能在這裡倖存。', '以穆拉丁的鬍子起誓，$c。這塊土地瀕臨毀滅。我不能想像任何人從第二次戰爭結束後能在這裡倖存。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10053 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10053, 'zhTW', '(獸人語)你好，$c。這塊破碎的大地就是你想見到的嗎?這和我聽過的故事沒什麼兩樣。很難相信我的人民能在這荒涼的地方茁壯成長。', '(獸人語)你好，$c。這塊破碎的大地就是你想見到的嗎?這和我聽過的故事沒什麼兩樣。很難相信我的人民能在這荒涼的地方茁壯成長。', '(獸人語)你好，$c。這塊破碎的大地就是你想見到的嗎?這和我聽過的故事沒什麼兩樣。很難相信我的人民能在這荒涼的地方茁壯成長。', '(獸人語)你好，$c。這塊破碎的大地就是你想見到的嗎?這和我聽過的故事沒什麼兩樣。很難相信我的人民能在這荒涼的地方茁壯成長。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10054 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10054, 'zhTW', '我正尋找某人幫助我做一項已經過期很久的任務。$B$B你看起來有這能力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10055 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10055, 'zhTW', '你為我在法拉隆廢墟所做的工作已讓我趕上進度。我現在正集合我的部隊前往那邊去。$B$B感謝你，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10056 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10056, 'zhTW', '到處都是燃燒軍團的成員...他們必須解決掉!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10057 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10057, 'zhTW', '感謝你，我們才能繼續我們的法拉隆廢墟計畫。', '感謝你，我們才能繼續我們的法拉隆廢墟計劃。', NULL, '感謝你，我們才能繼續我們的法拉隆廢墟計劃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10058 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10058, 'zhTW', '關於以太族你知道些什麼呢?$B$B你無疑地以相同的標準看我們全部，忘記了在不同派系之間的衝突和爭鬥。$B$B也該是介紹我自己的時候了。我是護國者的指揮官阿密爾 - 也是你在這地區內解決虛無生物和以太皇族充斥的唯一希望。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10059 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10059, 'zhTW', '以太皇族是在我凱瑞西家鄉的統治階級。可悲的是，虛無領主迪曼修斯在世界上釋出他的虛無軍團，並且計畫完全毀滅所有阻礙他的人，在事情發生之前，我們只好被迫撤出凱瑞西。對這種行為，以太皇族發誓要復仇。他們從那以後一直跟蹤迪曼修斯……$B$B然而，護國者並不是一個反對迪曼修斯的團體。我們反對的是以太皇族。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10060 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10060, 'zhTW', '以太皇族已經變得行為墮落……價值觀扭曲。報仇已經成為他們的唯一的寄託，而任何阻礙或者不加入他們行為的人都被當作敵人。很多人看見以太皇族陷入瘋狂並且離開。一些以太皇族議會的奈薩斯王子脫離以太皇族，以不同的目標成立其他團體和派別。聯合團就是因此而生的一個例子。護國者則是另一個……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10061 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10061, 'zhTW', '我們認為到以太皇族對我們的生存造成的威脅和迪曼修斯一樣大。兩者都必須被制止……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10062 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10062, 'zhTW', '嗨。我是維斯頓·急嘯，熱砂戰鬥同盟的正式競技場商人。如果你聲望足夠，我有使你看到流口水的稀世珍寶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10063 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10063, 'zhTW', '如果你想吐的話，與派斯托談話。他也許有暈機藥。', '如果你想吐的話，與派斯托談話。他也許有暈機藥。', '如果你想吐的話，與派斯托談話。他也許有暈機藥。', '如果你想吐的話，與派斯托談話。他也許有暈機藥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10064 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10064, 'zhTW', '<學徒偶爾轉頭看看四周，顯然是對那些你聽不見的聲音所做的反應。>$B$B祝你有美好的一天，$N。如果我看起來好像心不在焉的話請原諒我，因為我正在沉浸在農夫那丁所交待的工作當中。當他從市政廳返回時，我想要把他所有的馬都裝好馬蹄鐵。我能幫上你什麼忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10065 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10065, 'zhTW', '護國者指揮官授權密探亞希克斯和我一項優先處理的重要任務，消滅奧崔斯的所有虛無生物。這本來應該是是戰術上的突襲戰。在返回護國者哨站之前的最後一次突襲，我們的目標是一個名叫阿肯納斯的虛無領主，他的身軀因為吸取當地的生命體而茁壯強大。$B$B可惜，我們到達的太晚。亞希克斯和我在與噬屍獸的激烈交戰中被分開了。現在他被困在裡面，被阻擋在敵軍後方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10066 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10066, 'zhTW', '如果聖光不能指引你的道路，我的朋友，或許我可以幫上忙。你需要什麼?', '如果聖光不能指引你的道路，我的朋友，或許我可以幫上忙。你需要什麼?', '如果聖光不能指引你的道路，我的朋友，或許我可以幫上忙。你需要什麼?', '如果聖光不能指引你的道路，我的朋友，或許我可以幫上忙。你需要什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
