INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10069, 'zhTW', '一定要拜訪在虛空風暴52區的維斯頓·急嘯。身為熱砂戰鬥同盟的正式競技場商人，他有各式各樣難以置信的物品，出售給那些有足夠競技場點數的人。', '一定要拜訪在虛空風暴52區的維斯頓·急嘯。身為熱砂戰鬥同盟的正式競技場商人，他有各式各樣難以置信的物品，出售給那些有足夠競技場點數的人。', '別忘記去拜訪虛空風暴52區的維克斯頓。作為熱砂港搏擊會的官方競技場商人，他出售各種不可思議的物品給那些有著足夠競技場點數的傢伙。', '一定要拜訪在虛空風暴52區的維斯頓·急嘯。身為熱砂戰鬥同盟的正式競技場商人，他有各式各樣難以置信的物品，出售給那些有足夠競技場點數的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
