INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10073, 'zhTW', '範安姆是我們的公會註冊員。他的辦公室已經設立在艾克索達。請沿著道路走;你將立即找到它。', '範安姆是我們的公會註冊員。他的辦公室已經設立在艾克索達。請沿著道路走;你將立即找到它。', '範安姆是我們的公會註冊員。他的辦公室已經設立在艾克索達。請沿著道路走;你將立即找到它。', '範安姆是我們的公會註冊員。他的辦公室已經設立在艾克索達。請沿著道路走;你將立即找到它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
