INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10077, 'zhTW', '德魯伊?這裡沒有人選擇追求德魯伊之路……但是我想我聽說在艾克索達附近有人符合你的描述。我想是薩娜妮斯嗎?', '德魯伊?這裡沒有人選擇追求德魯伊之路……但是我想我聽說在艾克索達附近有人符合你的描述。我想是薩娜妮斯嗎?', '德魯伊?這裡沒有人選擇追求德魯伊之路……但是我想我聽說在艾克索達附近有人符合你的描述。我想是薩娜妮斯嗎?', '德魯伊?這裡沒有人選擇追求德魯伊之路……但是我想我聽說在艾克索達附近有人符合你的描述。我想是薩娜妮斯嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
