INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10078, 'zhTW', '艾克緹昂是我們的獵人代表，同時也是一名精通狩獵的獵人 - 他身上所穿的皮革就是他高超技術的證明。他的營地在藍色守望的東南邊。', '艾克緹昂是我們的獵人代表，同時也是一名精通狩獵的獵人 - 他身上所穿的皮革就是他高超技術的證明。他的營地在藍色守望的東南邊。', '艾克緹昂是我們的獵人代表，同時也是一名精通狩獵的獵人 - 他身上所穿的皮革就是他高超技術的證明。他的營地在藍色守望的東南邊。', '艾克緹昂是我們的獵人代表，同時也是一名精通狩獵的獵人 - 他身上所穿的皮革就是他高超技術的證明。他的營地在藍色守望的東南邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
