INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10085, 'zhTW', '你也是薩滿的一員嗎?嗯。我認為你可以自由地選擇你自己的道路……無論那條道路可能是什麼。塔奴藍在藍色守望的西北有一個孤立的小營地。', '你也是薩滿的一員嗎?嗯。我認為你可以自由地選擇你自己的道路……無論那條道路可能是什麼。塔奴藍在藍色守望的西北有一個孤立的小營地。', '你是個薩滿祭司？嗯，你可以自行決定未來要走的道路……哪條道路都行。圖倫就在碧藍崗哨西北方某處僻靜的小營地裡。', '你也是薩滿的一員嗎?嗯。我認為你可以自由地選擇你自己的道路……無論那條道路可能是什麼。塔奴藍在藍色守望的西北有一個孤立的小營地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
