INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10094, 'zhTW', '一個有抱負的釣魚者……嗯，狄克泰納住在安曼淺灘的岸上，用她的網和釣魚竿持續提供我們所需。我肯定她能幫助你。', '一個有抱負的釣魚者……嗯，狄克泰納住在安曼淺灘的岸上，用她的網和釣魚竿持續提供我們所需。我肯定她能幫助你。', '一個有抱負的釣魚者……嗯，狄克泰納住在安曼淺灘的岸上，用她的網和釣魚竿持續提供我們所需。我肯定她能幫助你。', '一個有抱負的釣魚者……嗯，狄克泰納住在安曼淺灘的岸上，用她的網和釣魚竿持續提供我們所需。我肯定她能幫助你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
