INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10095, 'zhTW', '赫爾從我們的到達起已經著手於研究本地植物。他能指引你的道路。你能發現他在藍色守望西部邊緣上與爹達歐一起工作。', '赫爾從我們的到達起已經著手於研究本地植物。他能指引你的道路。你能發現他在藍色守望西部邊緣上與爹達歐一起工作。', '赫爾從我們的到達起已經著手於研究本地植物。他能指引你的道路。你能發現他在藍色守望西部邊緣上與爹達歐一起工作。', '赫爾從我們的到達起已經著手於研究本地植物。他能指引你的道路。你能發現他在藍色守望西部邊緣上與爹達歐一起工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
