INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10097, 'zhTW', '杜維是你想找的人。她在藍色守望中間訓練採礦者。', '杜維是你想找的人。她在藍色守望中間訓練採礦者。', '去找杜爾維。她在崗哨的中間傳授著勘測礦藏的技能。', '杜維是你想找的人。她在藍色守望中間訓練採礦者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
