INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10098, 'zhTW', '前往靜松要塞吧，我的朋友。那裡的熊怪提供非常大的幫助，並且他們可能正好有你需要的專門技能。', '前往靜松要塞吧，我的朋友。那裡的熊怪提供非常大的幫助，並且他們可能正好有你需要的專門技能。', '前往靜松要塞吧，我的朋友。那裡的熊怪提供非常大的幫助，並且他們可能正好有你需要的專門技能。', '前往靜松要塞吧，我的朋友。那裡的熊怪提供非常大的幫助，並且他們可能正好有你需要的專門技能。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
