INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10099, 'zhTW', '藍色守望這裡沒有裁縫師。但是，你可以去海灘上的營地找找看 - 他們有許多從海外來經商的訓練師。', '藍色守望這裡沒有裁縫師。但是，你可以去海灘上的營地找找看 - 他們有許多從海外來經商的訓練師。', '藍色守望這裡沒有裁縫師。但是，你可以去海灘上的營地找找看 - 他們有許多從海外來經商的訓練師。', '藍色守望這裡沒有裁縫師。但是，你可以去海灘上的營地找找看 - 他們有許多從海外來經商的訓練師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
