INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10100, 'zhTW', '找一位珠寶工匠嗎?我們的珠寶設計師在艾克索達，使用他們發現的天然寶石加工成華麗炫目的珠寶。在你抵達之後可以與法芮談談。', '找一位珠寶工匠嗎?我們的珠寶設計師在艾克索達，使用他們發現的天然寶石加工成華麗炫目的珠寶。在你抵達之後可以與法芮談談。', '在找寶石工匠嗎？埃索達的珠寶匠們用雙手雕琢出精美的工藝品，到那邊找法裡談談吧。', '找一位珠寶工匠嗎?我們的珠寶設計師在艾克索達，使用他們發現的天然寶石加工成華麗炫目的珠寶。在你抵達之後可以與法芮談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10101 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10101, 'zhTW', '你想要什麼?!我聽到某些事情關於英雄谷裡其中一隻古怪的德萊尼生物。或許她知道；我不清楚。', '你想要什麼?!我聽到某些事情關於英雄谷裡其中一隻古怪的德萊尼生物。或許她知道；我不清楚。', '你想要什麼?!我聽到某些事情關於英雄谷裡其中一隻古怪的德萊尼生物。或許她知道；我不清楚。', '你想要什麼?!我聽到某些事情關於英雄谷裡其中一隻古怪的德萊尼生物。或許她知道；我不清楚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10103 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10103, 'zhTW', '水之靈已經離開我們。我們的部族厄運臨頭了。', '水之靈已經離開我們。我們的部族厄運臨頭了。', '水之靈已經離開我們。我們的部族厄運臨頭了。', '水之靈已經離開我們。我們的部族厄運臨頭了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
