INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10104, 'zhTW', '風已經不再跟我們的族人耳語了，$N。我的族人迷失了，我們需要長老將精靈們帶回部族。', '風已經不再跟我們的族人耳語了，$N。我的族人迷失了，我們需要長老將精靈們帶回部族。', '風已經不再跟我們的族人耳語了，$N。我的族人迷失了，我們需要長老將精靈們帶回部族。', '風已經不再跟我們的族人耳語了，$N。我的族人迷失了，我們需要長老將精靈們帶回部族。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10105 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10105, 'zhTW', '這些綁住我的鎖鏈阻止我把火焰之靈帶到我的族人那裡，$N。一個缺少火的靈魂是不能反抗主人的靈魂。', '這些綁住我的鎖鏈阻止我把火焰之靈帶到我的族人那裡，$N。一個缺少火的靈魂是不能反抗主人的靈魂。', '這些綁住我的鎖鏈阻止我把火焰之靈帶到我的族人那裡，$N。一個缺少火的靈魂是不能反抗主人的靈魂。', '這些綁住我的鎖煉阻止我把火焰之靈帶到我的族人那裡，$N。一個缺少火的靈魂是不能反抗主人的靈魂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10106 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10106, 'zhTW', '我聽說有兩個蠻錘的薩滿到了矮人區，所以你可以到那碰碰運氣。$B$B曾經待在英雄谷的德萊尼先知也已經去見他們了。', '我聽說有兩個蠻錘的薩滿到了矮人區，所以你可以到那碰碰運氣。$B$B曾經待在英雄谷的德萊尼先知也已經去見他們了。', '我不知道你為什麼要去找一個薩滿祭司……但是我看到過一個很符合你的描述的人，英雄谷的岸邊有個自稱為先知的女人。', '我不知道什麼原因使你急著想找一名薩滿……但是我曾經見過與你的描述相符的人。在英雄谷的岸邊有一個女人稱自己為先知。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10107 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10107, 'zhTW', '我們不像聖騎士。精靈女士來到城市，待在皇家區。她的聖騎士。你說，學習聖騎士東西。', '我們不像聖騎士。精靈女士來到城市，待在皇家區。她的聖騎士。你說，學習聖騎士東西。', '我們不喜歡聖騎士。女精靈來到城市，在皇家區。她是聖騎士，和她說話，學習聖騎士的東西。', '我們不像聖騎士。精靈女士來到城市，待在皇家區。她的聖騎士。你說，學習聖騎士東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10108 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10108, 'zhTW', '聖騎士?你有沒有參與藥劑師會議或者其他相關的呢?我聽說某支精靈分隊前往拜訪幽暗城的黑暗女王。也許他們之中有人會知情。', '聖騎士?你有沒有參與藥劑師會議或者其他相關的呢?我聽說某支精靈分隊前往拜訪幽暗城的黑暗女王。也許他們之中有人會知情。', '聖騎士?你有沒有參與藥劑師會議或者其他相關的呢?我聽說某支精靈分隊前往拜訪幽暗城的黑暗女王。也許他們之中有人會知情。', '聖騎士?你有沒有參與藥劑師會議或者其他相關的呢?我聽說某支精靈分隊前往拜訪幽暗城的黑暗女王。也許他們之中有人會知情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10109 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10109, 'zhTW', '你的幫助是無價的，我的朋友。$B$B我能向你保證，塞納里奧遠征隊將用一切的力量反擊任何未來被伊利丹從天空降下的汙染水晶。', '你的幫助是無價的，我的朋友。$B$B我能向你保證，塞納里奧遠征隊將用一切的力量反擊任何未來被伊利丹從天空降下的汙染水晶。', '你的幫助是無價的，我的朋友。$B$B我敢保證塞納里奧遠征隊會傾盡全力來抵抗伊利丹從天空中丟下來的任何汙染水晶。', '你的幫助是無價的，我的朋友。$B$B我能向你保證，塞納里奧遠征隊將用一切的力量反擊任何未來被伊利丹從天空降下的汙染水晶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10113 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10113, 'zhTW', '這是卡拉贊高塔，同時也是我的主人，麥迪文的住宅。作為一名謙卑的看門人，主人的事情我從不敢過問。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10114 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10114, 'zhTW', '關於麥迪文的所有問題應該去問哨塔服務員，摩洛。小的對主人的事情所知有限。如果你希望更進一步詢問的話，我相信有幾名貴族目前正在宴會大廳與摩洛交談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10115 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10115, 'zhTW', '從警衛站這裡，你可以選擇從3個方向之一前往。在我後面的樓梯通向華麗的跳舞大廳，那裡目前正在招待客人。我相信你也聞到了附近的獸欄，而通往傭人區的入口緊接著警衛站的大門。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10117 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10117, 'zhTW', '午夜是獵人阿圖曼的個人坐騎。我從未看過一隻比它更迅速，更強壯，或者脾氣更暴躁的馬。而且騎乘她的主人更加的喜怒無常!所有人都與她儘量保持距離，免得頭上無端多了個午夜的蹄印，或者是被阿圖曼一陣毒打。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10118 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10118, 'zhTW', '傭人區住著該死的蜘蛛、總是在尖嘯的蝙蝠和那些被詛咒的惡魔般的野獸。在該區走動已不再安全，特別是有大隻的怪物從潛藏處撲向你的時候。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10119 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10119, 'zhTW', '對了，我從未親眼看過他們，但是有時候我會在遠方聽見他們的聲音。如果你在裡面冒險，睜大眼睛注意它們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10120 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10120, 'zhTW', '我沒有時間陪你閒聊。我還要訓練一堆人，以及守護一座哨塔。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10122 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10122, 'zhTW', '你好!瞧這把羅德隆最好的樂器之一。能夠為主人和他的貴賓演奏是無上的光榮。在觀眾席找個位置坐，我聽說表演不久將開始。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10123 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10123, 'zhTW', '這個派對是毫無意義的。那些愚蠢的貴族絕不會看到麥迪文的。他們看不出來嗎?我本應該與我的家人待在夜色鎮，而不是在這裡浪費我的時間。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10124 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10124, 'zhTW', '就在這裡...的某個地方...我知道的。在這座圖書館的某處有我正在尋找的知識...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10125 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10125, 'zhTW', '這座塔簡直是完全建給瘋子住的地方。這不是一座圖書館，這是一座巨大的舊書攤，而我看這裡的書多到連針都插不進去!對了，我來這邊是要做什麼?', '這座塔簡直是完全建給瘋子住的地方。這不是一座圖書館，這是一座巨大的舊書攤，而我看這裡的書多到連針都插不進去!對了，我來這邊是要做什麼?', '這座塔完全陷入了瘋狂。這不是個圖書館，只是個巨大的書堆，而我不覺得這裡有我要找的東西！既然這樣，我以前都在幹什麼？', '這座塔簡直是完全建給瘋子住的地方。這不是一座圖書館，這是一座巨大的舊書攤，而我看這裡的書多到連針都插不進去!對了，我來這邊是要做什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10126 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10126, 'zhTW', '你在這裡會影響我做一項重要的工作。請立刻離開。對了，我又做到哪了?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10127 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10127, 'zhTW', '啊，想不到在這麼奇怪的地方可以找到潛在的客戶!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10128 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10128, 'zhTW', '等等$C！你想要找下一個BOSS可不能能夠這麼來，你該嘗試別的途徑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10152 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10152, 'zhTW', '你好，老百姓。我是納巫德，護國者哨站的首席研究員。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10153 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10153, 'zhTW', '離開凱爾薩斯是我們最正確的決定。他的跟隨者過於盲目或者畏懼而不能瞭解凱爾薩斯的真正目的。$B$B不過，我們卻不是。', '離開凱爾薩斯是我們最正確的決定。他的跟隨者過於盲目或者畏懼而不能瞭解凱爾薩斯的真正目的。$B$B不過，我們卻不是。', '離開凱爾薩斯是我們最正確的決定。他的跟隨者過於盲目或者畏懼而不能瞭解凱爾薩斯的真正目的。$b$b不過，我們卻不是。', '離開凱爾薩斯是我們最正確的決定。他的跟隨者過於盲目或者畏懼而不能瞭解凱爾薩斯的真正目的。$B$B不過，我們卻不是。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10178 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10178, 'zhTW', '有些人的天性喜愛編織謊言與歪曲事實。另一方面，先知將真相攤在陽光之下。$B$B這座圖書館的宗旨，$N，就是使每一個人都能成為一名先知。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10179 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10179, 'zhTW', '在以太族中，某些成員特別喜歡處理肉塊和生物的血肉之軀。那些人被稱為血肉處理者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10180 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10180, 'zhTW', '你在我們美好的大地尋找什麼嗎?', '你在我們美好的大地尋找什麼嗎?', '你在我們美好的大地尋找什麼嗎?', '你在我們美好的大地尋找什麼嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10181 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10181, 'zhTW', '女飛行師·薄暮站在博學者之門的外邊靠近銀月城，照顧龍鷹。', '女飛行師·薄暮站在博學者之門的外邊靠近銀月城，照顧龍鷹。', '葛拉米就站在影月城的魔導師之門外，她管理著龍鷹。', '女飛行師·薄暮站在博學者之門的外邊靠近銀月城，照顧龍鷹。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
