INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10183, 'zhTW', '德拉尼歐在獵鷹之翼廣場的東南角落妥善的經營她的旅館。美味的食物，香醇的美酒，柔軟的床……你還能找到更好的旅館嗎?', '德拉尼歐在獵鷹之翼廣場的東南角落妥善的經營她的旅館。美味的食物，香醇的美酒，柔軟的床……你還能找到更好的旅館嗎?', '德蘭妮爾經營著她那個設在鷹翼廣場東南角的旅店。美酒佳餚，還有柔軟的床……夫復何求？', '德拉尼歐在獵鷹之翼廣場的東南角落妥善的經營她的旅館。美味的食物，香醇的美酒，柔軟的床……你還能找到更好的旅館嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
