INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10184, 'zhTW', '有些遊俠似乎無法應付心中野獸般的慾望操控著他們的意志。如果你只是想在城鎮內製止這種事情，安納斯會接手的。她在獵鷹之翼廣場的旅館外頭等著工作上門。', '有些遊俠似乎無法應付心中野獸般的慾望操控著他們的意志。如果你只是想在城鎮內製止這種事情，安納斯會接手的。她在獵鷹之翼廣場的旅館外頭等著工作上門。', '有些獵人們似乎無法看管好他們自己的野獸。如果你必須找個地方把野獸暫時圈養起來，阿娜索絲可以幫忙。她就在鷹翼廣場的旅館外面工作。', '有些遊俠似乎無法應付心中野獸般的慾望操控著他們的意志。如果你只是想在城鎮內製止這種事情，安納斯會接手的。她在獵鷹之翼廣場的旅館外頭等著工作上門。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
