INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10187, 'zhTW', '卡綠笛在獵鷹之翼廣場裡教導魔法的奧秘;你可以在旅館的二樓找到她。', '卡綠笛在獵鷹之翼廣場裡教導魔法的奧秘;你可以在旅館的二樓找到她。', '加琳黛爾在鷹翼廣場內傳授奧術魔法之道，你可以在旅店二樓找到她。', '卡綠笛在獵鷹之翼廣場裡教導魔法的奧秘;你可以在旅館的二樓找到她。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
