INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10193, 'zhTW', '我知道一名本地的鏈金師。雪納倫，我相信這是他的名字。上次我見到他的時候，他正前往薩瑟裡的避風港，一定是去參加一個他那可笑的聚會。', '我知道一名本地的鏈金師。雪納倫，我相信這是他的名字。上次我見到他的時候，他正前往薩瑟裡的避風港，一定是去參加一個他那可笑的聚會。', '我認識一位本地的鍊金師。森納瑟林，應該是這個名字。當我最後一次看到他的時候，他正在前往薩瑟利爾莊園，毫無疑問，他是去參加一場可笑的聚會。', '我知道一名本地的鍊金師。雪納倫，我相信這是他的名字。上次我見到他的時候，他正前往薩瑟裡的避風港，一定是去參加一個他那可笑的聚會。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
