INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10200, 'zhTW', '誰能比植物學家泰尼阿瑞歐更會照顧滿屋子的花?如果有這種人我想薩瑟裡會請他喝酒。', '誰能比植物學家泰尼阿瑞歐更會照顧滿屋子的花?如果有這種人我想薩瑟裡會請他喝酒。', '誰能比植物學家塔尼安雷爾更擅長佈置晚會的鮮花布景？我相信薩瑟利爾男爵會用酒來報答他的。', '誰能比植物學家泰尼阿瑞歐更會照顧滿屋子的花?如果有這種人我想薩瑟裡會請他喝酒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
