INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10203, 'zhTW', '我們的居民珠寶設計師，阿蕾妮雅，可在獵鷹之翼廣場的德拉尼歐旅店裡找到。她可能正在尋找一個學徒。', '我們的居民珠寶設計師，阿蕾妮雅，可在獵鷹之翼廣場的德拉尼歐旅店裡找到。她可能正在尋找一個學徒。', '我們的居民珠寶設計師，阿蕾妮雅，可在獵鷹之翼廣場的德拉尼歐旅店裡找到。她可能正在尋找一個學徒。', '我們的居民珠寶設計師，阿蕾妮雅，可在獵鷹之翼廣場的德拉尼歐旅店裡找到。她可能正在尋找一個學徒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
