INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10204, 'zhTW', '莎希恩發現藏在永歌森林的山貓對他的創作很有幫助。你可以去跟他交談 - 他跟瑪斯莉安正好站在博學者之門的西南方。', '莎希恩發現藏在永歌森林的山貓對他的創作很有幫助。你可以去跟他交談 - 他跟瑪斯莉安正好站在博學者之門的西南方。', '薩瑟林在永歌森林找到的山貓皮很適合他的作品。你應該和他談談——他就站在魔導師之門西南的瑪斯雷恩旁邊。', '莎希恩發現藏在永歌森林的山貓對他的創作很有幫助。你可以去跟他交談 - 他跟瑪斯莉安正好站在博學者之門的西南方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
