INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10206, 'zhTW', '瑪斯莉安擅長於剝皮的野蠻工作，如果那真的是你所追尋的。他供應莎希恩皮革;你可以在博學者之門的西南方找到他們倆。', '瑪斯莉安擅長於剝皮的野蠻工作，如果那真的是你所追尋的。他供應莎希恩皮革;你可以在博學者之門的西南方找到他們倆。', '如果你真能習慣的話，瑪斯雷恩對野蠻的剝皮工作很在行。他在為薩瑟林提供皮料，你可以在魔導師之門的東南找到他們倆。', '瑪斯莉安擅長於剝皮的野蠻工作，如果那真的是你所追尋的。他供應莎希恩皮革;你可以在博學者之門的西南方找到他們倆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
