INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10209, 'zhTW', '在不同的時間和地點我可能只是一個沒經驗的小兵。但現在我是一位經驗豐富的戰士，為了那魯的榮譽而活，為了那魯的榮譽而死。$B$B我們之中的十位進入法力熔爐艾拉。其他人致力於對付燃燒軍團。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
