INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10236, 'zhTW', '你想不想來這裡，讓你自己成為有用的人，因為在那裡的巡影者做得不夠多。', '你想不想來這裡，讓你自己成為有用的人，因為在那裡的巡影者做得不夠多。', '如果你想從這裡出去的話，就得自己努力，那邊的巡影者什麼忙都幫不上。', '你想不想來這裡，讓你自己成為有用的人，因為在那裡的巡影者做得不夠多。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10237 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10237, 'zhTW', '海加爾山戰役是時間線中保護得最好的事件之一。如果一名入侵者改變它的結果，影響將會波及歷史上所有後續的關鍵發展。$B$B身為時間最好的夥伴，我比其他青銅龍更協調於時間流。我最近感覺到從圍繞海加爾山戰役的事件裡散發出片刻的時間漣漪。有人或者某些東西正試圖改變這條時間線，他們必須被制止。', '海加爾山戰役是時間線中保護得最好的事件之一。如果一名入侵者改變它的結果，影響將會波及歷史上所有後續的關鍵發展。$B$B身為時間最好的夥伴，我比其他青銅龍更協調於時間流。我最近感覺到從圍繞海加爾山戰役的事件裡散發出片刻的時間漣漪。有人或者某些東西正試圖改變這條時間線，他們必須被制止。', '海加爾山戰役是時間線中保護得最好的事件之一。如果一名入侵者改變它的結果，影響將會波及歷史上所有後續的關鍵發展。$b$b身為時間最好的夥伴，我比其它青銅龍更協調於時間流。我最近感覺到從圍繞海加爾山戰役的事件裡散發出片刻的時間漣漪。有人或者某些東西正試圖改變這條時間線，他們必須被制止。', '海加爾山戰役是時間線中保護得最好的事件之一。如果一名入侵者改變它的結果，影響將會波及歷史上所有後續的關鍵發展。$B$B身為時間最好的夥伴，我比其他青銅龍更協調於時間流。我最近感覺到從圍繞海加爾山戰役的事件裡散發出片刻的時間漣漪。有人或者某些東西正試圖改變這條時間線，他們必須被制止。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
