INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10239, 'zhTW', '你有什麼目的?大聲說。我不會把我的任何伊萊克託付給你，直到你證明你對我們族人的奉獻和友誼。', '你有什麼目的?大聲說。我不會把我的任何伊萊克託付給你，直到你證明你對我們族人的奉獻和友誼。', '你想要什麼？說出來，在你可以證明你的貢獻和與你和我們的友誼之前，我不準備雷象賣給你。', '你有什麼目的?大聲說。我不會把我的任何伊萊克託付給你，直到你證明你對我們族人的奉獻和友誼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10245 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10245, 'zhTW', '我們在生命之林裡的工作瀕臨斷絕。我們的生命決定於它延續的健康和成長。', '我們在生命之林裡的工作瀕臨斷絕。我們的生命決定於它延續的健康和成長。', '我們在活木林的工作不能受到打擾。活木林持續與健康的成長決定了我們的命運。', '我們在生命之林裡的工作瀕臨斷絕。我們的生命決定於它延續的健康和成長。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10246 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10246, 'zhTW', '假如你還沒拿到，請確認你對琳娜·月泉提供了協助。', '去問問莉娜?月泉有什麼需要你幫助的事情吧。', '去問問莉娜·月泉有什麼需要你幫助的事情吧。', '假如你還沒拿到，請確認你對琳娜·月泉提供了協助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10247 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10247, 'zhTW', '如果我聽到的沒錯，你已經為希爾瓦納完成了令人滿意的工作。$B$B保持下去，或許我們能夠把家留在這裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10249 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10249, 'zhTW', '漫遊者，去休息吧。我們的火堆就是你的。', '漫遊者，去休息吧。我們的火堆就是你的。', '流浪者，去休息吧。我們的就是你的。', '漫遊者，去休息吧。我們的火堆就是你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10250 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10250, 'zhTW', '古爾丹就是在這裡切斷獸人和元素之靈間的聯絡。他對力量的那種無法抑制的渴望無法由徹底消滅德萊尼來得到滿足。他還得毀掉德拉諾，夷平土地並且汲取它所有的能量供給他的戰爭使用。$B$現在所剩下的都是他瘋狂行徑的殘餘。$B$B看看這個祭壇，$r - 這片大地永遠被困著...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10251 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10251, 'zhTW', '我在古老崇敬的薩滿傳統裡尊敬我的祖先。我們絕不能忘記他們的犧牲造就今日我們能夠在這裡生存。$B$B同樣的，我們也得做出必要的犧牲讓我們的子孫能有個未來。$B$B什麼將你帶到我這裡，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10252 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10252, 'zhTW', '不久之前我們必須從附近的巨魔手中將雷霆王村的控制權奪過來。$B$B你是來這裡幫助我們維持我們的防禦嗎?我知道葛德雷克正在尋求協助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10253 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10253, 'zhTW', '你覺得戰爭怎麼樣，$N?只要記得我們為什麼在這裡...那就是戰鬥，以及死亡的原因，會容易得多。', '你覺得戰爭怎麼樣，$N?只要記得我們為什麼在這裡……那就是戰鬥，以及死亡的原因，會容易得多。', '你覺得戰爭怎麼樣，$N?只要記得我們為什麼在這裡……那就是戰鬥，以及死亡的原因，會容易得多。', '你覺得戰爭怎麼樣，$N?只要記得我們為什麼在這裡……那就是戰鬥，以及死亡的原因，會容易得多。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10254 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10254, 'zhTW', '在那魯之座有兩個郵箱︰一個緊鄰銀行，而另一個在拍賣場外面。', '在那魯之座有兩個郵箱︰一個緊鄰銀行，而另一個在拍賣場外面。', '在那魯之座有兩個郵箱∶一個緊鄰銀行，而另一個在拍賣場外面。', '在那魯之座有兩個郵箱∶一個緊鄰銀行，而另一個在拍賣場外面。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10255 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10255, 'zhTW', '遠征隊哨塔是一個可以駐紮的堅固之地，但當務之急是保護榮譽堡。這裡資訊的收集，以及我們計程車兵對抗軍團和薩斯葛爾獸人所做的戰鬥，對聯盟的地獄火戰役來說是無價的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10256 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10256, 'zhTW', '我聽說你已經開始在這附近盡一份力了。$B$B很好。我擔心我們得要〝說服〞你來幫忙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
