INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10264, 'zhTW', '很高興看見一位$r，例如你本人一樣，為了希爾瓦納的安寧有所奉獻。我們在非常短的時間內做了很多事，但是圍繞我們的力量卻威脅著我們的生活模式。$B$B我會傾聽你說得話。說出你的想法吧，$c。', '很高興看見一位$r，例如你本人一樣，為了希爾瓦納的安寧有所奉獻。我們在非常短的時間內做了很多事，但是圍繞我們的力量卻威脅著我們的生活模式。$b$b我會傾聽你說得話。說出你的想法吧，$c。', '很高興看見一位$r，例如你本人一樣，為了希爾瓦納的安寧有所奉獻。我們在非常短的時間內做了很多事，但是圍繞我們的力量卻威脅著我們的生活模式。$b$b我會傾聽你說得話。說出你的想法吧，$c。', '很高興看見一位$r，例如你本人一樣，為了希爾瓦納的安寧有所奉獻。我們在非常短的時間內做了很多事，但是圍繞我們的力量卻威脅著我們的生活模式。$B$B我會傾聽你說得話。說出你的想法吧，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10266 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10266, 'zhTW', '歡迎到塞納里奧避難所，$n。我接到指示要提供基本的補給品供你購買，你應該會有需要。', '歡迎到塞納里奧避難所，$n。我接到指示要提供基本的補給品供你購買，你應該會有需要。', '歡迎到塞納-馬恩省里奧避難所，$n。我接到指示要提供基本的補給品供你購買，你應該會有需要。', '歡迎到塞納里奧避難所，$n。我接到指示要提供基本的補給品供你購買，你應該會有需要。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
