INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10270, 'zhTW', '作為探險者協會的代表，布朗尼恩和我受命於聯盟在這裡研究這些山。$B$B但你和我之間，在希利蘇斯待了這麼長一段時間之後，我們只需要一個假期。這好像是一個很好的地點。', '作為探險者協會的代表，布朗尼恩和我受命於聯盟在這裡研究這些山。$b$b但你和我之間，在希利蘇斯待了這麼長一段時間之後，我們只需要一個假期。這好像是一個很好的地點。', '作為探險者協會的代表，布朗尼恩和我受命於聯盟在這裡研究這些山。$b$b但你和我之間，在希利蘇斯待了這麼長一段時間之後，我們只需要一個假期。這好像是一個很好的地點。', '作為探險者協會的代表，布朗尼恩和我受命於聯盟在這裡研究這些山。$B$B但你和我之間，在希利蘇斯待了這麼長一段時間之後，我們只需要一個假期。這好像是一個很好的地點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10271 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10271, 'zhTW', '波爾葛利姆也許是對的。或許我們真的需要休息一下。$B$B但是既然我們在這裡，我急切的想要搞髒我的手並研究一下這塊土地能夠提供什麼。', '波爾葛利姆也許是對的。或許我們真的需要休息一下。$B$B但是既然我們在這裡，我急切的想要搞髒我的手並研究一下這塊土地能夠提供什麼。', NULL, '波爾葛利姆也許是對的。或許我們真的需要休息一下。$B$B但是既然我們在這裡，我急切的想要搞髒我的手並研究一下這塊土地能夠提供什麼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10272 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10272, 'zhTW', '$N，我很高興見到你。我們的矮人盟友在奧特蘭克山谷需要我們的幫助。你能幫助他們嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10275 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10275, 'zhTW', '洛薩之子一直進行著一場無止盡的戰爭。我很訝異我們將裝備維持得完好如初!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10276 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10276, 'zhTW', '即使現在，自願的不死族仍在阿拉希盆地與阿拉索聯軍對抗。你會幫助汙染者戰勝人類及他們的聯盟盟友嗎?', '即使現在，自願的不死族仍在阿拉希盆地與阿拉索聯軍對抗。你會幫助汙染者戰勝人類及他們的聯盟盟友嗎?', '即使現在，自願的不死族仍在阿拉希盆地與阿拉索聯軍對抗。你會幫助汙染者戰勝人類及他們的聯盟盟友嗎?', '即使現在，自願的不死族仍在阿拉希盆地與阿拉索聯軍對抗。你會幫助汙染者戰勝人類及他們的聯盟盟友嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10277 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10277, 'zhTW', '(獸人語)你好，$N。戰歌峽谷需要像你這樣的英雄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10278 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10278, 'zhTW', '我們聯盟的盟友正在協助阿拉索聯軍保衛阿拉希盆地。他們能借用你的幫助來對抗不死族的汙染者，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10279 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10279, 'zhTW', '我們在聯盟的朋友聚集一起並肩對抗戰歌峽谷的銀翼哨兵。你會前往那裡去幫助他們嗎?', '我們在聯盟的朋友聚集一起並肩對抗戰歌峽谷的銀翼哨兵。你會前往那裡去幫助他們嗎?', '我們的盟友仍然在戰歌峽谷的銀翼崗哨與敵方作戰。去助他們一臂之力如何？', '我們在聯盟的朋友聚集一起並肩對抗戰歌峽谷的銀翼哨兵。你會前往那裡去幫助他們嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10280 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10280, 'zhTW', '你好，旅人。我是歐朗諾克。請坐在火旁，溫暖一下。$B$B小心我們下方破碎暗礁的貪婪野獸!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10282 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10282, 'zhTW', '不要忘記，$c，戰鬥仍然在艾澤拉斯激烈進行著。你會回來幫助在奧特蘭克山谷的部落嗎?', '不要忘記，$c，戰鬥仍然在艾澤拉斯激烈進行著。你會回來幫助在奧特蘭克山谷的部落嗎?', NULL, '不要忘記，$c，戰鬥仍然在艾澤拉斯激烈進行著。你會回來幫助在奧特蘭克山谷的部落嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10283 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10283, 'zhTW', '(獸人語)你好，$c。你知道我們與銀翼哨兵在戰歌峽谷的戰鬥還在繼續嗎?那裡將會歡迎你的出現……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10284 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10284, 'zhTW', '我已經走了很遠就為了尋找一個可以在阿拉希盆地裡戰勝阿拉索聯軍大使的最終方法，但是那名穿鐵衣的笨蛋亞當·伊特納姆緊追著我一切的行動。$B$B$B儘管如此，如果像你們這樣的殺戮者回到艾澤拉斯，也許我們終可戰勝聯盟!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10285 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10285, 'zhTW', '你好嗎?在外域有填飽你的肚子，並準備好回到奧特蘭克山谷給部落點顏色瞧瞧嗎?', '你好嗎?在外域有填飽你的肚子，並準備好回到奧特蘭克山谷給部落點顏色瞧瞧嗎?', '你好嗎?在外域有填飽你的肚子，並準備好回到奧特蘭克山谷給部落點顏色瞧瞧嗎?', '你好嗎?在外域有填飽你的肚子，並準備好回到奧特蘭克山谷給部落點顏色瞧瞧嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10286 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10286, 'zhTW', '銀翼哨兵仍然在戰歌峽谷跟部落作戰，$c。要是你回到那裡去幫助他們，結果會是怎樣都還不知道。', '銀翼哨兵仍然在戰歌峽谷跟部落作戰，$c。要是你回到那裡去幫助他們，結果會是怎樣都還不知道。', '銀翼哨兵仍然在戰歌峽谷跟部落作戰，$c。要是你回到那裡去幫助他們，結果會是怎樣都還不知道。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10287 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10287, 'zhTW', '我前來外域希望能發現強大的古器以協助阿拉索聯軍對抗阿拉希盆地裡的汙染者……但是我所找到的所有東西就是這種砸碎的魔法纏腰，一個可笑的地精夥伴，和一個自私的不死巡者，堅持我偷了他的灰色頭顱，或是一些那樣的東西。$B$B$B無論如何，在我繼續我的搜尋時，你願意加入聯軍他們的戰鬥嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10288 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10288, 'zhTW', '<有人感覺到歐力克在這裡只是一種喜劇舒緩的可悲意圖而且不需要多加註意，因為這隻會鼓勵他而已。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10290 AND `Locale` = 'zhTW';
