DELETE FROM `npc_text_locale` WHERE `ID` = 10291 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10291, 'zhTW', '只有法師才能學習傳送門的法術，$c。', '只有法師才能學習傳送門的法術，$c。', '只有法師才能學習傳送門的法術，$c。', '只有法師才能學習傳送門的法術，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10292 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10292, 'zhTW', '一個法師...你想要學習傳送門的法術，是嗎?', '一個法師...你想要學習傳送門的法術，是嗎?', '法師……你想學習傳送魔法，是嗎？', '一個法師……你想要學習傳送門的法術，是嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10293 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10293, 'zhTW', '幽暗城的皇家藥劑師學會積極要援助我們在外域的獸人盟友。這是一個強化我們的團結性以及發現可以進行研究的新種類及混合物的機會。$B$B混合物...比如說毒藥。', '幽暗城的皇家藥劑師學會積極要援助我們在外域的獸人盟友。這是一個強化我們的團結性以及發現可以進行研究的新種類及混合物的機會。$B$B混合物...比如說毒藥。', '幽暗城的皇家藥劑師學會積極要援助我們在外域的獸人盟友。這是一個強化我們的團結性以及發現可以進行研究的新種類及混合物的機會。$b$b混合物……比如說毒藥。', '幽暗城的皇家藥劑師學會積極要援助我們在外域的獸人盟友。這是一個強化我們的團結性以及發現可以進行研究的新種類及混合物的機會。$B$B混合物……比如說毒藥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10299 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10299, 'zhTW', '白沙崗哨對我來說就像是個意外的一站，溫和的放下它。我的客戶正指望我運送達我的貨品，我開始懷疑我是否可以在所有的耽擱下把東西即時送達。', '白沙崗哨對我來說就像是個意外的一站，溫和的放下它。我的客戶正指望我運送達我的貨品，我開始懷疑我是否可以在所有的耽擱下把東西即時送達。', '白沙崗哨對我來說就像是個意外的一站，溫和的放下它。我的客戶正指望我運送達我的貨品，我開始懷疑我是否可以在所有的耽擱下把東西即時送達。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10300 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10300, 'zhTW', '喂，不要開啟籠子!好嗎?$B$B那些巨魔將我放在我要他們放的地方了。', '喂，不要開啟籠子!好嗎?$B$B那些巨魔將我放在我要他們放的地方了。', '嘿，不要開啟那些籠子，好嗎？\n我就想讓食人魔把我放在這個籠子裡。', '喂，不要開啟籠子!好嗎?$B$B那些巨魔將我放在我要他們放的地方了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10301 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10301, 'zhTW', '我聽說地獄火半島的灰塵和熱度十分令人煩燥...我不知道，不過我會相信我那受人尊敬，還活著著的生命，盟友。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10302 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10302, 'zhTW', '遺忘元素制皮不是件容易的事。如果你選擇遺忘它，你也會忘記所有需要元素制皮的方法!', '遺忘元素制皮不是件容易的事。如果你選擇遺忘它，你也會忘記所有需要元素制皮的方法!', '遺忘元素制皮可不是說著玩的。如果你選擇放棄它，你同樣會忘記所有需要元素制皮專精的圖樣！', '遺忘元素制皮不是件容易的事。如果你選擇遺忘它，你也會忘記所有需要元素制皮的方法!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10305 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10305, 'zhTW', '你在這裡將無法購買陸行鷹直到你證明了你的價值及對我們族人的貢獻。$B$B$B不要回來直到你在血精靈之間擁有崇拜的聲望。離去吧!', '你在這裡將無法購買陸行鷹直到你證明了你的價值及對我們族人的貢獻。$B$B$B不要回來直到你在血精靈之間擁有崇拜的聲望。離去吧!', '在你向我們人民的證明了你的價值和貢獻前，你是不能在這裡購買陸行鳥的。\n在你被血精靈們崇拜前請不要回來。走開！', '你在這裡將無法購買路行鷹直到你證明了你的價值及對我們族人的貢獻。$B$B$B不要回來直到你在血精靈之間擁有崇拜的聲望。離去吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10306 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10306, 'zhTW', '這些獸人一定真的很渴望獲取外域的支配權!如果我告訴你他們為了我的忠誠付出了多少，你會因妒忌而殺了我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10307 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10307, 'zhTW', NULL, '不，$r。你的體積只會壓碎這些高貴生物的其中一個。\n$b\n現在，滾開吧你!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10308 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10308, 'zhTW', '如果你有黃金，我就能教導你如何騎乘陸行鷹。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10310 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10310, 'zhTW', '在我教你騎術之前，你必須與血精靈達到崇拜的聲望才行，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10312 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10312, 'zhTW', '你準備好聽毀滅密碼的故事了嗎，$N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10313 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10313, 'zhTW', '非常好。這些你要尋找的內容有一個名字，$N。他們被稱為毀滅密碼︰那些古爾丹本人訴說的話語足以粉碎這塊土地。這個特別的法術切斷最後一個僅存於獸人與德拉諾元素之間的聯絡。$B$B<歐朗諾克點頭。>$B$B好，這就是你必須重建的密碼及最終必須召喚的密碼內容。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10314 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10314, 'zhTW', '毀滅密碼被放在卡拉伯爾裡古爾丹的私人住所20年了。啊，對了，你不知道卡拉伯爾是什麼，對吧?$B$B就是黑暗神廟……$B$B是的，現在是伊利丹·怒風的居所。$B$B當伊利丹掌管黑暗神廟時，他發現了密碼。他知道對這世界的傷害已經完成了，但還是覺得將密碼儲存下來供以後使用比較好。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10315 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10315, 'zhTW', '當你站在詛咒祭壇看到被詛咒的靈魂，跪著禱告，你沒看見的是我，緊挨著古爾丹站著。$B$B<歐朗諾克點頭。>$B$B我告訴過你我什麼都做過，不是嗎?那些〝東西〞其中一個是古爾丹的一位副官。$B$B在我的生命裡我已經做了很多可怕的事。我曾經屠殺男人，婦女和小孩。在無辜的德萊尼血液裡跳舞……可是……$B$B<歐朗諾克哽住他的話。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10316 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10316, 'zhTW', '我永遠不會忘記那天，$r。從來沒有。即使我老早以前就已經因為熱衷暗影魔法而拋棄了薩滿教義，我還是覺得難過。一股深刻的失落感……我無法用言語來對你形容這種感受。$B$B當與元素的聯絡被切斷，所有德拉諾的獸人都變了。如果對暗影的力量有任何懷疑，都會被粉碎的大地上山頂的熔岩給沖洗掉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10317 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10317, 'zhTW', '一陣噁心衝擊著我。在儀式結束後，我跑回家找我的孩子。我收拾了一些我帶得走的東西並與孩子們一起離開。我們跑到小山丘去躲起來。當時真的沒有其他選擇了……$B$B我不去想這個傷口不是一天的事了。費了20年才與元素再度連線。費了20年了元素才開始癒合。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10318 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10318, 'zhTW', '正如我所說，當伊利丹接管黑暗神廟時他發現了密碼。他將書卷分成3個部分並交給他的爪牙負責看管。$B$B我的孩子們……我的男孩們現在已經長大了。在我得知伊利丹對密碼所做的事情後，我派我的孩子們去取回那些部份。$B$B你必須找到我的孩子，$N。你必須找到他們並將毀滅密碼帶回來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10321 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10321, 'zhTW', '歡迎到撒塔斯城，外域的撒塔之地。你在找嚮導嗎?', '歡迎到撒塔斯城，外域的撒塔之地。你在找嚮導嗎?', '歡迎到撒塔斯城，外域的撒塔之地。你在找嚮導嗎?', '歡迎到撒塔斯城，外域的撒塔之地。你在找嚮導嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10322 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10322, 'zhTW', '我來到這個地方是為了研究曾經是雷霆王氏族的退化文明。$B$B他們脆弱且屈服於被瑪諾洛斯之血轉化的魔獄獸人擁有的力量誘惑$B$B我已經閱讀過了他們所有的文字。我對於一個古器，一隻鼓，一隻箭以及遺失的一個石板特別感興趣，這些東西在追擊劍刃巨魔並將他們打回他們堡壘的過程中遺失了。', '我來到這個地方是為了研究曾經是雷霆王氏族的退化文明。$B$B他們脆弱且屈服於被瑪諾洛斯之血轉化的魔獄獸人擁有的力量誘惑$B$B我已經閱讀過了他們所有的文字。我對於一個古器，一隻鼓，一隻箭以及遺失的一個石板特別感興趣，這些東西在追擊劍刃巨魔並將他們打回他們堡壘的過程中遺失了。', '我來這個地方是由於我的研究涉及到了雷神氏族的文化。$B$B他們以前很弱小，不過由於屈服於力量的引誘，他們透過瑪諾洛斯之血轉變成了邪獸人。$B$B我讀了所有有關他們的文獻。在我們征服刀塔食人魔並把他們逐出要塞的時候，我們遺失了一件神器、一面鼓、一支箭和一塊石板。現在我對找回它們有著獨特的興趣。', '我來到這個地方是為了研究曾經是雷霆王氏族的退化文明。$B$B他們脆弱且屈服於被瑪諾洛斯之血轉化的魔獄獸人擁有的力量誘惑$B$B我已經閱讀過了他們所有的文字。我對於一個古器，一隻鼓，一隻箭以及遺失的一個石板特別感興趣，這些東西在追擊劍刃巨魔並將他們打回他們堡壘的過程中遺失了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10323 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10323, 'zhTW', '阿爾託無生命跡象的身體被惡魔魔法懸浮在半空中。他們奪走了他，即便死了也一樣……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10324 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10324, 'zhTW', '我很高興你已經決定接受我們的想法。我會使用你帶給我所剩下的永恆之井注入一枚戒指中作為獎勵。$B$B我提供你4條不同途徑以解放他們的力量。做出明智的選擇，$N。時間之沙無疑會容易流向一個方向而非另一個。', '我很高興你已經決定接受我們的想法。我會使用你帶給我所剩下的永恆之井注入一枚戒指中作為獎勵。$B$B我提供你4條不同途徑以解放他們的力量。做出明智的選擇，$N。時間之沙無疑會容易流向一個方向而非另一個。', '我很高興你已經決定接受我們的想法。我會使用你帶給我所剩下的永恆之井注入一枚戒指中作為獎勵。\n\n我提供你4條不同途徑以解放他們的力量。做出明智的選擇，$N。時間之沙無疑會容易流向一個方向而非另一個。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10327 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10327, 'zhTW', '我……死了。$B$B為什麼我還在這裡?沒有我可以去的大獵場嗎?$B$B不……我必須先完成我的任務。在我可以離開這個世界之前，毀滅密碼的第2個部分必須被收回。', '我……死了。$B$B為什麼我還在這裡?沒有我可以去的大獵場嗎?$B$B不……我必須先完成我的任務。在我可以離開這個世界之前，毀滅密碼的第2個部分必須被收回。', '我……死了。為什麼我還在這裡？是不是我要去的地方沒有什麼好的獵場？\n不……我必須先完成我的任務。在我可以離開這個世界前，必須找到詛咒密碼的第二塊碎片。', '我……死了。$B$B為什麼我還在這裡?沒有我可以去的大獵場嗎?$B$B不……我必須先完成我的任務。在我可以離開這個世界之前，毀滅密碼的第2個部分必須被收回。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10329 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10329, 'zhTW', '遺忘你的劍類鍛造技能不是件容易的事。如果你選擇遺忘，你將會失去所有制作劍類鍛造需要的方法!', '遺忘你的劍類鍛造技能不是件容易的事。如果你選擇遺忘，你將會失去所有制作劍類鍛造需要的方法!', '遺忘你的鑄劍技能並不是什麼輕鬆的事。如果你選擇放棄，你會忘記所有鑄劍專精相關的圖樣！', '遺忘你的劍類鍛造技能不是件容易的事。如果你選擇遺忘，你將會失去所有制作劍類鍛造需要的方法!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10338 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10338, 'zhTW', '如你所期望的，$N。幽魂獵手準備好了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10339 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10339, 'zhTW', '我已經在戰壕裡度過我的時間，並且花費很多年訓練這些自負的傻小子。回家的感覺真好。不管它變成怎樣，都是我的家。', '我已經在戰壕裡度過我的時間，並且花費很多年訓練這些自負的傻小子。回家的感覺真好。不管它變成怎樣，都是我的家。', '照料這些擋在我的族人和死亡之間的勇敢野獸是一種榮譽。', '我已經在戰壕裡度過我的時間，並且花費很多年訓練這些自負的傻小子。回家的感覺真好。不管它變成怎樣，都是我的家。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10341 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10341, 'zhTW', '這些巨魔，他們把我埋到只剩我的脖子，然後就忘記回來了。$B$B是啊，老兄，真有趣。笑出來吧。沒有身體的鬼魂頭在這裡。$B$B當然，如果你想要幫我出來，我也許值得你花點時間。$B$B但是不準，一直笑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10349 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10349, 'zhTW', '<奴艾恩·雷翼搖頭。>$B$B一邊是軍團而另一邊是伊利丹的爪牙，我們要盡一切能夠取得的事物來防衛堡壘，而且我們一定會受住它!每一個忠誠的蠻錘寧願死也不會交出我們的家園。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10350 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10350, 'zhTW', '站直，蠻兵!你現在受控於柯爾克隆守衛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10352 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10352, 'zhTW', '這塊土地仍然承受著過去的傷痕。我懷疑他們是否將夠治癒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10354 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10354, 'zhTW', '居住在贊格沼澤的菲拉芬擁有附帶精巧鎖閘的柳條籃。想必他們能夠挑戰你的技術。', '居住在贊格沼澤的菲拉芬擁有附帶精巧鎖閘的柳條籃。想必他們能夠挑戰你的技術。', '居住在贊加沼澤的蠻沼部族揹著帶鎖的籃子，你應該有興趣去挑戰一下自己的技能。', '居住在贊格沼澤的菲拉芬擁有附帶精巧鎖閘的柳條籃。想必他們能夠挑戰你的技術。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
