INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10355, 'zhTW', '納葛蘭的吉爾索洛堡壘置物箱會有一項大挑戰提供給即使是你這樣技術卓越的盜賊。', '納葛蘭的吉爾索洛堡壘置物箱會有一項大挑戰提供給即使是你這樣技術卓越的盜賊。', '撬開納格蘭的基爾索羅堡壘裡的箱子對你這樣的盜賊來說，是一種莫大的挑戰。', '納葛蘭的吉爾索洛堡壘裝備箱會有一項大挑戰提供給即使是你這樣技術卓越的盜賊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10356 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10356, 'zhTW', '輕輕走，$r。這座橋以外就是地獄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
