INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10379, 'zhTW', '在撒塔斯有兩家銀行，都沿著市中心的兩邊。一個由德萊尼奧多爾經營，而另一個由血精靈占卜者經營。', '在撒塔斯有兩家銀行，都沿著市中心的兩邊。一個由德萊尼奧多爾經營，而另一個由血精靈占卜者經營。', '在撒塔斯有兩家銀行，都沿著市中心的兩邊。一個由德萊尼奧多爾經營，而另一個由血精靈占卜者經營。', '在撒塔斯有兩家銀行，都沿著市中心的兩邊。一個由德萊尼奧多爾經營，而另一個由血精靈占卜者經營。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
