INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10382, 'zhTW', '撒塔斯的旅店裡充滿受傷的難民。不過，在奧多爾高地的德萊尼奧多爾和占卜者階梯的血精靈占卜者之中還有空房間。', '撒塔斯的旅店裡充滿受傷的難民。不過，在奧多爾高地的德萊尼奧多爾和占卜者階梯的血精靈占卜者之中還有空房間。', '撒塔斯的旅店裡充滿受傷的難民。不過，在奧多爾高地的德萊尼奧多爾和占卜者階梯的血精靈占卜者之中還有空房間。', '撒塔斯的旅店裡充滿受傷的難民。不過，在奧多爾高地的德萊尼奧多爾和占卜者階梯的血精靈占卜者之中還有空房間。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
