INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10395, 'zhTW', '你也許可以在占卜者階梯的先知書庫裡找到最高附魔師巴多蘭。身為一位藝術大師，他身邊總是圍著他的學生︰大師，工匠，專家和短工。', '你也許可以在占卜者階梯的先知書庫裡找到最高附魔師巴多蘭。身為一位藝術大師，他身邊總是圍著他的學生︰大師，工匠，專家和短工。', '高階附魔師巴爾杜蘭在占星者平臺的先知圖書館。他是附魔的宗師，身邊環繞著他的學生：初級附魔師，中級附魔師，高階附魔師和大師級附魔師。', '你也許可以在占卜者階梯的先知書庫裡找到最高附魔師巴多蘭。身為一位藝術大師，他身邊總是圍著他的學生∶大師，工匠，專家和短工。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
