INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10398, 'zhTW', '希摩爾，撒塔斯的首席剝皮師以及貿易大師，你可以在陰鬱城的公開市場裡找到他。', '希摩爾，撒塔斯的首席剝皮師以及貿易大師，你可以在陰鬱城的公開市場裡找到他。', '宗師級剝皮師塞莫爾就在貧民窟的露天市場裡，他也是沙塔斯城最好的剝皮師。', '希摩爾，撒塔斯的首席剝皮師以及貿易大師，你可以在陰鬱城的公開市場裡找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
