INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10422, 'zhTW', '我精通超過兩種語言︰矮人語，地精語和非常普通的人類語言。但是我不瞭解你在說什麼!$B$B說大聲點:引擎聲這麼吵，我聽不見你的聲音!', '我精通超過兩種語言∶矮人語，地精語和非常普通的人類語言。但是我不瞭解你在說什麼!$b$b說大聲點:引擎聲這麼吵，我聽不見你的聲音!', '我精通超過兩種語言∶矮人語，地精語和非常普通的人類語言。但是我不瞭解你在說什麼!$b$b說大聲點:引擎聲這麼吵，我聽不見你的聲音!', '我精通超過兩種語言∶矮人語，地精語和非常普通的人類語言。但是我不瞭解你在說什麼!$B$B說大聲點:引擎聲這麼吵，我聽不見你的聲音!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10423 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10423, 'zhTW', '是，是...歡迎到我的基地。$B$B那麼，你覺得如何呢?漂亮的俏皮話我們在這裡都說過了，你不來點嗎?$B$B無論如何，我很高興能夠擺脫那些希爾瓦納的自大精靈。$B$B四處找點事做吧;到處都有許多的實驗及匿名者等著需要幫忙。', '是，是……歡迎到我的基地。$b$b那麼，你覺得如何呢?漂亮的俏皮話我們在這裡都說過了，你不來點嗎?$b$b無論如何，我很高興能夠擺脫那些希爾瓦納的自大精靈。$b$b四處找點事做吧;到處都有許多的實驗及匿名者等著需要幫忙。', '是，是……歡迎到我的基地。$b$b那麼，你覺得如何呢?漂亮的俏皮話我們在這裡都說過了，你不來點嗎?$b$b無論如何，我很高興能夠擺脫那些希爾瓦納的自大精靈。$b$b四處找點事做吧;到處都有許多的實驗及匿名者等著需要幫忙。', '是，是……歡迎到我的基地。$B$B那麼，你覺得如何呢?漂亮的俏皮話我們在這裡都說過了，你不來點嗎?$B$B無論如何，我很高興能夠擺脫那些希爾瓦納的自大精靈。$B$B四處找點事做吧;到處都有許多的實驗及匿名者等著需要幫忙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
