INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10466, 'zhTW', '當你與洛薩克的非正式騎兵一起奔跑時，你會學會一點關於遵守命令的事。$B$B第一件事是作戰至死。第二件事是，看第一件事情。', '當你與洛薩克的非正式騎兵一起奔跑時，你會學會一點關於遵守命令的事。$B$B第一件事是作戰至死。第二件事是，看第一件事情。', NULL, '當你與洛薩克的非正式騎兵一起奔跑時，你會學會一點關於遵守命令的事。$B$B第一件事是作戰至死。第二件事是，看第一件事情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10467 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10467, 'zhTW', '需要將你的刀身磨利，還是選一種新武器?有備無患...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10468 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10468, 'zhTW', '如果你要尋找的是一支鐵錘，那你已經來對地方了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10469 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10469, 'zhTW', '$G年輕人:年輕的女士;，我不打算騙你;這裡的情況並不樂觀。我們不斷被蟲子襲擊，而我們的生命，我們的自由，都在危急關頭!$B$B你會成為一位負責任的居民並且幫助我們嗎?', '$G孩子:年輕的女士;，我不準備向你撒謊，這裡的事情不是那麼如意。我們受到了蟲子持續的攻擊，我們的生活、我們的自由，都受到了威脅！\n\n你願意盡一位好公民的責任來幫助我們嗎？', '$G孩子:年輕的女士;，我不準備向你撒謊，這裡的事情不是那麼如意。我們受到了蟲子持續的攻擊，我們的生活、我們的自由，都受到了威脅！\n\n你願意盡一位好公民的責任來幫助我們嗎？', '$G年輕人:年輕的女士;，我不打算騙你;這裡的情況並不樂觀。我們不斷被蟲子襲擊，而我們的生命，我們的自由，都在危急關頭!$B$B你會成為一位負責任的居民並且幫助我們嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10470 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10470, 'zhTW', '泰朗·血魔嗎?是的...我知道他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10471 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10471, 'zhTW', '太燦爛了!太驚人了!真是一個極佳的表演!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10473 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10473, 'zhTW', '我年輕時努力接受訓練以成為一個在教士中的隱士。那時從沒聽過有女性主教。$B$B現在性別不太重要 - 勇氣和信念才是重點。', '我年輕時努力接受訓練以成為一個在教士中的隱士。那時從沒聽過有女性主教。$B$B現在性別不太重要 - 勇氣和信念才是重點。', '我年輕時努力接受訓練以成為一個在教士中的隱士。那時從沒聽過有女性主教。$b$b現在性別不太重要-勇氣和信念才是重點。', '我年輕時努力接受訓練以成為一個在教士中的隱士。那時從沒聽過有女性主教。$B$B現在性別不太重要 - 勇氣和信念才是重點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10474 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10474, 'zhTW', '如果你已準備好，並且希望迅速返回正常的時間流，我能將你傳送至時光之穴的安杜姆那裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10475 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10475, 'zhTW', '形成時間流是一項非常艱難精細的任務，但是你今天表現的非常令人欽佩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10491 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10491, 'zhTW', '來幫忙這裡的騷動嗎?', '來幫忙這裡的騷動嗎?', '來幫忙這裡的騷動嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10492 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10492, 'zhTW', '為酬謝凱爾薩斯數年來的效勞，伊利丹允許凱爾薩斯送來五位戰士給他訓練。這是第一次血精靈被允許訓練為惡魔獵人。$B$B訓練是野蠻的。伊利丹讓凱爾薩斯的戰士進行試煉，讓他們可以戰勝大部分有完整能力的惡魔獵人。$B$B三個凱爾薩斯的精靈在訓練過程中死掉 - 另一個瘋掉。$B$B一個成功。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10493 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10493, 'zhTW', '瓦瑞迪斯是他的名字。讓伊利丹驚奇的是，他不僅成功完成訓練中痛苦的祭儀;而且與很多老練的惡魔獵人相比，瓦瑞迪斯更能掌控他的力量。$B$B伊利丹察覺到瓦瑞迪斯的潛能，並且指派三個惡魔獵人大師用他們的方式更進一步訓練他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10494 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10494, 'zhTW', '在伊利丹最好的三名惡魔獵人一年的訓練之下，瓦瑞迪斯已經超越了他們。$B$B他們的訓練無法再滿足他，於是瓦瑞迪斯滲透進入暗影議會，在那裡他獲悉有一件被稱為惡魔之名寶典的強大聖物。他偷偷地閱讀這本書，牢記每段文章。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10495 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10495, 'zhTW', '謠傳知道一個惡魔的真實名字會被賦予超過那個惡魔的一定力量。$B$B惡魔之名寶典據說寫著每個曾經存在的惡魔真實名字。在回憶書中的內容時，瓦瑞迪斯發現了一個來自古爾丹之顱的力量泉源，能與伊利丹自己競爭。$B$B應伊利丹的請求，瓦瑞迪斯現在於卡拉伯爾廢墟經營訓練場 - 與指導瓦瑞迪斯的三位大師一起。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10496 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10496, 'zhTW', '凡人，走開!你們在這裡是不受歡迎的……', '滾開，凡人！你在這裡不受歡迎……', '滾開，凡人！你在這裡不受歡迎……', '凡人，走開!你們在這裡是不受歡迎的……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10497 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10497, 'zhTW', '血精靈成為惡魔獵人的力量潛力如此高不令人驚訝。畢竟，辛多雷不像夜精靈擁有對惡魔魔法的自然排斥。$B$B然而，我不期望許多人成功。他們大多數人，包括瓦瑞迪斯，都為自己的理由追求力量。那力量將耗盡它們，因為它們不是被真正惡魔獵人心中燃燒的純火所驅動的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10500 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10500, 'zhTW', '你能從洛薩之子中帶走一個人，但是你不能從他那裡帶走那些兒子。$B$B<鐵匠聳聳肩。>$B$B很難解釋，但我不覺得我現在應該在榮譽堡。$B$B也許我應該屬於某個更偉大的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10501 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10501, 'zhTW', '慕曼已經在城市的主要入口附近開了她簡陋的商店，就在旅店再過去的地方。絕妙小廚，那一間。', '慕曼已經在城市的主要入口附近開了她簡陋的商店，就在旅店再過去的地方。絕妙小廚，那一間。', '慕曼已經在城市的主要入口附近開了她簡陋的商店，就在旅店再過去的地方。絕妙小廚，那一間。', '慕曼已經在城市的主要入口附近開了她簡陋的商店，就在旅店再過去的地方。絕妙小廚，那一間。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10502 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10502, 'zhTW', '奇蘭在商店街西北角的裁縫店有一部像你描述的織布機。', '奇蘭在商店街西北角的裁縫店有一部像你描述的織布機。', '奇蘭在商店街西北角的裁縫店有一部像你描述的織布機。', '奇蘭在商店街西北角的裁縫店有一部像你描述的織布機。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10503 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10503, 'zhTW', '你能在陰鬱城的商店街裡找到我們的法力織布機。', '法力製造機坐落在陰鬱城的公開市場。', '法力製造機坐落在陰鬱城的公開市場。', '法力製造機坐落在陰鬱城的公開市場。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10504 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10504, 'zhTW', '<秘法守護者安靜地等待你進一步的製作。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
