INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10505, 'zhTW', '「你要控制我還太早了，因為你最近已經離開比賽了 」。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10506 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10506, 'zhTW', '要透過我的大廳，你必須在一場競技比賽中戰勝我!當你準備開始時，控制你的國王...', '想穿越我的大廳，你就必須用你的精湛棋藝來擊敗我！當你準備好了之後，就去控制你的國王……', '想穿越我的大廳，你就必須用你的精湛棋藝來擊敗我！當你準備好了之後，就去控制你的國王……', '要透過我的大廳，你必須在一場競技比賽中戰勝我!當你準備開始時，控制你的國王……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10508 AND `Locale` = 'zhTW';
