INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10528, 'zhTW', '<復仇者奧多爾愁容滿面。>你……可以在占卜者階梯的先知書庫找到最高附魔師巴多蘭，和那些其他的邪惡血精靈。', '<復仇者奧多爾愁容滿面。>你……可以在占卜者階梯的先知書庫找到最高附魔師巴多蘭，和那些其他的邪惡血精靈。', '<奧爾多守備官皺著眉頭。>你……可以在占星者平臺上的先知圖書館找到高階附魔師巴爾杜蘭，他和那些邪惡的血精靈廝混在一起。', '<復仇者奧多爾愁容滿面。>你……可以在占卜者階梯的先知書庫找到最高附魔師巴多蘭，和那些其他的邪惡血精靈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
