INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10561, 'zhTW', '這次飛行將帶你到美聲山脊較遠的地方。非常危險!$B$B因此，我將要需要一張已簽署的棄權證明書……', '這次飛行將帶你到美聲山脊較遠的地方。非常危險!$b$b因此，我將要需要一張已簽署的棄權證明書……', '這次飛行將帶你到美聲山脊較遠的地方。非常危險!$b$b因此，我將要需要一張已簽署的棄權證明書……', '這次飛行將帶你到美聲山脊較遠的地方。非常危險!$B$B因此，我將要需要一張已簽署的棄權證明書……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
