INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10565, 'zhTW', '雖然探索這些新土地無疑是重要的，但你不可遺棄艾澤拉斯!我們現在比從前和那些汙染者對抗時更需要你。那些資源必須被妥善保護!', '雖然探索這些新土地無疑是重要的，但你不可遺棄艾澤拉斯!我們現在比從前和那些汙染者對抗時更需要你。那些資源必須被妥善保護!', '在新大陸的探索無疑非常重要，但是你不能遺忘艾澤拉斯！我們比以前更加需要你去和汙染者作戰！那些資源需要得到保護！', '雖然探索這些新土地無疑是重要的，但你不可遺棄艾澤拉斯!我們現在比從前和那些汙染者對抗時更需要你。那些資源必須被妥善保護!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10566 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10566, 'zhTW', '你，$c!我們需要你的幫助!粗暴的戰歌獸人正在破壞梣谷的奇蹟和美景，我們需要你的力量在戰場上對抗他們。與我們一起回到艾澤拉斯，為銀翼哨兵的榮譽而戰鬥!你願意加入我們嗎?', '你，$c!我們需要你的幫助!粗暴的戰歌獸人正在破壞梣谷的奇蹟和美景，我們需要你的力量在戰場上對抗他們。與我們一起回到艾澤拉斯，為銀翼哨兵的榮譽而戰鬥!你願意加入我們嗎?', '你，$c!我們需要你的幫助!粗暴的戰歌獸人正在破壞梣谷的奇蹟和美景，我們需要你的力量在戰場上對抗他們。與我們一起回到艾澤拉斯，為銀翼哨兵的榮譽而戰鬥!你願意加入我們嗎?', '你，$c!我們需要你的幫助!粗暴的戰歌獸人正在破壞梣谷的奇蹟和美景，我們需要你的力量在戰場上對抗他們。與我們一起回到艾澤拉斯，為銀翼哨兵的榮譽而戰鬥!你願意加入我們嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10568 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10568, 'zhTW', '有一句諺語說，「與其給他魚吃，還不如教他釣魚」。當然，你可能想要煮那條魚，而那是我進來的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
