INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10569, 'zhTW', '哈羅，$n!你的冒險如何?我的實驗進行的很順利...$B$B記得要再來和我聊聊!我搞不好會有更多飛行試驗機會給你!', '哈囉，$n!你的冒險如何?我的實驗進行的很順利……$b$b記得要再來和我聊聊!我搞不好會有更多飛行試驗機會給你!', '哈囉，$n!你的冒險如何?我的實驗進行的很順利……$b$b記得要再來和我聊聊!我搞不好會有更多飛行試驗機會給你!', '哈囉，$n!你的冒險如何?我的實驗進行的很順利……$B$B記得要再來和我聊聊!我搞不好會有更多飛行試驗機會給你!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10570 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10570, 'zhTW', '力量和榮譽，$c。我們在奧特蘭克山谷需要像你一樣熱心計程車兵;霜狼的領土必須被保衛!你會返回艾澤拉斯提供你的協助嗎?', '力量和榮譽，$c。我們在奧特蘭克山谷需要像你一樣熱心計程車兵;霜狼的領土必須被保衛!你會返回艾澤拉斯提供你的協助嗎?', '力量和榮譽，$c。我們非常渴望像你這樣計程車兵能前往奧特蘭克山谷，保衛霜狼氏族的領土！你會回到艾澤拉斯幫助我們嗎？', '力量和榮譽，$c。我們在奧特蘭克山谷需要像你一樣熱心計程車兵;霜狼的領土必須被保衛!你會返回艾澤拉斯提供你的協助嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10571 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10571, 'zhTW', '$R!對，就是你!你為什麼在該去阿拉希盆地的時候浪費你的時間在這座殘破的城市鬼混?阿拉索聯軍的攻擊是殘酷無情的;我們需要你的貢獻，而你將被獎勵!', '$R!對，就是你!你為什麼在該去阿拉希盆地的時候浪費你的時間在這座殘破的城市鬼混?阿拉索聯軍的攻擊是殘酷無情的;我們需要你的貢獻，而你將被獎勵!', '$c！是的，就是你！為什麼你會在這座破敗的城市裡閒逛著浪費時間，而不是出現在阿拉希盆地的戰場上？我們阿拉索聯軍正被敵人無情地攻擊，我們需要你的奉獻，而且你也一定會得到獎勵的！', '$R!對，就是你!你為什麼在該去阿拉希盆地的時候浪費你的時間在這座殘破的城市鬼混?阿拉索聯軍的攻擊是殘酷無情的;我們需要你的貢獻，而你將被獎勵!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10572 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10572, 'zhTW', '$C，從前在艾澤拉斯的時候，樹林裡的銀翼哨兵阻礙我們的前進。我們需要你在前線將他們擊退!你將因為幫助我們而贏得戰歌先遣騎極大的尊敬和聲望 - 現在加入我們吧!', '$C，從前在艾澤拉斯的時候，樹林裡的銀翼哨兵阻礙我們的前進。我們需要你在前線將他們擊退!你將因為幫助我們而贏得戰歌先遣騎極大的尊敬和聲望 - 現在加入我們吧!', '$C，回到艾澤拉斯吧， 銀翼哨兵妨礙了我們在森林裡的伐木工作。我們需要你趕赴那邊的前線，將戰線推回去！如果你幫助我們，就將獲得無上的榮譽，在戰歌氏族當中也會積累很高的聲望——現在就加入我們吧！', '$C，從前在艾澤拉斯的時候，樹林裡的銀翼哨兵阻礙我們的前進。我們需要你在前線將他們擊退!你將因為幫助我們而贏得戰歌偵察騎兵極大的尊敬和聲望 - 現在加入我們吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10573 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10573, 'zhTW', '救你自己吧，$r。從這個地方逃離!如果你被發現，赤紅法印將立即處決你。', '救你自己吧，$r。從這個地方逃離!如果你被發現，赤紅法印將立即處決你。', '救你自己吧，$r。從這個地方逃離!如果你被發現，赤紅法印將立即處決你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
