INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10601, 'zhTW', '喂!你聽說過熱砂戰鬥同盟嗎?$B$B你可以在加基森裡，納葛蘭和劍刃山脈的競技場外找到販賣競技場小隊特許狀的競技場編制者。', '喂!你聽說過熱砂戰鬥同盟嗎?$B$B你可以在加基森裡，納葛蘭和劍刃山脈的競技場外找到販賣競技場小隊特許狀的競技場編制者。', '喂!你聽說過熱砂戰鬥同盟嗎?$b$b你可以在加基森裡，納葛蘭和劍刃山脈的競技場外找到販賣競技場小隊特許狀的競技場編制者。', '喂!你聽說過熱砂戰鬥同盟嗎?$B$B你可以在加基森裡，納葛蘭和劍刃山脈的競技場外找到販賣競技場小隊特許狀的競技場編制者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
