INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10608, 'zhTW', '另一個想當鬥士的$c啊?很好!$B$B我專賣參加熱砂戰鬥同盟積分賽將需要的競技場隊伍登記表。', '另一個想當鬥士的$c啊?很好!$B$B我專賣參加熱砂戰鬥同盟積分賽將需要的競技場隊伍登記表。', '另一個想當鬥士的$c啊?很好!$b$b我專賣參加熱砂戰鬥同盟排名賽將需要的競技場小隊特許狀。', '另一個想當鬥士的$c啊?很好!$B$B我專賣參加熱砂戰鬥同盟積分賽將需要的競技場隊伍登記表。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10610 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10610, 'zhTW', '斷脊氏族崗哨是一個重要的駐紮地點!血之谷的異常是如此的靠近，你能聞到他們邪惡的鮮血!還有什麼地方比這更適合對一個背棄同志，與惡魔達成條約的氏族進行復仇呢?', '斷脊氏族崗哨是一個重要的駐紮地點!血之谷的異常是如此的靠近，你能聞到他們邪惡的鮮血!還有什麼地方比這更適合對一個背棄同志，與惡魔達成條約的氏族進行復仇呢?', '斷脊氏族崗哨是一個重要的駐紮地點!血之谷的異常是如此的靠近，你能聞到他們邪惡的鮮血!還有什麼地方比這更適合對一個背棄同志，與惡魔達成條約的氏族進行復仇呢?', '斷脊氏族崗哨是一個重要的駐紮地點!血之谷的異常是如此的靠近，你能聞到他們邪惡的鮮血!還有什麼地方比這更適合對一個背棄同志，與惡魔達成條約的氏族進行復仇呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10612 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10612, 'zhTW', '費爾威德和我來這裡代表希爾瓦納的利益。$B$B德魯伊們非常通融，但是允許部落穿越這裡讓我有種毛骨悚然的感覺。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10613 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10613, 'zhTW', '你好，凡人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10614 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10614, 'zhTW', '在虛空之翼農場東方的區域有一座龍喉堡壘。殘酷的龍喉獸人氏族在那裡拷問他們捕獲的龍，試圖使他們屈從於他們的意志。其中很多已經放棄希望，改為服從龍喉的命令。而其他的...他們拒絕登陸，擔心龍喉主戰派捕獲他們並且把他們帶回堡壘。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10615 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10615, 'zhTW', '我...我們是弱小的。伊利丹發現並且交給龍喉他們的領導人--祖魯希德。這個獸人就是負責捕捉和監禁雅立史卓莎的那個。我們怎能與這樣的力量戰鬥?他抓住了一名守護巨龍!$B$B而且一樣容易地，帶走了我的夥伴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10616 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10616, 'zhTW', '<奈爾斯阿拉古點頭。>$B$B凱瑞納古...她被關在龍喉堡壘頂端。我已經做了很多嘗試去解救她。全部都失敗了...你以前曾與這些野獸戰鬥過，不是嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10625 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10625, 'zhTW', '對抗凱爾薩斯和伊利丹的戰役在所有前線上持續著。戰敗不是一種選擇。', '對抗凱爾薩斯和伊利丹的戰役在所有前線上持續著。戰敗不是一種選擇。', '與凱爾薩斯和伊利丹的戰鬥仍然在前線繼續進行著。我們只可成功，不許失敗。', '對抗凱爾薩斯和伊利丹的戰役在所有前線上持續著。戰敗不是一種選擇。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10631 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10631, 'zhTW', '我瞭解你最近才加入我們，因此可能沒注意到我們的傳統。在月光林地裡，一個盛大的慶典正在進行。這是我們榮耀祖先的時刻，而你當然被邀請了!如果你願意參加，就前往我們的城市之一!', '我瞭解你最近才加入我們，因此可能沒注意到我們的傳統。在月光林地裡，一個盛大的慶典正在進行。這是我們榮耀祖先的時刻，而你當然被邀請了!如果你願意參加，就前往我們的城市之一!', '據我所知，你最近才加入我們，可能並不清楚我們的傳統。月光林地那邊正在舉辦一場龐大的慶典。這是一年一度向長者們致敬的日子，你被邀請了！如果你想加入的話，去任何一座城市都可以！', '我瞭解你最近才加入我們，因此可能沒注意到我們的傳統。在月光林地裡，一個盛大的慶典正在進行。這是我們榮耀祖先的時刻，而你當然被邀請了!如果你願意參加，就前往我們的城市之一!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10634 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10634, 'zhTW', '艾澤拉斯正在全力慶祝新年慶典!回到那裡，並在此精彩的慶典上向你的長者致敬!主要的慶典可在月光林地找到，而我們有提供自暴風城、鐵爐堡、達納蘇斯、雷霆崖、奧格瑪、和幽暗城的簡易傳送。我們希望在那裡見到你!', '艾澤拉斯正在全力慶祝新年慶典!回到那裡，並在此精彩的慶典上向你的長者致敬!主要的慶典可在月光林地找到，而我們有提供自暴風城、鐵爐堡、達納蘇斯、雷霆崖、奧格瑪、和幽暗城的簡易傳送。我們希望在那裡見到你!', '艾澤拉斯各地都在慶祝春節！回到那邊去吧，在這個偉大的節日向你的長者表達敬意吧！最大的慶典活動會在月光林地舉行，但我們在暴風城、鐵爐堡、達納蘇斯、雷霆崖、奧格瑞瑪和幽暗城也都提供了方便快捷的傳送器。希望能在那邊見到你，一定要來哦！', '艾澤拉斯正在全力慶祝新年慶典!回到那裡，並在此精彩的慶典上向你的長者致敬!主要的慶典可在月光林地找到，而我們有提供自暴風城、鐵爐堡、達納蘇斯、雷霆崖、奧格瑪、和幽暗城的簡易傳送。我們希望在那裡見到你!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10635 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10635, 'zhTW', 'What? Where am I? This isn\'t right at all! Look at you! Look at this place! It isn\'t on my list! There\'s going to be so much paperwork...$b$b<The goblin writes frantically in a small notebook.>$b$bLook, if you\'ve got nothing better to do than stand there and stare, why don\'t you go visit my cousin, Kwee Q. Peddlefeet, in one of the major cities? Says here he\'s taking care of Orgrimmar, Stormwind, Thunder Bluff, Ironforge, the Undercity, and Darnassus. Go on, get outta here!', '什麼?這是哪裡?這根本不對!看看你!看看這個地方!這不在我的清單上!肯定會有非常多的文書工作...$b$b<那些哥布林在小筆記本里瘋狂地寫著。>$b$b看，如果你已經沒有比站在那裡發呆更好的事可做，你怎麼不去拜訪我在主要城市之一的表弟，丘位元·傳播者?聽說他正在處理奧格瑪，暴風城，雷霆崖，鐵爐堡，幽暗城和達納蘇斯的事。去吧，離開這裡!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10636 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10636, 'zhTW', '這個地方有一些我們急於揭露的秘密，獸人。我們的過去，未來，以及窺探我們內心的秘密。$B$B洞察這些秘密是我的希望...你會與我一起走過那條道路嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10637 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10637, 'zhTW', '樹林裡有麻煩。我們必須快點發現它的來源!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10640 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10640, 'zhTW', '不久我將紮根安睡。在我歇息之前有些事情必須完成。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10641 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10641, 'zhTW', '你為我的土地帶來一段時間的綠意。足夠了。我平靜了。我準備好進入長眠了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10643 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10643, 'zhTW', '成功了!我瞭解地獄火堡壘和它裡面的魔法了!多強大的力量啊!$B$B在那個地方有數不盡的魔獄獸人...而且還不只這樣!我也感覺到在那些牆裡有惡魔的力量...$B$B假如你開啟自己的心靈，那麼我就可抓住你的心智 -- 簡短地提醒你 -- 並在羊皮紙上為你記錄下我的發現...', '成功了!我瞭解地獄火堡壘和它裡面的魔法了!多強大的力量啊!$b$b在那個地方有數不盡的魔獄獸人……而且還不只這樣!我也感覺到在那些牆裡有惡魔的力量……$b$b假如你開啟自己的心靈，那麼我就可抓住你的心智--簡短地提醒你--並在羊皮紙上為你記錄下我的發現……', '成功了!我瞭解地獄火堡壘和它裡面的魔法了!多強大的力量啊!$b$b在那個地方有數不盡的魔獄獸人……而且還不只這樣!我也感覺到在那些牆裡有惡魔的力量……$b$b假如你開啟自己的心靈，那麼我就可抓住你的心智--簡短地提醒你--並在羊皮紙上為你記錄下我的發現……', '成功了!我瞭解地獄火堡壘和它裡面的魔法了!多強大的力量啊!$B$B在那個地方有數不盡的魔獄獸人……而且還不只這樣!我也感覺到在那些牆裡有惡魔的力量……$B$B假如你開啟自己的心靈，那麼我就可抓住你的心智 -- 簡短地提醒你 -- 並在羊皮紙上為你記錄下我的發現……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10645 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10645, 'zhTW', '我們的敵人包圍我們。我本來能讓摩克納薩爾有更好的生活，但是我們所對抗的力量已為我們選擇了其他方式。$B$B假如你要證明自己對摩克納薩爾的價值，就幫助我們消滅他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10647 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10647, 'zhTW', '陌生人，被你所見的事物感到困惑嗎?$B$B我們藉由讓祖先的記憶火焰持續燃燒並向它祭拜，來讚揚我們祖先的靈魂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
