INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10659, 'zhTW', '打個招呼吧，$C。如果我太自大的話，或許你可以提醒我—當我想調和地獄火堡壘的魔法—毫無疑問的，地獄火的典獄官們都知道我的弱點!$B$B所以，你身為聯盟中正直的一員，同時也扮演著英雄的腳色...因此你得保護我才行!', '打個招呼吧，$C。如果我太自大的話，或許你可以提醒我—當我想調和地獄火堡壘的魔法—毫無疑問的，地獄火的典獄官們都知道我的弱點!$b$b所以，你身為聯盟中正直的一員，同時也扮演著英雄的腳色……因此你得保護我才行!', '打個招呼吧，$C。如果我太自大的話，或許你可以提醒我—當我想調和地獄火堡壘的魔法—毫無疑問的，地獄火的典獄官們都知道我的弱點!$b$b所以，你身為聯盟中正直的一員，同時也扮演著英雄的腳色……因此你得保護我才行!', '打個招呼吧，$C。如果我太自大的話，或許你可以提醒我—當我想調和地獄火堡壘的魔法—毫無疑問的，地獄火的典獄官們都知道我的弱點!$B$B所以，你身為聯盟中正直的一員，同時也扮演著英雄的腳色……因此你得保護我才行!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10661 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10661, 'zhTW', '搜尋我們受難的同胞、抵抗聯盟的侵襲以及跟巨魔和他們的古羅將領的戰爭。$B$B所有的事情都壓在我的肩頭上，$c。$B$B就算是我也需要不時的幫助。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10662 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10662, 'zhTW', '奧齊頓是我祖先靈魂的家，我們可以不去看管它，但是它曾經被德萊尼破壞殆盡...我們的靈魂都是一樣的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10664 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10664, 'zhTW', '死亡熔爐在燃燒軍團的監督之下，由暗影議會負責營運。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10666 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10666, 'zhTW', '下方就是叫做死亡熔爐的地方。如果任由他們的裝置生產，暗影議會就會提供燃燒軍團用之不盡的煉獄火了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10667 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10667, 'zhTW', '我們知道在另一邊的隧道那裡有一大群巨龍教徒，我們得在這裡作好準備才行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10669 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10669, 'zhTW', '歡迎啊，$N。我是原始月布的裁縫專家，那些有興趣成為月布專家的人通常都會要求我訓練他們。', '歡迎啊，$N。我是原始月布的裁縫專家，那些有興趣成為月布專家的人通常都會要求我訓練他們。', NULL, '歡迎啊，$N。我是原始月布的裁縫專家，那些有興趣成為月布專家的人通常都會要求我訓練他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
