INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10670, 'zhTW', '恐怕我能教你的只有一些皮毛而已，$c。當然，你可以隨意看看我的東西，只是你找不到你能用的東西。', '恐怕我能教你的只有一些皮毛而已，$c。當然，你可以隨意看看我的東西，只是你找不到你能用的東西。', '恐怕我能教你的只有一些皮毛而已，$c。當然，你可以隨意看看我的東西，只是你找不到你能用的東西。', '恐怕我能教你的只有一些皮毛而已，$c。當然，你可以隨意看看我的東西，只是你找不到你能用的東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
