INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10671, 'zhTW', '很高興遇見你!我叫蓋吉，是撒塔斯的居民也是魔焰裁縫專家，不管你是不是競爭對手，只要你還沒選擇你的裁縫專精系別並且有興趣成為一個專家級的魔焰裁縫師，我都很樂意幫助你。', '很高興遇見你!我叫蓋吉，是撒塔斯的居民也是魔焰裁縫專家，不管你是不是競爭對手，只要你還沒選擇你的裁縫專精系別並且有興趣成為一個專家級的魔焰裁縫師，我都很樂意幫助你。', NULL, '很高興遇見你!我叫蓋吉，是撒塔斯的居民也是魔焰裁縫專家，不管你是不是競爭對手，只要你還沒選擇你的裁縫專精系別並且有興趣成為一個專家級的魔焰裁縫師，我都很樂意幫助你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10672 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10672, 'zhTW', '如果你不是裁縫師的話，我想我的圖樣無法引起你的興趣，不過歡迎你隨意看看!', '如果你不是裁縫師的話，我想我的圖樣無法引起你的興趣，不過歡迎你隨意看看!', '如果你不是裁縫師的話，我想我的圖樣無法引起你的興趣，不過歡迎你隨意看看!', '如果你不是裁縫師的話，我想我的圖樣無法引起你的興趣，不過歡迎你隨意看看!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
