INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10675, 'zhTW', '藉由伊露恩的女神之淚可以獲得祝福，她的力量可以幫助你對抗阿克蒙德的邪惡魔法，好好使用她們的力量吧。', '藉由伊露恩的女神之淚可以獲得祝福，她的力量可以幫助你對抗阿克蒙德的邪惡魔法，好好使用她們的力量吧。', '這些被艾露恩祝福過的女神之淚蘊藏著強大的力量，可以幫助你對抗阿克蒙德的邪惡魔法。好好利用女神之淚的力量吧。', '藉由伊露恩的女神之淚可以獲得祝福，她的力量可以幫助你對抗阿克蒙德的邪惡魔法，好好使用她們的力量吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10676 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10676, 'zhTW', '他們害怕我的言語，所以狠狠的教訓了我以示眾人。這對一位真神，奈普圖隆來說真是一個諷刺呀。$B$B<司卡利斯吐口水。>$B$B凡人啊，報應來了。獵潮者的光榮之手將有一天會像是在鐮刀收割般地殺死這些不信之徒。', '他們害怕我的言語，所以狠狠的教訓了我以示眾人。這對一位真神，奈普圖隆來說真是一個諷刺呀。$b$b<司卡利斯吐口水。>$b$b凡人啊，報應來了。獵潮者的光榮之手將有一天會像是在鐮刀收割般地殺死這些不信之徒。', '他們害怕我的言語，所以狠狠的教訓了我以示眾人。這對一位真神，奈普圖隆來說真是一個諷刺呀。$b$b<司卡利斯吐口水。>$b$b凡人啊，報應來了。獵潮者的光榮之手將有一天會像是在鐮刀收割般地殺死這些不信之徒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10677 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10677, 'zhTW', '這些破壞恐怕是那些可怕的魔法所造成的，我們得儘可能的治療這些重大的創傷。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
