INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10679, 'zhTW', '死亡之門的入口將在這個世界開啟，燃燒軍團要利用這個門來繁殖惡魔犬和其他恐怖的犬齒生物。只要你看到這些從那裡來的生物，必定是先透過那道門來到這裡的。B$B最近，我們知道燃燒軍團要從這個入口召喚這些生物。$B$B你必須在他們造成不可收拾的情況之前，先把死亡之門關閉才行，要不然一切都會毀了!', '死亡之門的入口將在這個世界開啟，燃燒軍團要利用這個門來繁殖惡魔犬和其他恐怖的犬齒生物。只要你看到這些從那裡來的生物，必定是先透過那道門來到這裡的。B$B最近，我們知道燃燒軍團要從這個入口召喚這些生物。$B$B你必須在他們造成不可收拾的情況之前，先把死亡之門關閉才行，要不然一切都會毀了!', '死亡之門的入口將在這個世界開啟，燃燒軍團要利用這個門來繁殖惡魔犬和其它恐怖的犬齒生物。只要你看到這些從那裡來的生物，必定是先透過那道門來到這裡的。\n最近，我們知道燃燒軍團要從這個入口召喚這些生物。$b$b你必須在他們造成不可收拾的情況之前，先把死亡之門關閉才行，要不然一切都會毀了!', '死亡之門的入口將在這個世界開啟，燃燒軍團要利用這個門來繁殖惡魔犬和其他恐怖的犬齒生物。只要你看到這些從那裡來的生物，必定是先透過那道門來到這裡的。B$B最近，我們知道燃燒軍團要從這個入口召喚這些生物。$B$B你必須在他們造成不可收拾的情況之前，先把死亡之門關閉才行，要不然一切都會毀了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10680 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10680, 'zhTW', '我來到這塊土地是為了淨化冤靈，但是在那場攻擊之後我怕我的任務已經失敗了。更多的生命喪失在荒野之中，拜託你一定得幫幫他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10682 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10682, 'zhTW', '願聖光指引著你，$n。', '願聖光指引著你，$n。', '願聖光指引著你，$n。', '願聖光指引著你，$n。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
