INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10698, 'zhTW', '伊奈思娜是個精明的女人，她有許多的寶石和珠寶設計的材料，你可以在奧多爾高地的北部找到她的店。', '伊奈思娜是個精明的女人，她有許多的寶石和珠寶設計的材料，你可以在奧多爾高地的北部找到她的店。', '伊奈思娜是個尖酸刻薄的女人，她有許多形形色色如同是珠寶工藝的珠寶，你可以在北部的奧多爾高地那邊找她的店。', '伊奈思娜是個精明的女人，她有許多的寶石和珠寶設計的材料，你可以在奧多爾高地的北部找到她的店。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10699 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10699, 'zhTW', '麗斯瑞司剛開始看起來可能會有一點……可怕，不過她有你想找的東西。她在占卜者階梯的東部地區販賣她的商品。', '麗斯瑞司剛開始看起來可能會有一點……可怕，不過她有你想找的東西。她在占卜者階梯的東部地區販賣她的商品。', '利薩爾絲可能……看上去有點兇，但是她出售你想要的東西。她在占星者平臺的東部。', '麗斯瑞司剛開始看起來可能會有一點……可怕，不過她有你想找的東西。她在占卜者階梯的東部地區販賣她的商品。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
