INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10706, 'zhTW', '謝謝你!我內心的黑暗深淵已被解放，我又可以看見了...我看見救命恩人的臉龐!', '喔，謝謝你！我體內的黑暗物質已經被驅除了！我的眼睛又能看見東西了……啊，我看到了救世主的臉龐！', '喔，謝謝你！我體內的黑暗物質已經被驅除了！我的眼睛又能看見東西了……啊，我看到了救世主的臉龐！', '謝謝你!我內心的黑暗深淵已被解放，我又可以看見了……我看見救命恩人的臉龐!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10707 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10707, 'zhTW', '滾開，$c!不要煩我們，否則我們下次會讓你陷入真正的絕望!', '滾開，$c!不要煩我們，否則我們下次會讓你陷入真正的絕望!', '滾開，$c!不要煩我們，否則我們下次會讓你陷入真正的絕望!', '滾開，$c!不要煩我們，否則我們下次會讓你陷入真正的絕望!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
