INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10725, 'zhTW', '賽藍恩是這座城市最優秀的廚師之一，你能在遠行者旅店的樓上找到他。同時你也能從那裡的服務員那兒買到一些做好的菜餚。', '賽藍恩是這座城市最優秀的廚師之一，你能在遠行者旅店的樓上找到他。同時你也能從那裡的服務員那兒買到一些做好的菜餚。', NULL, '賽藍恩是這座城市最優秀的廚師之一，你能在遠行者旅店的樓上找到他。同時你也能從那裡的服務員那兒買到一些做好的菜餚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
