INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10729, 'zhTW', '我從未見過一塊土地經歷像外域如此激烈的戰爭與衝突。最悲慘的受害者是那些被遺棄的孩子們。$B$B而現在撒塔斯城與司凱堤斯的阿拉卡之間的衝突將導致更多的孤兒需要人照顧。這些孩子們通常在沒有未來的希望下成長。$B$B但是你有能力改變這個情形。現在是兒童周，$c，我懇求你自願將歡樂與希望帶給這些孤兒們。', '我從未見過一塊土地經歷像外域如此激烈的戰爭與衝突。最悲慘的受害者是那些被遺棄的孩子們。$B$B而現在撒塔斯城與司凱堤斯的阿拉卡之間的衝突將導致更多的孤兒需要人照顧。這些孩子們通常在沒有未來的希望下成長。$B$B但是你有能力改變這個情形。現在是兒童周，$c，我懇求你自願將歡樂與希望帶給這些孤兒們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10730 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10730, 'zhTW', '我很孤單。真希望這裡有更多和我同齡的孩子。有時候我還真懷念在撒塔斯孤兒院的日子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10732 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10732, 'zhTW', '到了嗎?', '到了嗎?', '到了嗎?', '到了嗎?', NULL, '到了嗎?', NULL, '到了嗎?', NULL, '我這樣穿看起來會很胖嗎?', NULL, '我打賭伊利丹私底下一定是個好人。他只是需要一個媽媽。', NULL, '我打賭冰淇淋要是有插槽味道會更好！', NULL, '男孩有蝨子，女孩有美貌！');
DELETE FROM `npc_text_locale` WHERE `ID` = 10733 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10733, 'zhTW', '我自由了!可是那件秘密…危險了。必須警告阿卡瑪!', '我自由了!可是那件秘密…危險了。必須警告阿卡瑪!', '我自由了！但是秘密……有洩露的危險。必須警告阿卡瑪！', '我自由了!可是那件秘密...危險了。必須警告阿卡瑪!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10734 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10734, 'zhTW', '為什麼外域不再叫做德拉諾了呢?', '為什麼外域不再叫做德拉諾了呢?', NULL, '為什麼外域不再叫做德拉諾了呢?', NULL, '為什麼外域不再叫做德拉諾了呢?', NULL, '為什麼外域不再叫做德拉諾了呢?', NULL, '如果馬有馬蹄鐵，那我會有德萊尼蹄鐵嗎?', NULL, '如果燃燒軍團是這樣一個問題，為什麼不用水倒在他們身上?那麼他們就只能是軍團了。', NULL, '你如何吃吃喝喝這麼多，但卻不會發胖呀?', NULL, '那魯想要睡覺時會關掉聖光嗎?');
DELETE FROM `npc_text_locale` WHERE `ID` = 10735 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10735, 'zhTW', '<莫西斯朝天空掃視。>$B$B某一方面，我忌妒魯克及寇瓦克斯所享有的自由。從世俗的責任中解放的確就是一種最好的祝福。$B$B未來將再次見我展翅高飛，不過首先我得先完成一件任務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10736 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10736, 'zhTW', '吉札很好心的讓我來這裡當學徒，學習所有這些有趣的東西，$g先生:女士;。$B$B<吉歐感到很羞愧。>$B$B但是，我很想念我妹妹。她還在撒塔斯城的孤兒院裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10738 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10738, 'zhTW', 'When you\'re done visiting this exotic city, perhaps you would be interested in celebrating with us. The Lunar Festival is underway in Moonglade; the other cities have transport to the festivities. Come and join the other revelers!', '等你拜訪完這個奇特的城市，或許你就會有興趣和我們一起慶祝。新年慶典在月光林地進行;其他城市有傳送點可前往慶祝。一起來加入其他的狂歡者吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10741 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10741, 'zhTW', '埃蘭已經戰敗了嗎?太好了...我可以感覺到他的勢力已經縮減了 - 即使只有一點點。但是這樣就足夠我執行身為一個看門人該做的事情了!你想要傳送至守護者圖書館嗎，$N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10742 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10742, 'zhTW', '很高興又見到你了，$C$N。朵娜一直探問你的訊息。', '很高興又見到你了，$C$N。朵娜一直探問你的訊息。', '很高興再次見到你，$c$n。多爾南一直在問起你。', '很高興又見到你了，$C$N。朵娜一直探問你的訊息。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10743 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10743, 'zhTW', NULL, '很高興又見到你了，$C$n。瑟蘭德雅一直都在探問你的訊息。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10744 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10744, 'zhTW', '外域的衝突比我看過的所有都還要致命。而最不幸的犧牲就是那些被遺留下來的孩童。$B$B現在，隨著來自司凱堤斯的阿拉卡這股反抗撒塔斯的威脅，將會有更多的孤兒需要照顧。這些孩童通常都活在沒有一個光明未來的絕望之中。', '外域的衝突比我看過的所有都還要致命。而最不幸的犧牲就是那些被遺留下來的孩童。$B$B現在，隨著來自司凱堤斯的阿拉卡這股反抗撒塔斯的威脅，將會有更多的孤兒需要照顧。這些孩童通常都活在沒有一個光明未來的絕望之中。', '外域的戰爭比起我所經歷過的任何戰爭都慘烈。大部分悲慘的受害人都是那些留在後方的孩子。\n現在，斯克提斯的鴉人對沙塔斯城的威脅進一步加劇，那裡也會有更多的孤兒需要照顧。這些孩子看不到光明的未來。\n但是你卻有能力為他們做些什麼。兒童周來了，$c，我懇求你給這些孩子的生活帶來些樂趣和奇蹟吧。', '外域的衝突比我看過的所有都還要致命。而最不幸的犧牲就是那些被遺留下來的孩童。$B$B現在，隨著來自司凱堤斯的阿拉卡這股反抗撒塔斯的威脅，將會有更多的孤兒需要照顧。這些孩童通常都活在沒有一個光明未來的絕望之中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10745 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10745, 'zhTW', '<這個德魯伊好像深深沉睡了，對周遭全無反應。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10746 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10746, 'zhTW', '我打賭你會是最快的，$r。他們將不會放棄追蹤我!我無法躲過他們的追捕，即使是在這也一樣!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10747 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10747, 'zhTW', '想要學習弩可以去找暴風城內維勒武器店的人類武器大師吳平、艾克索達內貿易區的德萊尼武器大師哈戴爾或者是鐵爐堡內密林武器店的地精武器大師比克斯。', '想要學習弩可以去找暴風城內維勒武器店的人類武器大師吳平、艾克索達內貿易區的德萊尼武器大師哈戴爾或者是鐵爐堡內密林武器店的地精武器大師比克斯。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10748 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10748, 'zhTW', '伊琳尼雅·月火，住在達納蘇斯戰士區的夜精靈武器大師，能夠教導你使用弓的方式。', '伊琳尼雅·月火，住在達納蘇斯戰士區的夜精靈武器大師，能夠教導你使用弓的方式。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10749 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10749, 'zhTW', '這間特別商店裡的比克斯能夠教導你使用匕首。如果你還想再往外找的話，其他還有 - 暴風城的吳平，艾克索達的哈戴爾，達納蘇斯的伊琳尼雅·月火 - 都能告訴你一兩件事。我，我從來都不是使用刀劍戰鬥的人。', '這間特別商店裡的比克斯能夠教導你使用匕首。如果你還想再往外找的話，其他還有 - 暴風城的吳平，艾克索達的哈戴爾，達納蘇斯的伊琳尼雅·月火 - 都能告訴你一兩件事。我，我從來都不是使用刀劍戰鬥的人。', '這間特別商店裡的比克斯能夠教導你使用匕首。如果你還想再往外找的話，其他還有 - 暴風城的吳平，艾克索達的哈戴爾，達納蘇斯的伊琳尼雅·月火 - 都能告訴你一兩件事。我，我從來都不是使用刀劍戰鬥的人。', '這間特別商店裡的比克斯能夠教導你使用匕首。如果你還想再往外找的話，其他還有 - 暴風城的吳平，艾克索達的哈戴爾，達納蘇斯的伊琳尼雅·月火 - 都能告訴你一兩件事。我，我從來都不是使用刀劍戰鬥的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10750 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10750, 'zhTW', '伊琳尼雅·月火，達納蘇斯戰士區的夜精靈武器大師，或是布里維夫，鐵爐堡內密林武器店的矮人武器大師，都能夠教導你使用拳類武器的方式。', '伊琳尼雅·月火，達納蘇斯戰士區的夜精靈武器大師，或是布里維夫，鐵爐堡內密林武器店的矮人武器大師，都能夠教導你使用拳類武器的方式。', '伊琳尼雅·月火，達納蘇斯戰士區的夜精靈武器大師，或是布里維夫，鐵爐堡內密林武器店的矮人武器大師，都能夠教導你使用拳類武器的方式。', '伊琳尼雅·月火，達納蘇斯戰士區的夜精靈武器大師，或是布里維夫，鐵爐堡內密林武器店的矮人武器大師，都能夠教導你使用拳類武器的方式。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10751 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10751, 'zhTW', '有關射擊方面可以找布里維夫談談，你可以在鐵爐堡內的密林武器店找到他。', '有關射擊方面可以找布里維夫談談，你可以在鐵爐堡內的密林武器店找到他。', '能教你使用槍的是布里維夫，去鐵爐堡的密林武器店找他吧。', '有關射擊方面可以找布里維夫談談，你可以在鐵爐堡內的密林武器店找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10752 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10752, 'zhTW', '我是奉奈薩斯王子哈拉瑪德的命令來到這裡。有奇怪的東西正在風暴之尖活動著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
