INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10754, 'zhTW', '矮人武器大師布里維夫可以訓練你單手及雙手斧兩種武器。你可以在鐵爐堡的密林武器店找到他。', '矮人武器大師布里維夫可以訓練你單手及雙手斧兩種武器。你可以在鐵爐堡的密林武器店找到他。', '矮人武器大師布里維夫可以訓練你單手及雙手斧兩種武器。你可以在鐵爐堡的密林武器店找到他。', '矮人武器大師布里維夫可以訓練你單手及雙手斧兩種武器。你可以在鐵爐堡的密林武器店找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
