INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10755, 'zhTW', '哈戴爾及布里維夫兩者都能夠告訴你正確揮舞錘子的方法，無論大小。你可以去鐵爐堡密林武器店裡找到布里維夫。哈戴爾住在艾克索達，在貿易區訓練德萊尼。', '哈戴爾及布里維夫兩者都能夠告訴你正確揮舞錘子的方法，無論大小。你可以去鐵爐堡密林武器店裡找到布里維夫。哈戴爾住在艾克索達，在貿易區訓練德萊尼。', '哈戴爾及布里維夫兩者都能夠告訴你正確揮舞錘子的方法，無論大小。你可以去鐵爐堡密林武器店裡找到布里維夫。哈戴爾住在艾克索達，在貿易區訓練德萊尼。', '哈戴爾及布里維夫兩者都能夠告訴你正確揮舞錘子的方法，無論大小。你可以去鐵爐堡密林武器店裡找到布里維夫。哈戴爾住在艾克索達，在貿易區訓練德萊尼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
