INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10757, 'zhTW', '法杖類武器是由暴風城維勒武器店的武器大師，吳平所教授，還有伊琳尼雅·月火，於達納蘇斯的戰士區訓練夜精靈們。', '法杖類武器是由暴風城維勒武器店的武器大師，吳平所教授，還有伊琳尼雅·月火，於達納蘇斯的戰士區訓練夜精靈們。', '法杖類武器是由暴風城維勒武器店的武器大師，吳平所教授，還有伊琳尼雅·月火，於達納蘇斯的戰士區訓練夜精靈們。', '法杖類武器是由暴風城維勒武器店的武器大師，吳平所教授，還有伊琳尼雅·月火，於達納蘇斯的戰士區訓練夜精靈們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
