INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10758, 'zhTW', '劍的部分有兩位大師:哈戴爾以及吳平。前者可於艾克索達的貿易區找到他，而後者則可於暴風城裡的維勒武器店找到。', '劍的部分有兩位大師:哈戴爾以及吳平。前者可於艾克索達的貿易區找到他，而後者則可於暴風城裡的維勒武器店找到。', '劍的部分有兩位大師:哈戴爾以及吳平。前者可於艾克索達的貿易區找到他，而後者則可於暴風城裡的維勒武器店找到。', '劍的部分有兩位大師:哈戴爾以及吳平。前者可於艾克索達的貿易區找到他，而後者則可於暴風城裡的維勒武器店找到。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
