INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10759, 'zhTW', '達納蘇斯戰士區的伊琳尼雅·月火以及鐵爐堡密林武器店的比克斯兩者都能告訴你正確使用投擲武器的方法。', '達納蘇斯戰士區的伊琳尼雅·月火以及鐵爐堡密林武器店的比克斯兩者都能告訴你正確使用投擲武器的方法。', '達納蘇斯戰士區的伊琳尼雅·月火以及鐵爐堡密林武器店的比克斯兩者都能告訴你正確使用投擲武器的方法。', '達納蘇斯戰士區的伊琳尼雅·月火以及鐵爐堡密林武器店的比克斯兩者都能告訴你正確使用投擲武器的方法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
