INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10761, 'zhTW', '我在這裡的勇敢同伴比克斯可以訓練你使用弩。不過如果你想找其他的訓練師，你也許想要找看看位於達納蘇斯戰士區的伊琳尼雅·月火，或者也許你可以找位於艾克索達內貿易區的德萊尼武器大師哈戴爾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10762 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10762, 'zhTW', '這裡的比克斯能夠教導你如何投擲武器。如果你離達納蘇斯夠近的話，去那裡與戰士區的伊琳尼雅·月火談談。', '這裡的比克斯能夠教導你如何投擲武器。如果你離達納蘇斯夠近的話，去那裡與戰士區的伊琳尼雅·月火談談。', '這裡的比克斯能夠教導你如何投擲武器。如果你離達納蘇斯夠近的話，去那裡與戰士區的伊琳尼雅·月火談談。', '這裡的比克斯能夠教導你如何投擲武器。如果你離達納蘇斯夠近的話，去那裡與戰士區的伊琳尼雅·月火談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
