INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10764, 'zhTW', '我在這裡的夥伴布里維夫可以告訴你如何使用拳套武器……或者，如果你比較喜歡，伊琳尼雅·月火 - 位於達納蘇斯戰士區的夜精靈武器大師 - 也可以告訴你!', '我在這裡的夥伴布里維夫可以告訴你如何使用拳套武器……或者，如果你比較喜歡，伊琳尼雅·月火 - 位於達納蘇斯戰士區的夜精靈武器大師 - 也可以告訴你!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
