INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10766, 'zhTW', '錘類武器是布里維夫的專長!他就在這家店的某處，發勞騷中。如果他的訓練技術非你的風格，我聽說艾克索達的德萊尼武器大師，哈戴爾，也對武器有他的一套方式!他就在貿易區的上層。', '錘類武器是布里維夫的專長!他就在這家店的某處，發勞騷中。如果他的訓練技術非你的風格，我聽說艾克索達的德萊尼武器大師，哈戴爾，也對武器有他的一套方式!他就在貿易區的上層。', '錘類武器是布里維夫的專長!他就在這家店的某處，發勞騷中。如果他的訓練技術非你的風格，我聽說艾克索達的德萊尼武器大師，哈戴爾，也對武器有他的一套方式!他就在貿易區的上層。', '錘類武器是布里維夫的專長!他就在這家店的某處，發勞騷中。如果他的訓練技術非你的風格，我聽說艾克索達的德萊尼武器大師，哈戴爾，也對武器有他的一套方式!他就在貿易區的上層。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
