INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10771, 'zhTW', '奧格瑪內榮譽谷的武器大師，塞尤克與哈納什，都能教授你使用弓射箭的方法。伊利達，銀月城遠行者廣場的武器大師，也是箇中好手。', '奧格瑪內榮譽谷的武器大師，塞尤克與哈納什，都能教授你使用弓射箭的方法。伊利達，銀月城遠行者廣場的武器大師，也是箇中好手。', '奧格瑞瑪榮譽谷內的武器大師塞尤克和哈納什可以教你如何射箭，銀月城遠行者廣場的武器大師伊蕾達同樣也是這方面的專家。', '奧格瑪內榮譽谷的武器大師，塞尤克與哈納什，都能教授你使用弓射箭的方法。伊利達，銀月城遠行者廣場的武器大師，也是箇中好手。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
