INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10773, 'zhTW', '學習匕首可找以下三位武器大師:幽暗城戰爭區的阿基巴德，奧格瑪榮譽谷的塞尤克，以及銀月城遠行者廣場的伊利達。', '學習匕首可找以下三位武器大師:幽暗城戰爭區的阿基巴德，奧格瑪榮譽谷的塞尤克，以及銀月城遠行者廣場的伊利達。', '學習匕首可找以下三位武器大師:幽暗城戰爭區的阿基巴德，奧格瑪榮譽谷的塞尤克，以及銀月城遠行者廣場的伊利達。', '學習匕首可找以下三位武器大師:幽暗城戰爭區的阿基巴德，奧格瑪榮譽谷的塞尤克，以及銀月城遠行者廣場的伊利達。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10774 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10774, 'zhTW', '拳套是由位於奧格瑪的獸人武器大師，塞尤克所指導。他通常都在榮譽谷那。', '拳套是由位於奧格瑪的獸人武器大師，塞尤克所指導。他通常都在榮譽谷那。', '你可以在奧格瑞瑪的獸人武器大師塞尤克那裡學會使用拳套。他每天都在榮譽谷。', '拳套是由位於奧格瑪的獸人武器大師，塞尤克所指導。他通常都在榮譽谷那。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10775 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10775, 'zhTW', '我們的射擊指導是位於雷霆崖低層中部高地的牛頭人武器大師，安塞瓦。', '我們的射擊指導是位於雷霆崖低層中部高地的牛頭人武器大師，安塞瓦。', '我們的射擊教師是安塞瓦，居住在雷霆崖中部高地底層的牛頭人武器大師。', '我們的射擊指導是位於雷霆崖低層中部高地的牛頭人武器大師，安塞瓦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
