INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10776, 'zhTW', '錘類武器由安塞瓦所教導，可以在雷霆崖的低層中部高地找到他。', '錘類武器由安塞瓦所教導，可以在雷霆崖的低層中部高地找到他。', '安塞瓦會教你怎麼使用錘子，你可以在雷霆崖的中部高地底層找到他。', '錘類武器由安塞瓦所教導，可以在雷霆崖的低層中部高地找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10777 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10777, 'zhTW', '被遺忘者的武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的軍事區訓練人們。銀月城遠行者廣場的血精靈武器大師，伊利達，也可以告訴你相關的技巧。', '被遺忘者的武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的軍事區訓練人們。銀月城遠行者廣場的血精靈武器大師，伊利達，也可以告訴你相關的技巧。', '被遺忘者的武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的軍事區訓練人們。銀月城遠行者廣場的血精靈武器大師，伊利達，也可以告訴你相關的技巧。', '被遺忘者的武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的軍事區訓練人們。銀月城遠行者廣場的血精靈武器大師，伊利達，也可以告訴你相關的技巧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10778 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10778, 'zhTW', '法杖類武器由位於奧格瑪榮譽谷的食人妖武器大師，哈納什所教導，以及位於雷霆崖低層中部高地進行訓練的牛頭人武器大師，安塞瓦。', '法杖類武器由位於奧格瑪榮譽谷的食人妖武器大師，哈納什所教導，以及位於雷霆崖低層中部高地進行訓練的牛頭人武器大師，安塞瓦。', '奧格瑞瑪榮譽谷的巨魔武器大師哈納什和雷霆崖中部高地底層的牛頭人武器大師安塞瓦可以教你如何使用法杖。', '法杖類武器由位於奧格瑪榮譽谷的食人妖武器大師，哈納什所教導，以及位於雷霆崖低層中部高地進行訓練的牛頭人武器大師，安塞瓦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10779 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10779, 'zhTW', '血精靈的伊利達，可在銀月城的遠行者廣場中找到他，訓練他的學生單手及雙手劍。阿基巴德，幽暗城的武器大師，也能夠訓練你;他就在軍事區那。', '血精靈的伊利達，可在銀月城的遠行者廣場中找到他，訓練他的學生單手及雙手劍。阿基巴德，幽暗城的武器大師，也能夠訓練你;他就在軍事區那。', '銀月城遠行者廣場的血精靈伊蕾達會教你學習使用單手劍和雙手劍。幽暗城的武器大師阿基巴德同樣也能教你，他就在軍事區。', '血精靈的伊利達，可在銀月城的遠行者廣場中找到他，訓練他的學生單手及雙手劍。阿基巴德，幽暗城的武器大師，也能夠訓練你;他就在軍事區那。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10780 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10780, 'zhTW', '塞尤克與哈納什，奧格瑪的武器大師，是專精投擲武器的大師。他們在榮譽谷訓練那些自願的學生們。不過，以此項技術的專精程度來說，銀月城遠行者廣場的伊利達才是所向無敵。', '塞尤克與哈納什，奧格瑪的武器大師，是專精投擲武器的大師。他們在榮譽谷訓練那些自願的學生們。不過，以此項技術的專精程度來說，銀月城遠行者廣場的伊利達才是所向無敵。', '奧格瑞瑪的武器大師塞尤克和哈納什是真正的投擲武器專家。他們在榮譽谷訓練所有對此有興趣的學生；如果想看更加優雅的投擲姿勢，那麼沒人比得上銀月城遠行者廣場的伊蕾達。', '塞尤克與哈納什，奧格瑪的武器大師，是專精投擲武器的大師。他們在榮譽谷訓練那些自願的學生們。不過，以此項技術的專精程度來說，銀月城遠行者廣場的伊利達才是所向無敵。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10781 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10781, 'zhTW', '阿基巴德，十字弩的大師。他是幽暗城的武器大師，位於軍事區那。', '阿基巴德，十字弩的大師。他是幽暗城的武器大師，位於軍事區那。', '阿基巴德是弩類武器的教師。他是幽暗城的武器大師，就在軍事區。', '阿基巴德，十字弩的大師。他是幽暗城的武器大師，位於軍事區那。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10782 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10782, 'zhTW', '塞尤克，這邊那個醜陋的獸人，可以教你使用匕首。你想要在別的地方學習的話，你可以找銀月城遠行者廣場的伊利達或是幽暗城戰爭區的阿基巴德談談，知道嗎?', '塞尤克，這邊那個醜陋的獸人，可以教你使用匕首。你想要在別的地方學習的話，你可以找銀月城遠行者廣場的伊利達或是幽暗城戰爭區的阿基巴德談談，知道嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10783 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10783, 'zhTW', '你想要拳擊事物，對吧?去跟這裡的塞尤克談談。他會教你的。', '你想要拳擊事物，對吧?去跟這裡的塞尤克談談。他會教你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10784 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10784, 'zhTW', '我們的射擊指導，安塞瓦，位於雷霆崖低層中部高地的牛頭人武器大師。', '我們的射擊指導，安塞瓦，位於雷霆崖低層中部高地的牛頭人武器大師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
