INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10786, 'zhTW', '那位被遺忘者武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的戰爭區訓練其他人。伊利達，銀月城內遠行者廣場的血精靈武器大師，也會告訴你正確的技巧，小子。', '那位被遺忘者武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的戰爭區訓練其他人。伊利達，銀月城內遠行者廣場的血精靈武器大師，也會告訴你正確的技巧，小子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10787 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10787, 'zhTW', '血精靈的伊利達，位於銀月城的遠行者廣場，訓練她的學生使用單手及雙手劍。阿基巴德，位於幽暗城的武器大師，也可以訓練你，小子。他就在軍事區。', '血精靈的伊利達，位於銀月城的遠行者廣場，訓練她的學生使用單手及雙手劍。阿基巴德，位於幽暗城的武器大師，也可以訓練你，小子。他就在軍事區。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10788 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10788, 'zhTW', '這裡的哈納什對法杖類武器很熟悉。如果你想要一個強力的指導者，到雷霆崖去。安塞瓦會在低層中部高地處指導你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10789 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10789, 'zhTW', '如果你不是要來訓練的，就退後點讓我好好工作。', '如果你不是要來訓練的，就退後點讓我好好工作。', '如果你不是要來訓練的，就退後點讓我好好工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10790 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10790, 'zhTW', '我無法瞭解為何你想要學其他的東西……不過我猜想我能夠指引你正確的方向。你之後有特別想要進行哪一種訓練嗎?', '我無法瞭解為何你想要學其他的東西……不過我猜想我能夠指引你正確的方向。你之後有特別想要進行哪一種訓練嗎?', '我無法瞭解為何你想要學其他的東西……不過我猜想我能夠指引你正確的方向。你之後有特別想要進行哪一種訓練嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10791 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10791, 'zhTW', '當心那些包圍我們四方的以太皇族。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10792 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10792, 'zhTW', '過來然後我會讓你見識到前所未見的方式來駕馭這匹優良野獸。我相信，你…有足夠的金錢可以付費吧?', '過來然後我會讓你見識到前所未見的方式來駕馭這匹優良野獸。我相信，你…有足夠的金錢可以付費吧?', '過來，我會教如何騎乘這些坐騎。不過，你……帶了足夠的錢來付這筆費用吧？', '過來然後我會讓你見識到前所未見的方式來駕馭這匹優良野獸。我相信，你…有足夠的金錢可以付費吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10793 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10793, 'zhTW', '歡迎來到永恆樹林，$c。泰姆昂與我已經研究劍刃山脈的阿拉卡有一段時日了，我們也發現了他們和他們在泰洛卡的親戚們具有一些令人擔心的差異性。', '歡迎來到永恆樹林，$c。泰姆昂與我已經研究劍刃山脈的阿拉卡有一段時日了，我們也發現了他們和他們在泰洛卡的親戚們具有一些令人擔心的差異性。', '歡迎來到常青林，$c。坦莫和我一直在研究刀鋒山一帶的鴉人，最近，我們發現他們和那些泰羅卡森林的鴉人之間有著一些令人擔憂的差別。', '歡迎來到永恆樹林，$c。泰姆昂與我已經研究劍刃山脈的阿拉卡有一段時日了，我們也發現了他們和他們在泰洛卡的親戚們具有一些令人擔心的差異性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10794 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10794, 'zhTW', '<這個阿拉卡鬼魂向你靠過來好像試著要辨認你是誰。你印象中它無法清楚的看見你。>$B$B洛卡拉姆，是你嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10795 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10795, 'zhTW', '原諒我對你的質疑，我的兒子。我的眼力已大不如前，不過烏鴉已經祝福我長命百歲了。$B$B<塞可往他的肩膀後看了一眼，就像他要傳達一個秘密一樣。>$B$B很快，就會是你取代我的時候了。我會將我所有的知識傳授給你。我唯一的悔恨就是我無法取回我們神聖的烏鴉聖典來證明我的價值。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10796 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10796, 'zhTW', '忠實的信徒們一直活在羞恥中，自從我們位於司凱堤斯那些背叛的族人從我們身邊偷走聖典，打碎它的石板，並在他們那個卑鄙的城市將碎片燒燬!$B$B祈禱烏鴉將選中你來取回聖典，我的兒子。要有信心並永遠記取預言，「烏鴉重回這個世界將始於敵人之夢。」', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10797 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10797, 'zhTW', '葛羅克尋求幫忙。小$r去山脈那幫助血槌!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10798 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10798, 'zhTW', '你去見了莫格多克?', '你去見了莫格多克?', '你去找莫戈多格嗎？', '你去見了莫格多克?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10799 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10799, 'zhTW', '我在找尋一個技術絕佳的$g英雄:英雌;。$G他:她;將會召集其他人來解救血槌氏族，還有來自我們古羅迫害者殘暴統治的所有位於這些山脈的巨魔。$B$B等你盡其所能的學完所有事物後回來找我。不過，$c，守住這個秘密免得古羅得到有關我們地下行動的風聲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10800 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10800, 'zhTW', '如果我們想要擺脫我們的束縛並再次活得如同自由的巨魔的話就一定要打倒戈魯爾之子!$B$B如果我們的暗中反抗要成功的話，我們就一定要安靜的進行，但是速度要快。', '如果我們想擺脫身上的枷鎖，再次享受自由的滋味，就必須殺死所有的格魯爾之子！但是，我們必須隱秘行動，只有透過秘密的抵抗行動，我們才有機會獲得成功。', '如果我們想擺脫身上的枷鎖，再次享受自由的滋味，就必須殺死所有的格魯爾之子！但是，我們必須隱秘行動，只有透過秘密的抵抗行動，我們才有機會獲得成功。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10801 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10801, 'zhTW', '我擔心喬渥上校可能只能藉由一種危險的儀式來挽救...一種驅邪儀式。', '要想拯救尤勒斯上校，恐怕只能利用那種危險性很高的儀式——是的，驅魔儀式。', '要想拯救尤勒斯上校，恐怕只能利用那種危險性很高的儀式——是的，驅魔儀式。', '我擔心喬渥上校可能只能藉由一種危險的儀式來挽救…一種驅邪儀式。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10807 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10807, 'zhTW', '我的眼睛會欺騙我嗎?那真的是你嗎，洛卡拉姆兄弟，在過了這些時日之後?$B$B如果你要找塞可，他就在漩渦尖塔西側的水晶之間走來走去。他好像專注於那裡一個他稱之作殘酷，原始的鬼魂，雖然好像沒有任何不對勁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10808 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10808, 'zhTW', '你也許在對待動物方面有一兩把刷子，不過你曾經到過天上嗎?我們蠻錘們知道如何有效地駕馭風。如果你有勇氣的話，只要一點點的費用，我將會好好的訓練你。', '你也許在對待動物方面有一兩把刷子，不過你曾經到過天上嗎?我們蠻錘們知道如何有效地駕馭風。如果你有勇氣的話，只要一點點的費用，我將會好好的訓練你。', '你也許瞭解一點點駕馭走獸的技巧，但是你有乘坐飛禽自由飛翔的經歷嗎？蠻錘矮人懂得如何馴養最好的飛行坐騎。如果你有膽的話，只需付一筆小錢，我就教給你這項技能。', '你也許在對待動物方面有一兩把刷子，不過你曾經到過天上嗎?我們蠻錘們知道如何有效地駕馭風。如果你有勇氣的話，只要一點點的費用，我將會好好的訓練你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10809 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10809, 'zhTW', '當你想到蠻錘時你會聯想到什麼呢，嗯?獅鷲獸駕駛，如果你還有印象的話!影月不是鷹巢山，不過我們仍然有好貨色可以提供給你，是的，好貨色喔。看一看我的小美人們並看看你挑中當中的哪一隻吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10817 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10817, 'zhTW', '你看起來好像對你周遭的陸行性動物很有一套的樣子，不過如果你想要飛起，就需要訓練及專心一致。還有金錢。你有金錢，對吧?', '你看起來好像對你周遭的陸行性動物很有一套的樣子，不過如果你想要飛起，就需要訓練及專心一致。還有金錢。你有金錢，對吧?', NULL, '你看起來好像對你周遭的陸行性動物很有一套的樣子，不過如果你想要飛起，就需要訓練及專心一致。還有金錢。你有金錢，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10818 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10818, 'zhTW', '很棒的動物，對吧?我們這裡養的翼龍都是訓練來面對德拉諾最猛烈及最奇怪的天氣狀況。你會發現他們很可靠且堅強。', '很棒的動物，對吧?我們這裡養的翼龍都是訓練來面對德拉諾最猛烈及最奇怪的天氣狀況。你會發現他們很可靠且堅強。', '很棒的動物，對吧?我們這裡養的翼龍都是訓練來面對德拉諾最猛烈及最奇怪的天氣狀況。你會發現他們很可靠且堅強。', '很棒的動物，對吧?我們這裡養的翼龍都是訓練來面對德拉諾最猛烈及最奇怪的天氣狀況。你會發現他們很可靠且堅強。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10819 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10819, 'zhTW', '我不在意你是何方神聖或者你在御天者外面做了什麼事，不過當你到這來你就得奉命行事。', '我不關心你是誰，或是你在天空衛隊以外做些什麼。不過只要你在這裡，你就要聽從我的命令。', '我不關心你是誰，或是你在天空衛隊以外做些什麼。不過只要你在這裡，你就要聽從我的命令。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10821 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10821, 'zhTW', '等我長大我要成為一位制皮匠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10830 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10830, 'zhTW', '關於這個...人，已經有一些抱怨出現了。我聽說他在從事見不得人的勾當。我是到此來判定他的這檔生意是否合法...並於可證明其他事物時提出訴訟。', '關於這個...人，已經有一些抱怨出現了。我聽說他在從事見不得人的勾當。我是到此來判定他的這檔生意是否合法...並於可證明其他事物時提出訴訟。', '到處都是對這個……這個傢伙的抱怨聲。據說他是個可疑的人物。我是來調查他的生意是否合法的……如果他膽敢做違法的勾當，我就會立即採取行動。', '關於這個...人，已經有一些抱怨出現了。我聽說他在從事見不得人的勾當。我是到此來判定他的這檔生意是否合法...並於可證明其他事物時提出訴訟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10831 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10831, 'zhTW', '如果你設法集滿了全套的風暴套卡你就會得到憤怒之高階暗月卡片。這將會增加你法術或物理攻擊的致命一擊機率直到擊殺為止。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10832 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10832, 'zhTW', '如果你設法集滿了全套的失心套卡，你就會得到瘋狂之高階暗月卡片。這股瘋狂的力量將於你每一次殺死敵人時充滿你的身體。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10833 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10833, 'zhTW', '如果你設法集滿了全套的祝福套卡，你就會得到聖戰之高階暗月卡片。這將會在你戰鬥時增加你的法術以及攻擊傷害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10834 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10834, 'zhTW', '如果你設法集滿了全套的狂怒套卡，你就會得到復仇之高階暗月卡片。當使用這張卡的同時，任何攻擊你的人都有機會遭到神聖復仇攻擊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
