INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10838, 'zhTW', '是的,$g 國王:皇后;！', NULL, '你殺死了戈隆！現在你在同來自空中的敵人作戰？', NULL, '我為 $N而活！ $N!', NULL, '這很好喝！', NULL, '如果$G 國王 : 女王; $N跳舞，我也跳舞！', NULL, '$G 國王: 女王; 不生我氣了？', NULL, '你為什麼那樣看我呀？你不會想吻我吧，對吧！？', NULL, '現在所有戈隆的兒子都死了！現在新的$g 國王:女王;將帶領所有食人魔去奧格瑞拉！', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10841 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10841, 'zhTW', '你最好快點醒過來，菜鳥。這可不是我們在司凱堤斯外的尋常後院;這裡是劍刃山脈!一個失誤就會造成爆炸並燒燬!', '你最好快點醒過來，菜鳥。這可不是我們在司凱堤斯外的尋常後院;這裡是劍刃山脈!一個失誤就會造成爆炸並燒燬!', '你最好快點醒來，新人。這裡不是斯克提斯外的某個舒適的後院，這裡是刀鋒山！一不小心就會導致災難性的後果！', '你最好快點醒過來，菜鳥。這可不是我們在司凱堤斯外的尋常後院;這裡是劍刃山脈!一個失誤就會造成爆炸並燒燬!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10842 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10842, 'zhTW', '好啦現在，你可以去大鍛爐找先知賈瓦德，就在東邊偏北那裡。', '好啦現在，你可以去大鍛爐找先知賈瓦德，就在東邊偏北那裡。', '好啦現在，你可以去大鍛爐找先知賈瓦德，就在東邊偏北那裡。', '好啦現在，你可以去大鍛爐找先知賈瓦德，就在東邊偏北那裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10843 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10843, 'zhTW', '你可以在智慧谷，葛羅瑪許堡，索爾的顧問群中找到大師皮禮諾。', '你可以在智慧谷，葛羅瑪許堡，索爾的顧問群中找到大師皮禮諾。', '身為薩爾酋長大人的顧問，派雷亞諾一直待在智慧谷的格羅瑪什要塞裡。', '你可以在智慧谷，葛羅瑪許堡，索爾的顧問群中找到大師皮禮諾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10846 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10846, 'zhTW', '我可以指導你珠寶設計。有興趣嗎?', '我可以指導你珠寶設計。有興趣嗎?', '我可以教你珠寶加工。有興趣嗎？', '我可以指導你珠寶設計。有興趣嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
