INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10848, 'zhTW', '你沒將這裡當你的家。或許你想吃點什麼東西?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10849 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10849, 'zhTW', '有時候那些該死的血精靈會停下來並要求一些愚蠢的藥劑或毒藥。我必須隨時保持此類物品的存貨充足免得伊利丹王聽到龍喉不配合...$B$B<藍普斯艱難的吞了口水。>$B$B我們不想要那樣...', '有時候那些該死的血精靈會停下來並要求一些愚蠢的藥劑或毒藥。我必須隨時保持此類物品的存貨充足免得伊利丹王聽到龍喉不配合...$B$B<藍普斯艱難的吞了口水。>$B$B我們不想要那樣...', '有時候，那些該死的血精靈會順路從我這裡購買一些特殊的材料或是毒藥。我必須隨時保持這類貨源，以免謠言傳到伊利丹大人耳朵裡，說龍喉氏族不與血精靈合作……\n\n<魯姆普斯艱難地嚥了口氣。>\n\n我們可不希望發生那種事……', '有時候那些該死的血精靈會停下來並要求一些愚蠢的藥劑或毒藥。我必須隨時保持此類物品的存貨充足免得伊利丹王聽到龍喉不配合…$B$B<藍普斯艱難的吞了口水。>$B$B我們不想要那樣…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10850 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10850, 'zhTW', '哦，是的！你想試試這把新式武器，他們會讓我被蛆蟲一樣踩在腳下！', NULL, '你如何與這些蟒蛇競爭？哦哈哈，兄弟！', NULL, '你聽到了嗎？你聽到詠唱，兄弟？他們正在為洛克斯人歡呼！', NULL, '當 Rulk-a-mania向你跑來時，你會怎麼做, 兄弟????!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10851 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10851, 'zhTW', '<圍繞在希瑞身邊的光跳動地轉為藍色。那魯歡迎你如戰場中的盟友一般。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10854 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10854, 'zhTW', '$G兄弟:姐妹;，你現在經由鮮血的認定與虛空之翼建立密切的關係。現在所有虛空之翼都將會支援你!當下就是打擊我們敵人中心的時候，朋友!我們必須復興我們失去的傳統。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10855 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10855, 'zhTW', '你已經為了我們做了許多，$N，但是直到你學會飛行前你可能無法在更進一步了。只有最勇敢的騎士才有辦法協助虛空之翼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10860 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10860, 'zhTW', '你一定懷疑過為何我身為一位巨魔卻可以如此清楚的說話。這是生長在歐格利拉周遭區域的水晶所產生的副作用。那裡的巨魔賦予我此項才能，而水晶本身則賦予我智慧。$B$B經由你在上述的歐格利拉所持續進行的一連序列動，我希望有一天能夠將這些好處帶給我所有的巨魔兄弟們。非常謝謝你，我的$g國王:女王;，對你曾做過以及將來會做的事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10862 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10862, 'zhTW', '另一個，是嗎?你永遠都不會成功的...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10863 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10863, 'zhTW', '記得你一天只能選一樣收集工作來做。除那之外，我們一直都在尋找更多的水晶。任何沒用的苦工都能將那些水晶帶回到營地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10864 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10864, 'zhTW', '我沒什麼可以給你了，小子。你已經長大了，不用再勞動了...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10866 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10866, 'zhTW', '伊利丹對我部族的控制很強硬，$N。這一切將很快地以某種方式結束了。$B$B你準備好了嗎，$N?我的人民的未來就靠我們了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
