INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10889, 'zhTW', '如果你在找機件，小東西，那個什麼的，零件，這個什麼的，新東西，或是小玩意兒，那你就來對地方了!', '如果你在找機件，小東西，那個什麼的，零件，這個什麼的，新東西，或是小玩意兒，那你就來對地方了!', NULL, '如果你在找機件，小東西，那個什麼的，零件，這個什麼的，新東西，或是小玩意兒，那你就來對地方了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10892 AND `Locale` = 'zhTW';
