INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10907, 'zhTW', '啊?什麼?我這裡有點忙，朋友!$B$B當然，如果你是來這裡幫忙的，我就有很多時間了。', '啊?什麼?我這裡有點忙，朋友!$B$B當然，如果你是來這裡幫忙的，我就有很多時間了。', '嗯？什麼？我這裡有點忙，朋友！$B$B當然，要是你是來幫忙的，我有著整個世界的時間。', '啊?什麼?我這裡有點忙，朋友!$B$B當然，如果你是來這裡幫忙的，我就有很多時間了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10909 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10909, 'zhTW', '燒燬在稜柱內的眼睛讓你的心裡充滿一股恐懼的感覺...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10910 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10910, 'zhTW', '惡魔水晶熔爐可以用來轉換你的頂尖裂片為野獸的不穩定精鏈藥劑。這些藥水能讓飲用者更加敏捷，更加強壯而且精力充沛。$B$B在下面當中選一個吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10911 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10911, 'zhTW', '<當你將你的頂尖裂片放進惡魔水晶熔爐並推動控制桿時，這個裝置發出一股沒聽過的聲響，像是在將這些裂片捻為粉塵。幾分鐘後你的藥水就從它的「開口」中掉出來了。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10912 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10912, 'zhTW', '<當你將你的頂尖裂片放進惡魔水晶熔爐並推動控制桿時，這個裝置發出一股沒聽過的聲響，像是在將這些裂片捻為粉塵。幾分鐘後你的藥水就從它的「開口」中掉出來了。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10913 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10913, 'zhTW', '貝許爾水晶熔爐可以用來轉換你的頂尖裂片為巫士的不穩定精鏈藥劑。這些藥水能讓飲用者更加聰明，精力充沛，並增加他們傷害以及治療法術的傷害效果。$B$B在下面當中選一個吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10914 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10914, 'zhTW', '<當你將頂尖裂片放進貝許爾水晶熔爐的凹槽並推動控制桿時，這個裝置直接壓碎這些裂片。幾分鐘後你的藥水就出現在你的腳邊了。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10915 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10915, 'zhTW', '<當你將埃匹希斯水晶放到巴什伊爾的靜止間的孔洞中，然後拉動拉桿，整個裝置自行運轉起來。片刻之後，你的瓶子出現在你腳下。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10916 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10916, 'zhTW', '我們希望你能夠舒緩我們的頭痛。你試試看有10個孩子，每一個都想去做他們本來不做的事!$B$B儘管如此，身為一位父親，我們得做好我們的本份。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10917 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10917, 'zhTW', '你有小孩嗎，$c?$B$B讓我們告訴你，我們覺得在我們到達歐格利拉，並且被這些水晶變得更有知覺之前快樂多了。以前，我們只要痛打他們的頭就可以讓他們閉嘴。現在他們所做得事就是纏著問我們有關薩塔御天者的事。$B$B無知是一種福氣啊!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10918 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10918, 'zhTW', '這個男孩不太會說話 - 發現的水晶還不夠 - 不過，他對於你帶給他的那些藥水還是感覺很感激的。$B$B現在，只剩9個多的孩子要走。唉!$B$B<託卡司的兩個頭同時嘆氣。>$B$B想要帶走一個嗎?我們會賣你便宜一點的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10919 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10919, 'zhTW', '身為歐格利拉相關的初訪者，你沒有因為在這裡發現足夠的水晶而獲得他們充份的好處。而且，你只有一個頭而已。$B$B另外一方面，我們已經到這裡有一段時間了。因此，如同你可以想像的，我們已經知道許多重要的事了。$B$B最近，我們對鍊冶場的惡魔特別的感興趣。再具體一點，我們已經想出一個方法使我們可以永遠的擺脫他們。$B$B至少，這就是原理。', '你剛來奧格瑞拉不久，這些水晶簇的好處你還沒有完全體會到呢。何況，你只有一個腦袋。而我們就不同了。我們在這裡住了很長一段時間了。因此，你可以想象我們聰明的頭腦精通多少事情。最近，我們對鑄魔營地的惡魔挺感興趣的。具體來說，我們設計出了一個徹底擺脫他們的好辦法。至少，理論上是那樣。', '你剛來奧格瑞拉不久，這些水晶簇的好處你還沒有完全體會到呢。何況，你只有一個腦袋。而我們就不同了。我們在這裡住了很長一段時間了。因此，你可以想象我們聰明的頭腦精通多少事情。最近，我們對鑄魔營地的惡魔挺感興趣的。具體來說，我們設計出了一個徹底擺脫他們的好辦法。至少，理論上是那樣。', '身為歐格利拉相關的初訪者，你沒有因為在這裡發現足夠的水晶而獲得他們充份的好處。而且，你只有一個頭而已。$B$B另外一方面，我們已經到這裡有一段時間了。因此，如同你可以想像的，我們已經知道許多重要的事了。$B$B最近，我們對鍊冶場的惡魔特別的感興趣。再具體一點，我們已經想出一個方法使我們可以永遠的擺脫他們。$B$B至少，這就是原理。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10920 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10920, 'zhTW', '我們希望我們可以在一天內製造出多於一個的暗色符文，不過那可能是浪費時間而已。這簡直是不可能的。而且，我們根本不可能準確的按照速度來製造它們。$B$B相信我們，如果這裡有其他人聰明到可以幫忙的話，他們就會被徵召了，那我們就會有足夠的暗色符文。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10921 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10921, 'zhTW', '貝許爾水晶熔爐可以用來轉換你的頂尖裂片為巫士的不穩定精鏈藥劑。這些藥水能讓飲用者更加聰明，精力充沛，並增加他們傷害以及治療法術的傷害效果。$B$B不過，看來似乎你連購買一瓶藥水需要的十片裂片都沒有。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10922 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10922, 'zhTW', '惡魔水晶熔爐可以用來轉換你的頂尖裂片為野獸的不穩定精鏈藥劑。這些藥水能讓飲用者更加敏捷，更加強壯而且精力充沛。$B$B不過，看來似乎你連購買一瓶藥水所需的十片裂片都沒有。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10923 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10923, 'zhTW', '賈克像小$r一樣新到歐格利拉。底下的其他巨魔都談論著說它像天堂一樣。不過這些會讓賈克變聰明點的水晶讓賈克的頭好痛。$B$B<賈克的兩個頭互相對彼此點頭。>$B$B我們正在學著製作那個晶鑄暗色符文。當我們學會了，我們就會毀掉那個惡魔的星移門!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10924 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10924, 'zhTW', '賈克現在變聰明瞭!我們知道如何將暗色符文作成晶鑄暗色符文了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10925 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10925, 'zhTW', '$N幹得好能摧毀那些星移門，不過那些惡魔讓星移門變得更強了。$B$B$N替賈克帶回其他的暗色符文然後賈克會為$N做出更特別的晶鑄暗色符文!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10926 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10926, 'zhTW', '歡迎來到歐格利拉，$c。$B$B這裡的巨魔已經設法經由周遭水晶的魔法放射能中大大提升了我們心智的敏銳程度。雖然我們並不完全瞭解它們是如何運作的，不過我們已經開始欣賞我們的新家，並只想要過平靜的生活。$B$B很不幸的是惡魔及以太族，還有特別是黑龍軍團，將不會讓我們安於平靜。', '歡迎來到歐格利拉，$c。$B$B這裡的巨魔已經設法經由周遭水晶的魔法放射能中大大提升了我們心智的敏銳程度。雖然我們並不完全瞭解它們是如何運作的，不過我們已經開始欣賞我們的新家，並只想要過平靜的生活。$B$B很不幸的是惡魔及以太族，還有特別是黑龍軍團，將不會讓我們安於平靜。', '歡迎來到奧格瑞拉，$c。食人魔透過奧格瑞拉周圍的水晶簇散發出的魔力獲得了敏銳的才智。儘管我們不完全明白這是怎麼回事，但我們喜歡這個新家，只想在這裡過安寧的生活。可是惡魔、虛靈，還有黑龍卻偏偏要來滋擾生事。', '歡迎來到歐格利拉，$c。$B$B這裡的巨魔已經設法經由周遭水晶的魔法放射能中大大提升了我們心智的敏銳程度。雖然我們並不完全瞭解它們是如何運作的，不過我們已經開始欣賞我們的新家，並只想要過平靜的生活。$B$B很不幸的是惡魔及伊斯利，還有特別是黑龍軍團，將不會讓我們安於平靜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10927 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10927, 'zhTW', '謹代表歐格利拉全體，我們要感謝你的努力，$N。$B$B<當裘阿洛右邊的頭對你笑的同時，左邊的頭對你點了點。>$B$B並且不要忘記，藉由在這裡幫助我們的同時，你也保護了我們在底下那些你已身為$g國王:女王;的同胞們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10929 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10929, 'zhTW', '你不行。你還不夠強壯到可以加入積分賽。你還是可以找競技場戰場軍官參加一些練習賽。開始訓練都不會太晚。', '你不行。你還不夠強壯到可以加入積分賽。你還是可以找競技場戰場軍官參加一些練習賽。開始訓練都不會太晚。', '憑你的能力，還不夠資格參加晉級賽。不過你可以找競技場管理員談一談，參加一些練習賽。訓練永遠都不會嫌太晚的。', '你不行。你還不夠強壯到可以加入排名賽。你還是可以找競技場戰場軍官參加一些練習賽。開始訓練都不會太晚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10930 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10930, 'zhTW', '你是來傷害我的嗎?我跟戰爭毫無關係，$r。$B$B我只是一個病厭厭的學者，請放過我!', '你要傷害我嗎？我可不想和戰爭扯上關係，$r。我只是個體弱多病的學者，請你別來打擾我！', '你要傷害我嗎？我可不想和戰爭扯上關係，$r。我只是個體弱多病的學者，請你別來打擾我！', '你是來傷害我的嗎?我跟戰爭毫無關係，$r。$B$B我只是一個病厭厭的學者，請放過我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10931 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10931, 'zhTW', '這顆蛋看起來似乎像黑龍軍團的蛋一樣有彈性。或許如果你放很多頂尖裂片在蛋的周邊的話，裂片本身的震動會使它裂開?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10932 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10932, 'zhTW', '這顆蛋看起來似乎像黑龍軍團的蛋一樣有彈性。或許如果你放置大量的頂尖裂片在蛋周邊的話，裂片本身的震動會使它裂開?$B$B很遺憾的是你好像沒有進行這項工作所需要的35片裂片可以這麼做。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10934 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10934, 'zhTW', '<安琪拉在注意你之前再度對惡魔獵犬低聲的說話。>$B$B澤西永遠都比其他的惡魔獵犬來得小號，不過卻從來不會困擾他。而外域將會改變一切，對吧澤西?$B$B媽咪的小天使將要長大成為一隻巨大，殘爆的惡魔獵犬，沒錯，他就是!', '<安琪拉在注意你之前再度對惡魔獵犬低聲的說話。>$B$B澤西永遠都比其他的惡魔獵犬來得小號，不過卻從來不會困擾他。而外域將會改變一切，對吧澤西?$B$B媽咪的小天使將要長大成為一隻巨大，殘爆的惡魔獵犬，沒錯，他就是!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10936 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10936, 'zhTW', '塞納里奧遠征隊將我從礦坑內必死的狀況中拯救出來。我欠他們一條命!我為那些塞納里奧遠征隊的同伴提供修理及藥劑販售的服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10937 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10937, 'zhTW', '你在這會找到很多事可以做，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10938 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10938, 'zhTW', '啊，你現在在忙對吧?!我不知道要怎麼感激你轟炸那些惡魔還有幫我們補充坐騎才好。$B$B你讓我們所有的工作更加便利了。保持良好的工作，$g小夥子:少女;!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10939 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10939, 'zhTW', '我們一定要在這些礦坑上重建我們的控制權!', '我們一定要在這些礦坑上重建我們的控制權!', '我們必須在礦洞附近重建我們的要塞！', '我們一定要在這些礦坑上重建我們的控制權!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10940 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10940, 'zhTW', '<黑暗之血監督者咕噥著。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10941 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10941, 'zhTW', '他們派你過來殺了我，是嗎?真是預料中…被恐怖所統治的生物都一樣。$B$B不過你…你不是他們其中一員…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10942 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10942, 'zhTW', '監督者?$B$B要是你是個監督者，那我就是暴風之王了。沒錯…你就是他們口中的那個人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10943 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10943, 'zhTW', '虛空之翼。他們跟我們溝通。他們提供我們安詳以及保護。有些事失落者永遠無法感覺。我們接受他們的提議，並協助托拉納庫讓這個礦坑的生物覺醒 - 花了我們很大的心力。我的許多兄弟為此奉獻了他們的生命。我們試著要將這個礦坑弄得不適合居住，迫使龍喉重新尋找居所，最後離開這個島嶼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10944 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10944, 'zhTW', '龍喉墮落了。他們在露天開採這個島嶼的所有自然資源，並用那些資源來提供伊利丹在黑暗神廟之外的軍隊。不過，他們本身拿了不少，並把那些他們私藏的東西賣給出價最高的買家。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10945 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10945, 'zhTW', '我們不知道。我們相信黑龍軍團有介入某些獨力的第三者當中。那就是你為什麼在這的原因，$r。你將會從中解開這個謎團並以此回報虛空之翼。$B$B現在…我只想得到她會要你帶回我的手。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10946 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10946, 'zhTW', '要是這能表示龍喉的落敗的話，我很高興做出這樣的犧牲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10947 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10947, 'zhTW', '我一定要馬上離開這個地方!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10948 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10948, 'zhTW', '頂尖聖物發出微光，透露出內含的一股隱藏的智慧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10949 AND `Locale` = 'zhTW';
