INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10978, 'zhTW', '哈羅，$N。需要快速抵達我們在斯其索山脈的基地，黑風平臺嗎?我有一隻美麗，小型的虛空鰭刺待命中。$B$B你現在就想去嗎?你只要說句話，$g大傢伙:小兔子;!', '哈羅，$N。需要快速抵達我們在斯其索山脈的基地，黑風平臺嗎?我有一隻美麗，小型的虛空鰭刺待命中。$B$B你現在就想去嗎?你只要說句話，$g大傢伙:小兔子;!', '你好，$N。要趕去我們位於鴉羽山的基地黑風碼頭嗎？我為你準備了一隻漂亮的小虛空鰩。\n\n現在就出發嗎？和我說一聲就成！', '哈囉，$N。需要快速抵達我們在斯其索山脈的基地，黑風平臺嗎?我有一隻美麗，小型的虛空鰭刺待命中。$B$B你現在就想去嗎?你只要說句話，$g大傢伙:小兔子;!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10979 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10979, 'zhTW', '哈羅，$g先生:小姐;!如果你要的話，我有一隻虛空鰭刺等著帶你到劍刃山脈上的御天者前哨。$B$B只要跟我說一聲就行了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10980 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10980, 'zhTW', '你好。當你在薩塔御天者的官階晉升時，我就能夠提供你直接飛行到我們位於劍刃山脈上的基地，御天者前哨。', '你好。如果你在沙塔爾天空衛隊的聲望再提升一點，我就為你開通轉至刀鋒山天空衛隊哨站的直達航線。', '你好。如果你在沙塔爾天空衛隊的聲望再提升一點，我就為你開通前往刀鋒山天空衛隊哨站的直達航線。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10982 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10982, 'zhTW', 'Forgetting your skill in Spellfire Tailoring is not something to do lightly.  If you choose to abandon it you will forget all recipes that require Spellfire Tailoring to create!$b$bAre you absolutely sure?', 'Forgetting your skill in Spellfire Tailoring is not something to do lightly.  If you choose to abandon it you will forget all recipes that require Spellfire Tailoring to create!$b$bAre you absolutely sure?$B', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10983 AND `Locale` = 'zhTW';
