INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10997, 'zhTW', '你好，$c!$B$B<卡緹狡猾的看著你。>$B$B任何時候要是你想要幫我們看管更多的蒼穹鰭刺，就設法前來見我!', '你好，$c!$B$B<卡緹狡猾的看著你。>$B$B任何時候要是你想要幫我們看管更多的蒼穹鰭刺，就設法前來見我!', '嗨，$c！$B$B<卡提害羞地看著你。>$B$B如果你願意為我們捕捉更多的以太鰩，可以隨時過來找我！', '你好，$c!$B$B<卡緹狡猾的看著你。>$B$B任何時候要是你想要幫我們看管更多的蒼穹鰭刺，就設法前來見我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
