INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11013, 'zhTW', '能夠得到你如此無私的幫助，是我們食人魔的榮耀。你讓我對有一個更好的未來充滿希望。$B$B現在如果我們能擺脫這些頭疼的事情。你確信你不想從我們這要一個孩子嗎？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
