INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11029, 'zhTW', '你在歐格利拉這裡與我們共渡了一段美好時光嗎?$B$B我們有很多巨魔不分日夜製作的東西。我們將最好的留下來賣給像你這樣優秀的客人!$B$B所以，當你離開去做你的事，並讓山脈變成一個更安全的地方，請常常停下來看看我們有什麼。$B$B祝你出外好運，$g老兄:小妞;。', '你在歐格利拉這裡與我們共渡了一段美好時光嗎?$B$B我們有很多巨魔不分日夜製作的東西。我們將最好的留下來賣給像你這樣優秀的客人!$B$B所以，當你離開去做你的事，並讓山脈變成一個更安全的地方，請常常停下來看看我們有什麼。$B$B祝你出外好運，$g老兄:小妞;。', '你在奧格瑞拉過得很愉快吧？我們有許多手工打造的好東西。我們挑選出最好的貨物，準備出售給你這樣酷斃了的客人！嗯，在你外出執行任務、確保奧格瑞拉安全的同時，有空的時候可以順路過來看看我們出售的貨物。朋友，祝你好運。', '你在歐格利拉這裡與我們共渡了一段美好時光嗎?$B$B我們有很多巨魔不分日夜製作的東西。我們將最好的留下來賣給像你這樣優秀的客人!$B$B所以，當你離開去做你的事，並讓山脈變成一個更安全的地方，請常常停下來看看我們有什麼。$B$B祝你出外好運，$g老兄:小妞;。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11030 AND `Locale` = 'zhTW';
