INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11089, 'zhTW', '看不見的阿拉卡…他們就在我們身邊…看著我們…等待著!', '肉眼見不見的鴉人們……他們就在我們身邊……注視著我們……他們在等待！', '肉眼見不見的鴉人們……他們就在我們身邊……注視著我們……他們在等待！', '看不見的阿拉卡…他們就在我們身邊…看著我們…等待著!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
