INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11128, 'zhTW', '你在這做什麼?你還想要汙辱這一家人的骨灰嗎?快離開，這裡不歡迎你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11136 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11136, 'zhTW', '你似乎是個明理的$c，朋友。你還記得塞拉摩以前風光的歲月嗎?珍娜要我們放棄對抗部落以前的那段美好時光?你是不是已經厭倦了在獸人一直挑釁我們的時候，還聽到人家跟你說別衝動嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11143 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11143, 'zhTW', '無頭騎士的不死心智著魔了!在萬鬼節期間，他對這座村子的攻擊頻繁而恐怖。', '無頭騎士的不死心智著魔了!在萬鬼節期間，他對這座村子的攻擊頻繁而恐怖。', '無頭騎士的靈魂已經變得瘋狂了！在萬聖節期間，他隨時可能襲擊這座村莊！他將在$4676D後歸來。', '無頭騎士的不死心智著魔了!在萬鬼節期間，他對這座村子的攻擊頻繁而恐怖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
