INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11189, 'zhTW', '我花了整天的時間在回收飛艇的零件，但弗雷薩卻連適度的付我鐘點費都不肯。不過你不是為此而來這的，對吧?我打賭你想要知道飛艇坐落的地點。好吧，算你走運 - 我手邊剛好有飛艇追蹤裝置!', '我花了整天的時間在回收飛艇的零件，但弗雷薩卻連適度的付我鐘點費都不肯。不過你不是為此而來這的，對吧?我打賭你想要知道飛艇坐落的地點。好吧，算你走運 - 我手邊剛好有飛艇追蹤裝置!', '我現在整天的時間都花在了收集飛艇零件上，就這樣，弗雷薩還不肯給我加點薪水。至於你，你肯定不是來跟我搶工作的，對吧？我猜你想知道飛艇現在的位置在哪。總之，你運氣不錯，我這裡就有個飛艇追蹤裝置了！', '我花了整天的時間在回收飛艇的零件，但弗雷薩卻連適度的付我鐘點費都不肯。不過你不是為此而來這的，對吧?我打賭你想要知道飛艇坐落的地點。好吧，算你走運 - 我手邊剛好有飛艇追蹤裝置!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11196 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11196, 'zhTW', '名為格利夫塔的商人已經因其詐欺的行為而被逐出這個城市。我們打算非常小心的重新簡視那些他販賣的小飾品。請保持他的攤位淨空好讓我們進行我們的工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11209 AND `Locale` = 'zhTW';
