INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11215, 'zhTW', '你沒看到我還有地方要去，有物件要見嘛!閃邊去，鄉巴佬!', '你沒看到我有好多事情要忙嗎？走開點，農夫！', '你沒看到我有好多事情要忙嗎？走開點，農夫！', '你沒看到我還有地方要去，有物件要見嘛!閃邊去，鄉巴佬!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11217 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11217, 'zhTW', '我只能假定你知道我是誰。而且還一直打擾我?$B$B你究竟想要我注意什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11219 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11219, 'zhTW', '喔拜託，別鬧了!我就是那個唯一的霸德·奈德瑞克$B$B我遍佈這個大陸，從海加爾山頂到沉沒的神廟深處。事實上，我就是第一個叫它為沉沒的神廟的人!$B$B沒錯，就是我。別想改變它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11220 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11220, 'zhTW', '我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道…他是個食人妖。不過他是一個非常特別的食人妖，擁有占卜你未來的能力!$B$B而且我們一直持續地擴充套件馬戲團在各方面的新吸引力!', '我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道…他是個食人妖。不過他是一個非常特別的食人妖，擁有占卜你未來的能力!$B$B而且我們一直持續地擴充套件馬戲團在各方面的新吸引力!', '我強烈建議你去找塞格占卜一下……我知道，他是個豺狼人。但是他是個非常特殊的、可以幫你占卜命運的豺狼人！\n\n我們也在不斷給馬戲團增加新專案以保持吸引力！', '我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道…他是個食人妖。不過他是一個非常特別的食人妖，擁有占卜你未來的能力!$B$B而且我們一直持續地擴充套件馬戲團在各方面的新吸引力!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11221 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11221, 'zhTW', '沒錯，那麼，聽好，$c。我比我外表所見的還年長，而且比我年齡來得有智慧。你最好不要質疑我。$B$B瞧，你並不需要對我說的話太認真。自己去看看任何一個當地佈告欄上的佈告。隨處都是我!$B$B就當是幫你自己的忙，省略掉開頭的「懸賞」吧。我跟你保證，那只是個誤會。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11224 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11224, 'zhTW', '幸會，$c。我正在那跟巴德拉克學著管理獅鷲獸的技巧。有一天，我希望可以有我自己的獅鷲獸欄。', '幸會，$c。我正在那跟巴德拉克學著管理獅鷲獸的技巧。有一天，我希望可以有我自己的獅鷲獸欄。', '$c，很高興見到你。我正在向巴德拉克討教駕馭獅鷲的竅門，希望有一天能有自己的獅鷲棚。', '幸會，$c。我正在那跟巴德拉克學著管理獅鷲獸的技巧。有一天，我希望可以有我自己的獅鷲獸廄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11226 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11226, 'zhTW', '嘿，美人!我可以幫你做什麼嗎?', '嘿，美人!我可以幫你做什麼嗎?', '嗨！有什麼我可以幫忙的嗎？', '嘿，美人!我可以幫你做什麼嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11230 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11230, 'zhTW', '你的決定是什麼呢，小甜心?', '你的決定是什麼呢，小甜心?', '事情會變成什麼樣子呢……', '你的決定是什麼呢，小甜心?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11231 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11231, 'zhTW', '喔，你說我是個廚師?我想你說的沒錯。酒吧女服務員總是偶爾要在廚房裡幹活，而多年來我已經學會了一些食譜。雖然不是什麼特別的菜餚，但是可以豐盛地滿足葛羅克的大胃口。', '喔，你說我是個廚師?我想你說的沒錯。酒吧女服務員總是偶爾要在廚房裡幹活，而多年來我已經學會了一些食譜。雖然不是什麼特別的菜餚，但是可以豐盛地滿足葛羅克的大胃口。', '啊，我的廚藝嗎？應該是吧。作為女招待，當然總得在廚房裡跑來跑去的。我確實學到了一些新的菜譜，雖然不是很特殊，但至少可以填飽葛羅克那無底洞一樣的胃。', '喔，你說我是個廚師?我想你說的沒錯。酒吧女服務員總是偶爾要在廚房裡幹活，而多年來我已經學會了一些食譜。雖然不是什麼特別的菜餚，但是可以豐盛地滿足葛羅克的大胃口。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11233 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11233, 'zhTW', '很抱歉，$N。你已經學會了我所有的烹飪技巧。當然你永遠不知道我們的廚藝什麼時候會研發出新的食譜，所以別害羞，有空的時候儘管回來找我。', '很抱歉，$N。你已經學會了我所有的烹飪技巧。當然你永遠不知道我們的廚藝什麼時候會研發出新的食譜，所以別害羞，有空的時候儘管回來找我。', '我很抱歉，$n，但是我已經沒有什麼可以教你的了。當然，你永遠都不會知道我們的廚師哪一天會突然發明出新的菜譜來，所以不要忘了經常回來看看！', '很抱歉，$N。你已經學會了我所有的烹飪技巧。當然你永遠不知道我們的廚藝什麼時候會研發出新的食譜，所以別害羞，有空的時候儘管回來找我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11234 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11234, 'zhTW', '我的兄弟克里克斯克覺得他在奧格瑪的工作不好。沒有比這個地方更臭了。至少老闆知情理付我安全費用!$B$B什麼?你想看看飛艇在哪了?我這有好東西飛艇追蹤器!', '我的兄弟克里克斯克覺得他在奧格瑪的工作不好。沒有比這個地方更臭了。至少老闆知情理付我安全費用!$B$B什麼?你想看看飛艇在哪了?我這有好東西飛艇追蹤器!', '我的兄弟克里克斯覺得他在奧格瑞瑪的工作很糟糕。但和這個地方的惡臭比較起來，那算的了什麼？不過至少老闆還付給我額外的危險津貼！\n什麼？你想知道飛艇在哪裡？你很幸運，我正好帶著我的飛艇追蹤器！', '我的兄弟克里克斯克覺得他在奧格瑪的工作不好。沒有比這個地方更臭了。至少老闆知情理付我安全費用!$B$B什麼?你想看看飛艇在哪了?我這有好東西飛艇追蹤器!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11243 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11243, 'zhTW', '保持警惕。我們是塞拉摩對抗沼澤中敵人的第一線防禦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11245 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11245, 'zhTW', '既然叛逃者已經接管了迷失哨塔，那麼北點哨塔就是塞拉摩最遠的哨站了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11256 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11256, 'zhTW', '像我這樣的人可以在像這樣的時候為了像你這樣一個$r做什麼事呢?', NULL, '像我這樣的人可以在像這樣的時候為了像你這樣一個$r做什麼事呢?', NULL, '像我這樣的人可以在像這樣的時候為了像你這樣一個$r做什麼事呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11257 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11257, 'zhTW', '我不知道，小子。我是新來的。$B$B我能跟你說的是，我已經有了我的食人妖獵殺量及烈酒可以喝。唯一剩下的就是霸德承諾的寶藏了…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11258 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11258, 'zhTW', '你是說，霸德的成員?$B$B是，他不太尊重人。他會帶著任何一個會用鏟工作的人。$B$B…除了不死族以外。霸德厭惡他們。懼怕他們，可能裝作沒有這事。', NULL, '你是說，霸德的成員?$B$B是，他不太尊重人。他會帶著任何一個會用鏟工作的人。$B$B…除了不死族以外。霸德厭惡他們。懼怕他們，可能裝作沒有這事。', NULL, '你是說，霸德的成員?$B$B是，他不太尊重人。他會帶著任何一個會用鏟工作的人。$B$B…除了不死族以外。霸德厭惡他們。懼怕他們，可能裝作沒有這事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11259 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11259, 'zhTW', '<聞了聞他自己，然後畏縮>$B$B那是探險的味道，$c!', NULL, '<聞了聞他自己，然後畏縮>$B$B那是探險的味道，$c!', NULL, '<聞了聞他自己，然後畏縮>$B$B那是探險的味道，$c!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11264 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11264, 'zhTW', '歡迎來到警戒崗哨，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11279 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11279, 'zhTW', '聽著，老兄!$B$B我會告訴你我所知道的一切，但你必須先將我從這些野蠻生物還有他們兇暴的熊手上救出來。$B$B一言為定?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11281 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11281, 'zhTW', '布洛葛很高興泥鏈哥布林讓他待在這裡，但是有時候覺得他好像聽見他們在笑他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11283 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11283, 'zhTW', '喔耶!坦札爾被釋放了，老兄!$B$B真幸運啊，受了那麼多苦我竟然還毫髮未損。$B$B老天爺的眷顧呀，老兄。我一定是受到眷顧。不用懷疑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11285 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11285, 'zhTW', '$r，我從沒經歷過這種寒冷。就算沒有冰雪落下，北裂境的冰凍荒原也讓人異常艱辛。', '$r，我從沒經歷過這種寒冷。就算沒有冰雪落下，北裂境的冰凍荒原也讓人異常艱辛。', '$r，我從沒經歷過這種寒冷。就算沒有冰雪落下，北裂境的冰凍荒原也讓人異常艱辛。', '$r，我從沒經歷過這種寒冷。就算沒有冰雪落下，北裂境的冰凍荒原也讓人異常艱辛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11287 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11287, 'zhTW', '嗨，你看起來很面熟，我們見過嗎?', NULL, '嗨，你看起來很面熟，我們見過嗎?', NULL, '嗨，你看起來很面熟，我們見過嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11289 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11289, 'zhTW', '好吧，老兄，既然答應你就不能反悔……$B$B我們在某個夜晚溜進祖阿曼檢視地形。$B$B一切是如此的安靜，直到我們聽到一陣沙沙作響的聲音，就像風吹過樹梢一樣。在尚未來得及反應之前，我們已經被那些野蠻生物還有他們的寵物給包圍了!隔天醒來的時候，我已經身陷牢籠了。$B$B日日夜夜，一個接著一個，囚犯們被處決了。每處決一個囚犯，那個熊一般的食人妖就會找下一個更強壯的囚犯。$B$B這就是我對這個地方的瞭解，老兄。而且我再也不想成名了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11291 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11291, 'zhTW', '我長大以後也要當馬伕!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11293 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11293, 'zhTW', '這座旅店在北邊的蠻族喚醒之前就建好了。好在有聖光!$B$B你會長住在這嗎?', '這座旅店在北邊的蠻族喚醒之前就建好了。好在有聖光!$B$B你會長住在這嗎?', '這座旅店在北邊的蠻族喚醒之前就建好了。好在有聖光!\n\n你會長住在這嗎?', '這座旅店在北邊的蠻族喚醒之前就建好了。好在有聖光!$B$B你會長住在這嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11295 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11295, 'zhTW', '那個人只是一個笨蛋!$B$B名聲，財富?呸!這個地方只是一個死亡陷阱罷了，老兄!$B$B在我的年代裡，我看過各式各樣的食人妖，但這些食人妖，他們不太一樣─鬼鬼祟祟、強壯又狡猾。$B$B在我看來他們早就知道我們要來了…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11297 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11297, 'zhTW', '處理*嗝*毒藥和酒…*嗝*酒精很危險…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11299 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11299, 'zhTW', '<霸德看見你靠近的時候轉動了他的眼珠>$B$B喔，是的，即將成為名人的$n!$B$B我能為你和你的夥伴們做些什麼呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11302 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11302, 'zhTW', '冷靜，冷靜，$n，放輕鬆然後深呼吸一下。你應該要學著信任我。$B$B這種處境會使缺乏經驗的你慌張，而慌張總是會使人跨大實情。因此你看，其實並沒有什麼危機產生。$B$B現在我們已經解決了你的疑慮，我必須要求你消除你的負面情緒。這會影響成員們計程車氣……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11309 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11309, 'zhTW', '假如你想跟學徒加利昂談話，他就在小屋裡跟塔貝薩在一起。至少在那邊他沒辦法偷走所有的試劑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11311 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11311, 'zhTW', '我真希望我們在這裡有個牧師或者德魯伊。在傷勢復原之前，我沒辦法繼續研究。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11313 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11313, 'zhTW', '等等，不要告訴我…$n，是嗎?$B$B我能幫你什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11314 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11314, 'zhTW', '喔，呃，看你指得是哪個夥伴啊。這些年有許多人來來去去 - 一直只有霸德·奈德瑞克這個人能夠從容的駕著傳說的順風車!$B$B你可以放心，他們大多數都已經變得富有而且都已經退休了。那不過就不是我選的路罷了。你看，我一直都覺得我發堀了這世界上許多偉大的秘密。唉，捨我其誰呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11315 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11315, 'zhTW', '聽著，$n，你應該知道既然當財寶來敲門，你應該開啟門先，然後再發問。像這樣的機會不是天天都有的!$B$B現在，你到底要不要加入，$c?$B$B<霸德不等你回答。>$B$B你當然會加入!現在，有件事要先完成，不過到目前我看過了太多人只說不做。我建議你在我找到替代者前先讓我看看你的能耐。$B$B我跟你保證，世上有上千人願意為了這樣的機會而死!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11316 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11316, 'zhTW', '啊，他們啊 - 那是一個令人難過的故事。$B$B他們消失在祖阿曼城牆後了。我已經好一陣子沒聽說他們的訊息。$B$B這種事我已經遇過上百次了;過份的渴求名聲及財寶。我試著阻止他們，告訴他們他們還沒準備好，但是最後他們選擇了冒險…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11320 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11320, 'zhTW', '你好!我們被海灘上的廢物海賊給困住了!你想你可不可以幫我們的忙，在他們的頭上丟炸彈呢?!$B$B我們偷來的飛艇來了;在她起錨以前快跳上船去!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11322 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11322, 'zhTW', '你好!我們被海灘上的廢物海賊給困住了!你想你可不可以幫我們的忙，在他們的頭上丟炸彈呢?!$B$B我們偷來的飛艇$3078w分鐘以內就會到了。在她離開之前記得上去喔!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11324 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11324, 'zhTW', '你好!我們被海灘上的廢物海賊給困住了!你想你可不可以幫我們的忙，在他們的頭上丟炸彈呢?!$B$B我們偷來的飛艇就在這附近…我想我聽見她的聲音了。在她離開之前記得上去喔!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11328 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11328, 'zhTW', '我簡直就是個囚犯!$B$B他們把我和我美麗的飛艇從空中打了下來。為了什麼?只為了我是運輸人員所以我算部落軍方的人?這可不是什麼新鮮事!$B$B然後他們要我開著她在海灘上繞圈圈，好讓他們可以轟炸海賊。我沒辦法讓飛艇這樣一直飛啊!我可不能光靠口水和鐵絲讓她不會散開來!$B$B你要是發生了什麼事，我可沒辦法負責，但是你還是得在飛艇離開前趕緊上去。$B$B我告訴你，這是犯罪!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11330 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11330, 'zhTW', '我簡直就是個囚犯!$B$B他們把我和我美麗的飛艇從空中打了下來。為了什麼?只為了我是運輸人員所以我算部落軍方的人?這可不是什麼新鮮事!$B$B然後他們要我開著她在海灘上繞圈圈，好讓他們可以轟炸海賊。我沒辦法讓飛艇這樣一直飛啊!我可不能光靠口水和鐵絲讓她不會散開來!$B$B如果你想要幫他們的忙，她一分鐘之內就會返回港口。$B$B我告訴你，這是犯罪!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11332 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11332, 'zhTW', '我簡直就是個囚犯!$B$B他們把我和我美麗的飛艇從空中打了下來。為了什麼?只為了我是運輸人員所以我算部落軍方的人?這可不是什麼新鮮事!$B$B然後他們要我開著她在海灘上繞圈圈，好讓他們可以轟炸海賊。我沒辦法讓飛艇這樣一直飛啊!我可不能光靠口水和鐵絲讓她不會散開來!$B$B如果你真的想幫他們，她會在$3078w分鐘以內返回港口。$B$B我告訴你，這是犯罪!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11338 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11338, 'zhTW', '拿出你的耐心來，$n。我可不是靠著倉促行事而贏得霸德·奈德瑞克這個名號的。$B$B我已經在做最後的準備，而不久之後祖阿曼的寶藏和秘密都將屬於我的了!$B$B<霸德停止說話並且看了你一下，然後輕笑著。>$B$B…當然，我是說我們的了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11352 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11352, 'zhTW', '我就只是坐在這，日以繼夜的製作彈藥、調整十字弓弦。$B$B我猜你也要我為你做些什麼吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11354 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11354, 'zhTW', '聽著，$c，很明顯的你及你的朋友對於艾澤拉斯很熟悉。想必你已穿越了幾個追求名利的民族。$B$B派幾個可能有意願進入祖阿曼的人給我，我會讓你的付出有價值的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11356 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11356, 'zhTW', '發生了什麼事?', '發生了什麼事?', '發生了什麼事?', '發生了什麼事?', '發生了什麼事?', '發生了什麼事?', '發生了什麼事?', '發生了什麼事?', '要是我媽還活著，她就會熄滅那些火焰！', '要是我媽還活著，她就會熄滅那些火焰！', NULL, NULL, NULL, NULL, NULL, NULL);
