INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11359, 'zhTW', '萬鬼節是個恐怖的節日，但是我喜歡!', '萬鬼節是個恐怖的節日，但是我喜歡!', '萬鬼節是個恐怖的節日，但是我喜歡!', '萬鬼節是個恐怖的節日，但是我喜歡!', '萬鬼節是個恐怖的節日，但是我喜歡!', '萬鬼節是個恐怖的節日，但是我喜歡!', '萬鬼節是個恐怖的節日，但是我喜歡!', '萬鬼節是個恐怖的節日，但是我喜歡!', '無頭騎士住在血色修道院。有時候他會出來嚇嚇大人們，不過不是我！', '無頭騎士住在血色修道院。有時候他會出來嚇嚇大人們，不過不是我！', '我以前跟旅店要到一些糖果。我等不及去要更多的糖了！', '我以前跟旅店要到一些糖果。我等不及去要更多的糖了！', NULL, NULL, NULL, NULL);
