INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11403, 'zhTW', '這裡的情況比我想像的還糟!那艘飛艇只比一堆扭曲的廢鐵加上起火的燃料還要好一點!', '這裡的情況比我想像的還糟!那艘飛艇只比一堆扭曲的廢鐵加上起火的燃料還要好一點!', '這裡的情況比我相信的糟的多！飛艇並不比一堆扭曲的金屬和燃燒的燃料好多少！', '這裡的情況比我想像的還糟!那艘飛艇只比一堆扭曲的廢鐵加上起火的燃料還要好一點!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
