INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11436, 'zhTW', '亞當斯隊長派我來這裡調查霍葛萊發生了什麼事情。然而，就差一點我就能搞清楚了;廢棄的維酷高塔提供了我一些躲避偵查之眼的掩蔽。$B$B被遺忘者在那兒鬼鬼祟祟的，我感覺得出來!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11457 AND `Locale` = 'zhTW';
