INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11472, 'zhTW', '暗月卡有八種種類;野獸，祝福，元素，狂怒，失心，傳送門，風暴以及督軍，每套八張卡片，由一到八。如果你收集到所全部一套八張卡片，那麼你可將它們轉為一副交給我們的薩杜斯·帕里歐教授，交換一個力量強大的墜飾。', '暗月卡有八種種類;野獸，祝福，元素，狂怒，失心，傳送門，風暴以及督軍，每套八張卡片，由一到八。如果你收集到所全部一套八張卡片，那麼你可將它們轉為一副交給我們的薩杜斯·帕里歐教授，交換一個力量強大的墜飾。', '暗月卡片共有八套：野獸、祝福、元素、報復、愚人、入口、風暴和督軍，每套卡片各有八張。如果你能集齊一套八張卡片，就能用一副暗月套牌在薩杜斯·帕雷教授處兌換到強大的飾品。', '暗月卡有八種種類;野獸，祝福，元素，狂怒，失心，傳送門，風暴以及督軍，每套八張卡片，由一到八。如果你收集到所全部一套八張卡片，那麼你可將它們轉為一副交給我們的薩杜斯·帕里歐教授，交換一個力量強大的墜飾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11473 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11473, 'zhTW', '無頭騎士受到瘟疫而神智不清了!在萬鬼節期間，他隨時都有可能來攻擊這個村莊。', '無頭騎士受到瘟疫而神智不清了!在萬鬼節期間，他隨時都有可能來攻擊這個村莊。', '無頭騎士的靈魂已經變得瘋狂了！在萬聖節期間，他隨時可能襲擊這座村莊！他將在$4676D後歸來。', '無頭騎士受到瘟疫而神智不清了!在萬鬼節期間，他隨時都有可能來攻擊這個村莊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
