INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11494, 'zhTW', '我們不該讓那麼多人留在瓦爾加德的。海軍中將凱勒，那個讓人受不了的自我主義者!$B$B我要怎麼用這麼少人來完成命令?我需要足夠的人手待在要塞裡面，準備就緒之後，同時安排適切兵力駐防威德瓦堡壘!$B$B既然你來了，至少我們的問題可望解決了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11496 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11496, 'zhTW', '我建議隊長事情要和我分擔，但是我感覺他可能情願聽你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11498 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11498, 'zhTW', '這些嘴巴都在等著吃，誰得完成這件事?就是我!$B$B所有煮飯，打掃，還有其它的事!', '這些嘴巴都在等著吃，誰得完成這件事?就是我!$B$B所有煮飯，打掃，還有其它的事!', '這些嘴巴都在等著吃，誰得完成這件事?就是我!\n\n所有煮飯，打掃，還有其它的事!', '這些嘴巴都在等著吃，誰得完成這件事?就是我!$B$B所有煮飯，打掃，還有其它的事!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11502 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11502, 'zhTW', '在我的一生之中從沒有想過能夠目睹這樣壯麗的新疆域。$B$B要是它沒有受到邪惡與理應成為禁忌的知識所汙染就好了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11504 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11504, 'zhTW', '我這輩子見識過很多事物，但以發生在低語峽谷中探險者協會的改變最為了不起。$B$B我實在很開心我毫髮無傷的離開那裡了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11538 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11538, 'zhTW', '牛頭大佬將會在每個小時開始時於舞臺上演出。表現出一點活力:為這些音樂家歡呼!讓他們感受到這些活動的熱度!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11549 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11549, 'zhTW', '尊敬你們的長者，凱亞特將可以訓練你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11551 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11551, 'zhTW', '你已經達到了我的知識極限，但是你還有更多東西可以學。越過海洋轉至暴風城的法師區，有一位裁縫大師。他的名字叫喬吉奧?波利羅，我想他可以繼續訓練你，去和他談談吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11562 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11562, 'zhTW', '大地...一片冰封，我們簡直就是活靶;這些血屍戰車哪兒都不能去了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11564 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11564, 'zhTW', '那看起來像什麼?地面凍得跟石頭一樣!$B$B血屍戰車的輪子建來最好是行駛在泥巴地上的。我們需要一頭憎惡以及一些鏈條來搶救這些戰車。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11567 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11567, 'zhTW', '我永遠不會把蕨牆村當作自己的家園。這麼做就等於放棄了奪回我們領土的希望。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11578 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11578, 'zhTW', '那麼，我想我該向你說聲謝謝，$r。$B$B事實上，假如你沒出現的話我想我可能會把我僅有的最後一個酒杯都給吞下肚了呢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11580 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11580, 'zhTW', '那是一個悲傷的故事─也有點令人難為情的故事。$B$B你知道的，我們族人是出了名的愛喝酒。而我也不例外。看起來我愛喝酒的程度比我想像的還嚴重。$B$B於是我跑去找霸德，他說只要我成為他的組員就可以盡情喝個夠─接下來的決定讓我感到後悔。$B$B有一晚，我喝了足夠醉倒一隻科多獸的酒，霸德引誘我跟著他那無法勝任的小組進入祖阿曼。$B$B我記得的下一件事情就是我在那個牢籠中醒過來了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11582 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11582, 'zhTW', '喔，非常感謝你將我從那個牢籠之中救了出來，因為我被關太久了，那裡的味道聞起來就像是剁碎的羊肉放在陽光下曬了一整個禮拜一樣，而我可是一點都不想提起羊肉，那是因為我小時候，比現在還小一點的時候，我真的有過被人變形成一隻羊一陣子的經驗，所以我知道當一隻羊是什麼樣的感覺，並且我不喜歡有人把我吃掉，尤其是一個打扮起來像一隻小貓咪，營養又過盛的食人妖……$B$B<阿西利深深地吸了一口氣。>$B$B我的髮型亂掉了嗎?', '喔，非常感謝你將我從那個牢籠之中救了出來，因為我被關太久了，那裡的味道聞起來就像是剁碎的羊肉放在陽光下曬了一整個禮拜一樣，而我可是一點都不想提起羊肉，那是因為我小時候，比現在還小一點的時候，我真的有過被人變形成一隻羊一陣子的經驗，所以我知道當一隻羊是什麼樣的感覺，並且我不喜歡有人把我吃掉，尤其是一個打扮起來像一隻小貓咪，營養又過盛的食人妖……$B$B<阿西利深深地吸了一口氣。>$B$B我的髮型亂掉了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11586 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11586, 'zhTW', '這些擱淺的聯盟水手知道他們活不久了，所以拼了老命的抵抗。$B$B英勇而可悲。', '這些擱淺的聯盟水手知道他們活不久了，所以拼了老命的抵抗。$B$B英勇而可悲。', '這些擱淺的聯盟水手知道他們活不久了，所以拼了老命的抵抗。\n\n英勇而可悲。', '這些擱淺的聯盟水手知道他們活不久了，所以拼了老命的抵抗。$B$B英勇而可悲。', NULL, '這些擱淺的聯盟水手知道他們活不久了，所以拼了老命的抵抗。$B$B英勇而可悲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11588 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11588, 'zhTW', '就是牆上的那兩尊火炮不斷減緩我們的攻勢。只要沒了火炮的援護，我們就能不費一兵一卒的情形下衝破他們的防禦工事。$B$B要不奪下火炮，要不就等到他們彈盡援絕。我想，安賽姆要做決定。', '就是牆上的那兩尊火炮不斷減緩我們的攻勢。只要沒了火炮的援護，我們就能不費一兵一卒的情形下衝破他們的防禦工事。$B$B要不奪下火炮，要不就等到他們彈盡援絕。我想，安賽姆要做決定。', '就是牆上的那兩尊火炮不斷減緩我們的攻勢。只要沒了火炮的援護，我們就能不費一兵一卒的情形下衝破他們的防禦工事。\n\n要不奪下火炮，要不就等到他們彈盡援絕。我想，安賽姆要做決定。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11590 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11590, 'zhTW', '無頭騎士，本來是白銀之手的一位騎士，也是他手下聖騎士中的一位英雄，卻受到了詛咒。他在血色修道院內發瘋了，相信除了他以外的我們都是不死族。$B$B現在，他的熱情不再服侍聖光。隨著萬鬼節的到來，他到處在艾澤拉斯的村落散佈絕望及烈火。', '無頭騎士，本來是白銀之手的一位騎士，也是他手下聖騎士中的一位英雄，卻受到了詛咒。他在血色修道院內發瘋了，相信除了他以外的我們都是不死族。$B$B現在，他的熱情不再服侍聖光。隨著萬鬼節的到來，他到處在艾澤拉斯的村落散佈絕望及烈火。', '無頭騎士本是白銀之手的成員，可惜這位昔日的英雄被詛咒了。他盤踞在血色修道院中，失去神智的無頭騎士竟然認為自己還活著，我們才是沒有生命的亡者。\n\n他再也不是聖光忠誠的僕從了。隨著萬聖節的來臨，他在艾澤拉斯世界各地的村落中散播著陰暗的種子，還有那仇恨的火焰。', '無頭騎士，本來是白銀之手的一位騎士，也是他手下聖騎士中的一位英雄，卻受到了詛咒。他在血色修道院內發瘋了，相信除了他以外的我們都是不死族。$B$B現在，他的熱情不再服侍聖光。隨著萬鬼節的到來，他到處在艾澤拉斯的村落散佈絕望及烈火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11596 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11596, 'zhTW', 'MISSING TEXT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
