INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11743, 'zhTW', '衝擊者5000型超級大炮是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大炮是布萊頓海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想和鳥一樣在空中翱翔，就去撒塔斯城的聖光露臺找瑪克希瑪·布萊頓海默。她會在城牆外一個小池塘的目標地向你瞄準!', '衝擊者5000型超級大炮是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大炮是布萊頓海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想和鳥一樣在空中翱翔，就去撒塔斯城的聖光露臺找瑪克希瑪·布萊頓海默。她會在城牆外一個小池塘的目標地向你瞄準!', '衝擊者5000型超級大炮是一種代表世界最尖端技術水平的單人發射裝置，它能以龍的速度將人發射出去。發明該設施的地精家族是家喻戶曉的航空領域先驅，這種超級大炮已經成為了家族的榮耀！\n\n如果你想象鳥兒一樣在空中翱翔，就去沙塔斯城的聖光廣場找瑪克希瑪吧。她會把你發射到城外的小池塘去！', '衝擊者5000型超級大炮是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大炮是布萊頓海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想和鳥一樣在空中翱翔，就去撒塔斯城的聖光露臺找瑪克希瑪·布萊頓海默。她會在城牆外一個小池塘的目標地向你瞄準!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11746 AND `Locale` = 'zhTW';
