INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11858, 'zhTW', '探險者協會真好心，願意讓我一路跟著。可是，裂木森林和附近地區危險重重，孤立無援的我看起來真像傻瓜。', '探險者協會真好心，願意讓我一路跟著。可是，裂木森林和附近地區危險重重，孤立無援的我看起來真像傻瓜。', '探險者協會真好心，願意讓我一路跟著。可是，裂木森林和附近地區危險重重，孤立無援的我看起來真像傻瓜。', '探險者協會真好心，願意讓我一路跟著。可是，裂木森林和附近地區危險重重，孤立無援的我看起來真像傻瓜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
