INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11874, 'zhTW', '我會想念冬蹄營地的，但我瞭解為何灰燼圖騰酋長做了這個決定。家就是那個無法永遠負擔起的安逸之所。', '我會想念冬蹄營地的，但我瞭解為何灰燼圖騰酋長做了這個決定。家就是那個無法永遠負擔起的安逸之所。', '我會想念冬蹄營地的，但我瞭解為何灰燼圖騰酋長做了這個決定。家就是那個無法永遠負擔起的安逸之所。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
