INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11884, 'zhTW', '什麼，骨頭啦…肉塊啦…筋肉啦…肌腱啦…軟骨啦…經過我的鋼鋸之後統統拼成一塊兒。', '什麼，骨頭啦…肉塊啦…筋肉啦…肌腱啦…軟骨啦…經過我的鋼鋸之後統統拼成一塊兒。', '什麼，骨頭啦…肉塊啦…筋肉啦…肌腱啦…軟骨啦…經過我的鋼鋸之後統統拼成一塊兒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
