INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11907, 'zhTW', NULL, '喔耶 - 你適時的殺了那個壞食人妖好讓我不會被無助的殺害並解救了我這無辜的小靈魂又破壞了他們想要統治艾澤拉斯的邪惡陰謀並又見試到你是如何冒險解救我遠離必死的境界我一定要回報你的仁慈無論你是誰或是從哪來的所以我幫逃出這裡我將會盡我所能的去找方法酬謝你...$b$b<阿西利深深地吸了一口氣。>$b$b我希望你會喜歡糖果...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
