INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11943, 'zhTW', '讓我猜猜，另一團霸德的烏合之眾?$B$B走開，$r，在你受傷 - 或遇到更糟的事之前。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11945 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11945, 'zhTW', '嗨你好!只因為我比任何人都會競速山羊，不代表我無法出力幫助酒廠。如果你喜歡的話可以幫忙。$B$B不過等等，還有別的!$B$B幫忙啤酒節的事宜代表你有機會可以騎乘各種族中最迅捷的山羊!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11947 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11947, 'zhTW', '啊哈哈，你有看到嗎?格利夫塔回來了!回到我的攤位，帶著我的舊東西，準備好繼續跟你做生意!$B$B想要變得更好，更強壯，更迅速嗎?這些護符的每一個都保證如我所說的作用一般。過來買一個奇妙的玩意兒吧!物超所值喔!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11956 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11956, 'zhTW', '黑暗的時代成就了不可思議的友誼。也許值得到舊羅德隆一遊，觀看被遺忘者焚燒他們的小稻草人。', '黑暗的時代成就了不可思議的友誼。也許值得到舊羅德隆一遊，觀看被遺忘者焚燒他們的小稻草人。', '黑暗的歲月可以促成奇怪的友誼。如果能去舊洛丹倫，觀看被遺忘者們燒燬稻草人的話也挺不錯的。', '黑暗的時代成就了不可思議的友誼。也許值得到舊羅德隆一遊，觀看被遺忘者焚燒他們的小稻草人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11957 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11957, 'zhTW', '我瞭解這個節慶不是我們盟友創造的，而是整個部落。我們為什麼要跟著一起做，我真的不知道。', '我瞭解這個節慶不是我們盟友創造的，而是整個部落。我們為什麼要跟著一起做，我真的不知道。', '這個節日原本是部落發明的，不是聯盟。真不明白我們為什麼也要慶祝。', '我瞭解這個節慶不是我們盟友創造的，而是整個部落。我們為什麼要跟著一起做，我真的不知道。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11958 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11958, 'zhTW', '我們正在慶祝那個誰因為什麼而重獲自由?呸，誰在意啊?!給我們更多的糖果!', '我們正在慶祝那個誰因為什麼而重獲自由?呸，誰在意啊?!給我們更多的糖果!', '我們這是在慶祝誰擺脫了誰的束縛？呸，管它呢？！我要更多的糖果！', '我們正在慶祝那個誰因為什麼而重獲自由?呸，誰在意啊?!給我們更多的糖果!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11959 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11959, 'zhTW', '為什麼每個人一直都說我們地精最不需要的東西就是更多的糖果?!', '為什麼每個人一直都說我們地精最不需要的東西就是更多的糖果?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
