INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11960, 'zhTW', '讓我告訴你，這些免費的糖果真是一樁不划算的生意。或者說……這些東西只是一些噱頭罷了……他們因此把客人騙進旅店，然後用其他的餐點賺你一筆。真是聰明!', '讓我告訴你，這些免費的糖果真是一樁不划算的生意。或者說……這些東西只是一些噱頭罷了……他們因此把客人騙進旅店，然後用其他的餐點賺你一筆。真是聰明!', '讓我告訴你，這些免費的糖果真是一樁不划算的生意。或者說……這些東西只是一些噱頭罷了……他們因此把客人騙進旅店，然後用其他的餐點賺你一筆。真是聰明!', '讓我告訴你，這些免費的糖果真是一樁不划算的生意。或者說……這些東西只是一些噱頭罷了……他們因此把客人騙進旅店，然後用其他的餐點賺你一筆。真是聰明!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
