INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11962, 'zhTW', '去慶祝另一個該死的敵人誕生是件很怪的事，至少可以這麼說。不過，我們還是會於參與我們盟友他們的慶典。', '去慶祝另一個該死的敵人誕生是件很怪的事，至少可以這麼說。不過，我們還是會於參與我們盟友他們的慶典。', '退一步說，慶祝另一位死敵的誕辰真是件詭異的事。不過，我們還是會參加盟友們的節日。', '去慶祝另一個該死的敵人誕生是件很怪的事，至少可以這麼說。不過，我們還是會於參與我們盟友他們的慶典。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11963 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11963, 'zhTW', '被遺忘者慶祝他們的自由是對的。還有什麼更重要呢?', '被遺忘者慶祝他們的自由是對的。還有什麼更重要呢?', '被遺忘者有權慶祝自己重獲自由。還有什麼比這更重要的嗎？', '被遺忘者慶祝他們的自由是對的。還有什麼更重要呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11964 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11964, 'zhTW', '我不瞭解被遺忘者每晚焚燒大型稻草像的涵意，不過我們自己的儀式在他們看起來一定也是很奇怪吧。', '我不瞭解被遺忘者每晚焚燒大型稻草像的涵意，不過我們自己的儀式在他們看起來一定也是很奇怪吧。', '我不瞭解被遺忘者每晚焚燒大型稻草像的涵意，不過我們自己的儀式在他們看起來一定也是很奇怪吧。', '我不瞭解被遺忘者每晚焚燒大型稻草像的涵意，不過我們自己的儀式在他們看起來一定也是很奇怪吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11965 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11965, 'zhTW', '我不知道為什麼被遺忘者要在每個萬鬼節晚上焚燒稻草人而非真人，不過這就是他們的節慶。', '我不知道為什麼被遺忘者要在每個萬鬼節晚上焚燒稻草人而非真人，不過這就是他們的節慶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 11966 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (11966, 'zhTW', '我們在萬鬼節期間慶祝這個由女妖之王將我們從巫妖王及天譴軍團手中解放出來的日子。一定要參加每晚在幽暗城外舉行的稻草人節。', '我們在萬鬼節期間慶祝這個由女妖之王將我們從巫妖王及天譴軍團手中解放出來的日子。一定要參加每晚在幽暗城外舉行的稻草人節。', '我們在萬聖節上狂歡，紀念女妖之王將我們從巫妖王和天災軍團的魔掌中解救出來。每晚在幽暗城外都會舉辦稻草人晚會，記得參加哦。', '我們在萬鬼節期間慶祝這個由女妖之王將我們從巫妖王及天譴軍團手中解放出來的日子。一定要參加每晚在幽暗城外舉行的稻草人節。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12044 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12044, 'zhTW', '我的顧客尋找的多是稀有且珍貴的物品。$B$B你可以是那個將東西帶來給我的人，$c。我提供的報酬會是你所渴望的事物。$B$B我們要不要多談些今天我想要取得的東西呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
