INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12046, 'zhTW', '虛空之風細語著一項命令，而瑪頓恩聽到了。$B$B有一名$g男人:女人;將經過瑪頓恩的面前，而他們討論的正是虛空之風今日要殺的目標。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12049 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12049, 'zhTW', '我們設立這個地區是為了作消防演練。你永遠不知道城鎮什麼時候會陷入災難之中!', '我們設立這個地區是為了作消防演練。你永遠不知道城鎮什麼時候會陷入災難之中!', '我們設立這個地區是為了作消防演練。你永遠不知道城鎮什麼時候會陷入災難之中!', '我們設立這個地區是為了作消防演練。你永遠不知道城鎮什麼時候會陷入災難之中!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
