INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12198, 'zhTW', '這桶麥芽酒由加文·雷酒看管著。只要他在地窖裡，誰都別想碰這些麥芽酒桶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12207 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12207, 'zhTW', '小鬍子船長是最棒的!', NULL, '小鬍子船長是最棒的!', NULL, '小鬍子船長是最棒的!', NULL, '小鬍子船長是最棒的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12208 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12208, 'zhTW', '時代改變了，$N。戰爭來臨了。$B$B我的族人會在這個時機崛起並且協助我們的盟友…或是我們會繼續在邊緣苟延?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12209 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12209, 'zhTW', '我沒有什麼時間可以聊天，抱歉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12210 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12210, 'zhTW', '你沒看到我正在這裡忙嗎，$g小夥子:姑娘;?在被可沃斯基看到我在閒聊之前，快滾。', '你沒看到我正在這裡忙嗎，$g小夥子:姑娘;?在被可沃斯基看到我在閒聊之前，快滾。', '沒看見我正忙著嗎？離我遠點，別讓科瓦斯基撞見了。', '你沒看到我正在這裡忙嗎，$g小夥子:姑娘;?在被可沃斯基看到我在閒聊之前，快滾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12211 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12211, 'zhTW', '啟航的好日子，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12212 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12212, 'zhTW', '多苟利對我們很嚴格，不過他是個好船長，沒錯。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12213 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12213, 'zhTW', '我們已經沒剩多少人了，$N。我們古老宿敵的迴歸令人非常擔憂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12214 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12214, 'zhTW', '我必須得盯牢這艘船及船員，好心的$g先生:女士;。你一定要原諒我無法停下來跟你進行交談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12215 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12215, 'zhTW', '梅利女士號真的就在塞拉摩，我們已經被指派去守衛船上的乘客了。', '梅利女士號真的就在塞拉摩，我們已經被指派去守衛船上的乘客了。', '梅蕾女士號長期停靠塞拉摩島，我們奉命保護船隻上的乘客。', '梅利女士號真的就在塞拉摩，我們已經被指派去護衛船上的乘客了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12216 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12216, 'zhTW', '歡迎來到雄偉的梅利女士號。我是多苟利船長。$B$B如果你對這艘船有任何的疑問，請盡情提問;其他，則請好好享受這趟旅程，一同我一直以來的一樣…最後，容我引述一段我最喜愛的內容:我的航船經驗就是，一個人能夠在這些船上發覺這世界有趣的一面。也有人不需藉此就能完全做到。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12217 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12217, 'zhTW', '是，那就是她的名字，她真是艘好船。$B$B你知道的，還有好多東西可以從這些船艦上學習。一個偉大的詩人曾說:在夜晚穿行的船隻，交錯時彼此傾訴，只有一個暗號，一聲黑暗中的遠音;就像在生命的汪洋中，我們擦肩時互語，只有一顧，只有一言，接著黑暗再臨，寂默再現。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12218 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12218, 'zhTW', '如果你想要點什麼的話，船艙長葛蕾絲可以滿足你的需求。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12219 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12219, 'zhTW', '這艘船的工程師及軍需官，康伯斯先生，可以提供任何你可能需要的物品。要是你的引擎需要維修的話，他也是一位技術不錯的修補工。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12220 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12220, 'zhTW', '啊，沒錯，那個…名字。嗯…如同他們說的，是個好名字，就像信譽一樣，一點小差錯就會毀掉許多的努力。不需要去深究方法及理由;只要說，那就是我為何會被某些人如此稱呼的原因就好了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12221 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12221, 'zhTW', '死者復活，並對那些膽敢侵入他們領域的生物復仇，回頭吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12222 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12222, 'zhTW', '我很幸運。沒有多少牛頭人可以在這樣的護衛艦上當船艙服務員好嗎!格瑞希克斯甚至派我來管這些不可思議的戰鬥獨木舟呢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12226 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12226, 'zhTW', '如果我們想要成功地建立一道傳送門通往奎爾達納斯之島，聯絡整個太陽之井。我們一定會需要一個強大的能量來源好維持傳送門。$B$B我們的目標已經完成了$3269w％。你願意幫助我們嗎，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12227 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12227, 'zhTW', '這座傳送門不像其他通往艾澤拉斯的。要維持它，我們需要更多的法力電池。$B$B否則我們就會失去通往奎爾達納斯之島與太陽之井的通道。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12237 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12237, 'zhTW', '歡迎，$r。$B$B我的店舖終於開了。希望你有看到喜歡的!', '歡迎，$r。$B$B我的店舖終於開了。希望你有看到喜歡的!', '很高興見到你.希望你找到你需要的.', '歡迎，$r。$B$B我的店鋪終於開了。希望你有看到喜歡的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12238 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12238, 'zhTW', '日安，$c。$B$B這裡還有好多事情等著完成。可惜我目前幫不上你的忙，除非我能拿到我的補給品。$B$B我現在才取得$3223w％的刺棘根莖。你提供的任何協助都是有價值的，我向你保證。', '日安，$c。$B$B這裡還有好多事情等著完成。可惜我目前幫不上你的忙，除非我能拿到我的補給品。$B$B我現在才取得$3223w％的刺棘根莖。你提供的任何協助都是有價值的，我向你保證。', '日安，$c。\n\n這裡還有好多事情等著完成。可惜我目前幫不上你的忙，除非我能拿到我的補給品。\n\n我現在才取得$3223w％的刺棘根莖。你提供的任何協助都是有價值的，我向你保證。', '日安，$c。$B$B這裡還有好多事情等著完成。可惜我目前幫不上你的忙，除非我能拿到我的補給品。$B$B我現在才取得$3223w％的刺棘根莖。你提供的任何協助都是有價值的，我向你保證。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12239 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12239, 'zhTW', '這就是凱爾的軍隊用來逃往太陽之井的通道。一些只會奉承他的寵物狗被留了下來；燃燒軍團以一些...不尋常的方法獎賞了他們。', '這就是凱爾的軍隊用來逃往太陽之井的通道。一些只會奉承他的寵物狗被留了下來；燃燒軍團以一些...不尋常的方法獎賞了他們。', '凱爾薩斯的軍隊就是從這裡撤退到太陽之井的。他的一些走狗仍然殘留在這裡，燃燒軍團以最不平常的方式獎賞著他們……', '這就是凱爾的軍隊用來逃往太陽之井的通道。一些只會奉承他的寵物狗被留了下來；燃燒軍團以一些……不尋常的方法獎賞了他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12240 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12240, 'zhTW', '你有看到島上那些受損漫遊的哨兵嗎?只需要對控制水晶做些調整，就讓我們控制這些哨兵，並且用他們來守衛我們的戰略據點。$B$B日境聖所很快就是我們的。我們目前的目標達成率為$3233w％。', '你有看到島上那些受損漫遊的哨兵嗎?只需要對控制水晶做些調整，就讓我們控制這些哨兵，並且用他們來守衛我們的戰略據點。$B$B日境聖所很快就是我們的。我們目前的目標達成率為$3233w％。', '你有沒有看到那些在島上游蕩的魔像守衛？只要對控制它們行動的水晶核心做一些小小的改動，就能讓我們獲得它們的控制權，用它們來保護戰略要地。\n\n陽灣聖殿很快就會是我們的了，眼下我們的目標完成率已經達到了$3244w%。', '你有看到島上那些受損漫遊的哨兵嗎?只需要對控制水晶做些調整，就讓我們控制這些哨兵，並且用他們來守衛我們的戰略據點。$B$B日境聖所很快就是我們的。我們目前的目標達成率為$3233w％。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12241 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12241, 'zhTW', '我們成功地拿下了聖所。我們可以繼續轉換那些哨兵，用他們來防衛其他戰略位置。', '我們成功地拿下了聖所。我們可以繼續轉換那些哨兵，用他們來防衛其他戰略位置。', '我們成功地拿下了聖殿。我們可以繼續轉變這些魔像守衛，用它們來保護其它的戰略要地。', '我們成功地拿下了聖所。我們可以繼續轉換那些哨兵，用他們來防衛其他戰略位置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12242 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12242, 'zhTW', '唷喝!你想要登記搭乘慈悲姐妹號嗎，朋友?那你就來對地方了…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12243 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12243, 'zhTW', '我們必須確保不會再於海中失去任何靈魂。', '我們必須確保不會再於海中失去任何靈魂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
