INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12245, 'zhTW', '許多人在大海中失去了身影。我，以及這些幽光，則負責尋找那些靈魂。', '許多人在大海中失去了身影。我，以及這些幽光，則負責尋找那些靈魂。', '很多人葬身大海。我和小精靈們負責在海面上搜尋靈魂。', '許多人在大海中失去了身影。我，以及這些幽光，則負責尋找那些靈魂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
