INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12267, 'zhTW', '對一個水手來說，不是個好名字，不是嗎?', '對一個水手來說，不是個好名字，不是嗎?', '對一個水手來說，不是個好名字，不是嗎?', '對一個水手來說，不是個好名字，不是嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12268 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12268, 'zhTW', '我這個灰髮的老水手雖然是船員中最老的，不過也是當中最強悍的!是吧?是吧?手臂就像巨魔一樣粗壯!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12270 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12270, 'zhTW', '我們立過誓要盡其所能來保護勇氣號上的乘客。一定要維持魯瑟蘭村與暴風港間航道的安全。', '我們立過誓要盡其所能來保護勇氣號上的乘客。一定要維持魯瑟蘭村與暴風港間航道的安全。', '我們立過誓要盡其所能來保護勇氣號上的乘客。一定要維持奧伯丁與暴風港間航道的安全。', '我們立過誓要盡其所能來保護勇氣號上的乘客。一定要維持奧伯丁與暴風港間航道的安全。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12271 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12271, 'zhTW', '嘿，小子。你登上的是少女之愛號。我是擰鼻船長，你已獲得在黑水強盜群中航行的特權。血帆無法靠近，無法與我精明的船員及手中的大量火藥比擬。你知道的，保險起見。$B$B如果你有任何問題的話，小子，我會知無不言的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12272 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12272, 'zhTW', '沒錯，你正站在她上面。很美，對吧?大財主任命我為船長了。她起初並不屬於我，因此名字不是我取的;小子，如果你想知道我的意見的話，我想當初為她命名的水手花了太多的時間在海上，待在港口的時間並不多，如果你懂我的意思的話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12273 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12273, 'zhTW', '如果你飢腸轆轆的話，去找船艙長鋼腹談談，不過我們之間知道就好?你可能會想等一下。他會叫那個名字不是沒有原因的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12274 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12274, 'zhTW', '一艘熱砂船沒有工程師的話行嗎，對不對?矩軸可以幫忙你所有的需求。他對於快速修復東西也很在行，如果這就是你在尋找的東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12275 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12275, 'zhTW', '歡迎登上羽月渡口。我們往來於羽月要塞及被遺忘的海岸之間搜尋那些在海上失蹤的人們。大海對那些沒做好準備的人來說會是個危險的地方。$B$B如果你需要準備什麼的話，請與我們的物資供應者談談。他們會很樂意幫忙你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12276 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12276, 'zhTW', '謹代表月霧號的船員，歡迎你$c。我希望你會在與我們分別前好好使用我們準備的糧食。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12277 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12277, 'zhTW', '登上伊露恩祝福號時請留意你的腳步，$r。雖然伊露恩使我們有幸發現我們的新朋友，但是我們在大海中也有過艱辛的時候。$B$B不過，找回迷失於大海中或是迷失在一個新世界中的靈魂的確都是來自伊露恩的祝福。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12278 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12278, 'zhTW', '伊露恩在我們每一次的發現中祝福過我們很多次。不過我們必須保持警戒，$c。', '伊露恩在我們每一次的發現中祝福過我們很多次。不過我們必須保持警戒，$c。', '伊露恩在我們每一次的發現中祝福過我們很多次。不過我們必須保持警戒，$c。', '伊露恩在我們每一次的發現中祝福過我們很多次。不過我們必須保持警戒，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12279 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12279, 'zhTW', '請原諒我，$r，我必須專心工作。', '請原諒我，$r，我必須專心工作。', '請原諒我，$r，我必須專心工作。', '請原諒我，$r，我必須專心工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12280 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12280, 'zhTW', '很抱歉，我除了跟幽光還有船長報告我的發現之外，沒有多少時間可以跟人聊天。請原諒我。', '很抱歉，我除了跟幽光還有船長報告我的發現之外，沒有多少時間可以跟人聊天。請原諒我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12281 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12281, 'zhTW', '歡迎登上少女之愛號。它將會一路順風的抵達港口。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12282 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12282, 'zhTW', '如果你用力壓榨地精的話，你可以從他身上學到很驚人的東西:逃脫捆綁的聰明小把戲，製造美味的餅乾，甚至連如何製造出一臺飛行器都有。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12283 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12283, 'zhTW', '常常。這是好活動，讓我可以知道他們在忙些什麼--就我的經驗來說，絕對不是好事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12284 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12284, 'zhTW', '惡惡惡...要是那邊那個骯髒的船艙長要你吃他的特別餐的話，幫你自己個忙，把它丟到海里吧。它可能可以殺死幾個你想致之死地的龍蝦人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12285 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12285, 'zhTW', '嗨，$r。$B$B動手吧!別浪費時間等那些可能永遠也不會到的補給。$B$B我需要我的鐵砧來替部隊打造裝備。目前才完成了$3228w％。$B$B當鐵砧完成後，我將可以為你做出更多強而有力的物品。', '嗨，$r。$B$B動手吧!別浪費時間等那些可能永遠也不會到的補給。$B$B我需要我的鐵砧來替部隊打造裝備。目前才完成了$3228w％。$B$B當鐵砧完成後，我將可以為你做出更多強而有力的物品。', '你好，$r。讓我們開動起來！根本不要指望那些也許永遠都到不了的補給。我需要一塊鐵砧才能為我們的軍隊提供裝備，但是現在只完成了$3228w%。等鐵砧完成之後，我就可以為你鍛造許多強大的武器裝備了。', '嗨，$r。$B$B動手吧!別浪費時間等那些可能永遠也不會到的補給。$B$B我需要我的鐵砧來替部隊打造裝備。目前才完成了$3228w％。$B$B當鐵砧完成後，我將可以為你做出更多強而有力的物品。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12286 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12286, 'zhTW', '嗨，$n。$B$B現在我已經完成了鐵砧，可以開始替部隊提供裝備了。這是很重要的一步，但還有許多事情得去做。$B$B更重要的是，我能製作新東西了，你可能會很感興趣的東西。', '嗨，$n。$B$B現在我已經完成了鐵砧，可以開始替部隊提供裝備了。這是很重要的一步，但還有許多事情得去做。$B$B更重要的是，我能製作新東西了，你可能會很感興趣的東西。', '嗨，$n。\n\n現在我已經完成了鐵鑽，可以開始替部隊提供裝備了。這是很重要的一步，但還有許多事情得去做。\n\n更重要的是，我能製作新東西了，你可能會很感興趣的東西。', '嗨，$n。$B$B現在我已經完成了鐵砧，可以開始替部隊提供裝備了。這是很重要的一步，但還有許多事情得去做。$B$B更重要的是，我能製作新東西了，你可能會很感興趣的東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12287 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12287, 'zhTW', '我們拿下了港口，而這艘船更是額外的收穫。可惜她已經不再適合航行了。$B$B不過我被指派要干擾綠鰓海岸的納迦。$B$B你能給我一些幫助嗎?', '我們拿下了港口，而這艘船更是額外的收穫。可惜她已經不再適合航行了。$B$B不過我被指派要干擾綠鰓海岸的納迦。$B$B你能給我一些幫助嗎?', '我們拿下了港口，而這艘船更是額外的收穫。可惜她已經不再適合航行了。\n\n不過我被指派要干擾綠鰓海岸的納迦。\n\n你能給我一些幫助嗎?', '我們拿下了港口，而這艘船更是額外的收穫。可惜她已經不再適合航行了。$B$B不過我被指派要干擾綠鰓海岸的納迦。$B$B你能給我一些幫助嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12288 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12288, 'zhTW', '歡迎登上喚雷者號!$B$B別在意那些對爆炸或類似事情有所埋怨的人們。我是說真的，每個人都有犯錯的時候。我們應該放過他們。$B$B瞧，我可以瞭解如果一位船長動不動就想把自己的船炸個22或23次的話...不過除此之外的事不值得一提。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12289 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12289, 'zhTW', '<咕噥著>我猜那些山是憑空出現的…總共5次!', NULL, '<咕噥著>我猜那些山是憑空出現的…總共5次!', NULL, '<咕噥著>我猜那些山是憑空出現的…總共5次!', NULL, '<咕噥著>我猜那些山是憑空出現的…總共5次!', NULL, '我從來沒想過我會親眼見到泰達希爾…我當然從來沒想到我們會墜落在泰達希爾。', NULL, '我們現在得設法穿越雷霆崖兩次！', NULL, '<咕噥著>我還是不知道我們是如何設法潛入透過千針石林還沒被發現，卻只是在閃光平原墜毀而已！', NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12290 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12290, 'zhTW', NULL, '如果你喜歡刺激，那可是我們船長最擅長的事了！我愛這份工作！', '如果你喜歡刺激，那可是我們船長最擅長的事了！我愛這份工作！', '如果你喜歡刺激的話，我們的船長是箇中高手!我愛死這份工作了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12291 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12291, 'zhTW', '不要問...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12292 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12292, 'zhTW', '這件事故你不能怪我…我甚至連我要去哪都不知道!$B$B雖然也許那表示你可以責怪我…$B$B不!等等!我還可以將船停靠…這有可能是船長下的命令!也許他喜歡將我們逼到極限，然後測試我們生存及修理的能力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12294 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12294, 'zhTW', '我本來叫做洛羅，直到全鎮秘密的投票將我的名字給改了。我只能接受他們替我取的新名字，不然就得叫做柯爾奇。如果換作是你也會和我的選擇一樣吧。你覺得我的新名字如何呢?好聽多了，對嗎?$B$B對了，假如你想找工作的話可以去看看佈告欄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12300 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12300, 'zhTW', '我很高興你問了。我們完成了計畫的$3233w％。$B$B我知道戰鬥法師艾裡娜和先驅者因努羅需要你的幫忙。你可以在奎爾達納斯之島的日境聖所找到他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12301 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12301, 'zhTW', '我從荷莎那邊聽來，她說我們才完成了目標的$3228w％。$B$B我無法說明完成這些對我們的計畫來說有多重要。我們的男女戰士都需要更好的鎧甲與武器，而鐵砧與熔爐是關鍵。$B$B你將會在日境軍械庫找到鐵匠，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12302 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12302, 'zhTW', '不，很不幸地我們還沒拿下港口。然而，報告顯示我們已經完成了$3238w％的目標。$B$B$N，如果你想要幫忙，可以去找奎爾達納斯之島上日境軍械庫的博學者伊拉斯塔和復仇者卡藍。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12303 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12303, 'zhTW', '鏈金實驗室還沒準備好，$N。瑪納說她才準備了$3223w％，然而。$B$B如果你願意協助她的話，你可以在日境港的旅店中找到她。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12304 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12304, 'zhTW', '我們還在努力終結第一道障壁。拜託，$c，前往奎爾達納斯之島並儘量幫忙我們!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12305 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12305, 'zhTW', '初始之門， 阿格瑪司已經被破壞了，而基爾加丹的兩大副官，莎珂蕾希女士和大術士艾黎瑟絲，一定得被消滅。$B$B召集你的朋友們，$c，解決它!洛罕鐸，次之門是我們下一個目標。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12309 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12309, 'zhTW', '萬一基爾加丹覺醒，透過太陽之井進入我們的世界，他將會掀起一場大戰，就像在10,000年前那樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12314 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12314, 'zhTW', '「鐵鷹。」嗯。它是艘客船，而非戰禽!不過嘿，工作就是工作，而我將迎合船長「浮誇」，既然好人都付錢了。$B$B無論如何，歡迎登船。', '「鐵鷹。」嗯。它是艘客船，而非戰禽!不過嘿，工作就是工作，而我將迎合船長「浮誇」，既然好人都付錢了。$B$B無論如何，歡迎登船。', '鐵鷹號是客船，並不是戰艦！不過，工作就是工作，只要王子還付我們工錢，我們就聽船長的。\n\n不管怎樣，歡迎上船。', '“鐵鷹。”嗯。它是艘客船，而非戰禽!不過嘿，工作就是工作，而我將迎合船長“浮誇”，既然好人都付錢了。$B$B無論如何，歡迎登船。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12315 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12315, 'zhTW', '有點忙。', '有點忙。', '有點忙。', '有點忙。', '有點忙。', '有點忙。', '有點忙。', '有點忙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
