INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12323, 'zhTW', '這個紀念碑很美吧?牢記那些歷史上的重大犧牲是很重要的，免得我們忘記那些戰爭的代價 - 既使是那些勝利的戰爭。', '這個紀念碑很美吧?牢記那些歷史上的重大犧牲是很重要的，免得我們忘記那些戰爭的代價 - 既使是那些勝利的戰爭。', '這個紀念碑很美吧?牢記那些歷史上的重大犧牲是很重要的，免得我們忘記那些戰爭的代價 - 既使是那些勝利的戰爭。', '這個紀念碑很美吧?牢記那些歷史上的重大犧牲是很重要的，免得我們忘記那些戰爭的代價 - 既使是那些勝利的戰爭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
