INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12327, 'zhTW', '歡迎登艦$c。卸下重擔好好享受這趟旅途。在「紫色公主號」上我們希望你能夠覺得放鬆。假如你登船後有任何需要的話，我們樓下備有販賣機。', '歡迎登艦$c。卸下重擔好好享受這趟旅途。在「紫色公主號」上我們希望你能夠覺得放鬆。假如你登船後有任何需要的話，我們樓下備有販賣機。', '歡迎登艦$c。卸下重擔好好享受這趟旅途。在「紫色公主號」上我們希望你能夠覺得放鬆。假如你登船後有任何需要的話，我們樓下備有販賣機。', '歡迎登艦$c。卸下重擔好好享受這趟旅途。在“紫色公主號”上我們希望你能夠覺得放鬆。假如你登船後有任何需要的話，我們樓下備有販賣機。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
