INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12333, 'zhTW', '從葛羅姆高到幽暗城的飛行是多麼的美麗而平靜。當然這不是在工作中睡著的藉口。', '從葛羅姆高到幽暗城的飛行是多麼的美麗而平靜。當然這不是在工作中睡著的藉口。', '儘管格羅姆高營地到幽暗城的航線平淡無奇，但一路上的景色實在太漂亮了。雖然那也不是在工作時候睡著的藉口。', '從葛羅姆高到幽暗城的飛行是多麼的美麗而平靜。當然這不是在工作中睡著的藉口。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12334 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12334, 'zhTW', '經過了灰燼與汙泥。讓你自己風乾一陣子吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12335 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12335, 'zhTW', '牛頭大佬在我替他們安排下一場巡迴演出時都會待在銀月城裡。他們沒排練的時候通常會在我上方的樓臺裡消磨時間。放心揮手吧...他們喜歡接受注目。$B$B我們目前沒有接受表演或是工作人員，不過你以後可以常來連繫看看。誰知道會發生什麼事呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12336 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12336, 'zhTW', '你有看過他們在泰洛卡森林的表演嗎?太驚人了!', '你有看過他們在泰洛卡森林的表演嗎?太驚人了!', '你有看過他們在泰洛卡森林的表演嗎?太驚人了!', '你有看過他們在泰洛卡森林的表演嗎?太驚人了!', '你有看過他們在泰洛卡森林的表演嗎?太驚人了!', '你有看過他們在泰洛卡森林的表演嗎?太驚人了!', '你有看過他們在泰洛卡森林的表演嗎?太驚人了!', '你有看過他們在泰洛卡森林的表演嗎?太驚人了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12338 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12338, 'zhTW', '不要毫無準備地和敵人交戰，$N。我可以提供你非常強大的物品...因為你已經向我們證明了自己。', '不要毫無準備地和敵人交戰，$N。我可以提供你非常強大的物品...因為你已經向我們證明了自己。', '不要在還未準備好的時候就去戰鬥，$N。倘若你已經向我們證明了自己的能力……我就可以給你提供一些非常強大的裝備。', '不要毫無準備地和敵人交戰，$N。我可以提供你非常強大的物品……因為你已經向我們證明了自己。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12339 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12339, 'zhTW', '凱爾的寵物是該在羞辱中學上一課。我們將會擊潰曦刃軍團並且從他們手中奪下日境港。$B$B我們目前的目標達成率為$3238w％。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12340 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12340, 'zhTW', '日境屬於我們了。凱爾的走狗四散奔逃...是時候來終結他們的苦難了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12341 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12341, 'zhTW', '我負責管理支援牛頭大佬的工作人員。$B$B你知道的:打包，開車，還有樂器拆卸，舞臺搭蓋及拆掉，設定煙火，所有這種類的事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12342 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12342, 'zhTW', '這裡的史懷哲是我的老朋友...那，是一件貴重的東西。我是說，友情。我想我會忘掉這種感覺，直到我們再度在撒塔斯城遇見。$B$B這些日子他沒有常常待在提里斯法，所以我想我會使用這裡的傳送之門去傳達我的問候。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12343 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12343, 'zhTW', '呣嚕咕嚕咕嚕咕嚕咕?咕嚕哺呣嚕，哺嚕呣咕嚕，咕嚕呣嚕哺呣咕嚕。$B$B咕嚕咕嚕咕嚕哺嚕，呣嚕咕嚕!!!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12344 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12344, 'zhTW', '<阿魯咕嚕咕爾因為聽的懂你所說的話而驚訝得看著你。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12347 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12347, 'zhTW', '最好的防禦就是有效的攻擊；任何人都會這麼告訴你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12348 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12348, 'zhTW', '如果你沒辦法活得夠久來配戴武器，那麼再強大的武器也不夠好，$c。', '如果你沒辦法活得夠久來配戴武器，那麼再強大的武器也不夠好，$c。', '如果你沒法保證自己能活下來，那麼再強的武器對你來說也毫無意義，$c。', '如果你沒辦法活得夠久來配戴武器，那麼再強大的武器也不夠好，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12349 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12349, 'zhTW', '嘎嗚嚕咕咕嚕!哺嚕咕嚕 - 哺嚕咕嚕，咕嚕咕嚕!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12350 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12350, 'zhTW', '$r，你學會了和我們溝通的技巧，但是我一點也不驚訝。$B$B有很多冬鰭魚人的叛徒在水的對岸，一定要殺掉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12352 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12352, 'zhTW', '我沒瞎，你知道嗎。這附近發生什麼我看得一清二楚!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12354 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12354, 'zhTW', '啊咕嚕咕嚕咕嚕咕嚕!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12357 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12357, 'zhTW', '我最近來這觀察冬鰭魚人。我打扮的跟他們一樣，和他們保持距離，記載著他們的日常生活。$B$B可是，在我到這不久以後，一切都變了。$B$B凜懼島發生的地震造成了坍方，附近的洞窟因此暴露出來。從裡面跑出一隻龍蝦人，偷走了冬鰭魚人的蝌蚪。然後，魚人進去洞窟解救他們的小寶寶，他們再度現身時，全身發著光，受到了龍蝦人的影響。$B$B如今，未受影響的魚人撤退到這裡，我則心不甘情不願的成了他們的領導者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12360 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12360, 'zhTW', '哺勒咕 啊嗚嚕咕嚕 呣嚕?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12361 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12361, 'zhTW', '我的兄弟姊妹都發瘋了!你覺得能幫我逃離這裡嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12362 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12362, 'zhTW', '咕嚕咕，哺呣嚕咕嚕，咕嚕咕咕嚕!', NULL, '咕嚕咕，哺呣嚕咕嚕，咕嚕咕咕嚕!', NULL, '咕嚕咕，哺呣嚕咕嚕，咕嚕咕咕嚕!', NULL, '咕嚕咕，哺呣嚕咕嚕，咕嚕咕咕嚕!', NULL, '哺嚕呣嚕咕嚕，咕嚕咕嚕，咕嚕。', NULL, '啦咕嚕咕嚕嚕咕嚕嚕！！！', NULL, '呣嚕咕嚕咕嚕咕嚕…咕嚕咕嚕?', NULL, '呣嚕咕嚕呣嚕咕嚕，咕嚕咕咕嚕！', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12363 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12363, 'zhTW', '不要跟我聊天 - 我還有活要幹!', NULL, '不要跟我聊天 - 我還有活要幹!', NULL, '不要跟我聊天 - 我還有活要幹!', NULL, '不要跟我聊天 - 我還有活要幹!', NULL, '哺嚕咕嚕咕嚕 姆哺嚕咕嚕…開玩笑的啦，我聽得懂你說什麼。', NULL, '你找出為什麼村子裡的兄弟姊妹都發瘋了嗎?', NULL, '我就知道我們不該進去那座洞窟的。那一點也不自然！', NULL, '那個新國王莫戈莫戈有點可疑，但是我指不出來哪裡怪。', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12364 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12364, 'zhTW', '我是阿推克，卡瑪廓這裡卡魯耶克的酋長。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12370 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12370, 'zhTW', '凱爾薩斯和他的魔化血精靈真該死!我們過去所做的努力已經毀於一旦，若他們認為我們不會還手的話就是蠢蛋。在這之前，莉雅德倫女士已經替我們找到新的能量來源。我們才不會如此容易就被打倒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12371 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12371, 'zhTW', '<龍鷹似乎因為周遭的騷動而感到不安。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12373 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12373, 'zhTW', '夷平奧格瑪不僅是對獸人發動攻擊而已，更是對部落公然挑釁，危害到我們的生存!$B$B巫妖王企圖播下恐懼的種子。$B$B而這些...$B$B<卡爾洛斯指著他四周強化過的圍牆。>$B$B這就是阿薩斯戰役的結果。$B$B部落一無所懼...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12374 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12374, 'zhTW', '你已經接近一座部落營火了!褻瀆這座營火併將它撲滅!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12376 AND `Locale` = 'zhTW';
