INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12381, 'zhTW', '一直以來，恐懼是我們最大的武器。不安與猜忌掌控了戰爭的勝負。那麼，我們該怎麼對抗一個不知恐懼為何物的敵人呢?$B$B<薩魯法爾搖搖頭。>$B$B我們不光只是對抗北裂境的天譴軍，我們還要在他們撕碎我們以前，固守我們的知覺...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12382 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12382, 'zhTW', '我們需要將這個前哨準備好，好推進休拉薩盆地。$B$B別隻是站在那裡，$c。到外面去，用榮耀和濺散的鮮血表現部落!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
