INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12384, 'zhTW', '我必需要把這一團亂清理乾淨，但是我不會抱怨。$B$B如果你還有一絲部落的驕傲的話，幫幫我!', '我必需要把這一團亂清理乾淨，但是我不會抱怨。$B$B如果你還有一絲部落的驕傲的話，幫幫我!', '我必需要把這一團亂清理乾淨，但是我不會抱怨。\n\n如果你還有一絲部落的驕傲的話，幫幫我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
