INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12403, 'zhTW', '眼見我的先祖從他們的墓地中被侵擾，讓我悲痛莫名。$B$B我們一定要擊敗那個被詛咒的靈魂 - 軍隊指揮官鋼顎，他率領著他的商隊愚蠢的透過這片神聖的土地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
