DELETE FROM `npc_text_locale` WHERE `ID` = 12417 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12417, 'zhTW', '我們在偵察西方的時候損失了不少雙足飛龍。天譴軍團對於任何可能是間諜的生物都發出無情的攻擊。$B$B所幸，我想出了一個解決之道，只拿騎乘者的性命冒險。搭渡船透過納森平原一般來講有30%的生還機率，這比我們之前使用雙足飛龍時，可是足足提升了30%呢!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12419 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12419, 'zhTW', '這真是奇恥大辱。我早該跟著先知一起死在瑪格默斯的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
