INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12422, 'zhTW', '卡爾洛斯臺地和帕雷亞兩地被大霧所橫掃，我們是少數幾個瘋到留下來的，老兄!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12423 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12423, 'zhTW', '嘶軸整天就是緊盯著我，然後所有的工具都不在我手邊，這樣是要我怎麼做事嘛?!', '嘶軸整天就是緊盯著我，然後所有的工具都不在我手邊，這樣是要我怎麼做事嘛?!', '嘶軸整天就是緊盯著我，然後所有的工具都不在我手邊，這樣是要我怎麼做事嘛?!', '嘶軸整天就是緊盯著我，然後所有的工具都不在我手邊，這樣是要我怎麼做事嘛?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12424 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12424, 'zhTW', '你在這個海岸所見的一切並非天譴軍幹得好事。事實上，我們相信天譴軍也很怕這股大霧 - 也是為何他們進不來的原因。$B$B懂了嗎，這陣霧是活的，朋友。在那些輕飄飄的霧縷中潛藏著死亡...$B$B要是你踏入它的魔爪，你會消失。這陣霧會殺了你!$B$B我從沒見過有人能從這陣霧中活著回來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12426 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12426, 'zhTW', '到這以後，原本一直困擾我的最黑暗的惡夢，如今成真了，但除此之外沒有別的東西能讓我準備好面對霧中的惡獸。$B$B<穆圖點點頭。>$B$B透過這片大霧，就在離我們不遠的地方，有著一頭名叫科瓦迪爾的嗜血生物，沒有人能從這片霧中返回，同樣的，原本就在臺地上的人，當這片霧升起之後，也鮮少有逃出來的。從此以後，地獄吼便譴責這塊地方。如果要進去，後果只有自己負責了...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12427 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12427, 'zhTW', '我...你是...$B$B<穆圖渾身發抖。>$B$B你是來救我的嗎?', '我...你是...$B$B<穆圖渾身發抖。>$B$B你是來救我的嗎?', '我…你是…\n\n<穆圖渾身發抖。>\n\n你是來救我的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12433 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12433, 'zhTW', '看到你真是太棒了!我太虛弱了，無法破壞這個生鏽的球和鐵鏈。$B$B哎，別隻是站在那啊!快幫我鬆綁!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12435 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12435, 'zhTW', '我現在可是手上的東西應有盡有，$c。$B$B我能幫你什麼忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12440 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12440, 'zhTW', '孩子，說慢點，我對你獨特的腔調很陌生。', '孩子，說慢點，我對你獨特的腔調很陌生。', '孩子，說慢點，我對你獨特的腔調很陌生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
