INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12555, 'zhTW', '為國家捐軀是士兵的天職。但是如果批評這場戰爭愚蠢就是通敵的話，那我就是叛徒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12556 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12556, 'zhTW', '我現在很忙，$r，請不要來煩我。', '我現在很忙，$r，請不要來煩我。', '我現在很忙，$r，請不要來煩我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12566 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12566, 'zhTW', '凡人，專注你的思緒。這與你所見過的戰爭前線不大一樣。$B$B如果你想要幫上點忙，你得完整控制你的身體機能才行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12571 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12571, 'zhTW', '你必須在我們匯入我們的火焰時讓艾胡恩的手下活著。別靠近冰霜領主，直到我們可以消滅他為止。', '你必須在我們匯入我們的火焰時讓艾胡恩的手下活著。別靠近冰霜領主，直到我們可以消滅他為止。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12572 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12572, 'zhTW', '當艾胡恩出現時，我們會準備好了嗎?', '當艾胡恩出現時，我們會準備好了嗎?', '當艾胡恩出現時，我們會準備好了嗎?', '當艾胡恩出現時，我們會準備好了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12575 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12575, 'zhTW', '大地正處於巨大的混亂之中!$B$B黑暗者伴隨著煞婪一族再度前來，龍群則忙於牠們偉大的奧核戰爭，而維酷人再次甦醒。$B$B你的人民搭乘著木船往北出航前去加入戰鬥，而我們卡魯耶克則被困在其中。$B$B而現在，某些極為邪惡的東西發生了，大地因為世界的魔法能量而爆發。我們一定得找到一個安全的地方，讓我們得以存活。$B$B這兩個大使讓我很頭疼...或許你可以幫幫我的人民，$r?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12576 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12576, 'zhTW', '$n，能再一次見到你真的很開心。', '$n，能再一次見到你真的很開心。', '$n，能再一次見到你真的很開心。', '$n，能再一次見到你真的很開心。', NULL, '$n，能再一次見到你真的很開心。', NULL, '$n，能再一次見到你真的很開心。', NULL, '在這樣的時代,親愛的朋友是無價的。.$b$b 非常安全, $n. 安全到你可以想去任何地方....', NULL, '如果你不救我,我現在肯定在監獄都死心了.$b$b我沒有忘記....', NULL, '我們的責任就是在將來，我會找到一個方法來報答你對我的拯救。', NULL, '我的力量回來了，慢慢的....$b$b希望能讓你很快看到屬於我真正的榮耀');
DELETE FROM `npc_text_locale` WHERE `ID` = 12577 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12577, 'zhTW', '唔...$B$B這是哪?', '唔...$B$B這是哪?', '喔....$B$B我在哪裡?', '唔…$B$B這是哪?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12578 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12578, 'zhTW', '科瓦迪爾很殘忍，$N。但是我沒有辦法將神聖的卡斯卡拉棄之不顧。如果我們不放棄靈魂，靈魂也就不會遺棄我們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12579 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12579, 'zhTW', '卡斯卡拉遭受攻擊!在我們有辦法逃跑之前，我們一定要拖住他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12580 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12580, 'zhTW', '該死的巨人!如果他們想要開戰，那就如他們所願!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12582 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12582, 'zhTW', '歡迎，$c。你是來榮耀這座火焰的嗎?$B$B記住:我們的節慶火焰在每個擁有部落營區的土地上燃燒著。如果可以的話，花點時間前去榮耀每一座火焰吧。$B$B聯盟也是一樣，燃燒著屬於他們的火焰。當你遇到聯盟的火焰時，你還是褻瀆一下像這樣沒有意義的努力比較好。', '歡迎，$c。你是來榮耀這座火焰的嗎?$B$B記住:我們的節慶火焰在每個擁有部落營區的土地上燃燒著。如果可以的話，花點時間前去榮耀每一座火焰吧。$B$B聯盟也是一樣，燃燒著屬於他們的火焰。當你遇到聯盟的火焰時，你還是褻瀆一下像這樣沒有意義的努力比較好。', '歡迎，$c。你是來榮耀這座火焰的嗎?\n\n記住:我們的節慶火焰在每個擁有部落營區的土地上燃燒著。如果可以的話，花點時間前去榮耀每一座火焰吧。\n\n聯盟也是一樣，燃燒著屬於他們的火焰。當你遇到聯盟的火焰時，你還是褻瀆一下像這樣沒有意義的努力比較好。', '歡迎，$c。你是來榮耀這座火焰的嗎?$B$B記住:我們的節慶火焰在每個擁有部落營區的土地上燃燒著。如果可以的話，花點時間前去榮耀每一座火焰吧。$B$B聯盟也是一樣，燃燒著屬於他們的火焰。當你遇到聯盟的火焰時，你還是褻瀆一下像這樣沒有意義的努力比較好。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12585 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12585, 'zhTW', '這頭年輕的巨牙海民看起來是戰死的，而不是溺死的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12587 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12587, 'zhTW', '我很高興你來了。現在你瞭解了我們的火焰，還有榮耀火焰的事…還有敵人的火焰，以及熄滅它們的事…你可以回去找他並接受獎勵了。', '我很高興你來了。現在你瞭解了我們的火焰，還有榮耀火焰的事…還有敵人的火焰，以及熄滅它們的事…你可以回去找他並接受獎勵了。', '我很高興你來了。現在你瞭解了我們的火焰，還有榮耀火焰的事…還有敵人的火焰，以及熄滅它們的事…你可以回去找他並接受獎勵了。', '我很高興你來了。現在你瞭解了我們的火焰，還有榮耀火焰的事...還有敵人的火焰，以及熄滅它們的事...你可以回去找他並接受獎勵了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12588 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12588, 'zhTW', 'MISSING TEXT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12590 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12590, 'zhTW', '簡而言之，魔法。$B$B不負責任的凡人們在他們短暫的生命裡毫不考慮自身行動所帶來的永續後果。$B$B秘法能量被過度抽取，逐漸破壞世界的平衡。如果這種情形繼續下去，艾澤拉斯很快的就會滅亡了。$B$B關於這件事，雙方都同意了。但在來得及舉行議會之前，瑪裡苟斯已經開始把他的計畫付諸實行。$B$B我們別無選擇，只有與他正面衝突。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12591 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12591, 'zhTW', '我們進步了，$r，不過速度還是太慢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12592 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12592, 'zhTW', '我們一定要成功!艾澤拉斯的命運危在旦夕...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12593 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12593, 'zhTW', '『織法者』瑪裡苟斯，魔法之王，藍龍軍團的主人。他是藍龍的守護巨龍，艾澤拉斯最古老的生物之一。$B$B傳說他已從持續億萬年的瘋狂中甦醒，但從他最近的行徑看來，我相信他還是瘋的。$B$B他解決我們困境的方法就是將艾澤拉斯之中所有行始魔法的凡人找出來並殺光。$B$B作為生命的守護者，此舉迫使紅龍軍團展開行動。$B$B龍與龍之間現在相互對抗，而我們脆弱世界的命運正危在旦夕。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12596 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12596, 'zhTW', '我很慶幸有你在這裡，$c。太陽之井高地的戰況相當糟。', '我很慶幸有你在這裡，$c。太陽之井高地的戰況相當糟。', '我很慶幸有你在這裡，$c。太陽之井高地的戰況相當糟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12597 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12597, 'zhTW', '賽拉娜上尉吩咐我前來協助你進行在太陽之井高地的工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12598 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12598, 'zhTW', '破碎之日進攻部隊在奎爾達納斯之島的外圍地區推進了一大步。基爾加丹的軍隊被逼退了，在這場混亂中我在太陽之井高地裡領導一小隊偵察軍隊。我的隊伍行進了幻日廣場，遇到了一群日刃血精靈，接著我們與敵人進行戰鬥。那場戰鬥很快的變成了一場災難。', '破碎之日進攻部隊在奎爾達納斯之島的外圍地區推進了一大步。基爾加丹的軍隊被逼退了，在這場混亂中我在太陽之井高地裡領導一小隊偵察軍隊。我的隊伍行進了幻日廣場，遇到了一群日刃血精靈，接著我們與敵人進行戰鬥。那場戰鬥很快的變成了一場災難。', '破碎之日進攻部隊在奎爾達納斯之島的外圍地區推進了一大步。基爾加丹的軍隊被逼退了，在這場混亂中我在太陽之井高地裡領導一小隊偵察軍隊。我的隊伍行進了幻日廣場，遇到了一群日刃血精靈，接著我們與敵人進行戰鬥。那場戰鬥很快的變成了一場災難。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12599 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12599, 'zhTW', '基爾加丹在太陽之井高地的防衛者比我們在島外所面對的更加強大。軍團甚至以魔化能量扭曲了我們的秘法護衛技術，製造出更為邪惡的事物。只要一隻日刃保衛者就殲滅了我的軍隊，所以我下令立時撤退。我希望我的小隊可以整個退出高地，不過敵方卻停止追擊，令我大吃一驚。', '基爾加丹在太陽之井高地的防衛者比我們在島外所面對的更加強大。軍團甚至以魔化能量扭曲了我們的秘法護衛技術，製造出更為邪惡的事物。只要一隻日刃保衛者就殲滅了我的軍隊，所以我下令立時撤退。我希望我的小隊可以整個退出高地，不過敵方卻停止追擊，令我大吃一驚。', '基爾加丹在太陽之井高地的防衛者比我們在島外所面對的更加強大。軍團甚至以魔化能量扭曲了我們的秘法護衛技術，製造出更為邪惡的事物。只要一隻日刃保衛者就殲滅了我的軍隊，所以我下令立時撤退。我希望我的小隊可以整個退出高地，不過敵方卻停止追擊，令我大吃一驚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12600 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12600, 'zhTW', '我不知道，不過我很慶幸他們這樣做。此舉讓隱士艾邦頓得以在我的指令下拯救許多人們。我已經派出了幾位秘探，他們回報了幾件很有趣的事。幾乎所有的日刃保衛者的能源都變低了!基爾加丹的軍隊好像在儲存他們的能量，並似乎對於只派一隻保衛者就控制我們這件事感到很滿意。如果你和你的同伴想要攻進去，請允許我提出一則攻擊計畫的建議。', '我不知道，不過我很慶幸他們這樣做。此舉讓隱士艾邦頓得以在我的指令下拯救許多人們。我已經派出了幾位秘探，他們回報了幾件很有趣的事。幾乎所有的日刃保衛者的能源都變低了!基爾加丹的軍隊好像在儲存他們的能量，並似乎對於只派一隻保衛者就控制我們這件事感到很滿意。如果你和你的同伴想要攻進去，請允許我提出一則攻擊計畫的建議。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12601 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12601, 'zhTW', '利用他們撤退的日刃保衛者。要是有日刃斥候鎖定你，我相信那位精靈將會試著重新啟動一隻附近的日刃保衛者。快速殺了他，別讓他那麼做。殺了血精靈後，只要你不啟動保衛者附近的感應器，你應該可以安全的透過他們。這麼做將可節省你的時間和資源。', '利用他們撤退的日刃保衛者。要是有日刃斥候鎖定你，我相信那位精靈將會試著重新啟動一隻附近的日刃保衛者。快速殺了他，別讓他那麼做。殺了血精靈後，只要你不啟動保衛者附近的感應器，你應該可以安全的透過他們。這麼做將可節省你的時間和資源。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12604 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12604, 'zhTW', '所有抵擋你進入太陽之井的屏障皆已摧毀。前進太陽之井並阻止基爾加丹進入這個世界!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12606 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12606, 'zhTW', '我和一位朋友前來解救一位年輕的人類女性逃離軍團領主基爾加丹與其邪惡手下的掌控。$B$B我們發現凱爾薩斯正試圖將基爾加丹從太陽之井的深處召喚出來。$B$B為了整個世界的安危 - 這件事絕不能發生!我保證會親自阻止這件事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12607 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12607, 'zhTW', '瑪卓苟莎在此趟旅行中和我同行，不過我們在太陽之井中分散了。$B$B希望命運眷顧，她平安無恙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12608 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12608, 'zhTW', '安薇娜不只是凡人，$r。那些瞭解她真實本質的人都想要擁有她。$B$B她曾經救過我，現在我想要報答她的恩惠。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12609 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12609, 'zhTW', '喜歡這個節慶嗎，$c?$B$B雖說火焰持護者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$B$B你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著...', '喜歡這個節慶嗎，$c?$B$B雖說火焰持護者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$B$B你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著...', '喜歡這個節慶嗎，$c?\n\n雖說火焰守護者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?\n\n你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著…', '喜歡這個節慶嗎，$c?$B$B雖說火焰守護者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$B$B你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12610 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12610, 'zhTW', '歡迎來到我們的營地，$c。請別覺得拘束，想待就待下來吧。', '歡迎來到我們的營地，$c。請別覺得拘束，想待就待下來吧。', '歡迎來到我們的營地，$c。請別覺得拘束，想待就待下來吧。', '歡迎來到我們的營地，$c。請別覺得拘束，想待就待下來吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
