INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12611, 'zhTW', '這裡對我們來說已經沒有意義了。', '這裡對我們來說已經沒有意義了。', '這裡對我們來說已經沒有意義了。', '這裡對我們來說已經沒有意義了。', '這裡對我們來說已經沒有意義了。', '這裡對我們來說已經沒有意義了。', '這裡對我們來說已經沒有意義了。', '這裡對我們來說已經沒有意義了。', '天譴軍團是一種不知恐懼為何的機器，用來終結這世界上所有的生命體。', '天譴軍團是一種不知恐懼為何的機器，用來終結這世界上所有的生命體。', '被他們稱作地獄吼的那個人也許是我們唯一的希望。', '被他們稱作地獄吼的那個人也許是我們唯一的希望。', '現在只有部落可以拯救我們了。', '現在只有部落可以拯救我們了。', NULL, NULL);
