INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12617, 'zhTW', '<霸德一動也不動，假裝沒聽到你說的話。靠近一看，你看見他的面具底下滴下幾滴口水。>', NULL, '<霸德一動也不動，假裝沒聽到你說的話。靠近一看，你看見他的面具底下滴下幾滴口水。>', NULL, '<霸德一動也不動，假裝沒聽到你說的話。靠近一看，你看見他的面具底下滴下幾滴口水。>', NULL, '<霸德一動也不動，假裝沒聽到你說的話。靠近一看，你看見他的面具底下滴下幾滴口水。>', NULL, '巨魔最強，老兄！', NULL, '你有什麼毛病啊，老兄?你沒見過巨魔?', NULL, NULL, NULL, NULL, NULL);
