INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12619, 'zhTW', '為了替我的子民復仇，為了要將吞噬我們家園的荒疫驅逐出去 - 我會接受血誓。我誓言我將全心全意的為部落奉獻。', '為了替我的子民復仇，為了要將吞噬我們家園的荒疫驅逐出去 - 我會接受血誓。我誓言我將全心全意的為部落奉獻。', '為了替我的子民復仇，為了要將吞噬我們家園的荒疫驅逐出去 - 我會接受血誓。我誓言我將全心全意的為部落奉獻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12620 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12620, 'zhTW', '(獸人語)部落的榮耀!不勝即亡 - 就是這幾個字讓我跟部落連結在一起!對任何一個部落的戰士而言，這幾個字是最神聖且基本的真理。$B$B我將我的血肉無條件獻給大酋長，我將完成所有大酋長的意志，我就是大酋長命令下的武器。$B$B從此刻起我活著，直到世界末日英勇赴死 - 為了部落!', '(獸人語)部落的榮耀!不勝即亡 - 就是這幾個字讓我跟部落連結在一起!對任何一個部落的戰士而言，這幾個字是最神聖且基本的真理。$B$B我將我的血肉無條件獻給大酋長，我將完成所有大酋長的意志，我就是大酋長命令下的武器。$B$B從此刻起我活著，直到世界末日英勇赴死 - 為了部落!', '(獸人語)部落的榮耀!不勝即亡 - 就是這幾個字讓我跟部落連結在一起!對任何一個部落的戰士而言，這幾個字是最神聖且基本的真理。\n\n我將我的血肉無條件獻給大酋長，我將完成所有大酋長的意志，我就是大酋長命令下的武器。\n\n從此刻起我活著，直到世界末日英勇赴死 - 為了部落!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12622 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12622, 'zhTW', '我，媽媽。還有這些巨魔兄弟們!', NULL, '是時候弄一些巨魔標籤了，媽媽！', NULL, '巨魔兄弟們今天玩得很開心！', NULL, '哈哈哈！去找些樂子吧！', NULL, '你確定我們走的路沒錯？', NULL, '<嗅，嗅> 我能聞到他們。', NULL, 'Nuttin\' 說 luvin\' 像是在一個小杯子敲打著 。', NULL, 'Nuttin\' 說 luvin\' 像是在一個小杯子敲打著 。', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12623 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12623, 'zhTW', '太陽之井的三道門全都被終結了，$N。$B$B你必須得率領你的隊伍在一切都太遲以前阻止基爾加丹進入艾澤拉斯!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12626 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12626, 'zhTW', '裂鞭族將永遠無法重返過去的榮耀，但是這些駕船的惡棍將為了他們的行為付出代價 - 我發誓!', '裂鞭族將永遠無法重返過去的榮耀，但是這些駕船的惡棍將為了他們的行為付出代價 - 我發誓!', '裂鞭族將永遠無法重返過去的榮耀，但是這些駕船的惡棍將為了他們的行為付出代價 - 我發誓!', '裂鞭族將永遠無法重返過去的榮耀，但是這些駕船的惡棍將為了他們的行為付出代價 - 我發誓!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12627 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12627, 'zhTW', '保護這些坦卡族並盡我們所能讓他們過得舒適，這是我們的責任。', '保護這些坦卡族並盡我們所能讓他們過得舒適，這是我們的責任。', '保護這些坦卡族並盡我們所能讓他們過得舒適，這是我們的責任。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12628 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12628, 'zhTW', NULL, '這些嬰兒將活下去，伴著愛和親情成長為部落強壯的一員，他們所經歷的那些可怕回憶會隨著時間漸漸淡去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
