INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12739, 'zhTW', '翻越了海加爾山的山谷與高峰，越過了希利蘇斯的流沙，對抗燃燒軍團的驚懼大軍 - 我們從不退縮。我們是沒有名字，沒有臉孔的聯盟子民。在聖光與聯盟的力量之下，我們永遠揮出第一擊，而我們的敵人也永遠看到我們的最後一擊。$B$B我們就是第七軍團。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
