INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12773, 'zhTW', '這些山丘的自然之美隱藏了巨大的黑暗力量。小心行走，朋友。', '這些山丘的自然之美隱藏了巨大的黑暗力量。小心行走，朋友。', '這些山丘的自然之美隱藏了巨大的黑暗力量。小心行走，朋友。', '這些美麗的自然風光的背後隱藏著巨大的邪惡，小心行事，我的朋友。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
