INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12781, 'zhTW', '謝謝你的幫助，$n。這些霜莓真可說是你的辛勞的成果。', '謝謝你的幫助，$n。這些霜莓真可說是你的辛勞的成果。', '謝謝你的幫助，$n。這些霜莓真可說是你的辛勞的成果。', '謝謝你的幫助，$n。這些霜莓真可說是你的辛勞的成果。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12785 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12785, 'zhTW', '當我聽說了我北方親戚的事之後，我來這裡打聽更多訊息。我只看到違揹我們天性打仗的部族。$B$B我已經失去所有希望了，$r。甚至連偉大的厄索克都被這受詛咒的大地給汙染了。$B$B我已經失去了所有希望。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12787 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12787, 'zhTW', '是的…我感覺到沃達希爾的魔法了…沒有任何的汙染。$B$B拜託!請務必讓我幫助你。命運把我帶來這裡，也許我能夠幫上忙!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12789 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12789, 'zhTW', '我們永遠不會忘記你的勇氣，$N。溫特加德永遠歡迎你。$B$B你想把這個旅館當作你的家嗎?', '我們永遠不會忘記你的勇氣，$N。溫特加德永遠歡迎你。$B$B你想把這個旅館當作你的家嗎?', '我們永遠不會忘記你的勇氣，$N。溫特加德永遠歡迎你。\n\n你想把這個旅館當作你的家嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12790 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12790, 'zhTW', '賽巴魯思打從心底感謝你，英雄。要是沒有你，賽巴魯思可能會死掉，或者更慘一點，賽巴魯思可能會變成他們之中的一員…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12793 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12793, 'zhTW', '我曾在灰白之丘遊蕩過，偉大的厄索克之子，統治了那個地方。$B$B但是如今…如今我卻註定在這個洞穴裡面度過餘生了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12794 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12794, 'zhTW', '你不明白。如果我想的話我可以殺出這個洞窟。$B$B是我的父親，厄索克。他從死亡中回來了…但是不再是以前的他。$B$B他在幾千年前的先祖之戰中犧牲了性命。幾百年來，信仰他的熊怪們試圖找出復活他的方法。$B$B最後他們決定試圖重植世界樹，沃達希爾，並且使用世界樹的魔法將我的父親帶回這世界。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12795 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12795, 'zhTW', '壓低你的音量，$c。我披著偽裝替毒怨之地進行諜報工作。', '壓低你的音量，$c。我披著偽裝替毒怨之地進行諜報工作。', '壓低你的音量，$c。我披著偽裝替毒怨之地進行諜報工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12796 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12796, 'zhTW', '他們種下的樹苗結出了果實。起初似乎很順利，厄索克回來了，有一陣子我心中充滿了喜悅。$B$B但當他復活之後，很顯然跟以前不同了。熊怪也是。$B$B不論是什麼樣的邪惡導致上古德魯伊摧毀了沃達希爾，它顯然寄居在新的樹中，並且把他們全部變成了嗜血的怪獸。$B$B現在在灰白之丘走動的怪物並不是我的父親，我們得讓他安息。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12797 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12797, 'zhTW', '我是寇荻安，厄索克之女。我守護這個一度神聖的祭壇。$B$B我已經很久沒有看過陌生人來此了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12798 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12798, 'zhTW', '一個名叫圖爾·怒掌的熊怪，不是我們之一。$B$B他來自南邊，屬於木喉部族。$B$B他想要見厄索克。他似乎覺得沃達希爾的腐化可以被淨化，並且用來拯救我父親。$B$B用這樣的希望來戲弄我是很愚蠢的，當你見到他，如同我一樣，被黑暗所折磨，你會同意我說的話的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12804 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12804, 'zhTW', '你覺得你能把我救出去嗎，$c?', '你覺得你能把我救出去嗎，$c?', '你覺得你能把我救出去嗎，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12805 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12805, 'zhTW', '噢，真好，你是來救我的。馬上放我出去!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12806 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12806, 'zhTW', '嘿，$g老兄:女士;我在這附近見過你。$B$B不介意把我救出去吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12808 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12808, 'zhTW', '我搞不清楚怎麼回事。我才剛到毒怨之地，然後當我一覺醒來我就在這牢籠裡了!$B$B你是來救我的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12810 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12810, 'zhTW', '你好，$c。$B$B我能為你效勞嗎?', '你好，$c。$B$B我能為你效勞嗎?', '很高興見到你.我能幫你什麼嗎?', '你好，$c。$B$B我能為你效勞嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12811 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12811, 'zhTW', '族長特沃德·艾利克森易怒的元龍被拴在這裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12812 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12812, 'zhTW', '嗯?你想說什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12819 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12819, 'zhTW', '每隔兩年競賽之靈都會變得特別激動熱情…而現在正是這個時候!我們穿著這身外袍前往戰場榮耀它們，打敗我們的敵人然後贏得它們的眷顧。', '每隔兩年競賽之靈都會變得特別激動熱情…而現在正是這個時候!我們穿著這身外袍前往戰場榮耀它們，打敗我們的敵人然後贏得它們的眷顧。', '每隔兩年競賽之靈都會變得特別激動熱情…而現在正是這個時候!我們穿著這身外袍前往戰場榮耀它們，打敗我們的敵人然後贏得它們的眷顧。', '每隔兩年競賽之靈都會變得特別激動熱情…而現在正是這個時候!我們穿著這身外袍前往戰場榮耀它們，打敗我們的敵人然後贏得它們的眷顧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12820 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12820, 'zhTW', '你必須在戰場上面對我們的對手。不論是贏或輸，如果你堅持到戰鬥的最後，你就會收到郵寄給你的競賽者外袍。', '你必須在戰場上面對我們的對手。不論是贏或輸，如果你堅持到戰鬥的最後，你就會收到郵寄給你的競賽者外袍。', '你必須在戰場上面對我們的對手。不論是贏或輸，如果你堅持到戰鬥的最後，你就會收到郵寄給你的競賽者外袍。', '你必須在戰場上面對我們的對手。不論是贏或輸，如果你堅持到戰鬥的最後，你就會收到郵寄給你的競賽者外袍。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12821 AND `Locale` = 'zhTW';
