INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12822, 'zhTW', '你知道競賽之靈，對吧?$B$B每隔兩年，它們就會靠近凡人的世界。在這段期間，聯盟與部落的成員都會穿著競賽者外袍進入戰場來榮耀它們，試圖擊敗敵人並且贏得眷顧。$B$B我倒是從這類的動盪時期累積了不少紀念品。你要是能學會一些適當的措辭，我倒可以考慮割捨一些……', '你知道競賽之靈，對吧?$B$B每隔兩年，它們就會靠近凡人的世界。在這段期間，聯盟與部落的成員都會穿著競賽者外袍進入戰場來榮耀它們，試圖擊敗敵人並且贏得眷顧。$B$B我倒是從這類的動盪時期累積了不少紀念品。你要是能學會一些適當的措辭，我倒可以考慮割捨一些……', '你知道競賽之靈，對吧?\n\n每隔兩年，它們就會靠近凡人的世界。在這段期間，聯盟與部落的成員都會穿著競賽者外袍進入戰場來榮耀它們，試圖擊敗敵人並且贏得眷顧。\n\n我倒是從這類的動盪時期累積了不少紀念品。你要是能學會一些適當的措辭，我倒可以考慮割捨一些……', '你知道競賽之靈，對吧?$B$B每隔兩年，它們就會靠近凡人的世界。在這段期間，聯盟與部落的成員都會穿著競賽者外袍進入戰場來榮耀它們，試圖擊敗敵人並且贏得眷顧。$B$B我倒是從這類的動盪時期累積了不少紀念品。你要是能學會一些適當的措辭，我倒可以考慮割捨一些……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
