INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12823, 'zhTW', '我們正在這嚴寒的荒原上學習死亡的代價，$N。巫妖王的力量擴充套件到北裂境的每一寸土地，甚至滲透進土地裡!他利用我們死去的將士來對付我們。$B$B獅鷲騎士從空中擲下復仇的風暴戰槌，而活死人在地面上襲擊我們。', '我們正在這嚴寒的荒原上學習死亡的代價，$N。巫妖王的力量擴充套件到北裂境的每一寸土地，甚至滲透進土地裡!他利用我們死去的將士來對付我們。$B$B獅鷲騎士從空中擲下復仇的風暴戰槌，而活死人在地面上襲擊我們。', '我們正在這嚴寒的荒原上學習死亡的代價，$N。巫妖王的力量擴充套件到北裂境的每一寸土地，甚至滲透進土地裡!他利用我們死去的將士來對付我們。\n\n獅鷲騎士從空中擲下復仇的風暴戰槌，而活死人在地面上襲擊我們。', '我們正在這嚴寒的荒原上學習死亡的代價，$N。巫妖王的力量擴充套件到北裂境的每一寸土地，甚至滲透進土地裡!他利用我們死去的將士來對付我們。$B$B獅鷲騎士從空中擲下復仇的風暴戰槌，而活死人在地面上襲擊我們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
