INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12859, 'zhTW', '眼睜睜的看著這些野蠻的怪物焚燒掉我們的船，我們的心也隨著沉入了海底。我從未感到如此無助…', NULL, '眼睜睜的看著這些野蠻的怪物焚燒掉我們的船，我們的心也隨著沉入了海底。我從未感到如此無助…', NULL, '眼睜睜的看著這些野蠻的怪物焚燒掉我們的船，我們的心也隨著沉入了海底。我從未感到如此無助…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
