INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12860, 'zhTW', '<遺民步卒搖搖頭。>$B$B我們不會一直存在，朋友。如果阿薩斯王子沒有回來，我們很快就會消失了。', NULL, '<遺民步卒搖搖頭。>$B$B我們不會一直存在，朋友。如果阿薩斯王子沒有回來，我們很快就會消失了。', NULL, '<遺民步卒搖搖頭。>$B$B我們不會一直存在，朋友。如果阿薩斯王子沒有回來，我們很快就會消失了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
