INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12868, 'zhTW', '嗯，在所有的戰鬥在此爆發之前，我們正在修理它們好收集當地的樹木。$B$B後來，它們不得不用來對抗部落。居然成了很優秀的戰鬥機器。如果你要是有把鑰匙的話，不使用它的人是傻瓜!', '嗯，在所有的戰鬥在此爆發之前，我們正在修理它們好收集當地的樹木。$b$b後來，它們不得不用來對抗部落。居然成了很優秀的戰鬥機器。如果你要是有把鑰匙的話，不使用它的人是傻瓜!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
