INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12887, 'zhTW', '龍後雅立史卓莎任命我負責龍眠神殿的防禦工事。$B$B如你所知，瑪裡苟斯透過他的部隊摧毀了附近的一個地脈錨點。藍龍軍團將那些能量導向蒼藍龍殿。$B$B藍龍透過那些能量強化他們自己，能量強大到讓他們膽敢攻擊神殿本體!他們已經佔了上風。$B$B你願意協助我們嗎，$r?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12895 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12895, 'zhTW', '喂，$c，你看到了嗎?就在那邊，殘留在水面上...$B$B你也看到了，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12896 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12896, 'zhTW', '你說什麼?$B$B嗯，我把它們當成是未確認的漂浮障礙物。在我的老家，大部分的人否認它們的存在。$B$B但我知道得更多!我甚至看過它們四處跑!我近幾年都花在建造這臺機械，可以鎖定、追蹤與記錄，如果需要的話，它還可以消滅它們!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12897 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12897, 'zhTW', '別被騙了，$r。它們非常難以捉摸。他們一下子在這兒，下一會兒就不見了 - 簡直難以理解!$B$B這秘密只跟你說，我實際上曾經抓到過一隻!很可惜，在我能測量它以前就不見了!憑空消失...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12898 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12898, 'zhTW', '眾說紛紜...$B$B有人說它們只是在觀察，有人認為它們改變了海洋生態，還有人覺得它們是來征服艾澤拉斯的!$B$B只要我拿一發火箭推進彈頭打一隻下來，我就能知道答案了。這你可以相信!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12899 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12899, 'zhTW', '歡迎，$r。$B$B我一直在等著你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12900 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12900, 'zhTW', '很好，我們走!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12904 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12904, 'zhTW', '北裂境群山中的獅鷲獸，是牠們種族中最堅毅強韌的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12905 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12905, 'zhTW', '獅鷲騎士站在我們10步之外，朋友。他們會送你前往托爾森崗哨。去吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12906 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12906, 'zhTW', '別以為你過去的成就頭銜能給你什麼好處，$N。他們不能。$B$B如果你想要我的尊敬，你就得自己來贏得它。這也意味著無條件地服從我的命令，並且完成。', '別以為你過去的成就頭銜能給你什麼好處，$N。他們不能。$B$B如果你想要我的尊敬，你就得自己來贏得它。這也意味著無條件地服從我的命令，並且完成。', '別以為你過去的成就頭銜能給你什麼好處，$N。他們不能。\n\n如果你想要我的尊敬，你就得自己來贏得它。這也意味著無條件地服從我的命令，並且完成。', '千萬別以為你過去的成就能讓你有權利做任何事，$N，它們不能。$B$B如果你想贏得我的尊敬，你就得付諸行動！意思就是按照我的要求毫無例外地解決問題，而不是問這問那。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12909 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12909, 'zhTW', '嗨。侍從沃特和我負責在這裡照料老馬布蘭契以及其他坐騎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12912 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12912, 'zhTW', '歡迎來到歐尼克瓦營地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12913 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12913, 'zhTW', 'S.T.O.U.T.不只是丟擲啤酒杯的目標，它還是個貴重的訓練資產。如果你能擊中S.T.O.U.T.，你就能擊中所有的東西!$B$B只要別丟我就好。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12915 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12915, 'zhTW', '貝加瑞斯塔茲說的是實話;戰況的確很險峻。$B$B我可以賦予你呼喚一頭綠龍軍團飛龍的力量。如果你傾向獲取紅龍軍團的力量，向貝加瑞斯塔茲交談，如果你屬意青銅龍的力量，向伊特諾斯交談。', '貝加瑞斯塔茲說的是實話;戰況的確很險峻。$B$B我可以賦予你呼喚一頭綠龍軍團飛龍的力量。如果你傾向獲取紅龍軍團的力量，向貝加瑞斯塔茲交談，如果你屬意青銅龍的力量，向伊特諾斯交談。', '貝加瑞斯塔茲說的是實話;戰況的確很險峻。\n\n我可以賦予你呼喚一頭綠龍軍團飛龍的力量。如果你傾向獲取紅龍軍團的力量，向貝加瑞斯塔茲交談，如果你屬意青銅龍的力量，向伊特諾斯交談。', '貝加瑞斯塔茲說的是實話;戰況的確很險峻。$B$B我可以賦予你呼喚一頭綠龍軍團飛龍的力量。如果你傾向獲取紅龍軍團的力量，向貝加瑞斯塔茲交談，如果你屬意青銅龍的力量，向伊特諾斯交談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12916 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12916, 'zhTW', '瓦羅斯·雲行者與他的環之守護者保衛第二道環。你的飛龍大軍雖然比環之守護者強上許多，但是瓦羅斯·雲行者躲在無法穿越的護盾後面，這護盾是由奧核之眼本身的能量所製造的，由十具離心傀儡在環以及平臺的上方提供護盾的能量。摧毀它們，瓦羅斯才會有弱點。$B$B我可以賦予你呼喚一頭紅龍軍團飛龍的力量。如果你傾向獲取青銅龍軍團的力量，向伊特諾斯交談，如果你屬意綠龍的力量，向薇爾迪莎交談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12917 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12917, 'zhTW', '貝加瑞斯塔茲說的是實話;時間緊迫!$B$B我可以賦予你呼喚一頭青銅龍軍團飛龍的力量。如果你傾向獲取紅龍軍團的力量，向貝加瑞斯塔茲交談，如果你屬意綠龍的力量，向薇爾迪莎交談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12926 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12926, 'zhTW', '我的兄弟當中大部分的人對於部落的「野蠻」方式很引以為傲，而我曾經也是他們其中的一員。當我第一次指揮這個有點潮溼且...芳香的地方時，我詛咒我的運氣。$B$B然而，在我進行研究的這段期間，我漸漸喜歡上我身處的環境。這地方很迷人，你不覺得嗎?$B$B啊，當然，還有我的研究，可以讓其他的法師使用法術回到這裡。我教你好嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12927 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12927, 'zhTW', '我的兄弟當中大部分的人對於部落的「野蠻」方式很引以為傲，而我曾經也是他們其中的一員。當我第一次指揮這個有點潮溼且…芳香的地方時，我詛咒我的運氣。$B$B然而，在我進行研究的這段期間，我漸漸喜歡上我身處的環境。這地方很迷人，你不覺得嗎?$B$B……當然，你不會對我的研究有興趣，你本身並不是位法師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12929 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12929, 'zhTW', '嗯?喔。要是我看起來不太專心的話，請見諒;我正擔心著北方城堡的人。我應該要派遣我的學生前往援助他們。現在，我要怎麼幫助你呢?', '嗯?喔。要是我看起來不太專心的話，請見諒;我正擔心著北方城堡的人。我應該要派遣我的學生前往援助他們。現在，我要怎麼幫助你呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12930 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12930, 'zhTW', '嗯?喔。要是我看起來不太專心的話，請見諒;我正擔心著北方城堡的人。我應該要派遣我的學生前往援助他們…', '嗯?喔。要是我看起來不太專心的話，請見諒;我正擔心著北方城堡的人。我應該要派遣我的學生前往援助他們…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12932 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12932, 'zhTW', '我的知識只適用於法師。我沒辦法幫到你的忙，$c。', '我的知識只適用於法師。我沒辦法幫到你的忙，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12933 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12933, 'zhTW', '(薩拉斯語)很高興見到你。如果你想要學習如何召喚一道通往塞拉摩的傳送門，我可以教你。', '(薩拉斯語)很高興見到你。如果你想要學習如何召喚一道通往塞拉摩的傳送門，我可以教你。', '(薩拉斯語)很高興見到你。如果你想要學習如何召喚一道通往塞拉摩的傳送門，我可以教你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12934 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12934, 'zhTW', '啤酒節從第一年以來已經做了不少革新。我們現在是用啤酒節獎品章代替獎品卷。如果你還有舊的獎品卷，我可以幫你兌換成獎品章。', '啤酒節從第一年以來已經做了不少革新。我們現在是用啤酒節獎品章代替獎品卷。如果你還有舊的獎品卷，我可以幫你兌換成獎品章。', '啤酒節從第一年以來已經做了不少革新。我們現在是用啤酒節獎品章代替獎品卷。如果你還有舊的獎品卷，我可以幫你兌換成獎品章。', '啤酒節從第一年以來已經做了不少革新。我們現在是用啤酒節獎品章代替獎品卷。如果你還有舊的獎品卷，我可以幫你兌換成獎品章。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12937 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12937, 'zhTW', '搭個便車嗎，$r?$B$B還是說，有其他事情在困擾你?', '搭個便車嗎，$r?$B$B還是說，有其他事情在困擾你?', '搭個便車嗎，$r?\n\n還是說，有其他事情在困擾你?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
