INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12938, 'zhTW', '聽好嘿，你如果要尋找答案的話，沒有什麼比爆破更有效了 - 爆炸越大越好!$B$B但是那大概就是我們最大的問題了，$r。$B$B我的彈頭是機密材料，而我做出來作為彈頭燃料的「元素115」更是機密中的機密!$B$B事實上，你最好回去過你的日常生活，假裝我們從來沒見過比較好。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12939 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12939, 'zhTW', '冒險者，歡迎你。你的光臨真是太湊巧了。', '冒險者，歡迎你。你的光臨真是太湊巧了。', '冒險者，歡迎你。你的光臨真是太湊巧了。', '冒險者，歡迎你。你的光臨真是太湊巧了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
