INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12942, 'zhTW', '黑龍的外表令你緊張嗎?$B$B很好。就是要這樣。這些龍類也感到很緊張。雖然牠們堅守他們先祖的美德 - 不敢在這裡攻擊我。$B$B一群傻蛋。', '黑龍的外表令你緊張嗎?$B$B很好。就是要這樣。這些龍類也感到很緊張。雖然牠們堅守他們先祖的美德 - 不敢在這裡攻擊我。$B$B一群傻蛋。', '黑龍的外表令你緊張嗎?\n\n很好。就是要這樣。這些龍類也感到很緊張。雖然牠們堅守他們先祖的美德 - 不敢在這裡攻擊我。\n\n一群傻蛋。', '黑龍的出場是不是讓你感到緊張了？$B$B很好，是這樣的，這些龍也感到緊張了，它們保留著它們遠古的德行，所以它們在這兒不敢攻擊我。$B$B真是愚蠢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
