INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12944, 'zhTW', '起先我們修復它們來收採這裡的森林，不過自從聯盟抵達和戰鬥爆發後，我們就把它們用來做為戰爭機器。$B$B相信我，$c。如果你有鑰匙，你一定是瘋了才不去使用它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
