INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12949, 'zhTW', '恆龍軍團正企圖修改阿薩斯·米奈希爾王子的命運。你所知道的他現在是巫妖王，但是在這裡的當下，他還是一個想要為他的王國盡力的羅德隆王子。阿薩斯今日將會做出影響命運的決定，導致時間線中發生某種我們時間看守者稱之為『反曲點』的事情。', '恆龍軍團正企圖修改阿薩斯·米奈希爾王子的命運。你所知道的他現在是巫妖王，但是在這裡的當下，他還是一個想要為他的王國盡力的羅德隆王子。阿薩斯今日將會做出影響命運的決定，導致時間線中發生某種我們時間看守者稱之為『反曲點』的事情。', '恆龍軍團正企圖修改阿薩斯·米奈希爾王子的命運。你所知道的他現在是巫妖王，但是在這裡的當下，他還是一個想要為他的王國盡力的羅德隆王子。阿薩斯今日將會做出影響命運的決定，導致時間線中發生某種我們時間看守者稱之為『反曲點』的事情。', '恆龍軍團正企圖修改阿薩斯·米奈希爾王子的命運。你所知道的他現在是巫妖王，但是在這裡的當下，他還是一個想要為他的王國盡力的羅德隆王子。阿薩斯今日將會做出影響命運的決定，導致時間線中發生某種我們時間看守者稱之為‘反曲點’的事情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
