INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12950, 'zhTW', '阿薩斯下令肅清斯坦索姆，殺光裡頭的所有人。他發現了天譴軍團使用邪惡的瘟疫及不會致人死地的疾病感染這個城市的證據。那些死於這場瘟疫的人復活成為無腦的殭屍，更近一步成為天譴軍團戰爭機器的燃料。', '阿薩斯下令肅清斯坦索姆，殺光裡頭的所有人。他發現了天譴軍團使用邪惡的瘟疫及不會致人死地的疾病感染這個城市的證據。那些死於這場瘟疫的人復活成為無腦的殭屍，更近一步成為天譴軍團戰爭機器的燃料。', '阿薩斯下令肅清斯坦索姆，殺光裡頭的所有人。他發現了天譴軍團使用邪惡的瘟疫及不會致人死地的疾病感染這個城市的證據。那些死於這場瘟疫的人復活成為無腦的殭屍，更近一步成為天譴軍團戰爭機器的燃料。', '阿薩斯下令肅清斯坦索姆，殺光裡頭的所有人。他發現了天譴軍團使用邪惡的瘟疫及不會致人死地的疾病感染這個城市的證據。那些死於這場瘟疫的人復活成為無腦的殭屍，更近一步成為天譴軍團戰爭機器的燃料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
