INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12953, 'zhTW', '我不覺得我們有本錢能錯失和紅龍軍團交好的機會，只要還有戰事，有他們作為聯軍的價值難以估計。', '我不覺得我們有本錢能錯失和紅龍軍團交好的機會，只要還有戰事，有他們作為聯軍的價值難以估計。', '我不覺得我們有本錢能錯失和紅龍軍團交好的機會，只要還有戰事，有他們作為聯軍的價值難以估計。', '我不覺得我們有本錢能錯失和紅龍軍團交好的機會，只要還有戰事，有他們作為聯軍的價值難以估計。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
