INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12954, 'zhTW', '多年以前，術士耐克魯斯·碎顱濫用強大的神器奴役雅立史卓莎，以及大多數的紅龍軍團。祖魯希德和耐克魯斯雖死，但我們欠紅龍的仍難以償還。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
