INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12963, 'zhTW', '親愛的，這雙鞋子真是棒到可以為他付出生命!我說的就是字面上的意思，你是打死誰把鞋子搶過來的?', '親愛的，這雙鞋子真是棒到可以為他付出生命!我說的就是字面上的意思，你是打死誰把鞋子搶過來的?', '親愛的，這雙鞋子真是棒到可以為他付出生命!我說的就是字面上的意思，你是打死誰把鞋子搶過來的?', '親愛的，這雙鞋子真是棒到可以為他付出生命!我說的就是字面上的意思，你是打死誰把鞋子搶過來的?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
