INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12966, 'zhTW', '歡迎來到花崗岩之泉，朋友。$B$B如果你活逮任何一隻寒冰食人妖，一定要讓我知道，我會給他們出個好價錢的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12968 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12968, 'zhTW', '嘿，我看到你手上的啤酒節獎品章，如果你需要的話，我有些啤酒節禮品可以賣喔。', '嘿，我看到你手上的啤酒節獎品章，如果你需要的話，我有些啤酒節禮品可以賣喔。', '嘿，我看到你手上的啤酒節獎品章，如果你需要的話，我有些啤酒節禮品可以賣喔。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
