INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12973, 'zhTW', 'Hey, $n!  I hope you\'ve been enjoying our club!', '嘿，$n!我希望你喜歡我們的俱樂部!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12976 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12976, 'zhTW', '$N，很高興見到你!$B$B還是說，這是我們首度見面呢?$B$B我現在得東奔西跑，有的時候我根本記不得誰是誰。', '$N，很高興見到你!$B$B還是說，這是我們首度見面呢?$B$B我現在得東奔西跑，有的時候我根本記不得誰是誰。', '$N，很高興見到你!\n\n還是說，這是我們首度見面呢?\n\n我現在得東奔西跑，有的時候我根本記不得誰是誰。', '$N，很高興再見到你！$B$B也許我們是第一次見面?$B$B這樣的情景實在太多了，有時候可能我都糊塗了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12977 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12977, 'zhTW', '荒疫、荒疫、荒疫…這附近我就只聽見這個。我好懷念多樣性!$B$B這裡，這啦，你有寵物，對吧?你當然有羅，當然，小寵物。我有一劑混合物給牠們。這會讓牠們死…呃，我是說思想敏捷又身強體壯，沒錯，沒錯。沒錯，就是身強體壯。$B$B試一下!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12978 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12978, 'zhTW', '小心使用。這東西不很穩定，又很快就會失效。馬上使用它!還有就是…最好盯著它，沒錯…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12982 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12982, 'zhTW', '我曾經離開了戰場，返回西部荒野的老家，就為了處理一些麻煩。那簡直就像是上輩子的事情了。感謝聖光，迪菲亞不再造成威脅。$B$B我們遠離家園，要是我們打不贏這場戰爭，那就沒有西部荒野可以回去了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12990 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12990, 'zhTW', '我的戰爭法師就要回來了，不一會兒就會抵達。$B$B當他們回來之後，再和我交談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12991 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12991, 'zhTW', '抱歉，$r，我有公務在身無法分心。$B$B很抱歉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12992 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12992, 'zhTW', '做得漂亮!阿薩斯已經知道斯坦索姆中的染疫穀物，即將要展開肅清行動了。但還是有些事情不對勁。我感覺得到在這條時間線中還有我們以外的外來存在，這表示恆龍軍團也一定在這裡的某處。', '做得漂亮!阿薩斯已經知道斯坦索姆中的染疫穀物，即將要展開肅清行動了。但還是有些事情不對勁。我感覺得到在這條時間線中還有我們以外的外來存在，這表示恆龍軍團也一定在這裡的某處。', '做得漂亮!阿薩斯已經知道斯坦索姆中的染疫穀物，即將要展開肅清行動了。但還是有些事情不對勁。我感覺得到在這條時間線中還有我們以外的外來存在，這表示恆龍軍團也一定在這裡的某處。', '做得漂亮!阿薩斯已經知道斯坦索姆中的染疫穀物，即將要展開肅清行動了。但還是有些事情不對勁。我感覺得到在這條時間線中還有我們以外的外來存在，這表示恆龍軍團也一定在這裡的某處。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12993 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12993, 'zhTW', '我一無所悉，這令我十分憂心。我已經竭盡所能去尋找恆龍。我現在需要你去加入阿薩斯的軍隊，以便接近他。', '我一無所悉，這令我十分憂心。我已經竭盡所能去尋找恆龍。我現在需要你去加入阿薩斯的軍隊，以便接近他。', '我一無所悉，這令我十分憂心。我已經竭盡所能去尋找恆龍。我現在需要你去加入阿薩斯的軍隊，以便接近他。', '我一無所悉，這令我十分憂心。我已經竭盡所能去尋找恆龍。我現在需要你去加入阿薩斯的軍隊，以便接近他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12994 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12994, 'zhTW', '嗯，你不用籤什麼到職通知書或是其他的，但你得去跟他並肩作戰。你得去確定阿薩斯肅清斯坦索姆，並打敗瑪爾加尼斯。由於沒有烏瑟跟珍娜在他身邊，他會需要所有他能得到的幫助。如果你跟他說，他會把你放進摧毀瑪爾加尼斯的武力之中。跟著隊伍，直到我瞭解恆龍軍團在搞什麼鬼。等我瞭解更多資訊時，我會聯絡你的。', '嗯，你不用籤什麼到職通知書或是其他的，但你得去跟他並肩作戰。你得去確定阿薩斯肅清斯坦索姆，並打敗瑪爾加尼斯。由於沒有烏瑟跟珍娜在他身邊，他會需要所有他能得到的幫助。如果你跟他說，他會把你放進摧毀瑪爾加尼斯的武力之中。跟著隊伍，直到我瞭解恆龍軍團在搞什麼鬼。等我瞭解更多資訊時，我會聯絡你的。', '嗯，你不用籤什麼到職通知書或是其他的，但你得去跟他並肩作戰。你得去確定阿薩斯肅清斯坦索姆，並打敗瑪爾加尼斯。由於沒有烏瑟跟珍娜在他身邊，他會需要所有他能得到的幫助。如果你跟他說，他會把你放進摧毀瑪爾加尼斯的武力之中。跟著隊伍，直到我瞭解恆龍軍團在搞什麼鬼。等我瞭解更多資訊時，我會聯絡你的。', '嗯，你不用籤什麼到職通知書或是其他的，但你得去跟他並肩作戰。你得去確定阿薩斯肅清斯坦索姆，並打敗瑪爾加尼斯。由於沒有烏瑟跟珍娜在他身邊，他會需要所有他能得到的幫助。如果你跟他說，他會把你放進摧毀瑪爾加尼斯的武力之中。跟著隊伍，直到我瞭解恆龍軍團在搞什麼鬼。等我瞭解更多資訊時，我會聯絡你的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12995 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12995, 'zhTW', '祝好運，並且自己小心。烏瑟和珍娜來了。', '祝好運，並且自己小心。烏瑟和珍娜來了。', '祝好運，並且自己小心。烏瑟和珍娜來了。', '祝好運，並且自己小心。烏瑟和珍娜來了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
