INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13006, 'zhTW', '我的生意夥伴負責殺;我負責抽取他們一部份的精華...只抽一點點，真的;只是薄薄的一小片而已。他們不會在意的。$B$B不過，為了要完成我的契約，我會用以太信用貨幣付帳。$B$B可以用這些貨幣隨時跟我換我賣的東西。我一定會有你感興趣的商品...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
