INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13024, 'zhTW', '我認為你應該離開，$g先生:小姐;。你嚇到軟綿綿先生了。', '我認為你應該離開，$g先生:小姐;。你嚇到軟綿綿先生了。', '我認為你應該離開，$g先生:小姐;。你嚇到軟綿綿先生了。', '你該走了，你嚇死我了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
