INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13044, 'zhTW', '驚懼船長狄米撒駛進了藏寶海灣，宣佈今天是海賊日!$B$B任何有勇氣跟她喝一杯酒的人都可以當她的榮譽船員。', '驚懼船長狄米撒駛進了藏寶海灣，宣佈今天是海賊日!$B$B任何有勇氣跟她喝一杯酒的人都可以當她的榮譽船員。', '驚懼船長狄米撒駛進了藏寶海灣，宣佈今天是海賊日!\n\n任何有勇氣跟她喝一杯酒的人都可以當她的榮譽船員。', '驚懼船長狄米撒駛進了藏寶海灣，然後宣佈今天是海賊日!$B$B任何有勇氣跟她喝一杯酒的人都可以當她的榮譽船員。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
