INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13047, 'zhTW', '替你感謝聖光!', '替你感謝聖光!', '替你感謝聖光!', '替你感謝聖光!', '替你感謝聖光!', '替你感謝聖光!', '替你感謝聖光!', '替你感謝聖光!', '快點…這裡的戰鬥是殘酷的。我需要保持警惕。', '快點…這裡的戰鬥是殘酷的。我需要保持警惕。', '你是新兵嗎？這不是標配的盔甲。', '你是新兵嗎？這不是標配的盔甲。', '哦，很好，援軍！', '哦，很好，援軍！', '你有給我的訊息？', '你有給我的訊息？');
