INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13050, 'zhTW', '我是烏邦苟，我代表贊達拉部族。$B$B壞事情正悄悄進行著，$r。德拉克瑞將會因為他們的所作所為而大難臨頭。$B$B總是有食人妖學不乖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13055 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13055, 'zhTW', '啊呵，甜心!$B$B今天是我們的日子，你知道…海賊日!$B$B老餌鬥跟我想出了這個點子，然後驚懼船長一聽到…就辦了這個活動!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13056 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13056, 'zhTW', '明天，大財主就可以拿回他的城市…但今天 - 海賊日 - 是屬於驚懼船長狄米撒和她的船員的。呀哈哈!$B$B記住:看起來像個海賊只是慶典內容的一部分。你得像個海賊一樣說話，$g小子:小妞;!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13057 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13057, 'zhTW', '哈帕那咕噥著揮手趕你去找驚懼船長狄米撒。$B$B在一隻粗壯手臂的毛底下你看見一顆被箭穿過的心上刺著「瑪加薩」的字樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13058 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13058, 'zhTW', '嘎!把那個小子抓去浸龍骨!浸龍骨!', NULL, '嘎!把那個小子抓去浸龍骨!浸龍骨!', NULL, '嘎!把那個小子抓去浸龍骨!浸龍骨!', NULL, '嘎!把那個小子抓去浸龍骨!浸龍骨!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
