INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13059, 'zhTW', '你還挺有種到這裡來的，$g小子:小妞;。今天是海賊日，知道吧…直到早晨陽光升起以前，藏寶海灣都是屬於我的。$B$B所以你要怎麼做呢?弄杯飲料給我和我的船員喝，然後加入我們的慶典如何?', '你還挺有種到這裡來的，$g小子:小妞;。今天是海賊日，知道吧…直到早晨陽光升起以前，藏寶海灣都是屬於我的。$B$B所以你要怎麼做呢?弄杯飲料給我和我的船員喝，然後加入我們的慶典如何?', '你還挺有種到這裡來的，$g小子:小妞;。今天是海賊日，知道吧…直到早晨陽光升起以前，藏寶海灣都是屬於我的。\n\n所以你要怎麼做呢?弄杯飲料給我和我的船員喝，然後加入我們的慶典如何?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
