INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13062, 'zhTW', '歡迎來到寶藏海灣，夥伴。請不要在意狄米撒和她的船員…我們讓這個壞人一年選一天放縱一次，就在海賊日，接著她就得平靜的離開，回到南海上繼續劫掠。$B$B現在呢…這個謙遜的熱砂僕人能為你做些什麼呢?更棒的是 - 你為能為我做什麼，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
