INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13092, 'zhTW', '你在輕視個什麼勁?$B$B我會讓你知道搗盆家族在搗碎方面可是赫赫有名。$B$B沒錯，那是一個字!$B$B我可以跟你保證，在全艾澤拉斯或是任何地方都找不到更好的鏈金師了!$B$B我現在可能領著學徒的頭銜，但我的技術可不比任何人差!一個人必須承受如此謙卑的想法才能在人生中有所成就。$B$B當然，或許你只是到這來幫忙我的?$B$B<這個小地精傲慢得笑了。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13093 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13093, 'zhTW', '聽著，告訴史懷哲和羅伊陶，這裡一切都在我們的掌控之下。他們不能…什麼?$B$B不是他們派你來的?那你幹嘛浪費我的時間?$B$B我還有活要幹!', '聽著，告訴史懷哲和羅伊陶，這裡一切都在我們的掌控之下。他們不能…什麼?$B$B不是他們派你來的?那你幹嘛浪費我的時間?$B$B我還有活要幹!', '聽著，告訴史懷哲和羅伊陶，這裡一切都在我們的掌控之下。他們不能…什麼?\n\n不是他們派你來的?那你幹嘛浪費我的時間?\n\n我還有活要幹!', '聽著，告訴史懷哲和羅伊陶，這裡一切都在我們的掌控之下。他們不能…什麼?$B$B不是他們派你來的?那你幹嘛浪費我的時間?$B$B我還有活要幹!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13094 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13094, 'zhTW', '嘿，沒看到我正在忙嘛?!$B$B你想看節目?樂團每天晚上八點演出。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13096 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13096, 'zhTW', '喔…好啦，好啦，不管怎樣，我們得測試一下裝備才行。$B$B給我幾秒鐘，我會叫它們出來「排練」一下。$B$B準備好了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13097 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13097, 'zhTW', '歡迎，$r。$B$B恐怕你得原諒我，因為我此刻異常的忙碌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13098 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13098, 'zhTW', '在這，時間是非常重要的，$n。你準備好接受考驗了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13100 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13100, 'zhTW', '嗯，我很驚訝在這樣的地方還會看到其他的冒險者!要是我知道你會到這來的話，我就會跟你一起進來，而不是駕駛這架煉獄般的地精玩意兒了。不過現在你人都在這裡了，你可以幫我進入議庭吧!如果我對此地的研究正確無誤，那關於創造整個矮人種族的資料就在這裡!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13101 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13101, 'zhTW', '夥伴，瞧!真是奇妙的景色!但願我那親愛的兄弟可以此刻出現在這兒。他們肯定不會相信這是多麼了不起的發現!議庭是泰坦圓盤的保管者，而圓盤就存放在這間房間裡。看!你可以看到地底下的圓盤!我們動作要快，矮人族的偉大發現就在眼前了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13117 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13117, 'zhTW', '我們最不需要的事情就是讓瘋狂的德拉克瑞食人妖在我們的後院把天譴亡域打下來。$B$B他們是怎麼做到的?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13118 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13118, 'zhTW', '呃，我實在不應該自願當個專家。他們老是要求一些不可能的事情!', '呃，我實在不應該自願當個專家。他們老是要求一些不可能的事情!', '呃，我實在不應該自願當個專家。他們老是要求一些不可能的事情!', '呃，我實在不應該自願當個專家。他們老是要求一些不可能的事情!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13119 AND `Locale` = 'zhTW';
