INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13157, 'zhTW', '感謝你釋放了我，$r。$B$B我還因為中毒而有些迷糊。我想我會待在這裡直到我的力量恢復。', '感謝你釋放了我，$r。$B$B我還因為中毒而有些迷糊。我想我會待在這裡直到我的力量恢復。', '感謝你釋放了我，$r。\n\n我還因為中毒而有些迷糊。我想我會待在這裡直到我的力量恢復。', '感謝你釋放了我，$r。$B$B我還因為中毒而有些迷糊。我想我會待在這裡直到我的力量恢復。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
