INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13172, 'zhTW', '透過穢邪之力，我們得以操控死亡!', '透過穢邪之力，我們得以操控死亡!', '邪惡的力量將令敵人畏懼也將帶給敵人死亡.', '透過穢邪之力，我們得以操控死亡!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13173 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13173, 'zhTW', '鮮血就是生命...操控鮮血的起伏是如此的簡單，一如玩弄敵人的生命。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13174 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13174, 'zhTW', '我們伴著寒風降臨。冰霜般凜冽的絕望...死亡的冰冷擁抱...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13176 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13176, 'zhTW', '突然間我們全都看見德拉克瑞用這種方式毀滅自己。$B$B他們殺死這片土地的自然諸神時所獲得的力量是短暫的。$B$B他們的短暫獲得，將永遠不復得。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13177 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13177, 'zhTW', '快點集中你的注意力，我們一定要加把勁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13179 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13179, 'zhTW', '情況並沒有簡單多少。斯坦索姆正在燃燒。我們必須要面對天譴軍團與火焰才能靠近瑪爾加尼斯。做好準備。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13180 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13180, 'zhTW', '辛託加可以提供我們某些程度的保護，但是因為天譴軍的出現與德拉克瑞的行動，辛託加已經被大幅弱化了。$B$B剩餘的防禦行動就落到我和艾胡奈的肩膀上了。', '辛託加可以提供我們某些程度的保護，但是因為天譴軍的出現與德拉克瑞的行動，辛託加已經被大幅弱化了。$B$B剩餘的防禦行動就落到我和艾胡奈的肩膀上了。', '辛託加可以提供我們某些程度的保護，但是因為天譴軍的出現與德拉克瑞的行動，辛託加已經被大幅弱化了。\n\n剩餘的防禦行動就落到我和艾胡奈的肩膀上了。', '辛託加可以提供我們某些程度的保護，但是因為天譴軍的出現與德拉克瑞的行動，辛託加已經被大幅弱化了。$B$B剩餘的防禦行動就落到我和艾胡奈的肩膀上了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13234 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13234, 'zhTW', '艾胡奈的巨斧會解決那些德拉克瑞人。$B$B就算逃過我的斧頭，你也會料理他們!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13237 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13237, 'zhTW', '欺詐者法師領主厄隆保護著第三道環。他看起來單獨一人並且毫無戒備，但是別被他的外貌給欺騙了!厄隆是位強大的咒術師，控制一整群的幻魅生物。在上面把他找出來。$B$B我可以賦予你呼喚一頭紅龍軍團飛龍的力量。如果你傾向獲取青銅軍團的力量，向伊特諾斯交談，如果你屬意綠龍的力量，向薇爾迪莎交談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13238 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13238, 'zhTW', '你的最大挑戰正等著你。地脈守護者伊瑞苟斯是一頭力大無窮的藍龍。你會在最上環的上方飛行遇到牠。$B$B你的飛龍力量已全部開啟，利用他們的能力擊敗伊瑞苟斯!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13239 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13239, 'zhTW', '你已經從瑪裡苟斯軍隊的手上奪走了奧核之眼的控制。紅龍軍團欠你一次。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13240 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13240, 'zhTW', '青銅龍軍團欠你一份人情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13241 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13241, 'zhTW', '綠龍軍團欠你一份人情。', '綠龍軍團欠你一份人情。', '綠龍軍團欠你一份人情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13254 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13254, 'zhTW', '晶紅龍擅長減輕傷害並且保護他們的同伴。$B$B使用灼熱之怒，他們會噴吐出一道液態火焰，在目標與目標之間跳躍，每增加一次跳躍便輸出更多的傷害。$B$B一旦晶紅龍遭受敵人攻擊，他便能獲得一發迴避能量。這些能量可以用來施展一系列的迴避動作，使飛龍在一段時間中閃躲來襲的攻擊與法術。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13255 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13255, 'zhTW', '晶紅龍處於能量全滿的狀態下可以施展殉節，可以保護友善目標，短時間內將所有敵對的魔法導引到晶紅龍身上。殉節施展的過程中依然可以使用迴避動作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13256 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13256, 'zhTW', '琥珀龍擅長於利用時間操縱來分配傷害。$B$B使用時間震擊可以中斷敵方目標的時間流逝，立刻造成傷害。這能力的效果會隨著震擊能量的提升而大幅強化。$B$B當受到威脅時，琥珀龍可以短暫停止敵人的時間流逝。時間中斷蘊含了大量的震能，以震擊能量的型態影響目標。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13257 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13257, 'zhTW', '琥珀龍處於能量全滿的狀態下可以施展時光裂隙，在敵人身邊製造出一顆壓縮的時間泡泡。透過泡泡的法術會造成雙倍的傷害，並且在目標上產生震擊能量。', '琥珀龍處於能量全滿的狀態下可以施展時光裂隙，在敵人身邊製造出一顆壓縮的時間泡泡。透過泡泡的法術會造成雙倍的傷害，並且在目標上產生震擊能量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13258 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13258, 'zhTW', '翡翠龍擅長以毒害敵人來治療自己。$B$B使用吸血之毒，他們可以從敵人身上偷取生命。反覆操作這種毒素可以提高其效果。$B$B利用夢魘之觸，翡翠龍可以接觸翡翠夢境，轉化一部分他們的生命能量成為巨幅傷害攻擊，使對手虛弱，短時間內降低他們的傷害能力。', '翡翠龍擅長以毒害敵人來治療自己。$B$B使用吸血之毒，他們可以從敵人身上偷取生命。反覆操作這種毒素可以提高其效果。$B$B利用夢魘之觸，翡翠龍可以接觸翡翠夢境，轉化一部分他們的生命能量成為巨幅傷害攻擊，使對手虛弱，短時間內降低他們的傷害能力。', '翡翠龍擅長以毒害敵人來治療自己。\n\n使用吸血之毒，他們可以從敵人身上偷取生命。反覆操作這種毒素可以提高其效果。\n\n利用夢魘之觸，翡翠龍可以接觸翡翠夢境，轉化一部分他們的生命能量成為巨幅傷害攻擊，使對手虛弱，短時間內降低他們的傷害能力。', '翡翠龍擅長以毒害敵人來治療自己。$B$B使用吸血之毒，他們可以從敵人身上偷取生命。反覆操作這種毒素可以提高其效果。$B$B利用夢魘之觸，翡翠龍可以接觸翡翠夢境，轉化一部分他們的生命能量成為巨幅傷害攻擊，使對手虛弱，短時間內降低他們的傷害能力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13259 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13259, 'zhTW', '翡翠龍處於能量全滿的狀態下可以施展夢境通道，傳送飛龍本身的生命能源到一名友善的目標身上，治療他。當使用這個能力時，可以施展吸血之毒恢復損失的生命力。', '翡翠龍處於能量全滿的狀態下可以施展夢境通道，傳送飛龍本身的生命能源到一名友善的目標身上，治療他。當使用這個能力時，可以施展吸血之毒恢復損失的生命力。', '翡翠龍處於能量全滿的狀態下可以施展夢境通道，傳送飛龍本身的生命能源到一名友善的目標身上，治療他。當使用這個能力時，可以施展吸血之毒恢復損失的生命力。', '翡翠龍處於能量全滿的狀態下可以施展夢境通道，傳送飛龍本身的生命能源到一名友善的目標身上，治療他。當使用這個能力時，可以施展吸血之毒恢復損失的生命力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13261 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13261, 'zhTW', '歡迎來到崗哨，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13262 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13262, 'zhTW', '你需要從寇孚斯那兒拿些什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13265 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13265, 'zhTW', '仔細考慮一下你今天見證的事情，$n。$B$B未來已經註定了。唯一尚待決定的，則是你要加入哪一邊了，老兄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13267 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13267, 'zhTW', '瑪裡苟斯手下最強大的成員保護著上方的環。你一個人沒辦法打敗他們。我們可以給予你得以召喚我方軍團飛龍的力量。騎上一條飛龍，你就可以在奧核之眼中飛翔並且指揮強大的龍族魔法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13268 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13268, 'zhTW', '貝加瑞斯塔茲說的是實話;時間緊迫!$B$B你的飛龍力量已全部開啟。使用他們的力量來打敗伊瑞苟斯。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13269 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13269, 'zhTW', '貝加瑞斯塔茲說的是實話;情況的確很嚴重。$B$B你的飛龍力量已全部開啟。使用他們的力量來打敗伊瑞苟斯。', '貝加瑞斯塔茲說的是實話;情況的確很嚴重。$B$B你的飛龍力量已全部開啟。使用他們的力量來打敗伊瑞苟斯。', '貝加瑞斯塔茲說的是實話;情況的確很嚴重。\n\n你的飛龍力量已全部開啟。使用他們的力量來打敗伊瑞苟斯。', '貝加瑞斯塔茲說的是實話;情況的確很嚴重。$B$B你的飛龍力量已全部開啟。使用他們的力量來打敗伊瑞苟斯。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13270 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13270, 'zhTW', '沒人比我們死亡騎士更瞭解天譴軍團了。$B$B相信我，$r，沒有什麼比以毒攻毒來的更加有用...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13271 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13271, 'zhTW', '別急著處理納斯。他已經不再年輕，也不再像從前一樣強韌了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
