INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13290, 'zhTW', '<血玫好奇的看著你。>$B$B我無法不去懷疑你到底哪裡值得注意。$B$B無冒犯之意...', '<血玫好奇的看著你。>$B$B我無法不去懷疑你到底哪裡值得注意。$B$B無冒犯之意...', '<血玫好奇的看著你。>\n\n我無法不去懷疑你到底哪裡值得注意。\n\n無冒犯之意……', '<血玫好奇的看著你。>$B$B我無法不去懷疑你到底哪裡值得注意。$B$B無冒犯之意……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13291 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13291, 'zhTW', '德拉克瑞一直將我的屍身在祭壇上保持半亡狀態。不過他們看不到我的靈魂。$B$B我們一定得聯手阻止他們得到我的力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13293 AND `Locale` = 'zhTW';
