INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13300, 'zhTW', '哇噢...看看那隻漂亮的小食屍鬼。$B$B跳啊，小食屍鬼!跳!$B$B哈，哈，哈...真是隻很棒的小食屍鬼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13301 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13301, 'zhTW', '我們打算把這堵牆炸掉，這樣威克的人才能蓋新的警衛站跟後面的道路，但是那個無知的蠢蛋嫌我用掉太多火藥了!$B$B嘖嘖，當我在挖通道的時候他還包著尿布呢。我要把他踢進運河然後自己一個人把剩下的爆破工作完成，這還會花比較多的時間!', '我們打算把這堵牆炸掉，這樣威克的人才能蓋新的警衛站跟後面的道路，但是那個無知的蠢蛋嫌我用掉太多火藥了!$B$B嘖嘖，當我在挖通道的時候他還包著尿布呢。我要把他踢進運河然後自己一個人把剩下的爆破工作完成，這還會花比較多的時間!', '我們打算把這堵牆炸掉，這樣威克的人才能蓋新的警衛站跟後面的道路，但是那個無知的蠢蛋嫌我用掉太多火藥了!\n\n嘖嘖，當我在挖通道的時候他還包著尿布呢。我要把他踢進運河然後自己一個人把剩下的爆破工作完成，這還會花比較多的時間!', '我們打算把這堵牆炸掉，這樣威克的人才能蓋新的警衛站跟後面的道路，但是那個無知的蠢蛋嫌我用掉太多火藥了!$B$B嘖嘖，當我在挖通道的時候他還包著尿布呢。我要把他踢進運河然後自己一個人把剩下的爆破工作完成，這還會花比較多的時間!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13302 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13302, 'zhTW', '只要這堵牆拆掉，我們就要舖另外一條通往暴風港的路…但是那個瘋矮人用了足以移平整座廣場的火藥啦!$B$B我不曉得當初艾力克斯頓大人僱用她的時候腦袋在想什麼…她是個滿口髒話、刻薄成性、剛愎自用的人!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13303 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13303, 'zhTW', '天譴軍團是這片原始大地的汙點。藉由我造物主的力量，我會連它們最後一丁點脆弱的骨頭都壓碎在我的腳下。', '天譴軍團是這片原始大地的汙點。藉由我造物主的力量，我會連它們最後一丁點脆弱的骨頭都壓碎在我的腳下。', '天譴軍團是這片原始大地的汙點。藉由我造物主的力量，我會連它們最後一丁點脆弱的骨頭都壓碎在我的腳下。', '天譴軍團是這片原始大地的汙點。藉由我造物主的力量，我會連它們最後一丁點脆弱的骨頭都壓碎在我的腳下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
