INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13305, 'zhTW', '把這些秘密告訴像你這樣的凡人簡直是褻瀆，不過我也沒有多少選擇了。$B$B自從泰坦之女，芙蕾雅把我留在這裡進行唯一的任務，我不能失敗。必須不惜代價保護生命體。$B$B有一個甬道之門連結本地與另一處極為相似之地。在那，我們可以找到我們在找的武器。', '把這些秘密告訴像你這樣的凡人簡直是褻瀆，不過我也沒有多少選擇了。$B$B自從泰坦之女，芙蕾雅把我留在這裡進行唯一的任務，我不能失敗。必須不惜代價保護生命體。$B$B有一個甬道之門連結本地與另一處極為相似之地。在那，我們可以找到我們在找的武器。', '把這些秘密告訴像你這樣的凡人簡直是褻瀆，不過我也沒有多少選擇了。\n\n自從泰坦之女，芙蕾雅把我留在這裡進行唯一的任務，我不能失敗。必須不惜代價保護生命體。\n\n有一個甬道之門連結本地與另一處極為相似之地。在那，我們可以找到我們在找的武器。', '把這些秘密告訴像你這樣的凡人簡直是褻瀆，不過我也沒有多少選擇了。$B$B自從泰坦之女，芙蕾雅把我留在這裡進行唯一的任務，我不能失敗。必須不惜代價保護生命體。$B$B有一個甬道之門連結本地與另一處極為相似之地。在那，我們可以找到我們在找的武器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
