INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13310, 'zhTW', '奧格瑪外有兩座飛艇塔。東部飛艇塔負責往來提里斯法林地與荊棘谷，而西部飛艇塔則負責往來北裂境和雷霆崖。', '奧格瑪外有兩座飛艇塔。東部飛艇塔負責往來提里斯法林地與荊棘谷，而西部飛艇塔則負責往來北裂境和雷霆崖。', '奧格瑪外有兩座飛艇塔。東部飛艇塔負責往來提里斯法林地與荊棘谷，而西部飛艇塔則負責往來北裂境和雷霆崖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
