INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13331, 'zhTW', '你喜歡這個為了我所謂的信徒所刻出來的新居嗎?$B$B藉著我死亡的掙扎，我詛咒每一個人，把他們和我一道拖進這親手創出來的幽暗世界。$B$B我認為我會在他們無盡的折磨之中找到樂子，但是我真正的希望是對我之前的預言者進行復仇!', '你喜歡這個為了我所謂的信徒所刻出來的新居嗎?$B$B藉著我死亡的掙扎，我詛咒每一個人，把他們和我一道拖進這親手創出來的幽暗世界。$B$B我認為我會在他們無盡的折磨之中找到樂子，但是我真正的希望是對我之前的預言者進行復仇!', '你喜歡這個為了我所謂的信徒所刻出來的新居嗎?\n\n藉著我死亡的掙扎，我詛咒每一個人，把他們和我一道拖進這親手創出來的幽暗世界。\n\n我認為我會在他們無盡的折磨之中找到樂子，但是我真正的希望是對我之前的預言者進行復仇!', '你喜歡這個為了我所謂的信徒所刻出來的新居嗎?$B$B藉著我死亡的掙扎，我詛咒每一個人，把他們和我一道拖進這親手創出來的幽暗世界。$B$B我認為我會在他們無盡的折磨之中找到樂子，但是我真正的希望是對我之前的預言者進行復仇!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
