INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13439, 'zhTW', '想要到奧伯丁或驍勇要塞嗎?越過運河你可以找到暴風港，就在教堂區和花園中間。', '想要到奧伯丁或驍勇要塞嗎?越過運河你可以找到暴風港，就在教堂區和花園中間。', '想要到奧伯丁或驍勇要塞嗎?越過運河你可以找到暴風港，就在教堂區和花園中間。', '想要到奧伯丁或驍勇要塞嗎?越過運河你可以找到暴風港，就在教堂區和花園中間。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13441 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13441, 'zhTW', '你好，$c。我想你是來告訴我有關全球受邀典禮的好訊息吧?如果沒錯，那你來這裡就是要告訴我驗證碼的。而為了感謝你提供的驗證碼，我會給你一份禮物，泰瑞爾之柄。$B$B等你準備好後，就在我耳邊小小聲地告訴我吧。', '你好，$c。我想你是來告訴我有關全球受邀典禮的好訊息吧?如果沒錯，那你來這裡就是要告訴我驗證碼的。而為了感謝你提供的驗證碼，我會給你一份禮物，泰瑞爾之柄。$B$B等你準備好後，就在我耳邊小小聲地告訴我吧。', '很高興見到你,$c.我相信你會給我關於全球邀請賽的好訊息吧?如果你是，那麼可以肯定，這意味著給你會告訴我一個秘密程式碼.給我程式碼之後我會給你一份禮"泰瑞爾之柄".$B$B當你準備好.只要在我耳邊輕輕告訴我.', '你好，$c。我想你是來告訴我有關全球受邀典禮的好訊息吧?如果沒錯，那你來這裡就是要告訴我驗證碼的。而為了感謝你提供的驗證碼，我會給你一份禮物，泰瑞爾之柄。$B$B等你準備好後，就在我耳邊小小聲地告訴我吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13444 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13444, 'zhTW', '我們是獲選之人，$N。天譴軍團的死亡騎士，前來散佈主人的毀滅之種。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13445 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13445, 'zhTW', '這些怪物殺了我的父親、擄走了我的妹妹。他們得為此付出代價!', '這些怪物殺了我的父親、擄走了我的妹妹。他們得為此付出代價!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13449 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13449, 'zhTW', '歡迎光臨我的廚房!我們準備了不少達拉然最棒的食物在這裡。', '歡迎光臨我的廚房!我們準備了不少達拉然最棒的食物在這裡。', '歡迎光臨我的廚房!我們準備了不少達拉然最棒的食物在這裡。', '歡迎光臨我的廚房!我們準備了不少達拉然最棒的食物在這裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13451 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13451, 'zhTW', '希望你跟大舌頭相處愉快。該是他們離開的時候了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13452 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13452, 'zhTW', '大戰依舊在炫觸避風港持續著。$B$B或許你可以找時間去幫忙?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13454 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13454, 'zhTW', '你好，$c!暴風港是一處很顯著的地方。即使從空中都看得一清二楚。你想像只鳥一樣來俯瞰這個海港嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13455 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13455, 'zhTW', '我不相信你的心智敏銳到可以理解傳送魔法的本質。$B$B不過，你可以使用我前面的水晶來傳送至水晶之歌森林中，位於達拉然底下的廢墟。', '我不相信你的心智敏銳到可以理解傳送魔法的本質。$B$B不過，你可以使用我前面的水晶來傳送至水晶之歌森林中，位於達拉然底下的廢墟。', '我不相信你的心智敏銳到可以理解傳送魔法的本質。\n\n不過，你可以使用我前面的水晶來傳送至水晶之歌森林中，位於達拉然底下的廢墟。', '我不相信你的心智敏銳到可以理解傳送魔法的本質。$B$B不過，你可以使用我前面的水晶來傳送至水晶之歌森林中，位於達拉然底下的廢墟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13456 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13456, 'zhTW', '身為一位法師，你屬於卓越團體中的一員，能夠召喚一道傳送門將你傳回這個特別的地方。如果你準備好了，我就可以教導你。$B$B記住，你永遠都可以使用我前方的水晶來傳送至水晶之歌森林中，位於達拉然下方的廢墟。', '身為一位法師，你屬於卓越團體中的一員，能夠召喚一道傳送門將你傳回這個特別的地方。如果你準備好了，我就可以教導你。$B$B記住，你永遠都可以使用我前方的水晶來傳送至水晶之歌森林中，位於達拉然下方的廢墟。', '身為一位法師，你屬於卓越團體中的一員，能夠召喚一道傳送門將你傳回這個特別的地方。如果你準備好了，我就可以教導你。\n\n記住，你永遠都可以使用我前方的水晶來傳送至水晶之歌森林中，位於達拉然下方的廢墟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13457 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13457, 'zhTW', '你有時間?蘇-睨教你好聽的歌!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13458 AND `Locale` = 'zhTW';
