INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13466, 'zhTW', '瓦羅斯·雲行者與他的環之守護者保衛第二道環。你的飛龍大軍雖然比環之守護者強上許多，但是瓦羅斯·雲行者躲在無法穿越的護盾後面，這護盾是由奧核之眼本身的能量所製造的，由十具離心傀儡在環以及平臺的上方提供護盾的能量。摧毀它們，瓦羅斯才會有弱點。', '瓦羅斯·雲行者與他的環之守護者保衛第二道環。你的飛龍大軍雖然比環之守護者強上許多，但是瓦羅斯·雲行者躲在無法穿越的護盾後面，這護盾是由奧核之眼本身的能量所製造的，由十具離心傀儡在環以及平臺的上方提供護盾的能量。摧毀它們，瓦羅斯才會有弱點。', '瓦羅斯·雲行者與他的環之守護者保衛第二道環。你的飛龍大軍雖然比環之守護者強上許多，但是瓦羅斯·雲行者躲在無法穿越的護盾後面，這護盾是由奧核之眼本身的能量所製造的，由十具離心傀儡在環以及平臺的上方提供護盾的能量。摧毀它們，瓦羅斯才會有弱點。', '瓦羅斯·雲行者與他的環之守護者保衛第二道環。你的飛龍大軍雖然比環之守護者強上許多，但是瓦羅斯·雲行者躲在無法穿越的護盾後面，這護盾是由奧核之眼本身的能量所製造的，由十具離心傀儡在環以及平臺的上方提供護盾的能量。摧毀它們，瓦羅斯才會有弱點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
