INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13467, 'zhTW', 'The trickster Mage-Lord Urom protects the third ring.  He will appear alone and defenseless, but do not be fooled by appearances!  Urom is a powerful conjurer who commands a menagerie of Phantasmal creatures.  Seek him out above.', '欺詐者法師領主厄隆保護著第三道環。他看起來單獨一人並且毫無戒備，但是別被他的外貌給欺騙了!厄隆是位強大的咒術師，控制一整群的幻魅生物。到上面把他找出來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13468 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13468, 'zhTW', '最大挑戰正等著你。地脈守護者伊瑞苟斯是一隻擁有強大力量的藍龍。你會在最上環上方找到飛行中的牠。', '最大挑戰正等著你。地脈守護者伊瑞苟斯是一隻擁有強大力量的藍龍。你會在最上環上方找到飛行中的牠。', '最大挑戰正等著你。地脈守護者伊瑞苟斯是一隻擁有強大力量的藍龍。你會在最上環上方找到飛行中的牠。', '最大挑戰正等著你。地脈守護者伊瑞苟斯是一隻擁有強大力量的藍龍。你會在最上環上方找到飛行中的它。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
