INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13471, 'zhTW', '去找到那些被藏起來的染疫穀物箱，對它們使用你的秘法干擾器!阿薩斯接著會找到他需要動手肅清斯坦索姆的證據。', '去找到那些被藏起來的染疫穀物箱，對它們使用你的秘法干擾器!阿薩斯接著會找到他需要動手肅清斯坦索姆的證據。', '去找到那些被藏起來的染疫穀物箱，對它們使用你的秘法干擾器!阿薩斯接著會找到他需要動手肅清斯坦索姆的證據。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13472 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13472, 'zhTW', '你在這做什麼?阿薩斯現在正在斯坦索姆的入口，你該在他身邊!去吧!', '你在這做什麼?阿薩斯現在正在斯坦索姆的入口，你該在他身邊!去吧!', '你在這做什麼?阿薩斯現在正在斯坦索姆的入口，你該在他身邊!去吧!', '你在這做什麼?阿薩斯現在正在斯坦索姆的入口，你該在他身邊!去吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13474 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13474, 'zhTW', '寵物的種類分成了三種。兇暴寵物，例如貓科猛獸，可以輸出大量傷害，但同樣的無法承受多少傷害。堅韌寵物，例如烏龜，則比較屬於防禦性，能吸引敵人的注意力使你保持距離。靈巧寵物，例如蜘蛛，攻擊與防禦性兼具，特別適合於戰場與競技場。$B$B只要你的寵物獲得更多的經驗，如同你一般，也能學習新的天賦，但是速度較為緩慢。如果你想要更動寵物的天賦，回來找我吧。', '寵物的種類分成了三種。兇暴寵物，例如貓科猛獸，可以輸出大量傷害，但同樣的無法承受多少傷害。堅韌寵物，例如烏龜，則比較屬於防禦性，能吸引敵人的注意力使你保持距離。靈巧寵物，例如蜘蛛，攻擊與防禦性兼具，特別適合於戰場與競技場。$B$B只要你的寵物獲得更多的經驗，如同你一般，也能學習新的天賦，但是速度較為緩慢。如果你想要更動寵物的天賦，回來找我吧。', '寵物的種類分成了三種。兇暴寵物，例如貓，可以輸出大量傷害，但同樣的無法承受多少傷害。堅毅寵物，例如烏龜，則比較具防禦性，並能佔據敵人的注意力，使你保持距離。靈巧寵物，例如蜘蛛，攻擊與防禦性兼具，特別適合於戰場與競技場。\n\n只要你的寵物獲得更多的經驗，如同你一般，也能學習新的天賦，但是速度較為緩慢。如果你想要更動寵物的天賦，回來找我吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13475 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13475, 'zhTW', '你確定嗎?$B$B一旦我消除了你學會的天賦知識，就沒有挽回的餘地了。', '你確定嗎?$B$B一旦我消除了你學會的天賦知識，就沒有挽回的餘地了。', '你確定嗎?\n\n一旦我消除了你學會的天賦知識，就沒有挽回的餘地了。', '你確定嗎?$B$B一旦我消除了你學會的天賦知識，就沒有挽回的餘地了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
