INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13503, 'zhTW', '因為你補足了我們部份的補給品，我又能回去煮東西了。那麼，我能為你做些什麼嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13504 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13504, 'zhTW', '保持警覺，$r。$B$B外頭生死一瞬!', '保持警覺，$r。$B$B外頭生死一瞬!', '保持警覺，$r。\n\n外頭生死一瞬!', '保持警覺，$r。$B$B外頭生死一瞬!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13506 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13506, 'zhTW', '為什麼大家一副就是我把船弄沉的一樣?', '為什麼大家一副就是我把船弄沉的一樣?', '為什麼大家一副就是我把船弄沉的一樣?', '為什麼大家一副就是我把船弄沉的一樣?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13510 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13510, 'zhTW', '嗯...你的臉怎麼看怎麼眼熟，$r...給我幾秒鐘...$B$B啊哈!西部荒野，我就是在那兒見過你的。你是$n!很高興再次見到你。不過，這回希望你能幫助我們完成這工作才行。$B$B既然我們離開西部荒野來到這麼遠的地方，如果打不了勝仗，我們可就無家可歸了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13511 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13511, 'zhTW', '$N!穿了新衣服以後差點認不出你來了。還是穿著那件外套…或者你穿的重腿甲…也許是那根手杖呢?我記不得啦，年代太久遠了…$B$B嗯，我很高興你又能在這兒幫忙了，只要願意，誰都可以來幫忙。$N，如果你還是能像當初幫忙西部荒野人民軍的時候一樣的身手，我們就有機會了。$B$B這是個艱困的時刻，如果我們打不贏勝仗，我們就回不去西部荒野了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13512 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13512, 'zhTW', '有著聖光的祝福和你的協助，$N，迪菲亞不再造成威脅。$B$B但是我們離開西部荒野來到這麼遠的地方，如果打不了勝仗，我們可就無家可歸了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13517 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13517, 'zhTW', '寇爾格今天能為您做什麼呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13519 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13519, 'zhTW', '你好，朋友。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13525 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13525, 'zhTW', '是的，巫妖王將不敵我們的力量。我們會完成最後的復仇。$B$B但首先，我們得將那些像瘟疫般的血色突襲軍一勞永逸地解決掉!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13526 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13526, 'zhTW', '非常好，但如果我是你，我會仔細聽著，不只是隨便聽聽，點點頭而已。$B$B故事的開始，就像所有的故事一樣，開始於背叛。噢，不是我們被背叛…差得遠了。巫妖王除了我們這些死亡騎士之外，誰也沒復活。$B$B然而，我們卻藉著大領主達瑞安·莫格萊尼的協助，背叛了他。$B$B在聖光之願禮拜堂的最終的決戰中，當這些笨蛋就要被毀滅之時，提里奧·弗丁幫助莫格萊尼打破了巫妖王對他的束縛，還有我們在場的所有人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13527 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13527, 'zhTW', '巫妖王因為弗丁握有灰燼使者而害怕得逃之夭夭，我們才能輕易地從殘存的天譴軍手中拿下黯黑堡。$B$B但這並未解決我們與血色十字軍之間的糾紛。$B$B被遺忘者經歷了一番艱辛才獲得認同，然而那些血色傢伙似乎分辨不出我們與天譴軍之間的差異。$B$B我們有自己的想法，我們有自己的信念，我們有活人的大部分特質，但是對他們來說，我們與巫妖王無腦的奴隸之間並無二致。$B$B他們認為我們隨時會翻臉不認人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13528 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13528, 'zhTW', '<指揮統領繼續說下去之前，瞪得你一動也不敢動。>$B$B我馬上就要說到了。的確，當大將軍阿比迪斯率領她的大軍登陸北裂境之後，便將血色十字軍的名稱改為了血色突襲軍。$B$B這件事就在海軍上將巴瑞恩·西風與她在龍骨荒野的新壁爐谷會面前不久。各方揣測，阿比迪斯並不期待他會有什麼表現。同時阿比迪斯也不認為自己對血色突襲軍的統帥與權威會被他暗中削弱。$B$B就如同你被牽扯進阿比迪斯的權力鬥爭之中，但這無所謂。當她一死，上將就神秘地潛逃，連我們也跟丟了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13529 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13529, 'zhTW', '我說過，我們跟丟他了。但是我相信你能替我把他揪出來的。我懷疑他應該在下面某處，但是我的間諜無法在島上找到他。$B$B毒怨之地的被遺忘者乾得很好，成功的破壞了新壁爐谷，但是那兒的突襲軍只是善戰部隊的殘餘。不幸的是，他們沿途獲得了精良的裝備，還有獅鷲獸可以載著那些笨蛋東奔西走。$B$B我想要強調的是，$N，即使對你來說，這也不是鄉間遠足。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13530 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13530, 'zhTW', '我們馬上就會出發。$B$B我醜話說在前頭 -- 我們不光是要削弱他們，我們不只是騷擾他們，我們要把這種被叫做血色突襲軍的疾病一勞永逸的解決。$B$B如果你不想受牽連，如果你沒有興趣，現在就滾。我要一個願意日以繼夜的跟著我們、直到事情完成的人。$B$B你是那個我們要找的人嗎，$N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13531 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13531, 'zhTW', '<指揮統領笑得咧起嘴巴，目光銳利的上下端詳著你。>$B$B這才是我想聽的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13534 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13534, 'zhTW', '想想這些年以來，血色大軍所造成的折磨。折磨、狂熱、謀殺。$B$B我不允許這些惡行繼續。你呢?', '想想這些年以來，血色大軍所造成的折磨。折磨、狂熱、謀殺。$B$B我不允許這些惡行繼續。你呢?', '想想這些年以來，血色大軍所造成的折磨。折磨、狂熱、謀殺。\n\n我不允許這些惡行繼續。你呢?', '想想這些年以來，血色大軍所造成的折磨。折磨、狂熱、謀殺。$B$B我不允許這些惡行繼續。你呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13540 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13540, 'zhTW', '海茲競技是神聖的。誰要是能贏得勝利就能確保能永伴在索林姆身旁。', '海茲競技是神聖的。誰要是能贏得勝利就能確保能永伴在索林姆身旁。', '海茲競技是神聖的。誰要是能贏得勝利就能確保能永伴在索林姆身旁。', '海茲競技是神聖的。誰要是能贏得勝利就能確保能永伴在索林姆身旁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13548 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13548, 'zhTW', '你好，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13557 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13557, 'zhTW', '您好，$c，我能幫助您將寵物帶入獸欄，或找回失去的夥伴。', '您好，$c，我能幫助您將寵物帶入獸欄，或找回失去的夥伴。', '您好，$c，我能幫助您將寵物帶入獸欄，或找回失去的夥伴。', '您好，$c，我能幫助您將寵物帶入獸欄，或找回失去的夥伴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
