INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13565, 'zhTW', '冰牙已經載著我歷經了無數的戰鬥。$B$B別因為她沒穿上戰甲就被欺騙了，她可是我所知道最勇猛的熊了。', '冰牙已經載著我歷經了無數的戰鬥。$B$B別因為她沒穿上戰甲就被欺騙了，她可是我所知道最勇猛的熊了。', '冰牙已經載著我歷經了無數的戰鬥。\n\n別因為她沒穿上戰甲就被欺騙了，她可是我所知道最勇猛的熊了。', '冰牙已經載著我歷經了無數的戰鬥。$B$B別因為她沒穿上戰甲就被欺騙了，她可是我所知道最勇猛的熊了。', NULL, '冰牙已經載著我歷經了無數的戰鬥。$B$B別因為她沒穿上戰甲就被欺騙了，她可是我所知道最勇猛的熊了。', NULL, '冰牙已經載著我歷經了無數的戰鬥。$B$B別因為她沒穿上戰甲就被欺騙了，她可是我所知道最勇猛的熊了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
