DELETE FROM `npc_text_locale` WHERE `ID` = 13646 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13646, 'zhTW', '博克塔覺得這次墜毀是個不幸的意外，但我相信我們應該可以從中學到些什麼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13647 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13647, 'zhTW', '依米亞的戰鬥統帥，『天選』奧嘉爾，帶領著他的瓦苟軍團在痛苦之匣揮軍起義，就在這個牢籠的東北方。$B$B納法勒斯王子穿越了方的亡者原野，就在通往祖爾德拉克第二層的巨大階梯旁。瑟瑞姆的位置還不知道，但是以他的體型來說蠻奇怪的。$B$B你得處理掉他們三個。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
