INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13659, 'zhTW', '黯刃騎士團在拿下暗影穹殿這件事上欠你一份人情。我們很幸運能有你的幫助。$B$B當聯盟與部落彼此征戰，替巫妖王省下力氣時，我們依舊會全力處理眼前的任務。$B$B銀白十字軍還要猶豫、反覆思考要如何漂亮地戰勝敵人，我們可沒有那麼多道德限制。$B$B你能夠成為我們復仇的手段之一，$N。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13660 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13660, 'zhTW', '我會把你撕碎。', '我會把你撕碎。', '我會把你撕碎。', '我會把你撕碎。', NULL, '我會把你撕碎。', NULL, '我會把你撕碎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
