INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13678, 'zhTW', '別煩我，小蟲。我正在研究這些所謂的戰士的笨拙招式。$B$B我當然會勝過他們全部，接著我就可以榮升服侍巫妖王了。', '別煩我，小蟲。我正在研究這些所謂的戰士的笨拙招式。$B$B我當然會勝過他們全部，接著我就可以榮升服侍巫妖王了。', '別煩我，小蟲。我正在研究這些所謂的戰士的笨拙招式。\n\n我當然會勝過他們全部，接著我就可以榮升服侍巫妖王了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
