INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13694, 'zhTW', '你也來向巫妖王證明自己?$B$B你不覺得這樣做太過時了嗎?得拼個你死我活?', '你也來向巫妖王證明自己?$B$B你不覺得這樣做太過時了嗎?得拼個你死我活?', '你也來向巫妖王證明自己?\n\n你不覺得這樣做太過時了嗎?得拼個你死我活?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13695 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13695, 'zhTW', '嘿，是你!我想你應該很感激我在這裡。那個傳送意外可是我這輩子發生過最好的事情。$B$B要是你都能在北風凍原找到路，讓那個偽善的複製笨蛋知道我在這個世界上可還是有做事的!', '嘿，是你!我想你應該很感激我在這裡。那個傳送意外可是我這輩子發生過最好的事情。$B$B要是你都能在北風凍原找到路，讓那個偽善的複製笨蛋知道我在這個世界上可還是有做事的!', '嘿，是你!我想你應該很感激我在這裡。那個傳送意外可是我這輩子發生過最好的事情。\n\n要是你都能在北風凍原找到路，讓那個偽善的複製笨蛋知道我在這個世界上可還是有做事的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
