INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13699, 'zhTW', '我不再訓練死亡騎士了，我厭倦那些痴呆的新生跟他們無止境的問題了。$B$B現在滾吧。', '我不再訓練死亡騎士了，我厭倦那些痴呆的新生跟他們無止境的問題了。$B$B現在滾吧。', '我已不再訓練死亡騎士.去找適合你的訓練師吧!', '我不再訓練死亡騎士了，我厭倦那些痴呆的新生跟他們無止境的問題了。$B$B現在滾吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
