INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13735, 'zhTW', '你最近過的好嗎，老兄?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13737 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13737, 'zhTW', '我能怎麼服務你?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13738 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13738, 'zhTW', '你要什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13740 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13740, 'zhTW', '身為土靈的朋友跟盟友，這裡任何時候都歡迎你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13747 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13747, 'zhTW', '你可以參觀我們的堡壘了，小$r。$B$B別讓我們丟臉了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13748 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13748, 'zhTW', '我還沒有信任你到可以跟你講這種事。$B$B你必須尊重我們人民所受過的試鏈，我們所揹負的重擔…$B$B或許，你是來給丹尼弗蘭帶來榮耀的話，如此的話，我願意跟你分享一些我們的知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13749 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13749, 'zhTW', '非常好，小$c。$B$B雖然你在我們跟索林姆的關係上還有很多得做，不過我被迫要跟你分享這個小秘密。$B$B當你準備好要看時，再來找我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13759 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13759, 'zhTW', '嗨，$r。有什麼我能幫忙的嗎?', '嗨，$r。有什麼我能幫忙的嗎?', '哈羅, $r. 今天我能幫你什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13761 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13761, 'zhTW', '抱歉，朋友。只有被認可的部落軍官才有權購買一臺載具。', '抱歉，朋友。只有被認可的部落軍官才有權購買一臺載具。', '抱歉，朋友。只有被認可的部落軍官才有權購買一臺載具。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13764 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13764, 'zhTW', '很高興再次見到你!$B$B風暴之心國王已經離去一陣子了…他回想起一個悲傷的記憶，需要好好冷靜。他很堅持要我們不用跟著他，所以我們如往常尊重他的意願。$B$B而現在我負責領導我們氏族。當然，我們還是一樣歡迎你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13776 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13776, 'zhTW', '你不是坦卡族人。你為什麼來到我們族中戰士的神聖墓地?', '你不是坦卡族人。你為什麼來到我們族中戰士的神聖墓地?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13777 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13777, 'zhTW', '看看他們...他們只在乎勝過彼此。', '看看他們...他們只在乎勝過彼此。', '看看他們…他們只在乎勝過彼此。', '看看他們…他們只在乎勝過彼此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13778 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13778, 'zhTW', '你知道的，索林姆跟這群殘忍貪婪的潑婦不一樣。他是個像神一般的尊貴生物。$B$B他替泰坦服務，擔任奧杜亞和造物者殿堂的守護者。$B$B直到他的妻子希芙被他的哥哥卑鄙地殺害。', '你知道的，索林姆跟這群殘忍貪婪的潑婦不一樣。他是個像神一般的尊貴生物。$B$B他替泰坦服務，擔任奧杜亞和造物者殿堂的守護者。$B$B直到他的妻子希芙被他的哥哥卑鄙地殺害。', '你知道，索林姆不像這些鷹身人。他是個像神一般的尊貴生物。\n\n他替泰坦服務，擔任奧杜亞和造物者殿堂的守護者。\n\n直到他的妻子希芙被他的哥哥卑鄙地殺害。', '你知道，索林姆不像這些鷹身人。他是個像神一般的尊貴生物。$B$B他替泰坦服務，擔任奧杜亞和造物者殿堂的守護者。$B$B直到他的妻子希芙被他的哥哥卑鄙地殺害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13779 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13779, 'zhTW', '索林姆失去了控制。他猛烈地攻擊他最堅強的盟友，冰霜巨人。$B$B這也是為什麼那天，這塊土地被海迪尼爾與霍迪爾之子間的戰爭徹底撕裂...也因此索林姆將自己放逐到風暴神殿。', '索林姆失去了控制。他猛烈地攻擊他最堅強的盟友，冰霜巨人。$B$B這也是為什麼那天，這塊土地被海迪尼爾與霍迪爾之子間的戰爭徹底撕裂...也因此索林姆將自己放逐到風暴神殿。', '索林姆失去了控制。他猛烈地攻擊他最堅強的盟友，冰霜巨人。\n\n這也是為什麼那天，這塊土地被海迪尼爾與霍迪爾之子間的戰爭徹底撕裂…也因此索林姆將自己放逐到風暴神殿。', '索林姆失去了控制。他猛烈地攻擊他最堅強的盟友，冰霜巨人。$B$B這也是為什麼那天，這塊土地被海迪尼爾與霍迪爾之子間的戰爭徹底撕裂…也因此索林姆將自己放逐到風暴神殿。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13780 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13780, 'zhTW', '為什麼我要在意那些母狼和冰霜巨人每天殺得你死我活?$B$B不，不...我要索林姆不再恍惚度日，召集他的所有盟友重新奪回奧杜亞。$B$B如果他失敗了，這個世界將會就此分裂!$B$B當然，我也會適當地獎勵你。', '為什麼我要在意那些母狼和冰霜巨人每天殺得你死我活?$B$B不，不...我要索林姆不再恍惚度日，召集他的所有盟友重新奪回奧杜亞。$B$B如果他失敗了，這個世界將會就此分裂!$B$B當然，我也會適當地獎勵你。', '為什麼我要在意那些母狼和冰霜巨人每天殺得你死我活?\n\n不，不…我要索林姆不再恍惚度日，召集他的所有盟友重新奪回奧杜亞。\n\n如果他失敗了，這個世界將會就此分裂!\n\n當然，我也會適當地獎勵你。', '為什麼我要在意那些母狼和冰霜巨人每天殺得你死我活?$B$B不，不…我要索林姆不再恍惚度日，召集他的所有盟友重新奪回奧杜亞。$B$B如果他失敗了，這個世界將會就此分裂!$B$B當然，我也會適當地獎勵你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13782 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13782, 'zhTW', '讓我留在我的恥辱中，$r。', '讓我留在我的恥辱中，$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13783 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13783, 'zhTW', '人 -- 沒辦法不靠著它們活下去，沒辦法離開它們。嗯，你可以...但那真的很無聊。', '人 -- 沒辦法不靠著它們活下去，沒辦法離開它們。嗯，你可以...但那真的很無聊。', '人 -- 沒辦法不靠著它們活下去，沒辦法離開它們。嗯，你可以…但那真的很無聊。', '人 -- 沒辦法不靠著它們活下去，沒辦法離開它們。嗯，你可以…但那真的很無聊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
