INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13797, 'zhTW', '我們發現那些在龍骨荒野的青銅龍殿的元龍。我們知道他們曾是我們的族類 - 留著我們遠古的血液。$B$B我向你致歉，$c。你或許有些迷惑。我是青銅龍軍團的潘農布理斯。我為了方便活動而使用目前的外型。使用凡人的外型比較容易在凡人之中生活和溝通。$B$B有什麼我能幫忙的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13798 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13798, 'zhTW', '你好，$n!有什麼我能幫忙的嗎?', '你好，$n!有什麼我能幫忙的嗎?', '哈羅, $n! 今天我能為你做什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
