INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13801, 'zhTW', '有一瞬間我還以為你是我摯愛的希芙...那樣一綹綹的秀髮...但卻不是!這是不可能的...希芙已經死了!$B$B我的...我的哥哥...殺死了她!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13802 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13802, 'zhTW', '奧杜亞...我曾立誓要保護奧杜亞。$B$B立誓要保護造物者殿堂。$B$B立誓要保護冰霜種族之間的盟約。$B$B但我失敗了!我任由我的兄長設計陷害我。我任由他設計我和我們盟友反目成仇。他設計我讓我把希芙的死怪罪在最親愛的朋友，安格林，冰霜巨人之王。$B$B等我發現我做了什麼之後...我...我任由自己沈浸在絕望之中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13803 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13803, 'zhTW', '你是誰，小傢伙?來跟偉大的索林姆講這些話...$B$B我應該要...碾碎你!$B$B但是，你將我從迷惘中喚醒。你在此出現就是個徵兆!$B$B我把你誤認為希芙並不是個意外。她會怎麼想我?我一定要開始準備戰鬥。$B$B我一定要替她復仇，並且從我兄長的瘋狂中解放泰坦的聖地!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13804 AND `Locale` = 'zhTW';
