INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13853, 'zhTW', '援軍終於來了!監獄守衛無法繼續對抗這場入侵太久!你要接替我的手下，並且儘可能地擋住他們。防禦系統中還有一些能量可以使用。如果狀況太惡劣的話，可以使用監獄周圍的啟動水晶來發出一次釋能。', '援軍終於來了!監獄守衛無法繼續對抗這場入侵太久!你要接替我的手下，並且儘可能地擋住他們。防禦系統中還有一些能量可以使用。如果狀況太惡劣的話，可以使用監獄周圍的啟動水晶來發出一次釋能。', '援軍終於來了!監獄守衛無法繼續對抗這場入侵太久!你要接替我的手下，並且儘可能地擋住他們。防禦系統中還有一些能量可以使用。如果狀況太惡劣的話，可以使用監獄周圍的啟動水晶來發出一次釋能。', '援軍終於來了!監獄守衛無法繼續對抗這場入侵太久!你要接替我的手下，並且儘可能地擋住他們。防禦系統中還有一些能量可以使用。如果狀況太惡劣的話，可以使用監獄周圍的啟動水晶來發出一次釋能。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
