INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13854, 'zhTW', '你整個隊伍都準備好要繼續了嗎?我會用啟動水晶發出一次釋能，好掩護守衛的撤退。', '你整個隊伍都準備好要繼續了嗎?我會用啟動水晶發出一次釋能，好掩護守衛的撤退。', '你整個隊伍都準備好要繼續了嗎?我會用啟動水晶發出一次釋能，好掩護守衛的撤退。', '你整個隊伍都準備好要繼續了嗎?我會用啟動水晶發出一次釋能，好掩護守衛的撤退。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
