INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13856, 'zhTW', '我今天為銀白十字軍所做的事情只不過是完成我應盡的義務。一個報答。大領主將我從巫妖王的掌握中釋放出來，給了我們救贖之道。但要知道我們的行事方法有很大的…不同。我和黯刃騎士會協助銀白十字軍在寒冰皇冠設立據點，然後我們就會離開。我們的報答完成了。$B$B另一個不同的使命在等著我們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
