INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13857, 'zhTW', '毫無疑問那些十字軍是巨大不安的來源，$g兄弟:姊妹;。但有犧牲是沒有痛苦嗎?我們當時都在聖光之願禮拜堂。你親眼目睹許多偉大的犧牲。我們在此是要償還大領主的恩情。報答他的犧牲。$B$B一旦銀白十字軍在寒冰皇冠的高牆內建立了他們的堡壘，我們就會離開。另一個不同的使命在等著我們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
