INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14046, 'zhTW', '空中戰鬥正在熱烈進行，$n。我們和部落都派出了轟炸機前往轟炸地和逝望山谷。你願意加入嗎?', '空中戰鬥正在熱烈進行，$n。我們和部落都派出了轟炸機前往轟炸地和逝望山谷。你願意加入嗎?', '空中戰鬥正在熱烈進行，$n。我們和部落都派出了轟炸機前往轟炸地和逝望山谷。你願意加入嗎?', '空中戰鬥正在熱烈進行，$n。我們和部落都派出了轟炸機前往轟炸地和逝望山谷。你願意加入嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
