INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14051, 'zhTW', '元素與我們同在，$N。有著他們的幫助，我們可以全力阻止瓦里瑪薩斯和普崔司!為了部落!', '元素與我們同在，$N。有著他們的幫助，我們可以全力阻止瓦里瑪薩斯和普崔司!為了部落!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
