INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14052, 'zhTW', '喔天啊!小聲一點，$N!什麼?你想害我們被殺死嗎?!$B$B我當然知道你是誰!聯盟之中誰沒聽過你的名字，$N?!$B$B說說看，你覺得我的彈跳機器人怎麼樣?她是根據機械地精的設計而做。光滑而符合空氣動力學!', '喔天啊!小聲一點，$N!什麼?你想害我們被殺死嗎?!$B$B我當然知道你是誰!聯盟之中誰沒聽過你的名字，$N?!$B$B說說看，你覺得我的彈跳機器人怎麼樣?她是根據機械地精的設計而做。光滑而符合空氣動力學!', '喔天啊!小聲一點，$N!什麼?你想害我們被殺死嗎?!\n\n我當然知道你是誰!聯盟之中誰沒聽過你的名字，$N?!\n\n說說看，你覺得我的彈跳機器人怎麼樣?她是根據機械地精的設計而做。光滑而符合空氣動力學!', '喔天啊!小聲一點，$N!什麼?你想害我們被殺死嗎?!$B$B我當然知道你是誰!聯盟之中誰沒聽過你的名字，$N?!$B$B說說看，你覺得我的彈跳機器人怎麼樣?她是根據機械地精的設計而做。光滑而符合空氣動力學!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14053 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14053, 'zhTW', '哇，哇，哇!小聲點，$N。小聲點!$B$B<轟擊四處張望著。>$B$B我可不想被那些冰霜維酷人注意到我們，懂嗎?$B$B你覺得我的彈跳機器人怎麼樣?我跟根據機械地精的設計而制。很光滑，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14055 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14055, 'zhTW', '我們眼前的道路可不輕鬆。如果你自認夠強悍，那就四處看看直到我的其中一個小隊準備前往依米海姆。他們用得上任何幫手。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
