INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14061, 'zhTW', '你長得可真醜!倒不是說你不懂得戰鬥啦。$B$B我們其中一箇中隊已經整裝完成，即將出發 - 你這傢伙快去給我排隊準備!', '你長得可真醜!倒不是說你不懂得戰鬥啦。$b$b我們其中一箇中隊已經整裝完成，即將出發 - 你這傢伙快去給我排隊準備!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
