INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14062, 'zhTW', '競技場積分賽將在$6318d後開始。$B$B鬥士們忙著磨練他們的技能，並且取得他們最好的裝備。你準備好了嗎?', '競技場積分賽將在$6318d後開始。$B$B鬥士們忙著磨練他們的技能，並且取得他們最好的裝備。你準備好了嗎?', '競技場積分賽將在$6318d後開始。\n\n鬥士們忙著磨練他們的技能，並且取得他們最好的裝備。你準備好了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
