INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14066, 'zhTW', '這個傳送門通往時光之穴，在遙遠的塔納利斯地底深處。$B$B但在你變得更強之前，我必須請你別前去該地。', '這個傳送門通往時光之穴，在遙遠的塔納利斯地底深處。$B$B但在你變得更強之前，我必須請你別前去該地。', '這個傳送門通往時光之穴，在遙遠的塔納利斯地底深處。\n\n但在你變得更強之前，我必須請你別前去該地。', '這個傳送門通往時光之穴，在遙遠的塔納利斯地底深處。$B$B但在你變得更強之前，我必須請你別前去該地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
