INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14067, 'zhTW', '我可以從那些炸彈和火箭上聞到火藥味!你想去外頭找點樂子嗎?', '我可以從那些炸彈和火箭上聞到火藥味!你想去外頭找點樂子嗎?', '我可以從那些炸彈和火箭上聞到火藥味!你想去外頭找點樂子嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14068 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14068, 'zhTW', '那個聲音在跟我說話。', NULL, '那個聲音在跟我說話。', NULL, '那個聲音在跟我說話。', NULL, '那個聲音在跟我說話。', NULL, '薩鋼…有某種東西在裡頭！', NULL, '那裡有某種東西。就在岩石和土地裡頭！', NULL, '我要離開這裡！你能救我出去嗎?', NULL, '你聽見它在你心中說話嗎?', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14069 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14069, 'zhTW', '我還在準備中。還需要一陣子才能出發。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14070 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14070, 'zhTW', '我們差不多要走了。再給我們一點時間完成準備。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14071 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14071, 'zhTW', '我的手下已經準備好了。去嚐點維酷人的鮮血吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14072 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14072, 'zhTW', '在我的旅途中，我學會了幽光披風的圖樣。$B$B這是一件可交易的史詩級施法系披風，提供耐力、法術能量、智力與法力回覆。我在尋找一個值得傳授圖樣的人。$B$B完成北裂境所有一般地城和達成「北裂境地城大師」成就，就有資格學會幽光披風的圖樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14074 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14074, 'zhTW', '我曾冒險進入黑暗之地，學會了亡寒披風的裁縫圖樣。$B$B這件可交易的史詩級施法系披風提供法術能力、加速和致命一擊等級。我在尋找值得傳授這圖樣的人。$B$B完成北裂境的大多數任務並達成「北裂境博學大師」的成就，就有資格學習亡寒披風的圖樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14076 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14076, 'zhTW', '既然你是個有點才能的裁縫，我可以告訴你我知道一些獨特的圖樣。我知道幽光披風與死寒披風的圖樣。', '既然你是個有點才能的裁縫，我可以告訴你我知道一些獨特的圖樣。我知道幽光披風與死寒披風的圖樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14077 AND `Locale` = 'zhTW';
