INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14119, 'zhTW', '我是札倫陶，見證者。', NULL, '我是札倫陶，見證者。', NULL, '我是札倫陶，見證者。', NULL, '我是札倫陶，見證者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14120 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14120, 'zhTW', '早在燃燒軍團與大崩裂之前，當這個世界依舊年輕，世事未逢劇變時，我曾是我族首批牛頭人德魯伊的一份子，塞納留斯尊師的最後一代弟子。$B$B當我的族人在追尋更大更強的獵物時，我追尋著故事與傳說。在這樣的飢渴與對知識的渴望驅使下讓我走向了德魯伊之道。有一段時間，這些渴望在我學習如何與樹木、岩石還有野獸交談時獲得滿足，我聆聽他們的故事。$B$B但是當塞納留斯不再行走於我們之間的時候，我的族人也開始忘記他所教導的事物。然而我無法忘卻，我依舊渴望能從這個世界學習到更多事物。$B$B於是我揮別同族，踏上前往未知之地的旅程。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14121 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14121, 'zhTW', '我在我剩餘的自然壽命中繼續搜尋知識，比起我的任何一位族人，我看過更多的奇景也遭遇過更多奇怪與神秘的種族。我在遠古的卡林多四處旅行，直到我走遍諸地，看遍諸事。$B$B然而…我還想要知道更多的事情，但我感覺到我最終的旅程即將到來，我為了那些我永遠也無法知道的事情而落淚。$B$B當我死去，我的生命終結，他們找上了我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14122 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14122, 'zhTW', '青銅龍軍團。他們把我從死亡的邊緣給叼回來，將我帶到他們的主人，諾茲多姆的面前。他說他們一直觀察我，希望我繼續我的追尋。他賦予我觀察者的永生，成為他的使者，肩負起見證艾澤拉斯歷史的使命。$B$B我是『見證者』札倫陶，我的職責就是要見證艾澤拉斯的真實歷史，以防它被遺忘。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14123 AND `Locale` = 'zhTW';
