INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14137, 'zhTW', '我們在這裡已經損失了不少好人。我開始懷疑這個地方是不是值得我們的注意。', '我們在這裡已經損失了不少好人。我開始懷疑這個地方是不是值得我們的注意。', '我們在這裡已經損失了不少好人。我開始懷疑這個地方是不是值得我們的注意。.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
