INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14174, 'zhTW', '你總是可以在銘文訓練師附近發現這種遠古典籍。', '你總是可以在銘文訓練師附近發現這種遠古典籍。', '你總是可以在銘文訓練師附近發現這種遠古典籍。', '製造強化法術與技能雕紋的必需品，力量詞典對每個人來說都是無價之寶。你總是可以在銘文訓練師附近發現這種遠古典籍。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
