INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14213, 'zhTW', '閃爍的大本魔法書可以幫助製造法術與技能的雕紋。你可以在銘文學訓練師附近找到它，就在鏈金房。', '閃爍的大本魔法書可以幫助製造法術與技能的雕紋。你可以在銘文學訓練師附近找到它，就在鏈金房。', '閃爍的大本魔法書可以幫助製造法術與技能的雕紋。你可以在銘文學訓練師附近找到它，就在鏈金房。', '閃爍的大本魔法書可以幫助製造法術與技能的雕紋。你可以在銘文學訓練師附近找到它，就在鍊金房。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14215 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14215, 'zhTW', '快一點，$r。我又累又倦，沒時間聽笑話。', '快一點，$r。我又累又倦，沒時間聽笑話。', '快一點，$r。我又累又倦，沒時間聽笑話。', '快一點，$r。我又累又倦，沒時間聽笑話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
