DELETE FROM `npc_text_locale` WHERE `ID` = 14221 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14221, 'zhTW', '為了部落!你是來協助部落戰鬥的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14227 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14227, 'zhTW', '喔，貴族花園。看到其他人拋下尊貴的身份在那邊尋找彩蛋可真精彩。不過，他們確實有一種有趣的魔法光環……', '喔，貴族花園。看到其他人拋下尊貴的身份在那邊尋找彩蛋可真精彩。不過，他們確實有一種有趣的魔法光環……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14228 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14228, 'zhTW', '又到了貴族花園的時候啦!感謝聖光讓這個世界重生。', '又到了貴族花園的時候啦!感謝聖光讓這個世界重生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14229 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14229, 'zhTW', '糖果!這就是我說的，我真希望我不需要四處奔走找到它!', '糖果!這就是我說的，我真希望我不需要四處奔走找到它!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14230 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14230, 'zhTW', 'MISSING TEXT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14231 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14231, 'zhTW', '嘿，就是有人會想要跑去爛泥裡找彩蛋，我是不評論這種事啦。反正我還可以靠這些顏料賺上一筆，我今年還在雞隻上投資了一筆。', '嘿，就是有人會想要跑去爛泥裡找彩蛋，我是不評論這種事啦。反正我還可以靠這些顏料賺上一筆，我今年還在雞隻上投資了一筆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14232 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14232, 'zhTW', '貴族花園節!我已經找到了一堆蛋。狩獵的好天氣，對吧?', '貴族花園節!我已經找到了一堆蛋。狩獵的好天氣，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14233 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14233, 'zhTW', '貴族花園是艾澤拉斯的德魯伊慶祝生命重生的日子。蛋是繁殖的象徵，你不覺得這是個很棒方法讓大家體會節日的精神嗎?', '貴族花園是艾澤拉斯的德魯伊慶祝生命重生的日子。蛋是繁殖的象徵，你不覺得這是個很棒方法讓大家體會節日的精神嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14234 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14234, 'zhTW', '我們在貴族花園的時候慶祝春天。肯定生命的價值啊之類的。', '我們在貴族花園的時候慶祝春天。肯定生命的價值啊之類的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14235 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14235, 'zhTW', '現在是我們對生命的誕生獻上敬意的日子，蛋則是象徵著春天與重生。希望你能好好享受春天。', '現在是我們對生命的誕生獻上敬意的日子，蛋則是象徵著春天與重生。希望你能好好享受春天。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14236 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14236, 'zhTW', '是呀，老兄，這是生命與春天的喜悅時刻。你收集到那些蛋了沒?', '是呀，老兄，這是生命與春天的喜悅時刻。你收集到那些蛋了沒?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14237 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14237, 'zhTW', '整個節日都是荒謬而愚蠢。彩蛋與「生命的肯定」，呿。', '整個節日都是荒謬而愚蠢。彩蛋與「生命的肯定」，呿。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14238 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14238, 'zhTW', '你好哇，朋友!你來替艾澤拉斯之子效力嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14239 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14239, 'zhTW', '歡迎，朋友。希望，你能好好享受貴族花園節?何不跟我們同樂?', '歡迎，朋友。希望，你能好好享受貴族花園節?何不跟我們同樂?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14240 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14240, 'zhTW', '你好，$c。$B$B當聯盟控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。$B$B戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊!', '你好，$c。$B$B當聯盟控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。$B$B戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊!', '你好，$c。\n\n當聯盟控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。\n\n戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊!', '你好，$c。$B$B當聯盟控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。$B$B戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14241 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14241, 'zhTW', '你好，$c。$B$B當部落控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。$B$B戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊。', '你好，$c。$B$B當部落控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。$B$B戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊。', '你好，$c。\n\n當部落控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。\n\n戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14245 AND `Locale` = 'zhTW';
