INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14332, 'zhTW', '凡人們，我很感激你拯救我脫離此地的可怕腐化。雖然我還尚未完全恢復，但我能幫助你對抗尤格薩倫。$B$B我能讓你和你的朋友獲得自然韌性，提高你的傷害，以及法術與各種效應的治療效果。此外，我能召喚理智之井，讓你能在與現實的連結衰弱時回覆你的理智。', '凡人們，我很感激你拯救我脫離此地的可怕腐化。雖然我還尚未完全恢復，但我能幫助你對抗尤格薩倫。$B$B我能讓你和你的朋友獲得自然韌性，提高你的傷害，以及法術與各種效應的治療效果。此外，我能召喚理智之井，讓你能在與現實的連結衰弱時回覆你的理智。', '凡人們，我很感激你拯救我脫離此地的可怕腐化。雖然我還尚未完全恢復，但我能幫助你對抗尤格薩倫。\n\n我能讓你和你的朋友獲得自然韌性，提高你的傷害，以及法術與各種效應的治療效果。此外，我能召喚理智之井，讓你能在與現實的連結衰弱時回覆你的理智。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14333 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14333, 'zhTW', '凡人們，我很感激你拯救我脫離此地的可怕腐化。雖然我還尚未完全恢復，但我能幫助你對抗尤格薩倫。$B$B我能讓你和你的朋友獲得風暴烈怒，提高你們的傷害與生命力上限。要是你遭遇到無法摧毀的巨大邪惡時，我可以引導我的力量灌注在最終的泰坦風暴中，它甚至能摧毀不朽者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14334 AND `Locale` = 'zhTW';
