INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14358, 'zhTW', NULL, '快，$c!沒有多餘的時間可以浪費!$b$b我們不可以失去碎木!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14359 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14359, 'zhTW', '榮耀歸於暴風城與烏瑞恩王!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14362 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14362, 'zhTW', '噢，我的天，我沒想過我有機會親眼看見奧杜亞。布萊恩要我資助這個遠征隊的時候，我怎麼會拒絕呢?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14363 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14363, 'zhTW', '我都沒想過我們居然能逃出那片蒸汽叢林!現在我可是這次遠征隊的首席工程師了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14364 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14364, 'zhTW', '這些寶貝看起來雖然很像廢鐵，但他們可以猛衝敵人，把敵人給撞飛。前方的衝角裝載了超驗電電容器，讓它可以釋放電衝波。$B$B連炮塔都用對空火箭強化過，讓它們絕對比那些破爛的石毀車更厲害。', '這些寶貝看起來雖然很像廢鐵，但他們可以猛衝敵人，把敵人給撞飛。前方的衝角裝載了超驗電電容器，讓它可以釋放電衝波。$B$B連炮塔都用對空火箭強化過，讓它們絕對比那些破爛的石毀車更厲害。', '這些寶貝看起來雖然很像廢鐵，但他們可以猛衝敵人，把敵人給撞飛。前方的衝角裝載了超驗電電容器，讓它可以釋放電衝波。\n\n連炮塔都用對空火箭強化過，讓它們絕對比那些破爛的石毀車更厲害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14365 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14365, 'zhTW', '我所在此累積的或許是整個外域最偉大的知識寶庫。就算是銀月城的大圖書館也會相形失色。$B$B請來...看一看，讀一讀，隨意瀏覽。你會發現每樣東西都井然有序，編碼清楚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14367 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14367, 'zhTW', '我們真的是很幸運，能找到夠多的零件讓這些寶貝重新動起來!$B我能幫你什麼忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14368 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14368, 'zhTW', '這些寶貝投出獨一無二的火焰。我們甚至還可以加上第二具火炮，勾爪還有手動的燃油注射系統。你要是能從那些機械地精身上取得液態黃鐵，你可以用它來投擲高密度炸藥，或是瞬間強化你的移動速度。$B$B讓那些探險者協會的討厭鬼瞧瞧它的厲害!', '這些寶貝投出獨一無二的火焰。我們甚至還可以加上第二具火炮，勾爪還有手動的燃油注射系統。你要是能從那些機械地精身上取得液態黃鐵，你可以用它來投擲高密度炸藥，或是瞬間強化你的移動速度。$B$B讓那些探險者協會的討厭鬼瞧瞧它的厲害!', '這些寶貝投出獨一無二的火焰。我們甚至還可以加上第二具火炮，勾爪還有手動的燃油注射系統。你要是能從那些機械地精身上取得液態黃鐵，你可以用它來投擲高密度炸藥，或是瞬間強化你的移動速度。\n\n讓那些探險者協會的討厭鬼瞧瞧它的厲害!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14369 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14369, 'zhTW', '幸好你們出現了!鐵矮人把我們逼退到這個位置，我們快要守不住這道防線了。$B$B更糟的是，他們開始強化魔法防禦。如果我們不盡快攻擊，他們就可以在一瞬間就把我們毀滅殆盡!$B$B我們從先前的聯盟與部落遠征隊手中重新修復了一些攻城器械、石毀車和摩托車。但我們所有的駕駛員都在上一次突襲中喪生。$B$B你們必須要駕駛這些載具，並且攻破奧杜亞的大門!$B$B拜託，$n!你是我們最後的希望!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14372 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14372, 'zhTW', '有何貴幹，老大?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
