INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14391, 'zhTW', '雙天賦專精讓你可以保留兩套可用的天賦模組。你可以輕易地切換這兩套天賦，當你切換天賦模組時，你會同時切換第二套雕紋模組和第二套快捷列。你無法在戰鬥中切換，並會消耗你的可用資源。', '雙天賦專精讓你可以保留兩套可用的天賦模組。你可以輕易地切換這兩套天賦，當你切換天賦模組時，你會同時切換第二套雕紋模組和第二套快捷列。你無法在戰鬥中切換，並會消耗你的可用資源。', '雙天賦專精讓你可以保留兩套可用的天賦模組。你可以輕易地切換這兩套天賦，當你切換天賦模組時，你會同時切換第二套雕紋模組和第二套快捷列。你無法在戰鬥中切換，並會消耗你的可用資源。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14392 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14392, 'zhTW', '當我們以銀月城之名贏得聯賽，榮耀將盡歸於我們。', '當我們以銀月城之名贏得聯賽，榮耀將盡歸於我們。', '當我們以銀月城之名贏得聯賽，榮耀將盡歸於我們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
