INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14396, 'zhTW', '麥格尼王期待我們贏得聯賽，讓他驕傲。我們絕不會失敗。', '麥格尼王期待我們贏得聯賽，讓他驕傲。我們絕不會失敗。', '麥格尼王期待我們贏得聯賽，讓他驕傲。我們絕不會失敗。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
