INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14476, 'zhTW', '銀白騎士以平衡與精確為信條，靈巧而熟練地交替攻擊與防禦。$B$B但是當他們想要拉開距離的時候，往往也會讓自己暴露在衝鋒的危險下。$B$B在他們來得及反應前，用衝鋒縮短距離，然後對他們使用破盾然後搭配更多的戳刺。', '銀白騎士以平衡與精確為信條，靈巧而熟練地交替攻擊與防禦。$B$B但是當他們想要拉開距離的時候，往往也會讓自己暴露在衝鋒的危險下。$B$B在他們來得及反應前，用衝鋒縮短距離，然後對他們使用破盾然後搭配更多的戳刺。', '銀白騎士以平衡與精確為信條，靈巧而熟練地交替攻擊與防禦。\n\n但是當他們想要拉開距離的時候，往往也會讓自己暴露在衝鋒的危險下。\n\n在他們來得及反應前，用衝鋒縮短距離，然後對他們使用破盾然後搭配更多的戳刺。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14487 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14487, 'zhTW', '歡迎來到我們屬於聖光的小禮拜堂。歡迎，請坐。享受這不受世界邪惡影響的短暫時光吧。', '歡迎來到我們屬於聖光的小禮拜堂。歡迎，請坐。享受這不受世界邪惡影響的短暫時光吧。', '歡迎來到我們屬於聖光的小禮拜堂。歡迎，請坐。享受這不受世界邪惡影響的短暫時光吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14488 AND `Locale` = 'zhTW';
