INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14496, 'zhTW', '啟動次要防禦系統將會讓環軌炮塔消滅所有未經授權的生命型態。$B$B你是未經授權的生命型態。請確認。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14497 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14497, 'zhTW', '允許安全系統手控。啟動次要防禦系統。$B$B備用系統關閉，次要系統可以經由集合場的獨立動力裝置獲得能量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14500 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14500, 'zhTW', '銀白聯賽在寒冰皇冠的北境展開，$c。如果你還不知道怎麼去那裡，我可以送你一程。$B$B我們越多人參加技擊大賽，我們對抗巫妖王的力量就會越強。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14505 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14505, 'zhTW', '歡迎，孩子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14506 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14506, 'zhTW', NULL, '我不該期待這些骯髒的食人妖會一直安靜下去。對於可以接受部落的人不該抱有任何的信任。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14507 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14507, 'zhTW', '鮮血與雷霆，$n!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14508 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14508, 'zhTW', '許多危機正等著我們，但我們絕不能忽略大自然，避免我們在需要它的時候拋棄我們。這是我們從過去的經驗中所學習到的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14509 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14509, 'zhTW', '跟自然唱反調是一種異論，就算自然所帶來的是毀滅的力量也是一樣。$B$B不過，想要摧毀黑海岸的力量不是自然之力。我絕不允許這片大地被撕裂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14510 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14510, 'zhTW', '你好嗎?我是葛瑞，一定是高爾博多叫你來的吧。\n\n如果你是來幫忙的，計畫很簡單。我做了一些誘餌機器人。我們讓這些小東西跳到魚人附近，然後啟動它們的倒數計時。它們會發出亮光和聲音來吸引魚人，幾秒鐘後便會爆炸和那些魚人一起昇天。\n\n如果我們送了夠多個進去，我們應該就可以再次進到船艙裡。希望這次的傷亡會少一點，但這跟你沒關係，你只要把那些小魚人炸飛就好了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14511 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14511, 'zhTW', NULL, '當元素盡力的在摧毀黑海岸時，我很努力的在保護剩下的野生動植物。$B$B我能夠信任你嗎，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14514 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14514, 'zhTW', '別隻是站在那，$r...$b$b你還有活要幹!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14517 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14517, 'zhTW', '靜下心來，小東西，你可以聽到這個古老大地所發出的聲音。它正因痛苦而悲鳴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14518 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14518, 'zhTW', '嗯..嗯。力量強大的施法材料讓如此年輕的人得到。你將以你的同盟之名殺死許多敵人。但切記...在偉大的迴圈中，誕生的力量與死亡是對等的。$B$B<安努慢慢地拿了一粒頭上不起眼的果實。他不急不徐地把手放在你的面前。>$B$B這粒果實的力量極為強大。$B$B...我必須道歉，我沒有想要自吹自擂的意思。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14520 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14520, 'zhTW', '讓我們試試把敵人冰在他們所站的地方，小$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14521 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14521, 'zhTW', '我們的兄弟迷失了自己。他燃燒著大地，他蒸發著海水，他吞噬了太多的空氣。$B$B幫助我們引導他回來，並讓他恢復平衡和協調。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14523 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14523, 'zhTW', '<*轟隆*轟隆*轟隆>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14524 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14524, 'zhTW', NULL, '我很感激你幫忙保護這裡的野生動植物。希望我們這樣做還不算太遲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14526 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14526, 'zhTW', NULL, '我希望能告訴你更多，但在此之前誰都不相信這種生物是存在的。遠在泰坦塑造了我們今天所見的艾澤拉斯之前，在我們所知的自然界生死輪迴之前，上古之神為了達成他們邪惡的目地統治了元素和腐化了的生物。$B$B這裡的安努告訴了我，說泰坦們最終擊敗了上古之神，又或者是把他們囚禁在地底深淵。上古之神真的會死嗎?我自己也希望我知道。但這全都是比史前學還要久遠的史前學，而我已經算存在很久了。$B$B我知道有些相信這些歷史的人膜拜著上古之神，這與祈禱世界的毀滅沒什麼兩樣。這些古神會讓人喪失理智!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14527 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14527, 'zhTW', '<小暴掠龍看著你，似乎在想你到底是不是牠媽媽。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14529 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14529, 'zhTW', '放棄挖掘?別開玩笑了!在我的專業生涯中，我從沒放棄過任何一個挖掘場，沒有故意放棄。或許有挖錯幾個點。對了，你是誰啊?我們在這幹麻?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14531 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14531, 'zhTW', '這個挖掘場受到了威脅，探險者協會要我們馬上把值錢的東西帶上後閃人。說的比做的簡單。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14532 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14532, 'zhTW', '魚人。嘿!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14534 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14534, 'zhTW', '巫妖王的殘酷統治讓北裂境的所有居民都飽受苦難，尤其是孩子們。如果你是休拉薩的神諭者或狂心部族的朋友，或許你願意花上一個禮拜照顧一位孤兒。', '巫妖王的殘酷統治讓北裂境的所有居民都飽受苦難，尤其是孩子們。如果你是休拉薩的神諭者或狂心部族的朋友，或許你願意花上一個禮拜照顧一位孤兒。', '巫妖王的殘酷統治讓北裂境的所有居民都飽受苦難，尤其是孩子們。如果你是休拉薩的神諭者或狂心部族的朋友，或許你願意花上一個禮拜照顧一位孤兒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14535 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14535, 'zhTW', '我們可以來點陳年卵黃嗎?', '我們可以來點陳年卵黃嗎?', '我們可以來點陳年卵黃嗎?', '諸神也會袋子不夠大，沒辦法裝完所有閃亮亮的東西嗎?', '我們可以來點陳年卵黃嗎?', NULL, '我們可以來點陳年卵黃嗎?', NULL, '也許我們長大後會變成$r。你也這樣認為嗎？', NULL, '你也是一個人，這是因為狗頭人也殺了你的父母嗎？', NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14536 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14536, 'zhTW', '你應該離那些海象人遠一點。他們可能會偷襲你。', '你應該離那些海象人遠一點。他們可能會偷襲你。', '你應該離那些海象人遠一點。他們可能會偷襲你。', '恰嘎帶你打獵。你要當個好餌。', '你應該離那些海象人遠一點。他們可能會偷襲你。', NULL, '你應該離那些海象人遠一點。他們可能會偷襲你。', NULL, '抓三隻雞做午餐，我打賭你一直也抓不到。', NULL, '恰噶拿走了大舌幼仔最喜歡的玩具， 它可以幫你入睡。', NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14537 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14537, 'zhTW', '我們收容的孤兒來自戰火肆虐的休拉薩盆地。你可以選擇照顧失去父母的小神諭者或狂心小獾狼怪。他們都會很高興能認識新朋友，但你只能照顧他們其中一邊。', '我們收容的孤兒來自戰火肆虐的休拉薩盆地。你可以選擇照顧失去父母的小神諭者或狂心小獾狼怪。他們都會很高興能認識新朋友，但你只能照顧他們其中一邊。', '我們收容的孤兒來自戰火肆虐的休拉薩盆地。你可以選擇照顧失去父母的小神諭者或狂心小獾狼怪。他們都會很高興能認識新朋友，但你只能照顧他們其中一邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14538 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14538, 'zhTW', NULL, '我們不能只是守護著樹，$r。部落是不會投降的。$B$B我們必須摧殘他們!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14541 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14541, 'zhTW', '我一直在大地自己裂開的時候幫助飛行管理員們集攏到處亂飛的角鷹獸。就算現在我們的鳥都還是容易受驚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14543 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14543, 'zhTW', '你感覺到了嗎?$B$B在亡者節的時候，靈魂的世界變得離我們更近。這也是為什麼我們要準備鮮花、蠟燭和供品，用來裝飾跟我們最親近死者的墳墓，儘管只有短短的時間，也要歡迎它們回來。$B$B來吧!跟我一起跳舞!讓我們一起榮耀死者，跟它們一起同樂，讓它們可以開懷吃喝和歡笑，讓它們知道依舊有人在愛著它們。', '你感覺到了嗎?$B$B在亡者節的時候，靈魂的世界變得離我們更近。這也是為什麼我們要準備鮮花、蠟燭和供品，用來裝飾跟我們最親近死者的墳墓，儘管只有短短的時間，也要歡迎它們回來。$B$B來吧!跟我一起跳舞!讓我們一起榮耀死者，跟它們一起同樂，讓它們可以開懷吃喝和歡笑，讓它們知道依舊有人在愛著它們。', '你感覺到了嗎?\n\n在亡者節的時候，靈魂的世界變得離我們更近。這也是為什麼我們要準備鮮花、蠟燭和供品，用來裝飾跟我們最親近死者的墳墓，儘管只有短短的時間，也要歡迎它們回來。\n\n來吧!跟我一起跳舞!讓我們一起榮耀死者，跟它們一起同樂，讓它們可以開懷吃喝和歡笑，讓它們知道依舊有人在愛著它們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14544 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14544, 'zhTW', '在亡者節的時候，人們聚集在墓園中慶祝，和親人的鬼魂一起同樂。$B$B你可以在各大主城的墓園發現慶典活動，你可以在那邊烹飪、跳舞、扮裝還有許許多多的活動。', '在亡者節的時候，人們聚集在墓園中慶祝，和親人的鬼魂一起同樂。$B$B你可以在各大主城的墓園發現慶典活動，你可以在那邊烹飪、跳舞、扮裝還有許許多多的活動。', '在亡者節的時候，人們聚集在墓園中慶祝，和親人的鬼魂一起同樂。\n\n你可以在各大主城的墓園發現慶典活動，你可以在那邊烹飪、跳舞、扮裝還有許許多多的活動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14545 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14545, 'zhTW', NULL, '我有責任把這些補給帶到十字路口。要不就幫我，要不就別煩我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14546 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14546, 'zhTW', NULL, '很好，$n，準備好了嗎?這不是件簡單的差事!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14547 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14547, 'zhTW', '依露恩指引我們，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14548 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14548, 'zhTW', '我們絕對一步都不會讓。如果他們攻擊黑海岸，我們將奮力對抗，讓他們瞭解這於直接攻擊達納蘇斯沒什麼兩樣!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14549 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14549, 'zhTW', NULL, '需要幫忙指路嗎?我對這個地方熟到不能再熟了。', NULL, 'It saddens me to see the furbolg all corrupted so readily. These used to be our friends.', NULL, 'This place is infested... we\'ll need to make our way out of here with the relics as quickly as possible.', NULL, 'I haven\'t seen any of the sleeping druids. They must have been taken from here already.', NULL, 'We should have seen this coming. The corruption has been spreading for quite some time.', NULL, 'If the furbolg could be this far gone, what does that say for the rest of Teldrassil?', NULL, 'There has to be a way to stop this corruption before it consumes us all.', NULL, 'Damn you, Fandral! What have you gotten us into with this cursed "World Tree?"');
DELETE FROM `npc_text_locale` WHERE `ID` = 14552 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14552, 'zhTW', '能再回來看看朋友與家人真好，歡慶並且分享古老的故事。', '能再回來看看朋友與家人真好，歡慶並且分享古老的故事。', '能再回來看看朋友與家人真好，歡慶並且分享古老的故事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14553 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14553, 'zhTW', '<哼氣>這就是懦夫的戰鬥方式，$r?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14554 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14554, 'zhTW', NULL, '野豬人一直都在掠奪我們營地外圍的食物和補給，但現在是直接襲擊我的的農田和農莊?不知什麼東西讓他們最近變得如此狂暴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14555 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14555, 'zhTW', '<野豬人用他閃亮的黑眼珠丁盯著你看。>', NULL, '<The quilboar wrinkles his nose at you and snorts.>', NULL, 'What now, $r? Do your worst.', NULL, 'We\'re warriors, $n. <Snort> Many and proud.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14556 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14556, 'zhTW', NULL, '哈羅!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14557 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14557, 'zhTW', '<熊怪聞了聞你後發出了咕嚕聲。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14560 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14560, 'zhTW', '我很肯定在你的一生中一定當過學生，$c。你從一位指導者身上學習，某種程度上你會尊敬他們，對吧?或許不是一個人，但最起碼，有人瞭解得比你更多，而願意教導你。如果沒有的話，你也可以運用你的想像力……$B$B如果你最後發現，你的導師並不如你所想得全知全能，或許你會想到一條更好的道路?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14561 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14561, 'zhTW', '這太糟糕了!我根本不應該坐在這裡，一點用都沒有，有這麼多事情等著去做!要是我的手臂沒有在北裂境受傷…待在這裡根本沒有意義!塔胡會替我好好包紮最後我會痊癒，在這段期間我們會在這裡幫忙。$B$B我們不在前線並不表示我們沒辦法幫忙。', '這太糟糕了!我根本不應該坐在這裡，一點用都沒有，有這麼多事情等著去做!要是我的手臂沒有在北裂境受傷…待在這裡根本沒有意義!塔胡會替我好好包紮最後我會痊癒，在這段期間我們會在這裡幫忙。$B$B我們不在前線並不表示我們沒辦法幫忙。', '這太糟糕了!我根本不應該坐在這裡，一點用都沒有，有這麼多事情等著去做!要是我的手臂沒有在北裂境受傷…待在這裡根本沒有意義!塔胡會替我好好包紮最後我會痊癒，在這段期間我們會在這裡幫忙。\n\n我們不在前線並不表示我們沒辦法幫忙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14562 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14562, 'zhTW', NULL, '另一個新面孔?很高興見到你，我是德黎菈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14563 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14563, 'zhTW', NULL, '我知道幽影谷的情況不太好，但回到這片森林就像是回到家一樣。$B$B永恆的寧靜，永恆的純潔。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14564 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14564, 'zhTW', '把裝備和食物從奧格瑪運到十字路口曾經是苦工們做的工作。現在...我每次都必須自己來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14565 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14565, 'zhTW', '嘿，$n!我兄弟巴爾苟跟我說你對騎科多獸很有一手。把車隊從前沿哨所護送到這裡幹得太漂亮了。$B$B格羅多姆有蠻多事情可以做的...但你的板機指可以有效地幫我把剩下的東西運到十字路口。$B$B準備好了就來見我吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14566 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14566, 'zhTW', '你準備好要這樣做了嗎，$n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14568 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14568, 'zhTW', '小心，$n!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14569 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14569, 'zhTW', 'MISSING TEXT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14571 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14571, 'zhTW', '你好啊，$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14572 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14572, 'zhTW', '森林的救星!如果沒有你，阿斯特蘭納和整個梣谷一定都會落入燃燒軍團之手。$B$B我希望你能有愉快的一天，$n!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14574 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14574, 'zhTW', '喂，老兄，你是怎麼找到我的?看來我必須選個更好的藏匿地點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14575 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14575, 'zhTW', '你的名字叫...$n?這不是個常見的熊怪名字。$B$B你不是從梣谷來的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14576 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14576, 'zhTW', '<歐塔·文的雙眼，因為被奴役而呆滯，在聽了你的建議後更加往這看來了。你感受到了達圖爾魔棒的力量開始流動和延伸去觸碰熊怪。>$B$B起來反抗?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14577 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14577, 'zhTW', '<當他起身向天空咆哮時，眼中燃燒著一道奇特的光芒。>$B$B沒錯，我們將會掘起!掘起對抗和摧毀那些獄卒!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14579 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14579, 'zhTW', '深呼吸，$c。雷首之巔的頂端空氣很稀薄，但不像下面有那麼多嗆人的灰塵。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14580 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14580, 'zhTW', '幫個忙吧，我的小隻朋友?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14584 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14584, 'zhTW', NULL, '拜託你，$c，別助長葛加爾的氣焰。我們該做的是觀察與回報，而不是造成騷動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14585 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14585, 'zhTW', '鬼祟，鬼祟，鬼祟。讓我告訴你與葛加爾有關的事:葛加爾從不鬼鬼祟祟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14590 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14590, 'zhTW', NULL, '嗨，老大。我相信你正在享受你的晉升吧?$B$B我們全都相信你最後一定可以取代那個又老又臭的加里維克斯，獲得貿易$g親王:女王;的稱號。不要說這是我說的!$B$B我們在有限的時間內要做很多事。希望你已經準備好了!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14591 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14591, 'zhTW', '喂，$r。最近有什麼好康的?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14593 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14593, 'zhTW', '這些猴子真他X的煩人啊!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14595 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14595, 'zhTW', '什麼?$n，你不是一個術士。$B$B像你這樣一個$c，我沒什麼可以教你的，$g先生:女士;。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14596 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14596, 'zhTW', '$n，很高興看到你在這。或許我可以教你一兩件事。$B$B你意下如何?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14597 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14597, 'zhTW', '我有點懷疑你會想從我這裡學到什麼東西，$n。我不確定你那幾根手指是否可以掌握火焰箭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14599 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14599, 'zhTW', '你能忍受這些猴子，$n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14600 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14600, 'zhTW', '啊哈，你來啦...我未來的元素大師!今天想要接受怎樣的訓練!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14601 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14601, 'zhTW', NULL, '你不需要成為一位牧師來繳納什一稅。你的金幣在這也是一樣受歡迎的，$g先生:女士;。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14603 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14603, 'zhTW', NULL, '$n，我很驚訝一個像你這樣的$c竟然可以看到我。我可是潛行在一根柱子上!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14604 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14604, 'zhTW', NULL, '當然，$n，我會訓練你。好好看住那些猴子們!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14605 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14605, 'zhTW', '自動戰士NX-01目前離線中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14612 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14612, 'zhTW', '<喝醉的工程師茫茫地向你眨了眨眼和招了招手。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14613 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14613, 'zhTW', '我快要聾了。那個綠色大笨鳥連閉嘴五秒鐘都不肯。我知道怎麼駕駛這個玩意兒，好嗎?我不是個笨蛋!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14614 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14614, 'zhTW', '要是我不在這裡，齊派克會讓我們直直撞進雷霆崖。智障。', '要是我不在這裡，齊派克會讓我們直直撞進雷霆崖。智障。', '要是我不在這裡，齊派克會讓我們直直撞進雷霆崖。智障。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14615 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14615, 'zhTW', '如果不在意塵土的話，這倒是趟相當平穩的旅程。', '如果不在意塵土的話，這倒是趟相當平穩的旅程。', '如果不在意塵土的話，這倒是趟相當平穩的旅程。', '如果不在意塵土的話，這倒是趟相當平穩的旅程。', '如果不在意塵土的話，這倒是趟相當平穩的旅程。', '如果不在意塵土的話，這倒是趟相當平穩的旅程。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14616 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14616, 'zhTW', '<工程師突然倒在地上睡著了。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14617 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14617, 'zhTW', '嗨。我正在休息。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14618 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14618, 'zhTW', '歡迎登上西風號，你將會在最舒適的情況下橫越貧瘠之地。坐下，好好享受你的飛行吧，孩子?沒有東西比乾燥而香甜的空氣混著機油的氣味更美好的了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14619 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14619, 'zhTW', '我是託威。工作就是好好地瞭望。所以我正在看。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14621 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14621, 'zhTW', '嗨，甜心。這裡的飛艇將會送你直達雷霆崖，而且不收費唷。既然有我們哥布林在這裡，誰還需要那些雙足翼龍，對吧?', '嗨，甜心。這裡的飛艇將會送你直達雷霆崖，而且不收費唷。既然有我們哥布林在這裡，誰還需要那些雙足翼龍，對吧?', '嗨，甜心。這裡的飛艇將會送你直達雷霆崖，而且不收費唷。既然有我們哥布林在這裡，誰還需要那些雙足翼龍，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14622 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14622, 'zhTW', '你相信嗎?他們終於開放這個地方讓我們開飛艇經過這兒!不再有禁飛區了，對吧?我們只有在試飛的時候墜毀過一條船。我真不知道他們在擔心什麼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14623 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14623, 'zhTW', '你看什麼看，$r?來打落水狗嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14624 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14624, 'zhTW', '<男爵舉起了他的手鍊。 >$B$B那就過來，$c。你信任我嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14625 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14625, 'zhTW', '所以呢?不是還有頭在等你去砍和寶藏等你去挖?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14627 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14627, 'zhTW', '嗨，$N。如果你需要烹飪訓練，你可就找對地方了。旅人豐年祭的時候我總是會收到很多新學生。', '嗨，$N。如果你需要烹飪訓練，你可就找對地方了。旅人豐年祭的時候我總是會收到很多新學生。', '嗨，$N。如果你需要烹飪訓練，你可就找對地方了。旅人豐年祭的時候我總是會收到很多新學生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14628 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14628, 'zhTW', '如果你對學習更多傳統旅人豐年祭料理有興趣的話，可以跟任何一位女侍談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14630 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14630, 'zhTW', '你來這裡跟我們一起慶祝旅人豐年祭嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14631 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14631, 'zhTW', NULL, '別跟我討價還價，$r。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14633 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14633, 'zhTW', '歡迎!你是來加入我們的旅人豐年祭盛宴嗎?來來來，在豐年祭餐席旁邊找個位子坐下。$B$B嚐嚐每樣東西!我肯定你一定會找到某些你喜歡的食物。', '歡迎!你是來加入我們的旅人豐年祭盛宴嗎?來來來，在豐年祭餐席旁邊找個位子坐下。$B$B嚐嚐每樣東西!我肯定你一定會找到某些你喜歡的食物。', '歡迎!你是來加入我們的旅人豐年祭盛宴嗎?來來來，在豐年祭餐席旁邊找個位子坐下。\n\n嚐嚐每樣東西!我肯定你一定會找到某些你喜歡的食物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14634 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14634, 'zhTW', '歡迎!你是來加入我們的旅人豐年祭盛宴嗎?來來來，在豐年祭餐席旁邊找個位子坐下。$B$B嚐嚐每樣東西!我肯定你一定會找到某些你喜歡的食物。', '歡迎!你是來加入我們的旅人豐年祭盛宴嗎?來來來，在豐年祭餐席旁邊找個位子坐下。$B$B嚐嚐每樣東西!我肯定你一定會找到某些你喜歡的食物。', '歡迎!你是來加入我們的旅人豐年祭盛宴嗎?來來來，在豐年祭餐席旁邊找個位子坐下。\n\n嚐嚐每樣東西!我肯定你一定會找到某些你喜歡的食物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14635 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14635, 'zhTW', '「旅人豐年祭。」哈。我可以瞭解那些牛頭人急著想表現他們對部落大酋長的感激和情誼，但被遺忘者呢?$B$B我可以想見他們早就拋棄這些多愁善感的傳統。', '「旅人豐年祭。」哈。我可以瞭解那些牛頭人急著想表現他們對部落大酋長的感激和情誼，但被遺忘者呢?$B$B我可以想見他們早就拋棄這些多愁善感的傳統。', '「旅人豐年祭。」哈。我可以瞭解那些牛頭人急著想表現他們對部落大酋長的感激和情誼，但被遺忘者呢?\n\n我可以想見他們早就拋棄這些多愁善感的傳統。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14636 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14636, 'zhTW', 'I am told Pilgrim\'s Bounty is a time to reflect upon one\'s good fortune and share with all around you.$B$BWe are lucky to have found this world and its bold inhabitants; it is only fitting that we lend our knowledge and strength to these new-found allies.', '我聽說旅人豐年祭是把你自己的好運分享給周遭眾人的節日。$B$B我們很幸運能找到這個世界以及其中的勇敢居民，將我們的智慧與知識與他們分享應該相當適合。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14637 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14637, 'zhTW', 'Humans can\'t brew their way out of a tattered linen pouch, but there sure know how to cook. Pilgrim\'s Bounty? I\'m all for it!', '人類釀的酒跟亞麻袋泡水的味道差不多，但他們的確很懂料理。旅人豐年祭?我超喜歡的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14638 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14638, 'zhTW', 'The logistics involved in the optimal celebration of Pilgrim\'s Bounty are quite staggering... so many raw materials, so much labor, thousands upon thousands of crates of finished product shipped here and there and everywhere for countless Bountiful Tables.$B$BHonestly, I\'m quite impressed! And hungry... I can smell pumpkin pie. Can you smell that pie?', '一個理想的旅人豐年祭慶典所需要物資流通非常的驚人...需要這麼多的稀有材料，這麼多人力，成千上萬的箱子裝著成品被運到這裡，而到處都是豐年祭餐席。$B$B老實說，我很驚訝!而且很餓...我可以聞到南瓜派的香味。你聞到那些派了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14639 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14639, 'zhTW', '「旅人豐年祭?」感覺更像是「傻瓜愚行!」$B$B成千上百的裝滿食物的貨艙就這樣免費贈送出去…免費!腦袋一定是燒壞了!$B$B不過，我想我應該把我的家禽投資基金移一些到火雞上…我不敢相信雞的價格竟然會跌到谷底。還有那些貴族花園的蛋又從哪來的?!', '「旅人豐年祭?」感覺更像是「傻瓜愚行!」$B$B成千上百的裝滿食物的貨艙就這樣免費贈送出去…免費!腦袋一定是燒壞了!$B$B不過，我想我應該把我的家禽投資基金移一些到火雞上…我不敢相信雞的價格竟然會跌到谷底。還有那些貴族花園的蛋又從哪來的?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14640 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14640, 'zhTW', '旅人豐年祭是把一個人的好運分享給周遭眾人的時刻。$B$B我們希望所有高貴的盟友能都加入我們的盛宴與慶典。', '旅人豐年祭是把一個人的好運分享給周遭眾人的時刻。$B$B我們希望所有高貴的盟友能都加入我們的盛宴與慶典。', '旅人豐年祭是把一個人的好運分享給周遭眾人的時刻。\n\n我們希望所有高貴的盟友能都加入我們的盛宴與慶典。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14641 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14641, 'zhTW', '如此明顯的對比，這個節日，完全就是標準的人類行為。誰會想到一個無情貪婪的種族會舉行一個付出與分享的慶典?$B$B看了真讓人高興。達納蘇斯將會全力支援並且鼓勵這個活動。', '如此明顯的對比，這個節日，完全就是標準的人類行為。誰會想到一個無情貪婪的種族會舉行一個付出與分享的慶典?$B$B看了真讓人高興。達納蘇斯將會全力支援並且鼓勵這個活動。', '如此明顯的對比，這個節日，完全就是標準的人類行為。誰會想到一個無情貪婪的種族會舉行一個付出與分享的慶典?\n\n看了真讓人高興。達納蘇斯將會全力支援並且鼓勵這個活動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14642 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14642, 'zhTW', 'The orcs and tauren are fortunate to have found one another, for each people\'s strengths compliment the other\'s.  We are glad to join them in this celebration.$B$BEven the Forsaken partake, though to what end I am not certain...', '獸人跟牛頭人很幸運能找到彼此，因為我們對彼此種族的力量充滿欽佩與崇敬。我們很高興跟他們一起能加入慶典。$B$B就連被遺忘者也參加了，雖然我不在乎他們是為了什麼目的...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14643 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14643, 'zhTW', 'Pilgrim\'s Bounty is a time to reflect upon one\'s good fortune and share with all around you.$B$BIn Mulgore and the Horde, we have found both a home and friends to enjoy its many fruits with.$B$BIt is our hope that every one of our allies will be able to join us in feasting and celebration.', '旅人豐年祭是把一個人的好運分享給周遭眾人的時刻。$B$B在莫高雷與部落，我們找到了家園與朋友，來享受眾多的果實。$B$B我們誠心的希望我們所有的盟友都來加入我們的饗宴與慶典。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14644 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14644, 'zhTW', 'Dem tauren, dey be KNOWIN\' how ta cook. Have ya SEEN all de food dey be servin\'?$B$BI\'m gonna eat \'til I die... an\' den come back from de grave ta be eatin\' some more!', '那些牛頭人，他們可瞭解怎麼煮東西。你看到他們端出來的食物嗎?$B$B我要狂吃到掛掉...等回到墓地再吃更多!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14645 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14645, 'zhTW', 'MISSING TEXT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14647 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14647, 'zhTW', '豐年祭餐席放著五種旅人豐年祭食物，每個位子前面各有一樣。$B$B當你坐在其中一個位子時，那種食物你愛吃多少吃多少，你也可以把食物傳遞給其他的位子。儘量吃並且和朋友分享!$B$B如果你其中一種食物吃得夠多，你將可以獲得該食物的一種獨特增益效果。$B$B此外，如果你每一種食物都吃得夠多，你將可以獲得有福同享的效果!', '豐年祭餐席放著五種旅人豐年祭食物，每個位子前面各有一樣。$B$B當你坐在其中一個位子時，那種食物你愛吃多少吃多少，你也可以把食物傳遞給其他的位子。儘量吃並且和朋友分享!$B$B如果你其中一種食物吃得夠多，你將可以獲得該食物的一種獨特增益效果。$B$B此外，如果你每一種食物都吃得夠多，你將可以獲得有福同享的效果!', '豐年祭餐席放著五種旅人豐年祭食物，每個位子前面各有一樣。\n\n當你坐在其中一個位子時，那種食物你愛吃多少吃多少，你也可以把食物傳遞給其他的位子。儘量吃並且和朋友分享!\n\n如果你其中一種食物吃得夠多，你將可以獲得該食物的一種獨特增益效果。\n\n此外，如果你每一種食物都吃得夠多，你將可以獲得有福同享的效果!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14648 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14648, 'zhTW', '豐年祭餐席放著五種旅人豐年祭食物，每個位子前面各有一樣。$B$B當你坐在其中一個位子時，那種食物你愛吃多少吃多少，你也可以把食物傳遞給其他的位子。儘量吃並且和朋友分享!$B$B如果你其中一種食物吃得夠多，你將可以獲得該食物的一種獨特增益效果。$B$B此外，如果你每一種食物都吃得夠多，你將可以獲得有福同享的效果!', '豐年祭餐席放著五種旅人豐年祭食物，每個位子前面各有一樣。$B$B當你坐在其中一個位子時，那種食物你愛吃多少吃多少，你也可以把食物傳遞給其他的位子。儘量吃並且和朋友分享!$B$B如果你其中一種食物吃得夠多，你將可以獲得該食物的一種獨特增益效果。$B$B此外，如果你每一種食物都吃得夠多，你將可以獲得有福同享的效果!', '豐年祭餐席放著五種旅人豐年祭食物，每個位子前面各有一樣。\n\n當你坐在其中一個位子時，那種食物你愛吃多少吃多少，你也可以把食物傳遞給其他的位子。儘量吃並且和朋友分享!\n\n如果你其中一種食物吃得夠多，你將可以獲得該食物的一種獨特增益效果。\n\n此外，如果你每一種食物都吃得夠多，你將可以獲得有福同享的效果!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14649 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14649, 'zhTW', '<你眼前的食人妖從頭到腳佈滿了傷口和疤痕，臉上一道新的割痕使他的嘴唇都變形了。>$B$B呦!$B$B你知道，食人妖騎的是迅猛龍，而最大的問題是把野生的迅猛龍抓來訓練!這就是我的工作。我是個迅猛龍陷補者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14652 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14652, 'zhTW', '小心這些迅猛龍，有些非常非常的聰明。$B$B上週我被兩隻打了一頓，第三隻還拿棒子打我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14657 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14657, 'zhTW', NULL, '$n$G先生:小姐;，很高興見到你。$B$B希望你喜歡卡迦可樂的行銷活動。我們在活動的下個階段打算使用華麗的大爆炸。這對我們的目標客群來說一直都非常有用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14658 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14658, 'zhTW', '你可以在靈魂高地西緣的飛艇停靠處找到克倫德·大袋。我不喜歡那些哥布林的新玩意兒飛過這裡...但如果你受得了的話，它可以帶你去奧格瑪。', '你可以在靈魂高地西緣的飛艇停靠處找到克倫德·大袋。我不喜歡那些哥布林的新玩意兒飛過這裡...但如果你受得了的話，它可以帶你去奧格瑪。', '你可以在靈魂高地西緣的飛艇停靠處找到克倫德·大袋。我不喜歡那些哥布林的新玩意兒飛過這裡…但如果你受得了的話，它可以帶你去奧格瑪。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14659 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14659, 'zhTW', '真正的十字軍不單只是在戰場上對抗邪惡的英雄...他是一個楷模，能使眾人團結，所有人民眼中的勇士。$B$B作為一位高階十字軍，我的職責就是以適當的任務來考驗這些男女。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14661 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14661, 'zhTW', '某些獎勵只適用於那些取得十字軍頭銜，在銀白十字軍以及他們盟友中獲得崇拜聲望的人。$B$B提里奧本人親自任命我找尋這些的英雄，並給予他們適當的勳章。', '某些獎勵只適用於那些取得十字軍頭銜，在銀白十字軍以及他們盟友中獲得崇拜聲望的人。$B$B提里奧本人親自任命我找尋這些的英雄，並給予他們適當的勳章。', '某些獎勵只適用於那些取得十字軍頭銜，在銀白十字軍以及他們盟友中獲得崇拜聲望的人。\n\n提里奧本人親自任命我找尋這些的英雄，並給予他們適當的勳章。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14664 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14664, 'zhTW', '歡迎，勇士!你召集好隊伍，準備要迎接銀白十字軍的挑戰了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14665 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14665, 'zhTW', '你們準備好迎接第一場挑戰了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14667 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14667, 'zhTW', '那些野獸是驚人的對手。你不需要因為被他們擊敗而感到羞愧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14668 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14668, 'zhTW', '太棒啦!等你準備好再來一次的時候告訴我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14669 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14669, 'zhTW', '你的等級還不足以參加征服之島的戰鬥。等你獲得更多經驗的時候再回來。', '你的等級還不足以參加征服之島的戰鬥。等你獲得更多經驗的時候再回來。', '你的等級還不足以參加征服之島的戰鬥。等你獲得更多經驗的時候再回來。.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14670 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14670, 'zhTW', '征服之島充滿了珍貴的資源，我們絕不能讓它落入部落之手。你願意加入戰鬥嗎?', '征服之島充滿了珍貴的資源，我們絕不能讓它落入部落之手。你願意加入戰鬥嗎?', '征服之島充滿了珍貴的資源，我們絕不能讓它落入部落之手。你願意加入戰鬥嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14671 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14671, 'zhTW', '征服之島充滿了珍貴的資源，我們絕不能讓它落入聯盟之手。你願意加入戰鬥嗎?', '征服之島充滿了珍貴的資源，我們絕不能讓它落入聯盟之手。你願意加入戰鬥嗎?', '征服之島充滿了珍貴的資源，我們絕不能讓它落入聯盟之手。你願意加入戰鬥嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14672 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14672, 'zhTW', '我們希望每個人在啤酒節都玩得開心。這也能幫助我們大家記住這個節日。$B$B這些眼鏡讓任何人都能體驗酒醉的感覺，但什麼也不需要喝。只要戴上眼鏡，你就跟喝醉了一樣!拿下來，你又清醒啦!$B$B你有興趣來一副嗎?', '我們希望每個人在啤酒節都玩得開心。這也能幫助我們大家記住這個節日。$B$B這些眼鏡讓任何人都能體驗酒醉的感覺，但什麼也不需要喝。只要戴上眼鏡，你就跟喝醉了一樣!拿下來，你又清醒啦!$B$B你有興趣來一副嗎?', '我們希望每個人在啤酒節都玩得開心。這也能幫助我們大家記住這個節日。\n\n這些眼鏡讓任何人都能體驗酒醉的感覺，但什麼也不需要喝。只要戴上眼鏡，你就跟喝醉了一樣!拿下來，你又清醒啦!\n\n你有興趣來一副嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14673 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14673, 'zhTW', '對不起，你當前的等級或者經驗未達到進入戰場的要求。 $c. 你的等級或者經驗達到要求再進入戰場吧.', '對不起，你當前的等級或者經驗未達到進入戰場的要求。 $c. 你的等級或者經驗達到要求再進入戰場吧.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14674 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14674, 'zhTW', '你準備好要為了部落而戰嗎，$c?', '你準備好要為了部落而戰嗎，$c?', '你準備好為部落而戰嗎, $c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14675 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14675, 'zhTW', '你準備好要為了聯盟而戰嗎，$c?', '你準備好要為了聯盟而戰嗎，$c?', '你準備好要為了聯盟而戰嗎，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14678 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14678, 'zhTW', '幹得好!你和那些野獸的戰鬥非常精彩!我聽說下一場挑戰將會更困難!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14679 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14679, 'zhTW', '我們現在勉強擋住賈拉克瑟斯領主，但我們撐不了太久。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14680 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14680, 'zhTW', '你們很快就會知道了。準備好接受下一場挑戰了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14681 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14681, 'zhTW', NULL, '嗨，寶貝!我看起來如何?', NULL, 'I missed you so much! Where have you been?$B$BAre you going to answer me, or just stand there?', NULL, 'Do you like my outfit?  It\'s for the party. I charged it to your account.', NULL, 'There was another guy just hitting on me. Oh, the nerve!$B$BWill you beat him up for me, sweetie? Thanks. Love ya!', NULL, 'I can\'t wait for the day when you rise to the top. Just think, I\'ll be able to call myself Mrs. Trade Prince$B$BNot to mention buy all that stuff I\'ve always wanted!!!', NULL, 'Be careful out there. I heard that there are Southsea pirates in the bay.$B$BHmm, maybe I should go check for myself...', NULL, 'Can we go on a nice, romantic picnic on top of Mount Kajaro?$B$BMake sure you pickup my favorite champagne!', NULL, 'You\'ve got a miscievious look in your eye. What have you been up to, babe?$B$BWell?');
DELETE FROM `npc_text_locale` WHERE `ID` = 14682 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14682, 'zhTW', '太好了，等要撤掉束縛法術的時候，給我個訊號就行了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14683 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14683, 'zhTW', '你太漂亮了!你相信我所說的，對吧，寶貝?', NULL, 'Sweetie, where have you been? You know how worried I get when you don\'t check in with me!', NULL, 'What do you think of my abs, baby? I just got back from the gym.$B$BI am one fine piece of meat!', NULL, 'Those other women are just friends, baby.', NULL, 'I like what you\'re wearing!', NULL, 'I know that I promised you last night, and the night before that, but I\'m taking you out someplace really nice tomorrow night!', NULL, 'I heard that some Southsea pirates pulled into dock earlier. Be careful if you go into town!$B$BThey even have women pirates! Hmm, maybe I should go check it out myself? Just to make sure it\'s safe for you out there, baby.', NULL, 'How\'s my hot, company executive girlfriend today? With the way you run things around here, I think that any day now we\'ll be calling you Trade Princess $N!$B$BI cannot wait! I\'m gonna spend my days at the gym and working on my tan by the pool.', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14684 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14684, 'zhTW', '嗨，老大。這群食人妖奴隸真是有史以來最不聽話的!$B$B還好，卡迦邁礦好像沒有讓他們的笨腦袋變聰明，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14688 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14688, 'zhTW', '準備好進行第一次挑戰了嗎，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14689 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14689, 'zhTW', '你來學騎術?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14690 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14690, 'zhTW', '多年來我一直窩在這個偏僻的角落，投注所有的心力，熟悉此處的地形結構。現在我們的機會來了，奧格瑪已開始正視艾薩拉這塊地方，這裡已成了我們進攻梣谷以及佔領這塊大陸的門戶要地。歡迎來到前線，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14692 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14692, 'zhTW', '<角鷹獸看起來相當期待，並且整裝待發!>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14693 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14693, 'zhTW', NULL, '嗯?你要什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14694 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14694, 'zhTW', '快滾，老兄，不然就賞你吃一記老奇普·恩戴爾拳!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14695 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14695, 'zhTW', '歡迎來到凱贊第一銀行，這是由汙水貿易&南海商業銀行所獨資開設的子公司。$B$B我能為你做些什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14697 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14697, 'zhTW', '喂!你看起來像是一個品味與眾不同的$g男人:女人;。$B$B我可以為你做些什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14698 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14698, 'zhTW', '那個閃亮的玩意兒跟你媽一樣肥!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14700 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14700, 'zhTW', '看我必須跟什麼一起工作。薩波可以製造奇蹟?$B$B<薩波嘆了氣>$B$B是的，是的。薩波認為他可以跟你一起工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14702 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14702, 'zhTW', '噢，你看薩波做了什麼。一個傑作!$B$B你沒有資格穿上它，但薩波需要錢。<嘆氣>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14703 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14703, 'zhTW', NULL, '我這什麼牌子的墨鏡都有。你叫的出來，我就拿的出來!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14705 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14705, 'zhTW', NULL, '你看，這是我最上等的，便宜賣給你!$B$B你戴上後看起來一定很屌!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14712 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14712, 'zhTW', '歡迎來到我們的店。我們有所有你需要的東西...如果你需要鏈金材料的話。', '歡迎來到我們的店。我們有所有你需要的東西...如果你需要鏈金材料的話。', '歡迎啊.朋友~我的店裡貨物都是最好的~請慢慢看~', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14713 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14713, 'zhTW', '不，我可是個聰明人，我不會這麼輕易就被說動。我可以用洗碗水和蒲公英做出治療藥水，不過那可不是我要讓你見識的東西!$B$B總之，如果你想買東西，請洽派翠西亞。', '不，我可是個聰明人，我不會這麼輕易就被說動。我可以用洗碗水和蒲公英做出治療藥水，不過那可不是我要讓你見識的東西!$B$B總之，如果你想買東西，請洽派翠西亞。', '不，我可是個聰明人，我不會這麼輕易就被說動。我可以用洗碗水和蒲公英做出治療藥水，不過那可不是我要讓你見識的東西!\n\n總之，如果你想買東西，請洽派翠西亞。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14723 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14723, 'zhTW', '元素之靈的智慧超乎你我的想像。他們比我們更早就存於世上，並且將會存於我輩之後。當他們與我們溝通時，我們必須懂得聆聽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14724 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14724, 'zhTW', '元素之靈無所不在。我們必須懂得聆聽。我曾經親眼目賭人們無視他們的警告所帶來的後果……', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14729 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14729, 'zhTW', '滾吧，蟲子。你不屬於這片大地。不要激怒我。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14731 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14731, 'zhTW', '再次謝謝你幫忙處理這些懶惰的蠢貨，$g老大:大姐;。$B$B如果你問我，我會說我們不應該在獲得自由，不再是他們的奴隸後還對那些食人妖那麼的仁慈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14735 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14735, 'zhTW', '是的，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14736 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14736, 'zhTW', '有些人希望他們的行為將不會為其帶來經驗值;始終維持當前等級的力量，並且不再獲得成長。$B$B我能幫你這麼做...當然，你得花點錢。$B$B但是你要注意:一旦付了錢，『你就不再獲得任何經驗值了』。一點經驗值也得不到。$B$B要是你事後改變主意，並且想再度獲得經驗值的話，我可以用相同的費用幫你恢復正常。', '有些人希望他們的行為將不會為其帶來經驗值;始終維持當前等級的力量，並且不再獲得成長。$B$B我能幫你這麼做...當然，你得花點錢。$B$B但是你要注意:一旦付了錢，『你就不再獲得任何經驗值了』。一點經驗值也得不到。$B$B要是你事後改變主意，並且想再度獲得經驗值的話，我可以用相同的費用幫你恢復正常。', '有些人希望他們的行為將不會為其帶來經驗值;始終維持當前等級的力量，並且不再獲得成長。\n\n我能幫你這麼做…當然，你得花點錢。\n\n但是你要注意:一旦付了錢，『你就不再獲得任何經驗值了』。一點經驗值也得不到。\n\n要是你事後改變主意，並且想再度獲得經驗值的話，我可以用相同的費用幫你恢復正常。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14737 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14737, 'zhTW', '剛才的表現真精采。但是你準備好要接受下一個挑戰了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14738 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14738, 'zhTW', '你今天在競技場所展現的卓越技巧令眾人印象深刻。現在你該在眾人的面前獲得聯賽勇士的表揚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14739 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14739, 'zhTW', '這個古蹟不斷地發出遠古的能量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14740 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14740, 'zhTW', '你看到的是世界上最棒，等級最高的礦場運作方式。只有鄉巴佬才會花力氣去挖山洞來採集地下的礦石。我們移動了整座山!現在我們只要直接把地下寶貴的礦物給挖出來就好了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14742 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14742, 'zhTW', NULL, '我們終於有機會調查散佈在這的廢墟了...如果這些吸血鬼不離開這的話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14744 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14744, 'zhTW', NULL, '你對先祖之戰了解嗎，$n?那是我們對一萬年前的世代的稱呼，那個燃燒軍團無數的惡魔們入侵了艾澤拉斯，想要吞噬整個世界的時代。古老的首都艾薩拉，曾經昂首立於大地的城市，在那次的侵略中被夷為平地。那些四散於附近的古老殘骸便是我們那些自大祖先曾經存在的可悲證據。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14745 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14745, 'zhTW', NULL, '我現在擔心的是我們東邊圍繞著門納爾湖的廢墟。幾千年前，門納爾學院是最早研究秘法系別魔法的學院。它曾是一個花園式的建築，環繞著平靜的湖面，一個可以潛心進行研究的地方。就在那，我的祖先發現了永恆之井所蘊藏著的魔法能量。$B$B抱歉，訊息太多一下子無法接受嗎?我已經幾世紀都沉浸在秘法的歷史研究中，忘了其他人不會像我一樣那麼的狂熱。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14746 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14746, 'zhTW', NULL, '足夠的證據顯示學院對這些新發現的能量非常小心。少數的報告仍舊指出法師們對沉溺於秘法能量感到憂心，這也是我們一族到現在都還會碰到的問題。$B$B這個限制使門納爾的法師們與艾薩拉女王和她的精靈貴族走狗成為了對立的形勢，艾薩拉女王擁有對力量無止境的渴望，瘋狂地放縱這方面的研究，疏忽了運用魔法所帶來的危險副作用而越陷越深。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14747 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14747, 'zhTW', NULL, '當燃燒軍團開始進行侵略時，門納爾學院的法師們與女王已經形同陌路。他們在戰爭中本來會是非常強大的戰力，但他們在城市淪陷時並沒有撤退。$B$B他們並沒有在城市外聚集加入反擊戰，而是待在本來的地方，架起了一道魔法屏障將他們曾經安寧的家鄉變成了一座堡壘。難民在侵略開始的前幾天湧進了門納學院，生還者聚集了起來形成一道堅固的防護網。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14748 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14748, 'zhTW', NULL, '不要屈服?在軍團先鋒部隊的全面進攻之下?不太可能!$B$B不，歷史並沒有記錄接下來會發生的事...因為完全沒有任何的生還者。狂暴的惡魔們給我們留下的就是你今天看到的這些廢墟，學院的秘密也被埋藏在艾薩拉的泥土之下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14749 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14749, 'zhTW', NULL, '我喜歡你的思考方式，$r!$B$B就在最近，學院廢墟潛在的魔法能量吸引了藍龍軍團的注意，但我卻無法進行調查。現在，龍族已經將注意力轉移到其他的地方了，但更大的問題卻威脅著我─這些野蠻的綠色小生物想將廢墟剷平興建燃料站!已經失去了千年的知識就要在幾天內永遠的從這世界上消失了。我們必須快點行動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14751 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14751, 'zhTW', '峭壁之上，強風依舊呼嘯而過，多年來寒冰皇冠仍是生靈避之唯恐不及之處。然而只要不輕言放棄，我們仍可奪回此地，這也是我來到這裡的原因。終有一天，此地將會百樹林立，守護著我們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14752 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14752, 'zhTW', NULL, '加姆讓我幫他們經營這間店!我愛死鮮花了。$B$B<小艾德琳眯起了雙眼看著你，露出一派正經的表情。>$B$B你也喜歡鮮花嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14757 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14757, 'zhTW', '第一場挑戰賽需要你騎上銀白戰馬。你可以在大競技場的牆邊找到那些坐騎。$B$B請騎上那些戰馬，然後請告訴我，讓我們可以繼續下去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14759 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14759, 'zhTW', '猛瑪象人沒有一般人想像中的蠢。在戈莫克上場前禁錮牠是件困難的工作，但我們把他牢牢地綁住了，不會有安全上的顧忌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14760 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14760, 'zhTW', '由於戈莫克只會濫殺無辜，因此我把他囚禁起來。我不十分贊同這種屠殺的行為，但至少他仍有一拚的機會。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14761 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14761, 'zhTW', '雪人是兇猛，狡詐的生物，而這一隻又是個中的翹楚。我們在他的飲食中加入了安眠的草藥。$B$B不過別妄想他在競技場中也會昏昏欲睡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14762 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14762, 'zhTW', '我...我的礦場失去控制了!$g先生:女士;，不要開除我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14764 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14764, 'zhTW', '你好啊，$N。如果你想要我當你的拍賣師，我只能遺憾地跟你說:不。只有宗師級的工程師才擁有能啟動我的特殊功能所需的最低專業智慧。$B$B更重要的是，為什麼你還在跟我說話呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14766 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14766, 'zhTW', '凱麗莎，你還活著!找個地方躲起來，那些東西源源不絕地冒出來!', NULL, 'Am I still bleeding? I can\'t ... I can\'t keep this up much longer. Have you seen any of the archmages?', NULL, 'Hmph. I suppose these are the consequences of magic. You reap what you sew ... Elune help us all.', NULL, 'Kalytha! Archmage Selwyn was looking for you. She should be nearby...', NULL, 'These creatures ... so many of them. So many dead! Look at Azshara burn. What have the highborne done?', NULL, 'Why didn\'t I flee with the others? They\'ve got the academy surrounded. We\'re trapped here.', NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14767 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14767, 'zhTW', NULL, '我必須保持秘法結界內的能量。', NULL, 'My strength ... is beginning ... to falter. Kalytha, please tell me the Archmages have a backup plan...', NULL, 'I can\'t maintain this shield much longer. Kalytha - are any of us going to survive this?', NULL, 'More of these creatures! Where are they coming from? What\'s going on in the capital?', NULL, 'Kalytha! Hurry - Archmage Selwyn wanted to see you, she said it was urgent. Maybe we can win this thing?', NULL, 'It\'s all I can do to keep these wards up. Find one of the Archmages, Kalytha! I feel like I\'m about to collapse...', NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14768 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14768, 'zhTW', NULL, '凱麗莎...完成了。薩森石已經充能完畢和開始引導傳送門的能量。你還是我多年前所認識的那個游泳好手嗎?石頭不能被惡魔或我們「親愛的」女王發現。$B$B游到湖底最深的地方，凱麗莎，然後將石頭埋在中央拱形處最深的地方。我們祈禱那些惡魔入境者在摧毀附近的神殿時不會發現它。快去!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14770 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14770, 'zhTW', NULL, '<閃亮的視線並未發現你的存在。她迷失在自己的世界中，對千年前所發生的事件做出反應。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14771 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14771, 'zhTW', '當決戰的時刻來臨時，我將會加入冰冠城塞的突襲行動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14775 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14775, 'zhTW', '你好，$c。$B$B部落目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。$B$B下一場戰鬥將在$4354k後開始。', '你好，$c。$B$B部落目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。$B$B下一場戰鬥將在$4354k後開始。', '你好，$c。\n\n部落目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。\n\n下一場戰鬥將在$4354k後開始。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14777 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14777, 'zhTW', '你好，$c。$B$B部落目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', '你好，$c。$B$B部落目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', '你好，$c。\n\n部落目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14779 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14779, 'zhTW', '我們一直在照料這些大蟲。我希望他們來得及參與競技場的盛會。畢竟，你得面對的不只是一隻，而是兩隻蟄猛巨蟲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14781 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14781, 'zhTW', '你好，$c。$B$B聯盟目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', '你好，$c。$B$B聯盟目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', '你好，$c。\n\n聯盟目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14782 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14782, 'zhTW', '你好，$c。$B$B聯盟目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。$B$B下一場戰鬥將在$4354k後開始。', '你好，$c。$B$B聯盟目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。$B$B下一場戰鬥將在$4354k後開始。', '你好，$c。\n\n聯盟目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。\n\n下一場戰鬥將在$4354k後開始。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
