INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15428, 'zhTW', NULL, '我很高興你問了，$n!$B$B從來沒有人提出過這種問題，大家早就習以為常，反正東西有得用就好了。把那給我，我要炸爛一些東西。或者是:別跟我講那麼多有的沒的，讓我瞄準後發射就好了。誰會管那麼多細節，這次的爆炸比上次還來得大嗎?$B$B我發誓，有的時候我真的好想大聲尖叫，你知道嗎?荷巴爾特所有的事情幾乎都是我在做的，可是我從來沒有獲得什麼獎勵!我一定是有史以來最不受重視，加班時間最長和拿的錢最少的工匠助手了!$B$B啊，你想問什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15431 AND `Locale` = 'zhTW';
