INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16470, 'zhTW', '今天該把帳算清了，$c!', NULL, 'Have you come to help overthrow Mor\'ghor?', NULL, 'Zaela told us the Horde would help! What can I do?', NULL, 'Don\'t give me any armor. Just gimmie a blade and tell me who to kill.', NULL, 'The Horde has come! It\'s about time we got some real leadership around here.', NULL, 'I\'ll fight by your side, $c. You won\'t regret helping us!', NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16471 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16471, 'zhTW', 'Looks like I picked the wrong day to stop killin\' fel orcs.', '看來我選錯了停止殺魔獄獸人的日子了。', 'It\'s a day of reckoning, $c!', 'It\'s a day of reckoning, $c!', 'Put me in, coach! I\'m ready to fight!', 'Put me in, coach! I\'m ready to fight!', 'Today Mor\'ghor\'s tyranny will end.', 'Today Mor\'ghor\'s tyranny will end.', 'This is it, $c! The revolution has come.', 'This is it, $c! The revolution has come.', '$c! Zaela said the Horde would provide us with weapons. What do you have?', '$c! Zaela said the Horde would provide us with weapons. What do you have?', NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16472 AND `Locale` = 'zhTW';
